def test_tier3_reconstructs_call_arguments():
    # benchRunAll invokes the bench functions; Tier 3 must reconstruct each call's argument
    # list from the callee's register arity (x1..xk live-in), and fall back to `...` for the
    # stack calling convention (ArgumentsDescriptor set). Ground-truth arities:
    #   benchWithdraw(this, amount)=2, benchCheckSecret(input)=1, benchComputeChecksum(d)=1,
    #   benchFirstOrDefault(...)=stack (0 register args).
    if not _capstone_available():
        _skip("  SKIP test_tier3_reconstructs_call_arguments (no capstone)")
    from jadart.disasm import (load_instructions, disassemble_function,
                               function_name_by_pc, build_pool_map)
    from jadart.expr import lift_function, make_arity_resolver, entry_arity
    image, fr, _ = load_instructions(CLEAN)
    pc_to_name = function_name_by_pc(image, fr)
    pool_map = build_pool_map(fr)

    def arity_of(name):
        rf = [r for r, nr, ow, kt in fr.functions if fr.strings.get(nr) == name][0]
        dis = disassemble_function(image, rf)
        return entry_arity([(a, m, o, "") for a, m, o in dis])

    assert arity_of("benchWithdraw") == 2          # this + amount
    assert arity_of("benchCheckSecret") == 1       # input
    assert arity_of("benchComputeChecksum") == 1   # data
    assert arity_of("benchFirstOrDefault") is None  # stack convention -> unknown register arity

    refs = [r for r, nr, ow, kt in fr.functions if fr.strings.get(nr) == "benchRunAll"]
    ann = _ann(image, disassemble_function(image, refs[0]), pc_to_name, pool_map)
    body = "\n".join(lift_function(ann, pool_map, arity=make_arity_resolver(image)))
    import re
    assert "benchCheckSecret(x1)" in body                  # one register arg reconstructed
    # The stack convention is READ, not declined. Ground truth, constructs.dart:88:
    #     b.writeln(benchFirstOrDefault<int>(seed.codeUnits, -1));
    # Three values are pushed, because a generic function takes its type arguments as a
    # hidden first argument, so the reconstruction is (type args, items, fallback), and
    # the fallback is the `-1` in the source. `entry_arity` still declines for this callee
    # and must keep declining: it takes nothing in registers, which is WHY the values are
    # on the stack for the caller to have pushed.
    assert arity_of("benchFirstOrDefault") is None
    m = re.search(r"benchFirstOrDefault\(([^)]*)\)", body)
    assert m, body
    got = [a.strip() for a in m.group(1).split(",")]
    assert len(got) == 3, got
    assert got[0].startswith("pool_"), got                 # the <int> type-arguments vector
    assert got[2] == "-1", got                             # the fallback, straight from source
    # and `items` is the codeUnits view allocated two lines earlier, named at its definition
    assert re.search(rf"^\s*var {re.escape(got[1])} = \w", body, re.M), body
    # The one argument benchComputeChecksum takes is the list an earlier call built. That
    # value arrives in x0 and used to be printed as the bare register, which says nothing
    # about where it came from; it is named at the call that produced it, so the argument
    # names it and the definition is right there in the body.
    m = re.search(r"benchComputeChecksum\((t\d+)\)", body)
    assert m, body
    assert re.search(rf"^\s*var {m.group(1)} = \w", body, re.M), body
    # a 2-arg call renders two comma-separated arguments
    m = re.search(r"benchWithdraw\(([^)]*)\)", body)
    assert m and m.group(1).count(",") == 1, "benchWithdraw should show 2 reconstructed args"


def test_argument_reconstruction_does_not_depend_on_the_callee_having_a_name():
    # A missing NAME was treated as a missing signature. The two have nothing to do with
    # each other: the arity is read out of the callee's own entry code at the target
    # address. 13,923 direct call sites on the corpus binary fell back to `...` for no
    # reason beyond the callee having no recovered name, which is the whole of an
    # --obfuscate build, exactly where the argument list is the only thing left to read.
    if not _capstone_available():
        _skip("  SKIP test_argument_reconstruction_does_not_depend_on_the_callee_having_a_name")
    import re
    from jadart.disasm import (load_instructions, disassemble_range, build_pool_map,
                               function_name_by_pc)
    from jadart.expr import lift_function, make_arity_resolver

    for lib in (CLEAN, OBF):
        image, fr, _ = load_instructions(lib)
        pc_to_name, pool_map = function_name_by_pc(image, fr), build_pool_map(fr)
        arity = make_arity_resolver(image)
        named = anon = 0
        for cr in list(image.all_ranges)[:1500]:
            dis = disassemble_range(image, cr)
            if not dis:
                continue
            for ln in lift_function(_ann(image, dis, pc_to_name, pool_map), pool_map,
                                    arity=arity):
                for m in re.finditer(r"\bsub_0x[0-9a-f]+\(([^)]*)\)", ln):
                    anon += 1
                    named += m.group(1) != "..."
        assert anon > 50, f"{lib}: too few unnamed call sites to prove anything"
        assert named > anon // 10, (
            f"{lib}: {named} of {anon} unnamed call sites got an argument list")


def test_a_call_result_is_named_when_something_reads_it():
    # `bl f` leaves its result in x0. The lifter recorded that by putting the bare string
    # "x0" in the register map, so every later use printed a machine register and nothing
    # in the output connected the value being returned to the call that produced it.
    import re
    body = _lift_asm([("bl", "#0x40"), ("ldur", "x1, [x0, #7]"), ("ldur", "x2, [x0, #0xf]"),
                      ("add", "x0, x1, x2"), ("ret", "")])
    assert "x0" not in body, body
    m = re.search(r"var (t\d+) = sub_0x40\(\.\.\.\);", body)
    assert m, body
    assert f"return {m.group(1)}.field_0x8 + {m.group(1)}.field_0x10;" in body, body
    # One reader on the very next line needs no name at all: the value crosses no
    # statement, so folding it there reorders nothing and duplicates nothing.
    body = _lift_asm([("bl", "#0x40"), ("ret", "")])
    assert body.strip() == "return sub_0x40(...);", body
    # A result nothing reads does not grow a variable nobody uses.
    body = _lift_asm([("bl", "#0x40"), ("mov", "x0, #1"), ("ret", "")])
    assert "var " not in body and "sub_0x40(...);" in body, body


def test_a_join_keeps_what_the_two_arms_computed():
    # _merge keeps what both arms agree on and drops the rest, so a register each arm
    # computed differently left the join as a bare name with nothing anywhere saying what
    # either arm had put in it, and when both arms lifted to nothing else, the renderer
    # dropped the whole `if` as vacuous and the BRANCH went with it. A real case:
    # `scoreKey`'s `% 101` correction compiles to sdiv/msub then `if (r < 0) r += 101`,
    # and the entire correction was missing from the output.
    #
    # Pinned by BEHAVIOUR, not by spelling: the join value now gets a name rather than
    # being written back to the machine register, so what has to hold is that both arms'
    # arithmetic is in the output and that what the `return` names is the thing they wrote.
    # Asserting on `x0` would pin the old rendering, which was the defect being described
    # in the second half of the docstring above, a reader cannot tell that `x0` from one
    # the lifter lost.
    import re as _re
    body = _lift_asm([("cmp", "x1, x2"), ("b.lt", "#0x10"), ("add", "x0, x1, x2"),
                      ("b", "#0x14"), ("sub", "x0, x1, x2"), ("ret", "")])
    m = _re.search(r"return (\S+);", body)
    assert m, body
    ret = m.group(1)
    assert f"{ret} = x1 + x2;" in body and f"{ret} = x1 - x2;" in body, body
    # A register the arms merely move around is left alone: it costs a statement and says
    # nothing the reader could not already see.
    body = _lift_asm([("cmp", "x1, x2"), ("b.lt", "#0x10"), ("mov", "x0, x1"),
                      ("b", "#0x14"), ("mov", "x0, x2"), ("ret", "")])
    assert "= x1;" not in body and "= x2;" not in body, body


def test_an_overwritten_receiver_does_not_read_back_as_this():
    # _merge dropped a register the two arms disagreed about by OMITTING it, and an
    # omitted register falls back to the receiver alias. So an instance method whose
    # then-arm overwrote x1 printed `this.field_0x8` afterwards, on a path where x1 is
    # provably not this. A disagreement is a fact about the register and the map has to
    # hold it, not leave a gap for something else to fill.
    from jadart.expr import lift_function
    rows = [("cbz", "x2, #0xc"), ("mov", "x1, #5"), ("b", "#0x10"),
            ("mov", "x3, #1"), ("ldur", "x0, [x1, #7]"), ("ret", "")]
    body = "\n".join(lift_function([(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)],
                                   receiver={"x1": "this"}))
    assert "this.field_0x8" not in body, body
    assert "x1.field_0x8" in body, body


def test_a_call_does_not_leave_the_values_it_destroyed_behind_it():
    # `_CALL_CLOBBERS` says what a call takes with it, kDartVolatileCpuRegs, R0-R14 plus
    # every V register but VTMP, and liveness has read it that way for a while. The VALUE
    # map did not: a call reset x0 and nothing else, so anything the state knew about
    # x1-x14 or d0-d30 walked through the call that destroyed it and was printed on the
    # far side as though it had survived. A wrong value, not a missing one.
    from jadart.expr import lift_function

    # an integer register: 5 cannot still be in x9 once the callee has run.
    body = _lift_asm([("mov", "x9, #5"), ("bl", "#0x40"), ("mov", "x0, x9"), ("ret", "")])
    assert "return 5;" not in body, body
    # Not `x9` either: the call DEFINES what it clobbered, so what it left in x9 has a
    # name of its own rather than the register's, which read as the entry x9 (#176).
    assert re.search(r"return t\d+;", body), body

    # a float register, which had no invalidation at all: `_result` only ever names the
    # INTEGER return register, so d0 kept its pre-call value across every call.
    body = _lift_asm([("fmov", "d0, #1.0"), ("bl", "#0x40"), ("fmov", "d1, d0"),
                      ("ret", "")])
    assert "1.0" not in body.split("bl", 1)[-1].split("sub_0x40", 1)[-1], body

    # the receiver alias, which is the worse spelling: a register the state does NOT
    # describe falls back through `_leaf` to `this`, so x1 after a call printed the
    # receiver on a path where x1 is whatever the callee left there.
    body = "\n".join(lift_function(
        [(i * 4, mn, op, "") for i, (mn, op) in enumerate(
            [("bl", "#0x40"), ("ldur", "x2, [x1, #7]"), ("ret", "")])],
        receiver={"x1": "this"}))
    assert "this.field_0x8" not in body, body

    # ...and a register the call does NOT clobber still says what it held. x19 is
    # kAbiPreservedCpuRegs, so dropping it would be honesty bought at the price of
    # everything the reader came for.
    body = _lift_asm([("mov", "x19, #5"), ("bl", "#0x40"), ("mov", "x0, x19"), ("ret", "")])
    assert "return 5;" in body, body

    # Arguments are read before the clobber, not after. They live in exactly the registers
    # the call is about to destroy, so the wrong order prints a bare register for every
    # argument of every call in the image.
    rows = [("mov", "x1, #7"), ("mov", "x2, #8"), ("bl", "#0x40"), ("ret", "")]
    body = "\n".join(lift_function(
        [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)],
        arity=lambda _pc: 2))
    assert "sub_0x40(7, 8)" in body, body


def test_a_concurrent_modification_guard_is_not_rendered_as_a_tautology():
    # The real defect the clobber fix was found by. dart:collection's
    # _CompactLinkedHashBase.forEach re-reads `_data` after calling the user's callback and
    # compares it against the copy it took before, which is how a map mutated during
    # iteration is caught. The saved copy sits in a frame slot and survives; the register
    # holding the receiver does not. With the post-call registers still describing their
    # pre-call values both sides rendered as `this.field_0x10`, so the guard read as a
    # comparison that can never fail and the throw behind it as dead code.
    if not _capstone_available():
        _skip("  SKIP test_a_concurrent_modification_guard_is_not_rendered_as_a_tautology")
    from jadart.disasm import (load_instructions, disassemble_range, build_pool_map,
                               function_name_by_pc)
    from jadart.expr import lift_function, make_arity_resolver
    image, fr, _hdr = load_instructions(CLEAN)
    p2n = function_name_by_pc(image, fr)
    pm, ar = build_pool_map(fr), make_arity_resolver(image)
    checked = 0
    for cr in image.all_ranges:
        if p2n.get(cr.pc_offset) != "forEach":
            continue
        dis = disassemble_range(image, cr)
        if not dis:
            continue
        body = "\n".join(lift_function(_ann(image, dis, p2n, pm), pm,
                                       receiver={"x1": "this"}, arity=ar))
        checked += 1
        # Shape, not spelling: no comparison anywhere may have the same text on both
        # sides. A guard that compares a value to itself is either the Smi box idiom
        # (stripped elsewhere) or a value the lifter lost track of.
        for a, b in re.findall(r"\(([^()]+) [=!]= ([^()]+)\)", body):
            assert a != b, f"self-comparison {a!r} in forEach:\n{body}"
    assert checked >= 2, f"expected the compact-hash forEach bodies, saw {checked}"


def _then_forget(rows):
    """`rows`, then a loop that calls and stores over half of [x29, #-0x10], after which
    the walk forgets that slot, then a reload of it to return. A name given to a spill
    in `rows` is then read only by what `rows` print. The reload is from the register
    file the slot was stored from, as one from the other is no reload of it (#165)."""
    h = len(rows) + 1
    r = "d0" if any(op[:1] == "d" for _m, op in rows if "[x29, #-0x10]" in op) else "x0"
    return rows + [("mov", "x6, #0"), ("bl", "#0x100"), ("stur", "x6, [x29, #-0xc]"),
                   ("add", "x6, x6, #1"), ("cmp", "x6, #3"), ("b.lt", f"#{h * 4:#x}"),
                   ("ldur", f"{r}, [x29, #-0x10]"), ("ret", "")]


#: Spills the very next statement reads, and how that statement has to read once the
#: name folds back into it (#64). The precedence table has no `/` or `>>>` to ask, and
#: a sign folded in after a sign would read as a decrement, `--x20.field_0x8`.
_FOLDS = [
    ([("ldur", "w4, [x20, #0xb]"), ("add", "x4, x4, #1"), ("stur", "x4, [x29, #-0x10]"),
      ("mul", "x5, x4, x6"), ("str", "x5, [x23, #7]")],
     "x23.field_0x8 = (x20.field_0xc + 1) * x6;"),
    ([("ldur", "d0, [x20, #7]"), ("ldur", "d1, [x20, #0xf]"), ("fdiv", "d2, d0, d1"),
      ("stur", "d2, [x29, #-0x10]"), ("ldur", "d4, [x20, #0x17]"), ("fdiv", "d5, d4, d2"),
      ("stur", "d5, [x20, #0x1f]")],
     "x20.field_0x20 = x20.field_0x18 / (x20.field_0x8 / x20.field_0x10);"),
    ([("ldur", "x4, [x20, #7]"), ("lsr", "x4, x4, #3"), ("stur", "x4, [x29, #-0x10]"),
      ("add", "x5, x4, #1"), ("stur", "x5, [x20, #0xf]")],
     "x20.field_0x10 = (x20.field_0x8 >>> 3) + 1;"),
    ([("ldur", "x4, [x20, #7]"), ("neg", "x4, x4"), ("stur", "x4, [x29, #-0x10]"),
      ("neg", "x5, x4"), ("stur", "x5, [x20, #0xf]")],
     "x20.field_0x10 = -(-x20.field_0x8);"),
]


def test_a_spilled_field_is_named_where_it_is_stored_when_a_call_comes_between():
    """A frame slot keeps the TEXT of what was stored in it, so a field spilled before a
    call and reloaded after it printed as a fresh read of the field, which the callee may
    have rewritten. A concurrent modification guard, `length before == length after`,
    then reads as a field compared with itself (#64). The value gets its name at the
    store, and only when it reads memory and a reload after a call can see it."""
    guard = _lift_asm([("ldur", "w4, [x20, #0xb]"), ("stur", "x4, [x29, #-0x10]"),
                       ("bl", "#0x100"), ("ldur", "w0, [x20, #0xb]"),
                       ("ldur", "x2, [x29, #-0x10]"), ("cmp", "w0, w2"),
                       ("b.ne", "#0x24"), ("mov", "x0, #0"), ("ret", ""),
                       ("mov", "x0, #1"), ("ret", "")])
    lines = [ln.strip() for ln in guard.splitlines()]
    assert "if (x20.field_0xc == t0) {" in lines, guard
    assert lines.index("var t0 = x20.field_0xc;") < lines.index("sub_0x100(...);"), guard
    # The register it was stored from holds the same value and takes the same name, or
    # `_pin_call` names the one read a second time when that register outlives the call.
    once = _lift_asm([("ldur", "x19, [x20, #0xf]"), ("stur", "x19, [x29, #-0x10]"),
                      ("bl", "#0x100"), ("ldur", "x2, [x29, #-0x10]"),
                      ("add", "x0, x2, x19"), ("ret", "")])
    assert once.count("x20.field_0x10") == 1 and "return t0 + t0;" in once, once
    # ...and one value spilled to two slots by one `stp` is one name, not two. A pair of
    # 32-bit registers puts its second half four bytes on, where `_step` files it.
    pair = _lift_asm([("ldur", "w4, [x20, #0xb]"), ("stp", "x4, x4, [x29, #-0x10]"),
                      ("bl", "#0x100"), ("ldur", "x0, [x29, #-0x10]"),
                      ("ldur", "x1, [x29, #-0x8]"), ("add", "x0, x0, x1"), ("ret", "")])
    assert pair.count("var ") == 1 and "return t0 + t0;" in pair, pair
    pair = _lift_asm([("ldur", "w4, [x20, #0xb]"), ("ldur", "w5, [x20, #0xf]"),
                      ("stp", "w4, w5, [x29, #-0x10]"), ("bl", "#0x100"),
                      ("ldur", "w0, [x29, #-0xc]"), ("ret", "")])
    assert "var t0 = x20.field_0x10;" in pair and "return t0;" in pair, pair
    # A `ret` neither its callers nor its code decide falls back to the register written
    # last. Where that is d0, naming what d0 holds would claim it is returned, and a
    # function that allocates and fills an object returns x0: it prints the register.
    body = _lift_asm([("bl", "#0x100"), ("ldur", "d0, [x2, #7]"), ("fcmp", "d0, d0"),
                      ("stur", "d0, [x0, #7]"), ("ret", "")])
    assert body.splitlines()[-1].strip() == "return d0;", body

    # Only what needs it. Each of these spills the same field, and none of them has a
    # reload that a call stands in front of and that anything reads, so naming them would
    # be a declaration for nothing.
    from jadart.cfg import build_cfg
    from jadart.expr import Lifter, lift_function, strip_boilerplate

    def named(rows):
        """Whether `_slot_crossings` names a spill in `rows`, as (mnemonic, operands) or
        as annotated rows."""
        ann = [r if len(r) == 4 else (i * 4, r[0], r[1], "") for i, r in enumerate(rows)]
        blocks, entry = build_cfg(strip_boilerplate(ann), traps=())
        return bool(Lifter(blocks, entry=entry)._slot_crossings())
    for why, rows, want in (
            ("no call before the reload",
             [("ldur", "x0, [x29, #-0x10]"), ("ret", "")], "return x20.field_0xc;"),
            ("the reload is overwritten unread",
             [("bl", "#0x100"), ("ldur", "x2, [x29, #-0x10]"), ("mov", "x0, #3"),
              ("ret", "")], "return 3;"),
            ("the slot is stored again first",
             [("bl", "#0x100"), ("mov", "x5, #3"), ("stur", "x5, [x29, #-0x10]"),
              ("ldur", "x0, [x29, #-0x10]"), ("ret", "")], "return 3;"),
            ("a stub call is no call: it keeps the heap",
             [("bl", "#0x100"), ("ldur", "x0, [x29, #-0x10]"), ("ret", "")], None),
            # The walk forgets a slot after a loop that stores over part of it, so the
            # reload prints the register and the name would be read by nothing.
            ("the reload prints as the register",
             [("mov", "x6, #0"), ("bl", "#0x100"), ("stur", "x6, [x29, #-0xc]"),
              ("add", "x6, x6, #1"), ("cmp", "x6, #3"), ("b.lt", "#0xc"),
              ("ldur", "x0, [x29, #-0x10]"), ("ret", "")], "return x0;")):
        rows = [("ldur", "w4, [x20, #0xb]"), ("stur", "x4, [x29, #-0x10]")] + rows
        ann = [(i * 4, mn, op, "  ; -> _iso_stub_AllocateArrayStub"
                if want is None and mn == "bl" else "")
               for i, (mn, op) in enumerate(rows)]
        body = "\n".join(lift_function(ann))
        assert not re.search(r"\{\n\s*\}", body), (why, body)
        if "prints as" in why:
            # The reload says the read now instead of keeping x0, which read as the value
            # the function came in with (#198). The name comes from there and not from
            # `_slot_crossings`, which is what this case is about and what the assertion
            # on `named` below still checks.
            m = re.search(r"var (t\d+) = \(FP - 16\)\.field_0x1;", body)
            assert m and f"return {m.group(1)};" in body, (why, body)
            # Two names now. The call declares what it left in x6, which the loop reads
            # again, where a bare x6 read as the value the function came in with (#176).
            # The spill is still not named, which is what this case is for, so that is
            # what the second assertion says; the numbers move with whoever mints first.
            assert "x20.field_0xc" not in body, (why, body)
            assert body.count("var ") == 2 and re.search(r"var t\d+;", body), (why, body)
        else:
            assert "var " not in body, (why, body)
            assert "return " + ("x20.field_0xc;" if want is None else want[7:]) in body, (
                why, body)
        # Not named at all, rather than named and then found unread; and the other way
        # round where the loop stores over the slot (#157).
        assert named(ann) == ("prints as" in why), why
    # A name read only by the declaration of another that nothing reads goes with it:
    # the second spill is of a field of the first, and the loop stores over its slot.
    body = _lift_asm([("ldur", "w4, [x20, #0xb]"), ("stur", "x4, [x29, #-0x10]"),
                      ("bl", "#0x100"), ("ldur", "x2, [x29, #-0x10]"),
                      ("ldur", "w5, [x2, #0xb]"), ("stur", "x5, [x29, #-0x18]"),
                      ("mov", "x6, #0"), ("bl", "#0x100"), ("stur", "x6, [x29, #-0x14]"),
                      ("add", "x6, x6, #1"), ("cmp", "x6, #3"), ("b.lt", "#0x1c"),
                      ("ldur", "x0, [x29, #-0x18]"), ("ret", "")])
    # Neither spill is named, and the reload at the end says the read it is rather than
    # keeping x0, which read as the value the function came in with (#198).
    assert "x20.field_0xc" not in body and "x2.field_0xc" not in body, body
    m = re.search(r"var (t\d+) = \(FP - 24\)\.field_0x1;", body)
    assert m and f"return {m.group(1)};" in body, body
    assert named([("ldur", "w4, [x20, #0xb]"), ("stur", "x4, [x29, #-0x10]"),
                  ("bl", "#0x100"), ("ldur", "x2, [x29, #-0x10]"),
                  ("ldur", "w5, [x2, #0xb]"), ("stur", "x5, [x29, #-0x18]"),
                  ("mov", "x6, #0"), ("bl", "#0x100"), ("stur", "x6, [x29, #-0x14]"),
                  ("add", "x6, x6, #1"), ("cmp", "x6, #3"), ("b.lt", "#0x1c"),
                  ("ldur", "x0, [x29, #-0x18]"), ("ret", "")])
    # Each arm spills its own field, the join forgets the slot they disagree on, and the
    # names are read by nothing. Where a name is all its arm holds it stays, not leaving
    # the arm empty; lifting again without the names instead printed the field read again
    # after the call, `x20.field_0x48 = x20.field_0x10`, where the machine stores the
    # value from before it.
    for rows, sole in (
            ([("cbz", "x1, #0x1c"), ("ldur", "w4, [x23, #0xb]"),
              ("stur", "x4, [x29, #-0x10]"), ("str", "x5, [x24, #7]"), ("b", "#0x24"),
              ("ldur", "w4, [x23, #0xf]"), ("stur", "x4, [x29, #-0x10]")],
             "var t1 = x23.field_0x10;"),
            ([("cbz", "x1, #0x1c"), ("ldur", "w4, [x23, #0xb]"),
              ("stur", "x4, [x29, #-0x10]"), ("b", "#0x28"), ("nop", ""),
              ("ldur", "w4, [x23, #0xf]"), ("stur", "x4, [x29, #-0x10]"),
              ("str", "x5, [x24, #7]")], "var t0 = x23.field_0xc;")):
        body = _lift_asm([("ldur", "w4, [x20, #0xb]"), ("stur", "x4, [x29, #-0x10]")]
                         + rows + [("bl", "#0x100"), ("ldur", "x0, [x29, #-0x10]"),
                                   ("ret", "")])
        assert not re.search(r"\{\n\s*\}", body), body
        # The join forgot the slot, so the reload says the read rather than keeping x0,
        # which read as the value the function came in with (#198).
        m = re.search(r"var (t\d+) = \(FP - 16\)\.field_0x1;", body)
        assert m and f"return {m.group(1)};" in body, body
        # Two names: the arm's, and the reload after the call, which says the read it
        # is rather than keeping x0 (#198).
        assert body.count("var ") == 2 and sole in body, body
    body = _lift_asm([("ldur", "x2, [x20, #0xf]"), ("stur", "x2, [x29, #-0x18]"),
                      ("ldur", "x5, [x20, #0x17]"), ("cbz", "x5, #0x1c"),
                      ("ldur", "x2, [x20, #7]"), ("bl", "#0x100"), ("b", "#0x24"),
                      ("ldur", "x3, [x20, #0xf]"), ("stur", "x3, [x29, #-0x18]"),
                      ("ldur", "x24, [x29, #-0x18]"), ("bl", "#0x100"),
                      ("ldur", "x3, [x29, #-0x18]"), ("stur", "x3, [x20, #0x47]"),
                      ("ret", "")])
    assert _reads_frame(body.splitlines(), "x20.field_0x48"), body
    # ...and what a declaration that stays reads stays with it.
    body = _lift_asm([("ldur", "w4, [x20, #0xb]"), ("stur", "x4, [x29, #-0x10]"),
                      ("bl", "#0x100"), ("cbz", "x1, #0x24"),
                      ("ldur", "x2, [x29, #-0x10]"),
                      ("ldur", "w5, [x2, #0xb]"), ("stur", "x5, [x29, #-0x18]"),
                      ("b", "#0x30"), ("nop", ""), ("ldur", "w5, [x23, #0xb]"),
                      ("stur", "x5, [x29, #-0x18]"), ("str", "x6, [x24, #7]"),
                      ("bl", "#0x100"), ("ldur", "x0, [x29, #-0x18]"), ("ret", "")])
    # The two calls declare what they left in the registers the arms read, so the second
    # spill's name takes the number after those (#176); that it reads the first is the
    # point, so match the shape rather than the number.
    assert "var t0 = x20.field_0xc;" in body, body
    assert re.search(r"var t\d+ = t0\.field_0xc;", body), body
    # A name whose one printed use is the statement right after the store says no more
    # than the field did, and folds back into it like a call's result does.
    body = _lift_asm([("ldur", "w4, [x20, #0xb]"), ("stur", "x4, [x29, #-0x10]"),
                      ("cbz", "x4, #0x10"), ("bl", "#0x200"), ("mov", "x6, #0"),
                      ("bl", "#0x100"), ("stur", "x6, [x29, #-0xc]"),
                      ("add", "x6, x6, #1"), ("cmp", "x6, #3"), ("b.lt", "#0x14"),
                      ("ldur", "x0, [x29, #-0x10]"), ("ret", "")])
    # The guard still folds the field back into the condition. The one name is the
    # reload after the loop, which says the read it is rather than keeping x0 (#198).
    assert "if (x20.field_0xc != 0) {" in body, body
    # Two now: the call in the loop declares what it left in x6, which the loop reads
    # again (#176). The spill is still not named, which is what this case is for; the
    # field itself is in the body, folded back into the condition above.
    assert not re.search(r"var t\d+ = x20\.field_0xc;", body), body
    assert body.count("var ") == 2 and re.search(r"var t\d+;", body), body
    assert re.search(r"var (t\d+) = \(FP - 16\)\.field_0x1;\n\s*return \1;", body), body
    assert named([("ldur", "w4, [x20, #0xb]"), ("stur", "x4, [x29, #-0x10]"),
                  ("cbz", "x4, #0x10"), ("bl", "#0x200"), ("mov", "x6, #0"),
                  ("bl", "#0x100"), ("stur", "x6, [x29, #-0xc]"),
                  ("add", "x6, x6, #1"), ("cmp", "x6, #3"), ("b.lt", "#0x14"),
                  ("ldur", "x0, [x29, #-0x10]"), ("ret", "")])
    # In brackets where it is more than one term, whatever the operator: `t0 * x6` is not
    # `a + 1 * x6`, and the precedence table holds no `/` or `>>>` to ask; see the CPU
    # check of these below.
    for rows, want in _FOLDS:
        body = _lift_asm(_then_forget(rows))
        # The fold is not named. The one name is the reload `_then_forget` puts after the
        # loop, which says the read it is rather than keeping x0 (#198).
        assert want in body, (want, body)
        # Two names: the loop's call declares what it left in x6, which the loop reads
        # again (#176). The fold is still not named, which is what this case is for.
        assert body.count("var ") == 2 and re.search(r"var t\d+;", body), (want, body)
        assert re.search(r"var (t\d+) = \(FP - 16\)\.field_0x1;\n\s*return \1;",
                         body), (want, body)
        assert named(_then_forget(rows)), want              # named, then found unread
    # ...and a value that reads no memory cannot be changed by the callee.
    body = _lift_asm([("add", "x4, x19, #1"), ("stur", "x4, [x29, #-0x10]"),
                      ("bl", "#0x100"), ("ldur", "x0, [x29, #-0x10]"), ("ret", "")])
    assert "return x19 + 1;" in body and "var " not in body, body


def test_a_spilled_field_named_across_a_call_agrees_at_the_join_and_round_a_loop():
    """Naming at the CALL, the first cut at #64, put the name inside the arm or the loop
    body that made the call. The other arm still held the field, the arms disagreed at
    the join and the reload after it dropped to a bare register; inside a loop the field
    was read again on every trip, where the machine reads its spill. A name given at the
    store sits before the `if` and before the `while`, on every path to the reload."""
    join = _lift_asm([("ldur", "w4, [x20, #0xb]"), ("stur", "x4, [x29, #-0x10]"),
                      ("cbz", "x1, #0x10"), ("bl", "#0x100"),
                      ("ldur", "x0, [x29, #-0x10]"), ("ret", "")])
    lines = [ln.strip() for ln in join.splitlines()]
    assert lines[0] == "var t0 = x20.field_0xc;" and "return t0;" in lines, join

    loop = _lift_asm([("ldur", "w4, [x20, #0xb]"), ("stur", "x4, [x29, #-0x10]"),
                      ("mov", "x19, #0"), ("bl", "#0x100"),
                      ("ldur", "x2, [x29, #-0x10]"), ("add", "x19, x19, x2"),
                      ("cmp", "x19, #0x64"), ("b.lt", "#0xc"), ("mov", "x0, x19"),
                      ("ret", "")])
    lines = [ln.strip() for ln in loop.splitlines()]
    assert lines.index("var t0 = x20.field_0xc;") < lines.index("while (true) {"), loop
    assert "field_0xc" not in loop.split("while (true) {", 1)[1], loop
    # A spill written back unchanged around the call, `ldur x24, [k]; bl; stur x24, [k]`,
    # leaves the value from before the loop in the slot: the name is the store in front
    # of the loop's, where reading the field inside the loop gave the second trip the
    # field the first one wrote.
    loop = _lift_asm([("ldur", "x2, [x20, #0xf]"), ("stur", "x2, [x29, #-0x18]"),
                      ("mov", "x25, #0"), ("ldur", "x24, [x29, #-0x18]"),
                      ("bl", "#0x100"), ("stur", "x24, [x29, #-0x18]"),
                      ("stur", "x0, [x20, #0xf]"), ("stur", "x24, [x20, #7]"),
                      ("add", "x25, x25, #1"),
                      ("cmp", "x25, #2"), ("b.lt", "#0xc"), ("ret", "")])
    lines = [ln.strip() for ln in loop.splitlines()]
    assert lines.index("var t0 = x20.field_0x10;") < lines.index("while (true) {"), loop
    assert "x20.field_0x8 = t0;" in lines and loop.count("x20.field_0x10;") == 1, loop
    # The reload at the top of the body comes after a call too, the one the trip before
    # made: only the back edge says so.
    loop = _lift_asm([("ldur", "w4, [x20, #0xb]"), ("stur", "x4, [x29, #-0x10]"),
                      ("mov", "x19, #0"), ("ldur", "x2, [x29, #-0x10]"),
                      ("add", "x19, x19, x2"), ("bl", "#0x100"), ("cmp", "x19, #0x64"),
                      ("b.lt", "#0xc"), ("mov", "x0, x19"), ("ret", "")])
    lines = [ln.strip() for ln in loop.splitlines()]
    assert lines.index("var t0 = x20.field_0xc;") < lines.index("while (true) {"), loop
    assert "field_0xc" not in loop.split("while (true) {", 1)[1], loop


def test_a_spill_passed_to_a_call_counts_as_read():
    """Liveness says a direct call reads no register, and a reload that only feeds a call
    looked unread, so its slot kept no name: `handleMessage` passed a spilled field on as
    an argument, and the argument printed as a fresh read of the field after the calls in
    between (#64). The printed arguments are what the reader reads: the registers of a
    call whose arity is known, and x0 for a throw."""
    from jadart.expr import lift_function
    spill = [("ldur", "w4, [x20, #0xb]", ""), ("stur", "x4, [x29, #-0x10]", ""),
             ("bl", "#0x100", "")]

    def lift(rows, arity=None):
        ann = [(i * 4, mn, op, note) for i, (mn, op, note) in enumerate(spill + rows)]
        return "\n".join(lift_function(ann, arity=arity))
    call = [("ldur", "x1, [x29, #-0x10]", ""), ("bl", "#0x200", ""), ("ret", "", "")]
    body = lift(call, arity=lambda pc: 1 if pc == 0x200 else None)
    assert "var t0 = x20.field_0xc;" in body and "sub_0x200(t0)" in body, body
    body = lift([("ldur", "x0, [x29, #-0x10]", ""),
                 ("bl", "#0x300", "  ; -> _iso_stub_ThrowStub"), ("ret", "", "")])
    assert "var t0 = x20.field_0xc;" in body and "throw t0;" in body, body
    # A call that prints `(...)` reads nothing the reader can see: one whose arity is not
    # known, and one to a stub, which `_call_args` never spells out.
    body = lift(call, arity=lambda pc: None)
    assert "var " not in body and "sub_0x200(...)" in body, body
    from jadart.cfg import build_cfg
    from jadart.expr import Lifter, strip_boilerplate
    for note, named in (("  ; -> stub Foo", False), ("  ; -> foo", True)):
        rows = spill + [("ldur", "x1, [x29, #-0x10]", ""), ("bl", "#0x200", note),
                        ("ret", "", "")]
        ann = [(i * 4, mn, op, n) for i, (mn, op, n) in enumerate(rows)]
        blocks, entry = build_cfg(strip_boilerplate(ann), traps=())
        lifter = Lifter(blocks, entry=entry, arity=lambda pc: 1)
        assert bool(lifter._slot_crossings()) == named, note


def test_the_slot_dataflow_reaches_its_fixed_point_along_backward_branches():
    """`_slot_crossings` runs a worklist where `_liveness` sweeps, because a fact crosses
    one block per sweep along a chain of backward branches (#64). The answer has to be
    the same fixed point all the same: a field spilled at the top, then a chain of 40
    blocks each jumping back to the one before, then a call and the reload. The name
    is only given if the reload's liveness reaches the store through the whole chain.
    A frame move between store and reload is the other way a slot stops being the same
    address, and `_step` forgets every slot there, so nothing may be named across it."""
    from jadart.cfg import build_cfg
    from jadart.expr import Lifter, _liveness, lift_function, strip_boilerplate
    n = 40
    rows = [("ldur", "w4, [x20, #0xb]"), ("stur", "x4, [x29, #-0x10]"),
            ("b", f"#{(3 + 3 * (n - 1)) * 4:#x}"), ("bl", "#0x10000"),
            ("ldur", "x0, [x29, #-0x10]"), ("ret", "")]
    for i in range(1, n):
        rows += [("nop", ""), ("nop", ""),
                 ("b", f"#{(3 + 3 * (i - 1)) * 4 if i > 1 else 12:#x}")]
    ann = [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)]
    body = "\n".join(lift_function(ann))
    assert "var t0 = x20.field_0xc;" in body and "return t0;" in body, body
    blocks, entry = build_cfg(strip_boilerplate(ann), traps=())
    lifter = Lifter(blocks, entry=entry)
    assert lifter._liveout == _liveness(blocks)[1]
    assert lifter._slot_crossings() == {(4, "x29-16")}

    # A register reloaded from a slot stores back the value already there only while
    # nothing else was stored to the slot in between; after one it is a store like any.
    # Here the reload at the end reads the stale register's value, stored after the call.
    stale = [("ldur", "w4, [x20, #0xb]"), ("stur", "x4, [x29, #-0x10]"),
             ("ldur", "x19, [x29, #-0x10]"), ("ldur", "w5, [x20, #0xf]"),
             ("stur", "x5, [x29, #-0x10]"), ("bl", "#0x100"),
             ("stur", "x19, [x29, #-0x10]"), ("ldur", "x0, [x29, #-0x10]"), ("ret", "")]
    ann = [(i * 4, mn, op, "") for i, (mn, op) in enumerate(stale)]
    blocks, entry = build_cfg(strip_boilerplate(ann), traps=())
    assert Lifter(blocks, entry=entry)._slot_crossings() == frozenset()

    moved = [("ldur", "w4, [x20, #0xb]"), ("stur", "x4, [x29, #-0x10]"),
             ("bl", "#0x100"), ("ldr", "x5, [x29, #-8]!"),
             ("ldur", "x0, [x29, #-0x10]"), ("ret", "")]
    ann = [(i * 4, mn, op, "") for i, (mn, op) in enumerate(moved)]
    blocks, entry = build_cfg(strip_boilerplate(ann), traps=())
    assert Lifter(blocks, entry=entry)._slot_crossings() == frozenset()


def test_no_field_is_compared_with_itself_after_a_call_on_the_clean_fixture():
    """The spill pattern of #64 in the clean fixture, beyond `forEach`: `_filterWhere`
    keeps a field in a slot across the predicate call and `updateChildren` across a
    child update, and each then compared the field with itself. Both print the value
    from before the call against the one after it now."""
    _needs_capstone()
    from jadart.disasm import (load_instructions, disassemble_range, build_pool_map,
                               function_name_by_pc)
    from jadart.expr import lift_function, make_arity_resolver
    image, fr, _hdr = load_instructions(CLEAN)
    p2n = function_name_by_pc(image, fr)
    pm, ar = build_pool_map(fr), make_arity_resolver(image)
    seen = set()
    for cr in image.all_ranges:
        name = p2n.get(cr.pc_offset) or ""
        if name.split("@")[0] not in ("forEach", "_filterWhere", "updateChildren"):
            continue
        dis = disassemble_range(image, cr)
        if not dis:
            continue
        body = "\n".join(lift_function(_ann(image, dis, p2n, pm), pm,
                                       receiver={"x1": "this"}, arity=ar))
        seen.add(name.split("@")[0])
        for a, b in re.findall(r"\(([^()]+) [=!]= ([^()]+)\)", body):
            assert a != b or "field_" not in a, (
                f"{name} at 0x{cr.pc_offset:x} compares {a!r} with itself:\n{body}")
    assert seen == {"forEach", "_filterWhere", "updateChildren"}, seen


def _encode_fold(mn, op):
    """The word for one of the instructions in _FOLDS, or None."""
    m = re.match(r"(\w+) ([xd])(\d+), \[x(\d+), #(-?0x[0-9a-f]+|-?\d+)\]$", f"{mn} {op}")
    if m:
        base = {("ldur", "x"): 0xF8400000, ("stur", "x"): 0xF8000000,
                ("ldur", "d"): 0xFC400000, ("stur", "d"): 0xFC000000}[(m[1], m[2])]
        return base | (int(m[5], 0) & 0x1ff) << 12 | int(m[4]) << 5 | int(m[3])
    regs = [int(r) for r in re.findall(r"[xd](\d+)", op)]
    imm = re.search(r"#(\d+)", op)
    if mn == "fdiv":
        return 0x1E601800 | regs[2] << 16 | regs[1] << 5 | regs[0]
    if mn == "lsr":
        return 0xD340FC00 | int(imm[1]) << 16 | regs[1] << 5 | regs[0]
    if mn == "add" and imm:
        return 0x91000000 | int(imm[1]) << 10 | regs[1] << 5 | regs[0]
    return None


def test_a_folded_slot_name_keeps_its_brackets_against_the_cpu():
    """The two folds of _FOLDS whose operator the precedence table lacks, run on the
    CPU: the right-hand side the lifter prints, evaluated with the fields the CPU read,
    has to give what the CPU stored. Without the brackets it gave `a / b / c` for
    `a / (b / c)`, and `a >>> 3 + 1` for `(a >>> 3) + 1` (#64)."""
    if not _unicorn_available() or not _capstone_available():
        _skip("  SKIP test_a_folded_slot_name_keeps_its_brackets_against_the_cpu")
    import ast
    import struct as _struct
    import capstone
    sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "tools"))
    import irfuzz
    from jadart.expr import lift_function
    unicorn, Uc, ARCH, MODE, a64 = irfuzz._unicorn()
    md = capstone.Cs(capstone.CS_ARCH_ARM64, capstone.CS_MODE_ARM)

    def ev(node, env):
        if isinstance(node, ast.Expression):
            return ev(node.body, env)
        if isinstance(node, ast.Name):
            return env[node.id]
        if isinstance(node, ast.Constant):
            return node.value
        a, b = ev(node.left, env), ev(node.right, env)
        return {ast.Add: lambda: a + b, ast.Div: lambda: a / b,
                ast.RShift: lambda: a >> b}[type(node.op)]()
    for (rows, want), fields, fmt, out in (
            (_FOLDS[1], {8: 6.0, 16: 3.0, 24: 12.0}, "<d", 0x20),
            (_FOLDS[2], {8: 0x1000}, "<Q", 0x10)):
        words = [_encode_fold(mn, op) for mn, op in rows]
        code = b"".join(_struct.pack("<I", w) for w in words)
        assert [f"{i.mnemonic} {i.op_str}" for i in md.disasm(code, 0)] == [
            f"{mn} {op}" for mn, op in rows]
        mu = Uc(ARCH, MODE)
        mu.mem_map(irfuzz.BASE, 0x1000)
        mu.mem_write(irfuzz.BASE, code)
        mu.mem_map(0x200000, 0x1000)
        mu.mem_map(0x300000, 0x1000)
        for off, val in fields.items():
            mu.mem_write(0x300000 + off, _struct.pack(fmt, val))
        mu.reg_write(a64.UC_ARM64_REG_X20, 0x300001)
        mu.reg_write(a64.UC_ARM64_REG_X29, 0x200800)
        mu.reg_write(a64.UC_ARM64_REG_CPACR_EL1, 0x300000)      # FP on
        mu.emu_start(irfuzz.BASE, irfuzz.BASE + len(code))
        cpu = _struct.unpack(fmt, mu.mem_read(0x300000 + out, 8))[0]
        ann = [(i * 4, mn, op, "") for i, (mn, op) in enumerate(_then_forget(rows))]
        line = next(ln for ln in lift_function(ann) if f"field_{out:#x} =" in ln)
        rhs = line.split(" = ", 1)[1].rstrip(";").replace(">>>", ">>")
        rhs = re.sub(r"x20\.field_0x([0-9a-f]+)", lambda m: f"f{int(m[1], 16)}", rhs)
        env = {f"f{off}": val for off, val in fields.items()}
        assert ev(ast.parse(rhs, mode="eval"), env) == cpu, (line, cpu)


#: A loop that keeps its counter in a frame slot, as #109 gives it: x0 starts at 1, the
#: slot counts up to 10 and the function returns it.
_SLOT_LOOP = [(0xD2800020, "mov x0, #1"), (0xF81F83A0, "stur x0, [x29, #-8]"),
              (0xF85F83A1, "ldur x1, [x29, #-8]"), (0x91000421, "add x1, x1, #1"),
              (0xF81F83A1, "stur x1, [x29, #-8]"), (0xF100283F, "cmp x1, #0xa"),
              (0x54FFFF8B, "b.lt #8"), (0xAA0103E0, "mov x0, x1"), (0xD65F03C0, "ret")]


def test_a_loop_that_stores_to_a_slot_does_not_read_its_pre_loop_value():
    """The walk of a loop starts from the state before it, so a slot the body stores a
    new value to kept its pre-loop text at the top of every trip (#109). The counter
    above printed as `(1 + 1) >= 0xa`, a loop that never ends, where the CPU counts the
    slot to 10 and returns. Checked against the CPU: the printed body is run, and it
    may decline to say (a register it does not know) but not claim to loop forever."""
    if not _unicorn_available() or not _capstone_available():
        _skip("  SKIP test_a_loop_that_stores_to_a_slot_does_not_read_its_pre_loop_value")
    import struct as _struct
    import capstone
    sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "tools"))
    import irfuzz
    from jadart.expr import lift_function
    code = b"".join(_struct.pack("<I", w) for w, _t in _SLOT_LOOP)
    md = capstone.Cs(capstone.CS_ARCH_ARM64, capstone.CS_MODE_ARM)
    ann = [(i.address, i.mnemonic, i.op_str, "") for i in md.disasm(code, 0)]
    assert [f"{m} {o}".strip() for _a, m, o, _n in ann] == [t for _w, t in _SLOT_LOOP]

    unicorn, Uc, ARCH, MODE, a64 = irfuzz._unicorn()
    mu = Uc(ARCH, MODE)
    mu.mem_map(irfuzz.BASE, 0x1000)
    mu.mem_write(irfuzz.BASE, code)
    mu.mem_map(0x200000, 0x1000)
    mu.reg_write(a64.UC_ARM64_REG_X29, 0x200800)
    mu.emu_start(irfuzz.BASE, irfuzz.BASE + len(code) - 4)
    assert mu.reg_read(a64.UC_ARM64_REG_X0) == 10

    lines = lift_function(ann)
    body = "\n".join(lines)
    assert "(1 + 1)" not in body, body
    env = {f"x{i}": 0 for i in range(31)}
    env["xzr"] = 0
    try:
        _run, _wrote, ret = irfuzz._run_body(irfuzz._parse_body(lines)[0], env, 512)
    except irfuzz._Undecidable as exc:
        assert "budget" not in str(exc), f"the printed loop never ends:\n{body}"
    else:
        assert ret == 10, body


def test_a_loop_keeps_a_slot_it_only_writes_back():
    """The other half of #109. Forgetting every slot a loop stores to was measured and
    is mostly a loss: the stores are spills of a value the loop does not change, `this`
    saved again around a call, and the pre-loop text was right. A store keeps the slot
    when it writes back what it reloaded, or a register the loop never writes that held
    the slot's value on the way in; and a store on a path that throws never comes back
    round. A trap ends its block, and so does a call to a stub that throws, so a `b` after
    either closes no loop (#64, #234); a throw INSIDE a loop leaves it, and the loop is
    still a loop."""
    from jadart.expr import lift_function

    def lift(rows):
        ann = [(i * 4, r[0], r[1], r[2] if len(r) > 2 else "")
               for i, r in enumerate(rows)]
        return "\n".join(lift_function(ann, receiver={"x1": "this"}))
    for why, rows in (
            ("written back as reloaded",
             [("stur", "x1, [x29, #-8]"), ("ldur", "x2, [x29, #-8]"), ("bl", "#0x100"),
              ("ldur", "x2, [x29, #-8]"), ("stur", "x2, [x29, #-8]"),
              ("ldur", "x0, [x2, #7]"), ("cbnz", "x0, #0x4"), ("ret", "")]),
            ("a register the loop never writes",
             [("mov", "x20, x1"), ("stur", "x20, [x29, #-8]"), ("bl", "#0x100"),
              ("ldur", "x2, [x29, #-8]"), ("ldur", "x0, [x2, #7]"),
              ("stur", "x20, [x29, #-8]"), ("cbnz", "x0, #0x8"), ("ret", "")]),
            # A throw inside the body leaves the loop, and the loop is still a loop: the
            # `break` lands on the throw, and the trip after it is the one the back edge
            # below the throw makes.
            ("a throw on the way round",
             [("stur", "x1, [x29, #-8]"), ("ldur", "x2, [x29, #-8]"),
              ("ldur", "x0, [x2, #7]"), ("cbnz", "x0, #0x18"), ("stur", "x0, [x29, #-8]"),
              ("bl", "#0x100", "  ; -> _iso_stub_NullErrorSharedWithoutFPURegsStub"),
              ("bl", "#0x200"), ("cbnz", "x0, #0x4"), ("ret", "")])):
        body = lift(rows)
        assert "while (true) {" in body and "this.field_0x8" in body, (why, body)
        assert "x2.field_0x8" not in body, (why, body)
    # Past a trap, and past a call that cannot return, there is no loop at all: the block
    # ends there, so the `b` after it is unreachable and closes nothing (#64, #234). The
    # code after it is still placed, as its own labelled section holding that `b`, and the
    # slot still keeps `this`, not the register it was reloaded into.
    throws = "  ; -> _iso_stub_NullErrorSharedWithoutFPURegsStub"
    for why, rows in (
            ("past a trap",
             [("stur", "x1, [x29, #-8]"), ("ldur", "x2, [x29, #-8]"),
              ("ldur", "x0, [x2, #7]"), ("cbz", "x0, #0x14"), ("ret", ""),
              ("stur", "x0, [x29, #-8]"), ("bl", "#0x100"), ("brk", "#0"),
              ("b", "#0x4")]),
            ("past a throw stub",
             [("stur", "x1, [x29, #-8]"), ("ldur", "x2, [x29, #-8]"),
              ("ldur", "x0, [x2, #7]"), ("cbz", "x0, #0x14"), ("ret", ""),
              ("stur", "x0, [x29, #-8]"), ("bl", "#0x100", throws), ("b", "#0x4")]),
            # The only way back to the top runs through the throw, so the store at the
            # top is never read by a next trip: there is no loop.
            ("a loop only a throw closes",
             [("stur", "x1, [x29, #-8]"), ("ldur", "x2, [x29, #-8]"),
              ("ldur", "x0, [x2, #7]"), ("stur", "x0, [x29, #-8]"), ("cbz", "x0, #0x18"),
              ("ret", ""), ("bl", "#0x100", throws), ("b", "#0x4")])):
        body = lift(rows)
        assert "while (true) {" not in body and "this.field_0x8" in body, (why, body)
        assert "x2.field_0x8" not in body, (why, body)
        assert "goto L_0x4;" in body, (why, body)
    # ...and one that stores something else does forget it: the loop reads its own
    # value back at the top of the next trip, not `this`. So does a register that held
    # the slot's value on the way in, once the loop has changed it, and a loop that moves
    # the frame, whose slots are other addresses by the next trip.
    for why, rows in (
            ("another value",
             [("stur", "x1, [x29, #-8]"), ("bl", "#0x100"), ("ldur", "x2, [x29, #-8]"),
              ("ldur", "x0, [x2, #7]"), ("stur", "x0, [x29, #-8]"), ("cbnz", "x0, #0x4"),
              ("ret", "")]),
            ("its register, changed",
             [("mov", "x3, x1"), ("stur", "x3, [x29, #-8]"), ("mov", "x19, #0"),
              ("ldur", "x2, [x29, #-8]"), ("ldur", "x0, [x2, #7]"),
              ("stur", "x0, [x20, #0xf]"), ("add", "x3, x3, #8"),
              ("stur", "x3, [x29, #-8]"), ("add", "x19, x19, #1"), ("cmp", "x19, #3"),
              ("b.lt", "#0xc"), ("ret", "")]),
            ("the frame moves",
             [("stur", "x1, [x29, #-8]"), ("ldur", "x2, [x29, #-8]"),
              ("ldur", "x0, [x2, #7]"), ("ldr", "x5, [x29, #-8]!"),
              ("cbnz", "x0, #0x4"), ("ret", "")])):
        body = lift(rows)
        # Fresh, not the stale `this.field_0x8`. Read through the name the reload gives
        # the slot now rather than through x2, which read as the value the function came
        # in with (#198).
        assert "this.field_0x8" not in body, (why, body)
        assert re.search(r"var (t\d+) = \(?(?:FP|SP)[^;]*;[\s\S]*?\1\.field_0x8",
                         body), (why, body)
    # The counter of #109 itself, without the CPU the test above needs.
    body = lift([(t.split(" ", 1)[0], t.split(" ", 1)[1] if " " in t else "")
                 for _w, t in _SLOT_LOOP])
    # Still read afresh on every trip rather than folded to a constant. Read through the
    # name the reload gives the slot now, not through x1 (#198).
    assert "(1 + 1)" not in body, body
    m = re.search(r"var (t\d+) = \(?(?:FP|SP)[^;]*;", body)
    assert m and f"if (({m.group(1)} + 1) >= 0xa) {{" in body, body
    # A write-back is judged by slot key, and once the frame moves a key is another
    # address: a register reloaded before the move and stored after it is a new store.
    from jadart.expr import _frame_accesses
    rows = [("ldur", "x2, [x29, #-8]"), ("ldr", "x5, [x29, #-0x10]!"),
            ("stur", "x2, [x29, #-8]"), ("ldur", "x3, [x29, #-8]"),
            ("stur", "x3, [x29, #-8]")]
    got = _frame_accesses([(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])
    assert [t[4] for t in got if t[4] is not None] == [[False], [True]]


def test_a_loop_rewriting_a_slot_that_held_a_lost_register_still_lifts():
    """Two rules forget the same frame slot at a loop's head. The slot holds x3 as a join
    lost it, and the loop writes x3, so the slot goes with it (#140); the loop also stores
    x6 there and reads it back at the top, so `_loop_rewrites` names it too (#109). The
    second was a `del` on the loop's state after the first had run, and raised KeyError
    out of `lift_function` on this range (#287). Applied first, both forget the slot, and
    the reload in the loop reads the slot afresh rather than the x3 the first trip saw."""
    from jadart.expr import lift_function
    rows = [("b.ne", "#0x20"), ("cbnz", "x1, #0x14"), ("b", "#0x8"), ("b.ge", "#0x1c"),
            ("nop", ""), ("stur", "x3, [x29, #-8]"), ("b.ne", "#0x24"), ("b.ne", "#0x18"),
            ("b", "#0x10"), ("cmp", "x5, x1"), ("ldur", "x5, [x29, #-8]"),
            ("stur", "x6, [x29, #-8]"), ("ldur", "x3, [x29, #-24]"), ("b", "#0xc"),
            ("ret", "")]
    ann = [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)]
    body = "\n".join(lift_function(ann))
    assert "while (true) {" in body, body
    assert re.search(r"var t\d+ = \(FP - 8\)", body), body
    assert not re.search(r"\bx3\b", body), body


def test_the_lifted_output_does_not_depend_on_the_hash_seed():
    # Python randomises string hashing per process, so iterating a SET of register names
    # is a different order in every run. The lifter invalidates a set of registers after a
    # loop, and that write inserts into the register map, whose insertion order decides
    # the order temporaries are minted in: two runs over the same binary numbered the same
    # variables differently and `bench.py --digest`, which exists to compare checkouts for
    # equivalence, could not tell a real change from a reshuffle. Two subprocesses, because
    # the seed is fixed for the life of one.
    if not _capstone_available():
        _skip("  SKIP test_the_lifted_output_does_not_depend_on_the_hash_seed")
    import subprocess
    prog = (
        "import hashlib,sys;"
        "sys.path.insert(0, %r);" % os.path.join(os.path.dirname(__file__), "..") +
        "from jadart.disasm import load_instructions, disassemble_range, annotate,"
        " build_pool_map, function_name_by_pc;"
        "from jadart.expr import lift_function, make_arity_resolver;"
        "from jadart.branches import row_kinds;"
        "image, fr, hdr = load_instructions(%r);" % CLEAN +
        "p2n = function_name_by_pc(image, fr); pm = build_pool_map(fr);"
        "ar = make_arity_resolver(image); h = hashlib.sha256();"
        "[h.update(('\\n'.join(lift_function(annotate(d, p2n, pm, kinds=row_kinds(image, d)),"
        " pm, arity=ar))).encode())"
        " for d in (disassemble_range(image, cr) for cr in list(image.all_ranges)[::5]) if d];"
        "print(h.hexdigest())")
    digests = set()
    for seed in ("1", "424242"):
        env = dict(os.environ, PYTHONHASHSEED=seed)
        out = subprocess.run([sys.executable, "-c", prog], env=env,
                             capture_output=True, text=True)
        assert out.returncode == 0, out.stderr[-2000:]
        digests.add(out.stdout.strip())
    assert len(digests) == 1, f"the lift is not reproducible: {digests}"


def test_a_loop_does_not_leave_stale_values_behind_it():
    # `carried` is written-and-live-on-entry, and restoring only those left every register
    # the loop assigns WITHOUT reading first still holding its value from before the loop.
    # Set x9 to 5, write 7 to it in the body, and the code after the loop printed `return
    # 5;`, a confident wrong answer, which is the one thing this tool must not produce.
    body = _lift_asm([("mov", "x9, #5"), ("mov", "x9, #7"), ("cbnz", "x2, #4"),
                      ("mov", "x0, x9"), ("ret", "")])
    assert "return 5;" not in body, body
    assert "return x9;" in body, body


def test_tier3_strips_smi_box_idiom():
    # The Smi int-boxing idiom (sbfiz XD,XS,#1; cmp XS,XD,asr #1; b.eq; AllocateMint) must
    # not leak as a bogus self-comparison `if (x != x)`, and the Smi tag `sbfiz` must not
    # appear raw. benchRunAll boxes several int results and exercises this.
    if not _capstone_available():
        _skip("  SKIP test_tier3_strips_smi_box_idiom (no capstone)")
    import re
    from jadart.disasm import (load_instructions, disassemble_function,
                               function_name_by_pc, build_pool_map)
    from jadart.expr import lift_function, make_arity_resolver
    image, fr, _ = load_instructions(CLEAN)
    refs = [r for r, nr, ow, kt in fr.functions if fr.strings.get(nr) == "benchRunAll"]
    body = "\n".join(lift_function(
        _ann(image, disassemble_function(image, refs[0]),
             function_name_by_pc(image, fr), build_pool_map(fr)),
        build_pool_map(fr), arity=make_arity_resolver(image)))
    assert "sbfiz" not in body, "Smi tag (sbfiz) leaked as raw arm64"
    assert not re.search(r"if \((\w[\w.]*) != \1\)", body), "Smi overflow-check leaked as `x != x`"


def test_tier3_renders_runtime_stubs_semantically():
    # On a real app (dwarf build, stubs named in the ELF), VM runtime stubs must render as
    # source operations (throw / new) or be dropped (stack check, write barrier, type test) -
    # never as a raw `stub _iso_stub_...` call. Portable: set JADART_REALAPP_LIB.
    lib = os.environ.get("JADART_REALAPP_LIB")
    if not lib or not os.path.exists(lib) or not _capstone_available():
        _skip("  SKIP test_tier3_renders_runtime_stubs_semantically "
              "(set JADART_REALAPP_LIB to an unstripped dwarf-mode libapp.so)")
    from jadart.disasm import (load_instructions, disassemble_range,
                               function_name_by_pc, build_pool_map)
    from jadart.expr import lift_function, make_arity_resolver
    image, fr, _ = load_instructions(lib)
    p2n = function_name_by_pc(image, fr)
    pm = build_pool_map(fr)
    ar = make_arity_resolver(image)
    leaked = throws = news = 0
    for cr in image.all_ranges[:3000]:
        dis = disassemble_range(image, cr)
        if not dis:
            continue
        body = "\n".join(lift_function(_ann(image, dis, p2n, pm), pm, arity=ar))
        if "_iso_stub_" in body:
            leaked += 1
        throws += body.count("throw ")
        news += body.count("new ")
    assert leaked == 0, f"{leaked} functions leaked a raw _iso_stub_ call"
    assert throws > 0 and news > 0, "expected some throw / new renderings on a real app"


def test_runtime_stubs_are_named_from_the_object_store_roots():
    """A stub has no Function object and a release build keeps no symbol for one, so its
    name comes from the isolate snapshot's own object-store roots (#234).

    Both fixtures are plain `flutter build apk --release` output, features
    `no-dwarf_stack_traces_mode`, and before this they carried ZERO stub names: every
    stub-aware rule in the lifter was dead code on the build a user actually has, and a
    call that cannot return printed as `sub_0x2d5d00(...)`, an ordinary call that does."""
    from jadart.disasm import load_instructions
    from jadart.expr import _classify_stub
    from jadart.objstore import stub_names
    for lib in (CLEAN, OBF):
        image, fr, hdr = load_instructions(lib)
        got = stub_names(image, fr, hdr.epoch)
        assert len(got) == 76, (lib, len(got))
        # Each named pc is a range the image really has, and none of them had a name of
        # its own: a stub's Code is owned by no Function, which is why the map had none.
        starts = {cr.pc_offset for cr in image.all_ranges}
        assert set(got) <= starts, sorted(set(got) - starts)
        fname = {ref: fr.strings.get(nr, "") for ref, nr, _ow, _kt in fr.functions}
        owned = {cr.pc_offset for ow, cr in image.code_ranges.items() if fname.get(ow)}
        assert not (set(got) & owned), sorted(set(got) & owned)
        names = set(got.values())
        for want in ("_iso_stub_ThrowStub", "_iso_stub_AllocateArrayStub",
                     "_iso_stub_NullCastErrorSharedWithoutFPURegsStub",
                     "_iso_stub_StackOverflowSharedWithoutFPURegsStub"):
            assert want in names, (lib, want)
    # The eight ranges #234 measured, which are 50.1% of the clean export's printed calls.
    # The last of them is the reason a prologue-shape heuristic was not enough: it spills
    # the whole register file like the shared stubs do, and it returns.
    image, fr, hdr = load_instructions(CLEAN)
    got = stub_names(image, fr, hdr.epoch)
    want = {0x19f280: "NullCastErrorSharedWithoutFPURegs",
            0x19f120: "RangeErrorSharedWithoutFPURegs",
            0x19ebf0: "StackOverflowSharedWithoutFPURegs",
            0x19f1b0: "RangeErrorSharedWithFPURegs",
            0x19f508: "LateInitializationErrorSharedWithoutFPURegs",
            0x19f430: "NullErrorSharedWithoutFPURegs",
            0x19f2cc: "NullCastErrorSharedWithFPURegs",
            0x19e0e4: "AllocateFloat64Array"}
    for pc, nm in want.items():
        assert got.get(pc) == f"_iso_stub_{nm}Stub", (hex(pc), got.get(pc))
    # and the taxonomy those names wake up, which is the point of naming them
    assert _classify_stub(got[0x19f280]) == ("throw_err", "NullCastError")
    assert _classify_stub(got[0x19ebf0]) == ("suppress", None)
    assert _classify_stub(got[0x19e0e4]) == ("alloc", "Float64List")


def test_a_call_that_cannot_return_ends_its_block():
    """A `bl` to a stub that throws gets no fall-through, so the structurer cannot render
    a path the machine never takes (#234).

    Nothing in a `bl` says the callee does not come back, so the lift hands the addresses
    over (`_path_ends`) and `build_cfg` ends those blocks the way it ends one at a trap
    (#57). What was reached only through the old edge is still placed, as its own labelled
    section: Ghidra and Hex-Rays drop such code, and a callee misidentified as
    non-returning there hides real source, where a labelled section cannot."""
    from jadart.cfg import TRAPS, build_cfg
    from jadart.expr import _path_ends, lift_function
    throw = "  ; -> _iso_stub_NullCastErrorSharedWithoutFPURegsStub"
    rows = [("cbz", "x0, #0x8"), ("bl", "#0x100", throw), ("bl", "#0x100", throw),
            ("mov", "x0, #1"), ("ret", "")]
    ann = [(i * 4, r[0], r[1], r[2] if len(r) > 2 else "") for i, r in enumerate(rows)]
    blocks, _entry = build_cfg(ann, traps=TRAPS, ends=_path_ends(ann))
    assert [(a, b.succ, b.ends_path) for a, b in sorted(blocks.items())] == [
        (0x0, [0x8, 0x4], False), (0x4, [], True), (0x8, [], True), (0xc, [], False)]
    # Without the addresses the throw falls through to the next throw, and the code after
    # it is not even a block of its own: that is what main rendered as running next.
    kept, _e = build_cfg(ann, traps=TRAPS)
    assert kept[0x4].succ == [0x8] and not kept[0x4].ends_path
    assert 0xc not in kept
    # Each arm throws, nothing is printed under either, and the tail nothing reaches is
    # still there under its own label, and under the note that says so (#266).
    from jadart.cfg import UNREACHED
    assert [ln.strip() for ln in lift_function(ann)] == [
        "if (x0 != 0) {", "throw NullCastError();", "} else {",
        "throw NullCastError();", "}", "// " + UNREACHED, "L_0xc:", "return 1;"]


def test_the_null_test_chain_that_found_the_false_edge_reads_as_source():
    """`FocusTraversalPolicy.next` on the clean fixture, which is the shape #234 names.

    The compiler lays out three one-instruction blocks, each a `bl` to the null-cast-error
    stub, so the arms of three null tests can branch into them. With the fall-through kept,
    the lift printed the last as `throw NullCastError(); goto L_0x12c928;`, a jump out of a
    throw, and the two `if`s above it lost their else arms to the edge. Nothing in the
    range changes but the edges, so the whole body is pinned here."""
    if not _capstone_available() or not os.path.exists(CLEAN):
        _skip("  SKIP test_the_null_test_chain_that_found_the_false_edge_reads_as_source")
    from jadart.disasm import (load_instructions, disassemble_range,
                               function_name_by_pc, build_pool_map)
    from jadart.expr import lift_function, make_arity_resolver
    image, fr, _ = load_instructions(CLEAN)
    cr = next(c for c in image.all_ranges if c.pc_offset == 0x12c8bc)
    dis = disassemble_range(image, cr)
    body = [ln.rstrip() for ln in lift_function(
        _ann(image, dis, function_name_by_pc(image, fr), build_pool_map(fr)),
        build_pool_map(fr), arity=make_arity_resolver(image))]
    assert body == [
        "  if (THR.field_0x78.field_0xad1 != NULL) {",
        "    if (THR.field_0x78.field_0xad1.field_0xf0 != NULL) {",
        "      if (THR.field_0x78.field_0xad1.field_0xf0.field_0x14.field_0x2c != NULL) {",
        "        return nextFocus(THR.field_0x78.field_0xad1.field_0xf0.field_0x14"
        ".field_0x2c);",
        "      } else {",
        "        throw NullCastError();",
        "      }",
        "    } else {",
        "      throw NullCastError();",
        "    }",
        "  } else {",
        "    throw NullCastError();",
        "  }"], body


def test_the_object_store_root_run_ends_where_the_dispatch_table_begins():
    """The binary's own confirmation of the root count.

    The count comes from a generated table (tools/gen_objstore.py), so something has to
    check it against the binary. After `count` refs and the two initial-field tables the
    stream must be exactly at the dispatch table, which `dispatch.find_dispatch_table`
    locates from an unrelated invariant: the varint after the table length is the Code
    cluster's first ref id. Two independent anchors agreeing is what makes the count a
    measurement rather than a transcription (#234)."""
    from jadart.disasm import load_instructions
    from jadart.dispatch import find_dispatch_table
    from jadart.stream import ReadStream
    for lib in (CLEAN, OBF):
        image, fr, hdr = load_instructions(lib)
        st = ReadStream(image.data, fr.end_pos)
        for _ in range(hdr.epoch.roots.count):
            st.read_ref_id()
        for _ in range(2):          # the initial field table, then the shared one
            for _ in range(st.read_unsigned()):
                st.read_ref_id()
        found = find_dispatch_table(image.data, fr.end_pos, image.data_length,
                                    fr.code_first_ref, len(image.pcs) + 1)
        assert found is not None, lib
        assert found[0] == st.pos, (lib, found[0], st.pos)


def test_a_root_layout_that_does_not_describe_the_binary_names_nothing():
    """Naming a stub after its neighbour is worse than leaving it `sub_0x...`, so a layout
    that does not fit refuses rather than guessing (#234).

    The hazard is a field inserted or dropped ahead of the stub block in a release the
    bundled table was not generated from: every later index shifts by one and each stub
    takes its neighbour's name. The layout says which roots are Code-typed, and the reader
    checks every one of them against the Code objects the fill pass recovered, so a shift
    lands a non-Code where a Code is declared and the whole map is dropped."""
    from types import SimpleNamespace
    from jadart.disasm import load_instructions
    from jadart.objstore import RootLayout, stub_names
    image, fr, hdr = load_instructions(CLEAN)
    real = hdr.epoch.roots
    assert len(stub_names(image, fr, SimpleNamespace(roots=real))) == 76
    shifted = RootLayout(count=real.count + 1,
                         stubs={i + 1: nm for i, nm in real.stubs.items()},
                         unnamed=frozenset(i + 1 for i in real.unnamed))
    claims_a_class = RootLayout(count=real.count, unnamed=real.unnamed,
                                stubs={**real.stubs, 0: "Throw"})
    for bad in (shifted, claims_a_class):
        assert stub_names(image, fr, SimpleNamespace(roots=bad)) == {}
    # and nothing to name with is not an error either: that is every epoch before #234
    assert stub_names(image, fr, None) == {}
    assert stub_names(image, fr, SimpleNamespace(roots=None)) == {}


def test_a_named_stub_agrees_with_what_its_body_does():
    """The one cross-check that reads the TEXT rather than the stream.

    A root index could still be mis-mapped by a release that replaced one Code field with
    another in place, where the count and the Code positions both still fit. The body says
    otherwise: a stub named as a throw cannot contain a `ret` (all 17 of them on each
    fixture have none), and one named as an allocation has to be able to return, by a
    `ret` or by the tail jump `AllocateUnhandledException` ends with. This is also the
    structural reading on its own terms, which is how Ghidra and LLVM decide a function
    cannot return, kept as a check here because it needs a disassembly (#234)."""
    if not _capstone_available():
        _skip("  SKIP test_a_named_stub_agrees_with_what_its_body_does (no capstone)")
    from jadart.disasm import load_instructions, disassemble_range
    from jadart.expr import _classify_stub
    from jadart.objstore import stub_names
    jumps = ("br", "braa", "brab", "braaz", "brabz")
    for lib in (CLEAN, OBF):
        image, fr, hdr = load_instructions(lib)
        ranges = {cr.pc_offset: cr for cr in image.all_ranges}
        seen = {}
        for pc, nm in sorted(stub_names(image, fr, hdr.epoch).items()):
            kind = _classify_stub(nm)[0]
            mns = [mn for _a, mn, _op in disassemble_range(image, ranges[pc])]
            seen[kind] = seen.get(kind, 0) + 1
            if kind in ("throw", "rethrow", "throw_err"):
                assert "ret" not in mns, (lib, nm, "named as a throw and it returns")
            if kind == "alloc":
                assert "ret" in mns or any(m in jumps for m in mns), (lib, nm)
        assert seen["throw_err"] == 15 and seen["throw"] == 1 and seen["rethrow"] == 1
        assert seen["alloc"] == 36, (lib, seen)


def test_tier3_renders_runtime_stubs_semantically_on_a_release_build():
    """The fixture half of the real-app test above, which a release build could not reach
    before #234: with no stub named, every one of these printed as a plain call, so the
    whole semantic rendering path had no test that ran in CI.

    Over the first 3,000 ranges of the clean fixture this is 1,705 `throw` and 886 `new`
    where main has none of either, and still no range leaking a raw `_iso_stub_` call."""
    if not _capstone_available():
        _skip("  SKIP test_tier3_renders_runtime_stubs_semantically_on_a_release_build")
    from jadart.disasm import (load_instructions, disassemble_range,
                               function_name_by_pc, build_pool_map)
    from jadart.expr import lift_function, make_arity_resolver
    image, fr, _ = load_instructions(CLEAN)
    p2n, pm, ar = function_name_by_pc(image, fr), build_pool_map(fr), \
        make_arity_resolver(image)
    leaked = throws = news = 0
    for cr in image.all_ranges[:3000]:
        dis = disassemble_range(image, cr)
        if not dis:
            continue
        body = "\n".join(lift_function(_ann(image, dis, p2n, pm), pm, arity=ar))
        if "_iso_stub_" in body:
            leaked += 1
        throws += body.count("throw ")
        news += body.count("new ")
    assert leaked == 0, f"{leaked} functions leaked a raw _iso_stub_ call"
    assert throws > 1000 and news > 500, (throws, news)


def test_tier3_attributes_virtual_dispatch():
    # benchCheckSecret is `return input == 'FLUBENCH...'`, an operator== dispatched through the
    # X21 dispatch table. Tier 3.3 attributes the call to the receiver + a stable selector offset
    # (sel_0x<off>) instead of an opaque (dynamic call).
    if not _capstone_available():
        _skip("  SKIP test_tier3_attributes_virtual_dispatch (no capstone)")
    from jadart.disasm import (load_instructions, disassemble_function,
                               function_name_by_pc, build_pool_map)
    from jadart.expr import lift_function, detect_dispatch, strip_boilerplate
    image, fr, _ = load_instructions(CLEAN)
    refs = [r for r, nr, ow, kt in fr.functions if fr.strings.get(nr) == "benchCheckSecret"]
    ann = _ann(image, disassemble_function(image, refs[0]),
               function_name_by_pc(image, fr), build_pool_map(fr))
    # detection recovers (receiver register, selector offset) for the dispatch blr
    d = detect_dispatch(strip_boilerplate(ann))
    assert d, "no X21 dispatch call detected in benchCheckSecret"
    recv, off = next(iter(d.values()))
    assert recv == "x1" and off is not None, f"receiver/offset not recovered: {(recv, off)}"
    # rendering: a receiver-attributed virtual call, not an opaque (dynamic call)
    body = "\n".join(lift_function(ann, build_pool_map(fr)))
    assert "x1.sel_0x" in body, "virtual dispatch not attributed to the receiver"
    assert "(dynamic call)" not in body


