def test_virtual_targets_are_filtered_by_the_defining_name():
    """`k = cid + selector_offset` is a PACKING: two (class, selector) pairs legitimately
    share a row, so walking every class id at one offset returns real implementations
    mixed with unrelated collisions. Unfiltered, the median selector came back with 370
    targets, which is nonsense for a method a few dozen classes override. Every real
    implementation carries the same method name, so the modal name is the selector."""
    if not _capstone_available():
        _skip("  SKIP test_virtual_targets_are_filtered_by_the_defining_name (no capstone)")
    from jadart.disasm import load_instructions
    from jadart.callgraph import build_index
    image, fr, _ = load_instructions(CLEAN)
    idx = build_index(image, fr)
    assert idx.sel_targets, "no selector resolved to any target"
    sizes = sorted(len(v) for v in idx.sel_targets.values())
    median = sizes[len(sizes) // 2]
    assert median <= 20, (
        f"median {median} targets per selector: the collision filter is not working")
    assert sizes[-1] < len(image.all_ranges) // 8, f"largest set is {sizes[-1]}"
    # A selector every implementation of which is one function resolves a virtual site
    # as precisely as a direct call, and those must exist in a real program.
    assert any(n == 1 for n in sizes), "no selector resolved to a single target"


def test_virtual_edges_stay_separate_from_direct_ones():
    """A direct edge is a fact and a virtual edge is a maybe. Merging them would let one
    toString site add eighty-odd edges indistinguishable from real calls."""
    if not _capstone_available():
        _skip("  SKIP test_virtual_edges_stay_separate_from_direct_ones (no capstone)")
    from jadart.disasm import load_instructions
    from jadart.callgraph import build_index
    image, fr, _ = load_instructions(CLEAN)
    idx = build_index(image, fr)
    direct = {(s, t) for s, ts in idx.callees.items() for t in ts}
    virtual = {(s, t) for s, ts in idx.may_call.items() for t in ts}
    assert virtual, "no virtual edges resolved at all"
    # the two views of the virtual relation must agree, as with the direct one
    back = {(s, t) for t, ss in idx.may_be_called_by.items() for s in ss}
    assert virtual == back, f"{len(virtual ^ back)} virtual edges appear on one side only"
    assert direct is not virtual
    # every blr is accounted for: attributed to a selector, or counted as opaque
    assert idx.virtual_sites + idx.opaque_sites == sum(idx.indirect.values())
    assert idx.opaque_sites >= 0


def test_one_name_builds_only_its_part_of_the_call_graph():
    """`functions -f NAME` and `xrefs function NAME` built the call graph of the whole
    image and kept one row of it: 5.80 and 5.41 s on an app of 88,618 ranges, where
    `symbols -f` answers the same name in 1.01 s. Counted rather than timed. The index a
    one-name query builds holds the edges that touch that name and no others, it decodes
    fewer ranges than the whole graph, and the counts it prints are the whole graph's."""
    _needs_capstone()
    import io
    import json
    import contextlib
    from jadart import cli, callgraph
    from jadart.disasm import load_instructions, function_name_by_pc

    image, fr, hdr = load_instructions(CLEAN)
    pc = next(p for p, nm in function_name_by_pc(image, fr).items()
              if nm == "benchWithdraw")
    whole = {f.pc_offset: f for f in callgraph.function_table(image, fr, hdr)[0]}[pc]

    built, decoded = [], [0]
    real_build, real_dis = callgraph.build_index, callgraph.disassemble_range

    def build(*a, **k):
        built.append(real_build(*a, **k))
        return built[-1]

    def dis(*a, **k):
        decoded[0] += 1
        return real_dis(*a, **k)

    def run(*argv):
        built.clear()
        decoded[0] = 0
        out = io.StringIO()
        callgraph.build_index, callgraph.disassemble_range = build, dis
        try:
            with contextlib.redirect_stdout(out):
                rc = cli.main([*argv, "-j"])
        finally:
            callgraph.build_index, callgraph.disassemble_range = real_build, real_dis
        assert rc == 0 and len(built) == 1, (rc, len(built))
        return json.loads(out.getvalue()), built[0], decoded[0]

    _doc, _idx, all_decodes = run("functions", CLEAN, "-n", "1")
    for argv in (("functions", CLEAN, "-f", "benchWithdraw"),
                 ("xrefs", CLEAN, "function", "benchWithdraw")):
        doc, idx, decodes = run(*argv)
        edges = ([(s, t) for t, ss in idx.callers.items() for s in ss]
                 + [(s, t) for s, ts in idx.callees.items() for t in ts]
                 + [(s, t) for t, ss in idx.may_be_called_by.items() for s in ss])
        assert edges and all(pc in e for e in edges), (
            f"{argv[0]}: {sum(pc not in e for e in edges)} of {len(edges)} edges in the "
            f"index do not touch benchWithdraw")
        assert decodes < all_decodes, (argv[0], decodes, all_decodes)
        if argv[0] == "functions":
            (row,) = doc["functions"]
            assert (row["callers"], row["callees"], row["indirect"],
                    row["virtual_callers"], row["overloads"]) == (
                whole.callers, whole.callees, whole.indirect, whole.virtual_callers,
                whole.overloads), row
        else:
            (fn,) = doc["functions"]
            assert len(fn["called_by"]) == whole.callers, fn


def test_xrefs_names_each_reference_the_way_functions_does():
    """`xrefs` printed a reference as an address and a size, `0x23b720  168 bytes`, and
    left the reader to look each one up. Every reference now carries the name `functions`
    gives its range and the class that owns it, in the text and in `-j`, and a range with
    no name still prints as its address alone."""
    _needs_capstone()
    import io
    import json
    import contextlib
    from jadart import cli, callgraph
    from jadart.disasm import load_instructions

    image, fr, hdr = load_instructions(CLEAN)
    label = {f.pc_offset: f.name for f in callgraph.function_table(image, fr, hdr)[0]}

    def run(*argv):
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            assert cli.main(list(argv)) == 0, argv
        return out.getvalue()

    refs = [r for e in json.loads(run("xrefs", CLEAN, "string", "Bench", "-j"))["entries"]
            for r in e["referenced_by"]]
    doc = json.loads(run("xrefs", CLEAN, "function", "benchWithdraw", "-j"))
    (fn,) = doc["functions"]
    refs += fn["called_by"]
    assert refs and all("name" in r and "class" in r for r in refs), refs[0]
    assert [r["name"] for r in refs] == [label[r["pc_offset"]] for r in refs], refs
    build = next(r for r in refs if r["name"] == "build" and r["class"] == "FluBenchApp")

    text = run("xrefs", CLEAN, "string", "Bench")
    line = next(ln for ln in text.splitlines() if f"{build['size']} bytes" in ln)
    assert line.rstrip().endswith("  FluBenchApp.build"), line
    assert "  benchRunAll" in run("xrefs", CLEAN, "function", "benchWithdraw")

    anon = next(pc for pc, nm in label.items() if not nm)
    assert cli._ref_line(image, {"pc_offset": anon, "size": 4, "name": "",
                                 "class": ""}).rstrip().endswith("4 bytes")


