def test_overlapping_tables_cannot_make_a_container_cost_more_than_its_size(tmp_path):
    # A name, a symbol table and a segment's sections are each found by an offset or a
    # count the file gives, and nothing stops them from overlapping (#95). One long name
    # with a symbol at each of its bytes kept 200M characters from a 500 KB ELF, 2,000
    # section headers on one symbol table read it 2,000 times, and a 304 KB Mach-O made
    # 4M sections out of 2,000 load commands. Tables that do not overlap cannot cost
    # more than the file has bytes, so each kind is refused past that, as a
    # ContainerError, and a symbol on a name offset already read is skipped.
    import contextlib
    import io
    import json
    import struct as _s
    from jadart import cli
    from jadart.errors import ContainerError
    from jadart.macho import open_container

    def elf(strtab, syms, tables=1, bits=64, shstr=b"\x00", table_names=None,
            stride=None, also=()):
        # the section names, the symbol names, `tables` symbol tables that all read the
        # one run of entries, `stride` bytes apart, and for each of `also` a string
        # table and a symbol table of its own
        if bits == 64:
            eh, sh, shfmt, ent = 64, 64, "<IIQQQQIIQQ", 24
            pack = lambda n, v: _s.pack("<IBBHQQ", n, 0, 0, 0, v, 4)    # noqa: E731
        else:
            eh, sh, shfmt, ent = 52, 40, "<IIIIIIIIII", 16
            pack = lambda n, v: _s.pack("<IIIBBH", n, v, 4, 0, 0, 0)    # noqa: E731
        gap = b"\x00" * ((stride or ent) - ent)
        blobs, heads = [], []
        at = eh + (2 + tables + 2 * len(also)) * sh

        def put(blob):
            nonlocal at
            blobs.append(blob)
            at += len(blob)
            return at - len(blob)

        heads.append((0, 3, put(shstr), len(shstr), 0, 0))
        heads.append((0, 3, put(strtab), len(strtab), 0, 0))
        run = gap.join(pack(n, v) for n, v in syms)
        where = put(run)
        for i in range(tables):
            heads.append(((table_names or [0] * tables)[i], 2, where,
                          len(syms) * (stride or ent), 1, stride or ent))
        for st, sy in also:
            heads.append((0, 3, put(st), len(st), 0, 0))
            run = b"".join(pack(n, v) for n, v in sy)
            heads.append((0, 11, put(run), len(run), len(heads) - 1, ent))
        h = bytearray(eh)
        h[0:7] = b"\x7fELF" + bytes([2 if bits == 64 else 1, 1, 1])
        if bits == 64:
            _s.pack_into("<Q", h, 0x28, eh)
            _s.pack_into("<HHH", h, 0x3A, sh, len(heads), 0)
        else:
            _s.pack_into("<I", h, 0x20, eh)
            _s.pack_into("<HHH", h, 0x2E, sh, len(heads), 0)
        return (bytes(h) + b"".join(_s.pack(shfmt, nm, ty, 0, 0, off, size, link, 0, 0,
                                            es)
                                    for nm, ty, off, size, link, es in heads)
                + b"".join(blobs))

    def macho(strtab, syms, tables=1, segments=(), also=()):
        # `segments` load commands of 72 bytes each claiming that many sections, which
        # are read out of whatever follows, `tables` LC_SYMTABs on one run of entries,
        # and for each of `also` an LC_SYMTAB with a string table of its own
        cmds = b""
        for nsects in segments:
            c = bytearray(72)
            _s.pack_into("<II", c, 0, 0x19, 72)
            _s.pack_into("<I", c, 64, nsects)
            cmds += bytes(c)
        at = 32 + len(cmds) + 24 * (tables + len(also))
        rest = b""
        for st, sy, times in [(strtab, syms, tables)] + [(st, sy, 1) for st, sy in also]:
            where = at + len(rest)
            cmds += _s.pack("<IIIIII", 2, 24, where + len(st), len(sy), where,
                            len(st)) * times
            rest += st + b"".join(_s.pack("<IBBHQ", n, 0x0E, 1, 0, v) for n, v in sy)
        h = _s.pack("<IiiIIIII", 0xFEEDFACF, 0x0100000C, 0, 6,
                    len(segments) + tables + len(also), len(cmds), 0, 0)
        return h + cmds + rest + b"\x00" * (80 * max(segments, default=0))

    def refused(data, what):
        try:
            c = open_container(data)
        except ContainerError as e:
            assert str(e).startswith(f"{what} overlap: "), e
            # refused at the file's size, by the one read that went past it
            total, size = map(int, re.search(r"came to (\d+) bytes in a (\d+) byte file",
                                             str(e)).groups())
            assert size == len(data) < total <= size + 80 * 200, e
            return
        raise AssertionError(f"{len(data)} byte file read to {len(c.symbols)} symbols, "
                             f"{sum(map(len, c.symbols))} characters of names, "
                             f"{len(c.sections)} sections: {what} not refused")

    long = b"A" * 4000
    names, tables, sections = ("names in the string tables", "symbol tables",
                               "section headers")
    # a symbol at every byte of one name, in either ELF class and in Mach-O
    one_name_each_byte = [(1 + i, 0x1000 + i) for i in range(len(long))]
    refused(elf(b"\x00" + long + b"\x00", one_name_each_byte), names)
    refused(elf(b"\x00" + long + b"\x00", one_name_each_byte, bits=32), names)
    # ahead of them a Mach-O symbol whose name starts past its table, which reads
    # nothing and must not be charged less than nothing to make room
    refused(macho(b"\x00" + long + b"\x00", [(0xFFFF0000, 0x1000)] + one_name_each_byte),
            names)
    # with no NUL in the table no Mach-O name is kept, and each scan still costs
    refused(macho(b"\x00" + long, one_name_each_byte), names)
    # section names are read from offsets too
    refused(elf(b"\x00", [], tables=2000, shstr=b"\x00" + long + b"\x00",
                table_names=[1 + i for i in range(2000)]), names)
    # many headers on one symbol table, in both containers
    short = b"\x00" + b"".join(b"s%d\x00" % i for i in range(500))
    starts = [1 + sum(len(b"s%d" % j) + 1 for j in range(i)) for i in range(500)]
    syms = [(at, 0x1000 + i) for i, at in enumerate(starts)]
    refused(elf(short, syms, tables=200), tables)
    refused(macho(short, syms, tables=200), tables)
    # load commands that claim sections they do not hold
    refused(macho(b"\x00", [], tables=0, segments=[200] * 200), sections)

    # The limit is the file's size: a file whose names come to exactly that is read.
    few = elf(b"\x00" + long + b"\x00", one_name_each_byte[:10])
    spent = open_container(few + bytes(10 ** 5))._budget.spent[names]
    assert open_container(few + bytes(spent - len(few)))._budget.spent[names] == spent
    refused(few + bytes(spent - 1 - len(few)), names)

    # A table that runs past the end of the file says so, where it did not overlap
    # anything; one whose last entry ends where the file does is read, as it always was.
    data = bytearray(elf(short, syms))
    _s.pack_into("<Q", data, 64 + 2 * 64 + 32, 10 ** 6)        # the table's sh_size
    with pytest.raises(ContainerError, match="past the end of the file"):
        open_container(bytes(data))
    data = bytearray(elf(short, syms))          # no whole entry, so nothing read
    _s.pack_into("<QQ", data, 64 + 2 * 64 + 24, 10 ** 9, 8)    # sh_offset, sh_size
    assert open_container(bytes(data)).symbols == {}
    data = elf(short, syms, stride=32)          # the last 8 bytes of padding not there
    c = open_container(data)
    assert len(c.symbols) == 500 and c._budget.spent[tables] == 500 * 24  # bytes read
    data = macho(b"", [], tables=0, segments=[1])[:32 + 72 + 52]
    assert [s.name for s in open_container(data).sections] == [","]
    with pytest.raises(ContainerError, match="past the end of the file"):
        open_container(data[:-1])
    # a Mach-O string table said to run on past the file, with no NUL in it: the scan
    # stops at the end of the file, and so does what it is charged
    at = 32 + 24
    c = open_container(_s.pack("<IiiIIIII", 0xFEEDFACF, 0x0100000C, 0, 6, 1, 24, 0, 0)
                       + _s.pack("<IIIIII", 2, 24, at, 1, at + 16, 10 ** 6)
                       + _s.pack("<IBBHQ", 1, 0x0E, 1, 0, 0x1000) + b"\x00" + b"A" * 100)
    assert c.symbols == {} and c._budget.spent[names] == 100
    # a Mach-O symbol table runs on past the file and is read as far as it goes
    data = bytearray(macho(short, syms))
    _s.pack_into("<I", data, 32 + 12, 0xFFFFFFFF)          # nsyms
    assert len(open_container(bytes(data)).symbols) == 500

    # Every symbol on one offset is one name, read and charged once, and costs nothing
    # after: the lookups for every symbol on it cost its length each, so they are not
    # made. In Mach-O its `_` alias too, and in either one a second copy of the name.
    for build, under in ((elf, b""), (macho, b"_")):
        twice = b"\x00" + under + long + b"\x00" + under + long + b"\x00"
        second = 1 + len(under) + len(long) + 1
        c = open_container(build(twice, [(1, 0x1000)] + [(second, 0x1000)] * 4000))
        assert sorted(map(len, c.symbols)) == [4000, 4001][:1 + len(under)], build
        # each name and its NUL, and in the ELF the empty section name's NUL; and every
        # byte of the entries
        assert c._budget.spent == {names: 2 * (len(under) + 4001) + (build is elf),
                                   tables: 4001 * (24 if build is elf else 16)}, build
    # and a name offset is a file offset: two tables can each have a name at 1
    for build in (elf, macho):
        c = open_container(build(b"\x00foo\x00", [(1, 0x10)],
                                 also=[(b"\x00bar\x00", [(1, 0x20)])]))
        assert {n: s.value for n, s in c.symbols.items()} == {"foo": 0x10, "bar": 0x20}

    # A real build is nowhere near: the fixtures name a few hundred bytes. 4,537 ELF and
    # Mach-O files measured came to at most 0.45 of the file for names, 0.68 for tables.
    for lib in (CLEAN, OBF):
        with open(lib, "rb") as f:
            d = f.read()
        c = open_container(d)
        assert sorted(c.symbols) == ["_kDartIsolateSnapshotData",
                                     "_kDartIsolateSnapshotInstructions",
                                     "_kDartSnapshotBuildId", "_kDartVmSnapshotData",
                                     "_kDartVmSnapshotInstructions"]
        assert [s.name for s in c.sections] == [
            "", ".note.gnu.build-id", ".dynstr", ".dynsym", ".hash", ".rodata",
            ".eh_frame", ".text", ".dynamic", ".bss", ".shstrtab"]
        assert c._budget.spent == {names: 222, tables: 144}

    # The extent of a Mach-O snapshot blob looked its section up again for every
    # boundary symbol, which cost symbols times sections. Now two lookups however
    # many, the blob's own and the one for its file offset.
    many = b"\x00_kDartIsolateSnapshotData\x00"
    syms = [(1, 0x100000)]
    for i in range(300):
        syms.append((len(many), 0x100001 + 299 - i))   # each one nearer, so each counts
        many += b"_kDartX%d\x00" % i
    seg = bytearray(152)                 # one segment, one section at 0x100000
    _s.pack_into("<II", seg, 0, 0x19, 152)
    _s.pack_into("<I", seg, 64, 1)
    seg[72:74] = b"s\x00"
    _s.pack_into("<QQI", seg, 72 + 32, 0x100000, 0x100000, 64)
    at = 32 + 152 + 24
    m = open_container(
        _s.pack("<IiiIIIII", 0xFEEDFACF, 0x0100000C, 0, 6, 2, 152 + 24, 0, 0) + bytes(seg)
        + _s.pack("<IIIIII", 2, 24, at + len(many), len(syms), at, len(many)) + many
        + b"".join(_s.pack("<IBBHQ", n, 0x0E, 1, 0, v) for n, v in syms))
    looked = []
    find = m._section_of
    m._section_of = lambda va: looked.append(va) or find(va)
    assert m.symbol_bytes("_kDartIsolateSnapshotData") == m.data[64:65]
    assert len(looked) == 2, f"{len(looked)} section lookups for one blob"

    # and through the command line, a typed failure that says what overlapped
    path = tmp_path / "overlap.so"
    path.write_bytes(elf(b"\x00" + long + b"\x00", one_name_each_byte))
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        assert cli.main(["info", str(path), "-j"]) == 2
    doc = json.loads(buf.getvalue())
    assert doc["type"] == "ContainerError" and doc["error"].startswith(names), doc


def test_the_magic_scan_refuses_more_snapshots_than_a_library_holds(
        tmp_path, monkeypatch):
    # A binary with no _kDart*SnapshotData symbols is read by scanning for the snapshot
    # magic, and each hit was parsed out of a copy of the rest of the file: a file of
    # small headers cost hits times its size, 9.7s for 16 MB and four times that for
    # each doubling, and `info` listed every one (#99). A library holds two snapshots at
    # most, the vm and the isolate one.
    import contextlib
    import dataclasses
    import io
    import json
    from jadart import cli
    from jadart import snapshot
    from jadart.elf import Elf, find_magic
    from jadart.macho import MachO64, open_container
    from jadart.stream import ReadStream

    d = open(CLEAN, "rb").read()
    real = parse_libapp(CLEAN)

    # The fixture with its section headers gone has no symbols to find the snapshots by,
    # and the scan finds the same two headers they name.
    bare = bytearray(d)
    struct.pack_into("<HHH", bare, 0x3A, 0, 0, 0)
    path = tmp_path / "stripped.so"
    path.write_bytes(bare)
    got = parse_libapp(str(path))
    assert list(got) == ["blob0", "blob1"]
    assert dataclasses.replace(got["blob0"], which="vm") == real["vm"]
    assert dataclasses.replace(got["blob1"], which="isolate") == real["isolate"]

    # The fixture's vm header up to its counts, the five counts zero, and a length that
    # is its own size, so a copy of it is a whole snapshot header on its own.
    vm = Elf(d).symbol_bytes("_kDartVmSnapshotData")
    st = ReadStream(vm, 52)
    st.read_cstring()
    hdr = bytearray(vm[:st.pos]) + bytes([0x80] * 5)
    struct.pack_into("<q", hdr, 4, len(hdr))
    hdr = bytes(hdr)

    def elf(body):
        eh = bytearray(64)
        eh[0:4] = b"\x7fELF"; eh[4] = 2; eh[5] = 1; eh[6] = 1
        return bytes(eh) + body             # no section headers, so no symbols

    def macho(body):
        mh = struct.pack("<IiiIIIII", 0xFEEDFACF, 0x0100000C, 0, 6, 0, 0, 0, 0)
        return mh + body                    # no load commands, so no symbols

    calls, asked = [], []
    real_parse = snapshot.parse_blob

    def counted(blob, which, **kw):
        calls.append(which)
        return real_parse(blob, which, **kw)

    monkeypatch.setattr(snapshot, "parse_blob", counted)
    # The scan has to be asked for three, not made to find them all and cut to three:
    # that refused the same files and still took a file of nothing but the magic to
    # 396 MB.
    for cls in (Elf, MachO64):
        def scan(self, limit=None, real=cls.find_snapshot_magic):
            asked.append(limit)
            return real(self, limit)
        monkeypatch.setattr(cls, "find_snapshot_magic", scan)

    magic = struct.pack("<I", 0xDCDCF5F5)
    for build, at in ((elf, 64), (macho, 32)):
        # Two are what a library holds, and read as before.
        path.write_bytes(build(hdr * 2))
        calls.clear(); asked.clear()
        got = parse_libapp(str(path))
        assert list(got) == ["blob0", "blob1"] and calls == ["blob0", "blob1"]
        assert asked == [3]
        for h in got.values():
            assert (h.length, h.version_hash, h.features, h.num_objects) == (
                len(hdr), real["vm"].version_hash, real["vm"].features, 0)
        # and a release nothing has vetted is refused unless asked to be lenient
        unknown = hdr[:20] + b"0" * 32 + hdr[52:]
        path.write_bytes(build(unknown * 2))
        with pytest.raises(UnknownEpoch):
            parse_libapp(str(path))
        assert [h.epoch for h in parse_libapp(str(path), strict=False).values()] == [
            None, None]

        # A third is refused before any is parsed, and the scan stops at it.
        # Nothing but the magic, one every four bytes, is refused at the third as well.
        for body, step in ((hdr * 3, len(hdr)), (hdr * 2000, len(hdr)),
                           (magic * 1000, 4)):
            path.write_bytes(build(body))
            calls.clear(); asked.clear()
            with pytest.raises(jadart.InputError) as e:
                parse_libapp(str(path))
            offs = ", ".join(hex(at + i * step) for i in range(3))
            assert f"magic is at 3 or more file offsets ({offs}). " in str(e.value)
            assert calls == [], f"{len(calls)} headers parsed before refusing"
            assert asked == [3]
            assert open_container(path.read_bytes()).find_snapshot_magic(3) == [
                at + i * step for i in range(3)]

    # The scan itself holds only what it is asked for.
    assert find_magic(magic * 1000, 3) == [0, 4, 8]
    assert find_magic(magic * 1000) == list(range(0, 4000, 4))
    assert find_magic(b"\x00" + magic * 2, 3) == [1, 5]
    assert find_magic(b"", 3) == []
    for build in (elf, macho):
        assert open_container(build(magic * 1000)).find_snapshot_magic(limit=3) == [
            len(build(b"")) + i for i in (0, 4, 8)]

    # and through the command line, a typed failure that says why
    path.write_bytes(elf(hdr * 3))
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        assert cli.main(["info", str(path), "-j"]) == 2
    doc = json.loads(buf.getvalue())
    assert doc["type"] == "InputError" and "A Flutter library holds at most 2 " in (
        doc["error"]), doc


def test_a_features_string_is_read_only_as_long_as_a_real_one_can_be(tmp_path):
    # The features string was read to its NUL however far away that was, kept whole and
    # given to `info -j` whole: a 16.8 MB file of two headers whose features were the real
    # flags and 8 MB of 0xff each printed 100 MB of JSON, every byte a six-character
    # escape (#101). A real one from an AOT build is under 160 bytes; past 4096 it is
    # refused.
    import contextlib
    import io
    import json
    from jadart import cli
    from jadart.elf import Elf
    from jadart.stream import ReadStream

    d = open(CLEAN, "rb").read()
    vm = Elf(d).symbol_bytes("_kDartVmSnapshotData")
    st = ReadStream(vm, 52)
    feat = st.read_cstring().encode()
    assert len(feat) < 200

    def header(features):
        h = bytearray(vm[:52]) + features + b"\x00" + bytes([0x80] * 5)
        struct.pack_into("<q", h, 4, len(h))
        return bytes(h)

    real = parse_blob(vm, "vm")
    # 4096 bytes of features is read, the real flags first so the target still resolves
    longest = feat + b" " + b"x" * (4096 - len(feat) - 1)
    got = parse_blob(header(longest), "vm")
    assert got.features == longest.decode() and got.epoch == real.epoch
    # one more is refused, whether it ends later or never does
    for blob in (header(longest + b"x"), header(feat + b" " + b"\xff" * (1 << 20)),
                 vm[:52] + b"\xff" * (1 << 20)):
        with pytest.raises(jadart.InputError) as e:
            parse_blob(blob, "vm")
        assert str(e.value).startswith("vm: the features string is longer than 4096 ")
    # A header that ends with no NUL is truncated, as before, unless it ran past the bound
    # first: 4096 bytes and the end of the blob is the one, 4097 the other.
    for n, said in ((100, "unterminated C-string"), (4096, "unterminated C-string"),
                    (4097, "is longer than 4096 bytes")):
        short = bytearray(vm[:52]) + b"x" * n
        struct.pack_into("<q", short, 4, len(short))
        with pytest.raises(jadart.JadartError) as e:
            parse_blob(bytes(short), "vm")
        assert said in str(e.value), (n, str(e.value))

    # and through the command line, on a stripped ELF holding two such headers
    def elf(body):
        eh = bytearray(64)
        eh[0:4] = b"\x7fELF"; eh[4] = 2; eh[5] = 1; eh[6] = 1
        return bytes(eh) + body

    path = tmp_path / "long.so"
    for features, rc in ((feat, 0), (feat + b" " + b"\xff" * (1 << 20), 2)):
        path.write_bytes(elf(header(features) * 2))
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            assert cli.main(["info", str(path), "-j"]) == rc
        doc = json.loads(buf.getvalue())
        assert len(buf.getvalue()) < 10_000, len(buf.getvalue())
        if rc:
            assert doc["type"] == "InputError" and "4096 bytes" in doc["error"], doc
        else:
            assert doc["snapshots"]["blob0"]["features"] == feat.decode()
    # The fixtures' own read as before.
    assert parse_libapp(CLEAN)["vm"].features == feat.decode()


def test_export_gives_every_library_a_file_of_its_own(tmp_path, monkeypatch):
    # A library url is text out of the snapshot, and export wrote each one where its url
    # said. Two could be one file: obfuscation names libraries `Ahd` and `ahd`, one file
    # on macOS and Windows, and the obfuscated fixture lost 99 of its 307 libraries to
    # that without a word. One could need for a file what another needs as a directory,
    # which ended the export with exit 3, and so did a url nested past what the OS takes
    # in one path. An output directory it cannot write was exit 3 as well (#96).
    import contextlib
    import errno
    import importlib
    import io
    import json
    import unicodedata
    from jadart import cli
    # the modules, not the API functions the package exports under the same names
    ex = importlib.import_module("jadart.export")
    program = importlib.import_module("jadart.program")

    up = ex.unique_paths
    j = os.path.join
    # a file where another library needs a directory gives way, whatever the order
    for rels in ([j("zz", "foo.dart"), j("zz", "foo.dart", "bar.dart")],
                 [j("zz", "foo.dart", "bar.dart"), j("zz", "foo.dart")]):
        bar = j("zz", "foo.dart", "bar.dart")
        assert up(rels) == {j("zz", "foo.dart"): j("zz", "foo~2.dart"), bar: bar}
    # and one where a library deeper down needs a directory, not only the next one down
    assert up([j("zz", "foo.dart"), j("zz", "foo.dart", "x", "y.dart")])[
        j("zz", "foo.dart")] == j("zz", "foo~2.dart")
    # so does one that differs from a directory only in case
    got = up([j("zz", "Foo.dart"), j("zz", "foo.dart", "x.dart")])
    assert got[j("zz", "Foo.dart")] == j("zz", "Foo~2.dart")
    got = up([j("zz", "foo.dart"), j("zz", "FOO.dart", "x.dart")])
    assert got[j("zz", "foo.dart")] == j("zz", "foo~2.dart")
    # case and composition: the first in sorted order keeps its name, and a new name is
    # never one a library has already
    assert up(["Ahd.dart", "ahd.dart"]) == {"Ahd.dart": "Ahd.dart",
                                            "ahd.dart": "ahd~2.dart"}
    assert up(["a.dart", "A.dart", "a~2.dart"]) == {
        "A.dart": "A.dart", "a.dart": "a~3.dart", "a~2.dart": "a~2.dart"}
    nfc, nfd = "caf\u00e9.dart", "cafe\u0301.dart"
    assert unicodedata.normalize("NFC", nfd) == nfc
    assert sorted(up([nfc, nfd]).values()) == sorted([nfd, "caf\u00e9~2.dart"])
    assert up(["x"]) == {"x": "x"} and up(["x", "X"])["x"] == "x~2"
    # Composed, these two fold apart; APFS holds them one file, as the canonical caseless
    # match does.
    greek = ["\u0391\u0342\u0345.dart", "\u0391\u0342\u0399.dart"]
    # and two orders of one pair of marks are one name too, which only the inner NFD sees
    marks = ["\u0391\u0345\u0342.dart", "\u0391\u0342\u0345.dart"]
    assert up(marks)[marks[0]] == "\u0391\u0345\u0342~2.dart"
    assert up(greek) == {greek[0]: greek[0], greek[1]: "\u0391\u0342\u0399~2.dart"}
    # nor a directory another library needs
    got = up([j("zz", "Foo.dart"), j("zz", "foo.dart"), j("zz", "foo~2.dart", "x.dart")])
    assert got[j("zz", "foo.dart")] == j("zz", "foo~3.dart")
    # Every case spelling of one name: each gets a file, and the numbering counts on
    # rather than trying every number again for each, which was quadratic.
    import itertools
    cases = [(c, c.upper()) for c in "abcdefghijkl"]
    spell = ["".join(c) + ".dart" for c in itertools.product(*cases)]
    folds = []
    real_fold = ex._fold
    monkeypatch.setattr(ex, "_fold", lambda r: folds.append(r) or real_fold(r))
    got = up(spell)
    monkeypatch.undo()
    assert len({real_fold(p) for p in got.values()}) == len(spell) == 4096
    assert len(folds) < 8 * len(spell), f"{len(folds)} folds for {len(spell)} paths"

    # One component is cut to 120 bytes of UTF-8 on a character, a path to 400 bytes by
    # its deepest directories, and a lone surrogate, which no filesystem names a file
    # with, is replaced like any other character a filename cannot hold.
    # (100 characters, under the cap, but 400 bytes)
    wide = ex.library_path("package:zz/" + "\U0001d538" * 100)
    head, name = wide.split(os.sep)
    assert head == "zz" and 115 < len(name.encode()) < 120
    # a cut that ends on a dot loses it, as Windows would
    assert ex.library_path("package:zz/" + "a" * 119 + ".b" * 20) == j("zz", "a" * 119)
    dirs = [f"d{i:02d}" + "x" * 27 for i in range(40)]
    deep = ex.library_path("package:" + "/".join(dirs) + "/x.dart")
    parts = deep.split(os.sep)
    assert 400 - 31 < len(deep.encode()) <= 400 and parts[-1] == "x.dart"
    assert parts[:-1] == dirs[:len(parts) - 1]
    assert ex.library_path("package:zz/a\ud800b") == j("zz", "a_b.dart")
    # A Windows device name is still caught where the cut leaves one bare, as a file or
    # as a directory; a file's own name that comes to nothing is `unnamed.dart`, not the
    # directory above it; and a path goes no more than 16 directories down.
    assert ex.library_path("package:zz/nul" + " " * 117 + "x" * 10) == j("zz", "_nul")
    assert ex.library_path("package:aux" + " " * 120 + "x/y") == j("_aux", "y.dart")
    for dev in ("com0", "lpt0", "com\u00b9", "lpt\u00b3"):
        assert ex.library_path("package:zz/" + dev) == j("zz", "_" + dev + ".dart")
    assert ex.library_path("package:zz/" + "." * 130 + "x") == j("zz", "unnamed.dart")
    assert ex.library_path("package:" + "d/" * 40 + "x").count(os.sep) == 16

    # An output directory on a drive or a share that is not there, where dirname of its
    # root is the root itself, forever
    with monkeypatch.context() as m:
        m.setattr(ex.os.path, "lexists", lambda p: False)
        with pytest.raises(jadart.InputError) as e:
            ex._check_outdir(str(tmp_path / "gone" / "out"))
        assert "does not exist" in str(e.value)

    _needs_capstone()                     # from here on the fixture is read and lifted
    # The same through `export`, with library urls of the clean fixture renamed to these.
    crafted = {"_unattributed": "named so",
               "package:zz/foo": "foo", "package:zz/foo.dart/bar": "bar",
               "package:zz/Case": "Case", "package:zz/case": "case",
               "package:" + "d/" * 600 + "deep": "deep",
               "package:zz/" + "\U0001d538" * 100: "wide"}
    real_libraries = program.Program.libraries

    def libraries(self):
        libs = real_libraries(self)
        mine = sorted(u for u in libs if u.startswith("package:") and "flutter" not in u)
        assert len(mine) > len(crafted)
        for old, new in zip(mine, crafted):
            libs[new] = libs.pop(old)
        # and one more left out, so its classes have no library
        del libs[mine[len(crafted)]]
        return libs

    monkeypatch.setattr(program.Program, "libraries", libraries)

    def run(out, *more):
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            rc = cli.main(["export", CLEAN, "-t", "1", "-q", "-o", str(out), "-j", *more])
        return rc, json.loads(buf.getvalue())

    out = tmp_path / "out"
    rc, doc = run(out)
    assert rc == 0, doc
    files = doc["files"]
    on_disk = [os.path.relpath(j(d, f), out / "sources")
               for d, _, fs in os.walk(out / "sources") for f in fs]
    assert sorted(on_disk) == sorted(files) and len(files) == doc["libraries"]
    assert len({ex._fold(f) for f in files}) == len(files)
    assert doc["renamed"] == {j("zz", "foo.dart"): j("zz", "foo~2.dart"),
                              j("zz", "case.dart"): j("zz", "case~2.dart")}
    for want, rel in doc["renamed"].items():
        head = (out / "sources" / rel).read_text().split("\n")[1]
        assert head == "// lib: package:zz/" + want[3:-5], head
    summary = (out / "summary.txt").read_text()
    assert "renamed     2 library files" in summary
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        rc = cli.main(["export", CLEAN, "-t", "1", "-q", "-o", str(tmp_path / "t")])
    assert rc == 0
    assert "2 renamed so that each has a file of its own" in buf.getvalue()
    # A library named `_unattributed` keeps its classes, and the classes with no library
    # go beside it, where the summary says.
    assert "went to sources/_unattributed_2.dart" in summary
    named_so = (out / "sources" / "_unattributed.dart").read_text().split("\n")[1]
    assert named_so == "// lib: _unattributed"
    assert (out / "sources" / "_unattributed_2.dart").read_text().split("\n")[1] == (
        "// lib: _unattributed~2")
    # `-a` writes the app's own libraries only, and says so rather than naming a file
    rc, doc = run(tmp_path / "app", "-a")
    summary = (tmp_path / "app" / "summary.txt").read_text()
    assert rc == 0, doc
    assert "had no library and are left out with the framework (-a)" in summary
    assert not (tmp_path / "app" / "sources" / "_unattributed_2.dart").exists()
    assert f"{j('zz', 'case.dart')} -> {j('zz', 'case~2.dart')}" in summary

    # An output directory that cannot be one is refused before the binary is read, and
    # one that cannot be written is the same InputError when it is found.
    from jadart import disasm
    loaded = []
    real_load = disasm.load_instructions
    monkeypatch.setattr(disasm, "load_instructions",
                        lambda *a, **k: loaded.append(a) or real_load(*a, **k))
    a_file = tmp_path / "a_file"
    a_file.write_text("x")
    for bad, why in ((a_file, "is not a directory"),
                     (a_file / "x" / "y", "a_file is not")):
        loaded.clear()
        rc, doc = run(bad)
        assert rc == 2 and doc["type"] == "InputError" and why in doc["error"], doc
        assert doc["error"].startswith(f"{bad}: ") and loaded == [], doc
    if os.geteuid() != 0:
        ro = tmp_path / "ro"
        ro.mkdir()
        ro.chmod(0o555)
        try:
            rc, doc = run(ro / "out")
        finally:
            ro.chmod(0o755)
        assert rc == 2 and "Permission denied" in doc["error"], doc
    # a write that fails part way, a full disk say
    real_open = open

    def full(path, mode="r", *a, **k):
        if "w" in mode and str(path).endswith("pool.txt"):
            raise OSError(errno.ENOSPC, "No space left on device", str(path))
        return real_open(path, mode, *a, **k)

    monkeypatch.setattr(ex, "open", full, raising=False)
    rc, doc = run(tmp_path / "full")
    assert rc == 2 and "No space left on device" in doc["error"], doc
    assert doc["error"].startswith(f"{tmp_path / 'full'}: "), doc


def test_a_branch_out_from_inside_a_loop_or_an_if_is_read_as_leaving():
    # Two readings of a branch out of the function (or past the instruction cut) from
    # inside a structured region (#86). cfgcheck skipped it, so an arm that leaves read
    # as falling through to whatever followed, and reported an edge the rendering never
    # claimed. Tier 3 left without writing the loop's names back, as a break does, so a
    # name read one trip behind its register.
    sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "tools"))
    import copy
    import cfgcheck
    from jadart.cfg import build_cfg, structure
    from jadart.expr import lift_function

    # A block at the cut whose arms both leave, inside an `if` with code after it: main
    # read it as going on to block 4. Found by building random functions.
    rows = [(0, "b.gt", "#0x1c", ""), (4, "b", "#0x1000", ""),
            (8, "b.eq", "#0x1000", ""), (12, "mov", "x0, #4", ""),
            (16, "cmp", "x0, #1", ""), (20, "b", "#0x1000", ""),
            (24, "cbz", "x0, #0x1000", ""), (28, "b", "#0x18", ""),
            (32, "b.eq", "#0x18", ""), (36, "mov", "x2, #1", ""),
            (40, "b.gt", "#0x30", "")]
    blocks, entry = build_cfg(rows, traps=(), cut_end=60)
    stmts = structure(blocks, entry)
    assert cfgcheck.check_function(blocks, stmts)[0] == []
    # A loop whose back edge is at the cut runs on past it, which is past the last block
    # decoded and so no block; it has no exit of its own to say so.
    spin = [(0, "mov", "x0, #1", ""), (4, "cmp", "x0, #2", ""), (8, "b.gt", "#0x0", "")]
    b2, e2 = build_cfg(spin, traps=(), cut_end=0x40)
    assert b2[0].cut_next == 0xc and b2[0].exit_target < 0
    assert cfgcheck.check_function(b2, structure(b2, e2))[0] == []
    # and an exit the rendering drops is a violation now, where it read as the
    # fallthrough before
    exits = [b for b in blocks.values() if b.exit_target >= 0 and b.succ]
    assert exits

    def drop_exits(seq):
        out = []
        for s in seq:
            if s[0] == "if":
                s = ("if", s[1], [] if s[2] and s[2][0][0] == "exit" else
                     drop_exits(s[2]), drop_exits(s[3]))
            elif s[0] == "loop":
                s = ("loop", s[1], drop_exits(s[2]))
            out.append(s)
        return out

    bad = cfgcheck.check_function(blocks, drop_exits(copy.deepcopy(stmts)))[0]
    assert bad == [(24, [28], [28, "exit 0x1000"])], bad
    # and a branch out with nothing after it is held to saying so: rendered as a jump
    # back into the function it passed, with no successor to compare against
    out = build_cfg([(0, "mov", "x0, #1", ""), (4, "b", "#0x1000", "")], traps=())[0]
    assert cfgcheck.check_function(out, [("asm", 0), ("exit", 0x1000)])[0] == []
    for wrong in ([("asm", 0), ("goto", 0)], [("asm", 0)],
                  [("asm", 0), ("exit", 0x2000)], [("asm", 0), ("goto", 0x1000)]):
        assert cfgcheck.check_function(out, wrong)[0] == [(0, ["no exit rendered"], [])]

    # Tier 3: a counted loop that leaves the function, or runs past the cut, writes its
    # name back first, as its break does.
    loop = [(0, "mov", "x0, #0", ""), (4, "add", "x0, x0, #1", ""),
            (8, "cmp", "x0, #0xa", "")]
    for last, cut, leave in ((("b.eq", "#0x1000"), None, "goto sub_0x1000;"),
                             (("b.eq", "#0x20"), 0x40,
                              "goto 0x20;  // TRUNCATED: past the instruction cut")):
        body = [ln.strip() for ln in lift_function(
            loop + [(12, *last, ""), (16, "b", "#0x4", "")], cut_end=cut)]
        assert body[body.index(leave) - 1] == "t0 += 1;", body
    # From an inner loop, the inner loop's names, as a break from it writes back. Not the
    # outer loop's too: written after the inner ones they read names the inner loop has
    # just reassigned, which printed values the CPU contradicts (#86, review).
    nested = [(0, "mov", "x0, #0", ""), (4, "mov", "x1, #0", ""),
              (8, "add", "x1, x1, #1", ""), (12, "add", "x0, x0, #2", ""),
              (16, "cmp", "x1, #5", ""), (20, "b.eq", "#0x1000", ""),
              (24, "cmp", "x1, #3", ""), (28, "b.ne", "#0x8", ""),
              (32, "add", "x0, x0, #1", ""), (36, "b", "#0x4", "")]
    body = [ln.strip() for ln in lift_function(nested)]
    at = body.index("goto sub_0x1000;")
    brk = body.index("break;")
    assert body[at - 2:at] == body[brk - 2:brk] == ["t1 += 2;", "t2 += 1;"], body
    assert body[at - 3] == "if ((t2 + 1) == 5) {", body

    # A conditional return or indirect jump on arm32 leaves too, and its arm claims None
    # where the block records a cexit: bxeq lr, popne {fp, pc}, ldrne pc, [sl, #0x1c].
    _needs_capstone()
    import struct
    from jadart.disasm import InstrImage, CodeRange, disassemble_range
    for words in cfgcheck._A32_RANGES[1:3] + cfgcheck._A32_RANGES[6:7]:
        image = InstrImage(text=b"".join(struct.pack("<I", w) for w in words), pcs=[0],
                           first_code=0, code_ranges={}, all_ranges=[], symbol_names={})
        image.arch = type("Arch", (), {"name": "arm", "compressed": False,
                                       "word_size": 4})()
        image.anchor_va = None
        cr = CodeRange(pc_offset=0, size=4 * len(words), owner_ref=-1)
        blocks = cfgcheck._tier2_cfg(image, disassemble_range(image, cr), {}, {}, True)
        assert any(b.cexit for b in blocks.values())
        stmts = structure(blocks, min(blocks))
        assert cfgcheck.check_function(blocks, stmts)[0] == [], words


#: For test_a_goto_target_reads_what_the_jump_left: name -> (the code as (word, mnemonic,
#: operands), the arguments to run it on a CPU with or None, the lines that end the way
#: out, a line the target has to print, and one it must not). The text is what capstone
#: prints for the words.
_GOTO_SHAPES = {
    # One loop, two ways out. The goto's target reads the register the write-back just
    # copied into t0, so the target has to read t0, not `t0 + 1` over again. x8 and the
    # slot it is spilled to hold `t0 + 5` and nothing past the goto reads either.
    "renamed": ([(0xd2800003, "mov", "x3, #0"), (0x91001468, "add", "x8, x3, #5"),
                 (0xf81f03a8, "stur", "x8, [x29, #-0x10]"),
                 (0x91000463, "add", "x3, x3, #1"), (0xeb01007f, "cmp", "x3, x1"),
                 (0x540000a0, "b.eq", "#0x28"), (0xf100247f, "cmp", "x3, #9"),
                 (0x54ffff41, "b.ne", "#4"), (0xd2800000, "mov", "x0, #0"),
                 (0xd65f03c0, "ret", ""), (0x91019060, "add", "x0, x3, #0x64"),
                 (0xd65f03c0, "ret", "")],
                {"x1": 3}, ["t0 += 1;", "goto L_0x28;"], "return t0 + 100;",
                "return t0 + 1 + 100;"),
    # The same goto to a block another path reaches too: that block is entered from
    # nothing (`_reenter`), so nothing is written out for it, x1 included.
    "joined": ([(0xd2800003, "mov", "x3, #0"), (0xb4000122, "cbz", "x2, #0x28"),
                (0xaa0303e1, "mov", "x1, x3"), (0x91000463, "add", "x3, x3, #1"),
                (0xeb04007f, "cmp", "x3, x4"), (0x540000a0, "b.eq", "#0x28"),
                (0xf100247f, "cmp", "x3, #9"), (0x54ffff61, "b.ne", "#8"),
                (0xd2800000, "mov", "x0, #0"), (0xd65f03c0, "ret", ""),
                (0xaa0103e0, "mov", "x0, x1"), (0xd65f03c0, "ret", "")],
               None, ["t0 += 1;", "goto L_0x28;"], "return x1;", "var t1 = t0;"),
    # x1 holds t0 from before the write-back and is the argument of the call there,
    # which liveness does not count as a read. Not run: the printed call has no value.
    "call_arg": ([(0xd2800003, "mov", "x3, #0"), (0xaa0303e1, "mov", "x1, x3"),
                  (0x91000463, "add", "x3, x3, #1"), (0xeb02007f, "cmp", "x3, x2"),
                  (0x540000a0, "b.eq", "#0x24"), (0xf100247f, "cmp", "x3, #9"),
                  (0x54ffff61, "b.ne", "#4"), (0xd2800000, "mov", "x0, #0"),
                  (0xd65f03c0, "ret", ""), (0x94000037, "bl", "#0x100"),
                  (0xd65f03c0, "ret", "")],
                 # `t1` is read at the goto target, outside the block `_arrive` pins it
                 # in, so its declaration is hoisted and the assignment stays here (#204).
                 None, ["t1 = t0;", "t0 += 1;", "goto L_0x24;"],
                 "return sub_0x100(t1);", "return sub_0x100(t0);"),
    # The target reads x4 and x6, which hold t0 from BEFORE the write-back, and reloads
    # `t0 + 2` from a frame slot: each value is written out once, while it still means
    # that, and the target reads the copies. x5 holds `t0 + 3` and nothing reads it, so
    # it is not written out.
    "pinned": ([(0xd2800003, "mov", "x3, #0"), (0xaa0303e4, "mov", "x4, x3"),
                (0xaa0303e6, "mov", "x6, x3"), (0x91000c65, "add", "x5, x3, #3"),
                (0x91000868, "add", "x8, x3, #2"), (0xf81f83a8, "stur", "x8, [x29, #-8]"),
                (0x91000463, "add", "x3, x3, #1"), (0xeb01007f, "cmp", "x3, x1"),
                (0x540000a0, "b.eq", "#0x34"), (0xf100247f, "cmp", "x3, #9"),
                (0x54fffee1, "b.ne", "#4"), (0xd2800000, "mov", "x0, #0"),
                (0xd65f03c0, "ret", ""), (0xf85f83a9, "ldur", "x9, [x29, #-8]"),
                (0x8b060080, "add", "x0, x4, x6"), (0x8b090000, "add", "x0, x0, x9"),
                (0xd65f03c0, "ret", "")],
               {"x1": 3},
               # Both are read at the goto target, so both declarations hoist (#204).
               ["t1 = t0;", "t2 = t0 + 2;", "t0 += 1;", "goto L_0x34;"],
               "return t1 + t1 + t2;", "return t0 + t0 + (t0 + 2);"),
    # The inner loop's `break` writes t2 back, then the outer loop's goto leaves: the
    # shape parsePartialString has, where no write-back sits next to the goto at all.
    "via_break": ([(0xd2800003, "mov", "x3, #0"), (0x14000005, "b", "#0x18"),
                   (0xd28000e0, "mov", "x0, #7"), (0xd65f03c0, "ret", ""),
                   (0x910190a0, "add", "x0, x5, #0x64"), (0xd65f03c0, "ret", ""),
                   (0xb4ffff82, "cbz", "x2, #8"), (0xd2800005, "mov", "x5, #0"),
                   (0x910004a5, "add", "x5, x5, #1"), (0xeb0100bf, "cmp", "x5, x1"),
                   (0x54ffff40, "b.eq", "#0x10"), (0xf1000cbf, "cmp", "x5, #3"),
                   (0x54ffff81, "b.ne", "#0x20"), (0x91000463, "add", "x3, x3, #1"),
                   (0xf100107f, "cmp", "x3, #4"), (0x54fffee1, "b.ne", "#0x18"),
                   (0x17fffff2, "b", "#8")],
                  # t1, not t2: the loop no longer carries a register it does not
                  # write, so one name fewer is minted before this one (#228).
                  {"x1": 2, "x2": 1}, ["t1 += 1;", "break;"], "return t1 + 100;",
                  "return t1 + 1 + 100;"),
    # The same, but the break leaves before the increment and writes nothing back, so
    # x6, the copy of t2 the state past the loop has lost, still reads as t2.
    "via_break_kept": ([(0xd2800003, "mov", "x3, #0"), (0x14000005, "b", "#0x18"),
                        (0xd28000e0, "mov", "x0, #7"), (0xd65f03c0, "ret", ""),
                        (0x910190c0, "add", "x0, x6, #0x64"), (0xd65f03c0, "ret", ""),
                        (0xb4ffff82, "cbz", "x2, #8"), (0xd2800005, "mov", "x5, #0"),
                        (0xaa0503e6, "mov", "x6, x5"), (0xeb0100bf, "cmp", "x5, x1"),
                        (0x54ffff40, "b.eq", "#0x10"), (0x910004a5, "add", "x5, x5, #1"),
                        (0xf1000cbf, "cmp", "x5, #3"), (0x54ffff61, "b.ne", "#0x20"),
                        (0x91000463, "add", "x3, x3, #1"), (0xf100107f, "cmp", "x3, #4"),
                        (0x54fffec1, "b.ne", "#0x18"), (0x17fffff1, "b", "#8")],
                       {"x1": 2, "x2": 1}, ["} else {", "break;"], "return t1 + 100;",
                       "return x6 + 100;"),
}


def test_a_goto_target_reads_what_the_jump_left():
    # A block only a goto reaches is lifted from the state its one predecessor left, and
    # that state was recorded BEFORE the printed program writes loop names back on the
    # way there (#106). The write-back changes what a name means, and the target went on
    # reading the old meaning: 2.19.6's parsePartialKeyword returned `t4 + 1` right after
    # `t4 += 1;`, one more than the CPU, and 3.4.4's parsePartialString passed `t0` where
    # the machine passes the t0 from before `t0 = x0;`. Each shape is one way in.
    sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "tools"))
    import struct
    from jadart import expr

    lifted, walks = {}, []
    init = expr.Lifter.__init__
    try:
        def counted(self, *a, **k):
            walks.append(1)
            init(self, *a, **k)
        expr.Lifter.__init__ = counted
        for name, (rows, _args, before, want, old) in _GOTO_SHAPES.items():
            walks.clear()
            lines = expr.lift_function([(4 * i, mn, op, "")
                                        for i, (_w, mn, op) in enumerate(rows)],
                                       arity=lambda pc: 1)
            body = [ln.strip() for ln in lines]
            at = body.index(before[-1])
            assert body[at - len(before) + 1:at + 1] == before, (name, body)
            assert want in body and old not in body, (name, body)
            lifted[name] = (lines, len(walks))
    finally:
        expr.Lifter.__init__ = init
    # A second walk is what keeps a value written out for nothing out of the output;
    # one nothing past the jump can read is not written out to begin with. `pinned` takes
    # a third now: its two pins are read at the goto target, so the hoist wants them and
    # the hoist decides on the lines as they will ship, which costs one more walk (#204).
    assert [lifted[k][1] for k in ("renamed", "joined", "pinned")] == [1, 1, 3], lifted

    # And on a CPU: the value the printed program returns is the one the machine does.
    if not _unicorn_available() or not _capstone_available():
        _skip("  SKIP test_a_goto_target_reads_what_the_jump_left, CPU half")
    import irfuzz
    from capstone import Cs, CS_ARCH_ARM64, CS_MODE_LITTLE_ENDIAN
    from unicorn import Uc, UC_ARCH_ARM64, UC_MODE_ARM, arm64_const as a64
    md = Cs(CS_ARCH_ARM64, CS_MODE_LITTLE_ENDIAN)
    for name, (rows, args, _b, _w, _o) in _GOTO_SHAPES.items():
        code = b"".join(struct.pack("<I", w) for w, _m, _o in rows)
        assert [(i.mnemonic, i.op_str) for i in md.disasm(code, 0)] == [
            (m, o) for _w, m, o in rows], name
        if args is None:
            continue
        base, end = 0x10000, 0x10000 + len(code)
        mu = Uc(UC_ARCH_ARM64, UC_MODE_ARM)
        mu.mem_map(base, 0x1000)
        mu.mem_map(0x20000, 0x1000)                   # a frame for the slot x29 names
        mu.mem_write(base, code)
        for reg, v in args.items():
            mu.reg_write(getattr(a64, f"UC_ARM64_REG_X{reg[1:]}"), v)
        mu.reg_write(a64.UC_ARM64_REG_X29, 0x20800)
        mu.reg_write(a64.UC_ARM64_REG_X30, end)
        mu.emu_start(base, end, count=1000)
        env = dict(args, xzr=0)
        ret = irfuzz._run_printed([ln.strip() for ln in lifted[name][0]], env)
        got = irfuzz._ev(irfuzz._mem_expr(ret), env)
        assert got == mu.reg_read(a64.UC_ARM64_REG_X0), (name, ret, got)


def test_a_function_writes_out_a_bounded_number_of_values_before_its_gotos():
    # A loop that spills S slots and leaves by G gotos asked `_arrive` for S x G
    # write-outs, every slot before every goto: 4,000 slots and 250 gotos took 6 s and a
    # gigabyte of declarations. Past _MAX_PINS a value is forgotten instead (#106).
    import jadart.expr as E
    rows, labels, fix = [], {}, []

    def emit(mn, op=""):
        rows.append([len(rows) * 4, mn, op, ""])
    emit("mov", "x3, #0")
    labels["loop"] = len(rows) * 4
    for k in range(400):
        emit("add", f"x8, x3, #{k + 1}")
        emit("str", f"x8, [x29, #{16 + 8 * k}]")
    emit("add", "x3, x3, #1")
    for g in range(60):
        emit("cmp", f"x3, x{1 + g % 2}")
        fix.append((len(rows), f"out{g}"))
        emit("b.eq", "")
    emit("cmp", "x3, #100")
    fix.append((len(rows), "loop"))
    emit("b.ne", "")
    emit("ret")
    for g in range(60):
        labels[f"out{g}"] = len(rows) * 4
        for k in range(400 if g == 0 else 1):
            emit("ldr", f"x10, [x29, #{16 + 8 * k}]")
            emit("add", "x0, x0, x10")
        emit("ret")
    for i, label in fix:
        rows[i][2] = f"#{labels[label]:#x}"
    most = []
    real, cap = E.Lifter._arrive, E._MAX_PINS

    def spy(self, *a, **k):
        out = real(self, *a, **k)
        most.append(len(self.pins))
        return out
    E.Lifter._arrive = spy
    try:
        E.lift_function([tuple(r) for r in rows])
        assert most and max(most) == cap, max(most)
        E._MAX_PINS, most[:] = 10, []
        E.lift_function([tuple(r) for r in rows])
        assert max(most) == 10, max(most)
    finally:
        E.Lifter._arrive, E._MAX_PINS = real, cap

def test_the_nested_loop_oracle_catches_a_goto_target_read_stale():
    """Teeth for `irfuzz --cfgmem --nested`, which generates the shape #106 was found in.

    `_gen_function` builds one loop at most, so a goto out of two never came up and the
    oracle reported nothing on a lifter that had the defect. Without `_arrive` a goto's
    target is lifted from the state before the write-back again, and the nested graphs
    have to catch it; `--cfg` runs them too, and has to stay clean."""
    if not _unicorn_available() or not _capstone_available():
        _skip("  SKIP test_the_nested_loop_oracle_catches_a_goto_target_read_stale")
    sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "tools"))
    import irfuzz
    from jadart import expr

    assert irfuzz.run_cfg(200, 25, 1, False, nested=True) == 0
    for seed in (1, 3):
        got = irfuzz.run_cfgmem(300, 50, seed, False, seed_outs=True, nested=True)
        assert got == 0, f"the nested graphs disagreed with the CPU at seed {seed}"
    arrive = expr.Lifter._arrive
    try:
        expr.Lifter._arrive = lambda self, addr, st, moved, pad="": []
        assert irfuzz.run_cfgmem(300, 50, 3, False, seed_outs=True, nested=True) != 0, (
            "the nested graphs passed with a goto's target read from before its copy")
    finally:
        expr.Lifter._arrive = arrive


def test_cfgcheck_holds_a_leaving_arm_to_its_kind_and_target():
    # cfgcheck read every arm that leaves as None, whichever way it left and to where, so
    # a branch into the part past the cut rendered as one out of the function (#70's
    # mistake), an exit pointed somewhere else, or an exit arm emptied with the
    # fallthrough nested in the other arm all passed (#107). Each correct rendering
    # below passes, and each wrong one is reported.
    sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "tools"))
    import cfgcheck
    from jadart.cfg import EXIT_INDIRECT, EXIT_RETURN, build_cfg, structure

    def check(rows, stmts=None, cut=None):
        blocks, entry = build_cfg(rows, traps=(), cut_end=cut)
        return cfgcheck.check_function(blocks, stmts or structure(blocks, entry))[0]

    out = [(0, "mov", "x0, #1", ""), (4, "b", "#0x1000", "")]
    assert check(out) == [] and check(out, [("asm", 0), ("exit", 0x1000)]) == []
    assert check(out, [("asm", 0), ("cut", 0x1000)]) == [(0, ["no exit rendered"], [])]

    past = [(0, "mov", "x0, #1", ""), (4, "b", "#0x20", "")]
    assert check(past, cut=0x40) == []
    assert check(past, [("asm", 0), ("exit", 0x20)], cut=0x40) == [
        (0, ["no exit rendered"], [])]

    cond = [(0, "cmp", "x0, #1", ""), (4, "b.eq", "#0x1000", ""), (8, "ret", "", "")]
    good = [("asm", 0), ("if", "x0 == 1", [("exit", 0x1000)], []), ("asm", 8)]
    assert check(cond) == [] and check(cond, good) == []
    elsewhere = [("asm", 0), ("if", "x0 == 1", [("exit", 0x2000)], []), ("asm", 8)]
    assert check(cond, elsewhere) == [(0, [8, "exit 0x2000"], [8, "exit 0x1000"])]
    as_cut = [("asm", 0), ("if", "x0 == 1", [("cut", 0x1000)], []), ("asm", 8)]
    assert check(cond, as_cut) == [(0, [8, "cut 0x1000"], [8, "exit 0x1000"])]
    # the exit arm emptied and the fallthrough nested in the other one, at the end
    nested = [("asm", 0), ("if", "x0 == 1", [], [("asm", 8)])]
    assert check(cond, nested) == [(0, [8], [8, "exit 0x1000"])]

    # A conditional return is a return, and an indirect jump an indirect jump.
    _needs_capstone()
    import struct
    from jadart.disasm import InstrImage, CodeRange, disassemble_range
    words = cfgcheck._A32_RANGES[2]                      # popne {fp, pc}
    image = InstrImage(text=b"".join(struct.pack("<I", w) for w in words), pcs=[0],
                       first_code=0, code_ranges={}, all_ranges=[], symbol_names={})
    image.arch = type("Arch", (), {"name": "arm", "compressed": False,
                                   "word_size": 4})()
    image.anchor_va = None
    cr = CodeRange(pc_offset=0, size=4 * len(words), owner_ref=-1)
    blocks = cfgcheck._tier2_cfg(image, disassemble_range(image, cr), {}, {}, True)
    stmts = structure(blocks, min(blocks))
    assert cfgcheck.check_function(blocks, stmts)[0] == []

    def swap(seq):
        return [("if", s[1], [("exit", EXIT_INDIRECT, "x") if t[:2] == ("exit",
                                                                       EXIT_RETURN)
                              else t for t in s[2]], s[3]) if s[0] == "if" else s
                for s in seq]

    assert cfgcheck.check_function(blocks, swap(stmts))[0] == [
        (0, [8, "exit indirect"], [8, "exit return"])]


def test_an_output_path_signatures_cannot_write_is_an_input_error(tmp_path, monkeypatch):
    # `signatures -o` into a missing directory, onto a directory, under a file or into a
    # directory it may not write raised the OSError from open(), and the CLI called that
    # a bug in jadart with exit 3 (#97). A path is user input: exit 2, naming it.
    import contextlib
    import errno
    import io
    import json
    import shutil
    from jadart import cli
    from jadart import signatures as sig

    built = []

    def build(refs, progress=None):
        built.append(refs)
        lib = sig.Library(sources=[("ref.so", "3.12.2", 1)])
        lib.by_body[0x1234] = "foo"
        return lib

    monkeypatch.setattr(sig, "build", build)
    ref = tmp_path / "ref.so"
    shutil.copy(CLEAN, ref)

    def run(out):
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            rc = cli.main(["signatures", str(ref), "-o", str(out), "-j"])
        return rc, json.loads(buf.getvalue())

    a_file = tmp_path / "a_file"
    a_file.write_text("x")
    a_dir = tmp_path / "a_dir"
    a_dir.mkdir()
    # Seen before the build, which reads every reference first and takes a while, and
    # the reference itself is not a place to write the library to.
    for out, why in ((tmp_path / "nodir" / "x.sig", "nodir: No such file or directory"),
                     (a_file / "x.sig", "a_file is not a directory"),
                     (a_dir, "is a directory"),
                     (ref, "is one of the references")):
        built.clear()
        rc, doc = run(out)
        assert rc == 2 and doc["type"] == "InputError", (out, rc, doc)
        assert doc["error"].startswith(f"{out}: ") and why in doc["error"], doc
        assert built == [], f"built before refusing {out}"
    assert ref.read_bytes() == open(CLEAN, "rb").read()
    # and nor is the binary inside a reference given as a directory
    tree = tmp_path / "tree"
    (tree / "lib" / "arm64-v8a").mkdir(parents=True)
    inside = tree / "lib" / "arm64-v8a" / "libapp.so"
    shutil.copy(CLEAN, inside)
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        assert cli.main(["signatures", str(tree), "-o", str(inside), "-j"]) == 2
    assert "is one of the references" in json.loads(buf.getvalue())["error"]
    assert inside.read_bytes() == open(CLEAN, "rb").read()
    built.clear()
    rc, doc = run("")
    assert rc == 2 and doc["error"].startswith("-o is empty") and built == [], doc

    # Not seen until the file is opened, and the same typed failure then: a name too
    # long for the filesystem, and, unless this runs as root, a directory read only.
    long_name = tmp_path / ("n" * 300 + ".sig")
    rc, doc = run(long_name)
    assert rc == 2 and doc["error"].startswith(f"{long_name}: ") and built, doc
    if os.geteuid() != 0:
        ro = tmp_path / "ro"
        ro.mkdir()
        ro.chmod(0o555)
        try:
            rc, doc = run(ro / "x.sig")
        finally:
            ro.chmod(0o755)
        assert rc == 2 and doc["type"] == "InputError", doc
        assert doc["error"].startswith(f"{ro / 'x.sig'}: "), doc
        assert "Permission denied" in doc["error"] and built, doc
        assert not (ro / "x.sig").exists()

    # A write that fails part way, a full disk say, leaves no library cut short behind,
    # since one would load as a smaller library with nothing to say so.
    real_open = open
    hook = {}

    class Full:
        def __init__(self, f):
            self.f, self.n = f, 0

        def fileno(self):
            return self.f.fileno()

        def write(self, text):
            self.n += 1
            if self.n > 1:
                if "before" in hook:
                    hook["before"]()
                raise hook.get("raise", OSError(errno.ENOSPC, "No space left on device"))
            return self.f.write(text)

        def __enter__(self):
            return self

        def __exit__(self, *exc):
            self.f.close()

    def full_open(path, mode="r", *a, **k):
        f = real_open(path, mode, *a, **k)
        return Full(f) if "w" in mode else f

    monkeypatch.setattr(sig, "open", full_open, raising=False)
    out = tmp_path / "full.sig"
    rc, doc = run(out)
    assert rc == 2 and "No space left on device" in doc["error"], doc
    assert doc["error"].startswith(f"{out}: ") and not out.exists(), doc
    # Behind a link the file is emptied, which load() refuses, and the link stays.
    target = tmp_path / "target.sig"
    target.write_text("old")
    link = tmp_path / "link.sig"
    link.symlink_to(target)
    rc, doc = run(link)
    assert rc == 2 and link.is_symlink() and target.read_bytes() == b"", doc
    with pytest.raises(jadart.InputError):
        sig.load(str(link))
    a, b = tmp_path / "a.sig", tmp_path / "b.sig"
    a.write_text("old")
    os.link(a, b)
    rc, doc = run(a)
    assert rc == 2 and not a.exists() and b.read_bytes() == b"", doc
    # A file put at the path while the library was being written is not ours to remove;
    # ours, wherever it went, is emptied.
    out = tmp_path / "swapped.sig"

    def swap():
        os.rename(out, tmp_path / "ours.sig")
        out.write_text("theirs")

    hook["before"] = swap
    rc, doc = run(out)
    assert rc == 2 and out.read_text() == "theirs", doc
    assert (tmp_path / "ours.sig").read_bytes() == b""
    # A pipe is no file of ours either, though the descriptor is the path's own.
    if hasattr(os, "mkfifo"):
        fifo = tmp_path / "fifo"
        os.mkfifo(fifo)
        fd = os.open(fifo, os.O_RDWR)         # both ends, so opening it does not block
        try:
            sig._discard(fd, str(fifo))
        finally:
            os.close(fd)
        assert fifo.exists()
    # and Ctrl-C part way is undone the same way, and still a Ctrl-C
    hook.clear()
    hook["raise"] = KeyboardInterrupt()
    out = tmp_path / "interrupted.sig"
    with pytest.raises(KeyboardInterrupt):
        sig.save(build([]), str(out))
    assert not out.exists()
    monkeypatch.undo()

    # A path that can be written is, and reads back, a bare name in the current
    # directory included.
    monkeypatch.setattr(sig, "build", build)
    monkeypatch.chdir(tmp_path)
    for out in (tmp_path / "ok.sig", "bare.sig"):
        rc, doc = run(out)
        assert rc == 0 and doc["ok"], doc
        assert sig.load(str(out)).by_body == {0x1234: "foo"}


def test_cfgcheck_knows_which_arm_of_an_if_is_taken():
    # cfgcheck compared the set of places an `if`'s arms go with the block's, never which
    # arm is which, so an `if` whose arms were the other way round, each running exactly
    # when it should not, passed (#58's class, #110). Under the block's own condition the
    # then-arm is the branch taken; under its negation, the one not taken.
    sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "tools"))
    import cfgcheck
    from jadart.cfg import build_cfg, negate_cond, structure

    def check(rows, stmts=None, cut=None):
        blocks, entry = build_cfg(rows, traps=(), cut_end=cut)
        return cfgcheck.check_function(blocks, stmts or structure(blocks, entry))[0]

    # two blocks: taken (0x10) and not taken (0x8)
    two = [(0, "cmp", "x0, #1", ""), (4, "b.eq", "#0x10", ""), (8, "mov", "x1, #1", ""),
           (12, "ret", "", ""), (16, "mov", "x1, #2", ""), (20, "ret", "", "")]
    blocks, entry = build_cfg(two, traps=())
    cond = blocks[0].cond
    good = structure(blocks, entry)
    assert check(two) == [] and good[1][1] == negate_cond(cond)
    for stmts in ([("asm", 0), ("if", cond, [("asm", 16)],
                                [("asm", 8)])],
                  [("asm", 0), ("if", negate_cond(cond), [("asm", 8)],
                                [("asm", 16)])]):
        assert check(two, stmts) == []
    swapped = [("asm", 0), ("if", negate_cond(cond), [("asm", 16)],
                            [("asm", 8)])]
    assert check(two, swapped) == [(0, ["arms the wrong way round"], [16])]
    # a condition that is neither the block's nor its negation says nothing of the arms
    other = [("asm", 0), ("if", "x9 == 7", [("asm", 16)], [("asm", 8)])]
    assert check(two, other) == [(0, ["arms the wrong way round"], [16])]

    # a branch out of the function: under its own condition the exit is the then-arm
    out = [(0, "cmp", "x0, #1", ""), (4, "b.eq", "#0x1000", ""), (8, "ret", "", "")]
    blocks, entry = build_cfg(out, traps=())
    cond = blocks[0].cond
    assert check(out) == []
    inverted = [("asm", 0), ("if", negate_cond(cond), [("exit", 0x1000)], []),
                ("asm", 8)]
    assert check(out, inverted) == [(0, ["arms the wrong way round"], ["exit 0x1000"])]

    # at the cut: under the negation, the then-arm runs on past it
    spin = [(0, "mov", "x0, #1", ""), (4, "cmp", "x0, #2", ""), (8, "b.gt", "#0x0", "")]
    blocks, entry = build_cfg(spin, traps=(), cut_end=0x40)
    cond = blocks[0].cond
    assert check(spin, cut=0x40) == []
    turned = [("loop", 0, [("asm", 0), ("if", cond, [("cut", 0xc)], [])])]
    assert check(spin, turned, cut=0x40) == [(0, ["arms the wrong way round"], [0])]
    # and with no cut, a loop whose not-taken arm runs off the end of the body has no way
    # out written down, which is said as that rather than as a swap
    assert check(spin) == [(0, ["runs off the end, and nothing says so"], [0])]


def test_assets_are_written_one_to_a_file_and_failures_name_the_right_side(tmp_path):
    # An archive's assets went where their names said: two that differ only in case were
    # one file on macOS and Windows, so one was lost and the other's name labelled its
    # contents, and a file where another needed a directory refused the whole archive
    # after the sources were written. A failure writing the output blamed the archive
    # (#104). Assets take the library rule now (#96), and each side owns its failures.
    import gzip
    import warnings
    import zipfile
    from jadart import container

    fa = "assets/flutter_assets/"
    members = [("Logo.txt", b"upper"), ("logo.txt", b"lower"),
               ("zz", b"file"), ("zz/inner", b"inner"),
               ("NOTICES.Z", gzip.compress(b"pkg\n\nMIT\n")),
               ("dependencies.txt", b"mine"), ("n" * 300 + ".txt", b"long"),
               ("con.txt", b"device"), ("dup.txt", b"first"), ("dup.txt", b"second"),
               ("Icon.png", b"\x89PNG\r\n\x1a\n" + b"\x00" * 8), ("icon.png", b"{}")]
    apk = tmp_path / "app.apk"
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")              # the duplicate name, on purpose
        with zipfile.ZipFile(apk, "w") as z:
            for name, data in members:
                z.writestr(fa + name, data)
            z.writestr("lib/arm64-v8a/libapp.so", b"\x7fELF")

    out = tmp_path / "out"
    stats = container.unpack(str(apk), str(out))
    moved = {("logo.txt", "logo~2.txt"), ("zz", "zz~2"),
             ("dependencies.txt", "dependencies~2.txt"), ("con.txt", "_con.txt"),
             ("dup.txt", "dup~2.txt"), ("n" * 300 + ".txt", "n" * 119),
             ("icon.png", "icon~2.png")}
    assert {tuple(p) for p in stats["renamed"]} == moved, stats["renamed"]
    assert stats["assets"] == len(members)
    # every member is on disk under the name it was given, with its own bytes
    got = {"Logo.txt": b"upper", "logo~2.txt": b"lower", "zz~2": b"file",
           "zz/inner": b"inner", "dependencies~2.txt": b"mine", "n" * 119: b"long",
           "_con.txt": b"device", "dup.txt": b"first", "dup~2.txt": b"second"}
    for path, data in got.items():
        assert (out / "assets" / path).read_bytes() == data, path
    # and jadart's own files beside them keep their names
    assert (out / "assets" / "dependencies.txt").read_text().startswith("# ")
    inv = (out / "assets.txt").read_text()
    assert "7 written under another name" in inv and "  logo.txt -> logo~2.txt" in inv
    assert "logo~2.txt" in inv.split("\n\n")[1]
    # what each is, read from its own bytes, under the name it was written to
    rows = [ln[2:].split() for ln in inv.split("\n\n")[1].splitlines()]
    kinds = {r[0]: " ".join(r[2:]) for r in rows}
    assert (kinds["Icon.png"], kinds["icon~2.png"]) == ("png", "json"), kinds

    # The output's failures are the output's: InputError naming the directory.
    blocked = tmp_path / "blocked"
    blocked.mkdir()
    (blocked / "assets").write_text("x")
    with pytest.raises(jadart.InputError) as e:
        container.unpack(str(apk), str(blocked))
    assert str(e.value).startswith(f"{blocked}: cannot write the export there")
    if os.geteuid() != 0:
        ro = tmp_path / "ro"
        (ro / "assets").mkdir(parents=True)
        (ro / "assets").chmod(0o555)
        try:
            with pytest.raises(jadart.InputError) as e:
                container.unpack(str(apk), str(ro))
        finally:
            (ro / "assets").chmod(0o755)
        assert "Permission denied" in str(e.value)
    # and the archive's are the archive's: a member whose bytes fail their CRC
    with zipfile.ZipFile(apk) as z:
        info = next(i for i in z.infolist() if i.filename == fa + "Logo.txt")
    raw = bytearray(apk.read_bytes())
    raw[info.header_offset + 30 + len(info.filename.encode()) + len(info.extra)] ^= 0xFF
    bad = tmp_path / "bad.apk"
    bad.write_bytes(bytes(raw))
    with pytest.raises(jadart.ContainerError) as e:
        container.unpack(str(bad), str(tmp_path / "out2"))
    assert "Bad CRC-32" in str(e.value) and str(e.value).startswith(f"{bad}: ")
    # and a read of it that fails part way, though the copy is writing at the time
    import errno
    real_read = zipfile.ZipExtFile.read

    def failing(self, n=-1):
        raise OSError(errno.EIO, "Input/output error")

    zipfile.ZipExtFile.read = failing
    try:
        with pytest.raises(jadart.ContainerError) as e:
            container.unpack(str(apk), str(tmp_path / "out4"))
    finally:
        zipfile.ZipExtFile.read = real_read
    assert "Input/output error" in str(e.value)

    # Many copies of one name: each its own file, the numbering counting on rather than
    # trying every number again for each copy, which took 41s for 32,000 of them.
    import importlib
    ex = importlib.import_module("jadart.export")

    def archive(path, names):
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            with zipfile.ZipFile(path, "w") as z:
                for name, data in names:
                    z.writestr(fa + name, data)
        return str(path)

    folds = []
    real_fold = ex._fold
    ex._fold = lambda r: folds.append(r) or real_fold(r)
    try:
        stats = container.unpack(archive(tmp_path / "dups.apk",
                                         [("a.txt", b"%d" % i) for i in range(2000)]),
                                 str(tmp_path / "dups"))
    finally:
        ex._fold = real_fold
    assert len(folds) < 8 * 2000, f"{len(folds)} folds for 2000 copies"
    assert sorted(os.listdir(tmp_path / "dups" / "assets")) == sorted(
        ["a.txt"] + [f"a~{n}.txt" for n in range(2, 2001)])
    assert (tmp_path / "dups" / "assets" / "a~2000.txt").read_bytes() == b"1999"

    # jadart's own files come from the members named exactly as Flutter names them, so a
    # case variant is an asset like any other, on every platform; and where an asset
    # needs one of jadart's names as a directory, jadart does without that file.
    notices = gzip.compress(b"pkg\n\nMIT\n")
    manifest = b"\x0d\x02\x07\x01a\x00\x07\x01b\x00"     # {"a": null, "b": null}
    for name, extra, keeps in (
            ("cased", [("notices.z", notices), ("NOTICES", b"mine-notices"),
                       ("dependencies.txt", b"mine-deps")],
             {"NOTICES": b"mine-notices", "dependencies.txt": b"mine-deps"}),
            ("dir", [("NOTICES.Z", notices), ("NOTICES/readme", b"a dir")],
             {"NOTICES/readme": b"a dir"}),
            # the NOTICES.Z that is read is the one written under that name, the first
            ("twice", [("NOTICES.Z", notices), ("NOTICES.Z", gzip.compress(b"other\n"))],
             {"NOTICES": b"pkg\n\nMIT\n"}),
            ("binary", [("AssetManifest.bin", manifest),
                        ("AssetManifest.bin/readme", b"a dir"),
                        ("AssetManifest.decoded.json/x", b"a dir")],
             {"AssetManifest~2.bin": manifest, "AssetManifest.bin/readme": b"a dir",
              "AssetManifest.decoded.json/x": b"a dir"})):
        out = tmp_path / name
        got = container.unpack(archive(tmp_path / f"{name}.apk", extra), str(out))
        for path, data in keeps.items():
            assert (out / "assets" / path).read_bytes() == data, (name, path)
        if name == "binary":
            # read from where it was written, and counted though its decoded copy is not
            assert got["declared_assets"] == 2, got

    # Every member is checked before any is written.
    with zipfile.ZipFile(apk) as z:
        sizes = [i.file_size for i in z.infolist()]
    old = container.MAX_MEMBER
    container.MAX_MEMBER = max(sizes) - 1
    try:
        with pytest.raises(jadart.ContainerError):
            container.unpack(str(apk), str(tmp_path / "out3"))
    finally:
        container.MAX_MEMBER = old
    assert not (tmp_path / "out3" / "assets").exists()


def test_a_branch_reads_the_operands_its_flags_were_set_from():
    # `subs x1, x1, #8` sets the flags from the x1 it overwrites, and the branch after it
    # printed its condition with the x1 that was left: the clean fixture's copy loop read
    # `if (x1 == 8) break;` after the raw `subs`, where the machine leaves when the new x1
    # is 0 (#116). The condition is rendered from the operands as the flags saw them, and
    # an old value spelled with the register being overwritten is named first.
    from jadart.expr import lift_function

    def lift(rows):
        return [ln.strip() for ln in lift_function(rows)]

    # The `subs` prints no line of its own in these bodies: #239 models the VALUE a
    # flag-setting op writes, through the same twin `sub` is read by, and nothing here
    # reads the x1 it leaves. What this pins is the condition, which still has to read
    # the operands as the flags saw them.
    assert lift([(0, "subs", "x1, x1, #8", ""), (4, "b.ne", "#0xc", ""),
                 (8, "str", "xzr, [x2, #7]", ""), (12, "ret", "", "")]) == [
        "var t0 = x1;", "if (t0 == 8) {", "x2.field_0x8 = 0;", "}", "return x0;"]
    assert lift([(0, "ands", "x3, x3, #0xfffffff9", ""), (4, "b.eq", "#0xc", ""),
                 (8, "str", "xzr, [x2, #7]", ""), (12, "ret", "", "")])[:2] == [
        "var t0 = x3;", "if ((t0 & 0xfffffff9) != 0) {"]
    # an operand that is a field read keeps its text, and needs no name
    assert lift([(0, "ldur", "x1, [x2, #0xf]", ""), (4, "subs", "x1, x1, #8", ""),
                 (8, "b.ne", "#0x10", ""), (12, "str", "xzr, [x2, #7]", ""),
                 (16, "ret", "", "")])[0] == "if (x2.field_0x10 == 8) {"
    # and in the copy loop the loop's own name for x1 is the old value, which the trip
    # now also updates, since the `subs` writes one
    body = lift([(0, "ldr", "x0, [x3], #8", ""), (4, "str", "x0, [x4], #8", ""),
                 (8, "subs", "x1, x1, #8", ""), (12, "b.ne", "#0x0", ""),
                 (16, "ret", "", "")])
    assert "if (t0 == 8) {" in body, body
    assert "t0 -= 8;" in body, body
    # The flags are set from the sources, and an x1 the instruction only writes is no
    # source: nothing is named for it.
    assert lift([(0, "subs", "x1, x0, x2", ""), (4, "b.ne", "#0xc", ""),
                 (8, "str", "xzr, [x3, #7]", ""), (12, "ret", "", "")])[0] == (
        "if (x0 == x2) {")
    # A compare sets the flags without writing, and reads as it always did.
    assert lift([(0, "cmp", "x1, #8", ""), (4, "b.ne", "#0xc", ""),
                 (8, "str", "xzr, [x2, #7]", ""), (12, "ret", "", "")])[0] == (
        "if (x1 == 8) {")
    # A select reads the flags as the branch does.
    assert lift([(0, "subs", "x1, x1, #8", ""), (4, "csel", "x0, x3, x4, ne", ""),
                 (8, "ret", "", "")]) == [
        "var t0 = x1;", "return t0 != 8 ? x3 : x4;"]
    # cbz and tbz test their register as it is when they run, not the flags left by
    # the instruction before, and with nothing reading the flags nothing is named.
    # The register they test is the one the `subs` wrote, and #239 knows what that is
    # now, so it reads as the value rather than as the bare name after a raw line.
    assert lift([(0, "subs", "x1, x1, #8", ""), (4, "cbz", "x1, #0xc", ""),
                 (8, "str", "xzr, [x2, #7]", ""), (12, "ret", "", "")])[0] == (
        "if ((x1 - 8) != 0) {")
    assert lift([(0, "subs", "x1, x1, #2", ""), (4, "tbnz", "x1, #1, #0xc", ""),
                 (8, "str", "xzr, [x2, #7]", ""), (12, "ret", "", "")])[0] == (
        "if (((x1 - 2) >> 1) & 1 == 0) {")
    assert lift([(0, "ldur", "x0, [x2, #7]", ""), (4, "cmp", "x0, #5", ""),
                 (8, "stur", "xzr, [x2, #7]", ""), (12, "cbz", "x0, #0x14", ""),
                 (16, "stur", "x0, [x2, #0xf]", ""), (20, "ret", "", "")])[2] == (
        "if (t0 != 0) {")
    assert lift([(0, "subs", "x1, x1, #8", ""), (4, "str", "x1, [x2, #7]", ""),
                 (8, "ret", "", "")])[0] == "x2.field_0x8 = x1 - 8;"
    # ...nor where the flags are replaced, or an operand overwritten, before the select.
    # What says the select was declined is the select itself staying raw, since the
    # `subs` above it no longer prints a line of its own (#239).
    for row in (("sbcs", "x5, x6, x7"), ("mov", "x1, #3")):
        body = lift([(0, "subs", "x1, x1, #8", ""), (4, *row, ""),
                     (8, "csel", "x0, x3, x4, ne", ""), (12, "ret", "", "")])
        assert any(ln.startswith("csel ") for ln in body), body


def test_a_value_spelled_with_a_register_a_raw_line_writes_is_named_first():
    # A raw line assigns its destination in the printed body, so a value the lifter
    # still held that was spelled with that register read as the new value after it:
    # `add x5, x1, #1; subs x1, x1, #8; str x5` printed `x1 + 1` for the old x1 (#118).
    from jadart.expr import lift_function

    def lift(rows):
        return [ln.strip() for ln in lift_function(
            [(i * 4, *r, "") for i, r in enumerate(rows)])]
    # `subs` was the first of these and is no longer one: #239 models the value it
    # writes, so it prints no raw line. `adcs` still does, because its value needs the
    # carry bit and nothing here can spell that.
    for raw in (("adcs", "x1, x1, x3"), ("mrs", "x1, nzcv"),
                ("fmov", "x1, d0"), ("ldr", "x1, [x1, #-8]!")):
        body = lift([("add", "x5, x1, #1"), raw, ("str", "x5, [x2, #7]"), ("ret", "")])
        assert body == ["var t0 = x1 + 1;", " ".join(raw), "x2.field_0x8 = t0;",
                        "return x0;"], raw
    # A frame slot holding one is named the same way.
    assert lift([("add", "x5, x1, #1"), ("stur", "x5, [x29, #-8]"),
                 ("adcs", "x1, x1, x3"), ("ldur", "x6, [x29, #-8]"),
                 ("str", "x6, [x2, #7]"), ("ret", "")]) == [
        "var t0 = x1 + 1;", "adcs x1, x1, x3", "x2.field_0x8 = t0;", "return x0;"]
    # In a block with no call or store in it too.
    assert lift([("add", "x5, x1, #1"), ("adcs", "x1, x1, x3"), ("mov", "x0, x5"),
                 ("ret", "")]) == ["var t0 = x1 + 1;", "adcs x1, x1, x3", "return t0;"]
    # A store that moves its base by a register moves it in the printed body as well.
    assert lift([("add", "x5, x1, #1"), ("str", "x0, [x1], x2"), ("str", "x5, [x4, #7]"),
                 ("str", "x1, [x4, #0xf]"), ("ret", "")]) == [
        "var t0 = x1 + 1;", "str x0, [x1], x2", "x4.field_0x8 = t0;",
        "x4.field_0x10 = x1;", "return x0;"]
    # An `ldp` writes both of its registers, and the second one was kept as it was. The
    # old value of a register the line writes is not named, it is not read again.
    assert lift([("add", "x2, x3, #1"), ("ldp", "x1, x2, [x1], #0x10"),
                 ("str", "x2, [x4, #7]"), ("ret", "")])[1] == "x4.field_0x8 = x2;"
    assert lift([("add", "x5, x2, #1"), ("ldp", "x1, x2, [x1], #0x10"),
                 ("str", "x5, [x4, #7]"), ("ret", "")])[0] == "var t0 = x2 + 1;"
    assert lift([("add", "x2, x1, #1"), ("add", "x5, x1, #2"),
                 ("ldp", "x1, x2, [x1], #0x10"), ("str", "x5, [x4, #7]"),
                 ("str", "x2, [x4, #0xf]"), ("ret", "")])[0] == "var t0 = x1 + 2;"
    # A role register stays a role where the line only moves it, and is forgotten,
    # as before, where it is what the line loads.
    assert lift([("str", "x0, [x15], x1"), ("add", "x5, x15, #8"),
                 ("str", "x5, [x4, #7]"), ("ret", "")])[1] == "x4.field_0x8 = SP + 8;"
    assert lift([("ldr", "x15, [x15, #8]!"), ("add", "x5, x15, #8"),
                 ("str", "x5, [x4, #7]"), ("ret", "")])[1] == "x4.field_0x8 = x15 + 8;"
    # A store-release reads the register it names and writes none: x0 keeps its value.
    assert lift([("add", "x0, x1, #1"), ("add", "x17, x2, #27"), ("stlr", "x0, [x17]"),
                 ("str", "x0, [x3, #7]"), ("ret", "")])[1] == "x3.field_0x8 = x1 + 1;"
    # A comparison made from a value spelled with the register reads it no more.
    assert lift([("add", "x2, x1, #1"), ("cmp", "x2, #5"), ("umulh", "x1, x1, x3"),
                 ("csel", "x0, x4, x5, eq"), ("ret", "")])[1] == "csel x0, x4, x5, eq"
    # What a raw line writes is what the architecture says it writes: a store-release
    # none, an atomic its second register, a compare-and-swap its first, and `st1` the
    # base it moves. `br` reads its target.
    from jadart.expr import _def_use
    for mn, op, defs, uses in (
            ("stlr", "w0, [x17]", set(), {"x0", "x17"}),
            ("ldaddal", "x0, x1, [x2]", {"x1"}, {"x0", "x2"}),
            ("swp", "x0, x1, [x2]", {"x1"}, {"x0", "x2"}),
            ("cas", "x0, x1, [x2]", {"x0"}, {"x0", "x1", "x2"}),
            ("ldaxp", "x0, x1, [x2]", {"x0", "x1"}, {"x2"}),
            ("st1", "{v0.16b}, [x1], x2", {"x1"}, {"d0", "x1", "x2"}),
            ("br", "x16", set(), {"x16"})):
        assert _def_use(mn, op) == (defs, uses), (mn, _def_use(mn, op))
    # Nothing reads x5 after the line, so nothing is named, and a name nothing prints
    # is left out: `ret` counts d0 as read, and `isNaN` returns x0. The `subs` prints no
    # line of its own either, since #239 models the value and nothing reads x1 (`adcs`
    # below is the raw one, and its value needs a carry bit nothing here can spell).
    assert lift([("add", "x5, x1, #1"), ("subs", "x1, x1, #8"), ("ret", "")]) == [
        "return x0;"]
    assert lift([("add", "x5, x1, #1"), ("adcs", "x1, x1, x3"), ("ret", "")]) == [
        "adcs x1, x1, x3", "return x0;"]
    assert lift([("ldur", "d0, [x0, #7]"), ("fcmp", "d0, d0"),
                 ("csel", "x0, x16, x0, vc"), ("ret", "")]) == [
        "csel x0, x16, x0, vc", "return x0;"]


#: The shape of 3.4.4's `Rect.fromPoints` (#121): x8 holds a field read before the
#: branches, and the only path that overwrites x2, which the read is spelled with, is the
#: `umulh` one, so the field is named there and nowhere else. Every other path reaches the
#: store at the end by a goto.
_FROM_POINTS = [
    ("ldur", "x8, [x2, #7]"), ("ldur", "x4, [x2, #15]"), ("ldur", "x5, [x3, #15]"),
    ("cmp", "x4, x5"), ("b.le", "#0x1c"), ("mov", "x6, x5"), ("b", "#0x70"),
    ("cmp", "x5, x4"), ("b.le", "#0x2c"), ("mov", "x6, x4"), ("b", "#0x70"),
    ("cmp", "x4, #0"), ("b.ne", "#0x3c"), ("add", "x6, x4, x5"), ("b", "#0x70"),
    ("cmp", "x4, #0"), ("b.ne", "#0x5c"), ("cmp", "x5, #7"), ("b.eq", "#0x5c"),
    ("b.ne", "#0x58"), ("umulh", "x2, x5, x5"), ("cmp", "x2, #0"), ("b.lt", "#0x64"),
    ("cmp", "x5, #9"), ("b.ne", "#0x6c"), ("mov", "x6, x5"), ("b", "#0x70"),
    ("mov", "x6, x4"), ("stur", "x6, [x1, #15]"), ("stur", "x8, [x1, #7]"), ("ret", "")]


def test_a_join_reads_no_name_only_some_of_its_paths_set():
    # A name is set on the paths through the place it is set, and only those. A goto join
    # kept every register no block between wrote, and naming a value writes none, so the
    # join read a name only one path had set: `x1.field_0x8 = t10;` in the shape above
    # (#121). Not knowing x8 there is the honest answer; `x2.field_0x8`, what main says,
    # is wrong on the path through the `umulh`.
    from jadart.expr import lift_function

    def lift(rows):
        return [ln.strip() for ln in lift_function(
            [(i * 4, *r, "") for i, r in enumerate(rows)])]
    body = lift(_FROM_POINTS)
    assert body[-2] == "x1.field_0x8 = x8;", body
    # A loop that opens an arm declares its names inside the arm, not at the `if` above
    # it, so a goto past the arm does not find them set: here the label after the loop
    # read `t1`, set only in the loop.
    body = lift([("add", "x17, x14, #7"), ("swp", "x11, x7, [x17]"),
                 ("cbnz", "x3, #0x18"), ("stlr", "x7, [x17]"), ("b.eq", "#0x1c"),
                 ("tbz", "x9, #63, #0xc"), ("b", "#0x1c"), ("stur", "x7, [x2, #71]"),
                 ("ret", "")])
    assert body[-2] == "x2.field_0x48 = x7;", body
    body = lift([("add", "x8, x4, #49"), ("cbz", "x11, #0x18"), ("add", "x17, x14, #31"),
                 ("cbnz", "x0, #0x1c"), ("sub", "x10, x8, x1"), ("tbz", "x9, #63, #0x8"),
                 ("add", "x17, x14, #31"), ("swp", "x8, x4, [x17]"), ("ret", "")])
    # The note says what the register the line STORES holds, which is the value the
    # block before the loop put there: the loop does not write x8, so it is not
    # forgotten at the exit any more and the note has something to say (#228).
    assert body[-2] == "swp x8, x4, [x17]   // x8 holds x4 + 49", body
    # What a block that dominates the join names is set on every path, so it is kept:
    # a call's result, a phi bound above an `if` and a loop's name, each made before the
    # branches start.

    def ahead(prefix, tail):
        n = len(prefix) - 1
        moved = [(mn, f"#{int(op[1:], 16) + 4 * n:#x}")
                 if mn[0] == "b" and op.startswith("#") else (mn, op)
                 for mn, op in _FROM_POINTS[1:-2]]
        return lift(prefix + moved + tail)
    body = ahead([("bl", "#0x900"), ("mov", "x19, x0"), ("cbz", "x9, #0x14"),
                  ("add", "x10, x11, #1"), ("b", "#0x18"), ("add", "x10, x11, #2")],
                 [("stur", "x19, [x1, #0x17]"), ("stur", "x10, [x1, #0x1f]"),
                  ("ret", "")])
    # x1 is the call's to clobber like any other volatile register, so the base is the
    # name the call declares for it rather than a bare x1 that read as the entry value
    # (#176). The point is the two names made above the branches, the result and the phi,
    # which the join still reads; their numbers move with the declarations minted first.
    joined = "\n".join(body)
    res = re.search(r"var (t\d+) = sub_0x900\(\.\.\.\);", joined)
    phi = re.search(r"\b(t\d+) = t\d+ \+ 1;", joined)
    assert res and phi, body
    base = re.fullmatch(r"(t\d+)\.field_0x18 = %s;" % res.group(1), body[-3])
    assert base, body
    assert body[-2] == f"{base.group(1)}.field_0x20 = {phi.group(1)};", body
    body = ahead([("mov", "x8, #0"), ("add", "x8, x8, #1"), ("cmp", "x8, x13"),
                  ("b.lt", "#0x4")], [("stur", "x8, [x1, #7]"), ("ret", "")])
    assert body[-2] == "x1.field_0x8 = t0;", body
    # A raw write to a register in one arm changes it, though the register then prints as
    # itself, which is also how the value from before the `if` prints: the phi read the
    # entry x1 where the machine had the `umulh`.
    body = lift([("add", "x6, x1, #1"), ("cbz", "x7, #0x10"), ("umulh", "x1, x1, x3"),
                 ("b", "#0x14"), ("add", "x1, x1, #4"), ("stur", "x6, [x4, #7]"),
                 ("stur", "x1, [x4, #15]"), ("ret", "")])
    arm = body[body.index("umulh x1, x1, x3"):body.index("} else {")]
    assert "t1 = x1;" in arm and body[-2] == "x4.field_0x10 = t1;", body
    # ...as does a pointer the arm moves, `x4 += 8;`.
    body = lift([("cbz", "x7, #0x10"), ("ldr", "x0, [x4], #8"), ("str", "x0, [x5, #7]"),
                 ("b", "#0x14"), ("add", "x4, x4, #4"), ("stur", "x4, [x6, #7]"),
                 ("ret", "")])
    arm = body[body.index("x4 += 8;"):body.index("} else {")]
    assert "var t2;" in body and "t2 = x4;" in arm, body
    # A phi bound above an `if` holds what it was bound to only on the paths through the
    # binding. The clean fixture's `resolveAs` jumps into an arm of one from two places
    # outside it, and main declared it inside that arm: `var t1 = x0;`, which those
    # paths never ran, and then read `t1`. The arm a goto enters assigns it itself.
    _needs_capstone()
    from jadart.disasm import (load_instructions, disassemble_range, build_pool_map,
                               function_name_by_pc)
    from jadart.expr import make_arity_resolver
    image, fr, _hdr = load_instructions(CLEAN)
    p2n = function_name_by_pc(image, fr)
    pm, ar = build_pool_map(fr), make_arity_resolver(image)
    cr = next(c for c in image.all_ranges
              if c.pc_offset <= 0xae028 < c.pc_offset + (c.size or 0))
    body = [ln.strip() for ln in lift_function(
        _ann(image, disassemble_range(image, cr), p2n, pm), pm, arity=ar)]
    # Numbering is not the point and moves when another emitter mints a name first: the
    # declaration the goto-entered arm needs must be BARE, with no initialiser.
    assert not any(re.fullmatch(r"var t\d+ = x0;", l) for l in body), body
    assert any(re.fullmatch(r"var t\d+;", l) for l in body), body
    bare = [re.fullmatch(r"var (t\d+);", l).group(1) for l in body
            if re.fullmatch(r"var t\d+;", l) and f"{l[4:-1]} = x0;" in body]
    assert len(bare) == 1, (bare, body)
    assert body.index("L_0xae0b0:") < body.index(f"{bare[0]} = x0;"), body
    # ...and a phi an entered arm sets is set on every path into the `if`'s join, though
    # not on every path through its head: `ui.dart`'s goto into the arm keeps reading it.
    cr = next(c for c in image.all_ranges if c.pc_offset == 0x18d4e4)
    body = [ln.strip() for ln in lift_function(
        _ann(image, disassemble_range(image, cr), p2n, pm), pm, arity=ar)]
    # The call declines its argument list: the `stp x0, x1` before it is x0 and x1 saved
    # round the call and reloaded after, not two pushed arguments (#147). Which number it
    # gets is not the point and has moved twice, with #173 and again with #198, because it
    # counts the values named ahead of it.
    assert any(re.fullmatch(r"var t\d+ = pool_0x2650\.field_0x8\(\.\.\.\);", l)
               for l in body), body

def test_a_raw_line_says_what_the_registers_it_reads_hold():
    # A raw line reads the machine registers it names, and a register tier 3 held as an
    # expression was never assigned in the printed body: `add x1, x1, #8; adcs x1, x1,
    # x3` printed the `adcs` alone, which reads as working on the entry x1 (#120). The
    # line says what each register it reads holds, in a comment, so the printed body
    # still assigns a register only where the machine's own instruction does.
    from jadart.expr import lift_function

    def lift(rows, **kw):
        return [ln.strip() for ln in lift_function(
            [(i * 4, *r, "") for i, r in enumerate(rows)], **kw)]
    assert lift([("add", "x1, x1, #8"), ("adcs", "x1, x1, x3"), ("str", "x1, [x2, #7]"),
                 ("ret", "")])[:2] == ["adcs x1, x1, x3   // x1 holds x1 + 8",
                                       "x2.field_0x8 = x1;"]
    assert lift([("add", "x17, x1, #27"), ("ldar", "w1, [x17]"), ("str", "x1, [x2, #7]"),
                 ("ret", "")])[0] == "ldar w1, [x17]   // x17 holds x1 + 27"
    # A value named before the line is held under its name, and that name is then read.
    assert lift([("add", "x5, x1, #1"), ("adcs", "x1, x1, x3"), ("adcs", "x5, x5, x3"),
                 ("str", "x5, [x4, #7]"), ("ret", "")])[:3] == [
        "var t0 = x1 + 1;", "adcs x1, x1, x3", "adcs x5, x5, x3   // x5 holds t0"]
    # Every register a store-release reads, a role register a value was moved into, and
    # the target of a `br`.
    assert lift([("add", "x1, x2, #8"), ("add", "x17, x3, #15"), ("stlr", "x1, [x17]"),
                 ("ret", "")])[0] == (
        "stlr x1, [x17]   // x1 holds x2 + 8, x17 holds x3 + 15")
    assert lift([("mov", "x22, x1"), ("ldar", "x0, [x22]"), ("str", "x0, [x2, #7]"),
                 ("ret", "")])[0] == "ldar x0, [x22]   // x22 holds x1"
    assert lift([("ldr", "x16, [x26, #0x258]"), ("br", "x16")]) == [
        "br x16   // x16 holds THR.field_0x258"]
    # A call's result only the note mentions is still a call in the code, not folded
    # into the note.
    # The call declares x2 as well, which the store after the raw line reads, so the
    # result takes the number after that declaration (#176). The note still reads the
    # result's name and the call is still a line of its own, which is the point.
    got = lift([("bl", "#0x100"), ("add", "x17, x0, #27"), ("mov", "x0, #0"),
                ("ldar", "w1, [x17]"), ("str", "x1, [x2, #7]"), ("ret", "")])
    res = re.fullmatch(r"var (t\d+) = sub_0x100\(\.\.\.\);", got[1])
    assert re.fullmatch(r"var t\d+;", got[0]) and res, got
    assert got[2] == f"ldar w1, [x17]   // x17 holds {res.group(1)} + 27", got
    # A register that holds itself, or the receiver it was on entry, says nothing.
    # The note reads the loop's NAME for a register the loop writes...
    body = lift([("add", "x17, x14, #7"), ("cbnz", "x3, #0x1c"), ("stlr", "x7, [x17]"),
                 ("add", "x17, x17, #1"), ("tbz", "x9, #63, #0x8"),
                 ("stur", "x7, [x2, #71]"), ("ret", ""), ("ret", "")])
    assert "var t0 = x14 + 7;" in body, body
    assert "stlr x7, [x17]   // x17 holds t0" in body, body
    # ...and the value itself where there is no name, which is what one the loop does not
    # write now has: main carried it because the block before the loop wrote it (#228).
    body = lift([("add", "x17, x14, #7"), ("swp", "x11, x7, [x17]"),
                 ("cbnz", "x3, #0x18"), ("stlr", "x7, [x17]"), ("b.eq", "#0x1c"),
                 ("tbz", "x9, #63, #0xc"), ("b", "#0x1c"), ("stur", "x7, [x2, #71]"),
                 ("ret", "")])
    assert "stlr x7, [x17]   // x17 holds x14 + 7" in body, body
    assert not any(ln.startswith("var t") for ln in body), body
    assert lift([("adcs", "x1, x1, x3"), ("adcs", "x1, x1, x3"), ("str", "x1, [x2, #7]"),
                 ("ret", "")])[:2] == ["adcs x1, x1, x3", "adcs x1, x1, x3"]
    assert lift([("ldar", "w0, [x1]"), ("ret", "")], receiver={"x1": "this"})[0] == (
        "ldar w0, [x1]")

def test_a_bitfield_reads_as_wide_as_its_field():
    # `sbfx` carries the top bit of its field up, and tier 3 printed it as `(x >> lsb) &
    # mask`, which clears it; `sbfiz` and `ubfiz` printed `x << lsb` and kept every bit
    # above the field; and `ubfx` put its source in unbracketed, so `x1 & x2` read as
    # `x1 & (x2 >> 4)` (#124). Each form is checked against the arm64 definition on
    # random inputs, in Dart's 64-bit arithmetic.
    import random
    from jadart.expr import lift_function

    def text(mn, lsb, width, rows=()):
        body = lift_function([(i * 4, r[0], r[1], "") for i, r in enumerate(
            list(rows) + [(mn, f"x5, x3, #{lsb}, #{width}"), ("stur", "x5, [x2, #7]"),
                          ("ret", "")])])
        return body[0].strip().split(" = ", 1)[1].rstrip(";")
    assert text("sbfx", 4, 8) == "(x3 >> 4).toSigned(8)"
    assert text("sbfiz", 3, 8) == "x3.toSigned(8) << 3"
    assert text("ubfiz", 3, 8) == "(x3 & 0xff) << 3"
    assert text("sbfx", 4, 60) == "x3 >> 4" and text("ubfx", 4, 60) == "x3 >>> 4"
    assert text("ubfx", 4, 8, [("and", "x3, x1, x2")]) == "((x1 & x2) >> 4) & 0xff"
    # A negative literal is no atom to Dart's `.`: `-128.toSigned(8)` is
    # `-(128.toSigned(8))`, 1024 where the machine has -1024 for `<< 3`.
    assert text("sbfiz", 3, 8, [("mov", "x3, #-0x80")]) == "(-128).toSigned(8) << 3"
    # The Smi tag keeps the reading it had, the value. The untag reads bit 31 as the
    # sign, which `x3 >> 1` did not for an x3 whose top half disagrees (#285). The class
    # id read out of a tags word keeps its brackets.
    assert text("sbfiz", 1, 31) == "x3" and text("sbfx", 1, 31) == "x3.toSigned(32) >> 1"
    assert text("ubfx", 12, 20) == "(x3 >> 12) & 0xfffff"

    mask = (1 << 64) - 1

    def signed(v, n):
        v &= (1 << n) - 1
        return v - (1 << n) if v >> (n - 1) & 1 else v

    def arm(mn, x, lsb, width):
        field = (1 << width) - 1
        return {"ubfx": (x >> lsb) & field, "sbfx": signed(x >> lsb, width),
                "ubfiz": (x & field) << lsb, "sbfiz": signed(x, width) << lsb}[mn] & mask

    def dart(t, x):
        t = t.replace("x3 >>> ", "_u(x3) >> ")
        t = re.sub(r"(\([^()]*\)|\w+)\.toSigned\((\d+)\)", r"_s(\1, \2)", t)
        t = re.sub(r"\bx3\b", "_x", t)
        env = {"_s": signed, "_u": lambda v: v & mask, "_x": signed(x, 64)}
        return eval(t, env) & mask
    rng = random.Random(124)
    for mn in ("ubfx", "sbfx", "ubfiz", "sbfiz"):
        for lsb, width in ((4, 8), (4, 60), (3, 61), (12, 20), (7, 1), (5, 32), (1, 8),
                           (1, 63), (1, 31)):
            if mn == "sbfiz" and (lsb, width) in ((1, 63), (1, 31)):
                continue                                    # the Smi tag
            t = text(mn, lsb, width)
            for _ in range(200):
                x = rng.getrandbits(64)
                assert dart(t, x) == arm(mn, x, lsb, width), (mn, lsb, width, t, hex(x))

def test_a_raw_line_survives_a_pinned_name_the_hoist_took():
    """`_verbatim` reads `_pin`'s lines as declarations, and a hoisted one is not.

    A name the hoist took declares at the top of the body and ASSIGNS where the value is,
    `tN = ...;`, which `_DECL_RE` does not match because it requires `var`. `_verbatim`
    matched unconditionally to collect the names into `raw_names`, so such a line raised
    AttributeError, and an exception that escapes is exit 3: a bug in Jadart rather than
    bad input, which the threat model puts above a wrong answer.

    Nothing on either fixture hoists a name `_pin` writes out, which is why #212 shipped
    this green. The first change that makes `_verbatim` fire more often finds it, and one
    did: see #176."""
    from jadart.expr import Lifter, State, _DECL_RE

    hoisted = "t7 = x1 + 8;"
    assert _DECL_RE.match(hoisted) is None, "the premise: it is not a declaration"
    lf = Lifter.__new__(Lifter)
    lf.raw_names = set()
    lf._printed_regs = set()
    lf._live_after = 0
    lf.alias = {}
    lf._pin = lambda st, r, live=None: [hoisted, "var t8 = x2;"]
    out = Lifter._verbatim(lf, State(), "adcs", "x1, x1, x3", "x1, x1, x3")
    assert any(l.startswith("adcs") for l in out), out
    # Only the declaration contributes a name; the assignment is already declared above.
    assert lf.raw_names == {"t8"}, lf.raw_names


def test_liveness_is_asked_about_one_register_however_the_operand_spells_it():
    """`_reg_mask` maps to the LIVENESS identity, so a state key asks the right question.

    d0, s0, v0, q0, h0, b0 and v0.16b are one machine register, and `_regs` builds every
    liveness set calling them all `d0`. The STATE is keyed by `canon` instead, which keeps
    the view spellings apart on purpose, so a value written under one is not read back
    under another; that is what the test below this one is about (#114).

    So the two are different names for one register, and a caller holding a state key asks
    about liveness with the wrong one. The bit table cannot say so: an unknown name MINTS
    a bit, which no liveness set holds, so the answer is a confident "not live". 1,169
    frame reloads off FP, every one of them read again, were passed over for exactly that
    (#198 review). Mapping inside `_reg_mask` makes all fifteen callers right at once.

    `canon` first, because `_fp_n` does not match `s`: that is what makes `s3` right too.
    """
    from jadart.expr import _fp_n, _reg_mask, _regs, canon

    d = _reg_mask(("d3",))
    for r in ("d3", "s3", "v3", "q3", "h3", "b3", "v3.16b", "v3.d[0]"):
        assert _reg_mask((r,)) == d, r
        # ...and the liveness SETS agree with the mask, since both go through `_regs`.
        assert _reg_mask(tuple(_regs((r,)))) == d, r
    assert _reg_mask(("w3",)) == _reg_mask(("x3",)) != d
    # The state does NOT fold them, and must not: `_other_views` is what needs them apart.
    assert canon("q3") == "q3" and canon("v3.16b") == "v3.16b"
    assert canon("s3") == "d3" and _fp_n("s3") is None


def test_an_access_narrower_than_a_word_says_how_many_bytes_it_moved():
    """A byte or halfword access says its width, and four keeps the plain spelling (#221).

    A byte-offset spelling said nothing about how many bytes moved, so `strb w0` printed
    the same text as `str x0` and a reader could not tell a byte store from a word store.
    The store side overstated and the load side understated.

    FOUR is the exception. This target compresses pointers: 17,789 of the 20,941 four-byte
    loads on the clean build are followed by `add xN, xN, x28, lsl #32`, the
    decompression, so a four-byte read is what a reference field read looks like and the
    lifter prints the pointer it becomes. Marking those would decorate the most common
    read in the output with the width of a representation rather than of a value. The
    genuinely unsaid widths are one and two, 5,662 accesses, and sixteen, which had no
    other spelling at all (#209).
    """
    from jadart.expr import lift_function

    def lift(rows):
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])]

    for mn, reg, want in (("strb", "w0", "x2.field1_0x11 = x0;"),
                          ("strh", "w0", "x2.field2_0x11 = x0;"),
                          ("str", "w0", "x2.field_0x11 = x0;"),
                          ("str", "x0", "x2.field_0x11 = x0;")):
        assert lift([(mn, f"{reg}, [x2, #0x10]"), ("ret", "")])[0] == want, (mn, reg)
    # The load side, and the sign, which the width alone does not say: the shift pair is
    # how `_extended` spells a sign-extending load, and the ordinary load path said
    # neither the width nor the sign before.
    for mn, reg, want in (
            ("ldrb", "w0", "x2.field_0x8 = x1.field1_0x11;"),
            ("ldrh", "w0", "x2.field_0x8 = x1.field2_0x11;"),
            ("ldr", "w0", "x2.field_0x8 = x1.field_0x11;"),
            ("ldrsb", "x0", "x2.field_0x8 = x1.field1_0x11 << 56 >> 56;"),
            ("ldrsh", "x0", "x2.field_0x8 = x1.field2_0x11 << 48 >> 48;")):
        got = lift([(mn, f"{reg}, [x1, #0x10]"), ("stur", "x0, [x2, #7]"), ("ret", "")])
        assert got[0] == want, (mn, reg, got)
    # One write's bytes have more than one spelling now, so a live value that reads any of
    # them is still written out first. Without that these read memory the write changed.
    for store in (("strb", "w0, [x1, #0x10]"), ("strh", "w0, [x1, #0x10]")):
        got = lift([("ldr", "x3, [x1, #0x10]"), store,
                    ("stur", "x3, [x2, #7]"), ("ret", "")])
        assert got[0] == "var t0 = x1.field_0x11;", (store, got)
        assert got[2] == "x2.field_0x8 = t0;", (store, got)
    # and the other way round: an eight-byte write over a live one-byte read
    got = lift([("ldrb", "w3, [x1, #0x10]"), ("str", "x0, [x1, #0x10]"),
                ("stur", "x3, [x2, #7]"), ("ret", "")])
    assert got[0] == "var t0 = x1.field1_0x11;", got
    assert got[2] == "x2.field_0x8 = t0;", got


def test_an_access_of_sixteen_bytes_says_so_and_not_eight():
    """A 16-byte access is spelled `.field16_0x8`, and the bytes it covers are matched
    under every spelling of them (#209).

    Sixteen bytes had no spelling at all, so `ldr q0` printed the eight-byte read of its
    low half and `str q0` an eight-byte write: a 16-byte copy came out character for
    character identical to an 8-byte one and named half the bytes it moved. 195 printed
    assignments on each fixture move sixteen bytes. The width goes in the spelling
    because this output has no types to put it in, which is where Ghidra puts it
    (`undefined1 [16]`, sliced `._0_8_`) and where Hex-Rays puts it (`_OWORD`).
    """
    from jadart.expr import lift_function

    def lift(rows):
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])]

    # A 16-byte copy and an 8-byte copy are the same four instructions apart from the
    # register file, and used to print the same two lines.
    assert lift([("ldr", "q0, [x1, #0x10]"), ("str", "q0, [x2, #0x20]"), ("ret", "")]
                )[0] == "x2.field16_0x21 = x1.field16_0x11;"
    assert lift([("ldr", "d0, [x1, #0x10]"), ("str", "d0, [x2, #0x20]"), ("ret", "")]
                )[0] == "x2.field_0x21 = x1.field_0x11;"
    # A declined 16-byte reload off the frame names the read, now that there is a text
    # for it; it kept the load's own register before, which the body never assigns.
    frame = [("stp", "x29, x30, [x15, #-0x10]!"), ("mov", "x29, x15"),
             ("sub", "x15, x15, #0x20"), ("bl", "#0x100"),
             ("ldur", "q1, [x29, #-0x18]"), ("stur", "q1, [x2, #15]"), ("ret", "")]
    got = lift(frame)
    # The base is the name the call declares for x2, which it clobbers like any other
    # volatile register (#216).
    assert ["var t2 = (FP - 24).field16_0x1;", "t0.field16_0x10 = t2;"] == [
        ln for ln in got if "field16" in ln], got
    # A narrower access through that file still declines rather than claim a width: an
    # `s` read is four bytes and a masked double is not what the machine loaded.
    narrow = frame[:4] + [("ldur", "s1, [x29, #-0x18]"), ("stur", "s1, [x2, #15]"),
                          ("ret", "")]
    assert any(ln.endswith("= d1;") for ln in lift(narrow)), lift(narrow)

    # The bytes one write covers have more than one spelling now, and no two of them
    # contain each other, so a live value that reads any of them is pinned first. Without
    # that every one of these three reads memory the write had already changed.
    over = lift([("ldr", "x3, [x1, #0x10]"), ("str", "q0, [x1, #0x10]"),
                 ("stur", "x3, [x2, #7]"), ("ret", "")])
    assert over[:3] == ["var t0 = x1.field_0x11;", "x1.field16_0x11 = q0;",
                        "x2.field_0x8 = t0;"], over
    for store in (("str", "x3, [x1, #0x10]"), ("str", "x3, [x1, #0x18]")):
        inside = lift([("ldr", "q0, [x1, #0x10]"), store,
                       ("str", "q0, [x2, #0x20]"), ("ret", "")])
        assert inside[0] == "var t0 = x1.field16_0x11;", (store, inside)
        assert inside[2] == "x2.field16_0x21 = t0;", (store, inside)
    # The note that reads a stored literal as a Smi is about one word, so a write wider
    # than a field does not get one.
    from jadart.expr import V, P_ATOM, _smi_note
    assert _smi_note(V("x2.field_0x8", P_ATOM), V("4", P_ATOM)) != ""
    assert _smi_note(V("x2.field16_0x8", P_ATOM), V("4", P_ATOM)) == ""


def test_a_displacement_below_the_base_is_not_a_negative_field_offset():
    """`ldr x16, [x1, #-8]!` is a read at x1 - 8, not field -7 of anything (#236).

    The biased offset came out negative and printed as one, `t3.field_0x-3`. There is no
    field at a negative offset: `.field_0xN` says offset N of the object the base points
    at, so a reader who takes it at face value is reading a claim nothing made. 236 lines
    of the clean export and 2 of the obf one, from 511 accesses over 60 of the clean
    image's ranges, nearly all of them `_quickCopy`'s backward copy loop at 0x1aace0.

    `Lifter._frame_read` was written to avoid exactly this, and its docstring says so, but
    nothing applied the rule to a base that is not a frame register. So the fix is that
    rule for every base: the displacement goes into the base expression and the offset
    stays a field offset, which is what the lifter already prints when the same address
    arrives in a register first.

    The other tools do the same or refuse. Ghidra composes the identical default name,
    `field_0x` + hex, only after `if (ct->getSize() <= suboff || suboff < 0) throw
    LowlevelError("PTRSUB out of bounds into struct")` (printc.cc, PrintC::opPtrsub).
    Hex-Rays moves the negative part into the base: a structure offset applied to a
    negative number "usually converts the whole (var-num) expression into the
    CONTAINING_RECORD macro". Binary Ninja cannot spell one, a member offset being
    unsigned.
    """
    from jadart.expr import lift_function

    def lift(rows):
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])]

    # The two instructions the issue cites, 0x1aadf4 and 0x1aadf8. The rebased base is
    # the same text the write-back prints on the next line, so the two agree on sight.
    got = lift([("ldr", "x16, [x1, #-8]!"), ("str", "x16, [x0, #-8]!"), ("ret", "")])
    assert got[:4] == ["var t0 = (x1 - 8).field_0x1;", "x1 -= 8;",
                       "(x0 - 8).field_0x1 = t0;", "x0 -= 8;"], got
    # 0x1aae00, the four-byte step, and 0x1aae10, the pair: both halves rebase, the
    # second one slot on from the first.
    assert lift([("ldr", "w16, [x1, #-4]!"), ("ret", "")])[0] == \
        "var t0 = (x1 - 4).field_0x1;"
    assert lift([("ldp", "x16, x17, [x1, #-0x10]!"), ("ret", "")])[:2] == [
        "var t0 = (x1 - 16).field_0x1;", "var t1 = (x1 - 8).field_0x1;"]
    # A narrower access keeps saying its width; only the offset moves.
    assert lift([("ldrh", "w16, [x1, #-2]!"), ("ret", "")])[0] == \
        "var t0 = (x1 - 2).field2_0x1;"
    # A store below the base, no write-back: both halves of the pair rebase too.
    assert lift([("stp", "x3, x4, [x1, #-0x10]"), ("ret", "")])[:2] == [
        "(x1 - 16).field_0x1 = x3;", "(x1 - 8).field_0x1 = x4;"]

    # What must NOT move. A displacement of -1 off a tagged pointer is offset 0, the
    # object header, because kHeapObjectTag is 1; it is the tag and not a step below the
    # base, and 11,184 of the clean image's 11,695 negative displacements are it.
    assert lift([("ldur", "x2, [x1, #-1]"), ("mov", "x0, x2"), ("ret", "")])[0] == \
        "return x1.tags;"
    # An untagged role register keeps its exact offset (docs/usage.md), and a positive
    # displacement keeps the bias. Neither is rebased.
    assert lift([("ldr", "x2, [x26, #0x68]"), ("mov", "x0, x2"), ("ret", "")])[0] == \
        "return THR.field_0x68;"
    assert lift([("ldur", "x2, [x1, #7]"), ("mov", "x0, x2"), ("ret", "")])[0] == \
        "return x1.field_0x8;"
    # And the rebase is exact for BOTH representations, because it folds the raw
    # displacement rather than the biased offset: the address is base + disp either way.
    # THR - 8 is one byte below where the old spelling's `THR.field_0x-8` would have read.
    assert lift([("ldur", "x2, [x26, #-8]"), ("mov", "x0, x2"), ("ret", "")])[0] == \
        "return (THR - 8).field_0x1;"


def test_a_copy_of_thr_is_read_and_written_at_the_offset_as_written():
    """THR is untagged in whichever register holds it (#273).

    `_byte_off` asked the register's NAME, so a read through a copy of x26 took the
    heap-object tag bias: `mov x25, x26; ldr x9, [x25, #0x7d0]` printed
    `THR.field_0x7d1` beside `THR.field_0x6c8` read through x26 itself, one Thread
    spelled two ways, the odd offset no slot at all. The walk already carries the copy
    as `THR`, through a move, a copy of the copy and a spill and its reload, so the
    value decides now and the offset is spelled as for x26."""
    lift = _lift_rows
    # The FFI call sequence at 0x1390e8 on the clean fixture, cut down to its reads.
    assert lift([("mov", "x25, x26"), ("ldr", "x9, [x25, #0x7d0]"),
                 ("str", "x9, [x26, #0x6c8]"), ("ret", "")])[0] == \
        "THR.field_0x6c8 = THR.field_0x7d0;"
    # A store through a copy of the copy, and a displacement below a copy, which goes
    # into the base as it does off x26.
    got = lift([("mov", "x25, x26"), ("mov", "x0, x25"), ("str", "x1, [x0, #0x6c8]"),
                ("ldur", "x2, [x25, #-8]"), ("stur", "x2, [x19, #7]"), ("ret", "")])
    assert got[:2] == ["THR.field_0x6c8 = x1;",
                       "x19.field_0x8 = (THR - 8).field_0x1;"], got
    # An element off a copy keeps its displacement, as one off x26 does. It was
    # dropped, which named another slot.
    assert lift([("mov", "x25, x26"), ("add", "x0, x25, x1, lsl #3"),
                 ("ldr", "x2, [x0, #0x18]"), ("mov", "x0, x2"), ("ret", "")]) == \
        ["return THR[x1 + 3];"]
    # A spill of the copy, and its reload after a call: the fixture's second read.
    got = lift([("mov", "x25, x26"), ("stur", "x25, [x29, #-0x50]"), ("bl", "#0x100"),
                ("ldur", "x0, [x29, #-0x50]"), ("ldr", "x9, [x0, #0x7d8]"),
                ("stur", "x9, [x19, #7]"), ("ret", "")])
    assert "x19.field_0x8 = THR.field_0x7d8;" in got, got

    # What must not move. An interior pointer is not the thread, an ordinary register
    # keeps the bias, and x26 itself reads as it did.
    assert lift([("add", "x25, x26, #0x10"), ("ldr", "x0, [x25, #8]"),
                 ("ret", "")]) == ["return (THR + 16).field_0x9;"]
    assert lift([("ldr", "x0, [x1, #0x7d0]"), ("ret", "")]) == \
        ["return x1.field_0x7d1;"]
    assert lift([("ldr", "x0, [x26, #0x7d0]"), ("ret", "")]) == \
        ["return THR.field_0x7d0;"]


def test_a_copy_of_thr_is_the_thread_only_while_every_way_in_holds_it():
    """The role is the value the walk holds, so it ends where that value does (#273). A
    write or a call that clobbers the copy ends it, a join keeps it only where every way
    in holds the thread, and a section no edge leads into hands the body nothing. The
    guards print the same on main; the assertions that the role is KEPT do not."""
    from jadart.cfg import UNREACHED
    lift = _lift_rows
    # Overwritten: 0x213b2c on the clean fixture. x3 is the thread for one read, then the
    # object it loads, and the read through that is a tagged field again.
    got = lift([("mov", "x3, x26"), ("ldr", "x4, [x3, #0x688]"),
                ("ldr", "x3, [x4, #0x20]"), ("ldr", "x4, [x3, #0x430]"),
                ("stur", "x4, [x19, #7]"), ("ret", "")])
    assert got[0] == "x19.field_0x8 = THR.field_0x688.field_0x21.field_0x431;", got
    # Clobbered: x1 is volatile, so after the call it holds a value nobody knows.
    got = lift([("mov", "x1, x26"), ("bl", "#0x100"), ("ldr", "x9, [x1, #0x7d0]"),
                ("stur", "x9, [x19, #7]"), ("ret", "")])
    store = next(ln for ln in got if ln.startswith("x19.field_0x8 = "))
    assert re.fullmatch(r"x19\.field_0x8 = t\d+\.field_0x7d1;", store), got

    # A join keeps it where both arms copy the thread, and not where one copies x1.
    def join(other):
        return lift([("cbz", "x3, #0xc"), ("mov", "x25, x26"), ("b", "#0x10"),
                     ("mov", other), ("ldr", "x9, [x25, #0x7d0]"),
                     ("stur", "x9, [x19, #7]"), ("ret", "")])
    assert join("x25, x26")[0] == "x19.field_0x8 = THR.field_0x7d0;", join("x25, x26")
    assert join("x25, x1")[0] == "x19.field_0x8 = x25.field_0x7d1;", join("x25, x1")

    # A section no edge leads into copies the thread and falls into the join: the body
    # does not take the copy from it, and the block printed again under the section,
    # from the section's own state, does (#266).
    got = lift([("cbz", "x3, #0x10"), ("mov", "x25, x1"), ("b", "#0x10"),
                ("mov", "x25, x26"), ("ldr", "x9, [x25, #0x7d0]"),
                ("stur", "x9, [x19, #7]"), ("ret", "")])
    at = got.index("// " + UNREACHED)
    assert got[:at] == ["x19.field_0x8 = x25.field_0x7d1;", "return x0;"], got
    assert got[at + 1:] == ["L_0xc:", "x19.field_0x8 = THR.field_0x7d0;",
                            "return x0;"], got
    # ...and the section after a trap, falling into a join a goto also reaches, hands it
    # nothing (#237's arrival guard): the copy at 0x8 never reaches the read at 0xc.
    got = lift([("cbz", "x1, #0x18"), ("brk", "#0"), ("mov", "x25, x26"),
                ("ldr", "x9, [x25, #0x7d0]"), ("stur", "x9, [x19, #7]"), ("ret", ""),
                ("mul", "x5, x6, x12"), ("cbz", "x8, #0xc"), ("cbz", "x9, #0x2c"),
                ("sub", "x7, x7, #1"), ("cbnz", "x7, #0x18"), ("add", "x4, x4, #2"),
                ("ret", "")])
    assert "x19.field_0x8 = x25.field_0x7d1;" in got, got
    assert not [ln for ln in got if "THR" in ln], got


def test_a_copy_of_r10_is_the_thread_on_arm32_too():
    """arm32 keeps the thread in r10 and reads null, true and false out of it, so a copy
    of r10 reads them as r10 does, and its other slots at the offset as written (#273).
    arm32 is not in LIFTABLE_ARCHS, so this binds the target directly, as the arm32
    target test does. The width is matched loosely: it is not what this is about."""
    from jadart import expr as E
    rows = [("mov", "r4, sl"), ("ldr", "r0, [r4, #0x38]"), ("ldr", "r1, [r4, #0x40]"),
            ("str", "r1, [r4, #0x44]"), ("str", "r0, [r2, #7]"), ("bx", "lr")]
    with E.use_target(E.ARM32):
        body = [ln.strip() for ln in E._lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)],
            None, None, None, "  ", 1, None)]
    assert re.fullmatch(r"THR\.field\d*_0x44 = THR\.field\d*_0x40;", body[0]), body
    assert re.fullmatch(r"r2\.field\d*_0x8 = true;", body[1]), body
    assert body[-1] == "return true;", body
    assert E._T is E.ARM64


def test_the_ffi_sequence_on_the_clean_fixture_reads_the_thread_as_written():
    """#273 as reported, through the library API and `lift`: the closure at 0x1390ac
    copies x26 into x25, spills the copy, and reads Thread+0x7d0 through it and
    Thread+0x7d8 through its reload, and both print as the offsets they are."""
    _needs_capstone()
    import contextlib
    import io
    from jadart import cli
    body = [ln.strip() for ln in jadart.decompile(CLEAN, "0x1390e8")[0]["body"]]
    assert "THR.field_0x6c8 = THR.field_0x7d0;" in body, body
    assert "THR.field_0x6c8 = THR.field_0x7d8;" in body, body
    odd = [ln for ln in body for m in re.findall(r"\bTHR\.field\d*_0x([0-9a-f]+)", ln)
           if int(m, 16) & 1]
    assert not odd, odd
    out = io.StringIO()
    with contextlib.redirect_stdout(out):
        assert cli.main(["lift", CLEAN, "0x1390e8"]) == 0
    assert "var t3 = THR.field_0x7d0(...);" in out.getvalue(), out.getvalue()



def test_a_code_object_called_through_lr_is_read_at_its_tagged_offset():
    """LR is the role of a return address, not of every value in x30 (#280).

    `_byte_off` kept x30 in the untagged roles by its name, so a load through it took no
    heap-object tag bias. From 3.3 on, AOT code calls a pool Code through LR
    (`Assembler::BranchLink`, `code_reg = FLAG_precompiled_mode ? LR : CODE_REG`):
    `ldr x30, [x27, #0x13e0]; ldur x30, [x30, #7]` reads Code+8, the entry point, and it
    printed `pool_0x13e0.field_0x7(...)` beside `pool_0x13e8.field_0x8(...)` for the
    same read through x8. A value the code put in LR is spelled as in any register."""
    lift = _lift_rows
    # The call, off the pool, off the thread and off a far pool entry.
    assert lift([("ldr", "x30, [x27, #0x10]"), ("ldur", "x30, [x30, #7]"),
                 ("blr", "x30"), ("ret", "")]) == ["return pool_0x10.field_0x8(...);"]
    assert lift([("ldr", "x30, [x26, #0xd0]"), ("ldur", "x30, [x30, #7]"),
                 ("blr", "x30"), ("ret", "")]) == \
        ["return THR.field_0xd0.field_0x8(...);"]
    assert lift([("add", "x30, x27, #9, lsl #12"), ("ldr", "x30, [x30, #0x7e8]"),
                 ("ldur", "x30, [x30, #7]"), ("blr", "x30"), ("ret", "")]) == \
        ["return pool_0x97e8.field_0x8(...);"]
    # A read into another register, a store through LR, and a value moved into it.
    got = lift([("ldr", "x30, [x27, #0x10]"), ("ldur", "x0, [x30, #7]"),
                ("stur", "x0, [x19, #7]"), ("ret", "")])
    assert "x19.field_0x8 = pool_0x10.field_0x8;" in got, got
    assert lift([("ldr", "x30, [x27, #0x10]"), ("stur", "x0, [x30, #7]"),
                 ("ret", "")])[0] == "pool_0x10.field_0x8 = x0;"
    assert lift([("mov", "x30, x1"), ("ldur", "x0, [x30, #7]"), ("ret", "")]) == \
        ["return x1.field_0x8;"]
    # A copy of the thread in LR is the thread, as in any register (#273).
    assert lift([("mov", "x30, x26"), ("ldr", "x0, [x30, #0x68]"), ("ret", "")]) == \
        ["return THR.field_0x68;"]


def test_lr_is_untagged_only_while_every_way_in_holds_a_return_address():
    """LR holds a return address on entry and after a call, and nowhere else the graph
    cannot show: a join keeps it only where every way in holds one, and code no edge
    reaches holds none (#280). Where it is not shown, a read through LR takes the bias,
    as one through any register of unknown value does. The entry value, a call's return
    address and a join every way into which holds one are guards and print the same on
    main; a join or a loop head one way into which does not, and code no edge reaches,
    do not."""
    from jadart.cfg import UNREACHED
    lift = _lift_rows
    read = [("ldr", "x0, [x30, #8]"), ("stur", "x0, [x19, #7]"), ("ret", "")]

    def through(rows):
        return [ln for ln in rows if ln.startswith("x19.field_0x8 = ")]
    # Guards: the entry value, what a call leaves, and a call after a pool load.
    assert through(lift(read)) == ["x19.field_0x8 = LR.field_0x8;"]
    got = through(lift([("bl", "#0x100")] + read))
    assert len(got) == 1 and re.fullmatch(r"x19\.field_0x8 = t\d+\.field_0x8;",
                                          got[0]), got
    got = through(lift([("ldr", "x30, [x27, #0x10]"), ("bl", "#0x100")] + read))
    assert len(got) == 1 and got[0].endswith(".field_0x8;"), got

    # A join: kept where neither arm writes LR and where both call, not where one arm
    # loads a pool object into it.
    def join(arm):
        return through(lift([("cbz", "x2, #0xc"), arm, ("nop", "")] + read))
    assert join(("add", "x3, x3, #1")) == ["x19.field_0x8 = LR.field_0x8;"]
    assert join(("ldr", "x30, [x27, #0x10]")) == ["x19.field_0x8 = x30.field_0x9;"]
    got = through(lift([("cbz", "x2, #0xc"), ("bl", "#0x100"), ("b", "#0x10"),
                        ("bl", "#0x200")] + read))
    assert len(got) == 1 and got[0].endswith(".field_0x8;"), got
    # A loop head, entered with the return address and come back to with a pool object.
    got = lift([("ldr", "x0, [x30, #8]"), ("stur", "x0, [x19, #7]"),
                ("ldr", "x30, [x27, #0x10]"), ("subs", "x2, x2, #1"), ("b.ne", "#0x0"),
                ("ret", "")])
    assert through(got) == ["x19.field_0x8 = t1.field_0x9;"], got

    # Code no edge reaches falls into the read: the body has no proof there, and the
    # block printed again under the section, from the section's pool load, takes it too.
    got = lift([("cbz", "x3, #0x10"), ("mov", "x25, x1"), ("b", "#0x10"),
                ("ldr", "x30, [x27, #0x10]")] + read)
    at = got.index("// " + UNREACHED)
    assert through(got[:at]) == ["x19.field_0x8 = LR.field_0x9;"], got
    assert through(got[at:]) == ["x19.field_0x8 = pool_0x10.field_0x9;"], got

    # The dispatch-table call: LR is the index there, an interior value no read goes
    # through, and it prints as it did.
    assert lift([("sub", "x30, x0, #0xfda"), ("ldr", "x30, [x21, x30, lsl #3]"),
                 ("blr", "x30"), ("ret", "")]) == \
        ["var t0 = dispatch(...);   // virtual dispatch", "return t0;"]


def test_lr_on_arm32_rows_is_untagged_only_as_a_return_address():
    """r14 is arm32's LR and the same rule holds there: a Code object it is loaded with is
    read at its tagged offset, the entry value and a call's return address at the offset
    as written (#280). arm32 is not in LIFTABLE_ARCHS, so no command lifts its rows; this
    binds the target directly, as the arm32 tests do. The width is matched loosely."""
    from jadart import expr as E

    def lift(rows):
        with E.use_target(E.ARM32):
            return [ln.strip() for ln in E._lift_function(
                [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)],
                None, None, None, "  ", 1, None)]
    read = [("ldr", "r0, [lr, #3]"), ("str", "r0, [r1, #3]"), ("bx", "lr")]
    got = lift([("ldr", "lr, [r5, #0x1f]")] + read)
    assert re.fullmatch(r"r1\.field\d*_0x4 = pool_0x1f\.field\d*_0x4;", got[0]), got
    got = lift(read)
    assert re.fullmatch(r"r1\.field\d*_0x4 = LR\.field\d*_0x3;", got[0]), got
    got = lift([("bl", "#0x100")] + read)
    assert any(re.fullmatch(r"r1\.field\d*_0x4 = \w+\.field\d*_0x3;", ln)
               for ln in got), got
    assert E._T is E.ARM64


def test_get_ffi_native_resolver_on_the_clean_fixture_calls_the_code_entry_point():
    """#280 as reported: 0x25a0 on the clean fixture calls two pool Codes through their
    entry points, the first through LR and the second through x8, and both read Code+8.
    Through the library API and `lift`."""
    _needs_capstone()
