def test_the_low_doubleword_lane_of_a_v_register_reads_what_dn_holds():
    """`v0.d[0]` is the low 64 bits of the register `d0` names, so a read of it reads d0.

    Keyed apart, the read found nothing under its own spelling and fell back to the bare
    operand. The printed body never assigns that, so under the printed-body rule it read
    as the value the function came in with: 31 lines on each fixture read the double a
    call had just returned as the entry v0. Every lane operand in both fixtures is this
    spelling and all 62 of them are reads, so folding it is the whole of that class
    (#209). Folded in `canon`, the one place, so a write to the lane lands on d0 too,
    which is what it overwrites (#134).
    """
    from jadart.expr import canon, lift_function

    assert canon("v0.d[0]") == "d0" and canon("v12.d[0]") == "d12"
    # Not the upper lane, which d0 does not name (#134), and not a whole-register view,
    # which is wider than d0 and is kept apart on purpose (#114).
    assert canon("v0.d[1]") == "v0.d[1]" and canon("v0.16b") == "v0.16b"
    assert canon("q0") == "q0" and canon("vx.d[0]") == "vx.d[0]"

    def lift(rows):
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])]

    # A double read from memory, then its bits read through the lane: the read says what
    # was loaded, where it printed the register the body never assigns.
    out = lift([("ldur", "d0, [x1, #0x17]"), ("mov", "x0, v0.d[0]"),
                ("stur", "x0, [x2, #7]"), ("ret", "")])
    assert out[0] == "x2.field_0x8 = x1.field_0x18;", out
    # The shape the fixtures have, the isInfinite test on a double a call returned: the
    # lane carries the call's result and not the register it came back in.
    out = lift([("bl", "#0x100"), ("mov", "x0, v0.d[0]"),
                ("and", "x0, x0, #0x7fffffffffffffff"),
                ("stur", "x0, [x2, #7]"), ("ret", "")])
    assert "t0.field_0x8 = t1 & 0x7fffffffffffffff;" in out, out
    # An expression, not only a name: the lane reads whatever d0 holds.
    out = lift([("fadd", "d0, d0, d1"), ("mov", "x0, v0.d[0]"),
                ("stur", "x0, [x2, #7]"), ("ret", "")])
    assert out[0] == "x2.field_0x8 = d0 + d1;", out
    # The write side, which neither fixture holds: an insert into the lane overwrites the
    # whole of d0, and it used to land on a key nothing reads, leaving d0 reading as the
    # entry value with no printed assignment anywhere.
    out = lift([("ldur", "d0, [x1, #0x17]"), ("mov", "v0.d[0], x3"),
                ("stur", "d0, [x2, #7]"), ("ret", "")])
    assert out[0] == "x2.field_0x8 = x3;", out
    # `ins` and `fmov` of a lane print the instruction instead, and a raw line is itself a
    # printed assignment, so d0 after one is read as that line left it (#187).
    for mn in ("ins", "fmov"):
        out = lift([("ldur", "d0, [x1, #0x17]"), (mn, "v0.d[0], x3"),
                    ("stur", "d0, [x2, #7]"), ("ret", "")])
        assert out[:2] == [f"{mn} v0.d[0], x3", "x2.field_0x8 = d0;"], (mn, out)


def test_a_write_to_any_view_of_a_simd_register_reaches_the_double_in_it():
    # d0, v0.16b and q0 are one register, and tier 3 tracked a double under the spelling
    # it was written with: `eor v0.16b, v0.16b, v0.16b` (how the VM loads 0.0), `movi`,
    # `ldr q0` and `ins v0.d[0]` all left d0 describing the double loaded before them,
    # so the store after printed that (#114).
    from jadart.expr import lift_function

    def lift(mid):
        rows = [(0, "ldur", "d0, [x20, #7]", ""), mid, (8, "stur", "d0, [x21, #7]", ""),
                (12, "ret", "", "")]
        return [ln.strip() for ln in lift_function(rows)]

    # An `if` that leaves 0.0 in d1 on one arm names it at the join, unless the other
    # arm's d1 is the bare register: a join inside that arm lost the value, which reads
    # just like the d1 from before the `if`, and the name would carry that one down an
    # arm that loaded a field.
    # The `nop` after the `b` is a block nothing reaches, placed after the body since
    # #266, and the label its goto names keeps the arm it opens from vanishing.
    rows = [("cbz", "x0, #0x10"), ("movi", "d1, #0"), ("b", "#0x24"), ("nop", ""),
            ("cbz", "x2, #0x1c"), ("ldur", "d1, [x3, #7]"), ("b", "#0x20"),
            ("ldur", "d1, [x3, #0xf]"), ("nop", ""), ("stur", "d1, [x4, #7]"),
            ("ret", "")]
    assert [ln.strip() for ln in lift_function(
        [(i * 4, *r, "") for i, r in enumerate(rows)])][:5] == [
        "if (x0 == 0) {", "L_0x10:", "}", "x4.field_0x8 = d1;", "return x0;"]

    # the two ways the VM zeroes a double are 0.0
    for mid in ((4, "eor", "v0.16b, v0.16b, v0.16b", ""), (4, "movi", "v0.2d, #0", ""),
                (4, "movi", "d0, #0", "")):
        assert lift(mid) == ["DISPATCH.field_0x7 = 0.0;", "return 0.0;"], mid
    # anything else that writes the register leaves the double unknown, not stale
    for mid, raw in (((4, "ldr", "q0, [x22, #0x10]", ""), []),
                     ((4, "ins", "v0.d[0], x3", ""), ["ins v0.d[0], x3"]),
                     ((4, "eor", "v0.16b, v0.16b, v1.16b", ""), []),
                     ((4, "movi", "v0.2d, #0xff", ""), ["movi v0.2d, #0xff"])):
        assert lift(mid) == raw + ["DISPATCH.field_0x7 = d0;", "return d0;"], mid
    # and another register's write leaves it alone
    assert lift((4, "eor", "v1.16b, v1.16b, v1.16b", "")) == [
        "DISPATCH.field_0x7 = x20.field_0x8;", "return x20.field_0x8;"]
    # A q-register copy keeps reading as one, and a write to d0 in between ends it.
    copy = [(0, "ldr", "q0, [x1, #0x10]", ""), (4, "str", "q0, [x2, #0x10]", ""),
            (8, "ret", "", "")]
    stale = copy[:1] + [(4, "fmov", "d0, #1.0", ""), (8, "str", "q0, [x2, #0x10]", ""),
                        (12, "ret", "", "")]
    kept = [ln.strip() for ln in lift_function(copy)]
    ended = [ln.strip() for ln in lift_function(stale)]
    # `field16`, both sides: these move SIXTEEN bytes, and with the eight-byte spelling
    # the copy was character for character an eight-byte one and named half the bytes it
    # moved (#209).
    assert kept[0] == "x2.field16_0x11 = x1.field16_0x11;", kept
    assert ended[0] == "x2.field16_0x11 = q0;", ended
    # and so does a call, which clobbers the register whatever it is called
    called = copy[:1] + [(4, "bl", "#0x100", ""), (8, "str", "q0, [x2, #0x10]", ""),
                         (12, "ret", "", "")]
    # The base is the name the call declares for x2, which it clobbers like any other
    # volatile register (#176); `= q0` is the point, that the copy ended at the call.
    got = [ln.strip() for ln in lift_function(called)]
    assert any(re.fullmatch(r"t\d+\.field16_0x11 = q0;", ln) for ln in got), got
    # and so does a loop that writes d0, whose state after it forgets d0
    looped = copy[:1] + [(4, "fmov", "d0, #1.0", ""), (8, "subs", "x3, x3, #1", ""),
                         (12, "b.ne", "#0x4", ""), (16, "str", "q0, [x2, #0x10]", ""),
                         (20, "ret", "", "")]
    assert "x2.field16_0x11 = q0;" in [ln.strip() for ln in lift_function(looped)]

    # Zeroing a double for a comparison is no vote on what the function returns: x0 here.
    assert [ln.strip() for ln in lift_function(
        [(0, "mov", "x0, x2", ""), (4, "eor", "v0.16b, v0.16b, v0.16b", ""),
         (8, "fcmp", "d1, d0", ""), (12, "ret", "", "")])] == ["return x2;"]
    # A loop that writes v0 writes d0, so the 0.0 from before it does not stand after it.
    after = [ln.strip() for ln in lift_function(
        [(0, "eor", "v0.16b, v0.16b, v0.16b", ""), (4, "mov", "v0.16b, v1.16b", ""),
         (8, "subs", "x3, x3, #1", ""), (12, "b.ne", "#0x4", ""),
         (16, "stur", "d0, [x2, #7]", ""), (20, "ret", "", "")])]
    assert "x2.field_0x8 = d0;" in after, after
    # A join one arm of which is the 0.0 the eor made is named, as a computed one is, so a
    # spill of it read back after a call still says what it holds.
    joined = [ln.strip() for ln in lift_function(
        [(0, "cbz", "x0, #0xc", ""), (4, "ldur", "d0, [x1, #7]", ""),
         (8, "b", "#0x10", ""),
         (12, "eor", "v0.16b, v0.16b, v0.16b", ""), (16, "stur", "d0, [x29, #-8]", ""),
         (20, "bl", "#0x100", ""), (24, "ldur", "d1, [x29, #-8]", ""),
         (28, "stur", "d1, [x2, #7]", ""), (32, "ret", "", "")])]
    # The base is the name the call declares for x2 (#176); the 0.0 reaching the store
    # through the spill is the point.
    assert "t0 = 0.0;" in joined, joined
    assert any(_stores(ln, "t0") for ln in joined), joined

    # The clean fixture's lerp clamps to [0.0, 1.0]: `eor v4.16b` zeroes d4, which held a
    # product a moment before, and main compared that product.
    _needs_capstone()
    from jadart.disasm import (load_instructions, disassemble_range, build_pool_map,
                               function_name_by_pc)
    from jadart.expr import make_arity_resolver
    image, fr, _hdr = load_instructions(CLEAN)
    p2n = function_name_by_pc(image, fr)
    pm, ar = build_pool_map(fr), make_arity_resolver(image)
    cr = next(c for c in image.all_ranges
              if c.pc_offset <= 0x11a9c8 < c.pc_offset + (c.size or 0))
    body = "\n".join(lift_function(_ann(image, disassemble_range(image, cr), p2n, pm),
                                   pm, arity=ar))
    assert "if (0.0 > (" in body, body
    assert "(d0 * x3.field_0x8) > (" not in body


def test_a_goto_into_a_loop_head_reads_no_name_the_goto_skipped():
    # A loop head a goto also reaches was left out of the goto join's rules, because the
    # loop binds its own names there; the way in the walk did not take brought a state it
    # never saw, and the body read `t0`, set only on the walked way (#125).
    from jadart.expr import _def_use, lift_function

    def lift(rows):
        return [ln.strip() for ln in lift_function(
            [(i * 4, *r, "") for i, r in enumerate(rows)])]
    body = lift([("mov", "x9, #1"), ("add", "x17, x14, #7"), ("sub", "x8, x0, x3"),
                 ("cbnz", "x5, #0x1c"), ("adcs", "x0, x0, x4"), ("cmp", "x6, x7"),
                 ("b.ge", "#0x28"), ("stur", "x8, [x2, #15]"), ("sub", "x9, x9, #1"),
                 ("tbz", "x9, #63, #0x1c"), ("ret", "")])
    assert "x2.field_0x10 = x8;" in body and "goto L_0x1c;" in body, body
    # ...nor a value only the walked way in left in a register: the goto's way in still
    # has the x9 it came with, and main stored the 5 the other way set.
    body = lift([("and", "x10, x10, #7"), ("cbnz", "x5, #0x14"), ("mov", "x9, #5"),
                 ("cmp", "x6, x7"), ("b.ge", "#0x20"), ("stur", "x9, [x2, #0xf]"),
                 ("subs", "x10, x10, #1"), ("b.gt", "#0x14"), ("ret", "")])
    assert "x2.field_0x10 = x9;" in body and "x2.field_0x10 = 5;" not in body, body
    # An instruction that keeps part of its destination reads it, so a raw one says
    # what it held.
    assert _def_use("bfi", "x0, x1, #3, #8") == ({"x0"}, {"x0", "x1"})
    assert _def_use("movk", "x0, #0x1234, lsl #16") == ({"x0"}, {"x0"})
    assert _def_use("ins", "v0.d[1], x3") == ({"d0"}, {"d0", "x3"})
    assert _def_use("ins", "v0.d[0], x3") == ({"d0"}, {"x3"})
    # capstone spells a lane insert `mov`, and only a low doubleword one replaces dN
    assert _def_use("mov", "v0.s[1], w3") == ({"d0"}, {"d0", "x3"})
    assert _def_use("mov", "v0.d[0], x3") == ({"d0"}, {"x3"})
    assert lift([("add", "x0, x2, #1"), ("bfi", "x0, x1, #3, #8"),
                 ("str", "x0, [x4, #7]"), ("ret", "")])[0] == (
        "bfi x0, x1, #3, #8   // x0 holds x2 + 1")

def test_a_32_bit_destination_clears_the_top_half():
    """arm64 writes the w view of a register by clearing its top half, and `canon` folds
    the two views onto one name, so a 32-bit result printed as a 64-bit one keeps bits the
    machine does not have. DESIGN section 13 counted the fold at 59,073 sites; 3,000 of
    them on the clean fixture compute a value into a w register.

    Measured against the CPU rather than argued. With the `w` exclusion dropped from
    `tools/irfuzz.py`'s operand filter, its text pass disagreed with the hardware on 32
    printed expressions in 2,001 runs of the clean fixture's own code and on 30 of obf,
    every one of them a 32-bit shift of a 64-bit shift's result (#235)."""
    from jadart.expr import lift_function

    def first(rows):
        body = lift_function([(i * 4, mn, op, "") for i, (mn, op) in enumerate(
            list(rows) + [("str", "x6, [x2, #7]"), ("ret", "")])])
        return body[0].strip().split(" = ", 1)[1].rstrip(";")
    # The shape the oracle caught: a 64-bit shift, then a 32-bit shift of its result.
    assert first([("lsl", "x2, x1, #1"), ("lsl", "w6, w2, #1")]) == (
        "(x1 << 1 << 1).toUnsigned(32)")
    # One truncation at the END of a chain of 32-bit operations and not one per step,
    # because each of them reads the w view and drops the same bits itself. That is where
    # a decompiler carrying a type puts its cast too.
    assert first([("lsl", "x2, x1, #1"), ("lsl", "w3, w2, #1"), ("add", "w4, w3, #8"),
                  ("sub", "w6, w4, #2")]) == "((x1 << 1 << 1) + 8 - 2).toUnsigned(32)"
    # A value that provably fits needs none: a mask that small, a literal, a 32-bit shift
    # right, or a result this already truncated.
    assert first([("and", "w2, w1, #0xff"), ("add", "w6, w2, w2")]) == (
        "(x1 & 255) + (x1 & 255)")
    assert first([("mov", "w2, #7"), ("mul", "w6, w2, w2")]) == "7 * 7"
    assert first([("lsr", "w2, w1, #3"), ("orr", "w6, w2, w2")]) == (
        "(x1 & 0xffffffff) >>> 3 | (x1 & 0xffffffff) >>> 3")
    # ...and a bound that follows the arithmetic, so a sum of two bytes needs no mask
    # where a sum of two 32-bit values does.
    assert first([("and", "w2, w1, #0xff"), ("and", "w3, w1, #0xff"),
                  ("add", "w6, w2, w3")]) == "(x1 & 255) + (x1 & 255)"
    assert first([("and", "w2, w1, #0xffffffff"), ("add", "w6, w2, w2")]) == (
        "((x1 & 0xffffffff) + (x1 & 0xffffffff)).toUnsigned(32)")
    # The 64-bit forms of the same instructions are untouched.
    assert first([("lsl", "x2, x1, #1"), ("lsl", "x6, x2, #1")]) == "x1 << 1 << 1"
    assert first([("add", "x2, x1, #8"), ("sub", "x6, x2, #2")]) == "x1 + 8 - 2"
    # A store is not a destination: narrowing its first operand would rewrite a value the
    # machine kept whole.
    body = lift_function([(0, "lsl", "x2, x1, #1", ""), (4, "str", "w2, [x3, #7]", ""),
                          (8, "ret", "", "")])
    assert [ln.strip() for ln in body][0] == "x3.field_0x8 = x1 << 1;"


def test_the_width_conversions_are_evaluated_by_the_oracle():
    """The other half of #235. `tools/irfuzz.py` excluded every w operand by construction,
    so no gate in this repo could see the class at all, and its evaluator knew neither
    `toUnsigned` nor `toSigned`, so each expression carrying one DECLINED rather than
    being checked.

    Both halves matter in order. Dropping the exclusion alone leaves 3,500 of the clean
    fixture's expressions undecidable and reports no mismatches, which is what a hollow
    fix looks like. With the evaluator taught, its text pass checks 255,731 expressions
    where main checks 250,770, and disagrees with the CPU nowhere."""
    import ast
    sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "tools"))
    import irfuzz

    def ev(text, **env):
        return irfuzz._ev(ast.parse(irfuzz._texpr(text), mode="eval"), env)
    assert ev("x1.toUnsigned(32)", x1=0xdeadbeef00000001) == 1
    assert ev("x1.toUnsigned(64)", x1=(1 << 64) - 1) == (1 << 64) - 1
    assert ev("x1.toSigned(32)", x1=0x80000000) == -(1 << 31)
    assert ev("x1.toSigned(32)", x1=0xffffffff7fffffff) == (1 << 31) - 1
    assert ev("(x1 << 1).toUnsigned(32)", x1=0x90000000) == 0x20000000
    # A width outside the range declines rather than guessing, as every other decline in
    # that evaluator does.
    for bad in ("x1.toUnsigned(0)", "x1.toSigned(65)", "x1.toDouble()"):
        with pytest.raises(irfuzz._Undecidable):
            ev(bad, x1=1)
    # ...and the operand filter admits the class, which is what puts it under a gate: the
    # text pass over the fixture's own code now draws runs that write a w register.
    if not _capstone_available() or not os.path.exists(CLEAN):
        _skip("  SKIP the operand-filter half (no capstone, or no clean fixture)")
    runs = irfuzz.expr_cases(CLEAN, want=200)
    assert runs, "no pure-arithmetic runs at all"
    w = sum(1 for run, _code in runs
            for _a, _mn, op in run if re.search(r"\bw\d+\b", op))
    assert w > 0, "the oracle still draws no 32-bit operand"


def test_a_negative_literal_and_a_32_bit_shift_read_as_dart_reads_them():
    # A negative literal is an atom to the lifter and a unary minus to Dart: `neg` of it
    # printed `--128`, a decrement, and a field read off it `-128.field_0x8`, which Dart
    # reads as `-(128.field_0x8)`; `neg` of a `neg` printed `--x1` too. And a 32-bit
    # shift right printed as a 64-bit one, so the register's top half shifted into the
    # low 32 bits (#130).
    import random
    from jadart.expr import lift_function

    def first(rows):
        body = lift_function([(i * 4, mn, op, "") for i, (mn, op) in enumerate(
            list(rows) + [("str", "x6, [x2, #7]"), ("ret", "")])])
        return body[0].strip().split(" = ", 1)[1].rstrip(";")
    assert first([("mov", "x5, #-0x80"), ("neg", "x6, x5")]) == "-(-128)"
    assert first([("mov", "x5, #-0x80"), ("ldr", "x6, [x5, #7]")]) == "(-128).field_0x8"
    assert first([("neg", "x5, x1"), ("neg", "x6, x5")]) == "-(-x1)"
    assert first([("mov", "x5, #-0x80"), ("sub", "x6, x1, x5")]) == "x1 - -128"
    assert first([("lsr", "w6, w1, #3")]) == "(x1 & 0xffffffff) >>> 3"
    # The sign comes out of bit 31 and then the destination clears the top half, so the
    # value is a 32-bit pattern and not a negative Dart int (#235).
    assert first([("asr", "w6, w1, #3")]) == "(x1.toSigned(32) >> 3).toUnsigned(32)"
    assert first([("lsr", "x6, x1, #3")]) == "x1 >>> 3"
    # A value masked to fit already needs no second mask, as hash mixing mostly is.
    assert first([("and", "w5, w1, #0x7fffffff"), ("lsr", "w6, w5, #0xb")]) == (
        "(x1 & 0x7fffffff) >>> 11")
    assert first([("ubfx", "x5, x1, #0, #0x20"), ("lsr", "w6, w5, #0xb")]) == (
        "(x1 & 0xffffffff) >>> 11")
    assert first([("and", "w5, w1, #0x7fffffff"), ("asr", "w6, w5, #3")]) == (
        "(x1 & 0x7fffffff) >> 3")
    # ...but a sign still needs carrying out of bit 31,
    assert first([("ubfx", "x5, x1, #0, #0x20"), ("asr", "w6, w5, #3")]) == (
        "((x1 & 0xffffffff).toSigned(32) >> 3).toUnsigned(32)")
    assert first([("and", "w5, w1, #0x80000000"), ("asr", "w6, w5, #3")]) == (
        "((x1 & 0x80000000).toSigned(32) >> 3).toUnsigned(32)")
    # and a mask under an `|` bounds only its own side.
    assert first([("and", "w5, w1, #0xff"), ("orr", "w5, w2, w5"),
                  ("lsr", "w6, w5, #3")]) == "((x2 | x1 & 255) & 0xffffffff) >>> 3"

    mask32, mask64 = (1 << 32) - 1, (1 << 64) - 1

    def signed(v, n):
        v &= (1 << n) - 1
        return v - (1 << n) if v >> (n - 1) & 1 else v

    def dart(t, x):
        # The printed text, read as Dart reads it. `.toUnsigned(32)` is how a 32-bit
        # destination says it cleared the top half (#235), and it can wrap a whole
        # parenthesised expression, so it is taken off the tail rather than matched as a
        # name like `.toSigned(32)` is.
        while t.endswith(".toUnsigned(32)"):
            t = f"({t[:-len('.toUnsigned(32)')]}) & {mask32}"
        t = re.sub(r"(\w+)\.toSigned\(32\)", r"_s(\1, 32)", t)
        t = t.replace(">>>", ">>").replace("x1", "_x")
        return eval(t, {"_s": signed, "_x": x}) & mask64
    rng = random.Random(130)
    for mn in ("lsr", "asr"):
        for n in (1, 3, 11, 31):
            t = first([(mn, f"w6, w1, #{n}")])
            for _ in range(200):
                x = rng.getrandbits(64)
                low = x & mask32
                want = low >> n if mn == "lsr" else signed(low, 32) >> n
                assert dart(t, x) & mask32 == want & mask32, (mn, n, t, hex(x))


def test_a_frame_address_held_in_a_register_is_the_slot_it_names():
    # `mov x17, #0x238; add x17, x17, x15; str x1, [x17]` stores to the slot
    # `str x1, [x15, #0x238]` does. The add was read as an element address with the
    # constant as its base, so the store printed `0x238[SP] = x1;` and the reload of the
    # slot was not told it had been written (#328).
    from jadart.expr import lift_function

    def lift(rows):
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows + [("ret", "")])])]
    for fr in ("x15", "x29"):
        for build in ([("mov", "x17, #0x238")],
                      [("mov", "x17, #0x238"), ("movk", "x17, #0, lsl #16")],
                      [("movz", "x17, #0x1, lsl #16"), ("movk", "x17, #0x238")]):
            off = 0x10238 if build[0][0] == "movz" else 0x238
            for add in (f"x17, x17, {fr}", f"x17, {fr}, x17"):
                for st, ld, pre in (("str x1, [x17]", f"ldr x0, [{fr}, #{off:#x}]", "x1"),
                                    ("str w1, [x17]", f"ldr w0, [{fr}, #{off:#x}]", "x1"),
                                    ("str x1, [x17, #8]",
                                     f"ldr x0, [{fr}, #{off + 8:#x}]", "x1")):
                    got = lift(build + [("add", add),
                                        (st.split()[0], st.split(" ", 1)[1]),
                                        (ld.split()[0], ld.split(" ", 1)[1])])
                    assert got == [f"return {pre};"], (fr, build, add, st, got)
    # A pair, loaded back through the displacement, and the slot after it.
    for w in "xw":
        got = lift([("mov", "x17, #0xf0"), ("add", "x17, x17, x15"),
                    ("stp", f"{w}1, {w}2, [x17]"), ("ldp", f"{w}3, {w}4, [x15, #0xf0]"),
                    ("add", "x0, x3, x4")])
        assert got == ["return x1 + x2;"], got
    # Below the frame register: SP less a constant.
    assert lift([("mov", "x17, #0x80"), ("sub", "x17, x15, x17"), ("str", "x1, [x17]"),
                 ("ldur", "x0, [x15, #-0x80]")]) == ["return x1;"]
    # Another slot is another slot, and a held address tracks an add of its own.
    assert lift([("mov", "x17, #0x238"), ("add", "x17, x17, x15"), ("str", "x1, [x17]"),
                 ("str", "x2, [x15, #0x240]"),
                 ("ldr", "x0, [x15, #0x238]")]) == ["return x1;"]
    assert lift([("mov", "x17, #0x230"), ("add", "x17, x17, x15"),
                 ("add", "x17, x17, #8"), ("str", "x1, [x17]"),
                 ("ldr", "x0, [x15, #0x238]")]) == ["return x1;"]
    # A call may change x17 and a move of SP changes what it was taken off, so the
    # address is held to the next one of either and no further.
    for gap in ([("bl", "#0x100")], [("str", "x3, [x15, #-8]!")], [("mov", "x17, x3")]):
        got = lift([("mov", "x17, #0x238"), ("add", "x17, x17, x15")] + gap
                   + [("str", "x1, [x17]"), ("ldr", "x0, [x15, #0x238]")])
        assert "return x1;" not in got, (gap, got)
    # The same function as the displacement writes it gives the same lines, in a loop
    # that stores to the outgoing area and calls, which is what _writes_outgoing reads.
    held = [("mov", "x17, #0x238"), ("add", "x17, x17, x15"), ("str", "x1, [x17]")]
    direct = [("mov", "x16, #0"), ("mov", "x16, #1"), ("str", "x1, [x15, #0x238]")]
    for body in ([("bl", "#0x100"), ("ldr", "x0, [x15, #0x238]")],
                 [("str", "x3, [x15, #0x240]"), ("ldr", "x0, [x15, #0x238]")],
                 # a loop whose head is the store, so the address is held across the
                 # back edge into a block of its own
                 [("sub", "x2, x2, #1"), ("cbnz", "x2, #0x8"),
                  ("ldr", "x0, [x15, #0x238]")]):
        assert lift(held + body) == lift(direct + body), body
    # A call in the loop empties x17 on the back edge, so the store is not folded.
    got = lift(held + [("bl", "#0x100"), ("cbnz", "x2, #0x8"),
                       ("ldr", "x0, [x15, #0x238]")])
    assert "return x1;" not in got, got
    # ...and across a join, where one arm moves the address, it is not held.
    got = lift([("mov", "x17, #0x238"), ("add", "x17, x17, x15"), ("cbz", "x2, #0x14"),
                ("mov", "x17, x3"), ("b", "#0x14"), ("str", "x1, [x17]"),
                ("ldr", "x0, [x15, #0x238]")])
    assert "return x1;" not in got, got
    # A move of SP or FP that strip_boilerplate blanks to a `nop` still moves it: the
    # store is at old SP + 0x238, new SP + 0x258, so a load of new SP + 0x238 must not
    # read it back, and every load prints as the `add xD, xF, #imm` spelling does.
    for fr, imm, move, slots in (("x15", "#0x238", ("sub", "x15, x15, #0x20"),
                                  ("#0x238", "#0x258")),
                                 ("x29", "#0x38", ("mov", "x29, x15"), ("#0x38",))):
        for slot in slots:
            tail = [move, ("str", "x1, [x17]"), ("ldr", f"x0, [{fr}, {slot}]")]
            got = lift([("mov", f"x17, {imm}"), ("add", f"x17, x17, {fr}")] + tail)
            assert got == lift([("add", f"x17, {fr}, {imm}")] + tail), (fr, slot, got)
            assert got != ["return x1;"], (fr, slot, got)


def test_a_constant_is_not_printed_as_the_base_of_an_element():
    # `mov x17, #0x238; add x17, x17, x3; str x1, [x17]` is x3 plus 0x238, element 0x238
    # of x3 as `add x17, x3, x17` has always read, not element x3 of the number 0x238.
    # A shifted index off a number or two numbers is no element address and prints as
    # the sum it is (#328).
    from jadart.expr import lift_function

    def lift(rows):
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows + [("ret", "")])])]
    a = lift([("mov", "x17, #0x238"), ("add", "x17, x17, x3"), ("str", "x1, [x17]")])
    b = lift([("mov", "x17, #0x238"), ("add", "x17, x3, x17"), ("str", "x1, [x17]")])
    assert a == b == ["x3[0x238] = x1;", "return x0;"], (a, b)
    assert lift([("mov", "x17, #0x238"), ("add", "x2, x17, x3"),
                 ("mov", "x0, x2")]) == ["return 0x238 + x3;"]
    for rows in ([("mov", "x17, #0x238"), ("add", "x17, x17, x3, lsl #3"),
                  ("str", "x1, [x17]")],
                 [("mov", "x17, #0x238"), ("mov", "x16, #8"), ("add", "x17, x17, x16"),
                  ("str", "x1, [x17]")]):
        got = lift(rows)
        assert not re.search(r"0x238\[|8\[", "\n".join(got)), got


def test_a_frame_slot_past_the_displacement_is_its_own_slot():
    # A slot too far from FP for the 9-bit displacement is reached through x17: `mov
    # x17, #-0x158; str d0, [x29, x17]`. Read as `[x29]`, every such slot was x29+0, so
    # a load took whatever was stored at another offset last (#137).
    from jadart.expr import lift_function

    def lift(rows):
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows + [("ret", "")])])]
    assert lift([("mov", "x17, #-0x158"), ("str", "x1, [x29, x17]"),
                 ("mov", "x17, #-0x160"), ("str", "x2, [x29, x17]"),
                 ("mov", "x17, #-0x158"), ("ldr", "x0, [x29, x17]")]) == ["return x1;"]
    # The same slot as a displacement reaches it, under either spelling of the offset.
    assert lift([("mov", "x17, #-0x10"), ("str", "x1, [x29, x17]"),
                 ("ldur", "x0, [x29, #-0x10]")]) == ["return x1;"]
    assert lift([("mov", "x17, #0xfffffffffffffff0"), ("str", "x1, [x29, x17]"),
                 ("ldur", "x0, [x29, #-0x10]")]) == ["return x1;"]
    assert lift([("mov", "x17, #-0x158"), ("str", "x1, [x15, x17]"),
                 ("ldur", "x0, [x15, #-0x158]")]) == ["return x1;"]
    # A call may change x17, as a stub or a veneer uses it, so the offset is the `mov`'s
    # only right after it; and x17 itself is not what it was before the call.
    # The raw store may have written any slot, so the load that follows reads a slot the
    # walk no longer knows. It now says the read instead of keeping x0, which read as the
    # value the function came in with (#198).
    # The call declares x1 and x17 too, so the note says each holds a name for a value
    # nobody knows rather than nothing at all (#176). Still not the `mov`'s offset, which
    # is the point: nothing in the body names 0x158.
    got = lift([("stur", "x2, [x29, #-0x160]"), ("mov", "x17, #-0x158"),
                ("bl", "#0x100"), ("str", "x1, [x29, x17]"), ("mov", "x17, #-0x160"),
                ("ldr", "x0, [x29, x17]")])
    assert re.fullmatch(r"str x1, \[x29, x17\]   // x1 holds t\d+, x17 holds t\d+",
                        got[3]), got
    assert "0x158" not in "\n".join(got), got
    m = re.fullmatch(r"var (t\d+) = \(FP - 0x160\)\.field_0x1;", got[4])
    assert m and got[5] == f"return {m.group(1)};", got
    # ...and the 5 is gone with it: the call declares what it left in x17, where a bare
    # x17 read as the value the function came in with (#176).
    got = lift([("mov", "x17, #5"), ("bl", "#0x100"), ("mov", "x0, x17")])
    m = re.fullmatch(r"var (t\d+);", got[0])
    assert m and got[-1] == f"return {m.group(1)};", got
    # An offset changed since its `mov` is not the `mov`'s: this x17 is -0x158 again.
    # x17 changed since its `mov`, so the store went to a slot the walk cannot place and
    # the reload after it names the read instead of keeping x0 (#198).
    assert lift([("mov", "x17, #-0x158"), ("str", "x1, [x29, x17]"),
                 ("mov", "x17, #-0x160"), ("add", "x17, x17, #8"),
                 ("str", "x2, [x29, x17]"), ("mov", "x17, #-0x158"),
                 ("ldr", "x0, [x29, x17]")])[-1] == "return t0;"
    # An offset the lifter cannot read is printed, and a store through it may have
    # written any slot.
    assert lift([("stur", "x2, [x29, #-8]"), ("str", "x1, [x29, x3]"),
                 ("ldur", "x0, [x29, #-8]")]) == [
        "str x1, [x29, x3]", "var t0 = (FP - 8).field_0x1;", "return t0;"]
    assert lift([("stur", "x2, [x29, #-8]"), ("ldr", "x0, [x29, x3]")]) == [
        "ldr x0, [x29, x3]", "return x0;"]
    # A loop that stores through one rewrites every slot, the -8 it reloads too, off SP
    # as off FP.
    for base in ("x29", "x15"):
        # Not x2 and no longer x0 either: the slot is lost at the top of every trip, so
        # the reload names the read rather than keeping the register (#198).
        got = lift([("stur", "x2, [x29, #-8]"), ("ldur", "x0, [x29, #-8]"),
                    ("stur", "x0, [x1, #7]"), ("str", f"x3, [{base}, x4]"),
                    ("cbnz", "x5, #4")])
        assert ["var t0 = (FP - 8).field_0x1;", "x1.field_0x8 = t0;"] == got[1:3], got
    # Only an offset set in the same block counts: x17 here is -0x158 or -0x160.
    assert lift([("mov", "x17, #-0x158"), ("cbz", "x5, #0xc"), ("mov", "x17, #-0x160"),
                 ("str", "x1, [x29, x17]"), ("mov", "x17, #-0x158"),
                 ("ldr", "x0, [x29, x17]")]) == [
        "str x1, [x29, x17]", "var t0 = (FP - 0x158).field_0x1;", "return t0;"]


def test_a_register_list_load_writes_every_register_in_it():
    # `ld1 {v0.16b, v1.16b}` writes d0 and d1, and only the first register of a list
    # was seen as written: a store of d1 after it printed the field d1 held before, and
    # the raw line said it read d1 (#134).
    from jadart.expr import lift_function

    def lift(rows):
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows + [("ret", "")])])]
    assert lift([("ldur", "d1, [x4, #0xf]"), ("ld1", "{v0.16b, v1.16b}, [x1]"),
                 ("stur", "d1, [x5, #7]")])[:2] == [
        "ld1 {v0.16b, v1.16b}, [x1]", "x5.field_0x8 = d1;"]
    assert lift([("ldur", "q3, [x4, #0xf]"),
                 ("ld4", "{v0.2d, v1.2d, v2.2d, v3.2d}, [x2], #64"),
                 ("stur", "d3, [x5, #7]")])[1] == "x5.field_0x8 = d3;"
    # A lane of each keeps the rest of the register, so the line reads it too.
    assert lift([("ldur", "d5, [x4, #0xf]"), ("ld2", "{v4.s, v5.s}[1], [x3]"),
                 ("stur", "d5, [x5, #7]")])[:2] == [
        "ld2 {v4.s, v5.s}[1], [x3]   // d5 holds x4.field_0x10", "x5.field_0x8 = d5;"]
    # A store of a list writes none of them. It may write the field d1 was read from,
    # so that read is named first; through FP it cannot (#162).
    assert lift([("ldur", "d1, [x4, #0xf]"), ("st1", "{v0.16b, v1.16b}, [x1]"),
                 ("stur", "d1, [x5, #7]")])[:3] == [
        "var t0 = x4.field_0x10;", "st1 {v0.16b, v1.16b}, [x1]   // d1 holds t0",
        "x5.field_0x8 = t0;"]
    assert lift([("ldur", "d1, [x4, #0xf]"), ("st1", "{v0.16b, v1.16b}, [x29]"),
                 ("stur", "d1, [x5, #7]")])[1] == "x5.field_0x8 = x4.field_0x10;"


def test_a_value_read_only_as_a_call_argument_is_live_up_to_the_call():
    # `bl` reads no register to the machine, so a value read only as a call's argument
    # was dead to liveness: a raw line overwriting a register it is spelled with did not
    # name it first, and `foo(x1, x1 + 1)` passed the new x1 plus one (#122). A call
    # whose arity is known reads the arguments it prints.
    from jadart.expr import lift_function

    def lift(rows, k):
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows + [("ret", "")])],
            arity=lambda pc: k)]
    assert lift([("add", "x2, x1, #1"), ("csel", "x1, x4, x5, eq"), ("bl", "#0x100")],
                2) == ["var t0 = x1 + 1;", "csel x1, x4, x5, eq",
                       "return sub_0x100(x1, t0);"]
    # Arms that disagree on an argument give it a name at the join, where it printed
    # as a bare register.
    joined = [("mov", "x1, x6"), ("cbz", "x3, #0x10"), ("add", "x2, x1, #1"),
              ("b", "#0x14"), ("add", "x2, x1, #2"), ("bl", "#0x200")]
    assert lift(joined, 2) == ["var t0;", "if (x3 != 0) {", "t0 = x6 + 1;", "} else {",
                               "t0 = x6 + 2;", "}", "return sub_0x200(x6, t0);"]
    # A register the callee does not take is not read.
    assert lift(joined, 1) == ["return sub_0x200(x6);"]
    # An arm that loads x2 in an inner `if` whose join keeps no value for it ends with
    # x2 spelled as itself, as on entry. The name takes x2 in that arm, after the inner
    # `if`, and not from before the outer one, where it held something else. Either
    # arm of the inner `if` may be the one that loads it.
    # The first argument is no longer the entry x6: x6 is the call's to clobber, so the
    # arm that calls leaves the name the call declares for it and the join takes a phi
    # over the two. Main passed x6 where the callee may have left anything (#176).
    want = ["var t2;", "var t3 = x6;", "if (x3 != 0) {", "var t0;",
            "var t1 = sub_0x500(...);", "t2 = t1;", "t3 = t0;", "} else {", "t2 = x2;",
            "}", "return sub_0x200(t3, t2);"]
    for then, other in ((("ldur", "x2, [x5, #7]"), ("ldur", "x2, [x5, #0xf]")),
                        (("add", "x7, x7, #1"), ("ldur", "x2, [x5, #0xf]")),
                        (("ldur", "x2, [x5, #7]"), ("add", "x7, x7, #1"))):
        assert lift([("mov", "x1, x6"), ("cbz", "x3, #0x14"), ("bl", "#0x500"),
                     ("mov", "x2, x0"), ("b", "#0x24"), ("cbz", "x4, #0x20"), then,
                     ("b", "#0x24"), other, ("mov", "x1, x6"), ("bl", "#0x200")],
                    2) == want, (then, other)
    # The same holds for a value recomputed after the loss: `x1 + 1` from x1 loaded in
    # the inner `if` is spelled as the `x1 + 1` from before the outer one, and is not it.
    assert lift([("add", "x2, x1, #1"), ("cbz", "x3, #0x20"), ("cbz", "x4, #0x14"),
                 ("ldur", "x1, [x5, #7]"), ("b", "#0x18"), ("ldur", "x1, [x5, #0xf]"),
                 ("add", "x2, x1, #1"), ("b", "#0x24"), ("mov", "x2, x7"),
                 ("bl", "#0x200")], 2) == [
        "var t0;", "if (x3 != 0) {", "t0 = x2;", "} else {", "t0 = x7;", "}",
        "return sub_0x200(...);"]
    # ...and the list is not printed: its first argument is the x1 the inner `if` lost,
    # and a bare `x1` there would say the value the function came in with (#358). It
    # printed `sub_0x200(x1, t0)`.


def test_a_dispatch_offset_other_selectors_share_is_not_named():
    # The dispatch table is packed by row displacement, so selectors whose classes never
    # meet can take the same offset, and a call site's immediate does not say which of
    # them it calls. The clean build's 0x9c0e8 tests a bool and printed
    # `.textScaleFactor`, a double getter (#128).
    from jadart.disasm import (load_instructions, disassemble_range, function_name_by_pc,
                               build_pool_map)
    from jadart.expr import lift_function, make_arity_resolver
    from jadart import dispatch as D
    image, fr, hdr = load_instructions(CLEAN)
    sel = D.recover_selectors(image, fr, hdr)
    assert len(sel) == 133 and "build" in sel.values()
    # `renderObject` shares -0xff2 with `handleTapUp`, `encodeMethodCall` and
    # `get:notify`, each defined in a class whose only row is there; `controller.stream`
    # printed `.maximumSize`, as `_StreamController.stream`, defined in an abstract class,
    # which has no row of its own, is at that offset too.
    assert -0xff2 not in sel and "get:maximumSize" not in sel.values()
    # A function of an abstract class fills its subclasses' rows, not one above its
    # offset: these names were dropped for a sharer that was not there. And a function
    # that fits more than one offset is at its own selector's where the vote gives one.
    for nm in ("get:side", "get:alpha", "isScheme", "updateDependencies", "dispose",
               "didUpdateWidget"):
        assert nm in sel.values(), nm
    # A sharer with no name, or one that fits more than one offset, is a sharer: 122
    # calls of `.length` printed `.perform()`, `table._checkSum` `.visitChildren`,
    # `delegate.isSupported` `.asByteData`, `observer.didChangeTextScaleFactor` `.mount`.
    for nm in ("perform", "decodeMethodCall", "visitChildren", "asByteData", "mount"):
        assert nm not in sel.values(), nm
    # -0xfeb is also a Focus getter whose code is a `return false` another function
    # owns, invisible to the table's functions. The double getter's name is kept, and a
    # call site that reads the result from x0 is not given it.
    assert sel.get(-0xfeb) == "get:textScaleFactor"
    # The placement, on a table small enough to read: A (abstract, cid 10) defines f,
    # its subclass C (cid 12) overrides f, B (cid 11) inherits it. f fills B's row only,
    # at offset 5, where g, defined in D (cid 20), sits too; h, in E (cid 30), alone.
    from types import SimpleNamespace
    fr0 = SimpleNamespace(
        classes=[(1, 0, 10, 101), (2, 0, 11, 102), (3, 0, 12, 102), (4, 0, 20, 0),
                 (5, 0, 30, 0)],
        types={102: 10}, class_state={10: D._ABSTRACT},
        functions=[(50, 60, 1, 0), (51, 60, 3, 0), (52, 61, 4, 0), (53, 62, 5, 0)],
        names={60: "get:f@1", 61: "g", 62: "h"})
    rows0 = {0: [16], 1: [17], 2: [25], 3: [37]}
    slots0 = {50: 0, 51: 1, 52: 2, 53: 3}
    cids0 = {ref: cid for ref, _n, cid, _s in fr0.classes}
    placed0, _maybe0, _parents0, _defines0 = D._placements(fr0, rows0, slots0, {}, cids0)
    assert {f[0] for f in placed0[5]} == {"get:f@1", "g"}, dict(placed0)
    assert {f[0] for f in placed0[7]} == {"h"}, dict(placed0)
    assert sorted(f[3] for f in placed0[5] if f[0] == "get:f@1") == [50, 51]
    # A function with no name is another selector, unless a class above it defines the
    # one at that offset: get:n in N1 (10) and N2 (11) at offset 5 shares it with one in
    # U (20); M3 (32), below M1, overrides get:m (offset 3) with one.
    fr1 = SimpleNamespace(
        classes=[(1, 0, 10, 0), (2, 0, 11, 0), (3, 0, 20, 0), (4, 0, 30, 0),
                 (5, 0, 31, 0), (6, 0, 32, 106)],
        types={106: 30}, class_state={}, patch_class={},
        functions=[(50, 60, 1, 0), (51, 60, 2, 0), (52, 61, 3, 0), (53, 62, 4, 0),
                   (54, 62, 5, 0), (55, 61, 6, 0)],
        names={60: "get:n", 61: "", 62: "get:m"},
        codes=[(0, ref, ci) for ci, ref in enumerate(range(50, 56))])
    cells = [None] * 40
    for k, slot in ((15, 0), (16, 1), (25, 2), (33, 3), (34, 4), (35, 5)):
        cells[k] = slot + 1
    assert dict(D.build_selector_map(
        cells, fr1, SimpleNamespace(symbol_names={}, pcs=[], first_code=0))) == {
        3: "get:m"}
    # and the symbol table's spelling of a name is the snapshot's selector
    assert D._selector("get:_foo@0150898") == D._selector("_foo") == "_foo"
    assert D._selector("hashCode") == D._selector("get:hashCode")
    if not _capstone_available():
        _skip("  SKIP the call-site half of the shared offset test (no capstone)")
    assert -0xfeb in sel.doubles
    cr = next(c for c in image.code_ranges.values() if c.pc_offset == 0x9c0a8)
    body = "\n".join(lift_function(
        _ann(image, disassemble_range(image, cr), function_name_by_pc(image, fr),
             build_pool_map(fr)),
        build_pool_map(fr), receiver={"x1": "this"}, arity=make_arity_resolver(image),
        selectors=sel))
    assert ".sel_m0xfeb(...) >> 4" in body and "textScaleFactor" not in body, body


def test_a_stub_that_returns_a_value_is_a_call_to_the_return_rule():
    # `InitLate*`, `Await`, `InitAsync` and `CloneContext` hand a value back in x0, so the
    # return rule must not read a d0 written before one as what the `ret` after it hands
    # back (#127). They are also not dropped like the stubs that give every register back:
    # dropping them left the stale x0 standing in for the value they return, which is a
    # whole lazy-init getter printed as `return x0;` (#234).
    from jadart.expr import lift_function

    def lift(stub):
        rows = [("ldur", "d0, [x1, #0xf]", ""), ("fadd", "d0, d0, d0", ""),
                ("bl", "#0x200", f"  ; -> stub _iso_stub_{stub}Stub"), ("ret", "", "")]
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, n) for i, (mn, op, n) in enumerate(rows)])]
    for stub in ("InitLateStaticField", "InitLateFinalInstanceField", "Await",
                 "InitAsync", "CloneContext"):
        assert lift(stub) == [f"return {stub}(...);"], stub
    # A stub that does give every register back leaves the double where it was.
    assert lift("StackOverflowSharedWithoutFPURegs") == [
        "return x1.field_0x10 + x1.field_0x10;"]


def test_a_loop_carries_a_register_it_reads_only_as_a_call_argument():
    # A loop decides what it carries from the registers its body reads before writing,
    # and a call read none: x2, passed to the call and then set from its result, printed
    # as the value from before the loop on every trip (#142).
    from jadart.expr import lift_function
    rows = [("mov", "x2, #0"), ("mov", "x1, x6"), ("bl", "#0x200"), ("mov", "x2, x0"),
            ("cbnz", "x0, #0x4"), ("ret", "")]
    body = [ln.strip() for ln in lift_function(
        [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)], arity=lambda pc: 2)]
    # The call declares what it left in x1, which the loop carries, so its own result
    # takes the number after that. The latch said `t1 = x6;` on main, the entry x6 on
    # every trip, where the callee may have left anything in x1 (#176).
    assert body[:3] == ["var t0 = 0;", "var t1 = x6;", "while (true) {"], body
    clob = re.fullmatch(r"var (t\d+);", body[3])
    res = re.fullmatch(r"var (t\d+) = sub_0x200\(t1, t0\);", body[4])
    assert clob and res, body
    assert f"t0 = {res.group(1)};" in body and f"t1 = {clob.group(1)};" in body, body


def test_a_function_that_reads_its_arguments_off_the_stack_has_no_register_arity():
    # entry_arity counted x1..xN live on entry and gave 0 for a function that reads its
    # arguments off the stack where it did not recognise the read, so a call to it
    # printed `_absSub()` over the five values it pushed (#144): a frameless function
    # reads them off SP, and one indexes them through FP.
    from jadart.expr import entry_arity, lift_function

    def arity(rows):
        return entry_arity([(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])
    frame = [("stp", "x29, x30, [x15, #-0x10]!"), ("mov", "x29, x15")]
    assert arity([("ldr", "x0, [x15]"), ("ret", "")]) is None
    assert arity(frame + [("add", "x1, x29, w0, sxtw #2"), ("ldr", "x1, [x1, #0x28]"),
                          ("ret", "")]) is None
    # A frame's own slots off SP are not arguments, nor is a field read, nor a local
    # below FP read through an index.
    assert arity(frame + [("sub", "x15, x15, #0x10"), ("ldr", "x0, [x15, #8]"),
                          ("ldur", "x2, [x1, #7]"), ("ret", "")]) == 1
    assert arity(frame + [("add", "x3, x29, w2, sxtw #2"), ("ldur", "x3, [x3, #-8]"),
                          ("ret", "")]) == 0
    # One that takes registers too keeps their count, as `hash6` does.
    assert arity([("ldr", "x0, [x15]"), ("ldur", "x2, [x1, #7]"), ("ret", "")]) == 1
    # and a call to such a function prints what was pushed, all of it: a second push
    # that moves SP renames the first push's slots rather than dropping them, so the
    # three values pushed as two pushes stay the three-argument list (#147). The lost
    # third argument of `_setFlag` was main's.
    def call(rows):
        rows = rows + [("bl", "#0x100"), ("ret", "")]
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)],
            arity=lambda pc: None)]
    assert call([("stp", "x6, x7, [x15, #-0x10]!")]) == ["return sub_0x100(x7, x6);"]
    assert call([("stp", "x6, x7, [x15, #-0x10]!"), ("str", "x5, [x15, #-8]!")]) == [
        "return sub_0x100(x7, x6, x5);"]


def test_registers_saved_round_a_call_are_not_its_arguments():
    # A slow path spills volatile registers before a runtime call and reloads them after.
    # The spill lands in the outgoing area exactly as a pushed argument does, so main read
    # it back as the call's argument list, `pool_0x2650.field_0x7(t4, t3)` for a saved
    # `stp x0, x1` (#147). A save is told from an argument by what the code does after the
    # call: a save is reloaded into the registers it came from, an argument is dropped
    # with the outgoing area. A call whose pushes are reloaded reads no stack arguments.
    from jadart.expr import lift_function

    def call(rows):
        rows = rows + [("ret", "")]
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)],
            arity=lambda pc: None)]
    # x0 saved round the call and reloaded after: not an argument.
    # The call consumes the outgoing area, so the reload reads a slot the walk no longer
    # knows and names the read. It used to print `return x0`, right here because the entry
    # x0 is what was saved, but spelled exactly like a reload that had given up (#198).
    saved = call([("str", "x0, [x15, #-8]!"), ("mov", "x0, #0x46"), ("bl", "#0x100"),
                  ("ldr", "x0, [x15], #8")])
    assert saved == ["sub_0x100(...);", "var t0 = SP.field_0x1;", "return t0;"], saved
    # a pair saved with stp and reloaded with ldp, as 0x18d4e4 does. Only x0 is read
    # again, so only x0's half is named.
    pair = call([("stp", "x0, x1, [x15, #-0x10]!"), ("mov", "x0, #0x42"),
                 ("bl", "#0x100"), ("ldp", "x0, x1, [x15], #0x10")])
    assert pair == ["sub_0x100(...);", "var t0 = SP.field_0x1;", "return t0;"], pair
    # the same push with no reload after is a real argument and still reads.
    arg = call([("str", "x0, [x15, #-8]!"), ("bl", "#0x100")])
    assert arg == ["return sub_0x100(x0);"], arg
    # a push dropped with the outgoing area (add x15), not reloaded, is an argument too.
    dropped = call([("str", "x0, [x15, #-8]!"), ("bl", "#0x100"),
                    ("add", "x15, x15, #8")])
    assert dropped == ["return sub_0x100(x0);"], dropped


def _pool_358(*descs):
    """A pool map over a crafted fill result: slot i names descriptor i, given as
    (type_args_len, count, size, ((name, position), ...)), a base object for None, or
    the Array whose refs are listed. Smi v is ref 100 + v, except 0, which the VM
    snapshot holds: base ref 5. Refs below 10 are base objects and 1 is null."""
    import types
    from jadart.disasm import build_pool_map
    strings, arrays, pool = {}, {}, []
    smi = lambda v: 5 if v == 0 else 100 + v
    for i, d in enumerate(descs):
        if d is None:
            pool.append(("ref", 6))
            continue
        if isinstance(d, list):
            arrays[200 + i] = tuple(d)
        else:
            tlen, count, size, named = d
            elems = [smi(tlen), smi(count), smi(size), smi(count - len(named))]
            for name, pos in sorted(named):
                strings[300 + len(strings)] = name
                elems += [299 + len(strings), smi(pos)]
            arrays[200 + i] = tuple(elems + [1])
        pool.append(("ref", 200 + i))
    fr = types.SimpleNamespace(functions=[], names={}, strings=strings, pool=pool,
                               arrays=arrays, first_ref=10,
                               smi_values={100 + v: v for v in range(1, 300)})
    return build_pool_map(fr)


def _callee_358(k, regs=(), desc=False, fpu=False, convention="reg"):
    """A resolver that answers for one callee as make_arity_resolver does: `k` its
    arity, and what a call site asks, the argument registers it reads, whether it
    reads x4 and whether a V register, under `convention`."""
    ar = lambda pc: k
    ar.args = lambda pc: () if k is None else regs
    ar.entry = lambda pc: (regs, desc, fpu)
    ar.convention = convention
    return ar


def _lift_358(rows, pool=None, ar=None):
    from jadart.expr import lift_function
    return [ln.strip() for ln in lift_function(
        [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows + [("ret", "")])],
        pool, arity=ar)]


#: Pool slots 0x10 up: three named after two positional, a base object, a generic
#: call's, one named after the receiver, an Array that is no descriptor, one all on
#: the stack, three positional with one pushed, and one all in registers, whose size
#: is the base Smi and so says that Smi is 0.
_POOL_358 = [(0, 5, 3, (("left", 2), ("top", 3), ("right", 4))), None,
             (1, 2, 2, (("onError", 1),)), (0, 2, 1, (("colorSpace", 1),)),
             [105, 5, 5], (0, 2, 2, (("n", 1),)), (0, 3, 1, ()), (0, 2, 0, ())]
_REGS_358 = [("mov", "x1, #7"), ("mov", "x2, #9")]
_PUSH3_358 = [("stp", "x22, x22, [x15, #8]"), ("str", "x22, [x15]")]
#: A dispatch-table call on the receiver in x1.
_DISPATCH_358 = [("ldur", "x9, [x1, #-1]"), ("ubfx", "x9, x9, #0xc, #0x14"),
                 ("add", "x30, x9, #0x40"), ("ldr", "x30, [x21, x30, lsl #3]"),
                 ("blr", "x30")]


def test_a_call_handed_an_arguments_descriptor_lists_register_and_named_arguments():
    """#358: `removeViewInsets` printed `copyWith(NULL, NULL, NULL)` for a call that
    passes two arguments in x1 and x2, three more on the stack and a descriptor in x4
    naming those three. The callee reads x4, so its arity was not known, and what was
    pushed printed as the whole list. The descriptor counts them: `count - size` in
    registers, `size` words pushed, and the names with their positions."""
    pool = _pool_358(*_POOL_358)
    load = lambda off: [("ldr", f"x4, [x27, #{off:#x}]")]
    two = _callee_358(None, ("x1", "x2"), desc=True)
    none = _callee_358(None, (), desc=True)
    call = [("bl", "#0x100")]
    # the issue's shape
    assert _lift_358(_REGS_358 + _PUSH3_358 + load(0x10) + call, pool, two) == [
        "return sub_0x100(7, 9, left: NULL, top: NULL, right: NULL);"]
    # a callee that never reads its last register parameter: the caller wrote it
    assert _lift_358(_REGS_358 + _PUSH3_358 + load(0x10) + call, pool,
                     _callee_358(None, ("x1",), desc=True)) == [
        "return sub_0x100(7, 9, left: NULL, top: NULL, right: NULL);"]
    # everything in registers, nothing pushed
    assert _lift_358(_REGS_358 + load(0x48) + call, pool, two) == [
        "return sub_0x100(7, 9);"]
    # a generic call: nothing in a register, the type-argument vector pushed first
    assert _lift_358([("mov", "x0, #3"), ("stp", "x0, x1, [x15, #8]"),
                      ("str", "x22, [x15]")] + load(0x20) + call, pool, none) == [
        "return sub_0x100(x1, 3, onError: NULL);"]
    # before 3.4 everything is pushed, and a register written says nothing
    old = _callee_358(None, (), desc=True, convention="stack")
    assert _lift_358(_REGS_358 + [("stp", "x22, x1, [x15]")] + load(0x38) + call,
                     pool, old) == ["return sub_0x100(7, n: NULL);"]
    # a dispatch call: the receiver is argument zero and prints as the base. It
    # printed `x0.sel_0x40()`, the one argument dropped as the receiver.
    recv = [("mov", "x1, x0")]
    assert _lift_358(recv + [("str", "x22, [x15]")] + load(0x28) + _DISPATCH_358,
                     pool, two) == ["return x0.sel_0x40(colorSpace: NULL);"]
    assert _lift_358(recv + [("mov", "x2, #9"), ("str", "x22, [x15]")] + load(0x40)
                     + _DISPATCH_358, pool, two) == ["return x0.sel_0x40(9, NULL);"]


def test_a_call_whose_descriptor_is_not_read_or_not_met_prints_no_list():
    """#358: a descriptor's list is all of it or `...`. Each of these printed what was
    pushed as the whole list."""
    pool = _pool_358(*_POOL_358)
    load = lambda off: [("ldr", f"x4, [x27, #{off:#x}]")]
    two = _callee_358(None, ("x1", "x2"), desc=True)
    none = _callee_358(None, (), desc=True)
    call, no = [("bl", "#0x100")], ["return sub_0x100(...);"]
    # fewer words pushed than its size
    assert _lift_358(_REGS_358 + _PUSH3_358[1:] + load(0x10) + call, pool, two) == no
    # nothing shows the second register carries an argument: it could be a double
    assert _lift_358(_REGS_358[:1] + _PUSH3_358 + load(0x10) + call, pool,
                     _callee_358(None, ("x1",), desc=True)) == no
    # a register past the count carries one
    assert _lift_358(_REGS_358 + [("mov", "x3, #1")] + _PUSH3_358 + load(0x10) + call,
                     pool, two) == no
    assert _lift_358(_REGS_358 + _PUSH3_358 + load(0x10) + call, pool,
                     _callee_358(None, ("x1", "x2", "x3"), desc=True)) == no
    # an Array that is no descriptor, and x4 written from somewhere else
    assert _lift_358(_PUSH3_358 + load(0x30) + call, pool, none) == no
    assert _lift_358(_PUSH3_358 + [("mov", "x4, x0")] + call, pool, none) == no
    # a release whose convention nobody read
    assert _lift_358([("stp", "x22, x1, [x15]")] + load(0x38) + call, pool,
                     _callee_358(None, (), desc=True, convention=None)) == no
    # a callee that reads x4, and no descriptor loaded for it
    assert _lift_358([("stp", "x22, x1, [x15]")] + call, pool, none) == no
    # one of the VM's own descriptors, a base object: nothing is in a register, so a
    # register written for the call contradicts it
    assert _lift_358(_REGS_358 + _PUSH3_358 + load(0x18) + call, pool, none) == no
    # ...and with none written what was pushed is the list. (Passes on main: a guard.)
    assert _lift_358(_PUSH3_358 + load(0x18) + call, pool, none) == [
        "return sub_0x100(NULL, NULL, NULL);"]
    # a dispatch call whose first argument is not the receiver it prints as its base
    assert _lift_358([("mov", "x1, x0"), ("mov", "x9, #3"), ("stp", "x22, x9, [x15]")]
                     + load(0x38) + _DISPATCH_358, pool, two) == [
        "return x0.sel_0x40(...);"]


def test_a_call_with_no_descriptor_lists_every_register_it_is_handed_or_none():
    """#358, the same rule without a descriptor. A callee that reads x2 and not x1
    printed `f()`; one handed more registers than it reads printed the ones it reads;
    a dispatch call with its receiver in x1 printed the words pushed, less the first
    as the receiver, whatever it was."""
    call = [("bl", "#0x100")]
    # the registers run to the highest one read
    assert _lift_358(_REGS_358 + call, None, _callee_358(0, ("x2",))) == [
        "return sub_0x100(7, 9);"]
    # x2 is written for the call and the callee is not seen to read it
    assert _lift_358(_REGS_358 + call, None, _callee_358(1, ("x1",))) == [
        "return sub_0x100(...);"]
    # a word pushed for a callee that reads only registers
    assert _lift_358(_REGS_358 + [("str", "x22, [x15]")] + call, None,
                     _callee_358(2, ("x1", "x2"))) == ["return sub_0x100(...);"]
    # registers written for a callee that reads only the stack
    assert _lift_358(_REGS_358 + [("str", "x22, [x15]")] + call, None,
                     _callee_358(None)) == ["return sub_0x100(...);"]
    # a dispatch call: a register argument beside what is pushed
    recv = [("mov", "x1, x0")]
    assert _lift_358(recv + [("mov", "x2, #9"), ("str", "x22, [x15]")]
                     + _DISPATCH_358, None, _callee_358(None)) == [
        "return x0.sel_0x40(...);"]
    # ...and a first word pushed that is not the receiver
    assert _lift_358([("mov", "x9, #3"), ("stp", "x22, x9, [x15]")] + _DISPATCH_358,
                     None, _callee_358(None)) == ["return x1.sel_0x40(...);"]
    # before 3.4 a callee that reads no argument is still handed what was pushed, and
    # that is every argument: it printed `sub_0x100()`. Nothing pushed is no argument,
    # which passes on main.
    old = _callee_358(0, convention="stack")
    assert _lift_358(_REGS_358 + [("str", "x22, [x15]")] + call, None, old) == [
        "return sub_0x100(NULL);"]
    assert _lift_358(_REGS_358 + call, None, old) == ["return sub_0x100();"]
    # Guards, which pass on main. The receiver pushed first is left out of the list;
    # before 3.4 a register written is no argument; a call through a Code's entry
    # point is a stub's, with registers of its own (#280); and with no resolver the
    # list is what was pushed.
    assert _lift_358(recv + [("stp", "x22, x1, [x15]")] + _DISPATCH_358, None,
                     _callee_358(None)) == ["return x0.sel_0x40(NULL);"]
    assert _lift_358(_REGS_358 + [("str", "x22, [x15]")] + call, None,
                     _callee_358(None, convention="stack")) == [
        "return sub_0x100(NULL);"]
    assert _lift_358([("stp", "x22, x1, [x15]"), ("mov", "x1, #1"),
                      ("ldr", "x30, [x27, #0x80]"), ("ldur", "x30, [x30, #7]"),
                      ("blr", "x30")], None, _callee_358(None)) == [
        "return pool_0x80.field_0x8(x1, NULL);"]
    assert _lift_358(_REGS_358 + [("str", "x22, [x15]")] + call) == [
        "return sub_0x100(NULL);"]


def test_a_call_prints_no_list_with_an_argument_it_cannot_write():
    """#358, the review: a list is the call's only where each value in it is. `getOffset`
    printed `getOffsetY(this, a1)` for a call that also passes 0.0 in d0, to a callee
    that reads no V register on entry; `substring` printed `checkValidRange(x2, x2,
    ...)`, the incoming x2 and then what a join left in x2 under the same name; and a
    descriptor the VM made printed the one word both ways in agree on as the list."""
    pool = _pool_358(*_POOL_358)
    load = lambda off: [("ldr", f"x4, [x27, #{off:#x}]")]
    call = [("bl", "#0x100")]
    two = _callee_358(2, ("x1", "x2"))
    # a V register written for the call, the callee not seen to read one
    assert _lift_358(_REGS_358 + [("fmov", "d0, #1.0")] + call, None, two) == [
        "return sub_0x100(...);"]
    assert _lift_358(_REGS_358 + [("eor", "v0.16b, v0.16b, v0.16b")] + call, None,
                     two) == ["return sub_0x100(...);"]
    # ...and beside a descriptor that counts two in registers
    assert _lift_358(_REGS_358 + [("fmov", "d0, #1.0")] + load(0x48) + call, pool,
                     _callee_358(None, ("x1", "x2"), desc=True)) == [
        "return sub_0x100(...);"]
    # x1 is the incoming x2 and x2 what one way in loaded: one name, two values
    lost = [("mov", "x1, x2"), ("cbz", "x0, #0xc"), ("ldur", "x2, [x9, #7]")]
    assert _lift_358(lost + call, None, two)[-1] == "return sub_0x100(...);"
    # ...and a word pushed out of the register the join lost
    assert _lift_358(lost + [("str", "x2, [x15]")] + load(0x18) + call, pool,
                     _callee_358(None, (), desc=True))[-1] == "return sub_0x100(...);"
    # a descriptor the VM made does not count: two more words pushed one way in only
    some = [("str", "x22, [x15]"), ("cbz", "x0, #0xc"), ("stp", "x22, x22, [x15, #8]")]
    assert _lift_358(some + load(0x18) + call, pool,
                     _callee_358(None, (), desc=True))[-1] == "return sub_0x100(...);"
    # what an earlier call left in x1 is no argument: it printed `var t0; sub_0x200(7);
    # return sub_0x100(t0);`, a read of a name nothing assigns
    assert _lift_358([("mov", "x1, #7"), ("bl", "#0x200")] + call, None,
                     _callee_358(1, ("x1",))) == [
        "sub_0x200(7);", "return sub_0x100(...);"]
    # Guards, which pass on main. The VM's descriptor over words this block pushed
    # lists them. A receiver pushed first and its register used again is the base,
    # off its slot, and the rest is the list (#377).
    assert _lift_358([("stp", "x22, x22, [x15]")] + load(0x18) + call, pool,
                     _callee_358(None, (), desc=True)) == [
        "return sub_0x100(NULL, NULL);"]
    assert _lift_358([("ldur", "x0, [x2, #-1]"), ("ubfx", "x0, x0, #0xc, #0x14"),
                      ("str", "x2, [x15, #8]"), ("ldr", "x2, [x27, #0x80]"),
                      ("str", "x2, [x15]"), ("add", "x30, x0, #0x40"),
                      ("ldr", "x30, [x21, x30, lsl #3]"), ("blr", "x30")], pool,
                     _callee_358(None))[-1] == "return x2.sel_0x40(pool_0x80);"


def test_an_arguments_descriptor_is_read_from_its_array_in_full_or_not_at_all():
    """#358: what `build_pool_map` keeps of a descriptor, and what it refuses. A number
    the VM snapshot holds is a base ref, and its value is the one the rest leaves."""
    from jadart import disasm
    descs = _pool_358(*_POOL_358).descs
    assert descs[0x10] == (0, 5, 3, (None, None, "left", "top", "right"))
    assert descs[0x20] == (1, 2, 2, (None, "onError"))
    assert descs[0x48] == (0, 2, 0, (None, None))
    assert descs[0x18] == disasm.CACHED_DESC and 0x30 not in descs
    # Not read: a name that is no identifier or longer than one, a position twice, a
    # count past the cap, a size past the count, and no null at the end.
    for bad in ((0, 2, 1, (("a b", 1),)), (0, 2, 1, (("a" * 65, 1),)),
                (0, 3, 1, (("a", 2), ("b", 2))), (0, 256, 256, ()),
                [105, 102, 103, 102, 1], [105, 102, 102, 102, 105]):
        assert not _pool_358(bad).descs, bad
    # Without a second descriptor to say what the base Smi is, a type_args_len that
    # names it is not known; and a base ref is no value this snapshot has a Smi for.
    assert _pool_358((0, 2, 1, (("n", 1),))).descs[0x10][0] is None
    assert list(_pool_358((0, 2, 0, ()), [101, 102, 102, 5, 1]).descs) == [0x10]
    # Each Array once, however many slots name it (#91).
    calls, was = [0], disasm._args_desc

    def counted(*a):
        calls[0] += 1
        return was(*a)
    disasm._args_desc = counted
    try:
        many = _pool_358(*[_POOL_358[0]] * 2).descs
        again = disasm.build_pool_map(__import__("types").SimpleNamespace(
            functions=[], names={}, strings={}, first_ref=10, smi_values={101: 1, 102: 2},
            pool=[("ref", 200)] * 4000, arrays={200: (5, 102, 5, 102, 1)}))
    finally:
        disasm._args_desc = was
    assert len(many) == 2 and len(again.descs) == 4000 and calls[0] <= 6, calls


def test_the_rows_before_a_call_say_what_its_argument_registers_hold():
    """#358: `_call_sites`, the descriptor a call is handed and the argument
    registers written for it, and `_args_convention`, the releases that is read in."""
    from jadart.expr import _call_sites, _args_convention

    def sites(rows):
        return list(_call_sites([(i * 4, mn, op, "") for i, (mn, op)
                                 in enumerate(rows)]).values())
    assert sites([("mov", "x1, x0"), ("ldr", "x4, [x27, #0x58]"), ("bl", "#0x100"),
                  ("bl", "#0x100")]) == [(0x58, 0, False, 0), (None, -1, False, 0)]
    # a far slot, and a descriptor outlives a read of x4
    assert sites([("add", "x4, x27, #0x8, lsl #12"), ("ldr", "x4, [x4, #0x10]"),
                  ("mov", "x9, x4"), ("bl", "#0x100")]) == [(0x8010, -1, False, 0)]
    # anything else in x4 is not one, unless it was read: then it was a temporary
    assert sites([("mov", "w4, #1"), ("bl", "#0x100")]) == [(-1, -1, False, 0)]
    assert sites([("ldr", "x4, [x4, #0x10]"), ("bl", "#0x100")]) == [(-1, -1, False, 0)]
    assert sites([("mov", "x4, x0"), ("add", "x5, x4, #1"), ("bl", "#0x100")]) == [
        (None, 3, False, 0)]
    # a register read since it was written is not written for the call, nor is the
    # one the call goes through; a V register is its own class
    assert sites([("mov", "x2, x0"), ("ldur", "x3, [x2, #7]"), ("fmov", "d1, x0"),
                  ("blr", "x3")]) == [(None, -1, True, 0)]
    # the words the block stored off SP, a pair as two, counted again after a call
    assert sites([("stp", "x0, x1, [x15, #8]"), ("str", "x2, [x15]"),
                  ("stur", "x2, [x29, #-8]"), ("bl", "#0x100"),
                  ("str", "x0, [x15, #-8]!"), ("bl", "#0x100")]) == [
        (None, -1, False, 3), (None, -1, False, 1)]
    assert [_args_convention(v) for v in ("2.18.6", "2.19.6", "3.3.4", "3.4.0",
                                          "3.13.0", "3.14.0", "", None)] == [
        None, "stack", "stack", "reg", "reg", None, None, None]


def test_the_resolver_keeps_the_registers_a_callee_handed_a_descriptor_reads():
    """#358: `entry_arity` declines for a function that reads x4, and a call handed
    a descriptor still has to know which argument registers that function reads."""
    from jadart.expr import _entry_read, StackArity
    rows = lambda rs: [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rs)]
    got = _entry_read(rows([("ldur", "w0, [x4, #0xf]"), ("ldur", "x9, [x1, #7]"),
                            ("ldur", "x9, [x3, #7]"), ("ret", "")]), False)
    assert got == (None, (), (("x1", "x3"), True, None))
    assert _entry_read(rows([("ldur", "x9, [x2, #7]"), ("ret", "")]), False) == (
        0, ("x2",), (("x2",), False, False))
    # only stack arguments: the V registers are looked at where asked
    stack = rows([("ldr", "x9, [x15]"), ("fadd", "d2, d0, d0"), ("ret", "")])
    assert _entry_read(stack, False) == (None, (), ((), False, None))
    assert _entry_read(stack, False, True) == (None, (), ((), False, True))
    six = _entry_read(rows([("ldur", f"x9, [{r}, #7]") for r in
                            ("x1", "x2", "x3", "x5", "x6", "x7")]
                           + [("ldr", "x9, [x15]"), ("ret", "")]), False)
    assert isinstance(six[0], StackArity) and six[2] == (six[1], False, six[0].fpu)


def test_remove_view_insets_on_the_clean_fixture_prints_every_argument():
    """#358 as reported, through the library API: each `copyWith` in
    `removeViewInsets` on the clean fixture passes x1, or x1 and x2, beside what it
    pushes, and names what it pushes."""
    _needs_capstone()
    lists = [m for fn in jadart.decompile(CLEAN, "removeViewInsets")
             for ln in fn["body"] for m in re.findall(r"copyWith\(([^()]*)\)", ln)]
    assert len(lists) == 3, lists
    for got in lists[:2]:
        args = got.split(", ")
        assert len(args) == 5 and args[2:] == ["left: NULL", "top: NULL",
                                               "right: NULL"], lists
    last = lists[2].split(", ")
    assert len(last) == 3 and last[1].startswith("viewPadding: ") and (
        last[2].startswith("viewInsets: ")), lists


def test_a_call_to_a_function_that_takes_a_double_does_not_list_its_other_arguments():
    # Dart passes doubles in V0 to V5, apart from the x registers (kFpuRegistersForArgs).
    # entry_arity counted only the x registers, so a call to `f(Object a, double b)`,
    # which reads x1 and d0, printed `f(x1)`, and one to `lerp(double, double, double)`
    # printed its arguments as the fields its caller happened to pass in x1 and x2 (#155).
    # A register argument list cannot say where the doubles go, so such a callee declines.
    from jadart.expr import entry_arity, lift_function

    def arity(rows):
        return entry_arity([(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])
    # reads x1 and a double in d0: no register list says where the double goes
    assert arity([("ldur", "x9, [x1, #7]"), ("fadd", "d2, d0, d0"), ("ret", "")]) is None
    # a double in d0 and nothing else, where main printed `()`
    assert arity([("fadd", "d2, d0, d0"), ("ret", "")]) is None
    # a later double argument, in d3
    assert arity([("ldur", "x9, [x1, #7]"), ("ldur", "x9, [x2, #7]"),
                  ("fadd", "d4, d3, d3"), ("ret", "")]) is None
    # one that reads a double before a write of it does take it; the zero idiom and a
    # write first do not
    assert arity([("eor", "v0.16b, v0.16b, v0.16b"), ("ret", "")]) == 0
    assert arity([("fmov", "d0, #1.0"), ("fadd", "d2, d0, d0"), ("ret", "")]) == 0
    # A `ret` that hands d0 back is not a double argument: a function reading only x1 and
    # returning its object in x0 writes neither d0 nor x0 and makes no call, so it has
    # the same bare `ret`. It keeps its register count. (Passes on main.)
    assert arity([("ldur", "x9, [x1, #7]"), ("ret", "")]) == 1
    assert arity([("ldur", "x0, [x1, #7]"), ("ret", "")]) == 1
    # but a real read of the double in the body, beside that `ret`, does count
    assert arity([("fcmp", "d0, #0.0"), ("b.eq", "#0x8"), ("ret", ""),
                  ("ret", "")]) is None

    def call(k):
        rows = [("mov", "x1, #5"), ("fmov", "d0, #1.0"), ("bl", "#0x100"), ("ret", "")]
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)], arity=lambda pc: k)]
    # a callee that takes a double declines, and so does one that reads no V register
    # where the caller wrote one for the call: `sub_0x100(5)` left the double out (#358)
    assert call(None) == ["return sub_0x100(...);"]
    assert call(1) == ["return sub_0x100(...);"]


def test_an_insert_into_an_upper_lane_keeps_the_double_in_the_low_lane():
    # d0, v0.16b and q0 are one register, and #114 forgot the double under dN on any
    # write to a wider spelling. An insert into a lane entirely in the upper 64 bits
    # (`ins v0.d[1], x5`, `mov v0.d[1], ...`, `fmov v0.d[1], x5`, `.s[2]` and up) leaves
    # the low 64, which dN names, unchanged, so forgetting dN there declined a double the
    # machine still holds (#134). An insert into the low lane does change dN.
    from jadart.expr import lift_function, _upper_lane

    def lift(mid):
        rows = [("fadd", "d0, d1, d2"), mid, ("stur", "d0, [x2, #7]"), ("ret", "")]
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])]
    # upper-lane inserts keep d0 = d1 + d2
    assert lift(("ins", "v0.d[1], x5"))[-2] == "x2.field_0x8 = d1 + d2;"
    assert lift(("mov", "v0.d[1], v3.d[0]"))[-2] == "x2.field_0x8 = d1 + d2;"
    assert lift(("fmov", "v0.d[1], x5"))[-2] == "x2.field_0x8 = d1 + d2;"
    assert lift(("ins", "v0.s[2], w5"))[-2] == "x2.field_0x8 = d1 + d2;"
    # the insert still prints, its upper lane not being modelled
    assert any(ln.startswith("ins v0.d[1]") for ln in lift(("ins", "v0.d[1], x5")))
    # a write to the low lane changes dN, so it is forgotten and reads as itself
    assert lift(("ins", "v0.d[0], x5"))[-2] == "x2.field_0x8 = d0;"
    assert lift(("ins", "v0.s[0], w5"))[-2] == "x2.field_0x8 = d0;"
    assert lift(("ins", "v0.s[1], w5"))[-2] == "x2.field_0x8 = d0;"
    # a full-width write still forgets d0, as before (#114)
    assert lift(("mov", "v0.16b, v3.16b"))[-2] == "x2.field_0x8 = d3;"
    assert lift(("eor", "v0.16b, v0.16b, v0.16b"))[-2] == "x2.field_0x8 = 0.0;"
    # _upper_lane: the low element of each size is not upper
    assert [_upper_lane("v0." + s) for s in ("d[1]", "d[0]", "s[2]", "s[1]", "h[4]",
            "h[3]", "b[8]", "b[7]")] == [True, False, True, False, True, False, True, False]


def test_a_phi_name_nothing_reads_is_dropped():
    # `_phi` and `_render_loop` bind a name at a join or loop header whenever the paths
    # disagree about a register, before it is known whether the result is read. Where
    # nothing reads it, the declaration and the writes to it say nothing, `var t10 = t1;`
    # on an allocation slow path among them (#169). They go together, and stay whole where
    # dropping them would empty an if-arm or a loop body.
    from jadart.expr import _drop_dead_phis, lift_function, StackArity

    # the pass itself: a dead phi goes, decl and every assignment
    L = ["  var t0 = x1;", "  return x0;"]
    assert _drop_dead_phis(L, {"t0"}) == ["  return x0;"]
    split = ["  var t0;", "  if (c) {", "    t0 = x1;", "    keep();", "  } else {",
             "    t0 = x2;", "    other();", "  }", "  return x0;"]
    assert all("t0" not in ln for ln in _drop_dead_phis(split, {"t0"}))
    # a live phi stays
    live = ["  var t0 = x1;", "  t0 = t0 + 1;", "  return t0;"]
    assert _drop_dead_phis(live, {"t0"}) == live
    # kept whole where dropping would leave an arm holding nothing else
    alone = ["  var t0;", "  if (c) {", "    t0 = x1;", "  } else {", "    foo();", "  }",
             "  return x0;"]
    assert _drop_dead_phis(alone, {"t0"}) == alone
    # never dropped where an assignment makes a call: the call is a side effect
    call = ["  var t0;", "  t0 = foo(...);", "  bar();", "  return x0;"]
    assert _drop_dead_phis(call, {"t0"}) == call

    def lift(rows, **kw):
        rows = list(rows) + [("ret", "")]
        at, n = {}, 0
        for r in rows:
            if isinstance(r, str):
                at[r] = n * 4
            else:
                n += 1
        ann = []
        for r in (r for r in rows if not isinstance(r, str)):
            op = r[1]
            for nm, a in at.items():
                op = op.replace("@" + nm, "#%#x" % a)
            ann.append((len(ann) * 4, r[0], op, ""))
        return [ln.strip() for ln in lift_function(ann, **kw)]
    regs = [("mov", f"{r}, #{n}") for n, r in enumerate(("x1", "x2", "x3", "x5", "x6",
                                                         "x7"), 1)]
    one = {"arity": lambda pc: StackArity(6, 1)}
    # a loop carries the six argument registers for a call that declines to `...`, and
    # nothing reads them: the dead carries go, the call and the loop stay.
    out = lift(regs + [("str", "x9, [x15]"), "top", ("bl", "#0x200"),
                       ("stur", "x10, [x29, #-0x10]"), ("cbnz", "x20, @top")], **one)
    # The call's own number moves: it declares each clobbered register it left live
    # first, and those declarations are what the dead carries read (#176). The six that
    # are left over once the carries go are `_drop_unread`'s pass order, which its last
    # call already names and does not fix outside `blind_named`.
    assert any(re.fullmatch(r"var t\d+ = sub_0x200\(\.\.\.\);", ln) for ln in out), out
    assert not any(ln.startswith("var t0") or ln == "t0 = x1;" for ln in out), out
    assert not any(re.search(r"\{\s*\}", ln) for ln in out)
    # a loop whose carry is read keeps it
    out = lift([("mov", "x19, x1"), "top", ("bl", "#0x100"), ("add", "x19, x19, #1"),
                ("cbnz", "x20, @top"), ("stur", "x19, [x2, #7]")])
    assert "var t0 = x1;" in out and "x2.field_0x8 = t0;" in out, out

    # and the if-join phi `_phi` binds: `values` on the clean fixture leaves a value NULL
    # unless a field is set, then nothing reads it, `var t = NULL; if (..) { t = ..; }`.
    _needs_capstone()
    import jadart
    body = [ln.strip() for ln in jadart.decompile(CLEAN, "0x29ce18")[0]["body"]]
    assert not any(ln.endswith("= NULL;") for ln in body), body
    assert "var t0 = pool_0x218.field_0x8(...);" in body, body


def test_a_call_whose_double_result_is_read_names_it():
    # A double comes back in d0, and a call's d0 result was never named: it read as d0,
    # which is also how the d0 the function was handed reads, and `ratioOfTones`
    # compared two calls' results as `d0 > d0` (#134).
    from jadart.expr import lift_function

    def lift(rows):
        rows = rows + [("ret", "", "")]
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, n) for i, (mn, op, n) in enumerate(rows)])]
    assert lift([("bl", "#0x100", "  ; -> foo"), ("stur", "d0, [x29, #-8]", ""),
                 ("bl", "#0x200", "  ; -> bar"), ("ldur", "d1, [x29, #-8]", ""),
                 ("fcmp", "d1, d0", ""), ("cset", "x0, gt", "")]) == [
        "var t0 = foo(...);", "var t1 = bar(...);", "return t0 > t1 ? 1 : 0;"]
    # A `ret` reads both registers, and is no evidence: this call returns nothing read.
    assert lift([("bl", "#0x100", "  ; -> foo"), ("mov", "x0, x22", "")]) == [
        "foo(...);", "return NULL;"]
    # Nor does the zero idiom, which writes d0 and reads nothing.
    assert lift([("bl", "#0x100", "  ; -> foo"), ("eor", "v0.16b, v0.16b, v0.16b", ""),
                 ("bl", "#0x200", "  ; -> bar"), ("mov", "x0, x22", "")]) == [
        "foo(...);", "bar(...);", "return NULL;"]
    # Nor does a `ret` read the register it does not hand back: d0 was live up to every
    # `return NULL;`, and each join on the way took a phi for it that nothing reads.
    assert lift([("bl", "#0x100", "  ; -> foo"), ("fcmp", "d0, #0.0", ""),
                 ("b.le", "#0x14", ""), ("bl", "#0x200", "  ; -> bar"), ("nop", "", ""),
                 ("mov", "x0, x22", "")]) == [
        "if (foo(...) > 0.0) {", "bar(...);", "}", "return NULL;"]
    # Where x0 is read after it, the result is x0's, as before.
    # The store's base is the name the call declares for x2, which it clobbers like any
    # other volatile register (#176); the result being x0's is what this line is for.
    got = lift([("bl", "#0x100", "  ; -> foo"), ("stur", "x0, [x2, #7]", "")])
    base = re.fullmatch(r"var (t\d+);", got[0])
    res = re.fullmatch(r"var (t\d+) = foo\(\.\.\.\);", got[1])
    assert base and res, got
    assert got[2] == f"{base.group(1)}.field_0x8 = {res.group(1)};", got
    # A stub's result is an object; the double an allocation is for stays d0.
    # The stub call declares what it left in x2, which the `ret` reads, where a bare x2
    # read as the value the function came in with (#176). The allocation and its d0 are
    # the point.
    got = lift([("fmov", "d0, #1.0", ""),
                ("bl", "#0x300", "  ; -> stub _iso_stub_AllocateDoubleStub"),
                ("stur", "d0, [x0, #7]", ""), ("mov", "x0, x2", "")])
    m = re.fullmatch(r"var (t\d+);", got[0])
    assert m and got[1:] == ["new double().field_0x8 = d0;",
                             f"return {m.group(1)};"], got


def test_a_loop_names_what_it_computed_over_a_raw_write_it_printed():
    # A register a loop writes is forgotten at its exits and prints as itself, which reads
    # as the last value a printed line put in it: `umulh x7` printed, `add x7, x5, x1`
    # not, and the store after the loop printed `x7` where the machine has `x5 + x1`
    # (#123).
    from jadart.expr import lift_function

    def lift(tail):
        rows = [("mov", "x9, #2"), ("umulh", "x7, x10, x3"), ("add", "x7, x5, x1"),
                ("sub", "x9, x9, #1"), ("tbz", "x9, #63, #0x4")] + tail + [("ret", "")]
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])]
    body = lift([("stur", "x7, [x2, #95]")])
    assert "umulh x7, x10, x3" in body and body.count("t0 = x5 + x1;") == 2, body
    assert "x2.field_0x60 = t0;" in body, body
    # Read only by a call that prints `(...)`, the name would say nothing: no name.
    body = lift([("ldur", "w2, [x7, #0x13]"), ("bl", "#0x40")])
    assert not any(ln.endswith("= x5 + x1;") for ln in body), body
    # The name starts from the value before the loop: a break that comes before the
    # body writes the register reads that, and an unset name read it as nothing. The
    # loop has to WRITE x7 for any of this to be about it, which it does here with the
    # raw `umulh`: where only the block BEFORE the loop wrote it, the register is not
    # forgotten at the exit and the value is printed where it is read, with no name
    # minted at all (#228).
    from jadart.expr import lift_function
    rows = [("add", "x7, x5, x1"), ("mov", "x9, #2"), ("cbz", "x3, #0x18"),
            ("umulh", "x7, x10, x3"), ("sub", "x9, x9, #1"), ("tbz", "x9, #63, #0x8"),
            ("stur", "x7, [x2, #95]"), ("ret", "")]
    body = [ln.strip() for ln in lift_function(
        [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])]
    assert "var t0 = x5 + x1;" in body and "x2.field_0x60 = t0;" in body, body
    # Where the body prints no write to it, the bare register reads as nothing it says.
    rows = [("mov", "x9, #2"), ("add", "x7, x5, x1"), ("sub", "x9, x9, #1"),
            ("tbz", "x9, #63, #0x4"), ("stur", "x7, [x2, #95]"), ("ret", "")]
    body = [ln.strip() for ln in lift_function(
        [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])]
    assert "x2.field_0x60 = x7;" in body, body


def test_a_goto_backwards_out_of_a_loop_leaves_it():
    """Whether a goto leaves the loop is asked of the natural body, not of every ancestor
    of the header (#129).

    `_loop_nodes` closes BACKWARD over every predecessor, so it returns every ancestor of
    the header: on the clean fixture that put blocks which run before the loop into all
    6,131 of its loops, 70,789 such blocks. A goto back to one of those then read as
    staying inside the loop, so `_carry_out` wrote nothing back and the target read the
    loop's names holding what the PREVIOUS trip left, which is the hazard #123 is about
    at the other kind of edge. 46 gotos on each fixture answered this wrongly.

    `_loop_nodes` stays as it is where it is asked what the loop may WRITE, which wants an
    over-approximation, and where the blocks before the loop stand in for the ones between
    a store and the loop (#140). Replacing it there is a separate question, and the one
    the issue's own history records a revert for.
    """
    from jadart.cfg import build_cfg
    from jadart.expr import Lifter

    # Three blocks: the entry, a one-block loop at 0x8, and the return. The entry is a
    # predecessor of the header, so the ancestors closure holds it and the natural body
    # does not.
    rows = [("mov", "x5, #1"), ("add", "x5, x5, #1"),
            ("sub", "x9, x9, #1"), ("cbnz", "x9, #0x8"), ("ret", "")]
    blocks, entry = build_cfg(
        [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)], traps=())
    lf = Lifter(blocks, entry=entry)
    assert lf._loop_nodes(8) == frozenset({0, 8}), sorted(lf._loop_nodes(8))
    assert lf._back_loop(8) == frozenset({8}), sorted(lf._back_loop(8))
    # Walking that loop, a goto to the entry block leaves it: control is not at the
    # header again until it comes back round the way in.
    lf._carrying = [(8, {}, set())]
    assert lf._leaves_loop(entry) is True
    # ...and one to the header's own block does not.
    assert lf._leaves_loop(8) is False
    # Outside a loop the question does not arise.
    lf._carrying = []
    assert lf._leaves_loop(entry) is False


def _ranges_301(seed):
    """(rows, base, mono) of a random range for #301's guard: branches anywhere, so loops
    with several latches, a latch with both arms on the header, ways into a loop that
    skip its header, traps and returns, and in a third a monomorphic entry."""
    import random
    rng = random.Random(seed)
    n = rng.randrange(4, 64)
    base, mono, rows = 0, None, []
    if rng.random() < 0.3:
        base, mono, rows = 0x1000, 0x1008, list(_MONO_ROWS[:6])
    start = base + len(rows) * 4
    for _ in range(n):
        r = f"x{rng.randrange(4)}"
        t = f"#{start + rng.randrange(n + 1) * 4:#x}"
        rows.append(rng.choice([
            ("add", f"{r}, {r}, #1"), ("cmp", f"{r}, x1"), ("b.lt", t), ("b.ne", t),
            ("cbz", f"{r}, {t}"), ("cbnz", f"{r}, {t}"), ("b", t), ("ret", ""),
            ("brk", "#0")]))
    return rows + [("ret", "")], base, mono


def test_a_loop_body_holds_the_latches_a_scan_of_every_block_finds():
    """A guard test (#301). `structure`'s `loop_nodes` found a loop's latches by asking
    every block whether it jumps to the header and the header dominates it, and now takes
    them from the header's predecessors. This holds each loop body it returns, in tier 3
    lifts of 1,000 random ranges, to the body that scan gives, traced at the return with
    the graph and the dominance test the call had."""
    from jadart import cfg
    from jadart.expr import tier3_graph
    seen = {"loops": 0, "many": 0, "twice": 0, "outside": 0}

    def scanned(header, blocks, preds, dominates):
        latches = [n for n in blocks
                   if header in blocks[n].succ and dominates(header, n)]
        nodes, stack = {header}, list(latches)
        while stack:
            n = stack.pop()
            if n not in nodes:
                nodes.add(n)
                stack += [p for p in preds.get(n, ()) if dominates(header, p)]
        return nodes, latches

    def returned(frame, event, arg):
        if event == "return":
            header, up = frame.f_locals["header"], frame
            while up.f_code.co_name != "structure":
                up = up.f_back
            f = up.f_locals                     # the graph `structure` was handed
            want, latches = scanned(header, f["blocks"], f["preds"], f["dominates"])
            assert arg == want, (header, sorted(arg), sorted(want))
            seen["loops"] += 1
            seen["many"] += len(latches) > 1
            seen["twice"] += any(f["blocks"][n].succ.count(header) > 1 for n in latches)
            seen["outside"] += any(not f["dominates"](header, p)
                                   for p in f["preds"][header])
        return returned

    def calls(frame, _event, _arg):
        code = frame.f_code
        if code.co_name == "loop_nodes" and code.co_filename == cfg.__file__:
            return returned
        return None
    sys.settrace(calls)
    try:
        for seed in range(1000):
            rows, base, mono = _ranges_301(seed)
            tier3_graph([(base + i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)],
                        mono=mono)
    finally:
        sys.settrace(None)
    assert seen["loops"] > 600 and seen["many"] > 50, seen
    assert seen["twice"] > 0 and seen["outside"] > 500, seen


def test_a_loop_body_costs_the_same_per_instruction_at_any_length():
    """N loops in a row asked every block of the function whether it jumps to the loop's
    header, once per loop, to find the loop's latches: 3.0 million lines for 1,000 loops,
    and 2.50 s of `tier3_graph` at 8,000 loops where 2,000 took 0.16 (#301). Counted, not
    timed: the lines `structure`'s `loop_nodes` runs, per instruction, at 30 loops and at
    120. Scanning every block that was 35 and 125; from the header's predecessors, 3.6
    and 3.7."""
    from jadart import cfg
    from jadart.expr import tier3_graph
    ran = [0]

    def lines(frame, event, _arg):
        if event == "line":
            ran[0] += 1
        return lines

    def calls(frame, _event, _arg):
        code = frame.f_code
        if code.co_name == "loop_nodes" and code.co_filename == cfg.__file__:
            return lines
        return None

    def per_instruction(n):
        rows = []
        for _ in range(n):
            rows += [("add", "x2, x2, #1"), ("cmp", "x2, x1"),
                     ("b.lt", f"#{len(rows) * 4:#x}")]
        rows.append(("ret", ""))
        ran[0] = 0
        sys.settrace(calls)
        try:
            g = tier3_graph([(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])
        finally:
            sys.settrace(None)
        assert sum(s[0] == "loop" for s in g.stmts) == n, g.stmts
        return ran[0] / len(rows)
    small, large = per_instruction(30), per_instruction(120)
    assert 0 < small and large < 1.5 * small, (small, large)


def test_a_goto_out_of_a_loop_hands_on_what_the_last_trip_left():
    # A goto out of a loop handed its target the state the walk had at the jump, the
    # first trip's, where a register the loop writes later still held its value from
    # before the loop: `x2.field_0x60 = x5 + x1;`, and the CPU leaves on the second trip
    # with x6 + x1 (#154). The loop forgets such a register at its header.
    from jadart.expr import lift_function

    def lift(rows, **kw):
        return [ln.strip() for ln in lift_function(
            [(i * 4, r[0], r[1], r[2] if len(r) > 2 else "") for i, r in enumerate(rows)],
            **kw)]
    out = [("stur", "x7, [x2, #95]"), ("ret", "")]
    loop = [("mov", "x9, #2"), ("cmp", "x9, #1"), ("b.eq", "#0x20"),
            ("add", "x7, x6, x1"), ("sub", "x9, x9, #1"), ("tbz", "x9, #63, #0x8"),
            ("ret", "")]
    body = lift([("add", "x7, x5, x1")] + loop + out)
    assert body[-3:] == ["L_0x20:", "x2.field_0x60 = x7;", "return x0;"], body
    # One the loop does not write keeps its value, written after the loop or not.
    body = lift([("add", "x8, x5, x1")] + loop + [("stur", "x8, [x2, #95]"),
                                                  ("mov", "x8, #5"), ("ret", "")])
    assert "x2.field_0x60 = x5 + x1;" in body, body
    # Written on this trip before the goto, the value is this trip's, as before.
    body = lift([("add", "x7, x5, x1"), ("mov", "x9, #2"), ("add", "x7, x6, x1")]
                + loop[1:3] + loop[4:] + out)
    assert "x2.field_0x60 = x6 + x1;" in body, body
    # Where a printed line writes it, the bare register would read as that line's value,
    # so the loop carries it, as for a `break` (#123).
    body = lift([("add", "x7, x5, x1"), ("mov", "x9, #2"), ("cmp", "x9, #1"),
                 ("b.eq", "#0x24"), ("umulh", "x7, x10, x3")] + loop[3:] + out)
    assert "var t0 = x5 + x1;" in body and body.count("t0 = x6 + x1;") == 2, body
    assert "x2.field_0x60 = t0;" in body, body
    # Not where the target does not read it.
    body = lift([("add", "x8, x5, x1"), ("mov", "x9, #2"), ("cmp", "x9, #1"),
                 ("b.eq", "#0x24"), ("umulh", "x7, x10, x3")] + loop[3:]
                + [("stur", "x8, [x2, #95]"), ("ret", "")])
    assert "x2.field_0x60 = x5 + x1;" in body and "x6 + x1" not in str(body), body
    # A `break` before the trip writes it still carries it from its value before the
    # loop, as #123 has it.
    body = lift([("mov", "x7, #0"), ("mov", "x9, #2"), ("cmp", "x9, #1"),
                 ("b.eq", "#0x20"), ("umulh", "x7, x10, x3"), ("add", "x7, x5, x1"),
                 ("sub", "x9, x9, #1"), ("b", "#0x8")] + out)
    assert "var t0 = 0;" in body and "x2.field_0x60 = t0;" in body, body
    # ...and from the register where the loop had nothing for it: #123 took that for
    # the value before the loop, which a bare register is, and the store read the
    # `umulh` where the CPU has x5 + x1 from the trip before.
    body = lift([("mov", "x9, #2"), ("cbz", "x3, #0x18"), ("umulh", "x7, x10, x3"),
                 ("add", "x7, x5, x1"), ("sub", "x3, x3, #1"), ("b", "#0x4")] + out)
    assert "var t1 = x7;" in body and "x2.field_0x60 = t1;" in body, body
    # A goto whose target does not read it carries nothing: x7 here is the call's at
    # the `break`, and the store after the loop reads it bare, as before.
    body = lift([("mov", "x9, #2"), ("cmp", "x9, #1"), ("b.eq", "#0x2c"),
                 ("umulh", "x7, x10, x3"), ("bl", "#0x100"), ("cbz", "x0, #0x24"),
                 ("sub", "x9, x9, #1"), ("b", "#0x4"), ("ret", "")] + out
                + [("stur", "x8, [x2, #103]"), ("ret", "")])
    # x7 is the call's. The call declares what it left there, the loop carries that name
    # out, and the store says it where main said a bare x7 that read as the entry value
    # (#176). The carry still starts from the x7 the loop was entered with. x8 the callee
    # preserves, so the goto's target still reads it bare and carries nothing for x7.
    m = re.search(r"x2\.field_0x60 = (t\d+);", "\n".join(body))
    assert m and f"var {m.group(1)} = x7;" in body, body
    assert "x2.field_0x68 = x8;" in body, body
    # A join in the loop that names it starts from the register, not that value. The
    # declaration is at the TOP here, not inside the loop: the goto target reads it after
    # the loop closes, and a declaration inside the loop does not dominate that read
    # (#198). The assignment stays where the value is, so this is the same program.
    body = lift([("add", "x7, x5, x1"), ("mov", "x9, #2"), ("cbz", "x3, #0x10"),
                 ("add", "x7, x6, x1"), ("cmp", "x9, #1"), ("b.eq", "#0x24"),
                 ("sub", "x9, x9, #1"), ("tbz", "x9, #63, #0x8")] + out[1:] + out)
    assert body[0] == "var t1;" and "t1 = x7;" in body, body
    assert "x2.field_0x60 = t1;" in body, body
    # A goto out of two loops reads what the outer one wrote, and where a printed line
    # writes it, the outer loop carries it: on its first trip x8 is still x5 + x1.
    body = lift([("add", "x7, x5, x1"), ("mov", "x9, #2"), ("add", "x10, x9, #3"),
                 ("cmp", "x10, #1"), ("b.eq", "#0x2c"), ("sub", "x10, x10, #1"),
                 ("tbz", "x10, #63, #0xc"), ("add", "x7, x6, x1"), ("sub", "x9, x9, #1"),
                 ("tbz", "x9, #63, #0x8"), ("ret", "")] + out)
    assert "x2.field_0x60 = x7;" in body, body
    body = lift([("add", "x8, x5, x1"), ("mov", "x9, #2"), ("mov", "x10, #3"),
                 ("cmp", "x10, #1"), ("b.eq", "#0x30"), ("sub", "x10, x10, #1"),
                 ("tbz", "x10, #63, #0xc"), ("umulh", "x8, x6, x1"),
                 ("sub", "x9, x9, #1"), ("tbz", "x9, #63, #0x8"), ("ret", ""),
                 ("ret", ""), ("stur", "x8, [x2, #95]"), ("ret", "")])
    assert "var t0 = x5 + x1;" in body and "x2.field_0x60 = t0;" in body, body
    # Not a loop the goto stays in: the inner loop's goto into the outer body has the
    # `umulh` before it on every way there, and the outer loop names nothing.
    body = lift([("mov", "x9, #2"), ("mov", "x10, #3"), ("umulh", "x7, x6, x1"),
                 ("cmp", "x10, #1"), ("b.eq", "#0x24"), ("sub", "x10, x10, #1"),
                 ("tbz", "x10, #63, #0x8"), ("b", "#0x28"), ("ret", ""),
                 ("stur", "x7, [x2, #95]"), ("sub", "x9, x9, #1"),
                 ("tbz", "x9, #63, #0x4"), ("ret", "")])
    assert body[0] == "var t0 = 2;" and "x2.field_0x60 = x7;" in body, body
    # The target is a join, the block the outer loop leaves to as well. It now names the
    # value each way in holds, the goto's and the outer loop's own exit, rather than
    # reading x7 bare, which read the `umulh` a path that left first never ran (#123).
    body = lift([("add", "x7, x5, x1"), ("mov", "x9, #2"), ("mov", "x10, #3"),
                 ("cmp", "x10, #1"), ("b.eq", "#0x28"), ("umulh", "x7, x6, x1"),
                 ("sub", "x10, x10, #1"), ("tbz", "x10, #63, #0xc"),
                 ("sub", "x9, x9, #1"), ("tbz", "x9, #63, #0x8")] + out)
    # By shape, not by number, as the cases above it are: the number depends on how many
    # names are minted before it, and one fewer is now (#228).
    m = re.search(r"x2\.field_0x60 = (t\d+);", "\n".join(body))
    assert "var t0 = x5 + x1;" in body and m and f"var {m.group(1)};" == body[0], body
    # Not a loop the machine runs twice: the way back is past a trap, and the stack
    # check's slow path strip_boilerplate cut off is not part of the loop.
    for mid in (("brk", "#0"), ("nop", "")):
        body = lift([("add", "x7, x5, x1"), ("cbz", "x3, #0x20"), ("cmp", "x9, #1"),
                     ("b.eq", "#0x24"), mid, ("add", "x7, x6, x1"), ("b", "#0x4"),
                     ("ret", ""), ("ret", "")] + out)
        assert ("x2.field_0x60 = x5 + x1;" in body) == (mid[0] == "brk"), body
    # Nor does a slot such a header stores to come round with that value (#109).
    body = lift([("mov", "x5, #3"), ("stur", "x5, [x29, #-8]"),
                 ("ldur", "x0, [x29, #-8]"), ("stur", "x0, [x2, #7]"),
                 ("add", "x1, x0, #1"), ("stur", "x1, [x29, #-8]"), ("cbz", "x3, #0x24"),
                 ("brk", "#0"), ("b", "#0x8"), ("ret", "")])
    assert "x2.field_0x8 = 3;" in body, body
    body = lift([("add", "x7, x5, x1"), ("mov", "x9, #2"), ("ldr", "x16, [x26, #0x48]"),
                 ("cmp", "x15, x16"), ("b.ls", "#0x2c"), ("cmp", "x9, #1"),
                 ("b.eq", "#0x34"), ("sub", "x9, x9, #1"), ("tbz", "x9, #63, #0x8"),
                 ("ret", ""), ("ret", ""), ("bl", "#0x300"), ("b", "#0x14")] + out)
    assert "x2.field_0x60 = x5 + x1;" in body, body
    # A register each trip reloads from the slot it was saved in, after a call takes
    # it, still holds its value from before the loop: `compareTo` reads x6 so.
    def reload(mid, call=("bl", "#0x100"), pre=None, reg="x6"):
        rows = list(pre or [("mov", "x6, #5"), ("stur", "x6, [x29, #-8]")])
        rows.append(("mov", "x19, #2"))
        head = len(rows) * 4
        rows += [("cmp", "x19, #1"), None, call] + mid + [
            ("sub", "x19, x19, #1"), ("tbz", f"x19, #63, #{head:#x}"), ("ret", "")]
        rows[head // 4 + 1] = ("b.eq", f"#{len(rows) * 4:#x}")
        return lift(rows + [("stur", f"{reg}, [x2, #95]"), ("ret", "")])[-2]
    assert reload([("ldur", "x6, [x29, #-8]")]) == "x2.field_0x60 = 5;"
    # The base is a name here: this trip's `ldur x2` is the loop's own write, so after
    # the loop the machine holds the slot's value and not the x2 the function came in
    # with (#208). The VALUE, the 5 the slot holds, is what this asserts.
    assert reload([("ldur", "x2, [x29, #-8]"), ("mov", "x6, x2")]).endswith(
        ".field_0x60 = 5;")
    # A store beside the slot leaves it; and a double, reloaded after a call takes d6.
    for beside in (("stur", "x0, [x29, #-0x10]"), ("stp", "q0, q1, [x29, #-0x30]"),
                   ("sturb", "w0, [x29, #-9]"), ("sturh", "w0, [x29, #-0xa]"),
                   ("stur", "w0, [x29, #-0xc]"), ("stur", "x0, [x29]")):
        assert reload([beside, ("ldur", "x6, [x29, #-8]")]) == (
            "x2.field_0x60 = 5;"), beside
    double = [("fmov", "d6, #1.0"), ("stur", "d6, [x29, #-8]")]
    assert reload([("ldur", "d6, [x29, #-8]")], pre=double, reg="d6") == (
        "x2.field_0x60 = 1.0;")
    # Not where the trip stores to any byte of the slot, or through an index; reloads it
    # from another slot, whole or in a 128-bit load; writes it after the reload; reloads
    # only half of it; moves FP; or does not reload it at all.
    for mid, call in (([("ldur", "x6, [x29, #-8]"), ("stur", "x0, [x29, #-8]")], None),
                      ([("stur", "w0, [x29, #-4]"), ("ldur", "x6, [x29, #-8]")], None),
                      ([("sturb", "w0, [x29, #-1]"), ("ldur", "x6, [x29, #-8]")], None),
                      ([("stur", "w0, [x29, #-0xb]"), ("ldur", "x6, [x29, #-8]")], None),
                      ([("stp", "q0, q1, [x29, #-0x20]"), ("ldur", "x6, [x29, #-8]")],
                       None),
                      ([("ldur", "x6, [x29, #-8]"), ("str", "x0, [x29, x3]")], None),
                      ([("ldur", "x6, [x29, #-0x10]")], ("nop", "")),
                      ([("ldur", "x6, [x29, #-8]"), ("mov", "x6, x2")], None),
                      ([("ldur", "w6, [x29, #-8]")], None),
                      ([("ldrsw", "x6, [x29, #-8]")], None),
                      ([("add", "x29, x29, #0x10"), ("ldur", "x6, [x29, #-8]")], None),
                      ([("nop", "")], None)):
        assert reload(mid, call or ("bl", "#0x100")) == "x2.field_0x60 = x6;", mid
    # The same, for a trip that loads x2 itself. The store's base is a NAME there, because
    # after the loop the machine holds what the trip loaded and x2's own spelling says the
    # value the function came in with (#208). The reload is what this asserts, and it
    # still declines.
    assert reload([("ldur", "x2, [x29, #-8]"), ("mov", "w6, w2")],
                  ("bl", "#0x100")).endswith(".field_0x60 = x6;")
    for mid in ([("ldr", "q6, [x29, #-0x20]")], [("ldur", "q6, [x29, #-0x20]")],
                [("ldp", "q6, q7, [x29, #-0x40]")], [("ldr", "d6, [x29, #-0x20]")]):
        assert reload(mid, ("nop", ""), double, "d6") == "x2.field_0x60 = d6;", mid
    # Nor where the register held another value before the loop than the slot it is
    # reloaded from, or comes round with one the way in did not hand it: x6 = x7 is 9.
    assert reload([("ldur", "x6, [x29, #-0x10]")], pre=[
        ("mov", "x6, #5"), ("stur", "x6, [x29, #-8]"), ("mov", "x7, #7"),
        ("stur", "x7, [x29, #-0x10]")]) == "x2.field_0x60 = x6;"
    assert reload([("mov", "x6, x7"), ("ldur", "x7, [x29, #-8]")], ("nop", ""), [
        ("mov", "x6, #5"), ("stur", "x6, [x29, #-8]"), ("mov", "x7, #9")]) == (
        "x2.field_0x60 = x6;")
    # ...or where a frame address reaches a register, and a store through it can change
    # the slot.
    assert reload([("ldur", "x6, [x29, #-8]"), ("sub", "x3, x29, #0x10")]) == (
        "x2.field_0x60 = x6;")
    # A loop inside that takes it on its own way round, with nothing to reload it, is
    # one more way back.
    body = lift([("mov", "x6, #5"), ("stur", "x6, [x29, #-8]"), ("mov", "x19, #2"),
                 ("cmp", "x19, #1"), ("b.eq", "#0x30"), ("cbz", "x20, #0x24"),
                 ("bl", "#0x100"), ("b", "#0x14"), ("ret", ""), ("sub", "x19, x19, #1"),
                 ("tbz", "x19, #63, #0xc"), ("ret", ""), ("stur", "x6, [x2, #95]"),
                 ("ret", "")])
    assert "x2.field_0x60 = x6;" in body, body
    # Nor where the value is spelled with a register or reads memory: the slot holds
    # `x6 + 1` from before a call took x6 and the register the same text from after,
    # or the field, which a store in the loop changes and the reload does not.
    body = lift([("add", "x7, x6, #1"), ("stur", "x7, [x29, #-8]"), ("bl", "#0x100"),
                 ("add", "x7, x6, #1"), ("mov", "x19, #2"), ("cmp", "x19, #1"),
                 ("b.eq", "#0x30"), ("bl", "#0x100"), ("ldur", "x7, [x29, #-8]"),
                 ("sub", "x19, x19, #1"), ("tbz", "x19, #63, #0x14"), ("ret", "")] + out)
    assert body[-3:] == ["L_0x30:", "x2.field_0x60 = x7;", "return x0;"], body
    body = lift([("ldur", "x7, [x1, #7]"), ("stur", "x7, [x29, #-8]"), ("mov", "x19, #2"),
                 ("cmp", "x19, #1"), ("b.eq", "#0x28"), ("ldur", "x7, [x29, #-8]"),
                 ("stur", "x0, [x1, #7]"), ("sub", "x19, x19, #1"),
                 ("tbz", "x19, #63, #0xc"), ("ret", "")] + out, receiver={"x1": "this"})
    assert "x2.field_0x60 = x7;" in body, body


def test_a_loop_reload_costs_its_length():
    # Which registers a trip reloads from their slots was a set of every register and
    # slot pair, rebuilt at each instruction, so a loop that writes many registers after
    # many slots took the two counts multiplied: 7.4 s for the first shape here. Then
    # each frame store in the trip was checked against every slot held: 5.9 s for the
    # second. One value per register, and a store looks up only the keys it can touch,
    # so each costs a constant per instruction (#154). Timed, not counted: a count of
    # the instructions stepped would not have seen the first, whose cost was per
    # instruction. Timed as a ratio, each shape at a size and at half of it, the best of
    # three runs: linear gives 2 and quadratic 4, and a loaded machine slows both alike,
    # where a limit in seconds had less than three times headroom on CI (#162).
    import time
    from jadart.expr import lift_function
    regs = [0, 1, 3, 5, 6, 7, 8, 9, 10, 11, 12, 13]

    def shape(slots, body):
        rows = [("mov", f"x{r}, #5") for r in regs]
        for i in range(2, slots + 2):
            rows += [("mov", f"x17, #-{8 * i:#x}"), ("str", "x0, [x29, x17]")]
        rows.append(("mov", "x19, #2"))
        head = len(rows) * 4
        rows += [("cmp", "x19, #1"), None] + body + [("mov", f"x{r}, #1") for r in regs]
        rows += [("sub", "x19, x19, #1"), ("tbz", f"x19, #63, #{head:#x}"), ("ret", "")]
        rows[head // 4 + 1] = ("b.eq", f"#{len(rows) * 4:#x}")
        rows += [("stur", "x0, [x2, #95]"), ("ret", "")]
        return [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)]
    def took(ann):
        start = time.perf_counter()
        body = lift_function(ann)
        assert body[-2].strip() == "x2.field_0x60 = x0;", body[-2:]
        return time.perf_counter() - start
    for slots, body in ((2000, [("mov", f"x14, #{j % 7}") for j in range(8000)]),
                        (5000, [("stur", "x14, [x29, #-8]")] * 20000)):
        half, whole = shape(slots // 2, body[:len(body) // 2]), shape(slots, body)
        times = [(took(half), took(whole)) for _ in range(3)]
        small, large = min(t[0] for t in times), min(t[1] for t in times)
        assert large < 3 * small, (slots, small, large)


def test_a_double_result_read_past_the_next_instruction_is_named():
    # A call's d0 result read after a reload of x0, or through a join, printed as d0, the
    # d0 the function was handed (#152), and a `ret` one path reaches from a call and one
    # from the function's own double printed the x0 phi: `getOffsetX` (#127). Only a call
    # to a function that returns d0 counts, by its callers or by its own code.
    from jadart.expr import _read_after_call, lift_function

    def lift(rows, said, own=None):
        def returns(pc):
            return said(pc) if callable(said) else said
        returns.code_d0 = lambda pc: own
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, n) for i, (mn, op, n) in enumerate(rows)], returns=returns)]
    reload = [("bl", "#0x100", "  ; -> foo"), ("ldur", "x0, [x29, #-8]", ""),
              ("stur", "d0, [x0, #7]", ""), ("ret", "", "")]
    # The reload between the call and the store reads a slot the walk never saw a store
    # to, so it names the read rather than keeping x0 (#198); the result is still the
    # call's, which is what this test is about.
    assert lift(reload, "d0")[:3] == [
        "var t0 = foo(...);", "var t1 = (FP - 8).field_0x1;", "t1.field_0x8 = t0;"]
    assert lift(reload, None)[:3] == [
        "foo(...);", "var t0 = (FP - 8).field_0x1;", "t0.field_0x8 = d0;"]
    # Where the callers say nothing, the callee's own code decides (code_d0).
    assert lift(reload, None, own=True)[:3] == [
        "var t0 = foo(...);", "var t1 = (FP - 8).field_0x1;", "t1.field_0x8 = t0;"]
    assert lift(reload, None, own=False)[:3] == [
        "foo(...);", "var t0 = (FP - 8).field_0x1;", "t0.field_0x8 = d0;"]
    mixed = [("cbz", "x1, #0x10", ""), ("bl", "#0x100", "  ; -> foo"), ("b", "#0x14", ""),
             ("nop", "", ""), ("fmov", "d0, #1.0", ""), ("ret", "", "")]
    # (the `nop` nothing reaches goes after the body, and its goto names the else arm)
    assert lift(mixed, "d0")[:9] == ["var t1;", "if (x1 != 0) {", "var t0 = foo(...);",
                                     "t1 = t0;", "} else {", "L_0x10:", "t1 = 1.0;", "}",
                                     "return t1;"]
    # Not where a stub's or a register call's d0 may reach the `ret`, on any one path: a
    # stub's result is an object, and a register call's callee is unknown.
    three = [("cbz", "x1, #0x14", ""), ("cbz", "x2, #0x1c", ""), mixed[1],
             ("b", "#0x20", ""), ("nop", "", ""), ("fmov", "d0, #1.0", ""),
             ("b", "#0x20", ""), ("blr", "x9", ""), ("ret", "", "")]
    for rows in (mixed[:1] + [("bl", "#0x300", "  ; -> stub _iso_stub_FooStub")]
                 + mixed[2:], mixed[:1] + [("blr", "x9", "")] + mixed[2:], three):
        body = lift(rows, "d0")
        assert not any(ln.endswith(" = 1.0;") or ln == "return d0;" for ln in body), body
    # A slow path's save of d0 is not a read of it: a call whose double is only saved,
    # and a throw, which the next slow path's save follows in memory.
    keep = "  ; -> stub _iso_stub_StackOverflowSharedWithFPURegsStub"
    saved = [("bl", "#0x100", "  ; -> foo"), ("mov", "x0, x1", ""),
             ("str", "q0, [x15, #-0x10]!", ""), ("bl", "#0x200", keep),
             ("ldr", "q0, [x15], #0x10", ""), ("ret", "", "")]
    assert lift(saved, lambda pc: "d0" if pc == 0x100 else "x0")[0] == "foo(...);"
    # Nor is the restore, around a stub that gives every register back, a write: the d0
    # this `ret` hands back is the call's. The `ret` itself prints `d0`, because the
    # slot the save filled is dropped as x15 moves (#147).
    assert re.fullmatch(r"var t\d+ = foo\(\.\.\.\);", lift(saved, "d0")[0]), lift(
        saved, "d0")
    assert _read_after_call([(0, "str", "q0, [x15, #-0x10]!"),
                             (4, "fmov", "x0, d0")]) is None
    # A call's argument pushed is a read: `_adjustRect`'s callers pass on its Rect.
    assert _read_after_call([(0, "stp", "x0, x16, [x15, #-0x10]!")]) == "x0"
    assert _read_after_call([(0, "str", "d0, [x15, #-8]!")]) == "d0"
    # A stub, here an unnamed one on the slow path of a loop's stack check, gives every
    # register back: its callers say nothing, and the loop's d0 is not its result.
    loop = [("fmov", "d0, #1.0", ""), ("cbz", "x1, #0x18", ""), ("cbz", "x3, #0x20", ""),
            ("fadd", "d0, d0, d0", ""), ("sub", "x1, x1, #1", ""), ("b", "#0x4", ""),
            ("stur", "d0, [x2, #7]", ""), ("ret", "", ""), ("bl", "#0x300", ""),
            ("b", "#0xc", "")]
    body = lift(loop, None)
    # The phi's number moves with the names the stub's call site declares; `= d0;` is the
    # point, that this d0 is the loop's and not a result the call left (#176).
    m = re.search(r"\b(t\d+) = d0;", "\n".join(body))
    assert m and f"t0 = {m.group(1)} + {m.group(1)};" in body, body


def test_which_call_results_are_read_matches_a_walk_of_every_path():
    """A guard test (#296). `_d0_result_reads` carried the set of calls whose d0 may still
    be there forward, and now asks backward whether d0 is live past each call. Both have
    to be the answer of the plain question: a call in code the entry or a root reaches,
    on some path from which an instruction reads d0, or a `ret` hands it back, before
    anything writes it. On 400 random graphs, with loops, edges out of the map, blocks
    nothing reaches and extra roots, each instruction's kind is known here, and a walk
    of every path from every call is the oracle."""
    import random
    from jadart.cfg import Block
    from jadart.expr import _d0_result_reads
    kinds = [("call", "bl", "#0x100"), ("write", "blr", "x9"),
             ("write", "fmov", "d0, d1"), ("read", "fmov", "d1, d0"),
             ("both", "fadd", "d0, d0, d1"), ("none", "add", "x1, x1, #1"),
             ("ret", "ret", "")]
    seen = {True: 0, False: 0}
    for seed in range(400):
        rng = random.Random(seed)
        n = rng.randrange(1, 14)
        blocks, kind, returned = {}, {}, {}
        for i in range(n):
            b = 0x100 * i
            insns = []
            for j in range(rng.randrange(0, 5)):
                k, mn, op = rng.choice(kinds)
                a = b + 4 * j
                insns.append((a, mn, op, ""))
                if k == "ret":
                    returned[a] = rng.choice(("d0", "x0"))
                    k = "read" if returned[a] == "d0" else "none"
                kind[a] = k
            succ = [0x100 * rng.randrange(n) for _ in range(rng.randrange(0, 3))]
            if rng.random() < 0.1:
                succ.append(0xdead0)                     # out of the map
            blocks[b] = Block(b, insns, succ)
        entry = 0 if rng.random() < 0.95 else 0xbeef0
        roots = tuple(0x100 * rng.randrange(n) for _ in range(rng.randrange(0, 3)))

        def read_after(b, j):
            # Whether some path from just past instruction j of block b reads d0 before
            # anything writes it.
            done, todo = set(), [(b, j)]
            while todo:
                b, j = todo.pop()
                for (a, _mn, _op, _n) in blocks[b].insns[j:]:
                    if kind[a] in ("read", "both"):
                        return True
                    if kind[a] in ("call", "write"):
                        break
                else:
                    for s in blocks[b].succ:
                        if s in blocks and s not in done:
                            done.add(s)
                            todo.append((s, 0))
            return False
        reach, todo = set(), [r for r in (entry, *roots) if r in blocks]
        while todo:
            b = todo.pop()
            if b not in reach:
                reach.add(b)
                todo += [s for s in blocks[b].succ if s in blocks]
        want = {a for b in reach for j, (a, _m, _o, _n) in enumerate(blocks[b].insns)
                if kind[a] == "call" and read_after(b, j + 1)}
        got = _d0_result_reads(blocks, entry, returned, lambda *_a: True, roots)
        assert got == want, (seed, sorted(got), sorted(want))
        for a, k in kind.items():
            if k == "call":
                seen[a in want] += 1
    assert seen[True] > 100 and seen[False] > 100, seen


def test_which_call_results_are_read_costs_the_same_per_instruction_at_any_length():
    """N if/else diamonds in a row with a call in one arm: `_d0_result_reads` carried the
    set of calls whose d0 may still be there forward, rebuilt at each join and walked
    again each time it grew, and 1,000 diamonds took 8.05 s where 500 took 1.21 (#296).
    Counted, not timed: the lines of expr.py run inside the one call, per instruction,
    at 30 diamonds and at 120. Forward, that was 122 and 358, and growing with the length;
    backward, each block's bit is set once, and it is 48 and 44."""
    from jadart import expr
    from jadart.expr import _d0_result_reads, tier3_graph
    here = expr.__file__

    def per_instruction(n):
        rows = []
        for i in range(n):
            at = len(rows) * 4
            rows += [("cbz", f"x{i % 8}, #{at + 12:#x}"), ("ldr", "x10, [x27, #0x10]"),
                     ("b", f"#{at + 16:#x}"), ("bl", "#0x100"), ("ldur", "x9, [x10, #7]"),
                     ("stur", "x9, [x19, #7]")]
        ann = [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows + [("ret", "")])]
        g = tier3_graph(ann)
        ran = [0]

        def lines(frame, event, _arg):
            if event == "line":
                ran[0] += 1
            return lines

        def calls(frame, _event, _arg):
            return lines if frame.f_code.co_filename == here else None
        sys.settrace(calls)
        try:
            got = _d0_result_reads(g.blocks, g.entry, {}, lambda *_a: True, g.roots)
        finally:
            sys.settrace(None)
        assert got == frozenset(), got                 # no d0 is read
        return ran[0] / len(ann)
    small, large = per_instruction(30), per_instruction(120)
    assert large < 1.5 * small, (small, large)


def test_a_function_that_hands_back_its_double_argument_returns_d0():
    # `Curve.transform` returns its argument where it is 0.0 or 1.0, and never writes d0
    # itself, so no rule of the function's own code applied and it printed `return x0;`
    # (#127). Its callers read d0, and no call comes before that `ret`.
    from jadart.expr import lift_function

    def lift(said):
        rows = [("fcmp", "d0, #0.0", ""), ("b.eq", "#0x10", ""),
                ("bl", "#0x100", "  ; -> foo"), ("ret", "", ""), ("ret", "", "")]
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, n) for i, (mn, op, n) in enumerate(rows)],
            returns=lambda pc: said)]
    assert lift("d0") == ["if (d0 != 0.0) {", "return foo(...);", "} else {",
                          "return d0;", "}"]
    # Without the callers' word it is not decided.
    assert "return x0;" in lift(None)
    from jadart import expr as E
    from jadart.cfg import build_cfg

    def decide(rows):
        blocks, entry = build_cfg(_rows_at(rows, 0), traps=())
        return E._return_registers(blocks, entry, lambda: "d0")
    # A `ret` a path with a call also reaches, here the second to arrive, is not decided;
    # a stub that gives every register back is no call.
    assert decide([("fcmp", "d0, #0.0"), ("b.eq", "#0x10"), ("nop", ""), ("b", "#0x18"),
                   ("bl", "#0x100"), ("nop", ""), ("ret", "")]) == {}
    assert decide([("fcmp", "d0, #0.0"), ("b.eq", "#0x14"), ("bl", "#0x100"),
                   ("cmp", "x1, #0"), ("b.ne", "#0x8"), ("ret", "")]) == {}
    assert decide([("fcmp", "d0, #0.0"),
                   ("bl", "#0x100", "  ; -> stub _iso_stub_WriteBarrierWrappersStub"),
                   ("ret", "")]) == {8: "d0"}
    # Code the instruction cut left undecoded could hold a call, so a function cut short
    # gets none; and the question is arm64's.
    cut = [("fcmp", "d0, #0.0"), ("b.eq", "#0x40"), ("ret", "")]
    assert decide(cut) == {8: "d0"}
    blocks, entry = build_cfg(_rows_at(cut, 0), traps=(), cut_end=0x100)
    assert E._return_registers(blocks, entry, lambda: "d0") == {}
    blocks, entry = build_cfg(_rows_at([("ret", "")], 0), traps=())
    with E.use_target(E.ARM32):
        assert E._return_registers(blocks, entry, lambda: "d0") == {}

    # A function only the dispatch table calls has no callers to ask, and the other
    # implementations of its selector speak for it: `_Linear.transformInternal` is
    # `mov v1.16b, v0.16b; ret`. They are asked only where the callers say nothing.
    blocks, entry = build_cfg(_rows_at([("mov", "v1.16b, v0.16b"), ("ret", "")], 0),
                              traps=())
    asked = []

    def table(said):
        return lambda: asked.append(1) or said
    def ret_of(said, table):
        return E._return_registers(blocks, entry, lambda: said, None, table)
    assert ret_of(None, table("d0")) == {4: "d0"}
    assert ret_of(None, table("x0")) == {} and ret_of(None, table(None)) == {}
    asked.clear()
    assert ret_of("x0", table("d0")) == {} and not asked
    from jadart.dispatch import Selectors

    def lift_alone(by_table, selectors):
        def returns(pc):
            return None
        if by_table is not None:
            returns.by_table = by_table
        return [ln.strip() for ln in lift_function(
            [(0x40, "mov", "v1.16b, v0.16b", ""), (0x44, "ret", "", "")],
            selectors=selectors, returns=returns)]
    sels = Selectors({0x9c0: "transformInternal"})
    seen = []
    assert lift_alone(lambda pc, s: seen.append((pc, s)) or "d0", sels) == ["return d0;"]
    assert seen and seen[0] == (0x40, sels), seen
    assert lift_alone(lambda pc, s: "x0", sels) == ["return x0;"]
    assert lift_alone(None, sels) == ["return x0;"]
    assert lift_alone(lambda pc, s: "d0", None) == ["return x0;"]       # no table

    # Selectors.peers: the other functions of the family (`entries` key) the one asked
    # about is in, smallest first, at most `limit` of them. One of another family, at
    # the same offset or not, is not a peer.
    sels.entries = {(0x9c0, 1): (0x80, 0x00, 0x40), (0x9c8, 1): (0x00, 0x100),
                    (0x9c0, 2): (0x200,)}
    assert sels.peers(0x00) == [0x80, 0x40, 0x100]
    assert sels.peers(0x00, 1) == [0x80]
    assert sels.peers(0x80) == [0x00, 0x40] and sels.peers(0x200) == []
    assert sels.peers(0x300) == []
    sels.entries = {(0x9d0, 3): (0x00, 0x300)}          # new entries are read anew
    assert sels.peers(0x00) == [0x300]
    # build_selector_map says which functions at an offset share one selector. B (6)
    # and C (7), below the abstract A (5), both define `get:t`, at offset 10, and every
    # concrete class below A holds one of them there: they do. A concrete D (8) below A
    # whose row holds nothing there says they need not; nor do two classes that meet only
    # at the top, Object (1), the way `Animatable` and `ParametricCurve` do.
    from types import SimpleNamespace
    from jadart import dispatch as D

    def families(classes, fns, other=None, abstract=(5,)):
        # fns: (class ref, name) of each function, each with its own code, placed at
        # offset 10 in its class's row; or (class ref, name, offset).
        cid = {ref: c for ref, _n, c, _s in classes}
        fns = [f if len(f) == 3 else (*f, 10) for f in fns]
        fr2 = SimpleNamespace(
            classes=classes, types={101: 1, 102: 5, 103: 6},
            class_state={c: D._ABSTRACT for c in abstract}, patch_class={},
            names={60 + i: nm for i, (_o, nm, _k) in enumerate(fns)},
            functions=[(50 + i, 60 + i, o, 0) for i, (o, _n, _k) in enumerate(fns)],
            codes=[(0, 50 + i, i) for i in range(len(fns))])
        cells = [None] * 40
        for i, (o, _nm, k) in enumerate(fns):
            cells[cid[o] + k] = i + 1
        if other is not None:
            cells[other] = 40                   # a function no class here has
        got = D.build_selector_map(cells, fr2,
                                   SimpleNamespace(symbol_names={}, pcs=[], first_code=0))
        assert got.get(10) == fns[0][1], dict(got)
        return got.families
    below_a = [(1, 0, 1, 0), (2, 0, 5, 101), (3, 0, 6, 102), (4, 0, 7, 102)]
    b_c = [(3, "get:t"), (4, "get:t")]
    assert families(below_a, b_c) == {50: (10, "get:t"), 51: (10, "get:t")}
    assert families(below_a + [(5, 0, 8, 102)], b_c) == {}
    assert families(below_a + [(5, 0, 8, 102)], b_c, other=18) == {}      # D's cell
    at_top = [(1, 0, 1, 0), (2, 0, 5, 101), (3, 0, 6, 101), (4, 0, 7, 101)]
    assert families(at_top, b_c) == {}
    assert families(at_top, b_c, abstract=(1, 5)) == {}     # though every row holds one
    assert families([(1, 0, 1, 0), (2, 0, 5, 101), (3, 0, 6, 0), (4, 0, 7, 0)],
                    b_c) == {}                                 # they share none at all
    # The lowest class they all share, not the lowest two of them do: E (9), below B,
    # meets B at B and C at A, and D's empty row under A says no.
    deep = below_a + [(5, 0, 8, 102), (6, 0, 9, 103)]
    assert families(deep, [(6, "get:t"), (4, "get:t"), (3, "get:t")]) == {}
    # A crafted cycle of superclasses ends, whichever function is on it.
    loop, none = {6: 7, 7: 6}, [None] * 40
    for fs in ([("f", 6, 0, 50), ("f", 9, 1, 51)], [("f", 9, 0, 50), ("f", 6, 1, 51)]):
        assert not D._one_selector(fs, 10, none, loop, {}, set(), [100])
    # A private name keeps its library here: `_t` of two libraries is two selectors,
    # though the offset is named for one.
    assert families(below_a + [(5, 0, 8, 102)],
                    [(3, "_t@1"), (4, "_t@1"), (5, "_t@2")]) == {}
    # The walk is bounded over the whole table: up from B to the top (3 classes) and
    # from C to A (1), then down from A (3).
    old = D._MAX_FAMILY
    try:
        D._MAX_FAMILY = 7
        assert families(below_a, b_c) == {50: (10, "get:t"), 51: (10, "get:t")}
        D._MAX_FAMILY = 6
        assert families(below_a, b_c) == {}
        # ...over every offset: `get:u` at 20 would walk them again.
        b_c_u = b_c + [(3, "get:u", 20), (4, "get:u", 20)]
        D._MAX_FAMILY = 13
        assert len(families(below_a, b_c_u)) == 2
        D._MAX_FAMILY = 14
        assert len(families(below_a, b_c_u)) == 4
    finally:
        D._MAX_FAMILY = old

    # by_table on a made-up image: a peer whose caller reads d0 after the call, and one
    # with no callers whose own code hands back d0, say d0; a peer whose caller reads x0
    # disagrees, and then nothing is said. Nor is the table asked for a function whose
    # own callers read a register, even where they disagree.
    import types
    from jadart.disasm import CodeRange
    from jadart.expr import make_return_resolver

    def bl(pc, to):
        return 0x94000000 | (((to - pc) >> 2) & 0x3FFFFFF)
    RET, NOP, MOV_X1_X0 = 0xD65F03C0, 0xD503201F, 0xAA0003E1
    FMOV_D1_D0, FMOV_D0_D1, MOV_V1_V0 = 0x1E604001, 0x1E604020, 0x4EA01C01
    words = [NOP] * 0x90
    for at, w in ((0x00, RET), (0x04, NOP),                         # A, read as d0
                  (0x40, bl(0x40, 0x00)), (0x44, FMOV_D1_D0), (0x48, RET),
                  (0x80, FMOV_D0_D1), (0x84, RET),                  # B, its own d0
                  (0xC0, RET), (0xC4, NOP),                         # C, read as x0
                  (0x100, bl(0x100, 0xC0)), (0x104, MOV_X1_X0), (0x108, RET),
                  (0x140, MOV_V1_V0), (0x144, RET),                 # asked about
                  (0x180, MOV_V1_V0), (0x184, RET),                 # H, read as both
                  (0x1C0, bl(0x1C0, 0x180)), (0x1C4, FMOV_D1_D0), (0x1C8, RET),
                  (0x200, bl(0x200, 0x180)), (0x204, MOV_X1_X0), (0x208, RET)):
        words[at // 4] = w
    made_up = types.SimpleNamespace(
        arch=None, text=b"".join(w.to_bytes(4, "little") for w in words),
        all_ranges=[CodeRange(0x00, 8, -1), CodeRange(0x40, 12, -1),
                    CodeRange(0x80, 8, -1), CodeRange(0xC0, 8, -1),
                    CodeRange(0x100, 12, -1), CodeRange(0x140, 8, -1),
                    CodeRange(0x180, 8, -1), CodeRange(0x1C0, 12, -1),
                    CodeRange(0x200, 12, -1)])
    _needs_capstone()
    res = make_return_resolver(made_up)
    assert res(0x00) == "d0" and res(0xC0) == "x0" and res(0x140) is None
    assert res(0x180) is None
    sels = Selectors({0x9c0: "transformInternal"})
    sels.entries = {(0x9c0, 1): (0x140, 0x00, 0x80)}
    assert res.by_table(0x140, sels) == "d0"
    sels.entries = {(0x9c0, 1): (0x140, 0x80)}
    assert res.by_table(0x140, sels) == "d0"                       # its own code
    sels.entries = {(0x9c0, 1): (0x140, 0x00, 0x80, 0xC0)}
    assert res.by_table(0x140, sels) is None
    sels.entries = {(0x9c0, 1): (0x140, 0x80), (0x9c0, 2): (0xC0,)}
    assert res.by_table(0x140, sels) == "d0"                       # C is not a peer
    sels.entries = {(0x9c0, 1): (0x180, 0x80), (0x9c8, 1): (0x00, 0x80)}
    fresh = make_return_resolver(made_up)
    assert fresh.by_table(0x180, sels) is None                     # its callers spoke
    assert fresh.by_table(0x00, sels) is None
    # So have more than _MAX_SITES callers, read or not.
    old = E._MAX_SITES
    E._MAX_SITES = 1
    try:
        assert make_return_resolver(made_up).by_table(0x180, sels) is None
    finally:
        E._MAX_SITES = old
    # At most _MAX_SITES of them are asked, the smallest first.
    old = E._MAX_SITES
    E._MAX_SITES = 1
    try:
        sels.entries = {(0x9c0, 1): (0x80, 0xC0, 0x140)}
        assert res.by_table(0x140, sels) == "d0"
    finally:
        E._MAX_SITES = old
    sels.entries = {(0x9c0, 1): (0x140,)}
    assert res.by_table(0x140, sels) is None                       # nobody to ask
    assert res.by_table(0x140, {0x9c0: "transformInternal"}) is None   # a plain dict

    # And on the clean fixture, where `_Linear.transformInternal` printed `return x0;`.
    import jadart
    from jadart.disasm import load_instructions
    from jadart.dispatch import recover_selectors
    image, fr, hdr = load_instructions(CLEAN)
    at = image.anchor_va
    res = make_return_resolver(image)
    assert res(0x28a6c4 - at) is None                  # nothing calls it directly
    sels = recover_selectors(image, fr, hdr)
    assert len(sels.peers(0x28a6c4 - at)) == 5, sels.peers(0x28a6c4 - at)
    assert res.by_table(0x28a6c4 - at, sels) == "d0"
    assert sels.entries and {off for off, _c in sels.entries} <= set(sels)
    size = {cr.pc_offset: cr.size for cr in image.all_ranges}
    for pcs in sels.entries.values():
        assert [size[p] for p in pcs] == sorted(size[p] for p in pcs), pcs
    assert jadart.decompile(CLEAN, "0x28a6c4")[0]["body"] == ["return d0;"]
    body = [ln.strip() for ln in jadart.decompile(CLEAN, "0x177bdc")[0]["body"]]
    assert body[-1] == "return d0;", body                # Curve.transform


def test_returns_in_d0_ignores_a_ret_only_a_traps_fall_through_reaches():
    # #178. returns_in_d0 asks whether a function hands back d0 at every `ret`. A `ret`
    # that only the false fall-through past a trap reaches is dead (a CPU never resumes
    # after a brk), so it must not count. Here the live ret returns d0; a dead ret after a
    # brk, whose last write to a return register is a call, is classed x0. With the trap
    # honoured only the live d0 ret is reachable, so the function returns d0.
    from jadart.expr import (returns_in_d0, strip_boilerplate, build_cfg,
                             use_target, ARM64, _return_registers, TRAPS)

    rows = [("fmov", "d0, #1.0", ""),   # d0 written on the live path, never x0
            ("cbz",  "x1, #0x14", ""),  # x1 == 0 -> the live ret at 0x14
            ("bl",   "#0x100", ""),     # otherwise a call, the last write to x0
            ("brk",  "#0", ""),         # a trap: no fall-through on a CPU
            ("ret",  "", ""),           # dead ret, in only on the trap's false edge
            ("ret",  "", "")]           # the live ret
    ann = [(i * 4, mn, op, n) for i, (mn, op, n) in enumerate(rows)]
    assert returns_in_d0(ann) is True

    # The dead ret is what the trap's false edge adds: counting it (traps=()) sees x0 too,
    # so returns_in_d0 said False on main. Honouring the trap drops it.
    with use_target(ARM64):
        b_off, e_off = build_cfg(strip_boilerplate(ann), traps=())
        b_on, e_on = build_cfg(strip_boilerplate(ann), traps=TRAPS)
        off = set(_return_registers(b_off, e_off).values())
        on = set(_return_registers(b_on, e_on).values())
    assert off == {"d0", "x0"}          # the dead ret counted, as main did
    assert on == {"d0"}                 # only the live ret, the trap honoured


def test_a_return_is_not_proven_d0_by_a_block_the_cpu_cannot_reach():
    # #182. _return_facts proves a d0 return from a write that reaches a `ret`, but it ran
    # that proof over every block, forward-unreachable ones included, where at_ret is
    # reachable-only. A block a CPU never enters can `fmov d0; ret`, which proved d0 for a
    # live `ret` that actually hands back x0. The proof now uses reachable blocks only.
    from jadart.expr import (returns_in_d0, strip_boilerplate, build_cfg,
                             use_target, ARM64, _return_registers, TRAPS)

    def regs(rows):
        ann = [(i * 4, mn, op, n) for i, (mn, op, n) in enumerate(rows)]
        with use_target(ARM64):
            blocks, entry = build_cfg(strip_boilerplate(ann), traps=TRAPS)
            return returns_in_d0(ann), _return_registers(blocks, entry)

    # The live `ret` returns x0; a block that only `fmov d0; ret`s has no in-edge at all.
    d0_only, mapping = regs([("mov",  "x0, x2", ""),   # 0x0 entry: returns x0
                             ("ret",  "", ""),          # 0x4 the live ret
                             ("fmov", "d0, #1.0", ""),  # 0x8 unreachable, no in-edge
                             ("ret",  "", "")])         # 0xc
    assert d0_only is False      # main proved d0 off the dead block and said True
    assert mapping == {}         # #184: dead d0 is not the fn's own; defers, renders x0

    # The same leak as it arises after #64/#178: the unreachable block sits past a `brk`,
    # so only the trap's removed false edge ever reached it.
    d0_only, mapping = regs([("cbz",  "x1, #0x1c", ""),  # 0x00 live: x1==0 -> 0x1c
                             ("brk",  "#0", ""),          # 0x04 trap, no fall-through
                             ("bl",   "#0x100", ""),      # 0x08 (dead past the brk)
                             ("ret",  "", ""),            # 0x0c
                             ("fmov", "d0, #1.0", ""),    # 0x10 unreachable
                             ("ret",  "", ""),            # 0x14
                             ("nop",  "", ""),            # 0x18
                             ("mov",  "x0, x2", ""),      # 0x1c live: returns x0
                             ("ret",  "", "")])           # 0x20
    assert d0_only is False
    assert mapping == {}         # #184: same; defers to _argument_returns, renders x0


def test_return_facts_counts_only_reachable_d0_writes():
    # #184. _return_facts decides a function writes d0 at all, and proves a d0 return,
    # over the blocks the CPU can reach. A d0 write only a trap's false fall-through
    # reaches is not the function's own, so a function whose d0 writes are all unreachable
    # is left to _argument_returns, like one that never writes d0. Follow-up to #182, with
    # the same reachable basis #182 gave at_ret, only_ret and read.
    from jadart.expr import (returns_in_d0, strip_boilerplate, build_cfg,
                             use_target, ARM64, _return_registers, _return_facts, TRAPS)

    def facts_regs(rows, ev=None):
        a = [(i * 4, mn, op, n) for i, (mn, op, n) in enumerate(rows)]
        with use_target(ARM64):
            blocks, entry = build_cfg(strip_boilerplate(a), traps=TRAPS)
            got = (_return_registers(blocks, entry) if ev is None
                   else _return_registers(blocks, entry, lambda: ev))
            return _return_facts(blocks, entry) is None, returns_in_d0(a), got

    # A reachable pass-through `ret` whose only d0 write is in a dead block. Main counted
    # the dead write and labelled the ret d0 with no caller to ask. Now it has no d0 of
    # its own, so it defers: nothing without evidence, d0 once a caller says d0.
    passthrough = [("cbz",  "x1, #0x10", ""),  # 0x0 live -> 0x10
                   ("brk",  "#0", ""),         # 0x4 trap
                   ("fmov", "d0, #1.0", ""),   # 0x8 unreachable d0 write
                   ("ret",  "", ""),           # 0xc unreachable ret
                   ("ret",  "", "")]           # 0x10 live pass-through ret
    none0, d0_0, regs0 = facts_regs(passthrough)
    assert none0 and d0_0 is False and regs0 == {}   # defers, undecided with no caller
    assert facts_regs(passthrough, ev="d0")[2] == {16: "d0"}   # caller saying d0 decides

    # A reachable d0 write still counts, so the proof runs; an unreachable dead
    # d0-write-then-ret does not prove d0 for the live x0 ret (only_ret stays reachable,
    # #182). This exercises the proof that the pass-through above skips.
    mixed = [("fmov", "d0, #1.0", ""),  # 0x0 reachable d0 write
             ("str",  "d0, [x2]", ""),  # 0x4 stored
             ("cbz",  "x1, #0x18", ""),  # 0x8 -> 0x18
             ("brk",  "#0", ""),        # 0xc trap
             ("fmov", "d0, #2.0", ""),  # 0x10 unreachable d0 write
             ("ret",  "", ""),          # 0x14 unreachable ret
             ("mov",  "x0, x3", ""),    # 0x18 reachable x0 write
             ("ret",  "", "")]          # 0x1c reachable ret: returns x0
    none1, d0_1, regs1 = facts_regs(mixed)
    assert not none1                              # a reachable d0 write: the proof runs
    assert d0_1 is False and regs1 == {28: "x0"}  # the live ret is x0, not the dead d0


def test_a_call_to_a_function_with_register_and_stack_arguments_prints_both():
    # Past six arguments Dart passes the rest on the stack, the last at SP+0, and a callee
    # that reads both printed one part as the whole list: its registers, `hash6(t68, ...)`
    # over the seventh it pushed, or, framed, only what was pushed (#148).
    from jadart.expr import entry_arity, lift_function, StackArity

    def rows(body):
        return [(i * 4, mn, op, "") for i, (mn, op) in enumerate(body)]
    regs = [("add", "x0, x1, x2"), ("add", "x0, x0, x3"), ("add", "x0, x0, x5"),
            ("add", "x0, x0, x6"), ("add", "x0, x0, x7")]
    framed = entry_arity(rows([("stp", "x29, x30, [x15, #-0x10]!"), ("mov", "x29, x15")]
                              + regs + [("ldr", "x9, [x29, #0x18]"),
                                        ("ldr", "x8, [x29, #0x10]"),
                                        ("mov", "x15, x29"),
                                        ("ldp", "x29, x30, [x15], #0x10"), ("ret", "")]))
    assert isinstance(framed, StackArity) and (framed, framed.need) == (6, 2)
    frameless = entry_arity(rows(regs + [("ldr", "x8, [x15]"), ("ret", "")]))
    assert isinstance(frameless, StackArity) and (frameless, frameless.need) == (6, 1)
    assert not isinstance(entry_arity(rows(regs + [("ret", "")])), StackArity)

    def framed_with(body):
        return rows([("stp", "x29, x30, [x15, #-0x10]!"), ("mov", "x29, x15")] + regs
                    + body + [("mov", "x15, x29"), ("ldp", "x29, x30, [x15], #0x10"),
                              ("ret", "")])
    # A q load reads two slots; FP+8 is the return address, not an argument; and one
    # handed an arguments descriptor in x4 takes the stack convention, whatever it reads.
    wide = entry_arity(framed_with([("ldr", "q8, [x29, #0x10]")]))
    assert (wide, wide.need) == (6, 2)
    assert not isinstance(entry_arity(framed_with([("ldr", "x8, [x29, #8]")])),
                          StackArity)
    assert entry_arity(framed_with([("add", "x9, x4, x1"),
                                    ("ldr", "x8, [x29, #0x10]")])) is None
    # Read through an index computed from FP, how far up it reads is not known.
    via = entry_arity(rows(regs + [("add", "x9, x29, x0"), ("ldr", "x8, [x9, #0x18]"),
                                   ("ret", "")]))
    assert isinstance(via, StackArity) and via.need is None
    # Nor where the instruction cut stopped the function short: the part left out could
    # read higher.
    short = entry_arity(rows(regs + [("ldr", "x8, [x15]")]), cut=True)
    assert isinstance(short, StackArity) and short.need is None

    def call(arity, pushes):
        body = [("mov", f"{r}, #{n}") for n, r in enumerate(("x1", "x2", "x3", "x5",
                                                               "x6", "x7"), 1)]
        return [ln.strip() for ln in lift_function(
            rows(body + pushes + [("bl", "#0x100"), ("ret", "")]),
            arity=lambda pc: arity)]
    both = [("stp", "x10, x11, [x15]")]
    assert call(StackArity(6, 2), both)[0] == (
        "return sub_0x100(1, 2, 3, 4, 5, 6, x11, x10);")
    # The first stack arguments sit highest, so one the callee does not read is past
    # `need`, and all that was pushed is printed.
    assert call(StackArity(6, 2), both + [("str", "x12, [x15, #0x10]")])[0] == (
        "return sub_0x100(1, 2, 3, 4, 5, 6, x12, x11, x10);")
    # Fewer pushed than it reads, nothing pushed, or fewer registers than six, is not the
    # list, and nor is one beside a double handed over in a V register
    # (kFpuRegistersForArgs).
    assert call(StackArity(6, 2), [("str", "x10, [x15]")])[0] == "return sub_0x100(...);"
    assert call(StackArity(5, 2), both)[0] == "return sub_0x100(...);"
    assert call(StackArity(6, 2, True), both)[0] == "return sub_0x100(...);"
    assert call(StackArity(6, 0), [])[0] == "return sub_0x100(...);"
    assert call(via, both)[0] == "return sub_0x100(...);"
    assert call(short, both)[0] == "return sub_0x100(...);"
    # A callee whose arity is not asked for takes what was pushed, as before.
    assert [ln.strip() for ln in lift_function(rows(both + [("bl", "#0x100"),
                                                           ("ret", "")]))][0] == (
        "return sub_0x100(x11, x10);")
    # One that reads only registers does not read what was pushed, so where they are not
    # known nor is its list: 3.4.4's `contains` printed `contains(0)`.
    lone = rows([("mov", "x1, #5"), ("str", "xzr, [x15]"), ("bl", "#0x100"), ("ret", "")])
    assert [ln.strip() for ln in lift_function(lone, arity=lambda pc: 2)][0] == (
        "return sub_0x100(...);")
    handed = entry_arity(rows(regs + [("fadd", "d0, d1, d2"), ("ldr", "x8, [x15]"),
                                      ("ret", "")]))
    zeroed = entry_arity(rows(regs + [("eor", "v1.16b, v1.16b, v1.16b"),
                                      ("fmov", "d0, d1"), ("ldr", "x8, [x15]"),
                                      ("ret", "")]))
    assert handed.fpu and not zeroed.fpu and not frameless.fpu
    assert entry_arity(rows(regs + [("cbz", "x1, #0x20"), ("fadd", "d2, d0, d0"),
                                    ("ldr", "x8, [x15]"), ("ret", "")])).fpu
    # Each of V0 to V5 is an argument register, and V6 is not.
    for r in ("d0", "d1", "d2", "d3", "d4", "d5", "d6"):
        got = entry_arity(rows(regs + [("fmov", f"d7, {r}"), ("ldr", "x8, [x15]"),
                                       ("ret", "")]))
        assert got.fpu == (r != "d6"), r
    # A `ret` no call and no write to x0 can come before hands back d0, the argument
    # (#127's `Curve.transform`); one after a write to x0 returns in x0.
    keep = [("add", "x8, x1, x2"), ("add", "x8, x8, x3"), ("add", "x8, x8, x5"),
            ("add", "x8, x8, x6"), ("add", "x8, x8, x7"), ("ldr", "x9, [x15]")]
    assert entry_arity(rows(keep + [("ret", "")])).fpu
    assert not entry_arity(rows(keep + [("mov", "x0, x9"), ("ret", "")])).fpu
    # A pair reads two slots, and a double the function writes before it reads it, on
    # every path, was not handed to it. A framed function's own outgoing slots are not
    # its arguments.
    pair = entry_arity(rows(regs + [("ldp", "x8, x9, [x15]"), ("ret", "")]))
    assert (pair, pair.need) == (6, 2)
    own = entry_arity(rows(regs + [("fmov", "d0, #1.0"), ("cbz", "x1, #0x24"),
                                   ("fadd", "d2, d0, d0"), ("ldr", "x8, [x15]"),
                                   ("ret", "")]))
    assert isinstance(own, StackArity) and not own.fpu
    assert not isinstance(entry_arity(rows(
        [("stp", "x29, x30, [x15, #-0x10]!"), ("mov", "x29, x15")] + regs
        + [("str", "x8, [x15]"), ("ldr", "x9, [x15]"), ("mov", "x15, x29"),
           ("ldp", "x29, x30, [x15], #0x10"), ("ret", "")])), StackArity)
    import pickle
    back = pickle.loads(pickle.dumps(StackArity(6, 2, True)))
    assert (back, back.need, back.fpu) == (6, 2, True)
    # ...and a call printed `...` reads no register of its own (Lifter._call_reads).
    from jadart import expr as E
    for k in (StackArity(5, 1), StackArity(6, 1, True), StackArity(6, None)):
        lifter = E.Lifter({}, arity=lambda pc: k)
        assert lifter._call_reads([(0, "bl", "#0x100", "")]) == {}
    assert E.Lifter({}, arity=lambda pc: StackArity(6, 1))._call_reads(
        [(0, "bl", "#0x100", "")]) == {0: E._reg_mask(E.ARG_REGS)}
    # An address computed from FP and then overwritten reads no argument through it: a
    # `sync*` method that takes only `this` would print `_childrenInPaintOrder(...)`.
    assert not isinstance(entry_arity(rows(
        [("stp", "x29, x30, [x15, #-0x10]!"), ("mov", "x29, x15"),
         ("ldur", "x2, [x1, #7]"), ("add", "x0, x29, w1, sxtw #2"),
         ("ldur", "x0, [x0, #-8]"),
         ("ldur", "w3, [x0, #0x17]"), ("mov", "x15, x29"),
         ("ldp", "x29, x30, [x15], #0x10"), ("ret", "")])), StackArity)
    # The arity resolver tells entry_arity where the cut stopped a range short. It
    # decodes, so it needs capstone, and the rest of this test does not.
    if not _capstone_available():
        return
    import struct
    from jadart import versions
    from jadart.disasm import InstrImage, CodeRange, MAX_INSNS
    from jadart.expr import make_arity_resolver
    # add x0, x1, x2; add x0, x0, x3 / x5 / x6 / x7; ldr x8, [x15]; then nops, ret
    head = [0x8B020020, 0x8B030000, 0x8B050000, 0x8B060000, 0x8B070000, 0xF94001E8]
    for pad, need in ((0, 1), (MAX_INSNS, None)):
        words = head + [0xD503201F] * pad + [0xD65F03C0]
        cr = CodeRange(pc_offset=0, size=4 * len(words), owner_ref=-1)
        image = InstrImage(text=b"".join(struct.pack("<I", w) for w in words), pcs=[0],
                           first_code=0, code_ranges={}, all_ranges=[cr],
                           arch=versions.Arch("arm64", 8, True))
        got = make_arity_resolver(image)(0)
        assert isinstance(got, StackArity) and (got, got.need) == (6, need), pad


def test_a_slot_the_loop_does_not_store_to_survives_it():
    # A loop's exit dropped every frame slot where any block of `_loop_nodes` stored to
    # the frame, and those take in the blocks before the loop (#129). So a slot saved at
    # entry read back after the loop as the register it was reloaded into:
    # `_contentWidthFor` compares its first double argument and printed `d1 > t2`, which
    # reads as the second (#157). The exit now drops only the slots the loop's own blocks
    # may have stored to.
    from jadart.expr import lift_function

    def lift(rows):
        # In a frame, as `_contentWidthFor` is, with SP below every slot: where SP - FP
        # is not known, a store through SP may be to any slot (#162). The frame's three
        # instructions move every branch target in the function on by 12 bytes.
        def moved(mn, op):
            if mn == "b" or mn.startswith(("b.", "cb", "tb")):
                rest, _, at = op.rpartition("#")
                return mn, f"{rest}#{int(at, 0) + 12:#x}"
            return mn, op
        frame = [("stp", "x29, x30, [x15, #-0x10]!"), ("mov", "x29, x15"),
                 ("sub", "x15, x15, #0x50")]
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "")
             for i, (mn, op) in enumerate(frame + [moved(*r) for r in rows])])]

    # `_contentWidthFor`'s shape: the doubles saved, then a stack check whose slow path,
    # laid out after a throw, jumps back past the check. The only back edge comes in past
    # the `brk`, so honouring the trap (#64) leaves no loop, and the slots read as stored.
    check = [("ldr", "x16, [x26, #0x48]"), ("cmp", "x15, x16"), ("b.ls", "#0x44")]
    head = [("stur", "d0, [x29, #-0x18]"), ("stur", "d1, [x29, #-0x20]")]
    body = [("ldur", "x0, [x1, #7]"), ("stur", "x0, [x29, #-0x10]"),
            ("cbz", "x0, #0x38"), ("ldur", "d1, [x29, #-0x18]"),
            ("stur", "d1, [x2, #15]"), ("ldur", "x3, [x29, #-0x10]"),
            ("stur", "x3, [x2, #23]"), ("mov", "x0, #0"), ("ret", "")]
    throw = [("str", "x16, [x15]"), ("bl", "#0x300"), ("brk", "#0")]
    slow = [("bl", "#0x200"), ("b", "#0x14")]
    out = lift(head + check + body + throw + slow)
    assert "x2.field_0x10 = d0;" in out, out
    # With no loop the slot is not forgotten: the reload reads the value stored, named.
    assert "x2.field_0x18 = x1.field_0x8;" in out, out
    # The throw's call writes x1, which the loop carries for it; the slot saved from x1
    # holds it all the same.
    out = lift([head[0], ("stur", "x1, [x29, #-8]")] + check + body[:5]
               + [("ldur", "x3, [x29, #-8]")] + body[6:] + throw + slow)
    assert "x2.field_0x10 = d0;" in out and "x2.field_0x18 = x1;" in out, out
    # The store in the throw's block is on the path that throws, which the trap ends: it
    # never reaches the read on the way out, so the slot still reads as the entry double.
    out = lift(head + check + body + [("stur", "d16, [x29, #-0x18]")] + throw[1:] + slow)
    assert "x2.field_0x10 = d0;" in out, out

    # A loop of its own, counting down in x9: the slot at -0x20 holds d0 from before it.
    # It is read back from the register file it was stored from (#165).
    def counted(*inside, before=(("stur", "d0, [x29, #-0x20]"),)):
        r = "d6" if any(op[:1] == "d" for _m, op in before if "#-0x20" in op) else "x6"
        rows = list(before) + [("mov", "x9, #3")] + list(inside)
        rows += [("sub", "x9, x9, #1"), ("cbnz", "x9, #%#x" % (4 * (len(before) + 1))),
                 ("ldur", f"{r}, [x29, #-0x20]"), ("stur", f"{r}, [x2, #15]"),
                 ("ret", "")]
        return lift(rows)

    def kept(*inside, **kw):
        out = counted(*inside, **kw)
        return "x2.field_0x10 = d0;" in out
    assert kept(("add", "x5, x5, #1"))                     # it stores nothing
    assert kept(("ldur", "x5, [x29, #-0x20]"))             # it reads it
    assert kept(("stur", "x5, [x29, #-0x18]"))             # the slot above
    assert kept(("stur", "x5, [x29, #-0x28]"))             # the slot below
    assert kept(("stur", "w5, [x29, #-0x24]"))             # 4 bytes, ending below it
    assert kept(("stp", "q5, q6, [x29, #-0x40]"))          # 32 bytes up to it
    assert kept(("str", "x5, [x15]"))                      # the outgoing area
    assert not kept(("stur", "d5, [x29, #-0x20]"))         # the slot itself
    assert not kept(("stur", "w5, [x29, #-0x1c]"))         # its top half
    assert not kept(("stur", "w5, [x29, #-0x22]"))         # straddling its bottom
    assert not kept(("stp", "d5, d6, [x29, #-0x28]"))      # a pair over it
    assert not kept(("stp", "q5, q6, [x29, #-0x30]"))      # 32 bytes over it
    assert not kept(("str", "x5, [x29, x7]"))              # a place not known
    assert not kept(("str", "x5, [x9], x10"))              # an update not read
    assert not kept(("str", "x5, [x29, #-8]!"))            # the frame moves
    assert not kept(("add", "x29, x29, #0x10"))            # and so
    assert not kept(("add", "x9, x29, #0x10"), ("str", "x5, [x9]"))   # its address out
    # The blocks with a trap or a throw can be asked for before any trip is.
    from jadart.cfg import build_cfg
    from jadart.expr import Lifter
    rows = [("stur", "d0, [x29, #-0x20]"), ("mov", "x9, #3"), ("sub", "x9, x9, #1"),
            ("cbnz", "x9, #0x8"), ("ret", "")]
    blocks, entry = build_cfg([(i * 4, m, o, "") for i, (m, o) in enumerate(rows)],
                              traps=())
    lifter = Lifter(blocks, entry=entry)
    assert lifter._ended_blocks() == set() and lifter._trip_nodes(8) == {8}
    # A slot a q register filled is 16 bytes, and a store over its top half drops it.
    def wide(store):
        return lift([("stur", "q0, [x29, #-0x20]"), ("mov", "x9, #3"), store,
                     ("sub", "x9, x9, #1"), ("cbnz", "x9, #0x8"),
                     ("ldur", "q1, [x29, #-0x20]"), ("stur", "q1, [x2, #15]"),
                     ("ret", "")])
    # The store moves sixteen bytes and says so (#209). Where the loop dropped the slot
    # the reload now names the read as well, rather than keeping q1, which the printed
    # body never assigns; where the slot survives, q0 IS what it holds, the register the
    # function came in with, and that reads right.
    assert ["var t1 = (FP - 32).field16_0x1;", "x2.field16_0x10 = t1;"] == [
        l for l in wide(("stur", "x5, [x29, #-0x18]")) if "field16" in l]
    assert "x2.field16_0x10 = q0;" in wide(("stur", "x5, [x29, #-0x10]"))
    assert "x2.field16_0x10 = q0;" in wide(("stur", "x5, [x29, #-0x28]"))
    # The outgoing area goes whatever the loop does: a call in it takes what was pushed,
    # and the call after it printed the 7 for its arguments.
    out = lift([("mov", "x5, #7"), ("str", "x5, [x15]"), ("mov", "x9, #3"),
                ("bl", "#0x100"), ("sub", "x9, x9, #1"), ("cbnz", "x9, #0xc"),
                ("bl", "#0x200"), ("ret", "")])
    assert out[-1] == "return sub_0x200(...);", out
    for inside in (("add", "x8, x8, #1"), ("str", "x6, [x15, #8]")):
        out = lift([("str", "x5, [x15, #8]"), ("mov", "x9, #3"), inside,
                    ("sub", "x9, x9, #1"), ("cbnz", "x9, #0x8"), ("ldr", "x7, [x15, #8]"),
                    ("stur", "x7, [x2, #15]"), ("ret", "")])
        # The slot is gone, so the reload says the read rather than keeping x7, which
        # read as the value the function came in with (#198).
        # Anchored to the frame the function was entered with, not spelled off the live
        # SP: this shape's frame is 0x50, so the read 8 above SP is FP - 72, and it stays
        # that whatever the loop did to SP in between (#207).
        m = [re.fullmatch(r"var (t\d+) = \(FP - 72\)\.field_0x1;", l) for l in out]
        named = next((g.group(1) for g in m if g), None)
        assert named and f"x2.field_0x10 = {named};" in out, out
    # A text that reads memory goes where the loop stores to memory or calls, and one
    # that names a register where the loop writes it.
    field = (("ldur", "x4, [x1, #7]"), ("stur", "x4, [x29, #-0x20]"))
    out = counted(("add", "x5, x5, #1"), before=field)
    assert "x2.field_0x10 = x1.field_0x8;" in out, out
    out = counted(("stur", "x5, [x1, #7]"), before=field)
    # The store took the slot, so the reload says the read rather than keeping x6, which
    # read as the value the function came in with (#198).
    m = re.fullmatch(r"var (t\d+) = \(FP - 32\)\.field_0x1;", out[-3])
    assert m and out[-2] == f"x2.field_0x10 = {m.group(1)};", out
    # Across a call it has a name from before the loop (_slot_crossings), which holds.
    out = counted(("bl", "#0x100"), before=field)
    assert out[0] == "var t0 = x1.field_0x8;" and "x2.field_0x10 = t0;" in out, out
    # Nor where the register is written between the store and the loop: the text is
    # still spelled with it after (#140), as `_lShiftDigits`'s `x2 + x3 ~/ 32 + 1` was
    # beside the x3 it had loaded since.
    out = counted(("add", "x8, x8, #1"), before=(
        ("add", "x4, x2, #1"), ("stur", "x4, [x29, #-0x20]"), ("ldur", "x2, [x2, #7]")))
    assert _reads_frame(out, "x2.field_0x10"), out
    reg = (("stur", "x5, [x29, #-0x20]"),)
    assert "x2.field_0x10 = x5;" in counted(("add", "x7, x7, #1"), before=reg)
    out = counted(("add", "x5, x5, #1"), before=reg)
    # The loop reassigns x5, so the slot goes and the reload spells the x5 it held
    # (#196): the loop carries its own name, so nothing printed assigns x5. The #140 case
    # above keeps its decline, because a record does not survive a loop boundary and the
    # region kill that replaces it cannot cover a text naming a register the region
    # reloaded (#199).
    assert "x2.field_0x10 = x5;" in out, out

    # A loop's own stack check: its slow path, laid out after the `ret`, is a block
    # nothing reaches that jumps into the body, which could be a handler the graph has
    # no edge into. It is the check's, so its stub hands every register back and
    # touches no field; another block in its place counts as writing what its call
    # does, d0 among them, and as a call.
    def checked(*slow, before=(("stur", "d0, [x29, #-0x20]"),), check=True):
        n = len(before)
        r = "d6" if any(op[:1] == "d" for _m, op in before if "#-0x20" in op) else "x6"
        test = [("ldr", "x16, [x26, #0x48]"), ("cmp", "x15, x16"),
                ("b.ls", "#%#x" % (4 * (n + 9)))] if check else [("nop", "")] * 3
        return lift(list(before) + [("mov", "x9, #3")] + test + [
            ("sub", "x9, x9, #1"),
            ("cbnz", "x9, #%#x" % (4 * (n + 1))), ("ldur", f"{r}, [x29, #-0x20]"),
            ("stur", f"{r}, [x2, #15]"), ("ret", "")]
            + [(mn, "#%#x" % (4 * (n + 4)) if mn == "b" else op) for mn, op in slow])
    quiet, busy = [("bl", "#0x200"), ("b", "")], [("bl", "#0x200"), ("mov", "x9, #1"),
                                                   ("b", "")]
    assert "x2.field_0x10 = d0;" in checked(*quiet)
    assert _reads_frame(checked(*busy), "x2.field_0x10")
    assert _reads_frame(checked(*quiet, check=False), "x2.field_0x10")
    # Nor does one that jumps to the head itself, whether it calls or stores.
    for odd in ([("bl", "#0x200"), ("mov", "x9, #1")], [("stur", "d9, [x29, #-0x20]")]):
        out = lift([("stur", "d0, [x29, #-0x20]"), ("mov", "x9, #3"),
                    ("sub", "x9, x9, #1"), ("cbnz", "x9, #0x8"),
                    ("ldur", "d6, [x29, #-0x20]"), ("stur", "d6, [x2, #15]"), ("ret", "")]
                   + odd + [("b", "#0x8")])
        assert _reads_frame(out, "x2.field_0x10"), out
    field = (("ldur", "w4, [x20, #0xb]"), ("stur", "x4, [x29, #-0x20]"))
    assert "x2.field_0x10 = x20.field_0xc;" in checked(*quiet, before=field)
    assert _reads_frame(checked(*busy, before=field), "x2.field_0x10")

    # And on the clean fixture.
    _needs_capstone()
    import jadart
    body = [ln.strip() for ln in jadart.decompile(CLEAN, "0x161360")[0]["body"]]
    assert "if (d0 > t2) {" in body and "t5 = d0;" in body, body


def test_a_trap_prunes_the_arm_that_calls_a_throw_and_traps():
    # Honouring a trap in tier 3 (#64): an arm that sets a value, calls a throw stub and
    # then traps never hands that value to the code after the `if`. With the false edge
    # past the `brk` (the old graph), this lifted to `var t1; ...; t1 = t0; return t1;`,
    # merging a value the machine never carries out. Tier 2 took the rule in #57; tier 3
    # takes it now, so the live arm's constant is the whole result.
    from jadart.expr import lift_function
    rows = [("cmp", "x1, #0"), ("b.ne", "#0x10"), ("mov", "x0, #7"), ("b", "#0x1c"),
            ("mov", "x0, #5"), ("bl", "#0x100"), ("brk", "#0"), ("ret", "")]
    body = "\n".join(lift_function([(i * 4, m, o, "")
                                    for i, (m, o) in enumerate(rows)]))
    assert "return 7;" in body, body
    # No phi over the trapping arm's value: it is not declared and not merged in.
    assert "var t" not in body and "return t" not in body, body


def test_a_value_a_join_lost_is_not_read_back_from_a_slot_as_the_register():
    # A register the arms of an `if` disagree about is dropped to its bare name, which
    # reads like the entry value and like a raw line\'s result. A frame slot that stored
    # it kept the text `x6` while a later join left `x6` meaning something else, and a
    # reload read the wrong one: two field stores both printed `x6` though the machine
    # holds different values (#140). The slot is now tied to the lost register and
    # dropped when it is reassigned, so the reload reads the register afresh.
    from jadart.expr import lift_function

    def lift(rows):
        rows = list(rows) + [("ret", "")]
        at, n = {}, 0
        for r in rows:
            if isinstance(r, str):
                at[r] = n * 4
            else:
                n += 1
        ann = []
        for r in (r for r in rows if not isinstance(r, str)):
            op = r[1]
            for nm, a in at.items():
                op = op.replace("@" + nm, "#%#x" % a)
            ann.append((len(ann) * 4, r[0], op, ""))
        return [ln.strip() for ln in lift_function(ann)]

    out = lift([("cmp", "x5, #0"), ("csel", "x6, x1, x2, eq"), ("stur", "x6, [x20, #7]"),
                ("cbz", "x5, @L1"), ("ldr", "x6, [x20, #0x17]"), ("b", "@J1"),
                "L1", ("ldr", "x6, [x20, #0x1f]"),
                "J1", ("stur", "x6, [x29, #-8]"),
                ("cbz", "x5, @L2"), ("ldr", "x6, [x20, #0x27]"), ("b", "@J2"),
                "L2", ("ldr", "x6, [x20, #0x2f]"),
                "J2", ("stur", "x6, [x20, #0x37]"),
                ("ldur", "x0, [x29, #-8]"), ("stur", "x0, [x20, #0x3f]")])
    # the slot read (field_0x40) must not share the bare `x6` the direct store has: the
    # two are different values. The reload reads its own register.
    assert "x20.field_0x38 = x6;" in out, out
    assert "x20.field_0x40 = x6;" not in out, out
    assert _reads_frame(out, "x20.field_0x40"), out
    # a slot holding a lost register whose register is never reassigned still reads it:
    # here x6 is lost at the join, spilled, and read straight back.
    out = lift([("cbz", "x5, @A"), ("ldr", "x6, [x1, #7]"), ("b", "@B"),
                "A", ("ldr", "x6, [x1, #0xf]"),
                "B", ("stur", "x6, [x29, #-8]"), ("ldur", "x3, [x29, #-8]"),
                ("stur", "x3, [x20, #7]")])
    assert "x20.field_0x8 = x6;" in out, out      # still named, x6 not reassigned

    # A loop that carries a lost register renames it; the slot that spilled it is dropped
    # there too, so a reload in the body reads the register, not the dangling name.
    out = lift([("cbz", "x5, @L1"), ("ldr", "x6, [x20, #0x17]"), ("b", "@J1"),
                "L1", ("ldr", "x6, [x20, #0x1f]"), "J1", ("stur", "x6, [x29, #-8]"),
                "LH", ("ldur", "x9, [x29, #-8]"), ("stur", "x9, [x20, #0x40]"),
                ("add", "x6, x6, #1"), ("subs", "x3, x3, #1"), ("cbnz", "x3, @LH"),
                ("stur", "x6, [x20, #0x48]")])
    # Still not x6, the value the join lost. Not x9 either now: the reload says the read
    # it is rather than keeping the load's own register (#198).
    assert _reads_frame(out, "x20.field_0x41"), out
    assert "x20.field_0x41 = x6;" not in out, out

    # A lost value tied in only the else arm of a join: the slot is dropped, not left
    # untied, so a later reassignment cannot leave it reading stale.
    out = lift([("cbz", "x5, @E"), ("ldur", "x6, [x1, #7]"), ("b", "@M"),
                "E", ("cbz", "x4, @F"), ("ldur", "x6, [x1, #0xf]"), ("b", "@G"),
                "F", ("ldur", "x6, [x1, #0x17]"), "G", ("stur", "x6, [x29, #-8]"),
                "M", ("stur", "x6, [x29, #-8]"), ("ldur", "x6, [x1, #0x1f]"),
                ("ldur", "x9, [x29, #-8]"), ("stur", "x9, [x20, #0x27]")])
    assert _reads_frame(out, "x20.field_0x28"), out
    assert "x20.field_0x28 = x6;" not in out, out


def test_a_register_expression_is_named_before_a_load_reassigns_it():
    # `add x3, x2, #0xad` leaves x3 holding the expression `x2 + 173`. `ldur x2, ...` then
    # reassigns x2, so printing x3 at the later store read the reloaded x2, not the value
    # x3 held (#187): `x20.field_0x8 = x2 + 173;` reads the reassigned x2. It is the
    # register-level twin of the frame-slot staleness #173 fixed; a load now writes
    # such a live expression out first, so the store reads what x3 held. Only a load (an
    # unrelated clobber), only a compound expression (a bare-register copy stays bare for
    # the argument / phi / read-afresh rules), only the register map (a slot is #173's).
    body = _lift_asm([("add", "x3, x2, #0xad"), ("ldur", "x2, [x29, #-8]"),
                      ("stur", "x3, [x20, #7]"), ("ret", "")])
    m = re.search(r"var (t\d+) = x2 \+ 173;", body)
    assert m, f"the expression was not named before the reload:\n{body}"
    assert f"x20.field_0x8 = {m.group(1)};" in body, body    # the store reads the name
    assert "field_0x8 = x2 + 173;" not in body, body          # not the reloaded x2


def test_a_register_expression_is_named_before_a_move_or_compute_reassigns_it():
    # The load case above generalises (#187): a MOVE or a COMPUTED RESULT reassigns a
    # register the same way a load does, so an expression still naming it goes stale.
    # `add x3, x2, #0xad` leaves x3 as `x2 + 173`; whether x2 is then overwritten by a
    # computed result, a move or a shift, the later store must read what x3 held, not the
    # reassigned x2. On the pre-generalisation renderer each of these printed the stale
    # `x2 + 173`.
    for reassign in [("add", "x2, x4, #1"), ("mov", "x2, x4"), ("lsl", "x2, x4, #3")]:
        body = _lift_asm([("add", "x3, x2, #0xad"), reassign,
                          ("stur", "x3, [x20, #7]"), ("ret", "")])
        m = re.search(r"var (t\d+) = x2 \+ 173;", body)
        assert m, f"{reassign} did not name the expression first:\n{body}"
        assert f"x20.field_0x8 = {m.group(1)};" in body, body   # the store reads the name
        assert "field_0x8 = x2 + 173;" not in body, body        # not the reassigned x2

    # A write whose own result still names the register it sets is left alone: a source
    # holds a value naming it, so the new value self-references the soon-stale register.
    # `add x7, x4, #0xd6; sub x4, x7, x4` prints `x4 + 214 - x4`, right only because that
    # stale x4 cancels the other; pinning x7 into a temp would leave `t0 - x4`, reading
    # reassigned x4 on one side only and printing the wrong value. The guard keeps the
    # cancelling spelling, matching the pre-generalisation renderer exactly.
    body = _lift_asm([("add", "x7, x4, #0xd6"), ("sub", "x4, x7, x4"),
                      ("stur", "x4, [x20, #7]"), ("ret", "")])
    assert "x20.field_0x8 = x4 + 214 - x4;" in body, body
    assert re.search(r"var t\d+ = x4 \+ 214;", body) is None, body


def test_pbfuzz_says_what_it_assembles():
    """Every encoder the printed-body oracle uses, decoded back by capstone.

    The same contract irfuzz's own `verify_encodings` has, and for the same reason: a
    harness that fuzzes a different instruction than the one it names reports a clean
    pass and proves nothing."""
    if not _capstone_available():
        _skip("  SKIP test_pbfuzz_says_what_it_assembles")
    sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "tools"))
    import pbfuzz
    bad = pbfuzz.verify_encodings()
    assert not bad, "\n".join(f"wanted {w!r}, capstone read {g!r}" for w, g in bad)


def test_a_self_referential_write_is_right_under_printed_body_semantics():
    """The open half of #187, measured against a real CPU, and the answer is that there
    is nothing to fix.

    A register in the output starts at the value the function came in with and means
    whatever the printed body last assigned it. `expr._verbatim` states it ("a register
    the lifter holds as an expression was never assigned in the printed body"), the
    `_bump` invariant test states the consequence ("from that line on, the token `x3` in
    the output means what the statement put there"), and `tools/irfuzz.py` implements it.
    A self-referential write prints no assignment, so `add x4, x4, #1` leaves `x4` still
    meaning the argument and `x4 + 1` is exactly what the machine stored.

    So the pin #187 would have generalised here is not a missing guard, and the two
    spellings below are not right by luck. Only a PRINTED register write makes a spelling
    stale, which is `_pin`'s job: the last case puts that bug back and the oracle catches
    it, so a pass here is not the harness scoring nothing.
    """
    if not _unicorn_available() or not _capstone_available():
        _skip("  SKIP test_a_self_referential_write_is_right_under_printed_body_semantics")
    sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "tools"))
    import pbfuzz
    from jadart import expr
    P = pbfuzz

    def ldur(t, n, i):
        return (f"ldur x{t}, [x{n}, #{i:#x}]", P.enc_ldur(t, n, i))

    def stur(t, n, i):
        return (f"stur x{t}, [x{n}, #{i:#x}]", P.enc_stur(t, n, i))

    def alu(mn, d, n, m):
        tmpl, enc = next(x for x in P.ALU if x[0].startswith(mn + " "))
        return (tmpl.format(d=f"x{d}", n=f"x{n}", m=f"x{m}"), enc(d, n, m))

    def addi(d, n, i):
        return (f"add x{d}, x{n}, #{i:#x}", P.IMM[0][1](d, n, i))

    def ldr_post(t, n, i):
        return (f"ldr x{t}, [x{n}], #{i:#x}", P.enc_ldr_post(t, n, i))

    ret = ("ret", P.RET_WORD)
    oracle = P.Oracle()
    # The value registers are preloaded, so each holds a field expression and a bare
    # register anywhere is unambiguously the lifter declining (FINDINGS.md: a lost value
    # "rests on the bare register meaning nothing to the reader"). That is what makes a
    # self-referential spelling scoreable rather than skipped.
    pre = [ldur(d, P.SEED_BASE, 8 * k) for k, d in enumerate((3, 4, 5, 7))]
    cases = {
        # the simplest self-reference there is
        "add x4, x4, #1": pre + [addi(4, 4, 1), stur(4, P.OBS, 7), ret],
        # the spelling the #187 guard keeps, whose two references cancel
        "sub x4, x7, x4 after add x7, x4, #0xd6": pre + [
            addi(7, 4, 0xD6), alu("sub", 4, 7, 4), stur(4, P.OBS, 7), ret],
        # a self-referential write whose partner is a term that reads zero
        "sub x4, x4, x3 after add x4, x3, x4": pre + [
            alu("add", 4, 3, 4), alu("sub", 3, 5, 5), alu("sub", 4, 4, 3),
            stur(4, P.OBS, 7), ret],
    }
    for what, rows in cases.items():
        clean, wrong, _dec, _undec, lines = oracle.score(rows, trials=40, seed=7,
                                                         bind_values=False)
        assert wrong == 0 and clean >= 30, (
            f"{what} disagreed with the CPU in {wrong} of {clean + wrong} "
            "environments:\n  " + "\n  ".join(l.strip() for l in lines))

    # Put the bug back. A value spelled off x9 is stale once `_bump` PRINTS `x9 = x9 + 8`,
    # and that is the one case in this family that is a real defect. With both guards
    # disabled the oracle must call it wrong, or a pass above proves nothing.
    stale = [addi(3, 9, 0xAD), ldr_post(4, 9, 8), stur(3, P.OBS, 7), ret]
    clean, wrong, _d, _u, lines = oracle.score(stale, trials=40, seed=7,
                                               bind_values=True)
    assert wrong == 0 and clean >= 30, "\n  ".join(l.strip() for l in lines)
    real_pin, real_name = expr.Lifter._pin, expr.Lifter._name_stale_reg
    expr.Lifter._pin = lambda self, st, name, live=None: []
    expr.Lifter._name_stale_reg = lambda self, st, name, live, guard_feed=False: []
    try:
        clean, wrong, _d, _u, lines = oracle.score(stale, trials=40, seed=7,
                                                   bind_values=True)
    finally:
        expr.Lifter._pin, expr.Lifter._name_stale_reg = real_pin, real_name
    assert wrong >= 30 and clean == 0, (
        "with both pins disabled the oracle still agreed with the CPU, so it is not "
        "measuring the staleness it claims to:\n  "
        + "\n  ".join(l.strip() for l in lines))


def test_a_declined_frame_read_is_not_scored_as_a_disagreement():
    """A frame reload the lifter DECLINES to spell is not a defect, and the sweep used to
    report it as one (#238).

    `tools/pbfuzz.py --cases 3000` reported nine disagreements and every one of them was
    this shape. A spill to a frame slot is tracked in the slot map and printed as
    nothing, so the CPU's slot holds the register it spilled while the printed body's
    still holds the bytes the run started with, and the read #198 prints where the reload
    declines, `var t1 = (FP - 24).field_0x1;`, is the one line that reads one of each.
    The text is right; the harness was comparing two different images and calling the gap
    a wrong answer, which is the one thing an oracle may not do.

    Three scorings of one shape, because the two halves of the fix answer different
    questions. With both, the spill is replayed into the image both sides start from, so
    the declined read is still SCORED and agrees: the path #198 added gets a gate and not
    an exemption. With the replay off and the write log on, the read is a DECLINE and not
    a disagreement, which is the floor under every spill of a value the machine computes.
    With neither, the false positive is back, which is what says this test measures it.
    """
    if not _unicorn_available() or not _capstone_available():
        _skip("  SKIP test_a_declined_frame_read_is_not_scored_as_a_disagreement")
    sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "tools"))
    import pbfuzz

    adcs = next(x for x in pbfuzz.RAW if x[0].startswith("adcs"))
    # The smallest run that shows it, shrunk from the first case the sweep reported: the
    # slot holds x3, a PRINTED write to x3 supersedes that record, and the reload of the
    # slot can then spell nothing and says the read instead.
    rows = [("stur x3, [x29, #-0x18]", pbfuzz.enc_stur(3, pbfuzz.FPR, -24)),
            ("ldr x3, [x11], #0x8", pbfuzz.enc_ldr_post(3, 11, 8)),
            ("adcs x3, x3, x4", adcs[1](3, 3, 4)),
            ("ldur x5, [x29, #-0x18]", pbfuzz.enc_ldur(5, pbfuzz.FPR, -24)),
            ("stur x5, [x20, #0x17]", pbfuzz.enc_stur(5, pbfuzz.OBS, 23)),
            ("ret", pbfuzz.RET_WORD)]
    oracle = pbfuzz.Oracle()
    out = oracle.score(rows, trials=12, seed=7, bind_values=True)
    body = "\n  ".join(l.strip() for l in out[-1])
    assert "var t1 = (FP - 24).field_0x1;" in body, body   # the shape, still the shape
    assert out[1] == 0, (
        f"the scorer called a declined frame read a disagreement in {out[1]} of 12 "
        f"environments (#238):\n  {body}")
    assert out[0] == 12, (
        f"the declined read was not scored at all ({out[:-1]}), so the path #198 added "
        f"is exempt rather than gated:\n  {body}")

    class _Deaf(list):
        """A write log that records nothing, which is the state before #238."""

        def append(self, item):
            pass

    real = pbfuzz.entry_spills
    pbfuzz.entry_spills = lambda ann, defuse: {}
    try:
        half = oracle.score(rows, trials=12, seed=7, bind_values=True)
        oracle.wrote = _Deaf()
        none = oracle.score(rows, trials=12, seed=7, bind_values=True)
    finally:
        pbfuzz.entry_spills = real
        oracle.wrote = []
    assert (half[0], half[1], half[2]) == (0, 0, 12), (
        f"without the replay the frame read scored {half[:-1]}, where it has to be a "
        f"decline in all 12: a spill of a computed value cannot be replayed and must "
        f"fall back on this")
    assert none[1] == 12, (
        f"with neither half the scorer called the shape wrong in only {none[1]} of 12 "
        f"environments, so this test is not measuring the false positive it claims to")

    # And the sweep the issue reports, at the size the suite can afford. Two of these
    # four hundred cases were disagreements before, and the number nothing gated is how
    # a real defect of this class would have arrived: "three instead of two".
    tot = pbfuzz.run(400, 12, 1, False, False)
    assert tot["wrong"] == 0, f"{tot['wrong']} of {tot['scored']} scored runs disagreed"
    assert tot["scored"] >= 320 and tot["disagreed"] == 0, tot
    # Not a sweep that scores nothing: every class is reported, and the declines are the
    # runs where the printed body refused rather than runs this harness could not read.
    assert tot["clean"] == tot["scored"] and tot["declined"] > 0, tot


def test_a_self_referential_write_keeps_the_spelling_that_cancels():
    # A register reassigned from its own earlier value (`op d, .., d`, which includes a
    # plain `add d, d, #k`) leaves every value naming d spelled in terms of d, and this
    # pins the spellings the lifter prints for the shapes that produces.
    #
    # It is a spelling pin, NOT a correctness guard, and the distinction was measured:
    # see test_a_self_referential_write_is_right_under_printed_body_semantics. A
    # self-referential write prints no assignment, so d still means the value the function
    # came in with and both the spelling asserted here and the named-first alternative
    # agree with the CPU. An earlier version of this comment claimed the named-first
    # spelling was "correct in none" of 200 environments; that was scored by reading a
    # bare register as the machine's CURRENT value, which is not what the output means
    # (tools/irfuzz.py and the `_bump` invariant test both take the printed body's), so it
    # did not support the claim and is withdrawn.
    #
    # What the pin is worth is the temp it does not mint: naming one side of
    # `x4 + 214 - x4` costs a declaration and reads no better. Change these spellings if
    # something is gained, and show with tools/pbfuzz.py that the replacement still
    # agrees with the CPU.

    # partner is the write's own result: 214 for every input. Naming x7 first would
    # spell the same value as `t0 - x4`, for the cost of the declaration.
    body = _lift_asm([("add", "x7, x4, #0xd6"), ("sub", "x4, x7, x4"),
                      ("stur", "x4, [x20, #7]"), ("stur", "x7, [x20, #15]"), ("ret", "")])
    assert "x20.field_0x8 = x4 + 214 - x4;" in body, body
    assert re.search(r"var t\d+ = x4 \+ 214;", body) is None, body

    # partner is a source of the write, which the write's own spelling needs: 114 for
    # every input. Naming x3 first would spell it `x4 + 214 - t0`.
    body = _lift_asm([("add", "x7, x4, #0xd6"), ("add", "x3, x4, #100"),
                      ("sub", "x4, x7, x4"), ("sub", "x6, x7, x3"),
                      ("stur", "x6, [x20, #7]"), ("ret", "")])
    assert "x20.field_0x8 = x4 + 214 - (x4 + 100);" in body, body
    assert re.search(r"var t\d+ = x4 \+ 100;", body) is None, body

    # partner is a bare copy, which stays bare for the argument, phi and read-afresh rules
    # and so is never named first: all ones for every input.
    body = _lift_asm([("mvn", "x6, x4"), ("mov", "x3, x4"), ("lsr", "x4, x3, #4"),
                      ("orr", "x1, x6, x3"), ("stur", "x1, [x20, #7]"), ("ret", "")])
    assert "x20.field_0x8 = ~x4 | x4;" in body, body
    assert re.search(r"var t\d+ = ~x4;", body) is None, body

    # the partner is met across a FURTHER self-referential write, which leaves x4 as `~x4`
    # and so does not end the chain. Naming x1 at the move would spell it
    # `t0 + ~x4 * ~x4`.
    body = _lift_asm([("mvn", "x1, x4"), ("mov", "x4, x4"), ("mvn", "x4, x4"),
                      ("madd", "x5, x4, x4, x1"), ("stur", "x5, [x20, #7]"), ("ret", "")])
    assert "x20.field_0x8 = ~x4 + ~x4 * ~x4;" in body, body
    assert re.search(r"var t\d+ = ~x4;", body) is None, body

    # two values cancel EACH OTHER and neither is the register: x5 ^ x6 for every input.
    body = _lift_asm([("eor", "x4, x2, x6"), ("eor", "x3, x2, x5"),
                      ("eor", "x2, x4, x2"), ("eor", "x7, x3, x4"),
                      ("stur", "x7, [x20, #7]"), ("ret", "")])
    assert "x20.field_0x8 = x2 ^ x5 ^ (x2 ^ x6);" in body, body
    assert re.search(r"var t\d+ = x2 \^ x5;", body) is None, body


def test_a_block_holding_a_nested_one_is_not_empty():
    """`_drop_dead_phis` keeps a dead phi WHOLE rather than leave a block holding nothing
    else. The lines it counts are a block's DIRECT ones, so a parent whose body is one
    dead declaration plus an `if` looked bare and the dead phi survived (#198).

    Invisible while a live declaration sat beside the dead one, which is why it went
    unnoticed until hoisting moved the live one away: 16 dead lines came back in 5
    functions, 4 of them naming a bare machine register. Both shapes are checked, since
    the one that held before is what made the other one hard to see.

    `_drop_unread_slots` has the same guard for the same reason and does NOT need the same
    change: its `elif` appends a block-opening line to the parent's body, so such a parent
    already fails the all-dropped test. That shape is load-bearing, and tidying it into
    this function's form would reintroduce the bug there."""
    from jadart.expr import _drop_dead_phis

    # The parent holds the dead declaration and an `if`, and the arm holds the dead
    # assignment and a statement, so neither would be left with nothing: it all goes.
    dead_alone = ["  var t13;", "  if (c) {", "    t13 = 1;", "    f(x);", "  }"]
    out = _drop_dead_phis(dead_alone, {"t13"})
    assert out == ["  if (c) {", "    f(x);", "  }"], out

    # The same body with a live declaration beside it: unchanged by this fix, which is
    # why the parent case went unnoticed until hoisting moved the live one away.
    beside_live = ["  var t14;", "  var t13;", "  if (c) {", "    t13 = 1;",
                   "    f(x);", "  }", "  g(t14);"]
    out = _drop_dead_phis(beside_live, {"t13", "t14"})
    assert "  var t13;" not in out and "  var t14;" in out, out

    # And the guard still fires where it must: an arm whose ONLY line is the dead phi
    # stays, because the arm is the walk's to render.
    arm_would_empty = ["  var t13;", "  if (c) {", "    t13 = 1;", "  }"]
    assert _drop_dead_phis(arm_would_empty, {"t13"}) == arm_would_empty


def test_every_name_the_body_reads_is_bound_somewhere_in_it():
    """No read of a name no line of the body binds, at any depth (#205).

    `parsePartialNumber` on the clean fixture, `0xd0c0` on the obfuscated one, read four
    names that nothing declared or assigned anywhere in its 181 lines: six reads, and the
    output is not valid Dart. Worse than a name merely out of scope, which at least has a
    declaration to look at.

    The cause is a loop collapsing a carried name. `_render_loop` binds every carried
    register to a name and, once the body is walked, collapses the ones the body never
    assigned, substituting the entry value back through the body and the tail. A goto out
    of the loop is handed the state from INSIDE it by `_arrive`, which still holds the
    name, and no substitution reaches that target's lines. `_carry_out` now counts such a
    register as escaped, the same way it counts one an exit writes back, so the loop keeps
    the name and the declaration stays.

    This is the invariant SSA gives a decompiler for free, and why Ghidra cannot print
    one: its `ClangVariableDecl` tokens come from the HighVariables the body uses, so a
    declaration is derived from the variable set rather than emitted where the value is.
    """
    if not _capstone_available():
        _skip("  SKIP test_every_name_the_body_reads_is_bound_somewhere_in_it")
    from jadart.disasm import (load_instructions, disassemble_range, function_name_by_pc,
                               build_pool_map)
    from jadart.expr import lift_function

    # The scan is deliberately free of any helper from `expr`: it reads the shipped text
    # the way a reader does, so the same check runs against any commit.
    name_re = re.compile(r"\bt\d+\b")
    bound_re = re.compile(r"(?:^|[{};]|\bvar\s+)\s*(t\d+)\s*(?:[-+*/&|^]?=(?!=)|;)")

    def undeclared(lines):
        bound = set(bound_re.findall("\n".join(lines)))
        out = []
        for ln in lines:
            rest = ln
            for m in bound_re.finditer(ln):
                rest = rest.replace(m.group(0), " ", 1)
            out += [n for n in name_re.findall(rest) if n not in bound]
        return out

    image, fr, _hdr = load_instructions(CLEAN)
    pc_to_name = function_name_by_pc(image, fr)
    pool_map = build_pool_map(fr)
    at = next((cr for cr in image.all_ranges if cr.pc_offset == 0x11090), None)
    assert at is not None, "parsePartialNumber is not at 0x11090 in this fixture"
    lines = lift_function(_ann(image, disassemble_range(image, at), pc_to_name, pool_map),
                          pool_map)
    body = [ln.rstrip() for ln in lines]
    assert len(body) > 150, len(body)        # the shape this is about, not a stub
    assert undeclared(body) == [], undeclared(body)
    # The loop that collapsed them is still there, and still collapses the names no goto
    # target was handed: the three it binds for registers the body does assign stay.
    assert sum(1 for ln in body if re.match(r"\s*while \(true\) \{", ln)) >= 3, body


def test_a_name_is_not_read_after_its_declaration_closed():
    """The lifter printed `var t1 = x7;` inside a `while` and read `t1` at a goto target
    after the loop closed: a reference to something no longer declared, which a Dart
    parser rejects and an agent resolves to nothing. 1,488 such reads in 517 of 8,194
    ranges on the clean build, now 171 in 122 (#198).

    Counted by `expr._out_of_scope` and nowhere else. Four separate scripts of mine
    drifted from its rules and each reported a number I had to withdraw, so the only
    supported way to measure this is the function the lifter itself uses, through the
    `hits` list it fills on the same walk. Counting occurrences of the returned SET
    afterwards is a different and wrong number, because a name can be in scope on one
    line and out on another."""
    if not _capstone_available():
        _skip("  SKIP test_a_name_is_not_read_after_its_declaration_closed")
    sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "tools"))
    import pbfuzz
    from jadart import expr

    # the shape, as the lifter prints it: a declaration that has closed, and one that has not
    closed = ["  while (true) {", "    var t1 = x7;", "  }", "  x2.field_0x8 = t1;"]
    hits = []
    assert expr._out_of_scope(closed, hits) == {"t1"} and len(hits) == 1, hits
    hoisted = ["  var t1;", "  while (true) {", "    t1 = x7;", "  }",
               "  x2.field_0x8 = t1;"]
    assert expr._out_of_scope(hoisted) == set()
    # a use in the note a raw line carries is not a read: `_inline_single_use` refuses to
    # fold into one for the same reason, and hoisting on a comment moved a name for nobody
    noted = ["  while (true) {", "    var t1 = x7;", "  }",
             "  fmov x3, d0   // d0 holds t1"]
    assert expr._out_of_scope(noted) == set()
    # an inner declaration shadowing an outer one leaves the outer in scope
    shadowed = ["  var t1 = 1;", "  if (c) {", "    var t1 = 2;", "  }",
                "  x2.field_0x8 = t1;"]
    assert expr._out_of_scope(shadowed) == set()

    got = pbfuzz.census(CLEAN)
    assert got["lifted"] > 8000, f"only {got['lifted']} ranges lifted"
    # Zero since #234, where the last five went: `State.set` mints a name for a value too
    # long to inline, it was the one minting site outside `_mint`, and a name the hoist
    # does not know about cannot be moved to the top of the body. Now that it is known,
    # nothing is left reading a declaration that has closed.
    assert got["oos"] == 0, (
        f"{got['oos']} reads of a name whose declaration has closed, in "
        f"{got['oos_fns']} ranges, where there were none; see #204, #205 and #234")
    # And NO name read that the body never binds at all, which is not valid Dart and
    # leaves a reader nothing to go on. Four of them shipped, six reads, all in
    # `parsePartialNumber` on both fixtures (#205). A bound, not a budget: this one is
    # exactly zero.
    assert got["undecl"] == 0, (
        f"{got['undecl']} names read that no line of the body binds; see #205")


def test_a_declined_frame_reload_names_the_read_and_not_the_register():
    """A frame reload the walk cannot answer says the read, under a fresh name (#198).

    It used to print NOTHING and keep the load's own register. The printed body reads a
    register it never assigns as the value the function came in with, so the output said
    the destination still held its entry argument. It does not: the load happened. That
    is one silent wrong read per declined reload, and it is the whole residual of #198,
    because no record of what the slot held reaches the cases that make up most of it:
    once a path may have written the slot, neither the register nor a name for the
    register is what the load reads. Naming the value at the spill instead measured four
    fewer reads on the clean build for 1.7% more output.

    So the rule is `_phi_name`'s, at the other end: always a fresh one, never the
    register. The read is spelled the way the lifter already spells that address when it
    is held in a register, `sub x0, x29, #0x40; ldur x3, [x0, #8]` printing
    `(FP - 64).field_0x9`, so the negative part of the displacement goes into the base
    and the field offset carries the tag bias.

    Every assertion here prints a bare `x3` on main, except the two marked as guards."""
    from jadart.expr import lift_function

    def lift(rows):
        at, n = {}, 0
        for r in rows:
            if isinstance(r, str):
                at[r] = n * 4
            else:
                n += 1
        ann = []
        for r in (r for r in rows if not isinstance(r, str)):
            op = r[1]
            for name, a in at.items():
                op = op.replace("@" + name, "#%#x" % a)
            ann.append((len(ann) * 4, r[0], op, ""))
        return [ln.strip() for ln in lift_function(ann)]
    keep = [("stur", "x3, [x2, #7]"), ("ret", "")]

    # A slot the walk never saw a store to, below FP and above SP.
    assert lift([("ldur", "x3, [x29, #-8]")] + keep)[:2] == [
        "var t0 = (FP - 8).field_0x1;", "x2.field_0x8 = t0;"]
    assert lift([("ldur", "x3, [x15, #0x10]")] + keep)[:2] == [
        "var t0 = SP.field_0x11;", "x2.field_0x8 = t0;"]
    assert lift([("ldur", "x3, [x29]")] + keep)[:2] == [
        "var t0 = FP.field_0x1;", "x2.field_0x8 = t0;"]
    # A load narrower than a word says how many bytes it read, where it used to print
    # the eight-byte spelling masked, which said the same thing twice (#221).
    assert lift([("ldurh", "w3, [x29, #-8]")] + keep)[:2] == [
        "var t0 = (FP - 8).field2_0x1;", "x2.field_0x8 = t0;"]
    assert lift([("ldurb", "w3, [x29, #-8]")] + keep)[:2] == [
        "var t0 = (FP - 8).field1_0x1;", "x2.field_0x8 = t0;"]
    # The SIGN is a separate fact about the destination's 64 bits, and the shift pair is
    # still the only thing that says it.
    assert lift([("ldursh", "x3, [x29, #-8]")] + keep)[:2] == [
        "var t0 = (FP - 8).field2_0x1 << 48 >> 48;", "x2.field_0x8 = t0;"]
    # Four bytes keeps the plain spelling: this target compresses pointers, so a four-byte
    # read is what a reference field read looks like and the width is the representation's
    # rather than the value's (#221).
    assert lift([("ldur", "w3, [x29, #-8]")] + keep)[:2] == [
        "var t0 = (FP - 8).field_0x1;", "x2.field_0x8 = t0;"]
    # Only the half of a pair that is read again is named.
    assert lift([("ldp", "x3, x4, [x29, #-0x10]")] + keep)[:2] == [
        "var t0 = (FP - 16).field_0x1;", "x2.field_0x8 = t0;"]
    # The pass that drops a name nothing reads keeps one that is all its block holds: an
    # `if` arm is the walk's to render, and taking its only line prints `if (c) {` with
    # `}` under it. 112 empty blocks in 47 ranges of the clean build shipped without this.
    from jadart.expr import _drop_unread
    sole = ["  if (c) {", "    var t0 = (FP - 8).field_0x1;", "  }", "  f(x1);"]
    assert _drop_unread(sole, {"t0"}) == sole, _drop_unread(sole, {"t0"})
    more = ["  if (c) {", "    var t0 = (FP - 8).field_0x1;", "    f(x1);", "  }"]
    assert _drop_unread(more, {"t0"}) == [more[0], more[2], more[3]]
    # Liveness is keyed by `_regs` and not by `canon`, and the two disagree for the
    # floating-point file. Asking the state key minted a bit that is never live, so every
    # `q`, `v`, `h` and `b` reload was passed over however it was read: 1,169 of them off
    # FP on the clean build, in 260 ranges.
    from jadart.expr import _regs, canon
    assert canon("q3") == "q3" and _regs(("q3",)) == {"d3"}
    # A width the field spelling cannot say declines rather than claim eight bytes: the
    # general file has the `_extended` convention for that and the other one has none.
    # Only `s3` is a regression case, since `canon` already called it `d3` and the old
    # test matched; the rest are guards that hold either way.
    for r in ("q3", "v3", "s3", "h3", "b3"):
        got = lift([("ldur", f"{r}, [x29, #-8]"), ("stur", f"{r}, [x2, #7]")] + keep)
        assert not any("field_0x" in l and "var " in l for l in got), (r, got)
    assert lift([("ldur", "d3, [x29, #-8]"), ("stur", "d3, [x2, #7]")] + keep)[:2] == [
        "var t0 = (FP - 8).field_0x1;", "x2.field_0x8 = t0;"]
    # A guard: a register nothing reads again gets no line, because naming it would print
    # a value the reader never meets.
    assert lift([("ldur", "x3, [x29, #-8]"), ("mov", "x3, #1")] + keep)[0] == (
        "x2.field_0x8 = 1;")
    # A guard: a slot that round-trips still says what it holds, and says nothing of the
    # read. This is the case the old fallback was right about, 904 reader-visible reads on
    # the clean build, and it is the only one.
    assert lift([("stur", "x0, [x29, #-8]"), ("ldur", "x3, [x29, #-8]")] + keep)[0] == (
        "x2.field_0x8 = x0;")
    # The name is hoisted by the same rule as a phi name, so naming a reload inside a
    # block does not trade a wrong read for a read out of scope: the declaration goes to
    # the top and the read stays where the memory holds what it holds. (The goto target
    # here reads x3 rather than the name; that is the loop-exit class, #176.)
    got = lift([("mov", "x9, #3"), "top", ("ldur", "x3, [x29, #-8]"),
                ("cbz", "x1, @out"), ("sub", "x9, x9, #1"), ("cbnz", "x9, @top"),
                ("ret", ""), "out", ("stur", "x3, [x2, #7]"), ("ret", "")])
    assert got[0] == "var t1;" and "t1 = (FP - 8).field_0x1;" in got, got
    assert "var t1 = (FP - 8).field_0x1;" not in got, got


def test_a_frame_read_off_sp_says_where_it_is_in_the_frame_it_was_entered_with():
    """A read off SP is spelled against the frame the function was entered with (#207).

    `SP` in a read's text means SP AT that line, and the pushes and pops that move it
    print nothing, so two reads of two addresses printed one text and a reader had no way
    to tell them apart. Where the pass knows SP's place in the frame exactly, the read
    says that place instead, and one address then has one spelling whatever SP does. The
    accesses through FP were already rewritten into the coordinates of the frame FP
    started in (#165); this is the other half.
    """
    from jadart.expr import lift_function

    def lift(rows):
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])]

    # The body from the issue, which pushes two pairs, calls, and pops them back. The two
    # reads are sixteen bytes apart and both printed `SP.field_0x1`.
    body = [("stp", "x2, x3, [x15, #-0x10]!"), ("stp", "x4, x5, [x15, #-0x10]!"),
            ("bl", "#0x100"), ("ldp", "x4, x5, [x15], #0x10"),
            ("ldp", "x2, x3, [x15], #0x10"), ("stur", "x4, [x20, #7]"),
            ("stur", "x2, [x20, #0xf]"), ("ret", "")]
    enter = [("stp", "x29, x30, [x15, #-0x10]!"), ("mov", "x29, x15")]
    out = lift(enter + body)
    # A post-indexed load reads where SP is BEFORE its write-back, so the first pop takes
    # the pair 32 bytes under the frame and the second the pair 16 under it.
    assert ["var t0 = sub_0x100(...);", "var t1 = (FP - 32).field_0x1;",
            "var t2 = (FP - 16).field_0x1;"] == out[:3], out
    # Nothing to anchor to without a prologue: FP there is the caller's frame pointer, so
    # the reads stay off SP and the text still stands for both. This is the issue's own
    # listing, and it is the shape the fix does NOT reach.
    assert [l for l in lift(body) if "field_0x1;" in l] == [
        "var t1 = SP.field_0x1;", "var t2 = SP.field_0x1;"], lift(body)
    # An alignment leaves SP known only to within fifteen bytes, which names no address,
    # so the read declines and keeps the spelling that says only "off SP".
    aligned = enter + [("sub", "x15, x15, #0x20"), ("str", "x0, [x15, #8]"),
                       ("and", "x15, x15, #0xfffffffffffffff0"),
                       ("ldr", "x3, [x15, #8]"), ("stur", "x3, [x20, #7]"), ("ret", "")]
    assert "var t0 = SP.field_0x9;" in lift(aligned), lift(aligned)


def test_no_frame_slot_record_outlives_the_path_that_made_it():
    """The gate for #196's class, and the one check for it that needs no emulator.

    A reload that spells a register the slot did not hold, and a record spelled on a path
    that superseded it, are both properties of the printed body and the instruction list.
    So this runs wherever capstone does, which is every pull request. It exists because
    #197 shipped 2,023 stale spellings past four green CI jobs, a clean suite and five
    CPU-verified shapes: nothing automated looked at this class, in either direction
    (`irfuzz` generates no x29-relative frame slot, and `tools/pbfuzz.py`'s fuzzing half
    scores any store resting on a written register as a decline).

    Two assertions, and they are different in kind. STALE must be zero: a record spelled
    after its own path superseded it is `#199` and there is no acceptable number of them.
    WRONG READS is the residual #198 tracks, recorded here so it can only go down; lower
    the number when it does, and read FINDINGS.md before raising it.

    The census forks its bookkeeping where the lifter forks `State` and scores only the
    last walk of each range, because `lift_function` walks up to three times. Five earlier
    measurements of this class were wrong for want of one of those, so the second half of
    this test puts the bug back and checks the census still sees it."""
    if not _capstone_available():
        _skip("  SKIP test_no_frame_slot_record_outlives_the_path_that_made_it")
    sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "tools"))
    import pbfuzz
    from jadart import expr

    got = pbfuzz.census(CLEAN)
    assert got["ranges"] > 8000, f"only {got['ranges']} ranges, so this proved little"
    assert got["spelled"] > 1000, f"only {got['spelled']} records spelled"
    assert got["stale"] == 0, (
        f"{got['stale']} frame-slot records were spelled after their own path had "
        f"superseded them; see #199 and State.dropped's invariant")
    # Two numbers, because they can move in opposite directions. ACTIONABLE is where the
    # slot held a spelling that was still available; it is what #198's frame-model work
    # takes down. TOTAL adds the reads whose slot held a NAME out of its declaration's
    # scope, which cannot be spelled at all and so are a forced decline. Naming a spill
    # earlier moves reads from the first into the second without the reader gaining
    # anything, so a change that improves one must not quietly worsen the other.
    # Both numbers moved at #234, and down: a call that cannot return no longer hands its
    # block's state to the join under it, so a reload on the far side finds the spelling
    # the arm that DOES arrive left. 2,579 to 2,089, and the share with it, 30.3% to
    # 23.3%, over 451 more records spelled.
    assert got["wrong"] <= 2089, (
        f"{got['wrong']} reloads spell a register where the slot held a spelling that was "
        f"available, up from 2089; see #198. {got['diff_reg']} held another register, "
        f"{got['expr']} an expression")
    assert got["wrong"] / max(1, got["spelled"]) <= 0.24, (
        f"{got['wrong']} of {got['spelled']} spelled records read back wrong, a higher "
        f"share than the 23.3% #234 left; a count that rises with the records spelled is "
        f"the same residual, a rising share is a new one")
    # 2,856 to 2,886 when the census began to follow `_reenter`'s reset, which is not the
    # same count: main read 2,853 judged against the path printed above a reset, and
    # 2,886 against the way in the state came by. Then 2,896 at #266, the code tier 3 now
    # places adding 10 wrong reads, all of them in it. Then 2,899 at #278, `wrong` at
    # 2,082 still and `name` 814 to 817: a monomorphic section lifted as a body keeps its
    # frame, so three loop latches, one in each of the `dyn:call` closures at 0x1be718,
    # 0x1bea7c and 0x1bedac, see a slot that held a name out of scope where they saw none.
    # Each prints as a declined read, as the same rows lifted from +8 do.
    assert got["wrong"] + got["name"] <= 2899, (
        f"{got['wrong'] + got['name']} reloads in total name a different value than the "
        f"slot held, up from 2899, of which {got['name']} are names out of scope")
    # And the reader-visible half of #198, which the two numbers above cannot see: they
    # score what `_reload` DECIDES, and the fix for a decline is at the call site, which
    # names the read rather than keeping the load's own register. A register the printed
    # body never assigns reads as the value the function came in with, so every line this
    # removes is a line that stopped claiming one. Counted with `tools/quality.py`'s own
    # regex, not a copy of it.
    assert got["regline"] <= 26393, (
        f"{got['regline']} lines carry a bare machine register, up from 26393; a reload "
        f"that declines must name the read and not keep the register (#198)")
    # And no block is left holding nothing. A pass that drops a declaration nothing reads
    # can take the only line an `if` arm has: `_drop_unread_slots`, `_drop_dead_phis` and
    # `_drop_unread` each guard against it, and 112 empty blocks in 47 ranges shipped
    # while the third one did not. There is no acceptable number of these.
    assert got["empty"] == 0, (
        f"{got['empty']} rendered blocks hold nothing, `if (c) {{` with `}}` under it; a "
        f"pass dropped the only line an arm had (#198)")
    # And the rest of the rendered text's own invariants (#210). These exist because a
    # per-symptom COUNT cannot see a shape: #206 verified its counts over two review
    # rounds and still nearly shipped 112 empty blocks. Four are exact, because there is
    # no acceptable number of them.
    # `dead` is #234's: a statement under a `throw` is code no path reaches, and with the
    # runtime stubs named and the throw's fall-through edge still in the graph there were
    # 1,224 of them on this fixture, phi write-backs for the path that never arrives and
    # `goto`s out of a throw.
    for k, why in (("unbalanced", "functions whose braces do not balance"),
                   ("twice", "names the body declares twice"),
                   ("above", "names read on a line above their declaration"),
                   ("dead", "statements printed under a `throw`, which no path reaches")):
        assert got[k] == 0, f"{got[k]} {why} (#210, #234)"
    # A bound, not a zero: `_drop_unread`'s guard trades an empty block for a block whose
    # only line is a declaration nothing reads, which is the honest side of that trade and
    # the same one `_drop_unread_slots` already makes.
    # 1,398 to 1,489 at #234, one shape, and a named stub is what
    # uncovers it: a type-test stub is dropped, so the class-id load in front of it
    # (`var t11 = 60; if (x & 1 != 0) { t11 = (x.tags >> 12) & 0xfffff; }`) is left with
    # nothing reading it, and the arm of that `if` is a block holding one dead assignment.
    # Dropping a computation whose only reader was a suppressed stub is the fix, and it is
    # `_drop_unread`'s business rather than the naming's.
    # 1,489 to 1,527 at #266, all in the code tier 3 now places: over `lift`'s own output
    # 1,144 to 1,179, every one of the 35 in a section past the body. 1,528 at #278: the
    # section at 0x1be718, lifted as a body, writes the phi of x4 under its null test,
    # which nothing reads, as the same rows lifted from +8 do.
    assert got["sole"] <= 1528, (
        f"{got['sole']} blocks hold nothing but a declaration nothing reads, up from "
        f"1528; see the guard in `_drop_unread` (#210)")

    # Put the bug back, twice, on a subset for speed. #197 was both of these at once.
    real_note, real_copy, real_merge = (expr.State.note_slot, expr.State.copy,
                                        expr._merge)

    def no_supersede(self, key, v):
        kept = self.dropped.get(key)
        out = real_note(self, key, v)
        if kept is not None:
            self.dropped[key] = kept          # a fill no longer kills the record
        return out

    def shared(self):
        s = real_copy(self)
        s.dropped = self.dropped              # the arms share one map
        return s

    def no_intersect(dst, a, b):
        kept = dict(a.dropped)
        real_merge(dst, a, b)
        dst.dropped = kept                    # the join no longer intersects

    for what, patch in (("a fill no longer supersedes", ("note_slot", no_supersede)),
                        ("records leak across paths", ("copy", shared))):
        name, fn = patch
        setattr(expr.State, name, fn)
        if name == "copy":
            expr._merge = no_intersect
        try:
            bad = pbfuzz.census(CLEAN, limit=3000)
        finally:
            expr.State.note_slot, expr.State.copy = real_note, real_copy
            expr._merge = real_merge
        assert bad["stale"] > 0, (
            f"with {what} the census still reported 0 stale records, so it is not "
            f"measuring what it claims")


def test_the_census_judges_a_reload_past_a_reset_by_the_way_in_it_came():
    """The census keeps, per walk state, what each frame slot was filled with, and judges
    a reload the lifter declines against it. `_reenter` hands a block a slot map of its
    own, the one predecessor's exit state or none at all, and the history stayed with the
    path printed above: past a trap, an honest decline read as a wrong read of the
    register that path had stored. The history follows the reset now: 17 wrong reads
    went on the clean fixture and 3 were judged against the predecessor they came by."""
    sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "tools"))
    import pbfuzz
    from jadart import expr
    rows = [("stur", "x2, [x29, #-8]"), ("brk", "#0"), ("ldur", "x3, [x29, #-8]"),
            ("stur", "x3, [x4, #7]"), ("ret", "")]
    restore, _tot, walk, _hist, _alive = pbfuzz._census_hooks(expr)
    try:
        expr.lift_function([(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])
    finally:
        restore()
    got = walk["cur"]
    assert (got["diff_reg"], got["never"]) == (0, 1), got


def test_a_reload_of_a_dropped_slot_reads_the_value_it_held():
    # A frame slot whose text names a register that is then reassigned is DROPPED, so the
    # text cannot read the new register (#173). What the reload then PRINTS is this test.
    #
    # It used to print the load's own destination, which names a different value: over 60
    # random register environments each case below stores what the slot held in 60 of 60
    # and the destination register's entry value in 0 of 60, and across the 3.12.2 clean
    # build the fallback misnamed 6,623 reads in 1,967 of 8,194 functions (#196).
    #
    # Sound because the drop is about the MAP, not the output: the instruction that
    # reassigned the register was folded, so it printed no assignment and the printed body
    # still reads that register as it did at the spill. `State.dropped` carries the
    # conditions that have to hold with it, and #199 is what happens without them.
    from jadart.expr import lift_function

    def lift(rows):
        rows = list(rows) + [("ret", "")]
        ann = [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)]
        return [ln.strip() for ln in lift_function(ann)]

    # the issue's case: x6 stored, reassigned by a mov, then reloaded into x3. The
    # machine stores the x6 that was spilled, which is what the body's `x6` still reads.
    out = lift([("stur", "x6, [x29, #-8]"), ("mov", "x6, x2"),
                ("ldur", "x3, [x29, #-8]"), ("stur", "x3, [x20, #7]")])
    assert "x20.field_0x8 = x6;" in out, out
    assert "x20.field_0x8 = x3;" not in out, out

    # a register reassigned by a load reads the same way: the load prints nothing either
    out = lift([("stur", "x6, [x29, #-8]"), ("ldr", "x6, [x7, #0x10]"),
                ("ldur", "x3, [x29, #-8]"), ("stur", "x3, [x20, #7]")])
    assert "x20.field_0x8 = x6;" in out, out
    assert "x20.field_0x8 = x3;" not in out, out

    # an EXPRESSION the slot held reads the same way. The text reads memory, so it is
    # spelled only while nothing has written memory since the drop (`State.stale_mem`);
    # nothing has here.
    out = lift([("ldr", "x5, [x7, #0x10]"), ("stur", "x5, [x29, #-8]"),
                ("mov", "x7, x2"), ("ldur", "x3, [x29, #-8]"),
                ("stur", "x3, [x20, #7]")])
    assert "x20.field_0x8 = x7.field_0x11;" in out, out
    assert "x20.field_0x8 = x3;" not in out, out

    # Put the bug back. With the record forgotten the reload no longer has the value the
    # slot held, so a pass above is not the shape being uninteresting. It says the read it
    # is rather than the register it used to keep, which is truthful and tells the reader
    # less, and is exactly why the record is worth having (#198).
    from jadart import expr
    real = expr.Lifter._reload

    def no_memory(self, st, key, mn, reg):
        st.dropped.clear()
        return real(self, st, key, mn, reg)

    expr.Lifter._reload = no_memory
    try:
        out = lift([("stur", "x6, [x29, #-8]"), ("mov", "x6, x2"),
                    ("ldur", "x3, [x29, #-8]"), ("stur", "x3, [x20, #7]")])
    finally:
        expr.Lifter._reload = real
    assert "x20.field_0x8 = x7.field_0x11;" not in out, out
    assert ["var t0 = (FP - 8).field_0x1;", "x20.field_0x8 = t0;"] == out[:2], out

    # a register reassigned by a reload off the frame drops the OTHER slots it names, not
    # just the straight-line writes: the slot it reads back is kept (dropping it would
    # collide two reloads), the rest go (#173). Here x6 reloads from [-0x10], so the [-8]
    # slot that names x6 is dropped and its reload spells the x6 it held. The kept slot is
    # never recorded, because `stale_on_write` records at the drop and not before it.
    out = lift([("stur", "x6, [x29, #-8]"), ("ldur", "x6, [x29, #-0x10]"),
                ("ldur", "x3, [x29, #-8]"), ("stur", "x3, [x20, #7]")])
    assert "x20.field_0x8 = x6;" in out, out
    assert "x20.field_0x8 = x3;" not in out, out

    # a slot whose register is never reassigned still reads it: the drop is tight, not a
    # blanket stale of every slot that names a register the block writes. The restore form
    # (a reload that reads a slot back into the register it names) keeps the slot too.
    out = lift([("stur", "x6, [x29, #-8]"), ("ldur", "x3, [x29, #-8]"),
                ("stur", "x3, [x20, #7]")])
    assert "x20.field_0x8 = x6;" in out, out
    out = lift([("stur", "x6, [x29, #-8]"), ("ldur", "x6, [x29, #-8]"),
                ("stur", "x6, [x20, #7]")])
    assert "x20.field_0x8 = x6;" in out, out


def test_a_store_through_a_base_the_loop_wrote_names_it_unknown():
    """A store whose base register the LOOP'S OWN code writes goes through a name (#208).

    After the loop the machine holds what the last trip put in that register, while the
    register's own name says the value the function came in with, so the store writes a
    field of the wrong object. Same rule as #206's at the other map and #216's at the
    other end: a fallback must not borrow a name that already means something. 39 stores
    on each fixture.

    Two things are deliberately NOT this, and the cases below hold them:

    * a register only a CALL inside the loop clobbered. That is #216's class, which names
      it where a straight-line read follows the call. Treating it here renames the base of
      every store after a loop that calls, which is most of them, and three loop tests say
      so; that half wants its own measurement.
    * a register written BEFORE the loop. `_loop_nodes` returns every ancestor of the
      header, so the pre-loop blocks are in it (#228), and a register written there holds
      what that block put in it, which its own name says correctly. The marking asks
      `_loop_region` instead, the blocks the header dominates.
    """
    from jadart.expr import lift_function

    def lift(rows):
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])]

    # The loop loads x2 every trip, and the store after it is based on x2.
    got = lift([("mov", "x9, #3"), ("ldur", "x2, [x1, #7]"), ("sub", "x9, x9, #1"),
                ("cbnz", "x9, #0x4"), ("stur", "x5, [x2, #0xb]"), ("ret", "")])
    assert "var t1;" in got, got
    assert "t1.field_0xc = x5;" in got, got
    # A loop that only CALLS keeps the bare base: that is #216's class, not this one.
    called = lift([("mov", "x9, #3"), ("bl", "#0x100"), ("sub", "x9, x9, #1"),
                   ("cbnz", "x9, #0x4"), ("stur", "x5, [x2, #0xb]"), ("ret", "")])
    assert "x2.field_0xc = x5;" in called, called
    # A write BEFORE the loop keeps it too: x2 holds what that line put there.
    before = lift([("ldur", "x2, [x1, #7]"), ("mov", "x9, #3"), ("add", "x8, x8, #1"),
                   ("sub", "x9, x9, #1"), ("cbnz", "x9, #0x8"),
                   ("stur", "x5, [x2, #0xb]"), ("ret", "")])
    assert any(ln.endswith(".field_0xc = x5;") and not ln.startswith("var") for ln in
               before), before
    assert not any(ln == "var t1;" for ln in before), before
    # A register the loop carries is named by the carry, not by this: it has a value.
    walked = lift([("mov", "x9, #3"), ("ldur", "x2, [x2, #7]"), ("sub", "x9, x9, #1"),
                   ("cbnz", "x9, #0x4"), ("stur", "x5, [x2, #0xb]"), ("ret", "")])
    assert "var t0 = x2;" in walked, walked
    assert "t0.field_0xc = x5;" in walked, walked


def test_a_register_the_loop_never_wrote_still_holds_its_value_after_it():
    """The loop's blocks are its OWN, the natural body read off the back edges (#228).

    `_loop_nodes` closes backward over the header's predecessors without stopping at the
    header, so it returns every ANCESTOR of it: on the clean fixture, 20,211 blocks across
    the 833 loops it is asked about where the body is 8,975, and 9,781 of the extra ones
    run BEFORE the loop. Three questions are asked of that set, and a block that ran
    before the loop answers none of them.

    #129 called this conservative. It is not. What the loop WRITES decides what is
    forgotten after it, and a forgotten register prints as its own bare name, which reads
    as the value the function came in with: the third case below holds a register the loop
    never touched, and main prints the entry value where the machine has what the line
    before the loop computed. That is #206's class, reached by counting a pre-loop write
    as the loop's.

    Taking the body instead needs the two things a trip can make stale written out above
    the loop, which the inflation was doing by accident (`_pin_loop`): a value whose text
    names a register the loop writes, and one that reads memory a trip stores to. Without
    them `--cfgmem` disagrees at seed 9.

    The body is also what the field means by a loop: LLVM's is the maximal strongly
    connected set whose every entering edge reaches the header, and Ghidra's `LoopBody`
    marks the same one off the back edges, by Tarjan's method.
    """
    from jadart.expr import lift_function

    def lift(rows):
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])]

    # Written before the loop and read INSIDE it: not loop-carried, because no trip
    # assigns it. Main hoisted the value into a carried name and read that.
    inside = lift([("add", "x3, x1, #8"), ("mov", "x9, #3"), ("stur", "x3, [x2, #7]"),
                   ("sub", "x9, x9, #1"), ("cbnz", "x9, #0x8"), ("ret", "")])
    assert "x2.field_0x8 = x1 + 8;" in inside, inside
    assert not any(ln.startswith("var t0 = x1 + 8;") for ln in inside), inside
    # Read AFTER the loop, which the loop leaves alone: it still holds what that line put
    # there. Main forgot it and printed `x3`, the entry value.
    after = lift([("add", "x3, x1, #8"), ("mov", "x9, #3"), ("add", "x8, x8, #1"),
                  ("sub", "x9, x9, #1"), ("cbnz", "x9, #0x8"),
                  ("stur", "x3, [x2, #7]"), ("ret", "")])
    assert "x2.field_0x8 = x1 + 8;" in after, after
    # A value naming a register the loop DOES write is written out above the loop, where
    # it still means what it says.
    stale = lift([("add", "x3, x9, #0x22"), ("mov", "x11, #3"), ("add", "x9, x9, #1"),
                  ("sub", "x11, x11, #1"), ("cbnz", "x11, #0x8"),
                  ("stur", "x3, [x2, #7]"), ("ret", "")])
    assert "var t0 = x9 + 34;" in stale and "x2.field_0x8 = t0;" in stale, stale
    # So is one that reads memory a trip stores to: the load already happened.
    mem = lift([("ldur", "x3, [x1, #7]"), ("mov", "x11, #3"), ("stur", "x5, [x1, #7]"),
                ("sub", "x11, x11, #1"), ("cbnz", "x11, #0x8"),
                ("stur", "x3, [x2, #0xf]"), ("ret", "")])
    assert "var t0 = x1.field_0x8;" in mem, mem
    assert "x1.field_0x8 = x5;" in mem and "x2.field_0x10 = t0;" in mem, mem


def test_a_store_through_a_base_the_join_lost_names_it_unknown():
    """A store whose BASE register a join lost is written through a name, not through the
    register (#208, from #198).

    The two arms left different values in it, so the register's own name says the object
    the function came in with while the machine has one of the two others, and the store
    writes a field of the wrong object. That is #206's rule at the other map: a fallback
    must not borrow a name that already means something, and #216's at the other end of
    the same argument. The name has no initialiser, `var tN;`, which says the lifter does
    not know what this points at.

    `lost` and not every register the walk drops to its bare name. A loop exit drops the
    ones the loop writes, which takes the class from 17 stores to 147, and naming those
    costs 152 more blocks holding nothing but a declaration nothing reads, and contradicts
    the loop-reload expectations two tests below this one. Measured and left on the issue.
    """
    from jadart.expr import lift_function

    def lift(rows):
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])]

    # One arm loads x2 from itself, the other copies x4 into it, and the store after the
    # join uses x2 as its base.
    # The `nop` is a block nothing reaches, placed after the body since #266; the `if`
    # above the store is there only for the label its goto names.
    got = lift([("cbz", "x3, #0x10"), ("ldur", "x2, [x2, #7]"), ("b", "#0x14"),
                ("nop", ""), ("mov", "x2, x4"),
                ("stur", "x1, [x2, #0xb]"), ("ret", "")])
    assert got[:3] == ["if (x3 == 0) {", "L_0x10:", "}"], got
    assert got[3] == "var t0;", got
    assert got[4] == "t0.field_0xc = x1;", got
    # Where the arms AGREE the register is not lost and keeps its own name, which is the
    # value the function came in with and reads right.
    agree = lift([("cbz", "x3, #0x10"), ("mov", "x5, #1"), ("b", "#0x14"),
                  ("nop", ""), ("mov", "x5, #2"),
                  ("stur", "x1, [x2, #0xb]"), ("ret", "")])
    assert "x2.field_0xc = x1;" in agree, agree
    # And a role register is not renamed: THR, SP, FP and PP hold the same thing all the
    # way through, so their own spelling is right wherever it appears.
    thr = lift([("cbz", "x3, #0x10"), ("ldur", "x2, [x2, #7]"), ("b", "#0x14"),
                ("nop", ""), ("mov", "x2, x4"),
                ("stur", "x1, [x26, #0xb]"), ("ret", "")])
    assert "THR.field_0xb = x1;" in thr, thr


def test_a_slot_or_lr_a_write_changed_out_of_sight_reads_as_changed():
    # What the review of #154 left (#162). A call writes LR, and LR read the same after
    # it. A store replaced only the slots it filled, so one it covered part of kept its
    # text, and a store `_step` prints raw, or one through SP over a slot kept through
    # FP, changed none. Each of these printed a value the machine no longer holds.
    from jadart.expr import StackArity, lift_function, _frame_meets

    def lift(rows, **kw):
        # A string row is a label, and `@name` in the operands is its address.
        rows = rows + [("ret", "")]
        at, n = {}, 0
        for r in rows:
            if isinstance(r, str):
                at[r] = n * 4
            else:
                n += 1
        ann = []
        for r in (r for r in rows if not isinstance(r, str)):
            op = r[1]
            for name, a in at.items():
                op = op.replace("@" + name, "#%#x" % a)
            ann.append((len(ann) * 4, r[0], op, r[2] if len(r) > 2 else ""))
        return [ln.strip() for ln in lift_function(ann, **kw)]

    def frame(size, *rows):
        # Dart's frame: FP at the saved pair, SP `size` below it.
        return [("stp", "x29, x30, [x15, #-0x10]!"), ("mov", "x29, x15"),
                ("sub", "x15, x15, #%#x" % size)] + list(rows)

    def loop(*inside):
        return [("mov", "x9, #3"), "top", *inside, ("sub", "x9, x9, #1"),
                ("cbnz", "x9, @top")]
    keep = [("stur", "x3, [x2, #7]")]
    throw = "  ; -> stub _iso_stub_ThrowStub"
    # LR after a call, after a stub that gives every register back, and after an atomic
    # that loads into it.
    # LR is the call's to clobber like any other register, so the store now says the name
    # the call declares for what it left there, where a bare x30 read as the LR the
    # function was entered with (#176). Either way it is not the slot the `stur` filled,
    # which is what this case is about, so that is what the assertion says.
    got = lift([("stur", "x30, [x29, #-8]"), ("bl", "#0x200"), ("mov", "x6, x30"),
                ("stur", "x6, [x2, #7]")])
    m = re.search(r"t\d+\.field_0x8 = (t\d+);", "\n".join(got))
    assert m and f"var {m.group(1)};" in got, got
    assert "FP - 8" not in "\n".join(got), got
    check = "  ; -> stub _iso_stub_StackOverflowSharedWithFPURegsStub"
    assert lift([("bl", "#0x200", check), ("mov", "x6, x30"),
                 ("stur", "x6, [x2, #7]")])[0] == "x2.field_0x8 = x30;"
    assert lift([("ldadd", "x0, x30, [x1]"),
                 ("stur", "x30, [x2, #7]")])[1] == "x2.field_0x8 = x30;"
    def lost(got):
        return _reads_frame(got, "x2.field_0x8")
    # A store over part of a slot, and a load of a part, or of more than a part filled.
    load = ("ldur", "x3, [x29, #-0xc]")
    got = lift([("stur", "x0, [x29, #-0xc]"), ("stur", "x1, [x29, #-8]"), load]
                + keep)
    assert lost(got), got
    load = ("ldur", "x3, [x29, #-8]")
    got = lift([("stur", "x0, [x29, #-8]"), ("sturb", "w1, [x29, #-8]"), load]
                + keep)
    assert lost(got), got
    got = lift([("stur", "x0, [x29, #-8]"), ("ldurb", "w3, [x29, #-8]")]
                + keep)
    assert lost(got), got
    assert lift([("stur", "w0, [x29, #-8]"), ("ldur", "w3, [x29, #-8]")]
                + keep)[0] == "x2.field_0x8 = x0;"           # as wide as it was stored
    # Nor does a trip's reload of a slot a byte store filled put back what was there:
    # the slot reads 5, and its 8 bytes are 0x1205.
    assert lift([("mov", "x0, #0x1234"), ("stur", "x0, [x29, #-8]"), ("mov", "x6, #5"),
                 ("strb", "w6, [x29, #-8]"), ("mov", "x19, #2"), "top",
                 ("cmp", "x19, #1"), ("b.eq", "@out"), ("bl", "#0x100"),
                 ("ldur", "x6, [x29, #-8]"), ("sub", "x19, x19, #1"),
                 ("tbz", "x19, #63, @top"), ("ret", ""), "out",
                 ("stur", "x6, [x2, #95]")])[-2] == "x2.field_0x60 = x6;"
    # q1 of a pair sits 16 bytes on, and 8 bytes into q0 is no slot, so the load names
    # the read rather than keeping d3 (#198).
    assert lift([("stp", "q0, q1, [x29, #-0x20]"), ("ldur", "d3, [x29, #-0x18]"),
                 ("stur", "d3, [x2, #7]")])[:2] == [
        "var t0 = (FP - 24).field_0x1;", "x2.field_0x8 = t0;"]
    # A write-back store lands off FP where it was, and FP is then 8 lower.
    assert lift([("str", "x0, [x29, #-8]!"), ("ldur", "x3, [x29, #-8]"), keep[0],
                 ("ldr", "x4, [x29]"), ("stur", "x4, [x2, #15]")])[:3] == [
        "var t0 = (FP - 8).field_0x1;", "x2.field_0x8 = t0;", "x2.field_0x10 = x0;"]
    # Stores `_step` leaves raw: off the frame, also in a loop, and to the heap a field,
    # or a slot holding one, was read from.
    got = lift([("stur", "x0, [x29, #-0x10]"), ("stnp", "x4, x5, [x29, #-0x10]"),
                 ("ldur", "x3, [x29, #-0x10]")] + keep)
    assert lost(got), got
    got = lift([("stur", "d0, [x29, #-0x20]")] + loop(("stnp", "x5, x6, [x29, #-0x20]"))
               + [("ldur", "d3, [x29, #-0x20]"), ("stur", "d3, [x2, #7]")])
    assert lost(got), got
    assert lift([("ldur", "x5, [x1, #7]"), ("stlr", "x0, [x16]"),
                 ("stur", "x5, [x2, #7]")])[:3] == [
        "var t0 = x1.field_0x8;", "stlr x0, [x16]", "x2.field_0x8 = t0;"]
    got = lift([("ldur", "x5, [x1, #7]"), ("stur", "x5, [x29, #-8]"),
                 ("stlr", "x0, [x16]"), load] + keep)
    assert lost(got), got
    # What a call takes off the stack, where a store broke the run of what was pushed:
    # one over half a slot, a raw one off the frame, one over a q register's top half.
    # Taken without them, the run reads as the whole list.
    assert lift([("stp", "x10, x9, [x15]"), ("bl", "#0x100")]) == [
        "return sub_0x100(x9, x10);"]
    assert lift([("stp", "x10, x9, [x15]"), ("str", "w12, [x15, #0xc]"),
                 ("bl", "#0x100")]) == ["return sub_0x100(...);"]
    assert lift([("str", "x9, [x15, #8]"), ("str", "x10, [x15]"),
                 ("stnp", "x4, x5, [x29, #-0x10]"), ("str", "x11, [x15]"),
                 ("bl", "#0x100")])[1] == "return sub_0x100(...);"
    regs = [("mov", f"{r}, #{n}") for n, r in enumerate(("x1", "x2", "x3", "x5",
                                                           "x6", "x7"), 1)]
    two = {"arity": lambda pc: StackArity(6, 2)}
    assert lift(regs + [("str", "q0, [x15, #-0x10]!"), ("str", "x9, [x15, #8]"),
                        ("bl", "#0x100")], **two) == ["return sub_0x100(...);"]
    # A q register pushed round a call is two of its 8-byte slots, and saved, not an
    # argument: `str q0; bl; ldr q0` round an allocation printed `f(q0)`.
    assert lift([("str", "q0, [x15, #-0x10]!"), ("bl", "#0x100"),
                 ("ldr", "q0, [x15], #0x10")]) == ["return sub_0x100(...);"]

    # Through SP over a slot kept off FP: the frame puts SP 16 below FP, so SP+8 is
    # FP-8. So is a push to FP-0x18, SP moved to FP-0x10 off FP, and a store below SP
    # once SP is aligned, which may be up to 15 lower. And through FP over an argument
    # pushed through SP, at SP+0. Each also in a loop, which drops the slot at its exit.
    over = [("stur", "x0, [x29, #-8]"), ("str", "x1, [x15, #8]"), load] + keep
    got = lift(frame(0x10, *over))
    assert lost(got), got
    got = lift(frame(0x10, over[0], ("str", "x1, [sp, #8]"), *over[2:]))
    assert lost(got), got   # SP by its other name
    assert lift(frame(0x20, *over))[0] == "x2.field_0x8 = x0;"    # SP+8 is FP-0x18
    got = lift(frame(0x10, ("stur", "x0, [x29, #-0x18]"), ("str", "x1, [x15, #-8]!"),
                      ("ldur", "x3, [x29, #-0x18]"), *keep))
    assert lost(got), got
    got = lift(frame(0x20, ("stur", "x0, [x29, #-8]"), ("sub", "x15, x29, #0x10"),
                      *over[1:]))
    assert lost(got), got
    got = lift(frame(0x10, ("stur", "x0, [x29, #-0x18]"),
                      ("and", "x15, x15, #0xfffffffffffffff0"), ("str", "x1, [x15]"),
                      ("ldur", "x3, [x29, #-0x18]"), *keep))
    assert lost(got), got
    got = lift(frame(0x10, ("stur", "d0, [x29, #-0x10]"), *loop(("str", "x5, [x15]")),
                     ("ldur", "d3, [x29, #-0x10]"), ("stur", "d3, [x2, #7]")))
    assert lost(got), got
    push = regs + [("str", "x9, [x15]"), ("stur", "x10, [x29, #-0x10]"), ("bl", "#0x100")]
    one = {"arity": lambda pc: StackArity(6, 1)}
    assert lift(frame(0x10, *push), **one)[0] == "return sub_0x100(...);"
    assert lift(frame(0x20, *push), **one)[0] == (
        "return sub_0x100(1, 2, 3, 4, 5, 6, x9);")
    # SP where the code that reaches a push leaves it: from code that took SP down, and
    # through the slow path strip_boilerplate cut off a box-or-tag check. The throw's own
    # edge is gone since #234, so the push is reached only by the branch, and what follows
    # the throw is placed as its own section rather than running into the join.
    saves = [("str", "x3, [x15, #-8]!"), ("bl", "#0x500"), ("ldr", "x3, [x15], #8")]
    for after in ((), (("mov", "x9, #0"),), (("sub", "x15, x15, #0x10"),)):
        # The call in `saves` declares what it left in x2 (#176), so the base is that
        # name; the slot reading x0 is what these cases are about, wherever the arm the
        # branch takes ends up printing it.
        body = lift(frame(0x20, ("stur", "x0, [x29, #-8]"), ("cbnz", "x4, @J"),
                          ("mov", "x15, x29"), ("bl", "#0x600", throw), *after,
                          "J", *saves, load, *keep))
        assert any(_stores(ln, "x0") for ln in body), (after, body)
    body = lift(frame(0x20, ("stur", "x0, [x29, #-8]"), ("cbz", "x4, @T"),
                      ("sbfiz", "x1, x0, #1, #0x1f"), ("cmp", "x0, x1, asr #1"),
                      ("b.eq", "@K"), ("cmp", "x5, x6"), ("b.ls", "@P"),
                      ("b", "@K"), "T", ("bl", "#0x600", throw), "P", *saves,
                      ("b", "@K"), "K", load, *keep))
    assert any(_stores(ln, "x0") for ln in body), body

    # A write-back store through FP is filed where FP is left, by the walk and by what
    # names a slot across a call alike, pre-index and post-index. SP's slots go when FP
    # moves, and SP loaded, through itself too, is not known.
    field = [("ldur", "x0, [x1, #7]")]
    # The call declares what it left in x2 between the name and the store, so the store's
    # base is that name and the result's number moves past it (#176).
    named = ["var t0 = x1.field_0x8;", "var t1;", "var t2 = sub_0x100(...);"]
    for rows in (field + [("str", "x0, [x29, #-8]!"), ("bl", "#0x100"),
                          ("ldr", "x3, [x29]")] + keep,
                 field + [("str", "x0, [x29], #8"), ("bl", "#0x100"),
                          ("ldur", "x3, [x29, #-8]")] + keep):
        got = lift(rows)
        assert got[:3] == named and _stores(got[3], "t0"), got
    got = lift(frame(0x20, ("str", "x0, [x29, #-0x10]!"), ("str", "x1, [x15, #0x10]"),
                      ("ldr", "x3, [x29], #0x10"), *keep))
    assert lost(got), got
    assert lift(frame(0x10, *regs, ("str", "x9, [x15]"), ("str", "x10, [x29, #-0x10]!"),
                      ("bl", "#0x100")), **one)[0] == "return sub_0x100(...);"
    got = lift(frame(0x20, ("stur", "x0, [x29, #-8]"), ("sub", "x16, x29, #8"),
                      ("str", "x16, [x15]"), ("ldr", "x15, [x15]"), ("str", "x1, [x15]"),
                      load, *keep))
    assert lost(got), got
    # A post-index store through SP lands where SP was, 8 above where it is.
    assert lift(regs + [("str", "x9, [x15], #-8"), ("bl", "#0x100")], **one)[0] == (
        "return sub_0x100(...);")
    # Round a loop: LR after its call; a slot a store covers part of; the outgoing area
    # a trip stores to, through SP or FP over it; a slot SP overwrites under a reload.
    out = lift([("mov", "x6, #0"), "top", ("stur", "x30, [x2, #7]"), ("bl", "#0x100"),
                ("cbnz", "x4, @top"), ("stur", "x30, [x2, #15]")])
    # The latch says the name the call declares for what it left in LR, where it said a
    # bare x30 that read as the LR the function was entered with (#176).
    assert "var t1 = LR;" in out, out
    m = re.search(r"\bt1 = (t\d+);", "\n".join(out))
    assert m and f"var {m.group(1)};" in out, out
    got = lift([("stur", "x0, [x29, #-8]"), "top", load, *keep,
                 ("sturb", "w1, [x29, #-5]"), ("cbnz", "x4, @top")])
    assert lost(got), got
    got = lift([("str", "x5, [x15]"), "top", ("ldr", "x3, [x15]"), *keep,
                 ("str", "x6, [x15]"), ("cbnz", "x4, @top")])
    assert lost(got), got
    got = lift(frame(0x10, ("str", "x5, [x15]"), "top", ("ldr", "x3, [x15]"), *keep,
                      ("stur", "x6, [x29, #-0x10]"), ("cbnz", "x4, @top")))
    assert lost(got), got
    assert lift(loop(("bl", "#0x100")) + [("mov", "x6, x30"),
                                          ("stur", "x6, [x2, #7]")])[-2] == (
        "x2.field_0x8 = x30;")                          # LR after a loop that calls
    # The call's own number moves: it declares each clobbered register it left live
    # first (#176), so match the shape rather than the number.
    assert any(re.fullmatch(r"var t\d+ = sub_0x200\(\.\.\.\);", ln) for ln in lift(
        frame(0x10, *regs, ("str", "x9, [x15]"), "top", ("bl", "#0x200"),
              ("stur", "x10, [x29, #-0x10]"), ("cbnz", "x20, @top")), **one))
    assert lift(frame(0x10, ("mov", "x6, #5"), ("stur", "x6, [x29, #-8]"),
                      "top", ("cbz", "x9, @out"), ("bl", "#0x200"),
                      ("str", "x7, [x15, #8]"), ("ldur", "x6, [x29, #-8]"),
                      ("cbnz", "x4, @top"), ("ret", ""), "out",
                      ("stur", "x6, [x2, #7]")))[-2] == "x2.field_0x8 = x6;"
    # A slot that starts below a push and ends in it; and what a call takes off the stack
    # before a loop, which a call in the loop takes, as `_drop_outgoing` has it.
    got = lift(frame(0x10, ("stur", "x0, [x29, #-0x14]"), ("str", "x1, [x15]"),
                      ("ldur", "x3, [x29, #-0x14]"), *keep))
    assert lost(got), got
    assert any(re.fullmatch(r"var t\d+ = sub_0x200\(\.\.\.\);", ln) for ln in lift(
        regs + [("str", "x9, [x15]"), "top", ("bl", "#0x200"),
                ("cbnz", "x20, @top")], **one))
    # A block the entry does not reach, that loses SP, says nothing of one it does.
    # Not by index: the call in `saves` declares what it left in x2 ahead of the store
    # (#176). The slot still reads x0, which is what this case is about.
    assert any(_stores(ln, "x0") for ln in lift(
        frame(0x20, ("stur", "x0, [x29, #-8]"), "J", *saves, load, *keep,
              ("ret", ""), ("mov", "x15, x0"), ("b", "@J"))))

    # The frame an FFI call builds for C ends where it began: what its calls push
    # meets no slot. Where SP is not known at a push, the push may meet any.
    from jadart.cfg import build_cfg
    from jadart.expr import strip_boilerplate

    def meets(rows):
        ann = [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows + [("ret", "")])]
        stripped = strip_boilerplate(ann)
        blocks, entry = build_cfg(stripped, traps=())
        return _frame_meets(blocks, entry, {a[0]: a[1:3] for a, s in zip(ann, stripped)
                                            if s[1:3] != a[1:3]})
    ffi = [("stur", "x0, [x29, #-8]"), ("str", "x29, [x15, #-8]!"), ("mov", "x29, x15"),
           ("sub", "x15, x15, #0x10"), ("and", "x15, x15, #0xfffffffffffffff0"),
           ("str", "x1, [x15]"), ("blr", "x9"), ("mov", "x15, x29"),
           ("ldr", "x29, [x15], #8"), ("str", "x2, [x15]"), ("ldur", "x3, [x29, #-8]")]
    assert meets(frame(0x10, *ffi)) == frozenset()
    # The two pushes, and the store through FP the second one may have been under.
    assert meets(frame(0x10, *ffi[:2], ("mov", "x15, x0"), *ffi[5:])) == {
        0xc, 0x18, 0x28}


def test_a_frame_written_out_of_sight_or_read_back_extended_reads_as_it_is():
    # What the review of #162 left (#165). A frame register moved where the walk did not
    # see it, a store went through a frame address held in a register, and a load that
    # extends read the stored text as it was: each printed a slot the machine no longer
    # holds, or holds as another value.
    from jadart.expr import lift_function

    def lift(rows, **kw):
        # A string row is a label, and `@name` in the operands is its address.
        rows = rows + [("ret", "")]
        at, n = {}, 0
        for r in rows:
            if isinstance(r, str):
                at[r] = n * 4
            else:
                n += 1
        ann = []
        for r in (r for r in rows if not isinstance(r, str)):
            op = r[1]
            for name, a in at.items():
                op = op.replace("@" + name, "#%#x" % a)
            ann.append((len(ann) * 4, r[0], op, r[2] if len(r) > 2 else ""))
        return [ln.strip() for ln in lift_function(ann, **kw)]

    def frame(size, *rows):
        return [("stp", "x29, x30, [x15, #-0x10]!"), ("mov", "x29, x15"),
                ("sub", "x15, x15, #%#x" % size)] + list(rows)

    def loop(*inside):
        return [("mov", "x9, #3"), "top", *inside, ("sub", "x9, x9, #1"),
                ("cbnz", "x9, @top")]
    keep = [("stur", "x3, [x2, #7]")]
    spill, load = ("stur", "x0, [x29, #-8]"), ("ldur", "x3, [x29, #-8]")
    held = "x2.field_0x8 = x0;"

    def lost(got):
        return _reads_frame(got, "x2.field_0x8")

    def gone_at(text):
        """A slot the walk LOST, which now says the read it is instead of keeping the
        load's own register. The register read as the value the function came in with, so
        every one of these cases printed a wrong value rather than a lost one (#198). The
        address is the one the moved frame register points at where the load is."""
        return [f"var t0 = {text};", "x2.field_0x8 = t0;"]

    # 1. FP moved by a move strip_boilerplate blanks, by arithmetic, and by a load into
    # it; SP by a blanked `sub` or `add`, an `and`, and a load through itself.
    assert lift([spill, ("mov", "x29, x15"), load] + keep)[:2] == gone_at(
        "(FP - 8).field_0x1")
    assert lift(frame(0x20, spill, ("mov", "x29, x15"), load, *keep))[:2] == gone_at(
        "(FP - 40).field_0x1")
    # x29 here is the pointer the `ldr` just put in it, not the frame, so the read is off
    # that value as through any other register, and claims no slot (#307).
    assert lift(frame(0x20, spill, ("ldr", "x29, [x1]"), load, *keep))[:2] == [
        "x2.field_0x8 = (x1.field_0x1 - 8).field_0x1;", "return x0;"]
    # FP moved by an amount known reads its slots where they now are.
    assert lift(frame(0x20, spill, ("add", "x29, x29, #8"), load, *keep))[:2] == gone_at(
        "FP.field_0x1")
    assert lift(frame(0x20, spill, ("add", "x29, x29, #8"), ("ldur", "x3, [x29, #-0x10]"),
                      *keep))[0] == held
    push, top = ("str", "x0, [x15, #8]"), ("ldr", "x3, [x15, #8]")
    # Each of these three used to print `SP.field_0x9`, one text for three addresses,
    # which is what made the spelling name nothing. Anchored to the frame the function was
    # entered with, each says where it really is: the frame is 0x20, so SP sits at FP - 32
    # before the move, and a read 8 above SP follows SP. The alignment is the one that
    # cannot be said, because it leaves SP known only to within 15 bytes (#207).
    for move, want in ((("sub", "x15, x15, #8"), "(FP - 32).field_0x1"),
                       (("add", "x15, x15, #8"), "(FP - 16).field_0x1"),
                       (("and", "x15, x15, #0xfffffffffffffff0"), "SP.field_0x9")):
        assert lift(frame(0x20, push, move, top, *keep))[:2] == gone_at(want), move
    # A load INTO SP is a declined reload of its own, and its name goes unread, so
    # `_drop_unread` takes that line and the slot read keeps the number after it.
    got = lift(frame(0x20, push, ("ldr", "x15, [x15]"), top, *keep))
    assert lost(got) and not any("SP.field_0x1;" in l for l in got), got
    # Dropped rather than moved with SP, so this is a fresh read; the address is the
    # pushed slot's own, which SP - 8 plus 0x10 comes back to, and it now says so (#207).
    assert lift(frame(0x20, push, ("sub", "x15, x15, #8"), ("ldr", "x3, [x15, #0x10]"),
                      *keep))[:2] == gone_at("(FP - 24).field_0x1")
    # An FFI call's frame and a leaf call's put FP back where it was: a slot kept from
    # before reads the same after, an access through the moved FP is to where it points,
    # and a store through it changes the slot it lands in.
    ffi = [("str", "x29, [x15, #-8]!"), ("mov", "x29, x15"),
           ("and", "x15, x15, #0xfffffffffffffff0")]
    out = [("blr", "x9"), ("mov", "x15, x29"), ("ldr", "x29, [x15], #8")]
    leaf = [("stp", "x29, x30, [x15, #-0x10]!"), ("mov", "x29, x15"),
            ("and", "x15, x15, #0xfffffffffffffff0")]
    back = [("blr", "x10"), ("mov", "x15, x29"), ("ldp", "x29, x30, [x15], #0x10")]
    field = [("ldur", "x0, [x1, #7]"), spill]
    for enter, leave, up in ((ffi, out, 0x20), (leaf, back, 0x28)):
        got = lift(frame(0x20, *field, *enter, *leave, load, *keep))
        # Not by index: the FFI epilogue's `ldr x29, [x15], #8` is a declined reload of
        # its own and is named, which the leaf one's `ldp` is not because neither
        # register it loads is read again.
        # The store's base is the name the call declares for x2, which it clobbers like
        # any other volatile register (#176); the slot read is what this case is about.
        assert got[0] == "var t0 = x1.field_0x8;", got
        assert any(re.fullmatch(r"t\d+\.field_0x8 = t0;", ln) for ln in got), got
        got = lift(frame(0x20, spill, *enter, ("ldur", "x3, [x29, #%#x]" % up), *keep,
                         *leave))
        assert got[0] == held, got                        # FP-8 through the moved FP
        got = lift(frame(0x20, spill, *enter, ("stur", "x5, [x29, #%#x]" % up), *leave,
                         load, *keep))
        assert _stores(got[-2], "x5"), got
    # A cell the push starts an FFI call's frame with and a leaf call's store into its
    # own frame use at different times, and cost no slot (`__constructor`).
    got = lift(frame(0x20, *field, *ffi, *out, *leaf, ("str", "x10, [x29, #8]"), *back,
                     load, *keep))
    assert _stores(got[-2], "t0"), got                 # and this
    # Where paths meet with FP in different places, the slots go.
    got = lift(frame(0x20, spill, ("cbz", "x4, @J"), *ffi[:2], "J", load, *keep))
    assert lost(got), got
    # A loop whose trip moves FP, or SP, where the walk does not see it starts with
    # neither's slots: on the second trip they are somewhere else.
    for rows in (frame(0x20, spill, *loop(load, *keep, ("mov", "x29, x15"))),
                 frame(0x20, push, *loop(top, *keep, ("sub", "x15, x15, #8")))):
        got = lift(rows)
        assert lost(got), got

    # 2. A store through a register that may hold a frame address: off FP or SP, through
    # a copy of one, and from one arm of a join, raw stores among them. Not one through
    # a register written since by a load or a call, which gives it a value of its own.
    sub = ("sub", "x16, x29, #8")
    got = lift(frame(0x20, spill, sub, ("str", "x1, [x16]"), load, *keep))
    assert lost(got), got
    got = lift(frame(0x20, push, ("add", "x16, x15, #8"), ("str", "x1, [x16]"), top,
                     *keep))
    assert lost(got), got
    got = lift(frame(0x20, spill, ("mov", "x17, x29"), ("mov", "x16, x17"),
                     ("stur", "x1, [x16, #-8]"), load, *keep))
    assert lost(got), got
    got = lift(frame(0x20, spill, ("cbz", "x4, @L"), sub, "L", ("str", "x1, [x16]"),
                     load, *keep))
    assert lost(got), got
    got = lift(frame(0x20, spill, sub, ("stlr", "x4, [x16]"), load, *keep))
    assert lost(got), got
    assert lift(frame(0x20, spill, sub, ("ldur", "x16, [x1, #7]"), ("str", "x4, [x16]"),
                      load, *keep))[1] == held            # guard: passes on main
    # Not by index: the call declares what it left in x9 and in x2, so the raw store and
    # the slot read both move down the body (#176). The slot still reads x0.
    assert _stores(lift(frame(0x20, spill, ("sub", "x9, x29, #8"), ("bl", "#0x400"),
                              ("str", "x4, [x9]"), load, *keep))[-2], "x0")  # and this
    got = lift(frame(0x20, spill, ("sub", "x19, x29, #8"), ("bl", "#0x400"),
                     ("str", "x4, [x19]"), load, *keep))
    assert lost(got), got
    # In a loop, the slot it may write, and the outgoing area, go at the top.
    for rows in (frame(0x20, spill, sub, *loop(load, *keep, ("str", "x9, [x16]"))),
                 frame(0x20, push, ("add", "x16, x15, #8"),
                       *loop(top, *keep, ("str", "x9, [x16]")))):
        got = lift(rows)
        assert lost(got), got

    # 3. A load that extends reads the slot as `sxtw` and `uxth` print it, and one into
    # the other register file reads none: it is `fmov`'s reinterpretation.
    for st, ld, want in (("stur w0", "ldursw x3", "x0 << 32 >> 32"),
                         ("sturh w0", "ldursh x3", "x0 << 48 >> 48"),
                         # Into a w register the extension stops at 32 bits (#374).
                         ("sturb w0", "ldursb w3", "(x0 << 56 >> 56).toUnsigned(32)"),
                         ("sturh w0", "ldurh w3", "x0 & 0xffff"),
                         ("sturb w0", "ldurb w3", "x0 & 0xff"),
                         ("stur w0", "ldur w3", "x0")):        # as `mov w3, w0`: guard
        got = lift([(st.split()[0], st.split()[1] + ", [x29, #-8]"),
                    (ld.split()[0], ld.split()[1] + ", [x29, #-8]")] + keep)
        assert got[0] == "x2.field_0x8 = %s;" % want, (st, ld, got)
    assert lift([("stp", "w0, w1, [x29, #-8]"), ("ldpsw", "x3, x4, [x29, #-8]"),
                 ("stur", "x4, [x2, #7]")])[0] == "x2.field_0x8 = x1 << 32 >> 32;"
    assert lift([("and", "x0, x1, #0xff"), ("sturb", "w0, [x29, #-8]"),
                 ("ldurb", "w3, [x29, #-8]")] + keep)[0] == (
        "x2.field_0x8 = x1 & 255;")                       # it fits: passes on main
    # A reinterpretation reads no slot, so it names the read: `d3` read as the double the
    # function came in with, and the name reads as the bits that are there (#198).
    assert lift([spill, ("ldur", "d3, [x29, #-8]"), ("fadd", "d4, d3, d3"),
                 ("stur", "d4, [x2, #7]")])[:2] == [
        "var t0 = (FP - 8).field_0x1;", "x2.field_0x8 = t0 + t0;"]
    got = lift([("fadd", "d0, d1, d2"), ("stur", "d0, [x29, #-8]"), load] + keep)
    assert lost(got), got
    assert lift([("fadd", "d0, d1, d2"), ("stur", "d0, [x29, #-8]"),
                 ("ldur", "d3, [x29, #-8]"), ("stur", "d3, [x2, #7]")])[0] == (
        "x2.field_0x8 = d1 + d2;")                        # guard: passes on main


def test_a_break_out_of_two_loops_writes_both_loops_names_back():
    """A break that leaves more than one loop makes every loop it leaves carry the
    register, not just the innermost (#176, from #123).

    The shape is #176's own: two loops, and two conditional exits out of the inner one
    that the structurer turns into breaks out of both. x7 is written before the loops by
    an instruction the lifter models and does not print, and again inside the inner loop
    by a raw line. On the path that breaks before the raw line the machine holds the
    first value, and the store after both loops printed a bare `x7`, which under the
    printed body rule reads as the value the function came in with.

    The hazard WAS recorded, against the inner loop, and the inner loop named it; the
    outer loop had still forgotten the register, so the code after both read it bare, the
    name had no reader, and `_lift_function` dropped the carry and walked again without
    it. Recording the hazard against every loop the break leaves is what makes the second
    walk's fix stick.
    """
    from jadart.expr import lift_function

    rows = [("add", "x7, x5, x1"), ("mov", "x9, #2"), ("mov", "x10, #3"),
            ("cbz", "x3, #0x34"), ("umulh", "x7, x6, x1"), ("cbz", "x4, #0x34"),
            ("sub", "x10, x10, #1"), ("cbnz", "x10, #0xc"),
            ("sub", "x9, x9, #1"), ("cbnz", "x9, #0x8"), ("ret", ""), ("ret", ""),
            ("ret", ""), ("stur", "x7, [x2, #95]"), ("ret", "")]
    got = [ln.strip() for ln in lift_function(
        [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])]
    # The unprinted write is named before the loops, and the store reads that name and
    # not the register. Which name it is depends on the numbering, so the test reads the
    # store line and checks what it names.
    store = next(ln for ln in got if ln.startswith("x2.field_0x60 = "))
    named = store[len("x2.field_0x60 = "):-1]
    assert re.fullmatch(r"t\d+", named), store
    assert f"var {named} = x5 + x1;" in got, got
    # The inner loop assigns it from x7 on each way out, after the raw line that wrote
    # x7, and the outer loop carries it on to the store.
    assert sum(1 for ln in got if re.fullmatch(r"t\d+ = x7;", ln)) >= 2, got
    assert f"{named} = t" in "\n".join(got), got


def test_a_goto_out_of_nested_loops_names_what_the_join_reads():
    # A goto out of an inner loop to a block the outer loop also leaves to is a join the
    # structured walk never met: `_join_kill` dropped the register to its bare name, which
    # reads as the last printed line put it. `umulh x7` prints inside the loop and `add
    # x7, x5, x1` before it, so the store at the join read the `umulh` where the CPU, when
    # it leaves on the first inner trip, has `x5 + x1`. On main this prints `x2.field_0x1
    # = x7;`. A loop inside another was left open by #156; this is the join half (#123).
    from jadart.expr import lift_function
    rows = [("add", "x7, x5, x1"), ("mov", "x9, #2"), ("mov", "x10, #3"),
            ("cbz", "x3, #0x28"), ("umulh", "x7, x6, x1"), ("sub", "x10, x10, #1"),
            ("cbnz", "x10, #0xc"), ("sub", "x9, x9, #1"), ("cbnz", "x9, #0x8"),
            ("nop", ""), ("str", "x7, [x2]"), ("ret", "")]
    body = [ln.strip() for ln in lift_function(
        [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])]
    store = next(ln for ln in body if ln.startswith("x2.field_0x1 ="))
    # The value carried out of the loops is bound before them and read at the join.
    assert "var t0 = x5 + x1;" in body, body
    name = store[len("x2.field_0x1 = "):].rstrip(";")
    assert re.fullmatch(r"t\d+", name), body          # a phi name, not the bare `x7`
    # It is written on every edge into the join: the goto out and the loops' own exit.
    assert sum(1 for ln in body if re.match(rf"{name} = ", ln)) >= 2, body


def test_a_loop_falls_out_to_a_block_some_run_can_enter():
    # A natural loop is the header plus the blocks IT DOMINATES that reach a latch without
    # passing it, and `loop_nodes` asked only the reaching half. A block no path from the
    # entry reaches is dominated by nothing, so it answers that half and no more, and the
    # backward walk from the latch took 0xc in. `loop_exit` counts each edge out of the
    # node set as a vote for where it goes, the three votes tie at one apiece, and the
    # lowest address wins, so 0x10 was printed as the block the loop falls out to: a path
    # no run takes, whose `add x2, x9, #0x1b` then supplied the value the join at 0x30
    # reads. On main this returns `x9 + 27 | x11` (#237).
    #
    # Found by `tools/irfuzz.py --cfg --nested` on two seeds the suite does not use, 2 in
    # about 36,000 generated graphs, both this shape. The lifter's `_back_loop` keeps such
    # a predecessor deliberately, because there the question is what the loop MAY write
    # and a handler with no edge in has to count; where the loop GOES is a claim.
    from jadart.cfg import build_cfg, structure
    from jadart.expr import lift_function
    rows = [("sub", "x7, x7, x7"), ("add", "x7, x7, #3"), ("b", "#0x18"),
            ("cbnz", "x9, #0x20"), ("add", "x2, x9, #0x1b"), ("b", "#0x30"),
            ("mul", "x5, x6, x12"), ("cbz", "x8, #0x2c"),
            ("sub", "x7, x7, #1"), ("cbnz", "x7, #0x18"), ("b", "#0x30"),
            ("mul", "x1, x5, x3"), ("orr", "x0, x2, x11"), ("ret", "")]
    ann = [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)]
    blocks, entry = build_cfg(ann)
    assert not [a for a in blocks if 0xc in blocks[a].succ], "0xc must have no way in"
    stmts = structure(blocks, entry)
    at = next(i for i, st in enumerate(stmts) if st[0] == "loop")
    nxt = next(st for st in stmts[at + 1:] if st[0] in ("asm", "label"))
    assert nxt[1] == 0x28, (
        f"the loop falls out to 0x{nxt[1]:x}, which no run can enter; 0x28 is the way "
        f"out its own blocks take")
    lines = lift_function(ann, arch="arm64")
    # The body, above the section 0xc is placed in after it (#266). That section prints
    # the return it reaches again, from its own state, and `x9 + 27` is right there.
    from jadart.cfg import UNREACHED
    note = "  // " + UNREACHED
    body = "\n".join(lines[:lines.index(note)] if note in lines else lines)
    assert "x9 + 27" not in body, (
        f"the join reads a value only the unreachable block computes\n{body}")
    assert "return x2 | x11;" in body, body


def _flat_stmts(stmts, out=None):
    """Every statement in a structured list, nesting flattened, for a membership test."""
    out = [] if out is None else out
    for st in stmts:
        out.append(st)
        if st[0] == "if":
            _flat_stmts(st[2], out)
            _flat_stmts(st[3], out)
        elif st[0] == "loop":
            _flat_stmts(st[2], out)
    return out


def test_the_section_after_a_trap_does_not_feed_the_join_below_it():
    # `structure` places the code after a trap, or after a call that cannot return, as its
    # own section (#57, #234), because an exception edge the CFG does not model may reach
    # it. That section FALLS THROUGH into the block below it, and `_reenter` stated the
    # rule for a section that does not fall through only, so what the walk was carrying
    # out of it reached a block with other ways in: `add x2, x9, #0x1b` at 0x8 flowed into
    # the join at 0xc, whose other way in is the `goto` out of the loop, and `return x9 +
    # 27 | x11;` came out of a value that way in never computes (#237).
    #
    # The goto-join's own meet (`_join_kill`) is what exists to stop that, and it cannot
    # see this one: the narrowing it makes from the join's immediate dominator can never
    # hold a block no path from the entry reaches. The guard is `_reenter` asked on
    # arrival. The section is still placed either way, which is the point: Ghidra and
    # Hex-Rays answer this by deleting the block, and a catch entry is one of these.
    from jadart.cfg import build_cfg, structure
    from jadart.expr import lift_function
    rows = [("cbz", "x1, #0x14"), ("brk", "#0"), ("add", "x2, x9, #0x1b"),
            ("orr", "x0, x2, x11"), ("ret", ""),
            ("mul", "x5, x6, x12"), ("cbz", "x8, #0xc"), ("cbz", "x9, #0x28"),
            ("sub", "x7, x7, #1"), ("cbnz", "x7, #0x14"),
            ("add", "x4, x4, #2"), ("ret", "")]
    ann = [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)]
    blocks, entry = build_cfg(ann)
    assert not [a for a in blocks if 0x8 in blocks[a].succ], "0x8 must have no way in"
    assert sorted(a for a in blocks if 0xc in blocks[a].succ) == [0x8, 0x14]
    assert ("goto", 0xc) in _flat_stmts(structure(blocks, entry)), (
        "the join has to be one a goto reaches, or this tests nothing")
    body = "\n".join(lift_function(ann, arch="arm64"))
    assert "x9 + 27" not in body, (
        f"the join reads what the section above it wrote, on a path that never ran\n"
        f"{body}")
    assert "return x2 | x11;" in body, body
    assert "L_0x8:" in body, f"the section itself still has to be placed\n{body}"


def test_a_join_inside_a_section_nothing_reaches_keeps_what_both_its_paths_agree_on():
    # The other half of the question above, and the first fix for it got this wrong. A
    # region nothing reaches is still a region: its own flow is the only flow there is,
    # so a join INSIDE one, whose every way in is inside it too, has nothing to meet with.
    # Asking only whether the arriving state came out of such a region wiped the join at
    # 0x20 here, where both paths carry `x2 = x9 + 27` and the store printed it; the
    # output then read `x8.field_0x1 = x2;`, a bare register no line of the body binds,
    # for a value it had. So the guard asks for a predecessor the entry CAN reach, the one
    # the arriving state cannot speak for (#237).
    from jadart.cfg import build_cfg
    from jadart.expr import lift_function
    rows = [("cbz", "x1, #0x28"), ("brk", "#0"), ("add", "x2, x9, #0x1b"),
            ("cbz", "x3, #0x1c"), ("str", "x4, [x7]"), ("b", "#0x20"),
            ("nop", ""), ("str", "x5, [x7]"), ("str", "x2, [x8]"), ("ret", ""),
            ("str", "x6, [x9]"), ("ret", "")]
    ann = [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)]
    blocks, _entry = build_cfg(ann)
    reach = {0x0, 0x4, 0x28}
    assert not [a for a in blocks if 0x8 in blocks[a].succ], "0x8 must have no way in"
    assert not [p for p in (0x10, 0x1c) if p in reach], "the join's ways in are both in"
    body = "\n".join(lift_function(ann, arch="arm64"))
    assert "x8.field_0x1 = x9 + 27;" in body, (
        f"both ways into the join carry x9 + 27, so the store has it\n{body}")


def test_a_loop_the_walk_re_enters_keeps_the_names_it_carries():
    # Third shape of #237, and the one the first guard broke. `_reenter` replaced the
    # register map and left `State.src` naming the block it had just disowned, and the
    # guard reads `src` on a LIVE arrival, so where a section nothing reaches falls into a
    # reachable loop HEADER the guard fired twice: once at the loop, rightly, and again at
    # the header's own block inside `_render_loop`, after the loop had bound its carried
    # registers to names. The second firing reset the map and took those names with it:
    # the counter's declaration and both of its write-backs left the output, so the
    # printed loop updated nothing and `sub x7, x7, #1` was nowhere in it. A loop that
    # cannot advance is a wrong answer, not a vague one.
    #
    # `_reenter` hands the state to the block it is entering now, and the call site makes
    # the same exclusion the goto-join meet makes four lines below it, for the same
    # reason. The shape: a trap at 0x4, the section after it at 0x8, and the header at
    # 0xc reachable only by the escape `goto` out of the loop whose header is 0x20.
    import re
    from jadart.cfg import build_cfg
    from jadart.expr import lift_function
    rows = [("cbz", "x1, #0x20"), ("brk", "#0"), ("add", "x2, x9, #0x1b"),
            ("mul", "x3, x9, x9"), ("sub", "x7, x7, #1"), ("cbnz", "x7, #0xc"),
            ("orr", "x0, x3, x11"), ("ret", ""),
            ("mul", "x5, x6, x12"), ("cbz", "x8, #0xc"), ("cbz", "x9, #0x3c"),
            ("cbz", "x10, #0x3c"), ("sub", "x6, x6, #1"), ("cbnz", "x6, #0x20"),
            ("ret", ""), ("add", "x4, x4, #2"), ("ret", "")]
    ann = [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)]
    blocks, _entry = build_cfg(ann)
    assert not [a for a in blocks if 0x8 in blocks[a].succ], "0x8 must have no way in"
    assert 0x20 in [a for a in blocks if 0xc in blocks[a].succ], (
        "0xc has to be reachable, by the escape out of the other loop")
    body = "\n".join(lift_function(ann, arch="arm64"))
    name = re.search(r"var (t\d+) = x7;", body)
    assert name, f"the loop carries x7 and nothing binds it\n{body}"
    held = name.group(1)
    assert f"({held} - 1) == 0" in body, (
        f"the loop tests the register, not the name it carries\n{body}")
    assert body.count(f"{held} -= 1;") >= 2, (
        f"the trip's update is missing, so the printed loop cannot advance\n{body}")


def test_a_join_a_section_falls_into_still_binds_its_phi_name():
    # The arrival guard of #237 replaces the state of a block a section nothing reaches
    # falls into. `_join_write` runs right after it, on the same fall-through, and records
    # WHICH EDGE wrote the join's phi name; the join binds the register to that name only
    # where every way in wrote it. `_reenter` had put the join's own address in
    # `State.src` by then, so the record named the join and not the edge, no set of edges
    # could
    # ever cover the predecessors, and the join dropped to the bare machine register: #123
    # again, by another road.
    #
    # Here the loop writes x2 on both arms and prints it on one (`clz x2, x9` is a raw
    # line); the join at 0xc reads it. With the record right, the join reads a name every
    # edge binds, and the section's own edge binds it to the bare register, since that
    # value is the one no way in justifies. With the record wrong it read `x2`, which on
    # the `x10 == 0` path is the value the function came in with and not the `x9 + 1` the
    # machine has.
    import re
    from jadart.cfg import build_cfg
    from jadart.expr import lift_function
    rows = [("cbz", "xzr, #0x14"), ("brk", "#0"), ("add", "x2, x9, #0x1b"),
            ("orr", "x0, x2, x11"), ("ret", ""),
            ("cbz", "x10, #0x20"), ("clz", "x2, x9"), ("b", "#0x24"),
            ("add", "x2, x9, #1"),
            ("cbz", "x8, #0xc"), ("cbz", "x12, #0x34"),
            ("sub", "x7, x7, #1"), ("cbnz", "x7, #0x14"),
            ("add", "x4, x4, #2"), ("ret", "")]
    ann = [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)]
    blocks, _entry = build_cfg(ann)
    assert not [a for a in blocks if 0x8 in blocks[a].succ], "0x8 must have no way in"
    assert len([a for a in blocks if 0xc in blocks[a].succ]) > 1, "0xc has to be a join"
    body = "\n".join(lift_function(ann, arch="arm64"))
    ret = re.search(r"return (\S+) \| x11;", body)
    assert ret, f"no return rendered\n{body}"
    name = ret.group(1)
    assert re.fullmatch(r"t\d+", name), (
        f"the join returns `{name}`, which only one arm of the loop prints a write to"
        f"\n{body}")
    assert sum(1 for ln in body.split("\n")
               if re.match(rf"\s*{name} = ", ln)) >= 2, (
        f"`{name}` has to be written on every way into the join\n{body}")


def test_a_flag_setting_alu_op_prints_the_value_it_wrote():
    # The flags and the value are two definitions of one instruction, and only the flags
    # were modelled: `subs x0, x1, x2` printed as arm64 where `sub x0, x1, x2` prints
    # `x1 - x2`, and the register it wrote read as nothing. 262 raw lines on the clean
    # fixture, the only difference being the flag suffix (#239).
    #
    # Every other tool splits the two. Ghidra translates one instruction to a sequence of
    # p-code operations each writing at most one varnode; Binary Ninja lifts the value as
    # the ordinary definition and puts the flag IL beside it; LLVM's `SUBSWrr` writes its
    # GPR and carries `implicit-def $nzcv`. So the value comes from the plain twin.
    from jadart.expr import lift_function
    rows = lambda rs: [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rs)]

    def one(mn, op):
        return [ln.strip() for ln in lift_function(rows([(mn, op), ("ret", "")]),
                                                   arch="arm64")]
    for mn, want in (("subs", "return x1 - x2;"), ("adds", "return x1 + x2;"),
                     ("ands", "return x1 & x2;"), ("bics", "return x1 & ~x2;")):
        assert one(mn, "x0, x1, x2") == [want], (mn, one(mn, "x0, x1, x2"))
    assert one("negs", "x0, x1") == ["return -x1;"], one("negs", "x0, x1")
    # Writing the zero register is what `cmp` is, and `State.set` drops it, so there is
    # no value to print and the entry x0 is what the return reads.
    assert one("subs", "xzr, x1, x2") == ["return x0;"], one("subs", "xzr, x1, x2")
    # The flags still hold the comparison: the condition AND the value, from one line.
    body = [ln.strip() for ln in lift_function(
        rows([("subs", "x3, x1, x2"), ("b.eq", "#0x10"), ("mov", "x0, x3"), ("ret", ""),
              ("mov", "x0, xzr"), ("ret", "")]), arch="arm64")]
    assert "if (x1 != x2) {" in body, body
    assert "return x1 - x2;" in body, body


def test_a_select_reads_a_comparison_from_the_one_block_that_reaches_it():
    # `_flag_cond` declined wherever the flags were set in another block, which was 102
    # of its 106 declines on the clean fixture, and 78 `csel` lines printed as arm64 while
    # the same select beside its own `cmp` rendered exactly (#239).
    #
    # The other tools keep the fact in state rather than per block: VEX holds the last
    # flag-setting op and its operands in guest state and computes the condition where it
    # is READ, so it crosses an edge like any value. `self._flags` already is such a
    # thunk, so what was missing is the edge, and it is taken only where the block has
    # ONE way in, which is the only case with nothing to meet.
    from jadart.cfg import build_cfg
    from jadart.expr import lift_function
    rows = lambda rs: [(0x1000 + i * 4, mn, op, "") for i, (mn, op) in enumerate(rs)]

    def body(rs):
        return [ln.strip() for ln in lift_function(rows(rs), {}, arch="arm64")]

    # one way in, over an unconditional branch: the predicate is known exactly
    assert body([("cmp", "x1, x2"), ("b", "#0x1008"),
                 ("csel", "x0, x1, x2, lt"), ("ret", "")]) == [
        "return x1 < x2 ? x1 : x2;"]
    # and over a conditional one, where the condition is spelled from it as well
    out = body([("cmp", "x1, x2"), ("b.eq", "#0x1010"), ("csel", "x0, x1, x2, lt"),
                ("ret", ""), ("mov", "x0, xzr"), ("ret", "")])
    assert "if (x1 != x2) {" in out and "return x1 < x2 ? x1 : x2;" in out, out
    # TWO ways in and it stays raw: the select would have to meet two comparisons, and
    # `_flag_cond`'s bar is that the predicate is known exactly.
    two = [("cmp", "x1, x2"), ("b.eq", "#0x100c"), ("cmp", "x3, x4"),
           ("csel", "x0, x1, x2, lt"), ("ret", "")]
    blocks, _e = build_cfg(rows(two))
    assert len([a for a in blocks if 0x100c in blocks[a].succ]) == 2
    assert any(ln.startswith("csel ") for ln in body(two)), body(two)
    # A comparison that overwrote an operand it compared is declined rather than re-read:
    # the arriving state has the NEW x1, and only the text the predecessor captured has
    # the old one (#116).
    assert any(ln.startswith("csel ") for ln in body(
        [("subs", "x1, x1, #8"), ("b", "#0x1008"), ("csel", "x0, x3, x4, ne", ),
         ("ret", "")])), "a comparison that overwrote its own operand must decline"
    # one it did not overwrite is read across the edge
    assert body([("subs", "x5, x1, x2"), ("b", "#0x1008"),
                 ("csel", "x0, x3, x4, ne"), ("ret", "")]) == [
        "return x1 != x2 ? x3 : x4;"]


def test_the_generated_corpus_can_draw_a_flag_setting_alu_op():
    # The gate for the value above, and the reason it had to be built: a flag-setting op
    # sits next to the branch that reads it, and a branch ends a straight-line run, so
    # `expr_cases` draws 5 runs containing one out of 6,623 over the whole clean fixture
    # and the default sweep reaches none of them. Nothing in this repo could see the
    # class, which is what #235 says is the real defect.
    #
    # Its own pool, drawn under `--flags`, because every named case in this suite is a
    # (seed, index) coordinate into a generator stream and widening the shared pool moves
    # all of them (#230).
    #
    # The encoding half needs capstone to decode what it claims, so it skips without it,
    # the way every other test that reaches a disassembler here does. The pool itself is
    # checked either way, since the tables and the generator are stdlib only.
    sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "tools"))
    import irfuzz
    import random
    if _capstone_available():
        assert not irfuzz.verify_fuzz_encodings(), "a claimed text does not decode"
    flagged = {t.split()[0] for t, _enc in irfuzz._FUZZ_FLAG_ALU + irfuzz._FUZZ_FLAG_IMM}
    assert flagged == {"adds", "subs", "ands", "bics"}, flagged
    assert flagged <= irfuzz._PURE, "the oracle has to treat them as value-preserving"
    plain = {t.split()[0] for t, _enc in irfuzz._FUZZ_ALU + irfuzz._FUZZ_IMM}
    assert not (plain & flagged), "the shared pool must not move: named cases index it"
    # and the graphs really contain them when asked, and really do not when not
    for flags, want in ((True, True), (False, False)):
        seen = set()
        for i in range(60):
            words = irfuzz._gen_function(random.Random(i), flags=flags)
            seen |= {w & 0xFF800000 for w in words}
        drew = bool(seen & {0xAB000000, 0xEB000000, 0xEA000000, 0xB1000000, 0xF1000000})
        assert drew == want, (flags, drew)


def _accessor_rows(rs):
    return [(0x1000 + i * 4, mn, op) for i, (mn, op) in enumerate(rs)]


def test_the_receiver_is_followed_from_the_entry_convention_and_nowhere_else():
    # #258. The old setter rule took "a store off x1 or x2" for a store into the receiver,
    # and named the slot after the setter. `RenderAnimatedSize.set:reverseDuration` loads
    # its controller into x2 and stores into THAT, and `_DelayedDone.set:next` stores into
    # an error it has just allocated; neither touches its receiver at the offset it wrote.
    # The reader follows parameter 0 from where the convention puts it: x1, or the first
    # pushed argument at entry-SP + 8 * (nargs - 1), through copies, spills and reloads.
    if not _capstone_available():
        _skip("  SKIP test_the_receiver_is_followed_from_the_entry_convention")
    from jadart.fields import _receiver_accesses as acc
    # register convention: a getter that is the load, and one that decompresses it
    assert acc(_accessor_rows([("ldur", "x0, [x1, #7]"), ("ret", "")]), 1) == {("ld", 8)}
    assert acc(_accessor_rows([("ldur", "w0, [x1, #0x17]"),
                               ("add", "x0, x0, x28, lsl #32"), ("ret", "")]), 1) \
        == {("ld", 0x18)}
    # stack convention, frameless: a getter's receiver at [SP], a setter's at [SP + 8]
    assert acc(_accessor_rows([("ldr", "x1, [x15]"), ("ldur", "w0, [x1, #0x17]"),
                               ("ret", "")]), 1) == {("ld", 0x18)}
    assert acc(_accessor_rows([("ldr", "x0, [x15]"), ("ldr", "x1, [x15, #8]"),
                               ("stur", "w0, [x1, #0xf]"), ("ret", "")]), 2) \
        == {("st", 0x10)}
    # with a frame, spilled across a call and reloaded: Tween.set:end's shape
    tween = [("stp", "x29, x30, [x15, #-0x10]!"), ("mov", "x29, x15"),
             ("sub", "x15, x15, #0x10"), ("stur", "x1, [x29, #-8]"),
             ("stur", "x2, [x29, #-0x10]"), ("blr", "x9"),
             ("ldur", "x0, [x29, #-0x10]"), ("ldur", "x1, [x29, #-8]"),
             ("stur", "w0, [x1, #0xf]"), ("mov", "x15, x29"),
             ("ldp", "x29, x30, [x15], #0x10"), ("ret", "")]
    assert acc(_accessor_rows(tween), 2) == {("st", 0x10)}
    # NOT the receiver: a register loaded out of it (set:reverseDuration's shape) ...
    assert acc(_accessor_rows([("ldur", "w2, [x1, #0x67]"),
                               ("add", "x2, x2, x28, lsl #32"),
                               ("stur", "w22, [x2, #0x2b]"), ("ret", "")]), 2) \
        == {("ld", 0x68)}
    # ... the result of an allocation (set:next's shape) ...
    assert acc(_accessor_rows([("bl", "#0x2000"), ("stur", "w2, [x0, #7]"),
                               ("ret", "")]), 2) == set()
    # ... x1 after a call has clobbered it, with nothing reloading it ...
    assert acc(_accessor_rows([("bl", "#0x2000"), ("stur", "w2, [x1, #7]"),
                               ("ret", "")]), 2) == set()
    # ... and a register that holds the receiver on one path into a join only.
    joined = [("cbz", "x3, #0x100c"), ("mov", "x1, x4"), ("stur", "w2, [x1, #7]"),
              ("ret", "")]
    assert acc(_accessor_rows(joined), 2) == set()
    # A receiver access it cannot place is no answer at all, rather than a partial one.
    assert acc(_accessor_rows([("ldr", "w0, [x1, x3]"), ("ret", "")]), 1) is None
    # An offset too big for the displacement goes through a constant register.
    assert acc(_accessor_rows([("mov", "x17, #0x15f"), ("ldr", "w0, [x1, x17]"),
                               ("ret", "")]), 1) == {("ld", 0x160)}


def test_a_hand_written_setter_does_not_name_the_slot_it_stores_to():
    # #258. `set capacity(int value) { _capacity = value; ... }`: Dart forbids a field
    # and a setter of one name in one class, so a hand-written setter's name is not its
    # slot's. main printed `this.capacity = x2;` inside `_Channel.set:capacity`, and 56
    # of the 61 offsets the old rule named on the clean fixture came from such setters.
    # Every name the channel gives now has an IMPLICIT accessor of that name whose own
    # Field is at that offset in that class.
    _needs_capstone()
    from jadart.disasm import load_instructions
    from jadart.fields import recover_accessors, recover_fields
    from jadart.program import _FUNCTION_KINDS
    image, fr, hdr = load_instructions(CLEAN)
    layout = recover_fields(fr, hdr.arch)
    acc = recover_accessors(image, fr, layout)
    assert not acc.refused, acc.refused
    channel = next(r for r, n in layout.class_name.items() if n.startswith("_Channel@"))
    assert (acc.by_class.get(channel) or {}).get(0x10) is None, acc.by_class.get(channel)
    for cls in (r for r, n in layout.class_name.items() if n == "TextPainter"):
        got = set((acc.by_class.get(cls) or {}).values())
        assert not got & {"locale", "ellipsis"}, got
    offset_of = {}
    for fref, (kb, vref) in fr.field_meta.items():
        if fr.smi_values.get(vref) is not None and not (kb >> 1) & 1:
            offset_of[fref] = fr.smi_values[vref] * hdr.arch.compressed_word_size
    implicit = {}
    for ref, nr, ow, kt in fr.functions:
        kind = _FUNCTION_KINDS[kt & 0x1F]
        if kind in ("ImplicitGetter", "ImplicitSetter"):
            off = offset_of.get(fr.func_data.get(ref))
            implicit.setdefault((ow, off), set()).add(fr.names.get(nr, "")[4:])
    named = [(cls, off, nm) for cls, offs in acc.by_class.items()
             for off, nm in offs.items()]
    assert len(named) == acc.added >= 5, (len(named), acc.added)
    for cls, off, nm in named:
        assert nm in implicit.get((cls, off), ()), (layout.class_name[cls], off, nm)


def test_an_implicit_accessor_names_its_own_fields_slot():
    # The positive half, and two things the old rule could not reach. An implicit
    # accessor's `data` IS its Field (KernelLoader::GenerateFieldAccessors calls
    # set_accessor_field), and the slots this names are the ones whose Field survives
    # with an offset but whose name is a VM-snapshot string the isolate snapshot never
    # writes. dart:ui's `Color` declares `final double a, r, g, b` in that order, which
    # puts r, g and b at 0x10, 0x18 and 0x20; `_ConstantTickerModeDataListenable`'s only
    # field is `value`, read by a getter whose body is more than the load.
    _needs_capstone()
    from jadart.disasm import load_instructions
    from jadart.fields import recover_accessors, recover_fields
    image, fr, hdr = load_instructions(CLEAN)
    layout = recover_fields(fr, hdr.arch)
    acc = recover_accessors(image, fr, layout)
    by_name = {layout.class_name[c]: offs for c, offs in acc.by_class.items()}
    assert by_name.get("Color") == {0x10: "r", 0x18: "g", 0x20: "b"}, by_name.get("Color")
    tick = next(v for k, v in by_name.items()
                if k.startswith("_ConstantTickerModeDataListenable@"))
    assert tick == {0x8: "value"}, tick
    stream = next(v for k, v in by_name.items()
                  if k.startswith("_AsyncStarStreamController@"))
    assert stream == {0xc: "controller", 0x10: "asyncStarBody"}, stream


def test_the_accessor_names_agree_with_every_field_object_that_speaks():
    # What says the channel reads names rather than inventing them, twice over. Where an
    # implicit accessor's Field names itself, the two names are equal (145 of 145 on the
    # clean fixture, 78 of 78 on the obf one); and the body reaches the receiver at the
    # Field's own offset (84 on clean). The obf fixture names nothing, because the
    # accessor names are obfuscated there too.
    _needs_capstone()
    from jadart.disasm import load_instructions
    from jadart.fields import recover_accessors, recover_fields
    for lib, wants in ((CLEAN, True), (OBF, False)):
        image, fr, _h = load_instructions(lib)
        layout = recover_fields(fr, getattr(image, "arch", None))
        acc = recover_accessors(image, fr, layout)
        assert acc.disagreed == 0 and not acc.refused, f"{lib}: {acc.refused}"
        assert acc.agreed >= 75, (lib, acc.agreed)
        if wants:
            assert acc.agreed >= 140 and acc.body_agreed >= 80, (acc.agreed,
                                                                 acc.body_agreed)
            merged = recover_fields(fr, getattr(image, "arch", None))
            assert merged.add_accessor_names(acc) == acc.added
            base = recover_fields(fr, getattr(image, "arch", None))
            for cls, offs in acc.by_class.items():
                for off in offs:
                    assert off not in (base.by_class.get(cls) or {}), (cls, off)
        else:
            assert acc.added == 0, f"{acc.added} names off an obfuscated build"



# The two symbol layouts a library names its snapshot with (#253).

#: A hash no release reproduces, for a header that has to be refused for its epoch.
_NO_SUCH_EPOCH = b"0" * 28 + b"0253"


def _merged_layout(d: bytes, version_hash: bytes = None) -> bytes:
    """The clean fixture as a Dart 3.13 container names it: the program's two images
    under _kDartSnapshotData and _kDartSnapshotText, and no vm symbol. Each name sits
    once in .dynstr, and the new spelling is shorter, so it is written over the old one
    in place and the symbol table needs no other change."""
    out = bytearray(d)
    for old, new in ((b"_kDartIsolateSnapshotData", b"_kDartSnapshotData"),
                     (b"_kDartIsolateSnapshotInstructions", b"_kDartSnapshotText"),
                     (b"_kDartVmSnapshotData", b"_kGoneVmSnapshotData"),
                     (b"_kDartVmSnapshotInstructions", b"_kGoneVmSnapshotInstructions")):
        assert d.count(old + b"\x00") == 1, old
        at = d.index(old + b"\x00")
        out[at:at + len(new) + 1] = new + b"\x00"
    if version_hash is not None:
        from jadart.elf import Elf
        e = Elf(d)
        at = e.va_to_offset(e.symbols["_kDartIsolateSnapshotData"].value)
        out[at + 20:at + 52] = version_hash
    return bytes(out)


def _merged_macho(header: bytes) -> bytes:
    """A Mach-O that exports the merged pair: one __TEXT segment whose __const holds
    `header` and whose __text holds a word of code, and an LC_SYMTAB naming both."""
    names = b"\x00_kDartSnapshotData\x00_kDartSnapshotText\x00"
    code = b"\xc0\x03\x5f\xd6" * 4
    seg = 72 + 2 * 80
    body = 32 + seg + 24
    at_const, at_text = body, body + len(header)
    at_sym = at_text + len(code)
    at_str = at_sym + 2 * 16
    va = 0x4000

    def section(name, addr, size, off):
        return (name.ljust(16, b"\x00") + b"__TEXT".ljust(16, b"\x00")
                + struct.pack("<QQI", addr, size, off) + bytes(28))

    out = struct.pack("<IiiIIIII", 0xFEEDFACF, 0x0100000C, 0, 6, 2, seg + 24, 0, 0)
    out += struct.pack("<II", 0x19, seg) + b"__TEXT".ljust(16, b"\x00")
    out += struct.pack("<QQQQIIII", va, 0x4000, 0, at_sym, 5, 5, 2, 0)
    out += section(b"__const", va + at_const, len(header), at_const)
    out += section(b"__text", va + at_text, len(code), at_text)
    out += struct.pack("<IIIIII", 0x02, 24, at_sym, 2, at_str, len(names))
    assert len(out) == body
    out += header + code
    out += struct.pack("<IBBHQ", 1, 0x0F, 1, 0, va + at_const)
    out += struct.pack("<IBBHQ", 20, 0x0F, 2, 0, va + at_text)
    return out + names


def test_a_merged_layout_library_is_refused_for_its_epoch_by_every_command(tmp_path):
    # Dart 3.13 writes one snapshot, exported as _kDartSnapshotData and
    # _kDartSnapshotText. `info` found it by its magic and named the unknown epoch, and
    # every other command asked for _kDartIsolateSnapshotData by name and refused with
    # "the snapshot is in libapp.so, not here" about the libapp.so (#253). The reason a
    # file cannot be read is one thing, whichever command is asked.
    import contextlib
    import io
    import json
    from jadart import cli
    from jadart.disasm import load_instructions
    from jadart.program import recover_program
    from jadart.snapshot import walk_isolate
    from jadart.stream import ReadStream
    from jadart.verify import verify_file

    path = tmp_path / "libapp.so"
    path.write_bytes(_merged_layout(open(CLEAN, "rb").read(), _NO_SUCH_EPOCH))
    out = tmp_path / "out"

    for door in (parse_libapp, recover_program, load_instructions, walk_isolate,
                 verify_file, jadart.program, jadart.verify, jadart.strings):
        with pytest.raises(UnknownEpoch):
            door(str(path))

    said = {}
    for argv in (["info"], ["verify"], ["classes"], ["libraries"], ["functions"],
                 ["strings"], ["symbols"], ["selectors"], ["constants"], ["ffi"],
                 ["decompile", "BenchAccount"], ["lift", "benchWithdraw"],
                 ["disasm", "benchWithdraw"], ["hook", "benchWithdraw"],
                 ["xrefs", "benchWithdraw"], ["export", "-o", str(out)]):
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            rc = cli.main(["-j", argv[0], str(path), *argv[1:]])
        doc = json.loads(buf.getvalue())
        assert (rc, doc["type"], doc["exit"]) == (2, "UnknownEpoch", 2), (argv, doc)
        said[argv[0]] = doc["error"]
    assert len(set(said.values())) == 1, said
    assert _NO_SUCH_EPOCH.decode() in said["info"] and "not here" not in said["info"]
    assert not out.exists(), "export wrote something for a file it refused"

    # The same on the Mach-O side, where the pair is spelled the same way.
    d = open(CLEAN, "rb").read()
    blob = jadart.elf.Elf(d).symbol_bytes("_kDartIsolateSnapshotData")
    st = ReadStream(blob, 52)
    st.read_cstring()
    header = bytearray(blob[:st.pos]) + bytes([0x80] * 5)
    struct.pack_into("<q", header, 4, len(header))
    header[20:52] = _NO_SUCH_EPOCH
    dylib = tmp_path / "App"
    dylib.write_bytes(_merged_macho(bytes(header)))
    for door in (parse_libapp, recover_program, load_instructions):
        with pytest.raises(UnknownEpoch):
            door(str(dylib))
    from jadart.snapshot import parse_libapp_with_anchor
    heads, anchor = parse_libapp_with_anchor(str(dylib), strict=False)
    assert list(heads) == ["isolate"] and heads["isolate"].epoch is None
    assert (anchor["symbol"], anchor["container"], anchor["size"]) == (
        "_kDartSnapshotText", "macho", 16)


def test_a_merged_layout_library_is_read_through_the_merged_pair(tmp_path):
    # The symbols say where the two images are and the version hash says how to read
    # them, so the fixture's own snapshot under the 3.13 names reads as it always did,
    # and every address is given against the symbol this file exports: a Frida script
    # that resolved _kDartIsolateSnapshotInstructions in such a library would find
    # nothing to hook.
    import dataclasses
    from jadart import hooks, interop
    from jadart.disasm import load_instructions
    from jadart.program import recover_program
    from jadart.snapshot import parse_libapp_with_anchor
    from jadart.verify import verify_file

    path = tmp_path / "libapp.so"
    path.write_bytes(_merged_layout(open(CLEAN, "rb").read()))

    real, real_anchor = parse_libapp_with_anchor(CLEAN)
    got, anchor = parse_libapp_with_anchor(str(path))
    assert list(got) == ["isolate"], "one snapshot, and it is the program's"
    assert got["isolate"] == real["isolate"]
    assert anchor == dict(real_anchor, symbol="_kDartSnapshotText")

    was = recover_program(CLEAN)
    now = recover_program(str(path))
    assert now.classes == was.classes and now.strings == was.strings

    old_image, old_fr, _hdr = load_instructions(CLEAN)
    image, fr, hdr = load_instructions(str(path))
    assert image.anchor_symbol == "_kDartSnapshotText"
    assert old_image.anchor_symbol == "_kDartIsolateSnapshotInstructions"
    # symbol_names maps the image's own start to the symbol that names it, so it
    # differs by exactly that spelling; everything else is the same image.
    for f in dataclasses.fields(image):
        if f.name not in ("anchor_symbol", "symbol_names"):
            assert getattr(image, f.name) == getattr(old_image, f.name), f.name
    assert fr.codes == old_fr.codes and fr.functions == old_fr.functions

    info = interop.binary_info(image, hdr, "libapp.so")
    assert info["anchor"]["symbol"] == info["runtime_symbol"] == "_kDartSnapshotText"
    syms = interop.code_symbols(image, fr, hdr)
    chosen, problems = hooks.select(syms, ["benchWithdraw"])
    assert not problems
    planned = hooks.plan(image, hdr, fr, chosen)
    for text in (hooks.render_frida(image, hdr, fr, syms, planned, "libapp.so", "t"),
                 interop.render_r2(image, hdr, syms, "libapp.so", "t"),
                 interop.render_ghidra(image, hdr, syms, "libapp.so", "t"),
                 interop.render_ida(image, hdr, syms, "libapp.so", "t")):
        assert "_kDartSnapshotText" in text
        assert "_kDartIsolateSnapshotInstructions" not in text

    # The gates still pass, and the one that needs a vm snapshot says there is none.
    rep = verify_file(str(path))
    assert rep.supported
    g13 = next(g for g in rep.gates if g.gate.startswith("G13"))
    assert g13.skipped == "no vm snapshot in this container"


def test_a_library_with_no_snapshot_symbol_is_told_what_is_true(tmp_path):
    # "If this is a Flutter app, the snapshot is in libapp.so, not here" was said to
    # every file the isolate symbol was missing from, and for two of these three it
    # was false: a stripped libapp.so IS the file, and so is one that names its
    # snapshot both ways.
    import contextlib
    import io
    import json
    from jadart import cli
    from jadart.disasm import load_instructions
    from jadart.errors import ContainerError, MissingSymbol
    from jadart.program import recover_program
    from jadart.snapshot import walk_isolate

    d = open(CLEAN, "rb").read()
    path = tmp_path / "libapp.so"

    def refused(kind, *doors):
        errors = []
        for door in doors or (recover_program, load_instructions, walk_isolate):
            with pytest.raises(kind) as e:
                door(str(path))
            errors.append(str(e.value))
        assert len(set(errors)) == 1, errors
        return errors[0]

    # Its section headers gone, the fixture has no symbols and still holds the
    # snapshot: the header is readable from the magic, the images are not locatable.
    bare = bytearray(d)
    struct.pack_into("<HHH", bare, 0x3A, 0, 0, 0)
    path.write_bytes(bare)
    assert list(parse_libapp(str(path))) == ["blob0", "blob1"]
    said = refused(MissingSymbol)
    assert "a Dart snapshot starts at file offset 0x340" in said, said
    assert "not here" not in said and "_kDartSnapshotData" in said

    # A library with no snapshot at all is the one case the old hint was right about.
    path.write_bytes(_minimal_elf64())
    said = refused(MissingSymbol)
    assert "no Dart snapshot here" in said and "libapp.so" in said, said

    # Both layouts at once: the vm symbol kept, the isolate pair renamed. No engine
    # loads the two families together, so which snapshot is the program is not in the
    # file, and `info` refuses it as well.
    both = bytearray(_merged_layout(d))
    at = both.index(b"_kGoneVmSnapshotData\x00")
    both[at:at + 21] = b"_kDartVmSnapshotData\x00"
    path.write_bytes(both)
    said = refused(ContainerError, recover_program, load_instructions, walk_isolate,
                   parse_libapp)
    assert "exports both snapshot layouts" in said, said
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        assert cli.main(["-j", "info", str(path)]) == 2
    assert json.loads(buf.getvalue())["type"] == "ContainerError"


def test_one_contradicted_accessor_refuses_the_whole_channel():
    # Teeth, for both encodings. Moving one implicit accessor's Field to another slot
    # makes its body disagree with it, and renaming one Field makes its accessor's name
    # disagree with it; either one has to refuse every name, the rule `recover_fields`
    # applies to an offset outside its owner.
    _needs_capstone()
    from jadart.disasm import load_instructions
    from jadart.fields import recover_accessors, recover_fields
    from jadart.program import _FUNCTION_KINDS
    image, fr, hdr = load_instructions(CLEAN)
    layout = recover_fields(fr, hdr.arch)
    assert recover_accessors(image, fr, layout).added > 0
    getter = next(ref for ref, nr, ow, kt in fr.functions
                  if _FUNCTION_KINDS[kt & 0x1F] == "ImplicitGetter"
                  and fr.names.get(nr, "") == "get:g"
                  and layout.class_name.get(ow) == "Color")
    field = fr.func_data[getter]
    kb, vref = fr.field_meta[field]
    # Point this one Field at the Smi of the next slot along. The Smi itself is shared by
    # every Field at that offset, so it is the Field's ref that moves, not the number.
    nxt = next(r for r, v in fr.smi_values.items() if v == fr.smi_values[vref] + 1)
    fr.field_meta[field] = (kb, nxt)
    try:
        moved = recover_accessors(image, fr, layout)
    finally:
        fr.field_meta[field] = (kb, vref)
    assert moved.disagreed == 1 and moved.added == 0 and "reaches" in moved.refused, moved
    at = next(i for i, (ref, _n, _o) in enumerate(fr.fields)
              if fr.names.get(_n, "") and any(fr.func_data.get(f) == ref
                                              for f, _nr, _ow, kt in fr.functions
                                              if _FUNCTION_KINDS[kt & 0x1F]
                                              == "ImplicitSetter"))
    other = next(n for _r, n, _o in fr.fields if fr.names.get(n, "")
                 and fr.names.get(n) != fr.names.get(fr.fields[at][1]))
    saved_field = fr.fields[at]
    fr.fields[at] = (saved_field[0], other, saved_field[2])
    try:
        renamed = recover_accessors(image, fr, layout)
    finally:
        fr.fields[at] = saved_field
    assert renamed.disagreed == 1 and renamed.added == 0, renamed
    assert "names an implicit accessor after its own Field" in renamed.refused, renamed


# Dart 3.13: one snapshot per library, and the reads that changed with it (#254).

DART_3_13 = "0451907c2eaa8467e848c0067bfe8ed4"
#: The one 3.13 binary there is to check against: FluffyChat's F-Droid build, pulled by
#: tools/appsweep.py. Not committed, so what needs it skips on a fresh clone.
FLUFFYCHAT = os.path.expanduser(
    "~/.cache/jadart-appsweep/libapps/chat.fluffy.fluffychat.so")


def _wu(v: int) -> bytes:
    """WriteUnsigned, datastream.h: 7-bit groups, the last one carrying the marker."""
    out = bytearray()
    while v > 127:
        out.append(v & 0x7F)
        v >>= 7
    return bytes(out) + bytes([v + 128])


def _ws(v: int) -> bytes:
    """Write<T>: the same groups with the signed marker, so the last is -64..63."""
    out = bytearray()
    while not -64 <= v <= 63:
        out.append(v & 0x7F)
        v >>= 7
    return bytes(out) + bytes([v + 192])


def _wref(v: int) -> bytes:
    """WriteRefId: 7-bit groups most significant first, the last with its high bit."""
    groups = [v & 0x7F]
    while v > 127:
        v >>= 7
        groups.append(v & 0x7F)
    groups.reverse()
    return bytes(groups[:-1]) + bytes([groups[-1] | 0x80])


def _merged_elf(blob: bytes) -> bytes:
    """An ELF64 that exports `blob` as _kDartSnapshotData and four words of code as
    _kDartSnapshotText, which is all a Dart 3.13 library names."""
    names = b"\x00_kDartSnapshotData\x00_kDartSnapshotText\x00"
    code = b"\xc0\x03\x5f\xd6" * 4
    at = 64 + 5 * 64
    offs = []
    for part in (names, None, blob, code):
        offs.append(at)
        at += 3 * 24 if part is None else len(part)      # None: the three symbols
    syms = (bytes(24) + struct.pack("<IBBHQQ", 1, 0x11, 0, 3, offs[2], len(blob))
            + struct.pack("<IBBHQQ", 20, 0x11, 0, 4, offs[3], len(code)))
    heads = [(0, 0, 0, 0, 0, 0),
             (3, 0, offs[0], len(names), 0, 0),              # the one string table
             (11, 0, offs[1], len(syms), 1, 24),             # .dynsym
             (1, offs[2], offs[2], len(blob), 0, 0),         # .rodata, loaded in place
             (1, offs[3], offs[3], len(code), 0, 0)]         # .text
    eh = bytearray(64)
    eh[0:7] = b"\x7fELF\x02\x01\x01"
    struct.pack_into("<Q", eh, 0x28, 64)
    struct.pack_into("<HHH", eh, 0x3A, 64, len(heads), 1)
    return (bytes(eh) + b"".join(struct.pack("<IIQQQQIIQQ", 0, ty, 0, addr, off, size,
                                             link, 0, 0, ent)
                                 for ty, addr, off, size, link, ent in heads)
            + names + syms + blob + code)


#: The root run _dart_3_13_snapshot writes after its fill, as a layout: LazyCompile and
#: UnknownDartCode at 1 and 3, the class table from 4, for the Classes of cids 5 and 4000.
#: Small on purpose, and not the 3.13.0 one, which needs 1,689 roots and every predefined
#: class; it is the same shape, read by the same code.
def _small_roots():
    from jadart.objstore import RootLayout
    return RootLayout(count=6, stubs={1: "LazyCompile", 3: "UnknownDartCode"},
                      class_base=4, class_cids=(5, 4000))


def _dart_3_13_snapshot(second_pool: int = 0, scope_vars: int = 0, kind: int = 2,
                        base: int = 7, closure_alloc=(0, 2), roots=None):
    """(blob, stream, (base, objects, clusters, fill_end)) for a small Dart 3.13 program
    snapshot, written by hand from app_snapshot.cc at 3.13.0: no 3.13 fixture can be
    built with the 3.12.2 SDK this repository pins. It holds one cluster of everything
    3.13 reads differently, in the order the serializer writes them: the roots' own
    small clusters first, so the canonical String cluster is not the first one. After
    the fill comes a root run in the shape of _small_roots, then two empty field tables.

    The knobs each make one thing wrong: `second_pool` gives the empty pool entries,
    `scope_vars` the empty ContextScope variables, `kind` and `base` the header's kind
    and base-object count, `closure_alloc` the lengths the alloc pass states for the two
    closures (the fill still reads 0 and 2), and `roots` the root run's refs."""
    from jadart import versions
    table = versions._EPOCHS[DART_3_13].cid_table

    def tag(name, canonical=False):
        return _ws(table.cid(name) << 12 | (2 if canonical else 0))

    refs = lambda n: _wref(1) * n                              # noqa: E731
    scalars = lambda n: _ws(0) * n                             # noqa: E731
    text = ("Foo", "Class", "bar")
    # base objects are refs 1..7; then Mint 8, the pools 9 and 10, the strings 11..13,
    # the Classes 14..16 and, last, the three Code objects 25..27
    foo, klass_name = 11, 12

    def klass(cid, name, bitmap=True):
        # 13 refs, name first; then id, sizes and state as int32s; the unboxed-fields
        # bitmap for every class that is not a library's top-level one
        return (_wref(name) + refs(12) + _ws(cid) + _ws(2) + _ws(2) + scalars(4)
                + (_wu(0) if bitmap else b""))

    pool = lambda n: _wu(n) + (b"\x01" + _wref(foo)) * n       # noqa: E731
    code = lambda owner: _wu(0) + _wref(owner) + refs(5)        # noqa: E731
    alloc = [
        tag("MintCid", True) + _wu(1) + _ws(0),
        tag("ObjectPoolCid") + _wu(1) + _wu(second_pool),      # the empty pool
        tag("ObjectPoolCid") + _wu(1) + _wu(2),                # the global one
        tag("StringCid", True) + b"".join([_wu(3)] + [_wu(len(t) << 1) for t in text])
        + _wu(6) + _wu(0) + _wu(0) * 3,                        # the canonical set
        tag("ClassCid") + _wu(3),                              # ReadAllocFixedSize
        tag("ClosureCid") + _wu(2) + b"".join(_wu(n) for n in closure_alloc),
        tag("ContextScopeCid") + _wu(1) + _wu(scope_vars),     # the empty singletons
        tag("LocalVarDescriptorsCid") + _wu(1) + _wu(0),
        tag("ApiErrorCid") + _wu(1),
        tag("UnwindErrorCid") + _wu(1),
        tag("LanguageErrorCid") + _wu(1),
        tag("UnhandledExceptionCid") + _wu(1),
        tag("CodeCid") + _wu(3) + _ws(0) * 3 + _wu(0),         # three, none deferred
    ]
    fill = [
        b"",
        pool(second_pool),
        pool(2),
        b"".join(_wu(len(t) << 1) + t.encode() for t in text),
        klass(table.cid("ClassCid"), klass_name) + klass(4000, foo)
        + klass((1 << 20) + 3, 1, bitmap=False),
        _wu(0) + refs(3) + _wu(2) + refs(5),                   # length, then 3 + length
        _wu(scope_vars) + b"\x00" + refs(10 * scope_vars),     # length, is_implicit
        _wu(0),                                                # length, and no entries
        refs(1),
        refs(1) + b"\x01",                                     # is_user_initiated
        refs(4) + _ws(-1) + b"\x00\x02",                       # token pos, bool, kind
        refs(2),
        # the LazyCompile and UnknownDartCode stubs, which are Code 26 and 27, then
        # each code's payload info and six refs, the owner first
        _wref(26) + _wref(27) + code(9) + code(1) + code(1),
    ]
    run = roots if roots is not None else (1, 26, 1, 27, 14, 15)
    fill_end = len(b"".join(alloc) + b"".join(fill))
    stream = (b"".join(alloc) + b"".join(fill) + b"".join(_wref(r) for r in run)
              + _wu(0) + _wu(0))
    objects = 7 + 1 + 2 + 3 + 3 + 2 + 1 + 1 + 1 + 1 + 1 + 1 + 3
    head = (struct.pack("<Iqq", 0xDCDCF5F5, 0, kind) + DART_3_13.encode()
            + b"product no-dwarf_stack_traces_mode arm64 android compressed-pointers\x00"
            + _wu(base) + _wu(objects) + _wu(len(alloc)) + _wu(0) + _wu(0))
    blob = bytearray(head + stream)
    struct.pack_into("<q", blob, 4, len(blob) - 4)
    return bytes(blob), stream, (7, objects, len(alloc), fill_end)


def test_dart_3_13_reads_the_clusters_the_merged_snapshot_changed():
    """Four reads differ between 3.12 and 3.13, and each is its own switch.

    Class alloc is one count where it was a predefined list and a count, a Closure
    carries a length in both passes, the Code fill opens with two stub refs, and
    ContextScope, LocalVarDescriptors and the four error classes reach an AOT snapshot
    for the first time because the vm snapshot that held them is gone. Each switch is
    put back in turn to show the walk needs it."""
    import dataclasses
    from jadart import versions
    from jadart.clusters import walk_alloc
    from jadart.fillwalk import FillError, walk_fill
    from jadart.stream import ReadStream

    epoch = versions._EPOCHS[DART_3_13]
    arch = versions.Arch("arm64", 8, True)
    assert (epoch.name, epoch.dart, epoch.merged) == ("objectheader-3.13", "3.13.0", True)
    _blob, stream, (base, objects, nclusters, fill_end) = _dart_3_13_snapshot()
    assert base == epoch.base_objects == 7

    def walk(e, data=stream):
        st = ReadStream(data, 0)
        clusters = walk_alloc(st, base, objects, nclusters, epoch=e, arch=arch)
        return clusters, walk_fill(st, clusters, e, arch=arch)

    clusters, fr = walk(epoch)
    assert fr.end_pos == fill_end, "the fill did not end where the roots begin"
    assert [(c.name[:-3], c.count, c.start_ref) for c in clusters] == [
        ("Mint", 1, 8), ("ObjectPool", 1, 9), ("ObjectPool", 1, 10), ("String", 3, 11),
        ("Class", 3, 14), ("Closure", 2, 17), ("ContextScope", 1, 19),
        ("LocalVarDescriptors", 1, 20), ("ApiError", 1, 21), ("UnwindError", 1, 22),
        ("LanguageError", 1, 23), ("UnhandledException", 1, 24), ("Code", 3, 25)]
    by_name = {c.name: c for c in clusters}
    assert by_name["ClassCid"].predefined_cids is None
    assert by_name["ClassCid"].main_count == 0
    assert by_name["ClosureCid"].lengths == [0, 2]
    assert [c & 0xFFFFFFFF for _r, _n, c, _s in fr.classes] == [5, 4000, (1 << 20) + 3]
    assert set(fr.class_unboxed) == {5, 4000}, "a top-level class has no bitmap to read"
    assert fr.codes == [(25, 9, 0), (26, 1, 1), (27, 1, 2)], (
        "a code's owner is the first ref after its payload info, past the two stubs")
    assert fr.code_stub_refs == [(26, 27)]
    assert fr.sized_lengths == {5: [0, 2], 6: [0], 7: [0]}
    assert fr.pool == [("ref", 11), ("ref", 11)], "the global pool, and only it"

    # Each switch back at its 3.12 value: the stream no longer walks, or no longer ends
    # where it ends.
    for off in ({"class_alloc_predefined": True}, {"closure_sized": False},
                {"code_stub_refs": False}, {"fill_sized": {}}, {"fill_overrides": {}}):
        older = dataclasses.replace(epoch, **off)
        try:
            ended = walk(older)[1].end_pos
        except jadart.JadartError:
            continue
        assert ended != fill_end, f"{off} changed nothing this stream can see"

    # And 3.12.2 itself refuses these bytes rather than reading them some other way.
    with pytest.raises(jadart.JadartError):
        walk(versions._EPOCHS[KNOWN_HASH])

    # Every pool_0x offset indexes the global pool, so a second pool with entries is
    # refused: read on, its entries would sit in front of the global pool's and shift
    # every index, and nothing in the stream says which pool the code uses.
    _blob, two, _counts = _dart_3_13_snapshot(second_pool=1)
    with pytest.raises(FillError) as e:
        walk(epoch, two)
    assert "ObjectPools with entries to 2" in str(e.value)

    # A ContextScope or LocalVarDescriptors with anything in it is refused too. A
    # product AOT snapshot holds only the empty singleton of each, so no binary has
    # shown what the source says a longer one holds, and this one is written the way
    # the source describes it: reading it would be taking that on trust.
    _blob, scoped, _counts = _dart_3_13_snapshot(scope_vars=1)
    with pytest.raises(FillError) as e:
        walk(epoch, scoped)
    assert "ContextScope of length 1" in str(e.value)


def test_a_dart_3_13_library_reads_end_to_end(tmp_path, monkeypatch):
    """The same snapshot inside the container a 3.13 build ships: one data symbol, one
    text symbol, no vm snapshot. This is what runs on a checkout with no real 3.13 app.

    It stops at the commands that read the stream. The blob has no data image behind
    it, so there is no instructions table for the others to find."""
    import contextlib
    import dataclasses
    import io
    import json
    from jadart import cli, versions
    from jadart.program import recover_program
    from jadart.snapshot import parse_libapp_with_anchor, walk_isolate

    blob, _stream, _counts = _dart_3_13_snapshot()
    path = tmp_path / "libapp.so"
    path.write_bytes(_merged_elf(blob))

    heads, anchor = parse_libapp_with_anchor(str(path))
    assert list(heads) == ["isolate"]
    hdr = heads["isolate"]
    assert (hdr.epoch.dart, hdr.kind, hdr.kind_name) == ("3.13.0", 2, "kFullAOT")
    assert (hdr.num_base_objects, hdr.num_clusters) == (7, 13)
    assert anchor["symbol"] == "_kDartSnapshotText" and anchor["size"] == 16

    prog = recover_program(str(path))
    assert (prog.epoch_name, prog.dart) == ("objectheader-3.13", "3.13.0")
    assert [(k.name, k.class_id & 0xFFFFFFFF) for k in prog.classes] == [
        ("Class", 5), ("Foo", 4000), ("", (1 << 20) + 3)]
    assert [k.name for k in prog.user_classes()] == ["Foo"]

    # The canonical String cluster is the fourth here and the tenth in a real app. The
    # quick path used to answer "no strings" whenever it was not the first.
    assert walk_isolate(str(path))["strings"] == ["Foo", "Class", "bar"]
    assert walk_isolate(str(path), full=True)["strings"] == ["Class", "Foo", "bar"]
    # Only on a 3.13 epoch, though. An older one keeps the quick path's answer for a
    # first cluster that is not String, which is none, so a crafted pre-3.13 file is
    # read as before. Its header numbers kFullAOT as every release before 3.13 does,
    # 3, or the kind check refuses it before the walk (#260).
    older = dataclasses.replace(hdr.epoch, merged=False)
    monkeypatch.setitem(versions._EPOCHS, DART_3_13, older)
    pre = tmp_path / "pre_3_13.so"
    pre.write_bytes(_merged_elf(_dart_3_13_snapshot(kind=3)[0]))
    assert walk_isolate(str(pre))["strings"] == []
    monkeypatch.setitem(versions._EPOCHS, DART_3_13, hdr.epoch)

    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        assert cli.main(["-j", "info", str(path)]) == 0
    doc = json.loads(buf.getvalue())
    assert doc["snapshots"]["isolate"]["kind"] == "kFullAOT"
    assert doc["snapshots"]["isolate"]["dart"] == "3.13.0"
    assert doc["anchor"]["symbol"] == "_kDartSnapshotText"
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        assert cli.main(["classes", str(path)]) == 0
    assert "class Foo" in buf.getvalue()


def test_a_dart_3_13_header_the_vm_would_not_load_is_refused(tmp_path):
    """A 3.13 header is read only as what the VM would load it as: an app's AOT
    snapshot, kind 2, with seven base objects.

    The kind range check was written for the older enum, where 3 is kFullAOT. In the
    3.13 enum 3 is kModule, so a kModule header passed it and parsed as a program, and
    with every gate passing (#254 review). The base objects are what every ref is
    counted from, and the VM FATALs on a count other than the one it provides; read on,
    a count of 8 shifted every ref by one and `classes` still exited 0."""
    import contextlib
    import io
    import json
    from jadart import cli

    path = tmp_path / "libapp.so"
    for knobs, says in (({"kind": 3}, "kind 3 (kModule)"),
                        ({"kind": 1}, "kind 1 (kFullJIT)"),
                        ({"kind": 0}, "kind 0 (kFull)"),
                        ({"base": 8}, "8 base objects")):
        blob, _stream, _counts = _dart_3_13_snapshot(**knobs)
        path.write_bytes(_merged_elf(blob))
        for strict in (True, False):           # --lenient knows this release too
            with pytest.raises(jadart.InputError) as e:
                parse_libapp(str(path), strict=strict)
            assert says in str(e.value), (knobs, str(e.value))
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            assert cli.main(["-j", "info", str(path)]) == 2
        assert json.loads(buf.getvalue())["type"] == "InputError"

    blob, _stream, _counts = _dart_3_13_snapshot()
    path.write_bytes(_merged_elf(blob))
    hdr = parse_libapp(str(path))["isolate"]
    assert (hdr.kind_name, hdr.num_base_objects) == ("kFullAOT", 7)


def test_a_data_symbol_that_ends_before_its_instructions_table_is_refused(
        tmp_path, clean_loaded):
    """The InstructionsTable is read out of the data symbol's bytes, at offsets the
    snapshot header gives, and nothing bounded the one by the other. The clean fixture
    with _kDartIsolateSnapshotData's st_size cut from 1,142,672 to 938,140, the
    header's own Snapshot::length(), still parses its header, and `verify` and
    `functions` exited 3 with a struct.error from parse_instructions_table (#256). Each
    cut is a typed failure now that names the symbol."""
    import contextlib
    import io
    import json
    from jadart import cli
    from jadart.disasm import load_instructions
    from jadart.elf import Elf
    from jadart.stream import TruncatedSnapshot

    d = open(CLEAN, "rb").read()
    sym = Elf(d).symbols["_kDartIsolateSnapshotData"]
    # st_value then st_size, side by side in the symbol's .dynsym entry
    record = struct.pack("<QQ", sym.value, sym.size)
    assert d.count(record) == 1
    at = d.index(record) + 8

    def cut(size):
        out = bytearray(d)
        struct.pack_into("<Q", out, at, size)
        path = tmp_path / f"cut-{size}.so"
        path.write_bytes(out)
        return str(path)

    def refused(path, said):
        with pytest.raises(TruncatedSnapshot) as e:
            load_instructions(path)
        assert str(e.value) == said
        for cmd in ("verify", "functions"):
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                rc = cli.main(["-j", cmd, path])
            doc = json.loads(buf.getvalue())
            assert (rc, doc["type"], doc["error"]) == (2, "TruncatedSnapshot", said), (
                cmd, doc)

    # The data image starts at 938,176, the table object at 938,240 and its 8,194
    # entries end at 1,003,824. Cut before the four-word preamble, after it and before
    # the last entry, and a byte short of the end.
    name = "_kDartIsolateSnapshotData: the symbol is"
    assert sym.size == 1142672
    refused(cut(938140), f"{name} 938140 bytes, and its snapshot header puts the "
                         f"InstructionsTable at 938240..938272, past the symbol's end.")
    for size in (938300, 1003823):
        refused(cut(size), f"{name} {size} bytes, and the InstructionsTable at 938240 "
                           f"declares 8194 entries, which end at 1003824, past the "
                           f"symbol's end.")
    # `info` reads only the header, which is all there.
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        assert cli.main(["-j", "info", cut(938140)]) == 0
    # A symbol that ends where the table does holds all of it.
    image, _fr, _hdr = load_instructions(cut(1003824))
    assert (image.pcs, image.first_code) == (clean_loaded[0].pcs,
                                            clean_loaded[0].first_code)

    # A Dart 3.13 library names its data symbol _kDartSnapshotData, and the one this
    # writes has no data image behind the stream, so its table starts past the end.
    blob, _stream, _counts = _dart_3_13_snapshot()
    path = tmp_path / "libapp.so"
    path.write_bytes(_merged_elf(blob))
    start = (len(blob) + 63) & ~63
    refused(str(path), f"_kDartSnapshotData: the symbol is {len(blob)} bytes, and its "
                       f"snapshot header puts the InstructionsTable at "
                       f"{start}..{start + 32}, past the symbol's end.")



def test_a_code_symbol_that_ends_before_its_image_is_refused(tmp_path, clean_loaded):
    """The instructions image says how long it is in its first word (ImageSize), and the
    symbol that holds it is sized by the container. The clean fixture with
    _kDartIsolateSnapshotInstructions' st_size cut to 0 exited 0 from every command:
    `verify` said "Grammar consistent" on Tier A 9/9, `functions` listed 8,193 ranges
    with no bytes behind them, `lift` printed nothing and `decompile` said "no code"
    (#267). Each cut is a typed failure now that names the symbol."""
    import contextlib
    import io
    import json
    from jadart import cli
    from jadart.disasm import load_instructions
    from jadart.elf import Elf
    from jadart.stream import TruncatedSnapshot

    d = open(CLEAN, "rb").read()
    elf = Elf(d)
    sym = elf.symbols["_kDartIsolateSnapshotInstructions"]
    record = struct.pack("<QQ", sym.value, sym.size)
    assert d.count(record) == 1 and sym.size == 1833776
    at = d.index(record) + 8
    word = elf.va_to_offset(sym.value)
    assert struct.unpack_from("<Q", d, word)[0] == sym.size   # ImageSize, as written

    def craft(size=None, image_size=None):
        out = bytearray(d)
        if size is not None:
            struct.pack_into("<Q", out, at, size)
        if image_size is not None:
            struct.pack_into("<Q", out, word, image_size)
        path = tmp_path / f"cut-{size}-{image_size}.so"
        path.write_bytes(out)
        return str(path)

    name = "_kDartIsolateSnapshotInstructions: the symbol is"

    def refused(path, said):
        with pytest.raises(TruncatedSnapshot) as e:
            load_instructions(path)
        assert str(e.value) == said
        for argv in (["verify", path], ["functions", path],
                     ["lift", path, "benchWithdraw"]):
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                rc = cli.main(["-j"] + argv)
            doc = json.loads(buf.getvalue())
            assert (rc, doc["type"], doc["error"]) == (2, "TruncatedSnapshot", said), (
                argv, doc)

    for size in (0, 4):
        refused(craft(size), f"{name} {size} bytes, too short to hold the "
                             f"instructions image's own header.")
    # Past the last range's start too: the table cannot say where the last function
    # ends, the image can.
    for size in (1000000, 1833376 + 4, 1833775):
        refused(craft(size), f"{name} {size} bytes, and the instructions image it "
                             f"holds says it is 1833776.")
    # An image that says it ends before the code the table places in it.
    refused(craft(image_size=1000000),
            "_kDartIsolateSnapshotInstructions: the InstructionsTable places code at "
            "offset 1833376, and the instructions image ends at 1000000.")
    # `info` reads only the data symbol's header.
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        assert cli.main(["-j", "info", craft(0)]) == 0
    # The whole symbol is the image, and loads as it did.
    image, _fr, _hdr = load_instructions(craft(1833776))
    assert (image.pcs, len(image.text)) == (clean_loaded[0].pcs, 1833776)

def _gates_3_13(hdr_base: int = 7, epoch=None, **knobs):
    """run_gates over _dart_3_13_snapshot(**knobs) with _small_roots for a layout, and
    the image and header a real file would give, cut to what the gates read."""
    import dataclasses
    from types import SimpleNamespace
    from jadart import versions
    from jadart.clusters import walk_alloc
    from jadart.fillwalk import walk_fill
    from jadart.stream import ReadStream
    from jadart.verify import run_gates

    e = epoch or dataclasses.replace(versions._EPOCHS[DART_3_13], roots=_small_roots())
    blob, _stream, (base, objects, nclusters, _end) = _dart_3_13_snapshot(**knobs)
    arch = versions.Arch("arm64", 8, True)
    st = ReadStream(blob, 52)
    st.read_cstring()
    for _ in range(5):
        st.read_unsigned()
    clusters = walk_alloc(st, base, objects, nclusters, epoch=e, arch=arch)
    fr = walk_fill(st, clusters, e, arch=arch)
    image = SimpleNamespace(data=blob, first_code=0, pcs=[0, 16, 32], text=bytes(48))
    hdr = SimpleNamespace(epoch=e, arch=arch, num_objects=objects,
                          num_base_objects=hdr_base, instr_table_len=3)
    gates = {g.gate.split()[0]: g for g in run_gates(clusters, fr, hdr, image=image)}
    return gates, image, fr, e


def test_the_dart_3_13_gates_run_without_a_real_app():
    """The four gates 3.13 changed or added, each with a case that has to fail.

    They ran only on FluffyChat, which CI does not have, so putting any of them back
    as it was left every test green there (#254 review). The layout is _small_roots
    rather than the 3.13.0 one, whose run is 1,689 refs and every predefined class
    long; the gates read either the same way."""
    import dataclasses
    from jadart.objstore import RootLayout, stub_names

    gates, image, fr, e = _gates_3_13()
    ran = [g for g in gates.values() if g.tier == "A" and not g.skipped]
    assert all(g.passed for g in ran), [(g.gate, g.detail) for g in ran if not g.passed]
    want = {"G3": ("G3 class table roots vs class ids", 2),
            "G16": ("G16 stub roots vs Code fill refs", 2),
            "G17": ("G17 sized alloc/fill lengths", 4),
            "G13": ("G13 base objects vs fixed roots", 1)}
    for key, (name, checks) in want.items():
        g = gates[key]
        assert (g.gate, g.checks, g.passed, g.skipped) == (name, checks, True, ""), g
    assert stub_names(image, fr, e) == {16: "_iso_stub_LazyCompileStub",
                                        32: "_iso_stub_UnknownDartCodeStub"}

    # G3: the class-table roots in the wrong order. The message counts them.
    g = _gates_3_13(roots=(1, 26, 1, 27, 15, 14))[0]["G3"]
    assert not g.passed and g.detail == (
        "2 of 2 roots are not the Class of the cid read for them; first at cid 5")

    # G16: a stub list with the two names the Code fill reads in each other's place,
    # and one with a stub more ahead of them. Either moves a stub onto a neighbour's
    # root, the gate fails, and the stubs are not named at all rather than wrongly.
    for stubs in ({1: "UnknownDartCode", 3: "LazyCompile"},
                  {1: "Extra", 2: "LazyCompile", 3: "UnknownDartCode"}):
        layout = RootLayout(count=6, stubs=stubs, class_base=4, class_cids=(5, 4000))
        moved = dataclasses.replace(e, roots=layout)
        gates, image, fr, _e = _gates_3_13(epoch=moved)
        assert not gates["G16"].passed and "disagree" in gates["G16"].detail, stubs
        assert stub_names(image, fr, moved) == {}, stubs

    # G17: the alloc pass says the second closure holds 3, and the fill reads 2. The
    # fill sizes its reads by its own copy, so nothing else notices.
    g = _gates_3_13(closure_alloc=(0, 3))[0]["G17"]
    assert not g.passed and "alloc 3, fill 2" in g.detail, g.detail

    # G13: seven base objects, and a header stating eight.
    assert not _gates_3_13(hdr_base=8)[0]["G13"].passed


def test_a_dart_3_13_stub_is_named_by_its_symbol_only_where_the_roots_agree(monkeypatch):
    """3.13 symbol tables spell a stub `stub X` where 3.12 wrote `stub _iso_stub_XStub`
    (StubCode::ForEachStub lost the object-store branch that supplied it), so a
    symbolized 3.13 build would hide every stub from the lifter's rules. The symbol is
    spelled the lifter's way, and it has to agree with the roots: where they differ
    the layout is wrong for this binary, and the compiler's names stand alone.

    Through 3.12 nothing changes: a symbol wins and the roots fill the gaps."""
    from types import SimpleNamespace
    from jadart import disasm, versions
    from jadart.expr import _classify_stub

    fr = SimpleNamespace(functions=[], strings={}, names={})

    def names(epoch, symbols, roots):
        monkeypatch.setattr(disasm, "stub_names", lambda _i, _f, _e: dict(roots))
        image = SimpleNamespace(symbol_names=symbols, code_ranges={}, epoch=epoch)
        return disasm.function_name_by_pc(image, fr)

    e313 = versions._EPOCHS[DART_3_13]
    throw, null, rng = ("_iso_stub_ThrowStub", "_iso_stub_NullErrorSharedWithFPURegsStub",
                        "_iso_stub_RangeErrorSharedWithFPURegsStub")
    # no symbol table, which is every release build so far: the roots' names
    assert names(e313, {}, {0x10: throw}) == {0x10: throw}
    # a symbol table that agrees, beside a function symbol it does not touch
    assert names(e313, {0x10: "stub Throw", 0x40: "Foo.bar"}, {0x10: throw}) == {
        0x10: throw, 0x40: "Foo.bar"}
    # no roots to compare with: the symbols, spelled so a throw is still a throw
    got = names(e313, {0x10: "stub NullErrorSharedWithFPURegs (#2)"}, {})
    assert got == {0x10: null} and _classify_stub(got[0x10]) == ("throw_err", "NullError")
    # the roots put NullError where the compiler wrote RangeError: the roots are wrong
    # for this binary, so none of their names is used
    assert names(e313, {0x10: "stub RangeErrorSharedWithFPURegs"},
                 {0x10: null, 0x20: throw}) == {0x10: rng}
    # a stub the roots do not have, and a stub where the compiler wrote a function
    assert names(e313, {0x10: "stub Throw", 0x30: "stub ReThrow"}, {0x10: throw}) == {
        0x10: throw, 0x30: "_iso_stub_ReThrowStub"}
    assert names(e313, {0x10: "Foo.bar"}, {0x10: throw, 0x20: null}) == {0x10: "Foo.bar"}

    e312 = versions._EPOCHS[KNOWN_HASH]
    assert names(e312, {0x10: "stub _iso_stub_ThrowStub"},
                 {0x10: "_iso_stub_ReThrowStub", 0x20: throw}) == {
        0x10: "stub _iso_stub_ThrowStub", 0x20: throw}

    # 3.13 sizes a closure by its captured slots and has a stub per size; each still
    # allocates a Closure, and 3.12's single stub reads as it did.
    for n in range(1, 5):
        assert _classify_stub(f"_iso_stub_AllocateClosure{n}Stub") == ("alloc", "Closure")
    assert _classify_stub("_iso_stub_AllocateClosureStub") == ("alloc", "Closure")


def test_dart_3_13_is_registered_for_what_was_checked_and_nothing_else():
    """The epoch claims arm64 and x64 compressed, the grammar the one real binary has.

    An uncompressed 3.13 snapshot (iOS, arm32) is a known release on a target nothing
    has read, so it is refused by name rather than parsed on the strength of android."""
    from jadart import versions
    from jadart.cidtables import ERA_3_9, ERA_3_13
    from jadart.objstore import LAYOUTS

    epoch = versions._EPOCHS[DART_3_13]
    feats = "product no-dwarf_stack_traces_mode arm64 android compressed-pointers"
    got = versions.resolve(DART_3_13, feats)
    assert got.epoch is epoch and str(got.arch) == "arm64/compressed-pointers"
    for target, arch in (("arm64 ios", "arm64"), ("arm android", "arm")):
        with pytest.raises(versions.UnsupportedTarget) as e:
            versions.resolve(DART_3_13, f"product {target} no-compressed-pointers")
        # The reason is the missing evidence, not a missing reader: the uncompressed
        # grammar is the one every older epoch uses on iOS and arm32.
        assert (f"No {arch}/uncompressed-pointers build of Dart 3.13.0 has passed the "
                f"acceptance gates") in str(e.value), str(e.value)
        assert "RODataDeserializationCluster" not in str(e.value)
    assert versions.known_epochs()[-1] is epoch, "3.13.0 is the newest release registered"

    # The cid table is 3.12's with LinkedHashBase given a cid at 96 and everything from
    # there up one higher (class_id.h at 3.13.0, through tools/gen_cids.py).
    assert ERA_3_13.num_predefined == ERA_3_9.num_predefined + 1 == 176
    assert ERA_3_13.names[96] == "LinkedHashBaseCid"
    for cid, name in ERA_3_9.names.items():
        assert ERA_3_13.names[cid if cid < 96 else cid + 1] == name
    assert (epoch.td_int8_cid, epoch.td_byte_data_view_cid) == (113, 169) == (
        ERA_3_13.cid("TypedDataInt8ArrayCid"), ERA_3_13.cid("ByteDataViewCid"))

    # The root layout is the generated one, and it hangs together without the SDK: the
    # 173 stubs are one run that ends where the six API handles begin, the class table
    # follows them, and it holds every predefined cid from Class up but the eleven
    # IsAbsentCid names.
    roots = LAYOUTS["3.13.0"]
    assert epoch.roots is roots and roots.count == 1689 and not roots.unnamed
    assert sorted(roots.stubs) == list(range(1178, 1351))
    assert roots.class_base == max(roots.stubs) + 1 + 6 == 1357
    absent = {"ObjectCid", "ErrorCid", "CallSiteDataCid", "AbstractTypeCid",
              "FinalizerBaseCid", "TypedDataBaseCid", "TypedDataCid",
              "ExternalTypedDataCid", "TypedDataViewCid", "StringCid", "FfiStructCid"}
    assert list(roots.class_cids) == [c for c in range(ERA_3_13.cid("ObjectCid"), 176)
                                      if ERA_3_13.names[c] not in absent]
    assert len(roots.class_cids) == 161
    assert roots.class_base + 161 + 171 == roots.count, "then the 171 ObjectStore fields"
    # Before 3.13 the roots hold no class table, and the layouts say so.
    assert all(l.class_base == -1 and not l.class_cids
               for dart, l in LAYOUTS.items() if dart != "3.13.0")


def test_dart_3_13_passes_the_gates_on_a_real_app():
    """Registering the hash claims the format; the gates on a real binary earn it.

    FluffyChat's F-Droid build is the only 3.13 snapshot there is to check against, and
    it is a stranger's file, so it is read where tools/appsweep.py caches it and this
    skips where it is not. Beyond the gates it pins the things 3.13 moved that no gate
    reads: the root run ends exactly where the field tables begin and those end on the
    dispatch table, the Code-typed roots are the 173 stub handles and nothing else, and
    a stub named as a throw has no `ret` in it."""
    if not os.path.exists(FLUFFYCHAT):
        _skip("  SKIP test_dart_3_13_passes_the_gates_on_a_real_app (no appsweep cache)")
    if not _capstone_available():
        _skip("  SKIP test_dart_3_13_passes_the_gates_on_a_real_app (no capstone)")
    from jadart.disasm import disassemble_range, load_instructions
    from jadart.dispatch import find_dispatch_table
    from jadart.expr import _classify_stub
    from jadart.objstore import stub_names
    from jadart.snapshot import parse_libapp_with_anchor, walk_isolate
    from jadart.stream import ReadStream
    from jadart.verify import verify_file

    heads, anchor = parse_libapp_with_anchor(FLUFFYCHAT)
    assert list(heads) == ["isolate"], "one snapshot, and no vm one"
    hdr = heads["isolate"]
    assert (hdr.version_hash, hdr.epoch.dart, hdr.kind_name) == (
        DART_3_13, "3.13.0", "kFullAOT")
    assert hdr.num_base_objects == 7 and anchor["symbol"] == "_kDartSnapshotText"

    rep = verify_file(FLUFFYCHAT)
    ran = [g for g in rep.tier_a if not g.skipped]
    bad = [g.gate for g in ran if not g.passed]
    assert rep.supported and not bad, f"Tier A gates failed: {bad}"
    assert len(ran) == 13, [g.gate for g in rep.tier_a if g.skipped]
    checks = {g.gate: g.checks for g in ran}
    assert checks["G3 class table roots vs class ids"] == 161
    assert checks["G16 stub roots vs Code fill refs"] == 2
    assert checks["G17 sized alloc/fill lengths"] == 456      # 454 closures, 2 empties
    tier_b = [g for g in rep.gates if g.tier == "B"]
    assert len(tier_b) == 3 and all(g.passed and not g.skipped for g in tier_b)

    image, fr, hdr = load_instructions(FLUFFYCHAT)
    assert image.anchor_symbol == "_kDartSnapshotText" and image.first_code == 0
    assert len(image.pcs) == hdr.instr_table_len == 88618
    assert len(fr.classes) == 10713
    # Nine small clusters sit ahead of the canonical String one, and the pool the code
    # indexes is the second ObjectPool: the first is the empty pool, with no entries.
    assert len(fr.strings) == 106075 and len(fr.pool) == 81174
    assert len(walk_isolate(FLUFFYCHAT)["strings"]) == 106038

    # Roots, the two field tables, then the dispatch table, with no byte between them.
    layout = hdr.epoch.roots
    st = ReadStream(image.data, fr.end_pos)
    roots = [st.read_ref_id() for _ in range(layout.count)]
    for _table in range(2):
        for _ in range(st.read_unsigned()):
            st.read_ref_id()
    found = find_dispatch_table(image.data, fr.end_pos, image.data_length,
                                fr.code_first_ref, len(image.pcs) + 1)
    assert found is not None and st.pos == found[0]
    codes = {ref for ref, _owner, _ci in fr.codes}
    assert {i for i, ref in enumerate(roots) if ref in codes} == set(layout.stubs)

    names = stub_names(image, fr, hdr.epoch)
    assert len(names) == 173 and len(set(names.values())) == 173
    ranges = {cr.pc_offset: cr for cr in image.all_ranges}
    seen = {}
    for pc, nm in sorted(names.items()):
        kind = _classify_stub(nm)[0]
        seen[kind] = seen.get(kind, 0) + 1
        mns = [mn for _a, mn, _op in disassemble_range(image, ranges[pc])]
        if kind in ("throw", "rethrow", "throw_err"):
            assert "ret" not in mns, (nm, "named as a throw and it returns")
    assert (seen["throw"], seen["rethrow"], seen["throw_err"]) == (1, 1, 15)
    assert _classify_stub("_iso_stub_AllocateClosure2Stub") == ("alloc", "Closure")

    # 3.13 no longer writes the `_iso_stub_` spelling into a symbol table, so where a
    # build keeps one the roots' name has to win, or the lifter stops seeing the stub.
    # This build keeps none, so one is put there the way 3.13 would spell it.
    from jadart.disasm import function_name_by_pc
    throw = next(pc for pc, nm in names.items() if nm == "_iso_stub_ThrowStub")
    image.symbol_names = {throw: "stub Throw"}
    assert function_name_by_pc(image, fr)[throw] == "_iso_stub_ThrowStub"



# -- #240: the class `this` is, for a method whose owner is a PatchClass --

def _patch_owned(fr, lay):
    """(ref, name, wrapped class ref, kind_tag) of every Function a PatchClass owns."""
    classes = set(lay.class_name)
    return [(ref, fr.names.get(nr, ""), fr.patch_class[ow], kt)
            for ref, nr, ow, kt in fr.functions
            if ow not in classes and fr.patch_class.get(ow) in classes]


def test_a_method_owned_by_a_patch_class_is_given_the_class_it_wraps():
    # `Function.owner` is a Class or a PatchClass, and `Function::Owner` (object.cc:11358)
    # resolves the second to the class it wraps. A PatchClass owns a member whose script
    # is not its class's: what a mixin application takes from its mixin, and what a patch
    # file adds to a core class. Reading the owner as a Class only left those methods
    # with no receiver class, so nothing off `this` in them could carry a name.
    from jadart.disasm import load_instructions
    from jadart.fields import recover_fields
    image, fr, hdr = load_instructions(CLEAN)
    lay = recover_fields(fr, hdr.arch)
    owned = _patch_owned(fr, lay)
    # SemanticsAnnotationsMixin's own source says what the slot is: `late bool
    # _container`, read by describeSemanticsConfiguration, whose owner is a PatchClass.
    ref, cls = next((ref, cls) for ref, nm, cls, _kt in owned
                    if nm == "describeSemanticsConfiguration"
                    and "SemanticsAnnotationsMixin" in lay.class_name[cls])
    names = lay.for_function(ref)
    assert names.get(0x58, "").startswith("_container@"), names
    assert lay.patch_refused == "", lay.patch_refused
    assert lay.patched >= 350, lay.patched
    placed = [f for f in owned if f[0] in lay.func_owner]
    assert len(placed) == lay.patched, (len(placed), lay.patched)
    assert all(lay.func_owner[r] == c for r, _n, c, _kt in placed)
    _needs_capstone()                   # the layout half above is stdlib; the body is not
    cr = image.code_ranges[ref]
    at = f"{image.anchor_va + cr.pc_offset:#x}"
    body = "\n".join(jadart.decompile(CLEAN, at)[0]["body"])
    assert "this._container@" in body and "this._explicitChildNodes@" in body, body
    assert "this.field_0x58" not in body, body
    # A slot of the same object whose Field was tree-shaken keeps its offset, and so does
    # every base that is not the receiver: the hop names a class, not a register.
    assert "a1.field_0x18 = this._explicitChildNodes@" in body, body


def test_a_patch_owner_is_followed_only_for_a_function_that_takes_a_receiver():
    # The hop is a statement about `this`, so it needs the function to have one. A static
    # method or a factory says so in its StaticBit; a closure's first argument is the
    # closure and a forwarder takes its arguments off the stack, which the kind says.
    from jadart.disasm import load_instructions
    from jadart.fields import _RECEIVER_KINDS, recover_fields
    from jadart.program import _FUNCTION_KINDS, static_bit
    for lib in (CLEAN, OBF):
        image, fr, hdr = load_instructions(lib)
        lay = recover_fields(fr, hdr.arch)
        sb = static_bit(fr)
        assert sb is not None
        declined = 0
        for ref, _nm, _cls, kt in _patch_owned(fr, lay):
            takes = (not (kt >> sb) & 1) and _FUNCTION_KINDS[kt & 0x1F] in _RECEIVER_KINDS
            assert (ref in lay.func_owner) == takes, (lib, ref, kt)
            assert bool(lay.for_function(ref)) <= takes, (lib, ref)
            declined += not takes
        assert declined == lay.patch_declined and declined >= 600, (lib, declined)


def test_no_patch_owner_is_followed_where_the_static_bit_does_not_calibrate():
    # The refusal that two of six real apps take. `program.static_bit` solves for the bit
    # and returns None when no single bit fits its witnesses; every caller then treats
    # every function as an instance method, which is the direction that prints a
    # receiver's field name off a static function's first argument. The hop must not add
    # to that: with no bit there is nothing saying which functions take a receiver.
    from jadart.disasm import load_instructions
    from jadart.fields import recover_fields
    from jadart.program import _KIND_INDEX, static_bit
    image, fr, hdr = load_instructions(CLEAN)
    good = recover_fields(fr, hdr.arch)
    assert any(good.for_function(r) for r, *_ in _patch_owned(fr, good)), (
        "nothing is placed with the bit calibrated, so the refusal below says nothing")
    sb = static_bit(fr)
    at = next(i for i, (_r, _n, _o, kt) in enumerate(fr.functions)
              if (kt & 0x1F) == _KIND_INDEX["ImplicitGetter"])
    saved = fr.functions[at]
    fr.functions[at] = saved[:3] + (saved[3] | (1 << sb),)   # one witness contradicts it
    try:
        assert static_bit(fr) is None
        bad = recover_fields(fr, hdr.arch)
        owned = _patch_owned(fr, bad)
    finally:
        fr.functions[at] = saved
    assert bad.patched == 0 and "static bit" in bad.patch_refused, bad.patch_refused
    assert owned and not any(ref in bad.func_owner for ref, _n, _c, _kt in owned)
    assert not any(bad.for_function(ref) for ref, _n, _c, _kt in owned)
    # and the functions a Class owns are where they were, which is all that is left
    class_owned = {ref: ow for ref, _n, ow, _kt in fr.functions if ow in good.class_name}
    assert bad.func_owner == {r: c for r, c in class_owned.items() if c in bad.class_name}
    assert set(good.func_owner) - set(bad.func_owner) == {r for r, *_ in owned
                                                          if r in good.func_owner}


def test_one_patch_owner_its_own_signature_contradicts_places_none_of_them():
    # Teeth, and the second encoding. An instance function's `parameter_types[0]` is its
    # receiver's own type, written by the FunctionType cluster and resolved through a
    # Type's class id, so it shares nothing with `PatchClass.wrapped_class` but the
    # answer. Pointing ONE PatchClass at another class must refuse every hop, on the
    # argument `recover_fields` makes for an offset outside its owner: they were all
    # read the same way.
    from jadart.disasm import load_instructions
    from jadart.fields import _receiver_type_class, recover_fields
    image, fr, hdr = load_instructions(CLEAN)
    good = recover_fields(fr, hdr.arch)
    by_cid = {cid & 0xFFFFFFFF: ref for ref, _n, cid, _s in fr.classes}
    owner_of = {ref: ow for ref, _n, ow, _kt in fr.functions}
    victim = next(ref for ref in good.func_owner
                  if owner_of[ref] in fr.patch_class
                  and _receiver_type_class(fr, ref, by_cid) == good.func_owner[ref])
    patch = owner_of[victim]
    saved = fr.patch_class[patch]
    other = next(ref for ref in good.by_class if ref != saved)
    fr.patch_class[patch] = other
    try:
        bad = recover_fields(fr, hdr.arch)
        owned = _patch_owned(fr, bad)
    finally:
        fr.patch_class[patch] = saved
    assert bad.patch_disagreed >= 1 and bad.patched == 0, bad
    assert "another class" in bad.patch_refused, bad.patch_refused
    assert len(owned) > 300 and not any(bad.for_function(r) for r, _n, _c, _kt in owned)


def test_every_patch_owner_agrees_with_the_receiver_its_signature_declares():
    # N of N on both fixtures, and a control that says the comparison is reading what it
    # claims to: a function a CLASS owns has to agree with its signature as well, which
    # pins `Epoch.ftype_params_index` (one slot off reads result_type or the parameter
    # names, and nothing would agree).
    from jadart.disasm import load_instructions
    from jadart.fields import _RECEIVER_KINDS, _receiver_type_class, recover_fields
    from jadart.program import _FUNCTION_KINDS, static_bit
    for lib, want, control in ((CLEAN, 20, 350), (OBF, 15, 190)):
        image, fr, hdr = load_instructions(lib)
        lay = recover_fields(fr, hdr.arch)
        assert lay.patch_disagreed == 0 and not lay.patch_refused, (lib, lay)
        assert lay.patch_agreed >= want, (lib, lay.patch_agreed)
        sb = static_bit(fr)
        by_cid = {cid & 0xFFFFFFFF: ref for ref, _n, cid, _s in fr.classes}
        agree = differ = 0
        for ref, _nr, ow, kt in fr.functions:
            if ow not in by_cid.values() or (kt >> sb) & 1:
                continue
            if _FUNCTION_KINDS[kt & 0x1F] not in _RECEIVER_KINDS:
                continue
            said = _receiver_type_class(fr, ref, by_cid)
            if said is not None:
                agree += said == ow
                differ += said != ow
        assert differ == 0 and agree >= control, (lib, agree, differ)


def test_parameter_types_is_read_from_the_slot_each_release_keeps_it_in():
    # `hash` is UntaggedFunctionType's last pointer through 3.0.6 and
    # UntaggedAbstractType's second from 3.1.5, so the four pointers after it sit one
    # slot later from 3.1 on. Read off raw_object.h for all nineteen registered releases,
    # and checked here by the RELEASE each epoch is, not by the family name the table
    # is keyed on, so a family registered under the wrong name fails.
    from jadart import versions
    seen = set()
    for ep in versions._EPOCHS.values():
        major, minor = (int(x) for x in re.match(r"(\d+)\.(\d+)", ep.dart).groups())
        early = (major, minor) < (3, 1)
        assert ep.ftype_params_index == (3 if early else 4), (ep.name, ep.dart)
        seen.add(early)
    assert seen == {True, False}


# -- incoming arguments named by the register they arrived in (#255) ----------------

def _rows(rows):
    """(addr, mn, op, note) from (mn, op) or (mn, op, note) rows, from address 0."""
    return [(i * 4, r[0], r[1], r[2] if len(r) > 2 else "") for i, r in enumerate(rows)]


def test_an_incoming_argument_is_named_by_the_register_it_arrived_in():
    """The body read its arguments as the registers they came in, `if (x2 > ...)`, while
    the arity pass already knew x2 was the second register argument. The source is in
    flubench/app/lib/constructs.dart, so each name below has a right answer."""
    if not _capstone_available():
        _skip("test_an_incoming_argument_is_named_by_the_register_it_arrived_in"
              " (no capstone)")
    got = {f["name"]: f for f in jadart.decompile(CLEAN, "benchWithdraw")}
    f = got["benchWithdraw"]                   # bool benchWithdraw(int amount)
    assert f["params"] == "a1", f
    assert "if (a1 > this.field_0x8) {" in f["body"], f["body"]
    assert "this.field_0x8 -= a1;" in f["body"], f["body"]
    # a static function's first register argument is a0, not `this`
    f = jadart.decompile(CLEAN, "benchCheckSecret")[0]       # (String input)
    assert f["params"] == "a0" and f["body"] == [
        'return a0.sel_0x0("FLUBENCH{str_literal_compare}");'], f
    f = jadart.decompile(CLEAN, "benchMakePair")[0]          # (int id, String name)
    assert f["params"] == "a0, a1", f
    # a generic function takes its arguments on the stack: no register is named and the
    # list says it was not read, the spelling a call whose list is not read already has
    f = jadart.decompile(CLEAN, "benchFirstOrDefault")[0]
    assert f["params"] == "...", f
    assert not any(re.search(r"\ba[0-5]\b", ln) for ln in f["body"]), f["body"]
    # ...and the names are declared where the body is shown
    from jadart.program import decompile_class
    out = decompile_class(CLEAN, "BenchAccount")
    assert "  benchWithdraw(a1) {  //" in out, out
    assert "if (a1 > this.field_0x8) {" in out, out
    # The other tiers print the machine's registers, so their brackets stay empty.
    assert "  benchWithdraw() {  //" in decompile_class(CLEAN, "BenchAccount", tier=2)


def test_entry_args_reads_past_a_gap_and_declines_with_the_count():
    """`entry_arity` counts the LEADING run of argument registers read on entry, because a
    call site prints a list and a list cannot skip a slot. A name can: a register read
    before any write holds what the caller left in it whether or not the one before it
    was read. `classify(int score)` never touches `this`, so its count is 0 and x2 is
    still its argument. Every reason the count has to decline holds for the names."""
    from jadart.expr import entry_arity, entry_args
    ann = _rows([("ldur", "x0, [x2, #7]"), ("ldur", "x3, [x3, #7]"),
                 ("add", "x0, x0, x3"), ("ret", "")])
    assert entry_arity(ann) == 0 and entry_args(ann) == ("x2", "x3")
    ann = _rows([("ldur", "x0, [x1, #7]"), ("ldur", "x2, [x2, #7]"),
                 ("add", "x0, x0, x2"), ("ret", "")])
    assert entry_arity(ann) == 2 and entry_args(ann) == ("x1", "x2")
    ann = _rows([("ldur", "x0, [x1, #7]"), ("ldur", "x4, [x4, #7]"),   # ARGS_DESC_REG
                 ("add", "x0, x0, x4"), ("ret", "")])
    assert entry_arity(ann) is None and entry_args(ann) == ()
    if not _capstone_available():
        _skip("test_entry_args_reads_past_a_gap_and_declines_with_the_count"
              " (no capstone)")
    # On the fixture: an instance method that reads x2 and never `this` is named a1 all
    # the same, and its signature lists it. 101 such methods on this build.
    from jadart.disasm import load_instructions
    from jadart.expr import make_arity_resolver
    from jadart.program import EntryNames, static_function_refs
    image, fr, hdr = load_instructions(CLEAN)
    arity = make_arity_resolver(image)
    entry = EntryNames(image, fr, hdr.epoch, arity)
    statics = static_function_refs(fr)
    owners = {ref for ref, _n, _o, _k in fr.functions} - statics
    gap = [cr for cr in image.all_ranges
           if cr.owner_ref in owners and arity(cr.pc_offset) == 0
           and arity.args(cr.pc_offset) == ("x2",)]
    assert len(gap) >= 100, len(gap)
    for cr in gap:
        assert entry.names(cr) == {"x1": "this", "x2": "a1"}, (cr, entry.names(cr))
        assert entry.params(cr) == "a1"


def test_a_name_holds_only_while_the_register_holds_what_it_came_in_with():
    """The one defect this must never ship: an argument's name on a register that no
    longer holds the argument. The name rides the receiver alias, so a register the walk
    has recorded on ANY path, written, clobbered by a call, dropped at a join, forgotten
    at a loop, reads as the lifter always read it: bare, or by a fresh name."""
    from jadart.expr import lift_function
    names = {"x1": "this", "x2": "a1", "x5": "a3"}

    def lift(rows, **kw):
        return "\n".join(lift_function(_rows(rows), receiver=names, **kw))
    # rewritten on the straight line: the value that was moved in
    assert lift([("mov", "x2, x5"), ("ldur", "x0, [x2, #7]"), ("ret", "")]) == (
        "  return a3.field_0x8;")
    # rewritten on one arm of a join: bare after it
    body = lift([("cbz", "x3, #0xc"), ("mov", "x2, x5"), ("b", "#0xc"),
                 ("ldur", "x0, [x2, #7]"), ("ret", "")])
    assert "x2.field_0x8" in body and "a1" not in body, body
    # destroyed by a call: a fresh name for a value nobody knows, never the argument
    body = lift([("bl", "#0x100", "  ; -> foo"), ("ldur", "x0, [x2, #7]"), ("ret", "")])
    assert "return t0.field_0x8;" in body and "a1" not in body, body
    # ...unless it was spilled before the call and reloaded after it, which is what the
    # compiler does with an argument it needs on both sides
    body = lift([("stur", "x2, [x29, #-8]"), ("bl", "#0x100", "  ; -> foo"),
                 ("ldur", "x2, [x29, #-8]"), ("ldur", "x0, [x2, #7]"), ("ret", "")])
    assert body.endswith("  return a1.field_0x8;"), body
    # rewritten by a loop: the carried name starts from the argument, and after the loop
    # the register reads as that name, never as the argument
    body = lift([("ldur", "x0, [x2, #7]"), ("add", "x2, x2, #8"), ("subs", "x3, x3, #1"),
                 ("b.ne", "#0x0"), ("ldur", "x0, [x2, #7]"), ("ret", "")])
    assert "var t0 = a1;" in body and "return t0.field_0x8;" in body, body
    assert "a1.field" not in body, body
    # A block no path from the entry reaches is handed no entry name. A catch block is
    # entered with the exception in x0 and the stack trace in x1, and `_run` on the
    # clean fixture printed `_list2(x0, this)` for the two of them.
    body = lift([("mov", "x0, x2"), ("bl", "#0x100", "  ; -> _iso_stub_ThrowStub"),
                 ("brk", "#0"), ("ldur", "x0, [x2, #7]"), ("ret", "")])
    assert "throw a1;" in body and "return x2.field_0x8;" in body, body
    body = lift([("bl", "#0x100", "  ; -> _iso_stub_ThrowStub"), ("brk", "#0"),
                 ("ldur", "x0, [x1, #7]"), ("ret", "")])
    code = "\n".join(ln for ln in body.splitlines() if not ln.strip().startswith("//"))
    assert "return x1.field_0x8;" in body and "this" not in code, body
    # A type-testing stub hands back x0, x1, x2 and x8 and nothing else
    # (TypeTestABI::kPreservedAbiRegisters), so x5 after one is not the argument.
    body = lift([("bl", "#0x100", "  ; -> _iso_stub_DefaultTypeTestStub"),
                 ("ldur", "x0, [x5, #7]"), ("ret", "")])
    assert body == "  return x5.field_0x8;", body
    body = lift([("bl", "#0x100", "  ; -> _iso_stub_DefaultTypeTestStub"),
                 ("ldur", "x0, [x1, #7]"), ("ldur", "x3, [x2, #7]"),
                 ("add", "x0, x0, x3"), ("ret", "")])
    assert body == "  return this.field_0x8 + a1.field_0x8;", body
    # ...and the same holds for a register that came to hold a name some other way: a
    # copy of an argument, a reload of one from its frame slot, or a copy of `this`.
    tts = ("bl", "#0x100", "  ; -> _iso_stub_DefaultTypeTestStub")
    for rows, reg in (([("mov", "x5, x2"), tts], "x5"),
                      ([("stur", "x5, [x29, #-8]"), ("bl", "#0x200", "  ; -> foo"),
                        ("ldur", "x5, [x29, #-8]"), tts], "x5"),
                      ([("mov", "x3, x1"), tts], "x3")):
        body = lift(rows + [("ldur", f"x0, [{reg}, #7]"), ("ret", "")])
        assert body.endswith(f"  return {reg}.field_0x8;"), body
    # A box-or-tag check is lifted down its fast path, and the Mint path it cuts calls a
    # stub whose fast path uses x1 as its temporary (AllocateMintABI::kTempReg), so x1
    # past the join is not `this`.
    body = lift([("sbfiz", "x0, x2, #1, #0x1f"), ("cmp", "x2, x0, asr #1"),
                 ("b.eq", "#0x14"),
                 ("bl", "#0x100",
                  "  ; -> _iso_stub_AllocateMintSharedWithoutFPURegsStub"),
                 ("stur", "x2, [x0, #7]"), ("ldur", "x0, [x1, #7]"), ("ret", "")])
    assert body.endswith("  return x1.field_0x8;") and "this" not in body, body


def test_no_argument_is_named_where_the_code_is_not_a_dart_functions():
    """A name rests on three facts: the release passes arguments in registers, the code
    is a function's of a kind the VM calls that way, and the body reads the register
    before writing it. Take any one away and the register stays bare."""
    if not _capstone_available():
        _skip("test_no_argument_is_named_where_the_code_is_not_a_dart_functions"
              " (no capstone)")
    import types
    from jadart.disasm import load_instructions
    from jadart.expr import make_arity_resolver
    from jadart.hooks import STACK_KINDS
    from jadart.program import EntryNames, _FUNCTION_KINDS
    image, fr, hdr = load_instructions(CLEAN)
    arity = make_arity_resolver(image)
    entry = EntryNames(image, fr, hdr.epoch, arity)
    kind = {ref: _FUNCTION_KINDS[kt & 0x1F] for ref, _n, _o, kt in fr.functions}
    classes = {ref for ref, *_ in fr.classes}
    named = stack = other = 0
    for cr in image.all_ranges:
        has = any(v != "this" for v in entry.names(cr).values())
        named += has
        if cr.owner_ref in kind and kind[cr.owner_ref] in STACK_KINDS:
            stack += 1
            assert not has, (cr, kind[cr.owner_ref])       # closures, dispatchers, ...
        elif cr.owner_ref not in kind:
            other += 1
            assert not has, cr                              # allocation and type stubs
            assert cr.owner_ref in classes or cr.owner_ref in fr.types or (
                "_iso_stub_" in (image.symbol_names or {}).get(cr.pc_offset, "")
                or cr.owner_ref != -1), cr
    assert named >= 2000 and stack >= 1000 and other >= 1300, (named, stack, other)
    # the release: before 3.4 nothing arrives in a register
    old = types.SimpleNamespace(dart="3.3.4", cid_table=hdr.epoch.cid_table)
    cr = next(c for c in image.all_ranges if c.owner_ref in kind
              and entry.params(c) == "a1")
    assert EntryNames(image, fr, old, arity).names(cr) == {"x1": "this"}
    assert EntryNames(image, fr, old, arity).params(cr) == "..."
    # a resolver with no `args` (a test's lambda) names nothing and lists nothing
    assert EntryNames(image, fr, hdr.epoch, lambda pc: 2).names(cr) == {"x1": "this"}


def test_discarded_code_on_an_obfuscated_build_is_still_a_functions():
    """`--obfuscate` drops the Function and keeps its Code with no owner. Only a Dart
    function's Code is discarded (precompiler.cc, DiscardCodeObjects), so those ranges
    are named too, and they are exactly the table entries below first_entry_with_code."""
    if not _capstone_available():
        _skip("test_discarded_code_on_an_obfuscated_build_is_still_a_functions"
              " (no capstone)")
    from jadart.disasm import load_instructions
    from jadart.expr import make_arity_resolver
    from jadart.program import EntryNames
    image, fr, hdr = load_instructions(OBF)
    entry = EntryNames(image, fr, hdr.epoch, make_arity_resolver(image))
    below = set(image.pcs[:image.first_code])
    named = 0
    for cr in image.all_ranges:
        if cr.owner_ref != -1:
            continue
        assert cr.pc_offset in below, cr
        names = entry.names(cr)
        # No Function owns these, so nothing says x1 is a receiver: it is `a0` where the
        # body reads it, never `this` (#259).
        assert set(names.values()) <= {"a0", "a1", "a2", "a3", "a4", "a5"}, names
        named += bool(names)
    assert named >= 1500, named


def test_irfuzz_scores_an_argument_name_as_the_value_the_register_came_in_with():
    """`tools/irfuzz.py --args` lifts the generated graphs with the six argument registers
    named and binds each name to the register's entry value, so a name printed where the
    register no longer holds it disagrees with the CPU. Without the flag such a read
    prints the bare register and declines, so the oracle never asked. The teeth: put a
    loop's forget back and the same graphs disagree."""
    if not _capstone_available():
        _skip("test_irfuzz_scores_an_argument_name_as_the_value_the_register_came_in_"
              "with")
    sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "tools"))
    import irfuzz
    from jadart import expr
    if irfuzz._unicorn() is None:
        _skip("test_irfuzz_scores_an_argument_name_as_the_value_the_register_came_in_"
              "with (no unicorn)")
    assert irfuzz.run_cfg(200, 25, 1, False, args=True) == 0, "argument names disagree"
    orig = expr.Lifter._render_loop

    def leaky(self, header, body, st, indent, depth):
        out = orig(self, header, body, st, indent, depth)
        for r in list(st.reg):
            if r in self.alias and st.reg[r].text == r:
                del st.reg[r]               # the loop wrote it; forget that it did
        return out
    expr.Lifter._render_loop = leaky
    try:
        assert irfuzz.run_cfg(200, 25, 1, False, args=True) != 0, (
            "a register the loop rewrote read as the argument and the oracle did not see")
    finally:
        expr.Lifter._render_loop = orig


def _graphs_282():
    """(name, rows, base, mono, tier 3) for #282's two tests: loops in a row, nested
    loops, a cycle with two ways in, a monomorphic entry rooting a second tree with a
    loop and a join in its body and a section after it that no edge reaches, and a loop
    one way into which traps, built with no block ending there: `_ridom`, the forest
    of the graph where it does, has the loop's head under the other way in."""
    row = []
    for _ in range(4):
        row += [("add", "x2, x2, #1"), ("cmp", "x2, x1"), ("b.lt", f"#{len(row) * 4:#x}")]
    nest = [("add", f"x{2 + i}, x{2 + i}, #1") for i in range(4)]
    for i in range(4):
        nest += [("cmp", "x2, x1"), ("b.lt", f"#{(3 - i) * 4:#x}")]
    two_ways = [("cbz", "x0, #0x10"), ("add", "x1, x1, #1"), ("cmp", "x1, x2"),
                ("b.ge", "#0x1c"), ("add", "x3, x3, #1"), ("cmp", "x3, x4"),
                ("b.lt", "#0x4")]
    mono = _MONO_ROWS[:6] + [
        ("mov", "x2, #0"), ("add", "x2, x2, #1"), ("cmp", "x2, x1"), ("b.lt", "#0x101c"),
        ("cbz", "x2, #0x1034"), ("mov", "x0, x2"), ("ret", ""), ("mov", "x0, #1"),
        ("ret", ""), ("add", "x5, x5, #1"), ("cmp", "x5, x1"), ("b.lt", "#0x103c")]
    trap = [("cbz", "x0, #0xc"), ("brk", "#0"), ("b", "#0x14"), ("add", "x1, x1, #1"),
            ("add", "x2, x2, #1"), ("sub", "x9, x9, #1"), ("cbnz", "x9, #0x14")]
    return [("in a row", row + [("ret", "")], 0, None, True),
            ("nested", nest + [("ret", "")], 0, None, True),
            ("two ways in", two_ways + [("ret", "")], 0, None, True),
            ("second root", mono + [("ret", "")], 0x1000, 0x1008, True),
            ("trap", trap + [("ret", "")], 0, None, False)]


def test_dominance_by_numbers_answers_what_the_walk_up_idom_did():
    """A guard test (#282). Whether one block dominates another was a walk up `idom`
    from the lower, and is now a check of two numbers (cfg.dom_numbers). This holds the
    numbers to the walk: on each graph of _graphs_282, `_dominates` agrees with
    `_dominators` on every ordered pair of blocks, a block in no tree and an address
    that is no block among them; and with the lifter's numbering turned off, which is
    the walk as main had it, the loop bodies, trips, regions, join kills, structure and
    lifted lines are the same. A numbering that is no forest is refused. `structure`
    keeps no walk: the forest it numbers is always one, so its numbering stays on."""
    from jadart import cfg, expr
    from jadart.cfg import build_cfg, entry_reach, structure
    from jadart.expr import Lifter, lift_function, tier3_graph

    assert cfg.dom_numbers({1: 2, 2: 1}) is None                  # a cycle, no root
    assert cfg.dom_numbers({1: 1, 2: 3}) is None                  # an idom off the map
    pre, end, _kids = cfg.dom_numbers({1: 1, 2: 1, 3: 3, 4: 3})   # two trees
    assert pre[1] <= pre[2] < end[1] and not pre[1] <= pre[3] < end[1]

    def built(name, rows, base, mono, tier3, numbered):
        ann = [(base + i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)]
        saved = expr.dom_numbers
        if not numbered:
            expr.dom_numbers = lambda idom: None
        try:
            if tier3:
                g = tier3_graph(ann, mono=mono)
                blocks, entry, roots = g.blocks, g.entry, g.roots
            else:
                blocks, entry = build_cfg(ann, traps=())
                roots = ()
            lf = Lifter(blocks, entry=entry)
            lf.roots, lf.placed = roots, frozenset(entry_reach(blocks, entry))
            lf._dom_tree()
            got = {"stmts": structure(blocks, entry, orphans=True, entries=roots),
                   "lines": lift_function(ann, mono=mono) if tier3 else None}
            for h in sorted(blocks):
                got[h] = (lf._back_loop(h), lf._trip_nodes(h), lf._region_written(h),
                          lf._join_kill(h), lf._join_kill(h, entry=True))
            asked = sorted(blocks) + [None, max(blocks) + 4096]
            got["pairs"] = {(a, b): lf._dominates(a, b) for a in asked for b in asked}
            return lf, got
        finally:
            expr.dom_numbers = saved

    for name, rows, base, mono, tier3 in _graphs_282():
        lf, got = built(name, rows, base, mono, tier3, True)
        walk, want = built(name, rows, base, mono, tier3, False)
        assert lf._dnum is not None and lf._rnum is not None, name
        assert walk._dnum is None and walk._rnum is None, name
        for (a, b), yes in got["pairs"].items():
            assert yes == (a in lf._dominators(b)), (name, a, b, yes)
        assert got == want, name
        if name == "second root":
            assert lf.roots and any(b not in lf._idom for b in lf.blocks), lf._idom
        if name == "trap":
            assert lf._ridom != lf._idom, (lf._ridom, lf._idom)


def test_dominance_costs_the_same_per_instruction_at_any_length():
    """N loops in a row, or N nested, asked the dominator tree whether one block was above
    another once per block each loop dominates, and answered by walking `idom` up from
    the lower: 42 million steps for 500 loops in a row and 13 s at 1,000 (#282). Counted,
    not timed: each lookup on a forest dominator_forest builds, per instruction, at 30
    loops and at 120. Walking, four times the loops cost about sixteen times as many
    lookups per instruction; numbered, about as many. So too the blocks `_own_written`
    is handed: gathered per loop, each loop's region held every block it dominates, and
    folded up the tree each block is handed once."""
    from jadart import cfg, expr
    from jadart.expr import lift_function
    looks, handed = [0], [0]

    class Counted(dict):
        def get(self, k, d=None):
            looks[0] += 1
            return dict.get(self, k, d)

        def __getitem__(self, k):
            looks[0] += 1
            return dict.__getitem__(self, k)

        def __contains__(self, k):
            looks[0] += 1
            return dict.__contains__(self, k)

    forest, own = cfg.dominator_forest, expr.Lifter._own_written

    def counted(*args, **kw):
        idom, order, trees = forest(*args, **kw)
        return Counted(idom), order, trees

    def own_written(self, nodes):
        handed[0] += len(nodes)
        return own(self, nodes)

    def per_instruction(n, nested):
        if nested:
            rows = [("add", f"x{2 + i % 6}, x{2 + i % 6}, #1") for i in range(n)]
            for i in range(n):
                rows += [("cmp", "x2, x1"), ("b.lt", f"#{(n - 1 - i) * 4:#x}")]
        else:
            rows = []
            for _ in range(n):
                rows += [("add", "x2, x2, #1"), ("cmp", "x2, x1"),
                         ("b.lt", f"#{len(rows) * 4:#x}")]
        rows.append(("ret", ""))
        looks[0] = handed[0] = 0
        lift_function([(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])
        return looks[0] / len(rows), handed[0] / len(rows)
    expr.dominator_forest = cfg.dominator_forest = counted
    expr.Lifter._own_written = own_written
    try:
        for nested in (False, True):
            small, large = per_instruction(30, nested), per_instruction(120, nested)
            assert large[0] < 2 * small[0], ("lookups", nested, small, large)
            assert large[1] < 2 * small[1], ("blocks written", nested, small, large)
    finally:
        expr.dominator_forest = cfg.dominator_forest = forest
        expr.Lifter._own_written = own


def test_dominators_are_the_ones_the_iteration_found():
    """A guard test (#319). `cfg._idoms` was Cooper, Harvey and Kennedy's iteration and
    is now Lengauer and Tarjan's algorithm. This holds both of what it returns, the
    immediate dominators and the order of the walk, to the iteration as main had it,
    copied here, on 20,000 random graphs: up to three edges out of a block, edges out
    of the map, self loops, an entry that is no block, and the graphs `structure`
    builds the post-dominators over."""
    import random
    from jadart.cfg import _idoms

    def iteration(blocks, entry, succ):
        order, seen, stack = [], set(), [entry]
        while stack:
            n = stack.pop()
            if n in seen or n not in blocks:
                continue
            seen.add(n)
            order.append(n)
            stack += [s for s in succ(n) if s in blocks]
        rpo = {n: i for i, n in enumerate(order)}
        preds = {n: [] for n in order}
        for n in order:
            for s in succ(n):
                if s in preds:
                    preds[s].append(n)
        idom = {entry: entry}

        def inter(a, b):
            while a != b:
                while rpo[a] > rpo[b]:
                    a = idom[a]
                while rpo[b] > rpo[a]:
                    b = idom[b]
            return a
        changed = True
        while changed:
            changed = False
            for n in order[1:]:
                new = None
                for p in preds[n]:
                    if p in idom:
                        new = p if new is None else inter(p, new)
                if new is not None and idom.get(n) != new:
                    idom[n], changed = new, True
        return idom, order
    deep = 0
    for seed in range(20000):
        rng = random.Random(seed)
        n = rng.randrange(1, 40)
        g = {i: [rng.randrange(n + 3) for _ in range(rng.choice((0, 1, 2, 2, 3)))]
             for i in range(n)}
        if seed % 2:                    # reversed, from a virtual exit, as structure does
            r = {-1: [i for i in g if not g[i]]}
            for i, ss in g.items():
                for s in ss:
                    r.setdefault(s, []).append(i)
            g, entry, blocks = r, -1, set(range(-1, n))
        else:
            entry, blocks = rng.randrange(n + 1), set(range(n))
        want = iteration(blocks, entry, lambda x: g.get(x, []))
        assert _idoms(blocks, entry, lambda x: g.get(x, [])) == want, seed
        depth = {entry: 0}
        for b in want[1][1:]:
            d, x = 0, b
            while want[0][x] != x:
                d, x = d + 1, want[0][x]
            depth[b] = d
        deep += max(depth.values()) >= 5
    assert deep > 4000, deep


def test_dominators_cost_the_same_per_instruction_at_any_length():
    """N checks that branch to one trap after the `ret`: Cooper, Harvey and Kennedy's
    iteration met the trap's N predecessors by walking each up the dominator tree it
    had so far, a chain N deep, so building the trees cost about N * N, 1.93 s of
    `tier3_graph` at 8,000 checks where 1,000 took 0.04 (#319). Counted, not timed: the
    lines run inside `cfg._idoms`, per instruction, at 30 checks and at 120. Iterated
    that was 104 and 194; by Lengauer and Tarjan, 69 and 69."""
    from jadart import cfg
    from jadart.expr import tier3_graph
    ran, inside = [0], [0]

    def lines(frame, event, _arg):
        if event == "line":
            ran[0] += 1
        elif event == "return" and frame.f_code.co_name == "_idoms":
            inside[0] -= 1
        return lines

    def calls(frame, _event, _arg):
        code = frame.f_code
        if code.co_filename != cfg.__file__:
            return None
        if code.co_name == "_idoms":
            inside[0] += 1
        return lines if inside[0] else None

    def per_instruction(n):
        rows = [("cbz", "x9, #END"), ("add", "x2, x2, #1")] * n + [("ret", "")]
        rows = [(mn, op.replace("END", f"{len(rows) * 4:#x}")) for mn, op in rows]
        rows.append(("brk", "#0"))
        ran[0] = 0
        sys.settrace(calls)
        try:
            tier3_graph([(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])
        finally:
            sys.settrace(None)
        return ran[0] / len(rows)
    small, large = per_instruction(30), per_instruction(120)
    assert 0 < small and large < 1.5 * small, (small, large)


def _rows_289(seed):
    """(rows, base, mono) of a random range for #289's guard: branches anywhere, loops,
    gotos into loops, traps, frame stores and calls, and in a third a monomorphic
    entry."""
    import random
    rng = random.Random(seed)
    n = rng.randrange(4, 48)
    base, mono, rows = 0, None, []
    if rng.random() < 0.3:
        base, mono, rows = 0x1000, 0x1008, list(_MONO_ROWS[:6])
    start = base + len(rows) * 4
    for _ in range(n):
        r, q = f"x{rng.randrange(7)}", f"x{rng.randrange(7)}"
        t = f"#{start + rng.randrange(n + 1) * 4:#x}"
        rows.append(rng.choice([
            ("add", f"{r}, {r}, #1"), ("cmp", f"{r}, {q}"), ("b.lt", t), ("b.ne", t),
            ("cbz", f"{r}, {t}"), ("b", t), ("ret", ""), ("brk", "#0"), ("bl", "#0x100"),
            ("mov", f"{r}, {q}"), ("stur", f"{r}, [x29, #-{rng.randrange(1, 4) * 8}]"),
            ("ldur", f"{r}, [x29, #-{rng.randrange(1, 4) * 8}]"),
            ("str", f"{r}, [x0, #{rng.randrange(4) * 8 + 8}]")]))
    return rows + [("ret", "")], base, mono


def test_loop_exits_and_goto_joins_answer_what_the_walks_over_ancestors_did():
    """A guard test (#289). A loop's exit asked `_exit_slots` what every block that
    reaches the header writes, and a goto's join asked `_join_kill` what the blocks
    between it and its immediate dominator write, each by walking the blocks once per
    loop or join; both are now worked out once over the graph's strongly connected
    pieces and a walk bounded by the dominator tree. This holds them to the walks, in
    the middle of real lifts of 300 random ranges and of _graphs_282's.

    Every join is asked again by the walk as main had it. Every loop exit is asked
    again of a state holding one frame slot per register, each naming that register
    and far from any store: a slot goes where the walk over `_loop_nodes` says a block
    writes the register, and its value is recorded where no block that calls does."""
    from jadart import expr
    from jadart.expr import V, P_ATOM, State, lift_function
    regs = ([f"x{i}" for i in range(31) if f"x{i}" not in expr._SPECIAL]
            + [f"d{i}" for i in range(8)])
    exits, kill = expr.Lifter._exit_slots, expr.Lifter._join_kill
    seen = {"probed": 0, "dropped": 0, "recorded": 0, "joins": 0, "killed": 0,
            "swept": 0}

    def exit_slots(self, st, header):
        probe = State()
        for i, r in enumerate(regs):
            probe.slot[f"x29-{4096 + 8 * i}"] = V(f"{r} + 1", P_ATOM)
        exits(self, probe, header)
        if probe.slot:
            ended = self._ended_blocks()
            near = {b for b in self._loop_nodes(header)
                    if b not in ended and not self._quiet(b)}
            written = self._written(near) - expr._SPECIAL
            unsafe = self._call_written(near)
            seen["probed"] += 1
            for i, r in enumerate(regs):
                k = f"x29-{4096 + 8 * i}"
                assert (k not in probe.slot) == (r in written), (header, r)
                assert (k in probe.dropped) == (r in written and r not in unsafe), (
                    header, r)
                seen["dropped"] += k not in probe.slot
                seen["recorded"] += k in probe.dropped
        return exits(self, st, header)

    def join_kill(self, addr, entry=False):
        if not getattr(self, "swept_333", False):
            # Every block, as a join of either kind, the first time a lift asks (#333).
            self.swept_333 = True
            for a in sorted(self.blocks):
                for e in (False, True):
                    join_kill(self, a, e)
                    seen["swept"] += 1
        got = kill(self, addr, entry)
        preds = self._preds.get(addr, ())
        if entry:
            preds = [p for p in preds if not self._dominates(addr, p)]
        back, stack = set(), list(preds)
        while stack:
            n = stack.pop()
            if n in back or n == addr:
                continue
            back.add(n)
            stack.extend(self._preds.get(n, ()))
        d = self._idom.get(addr)
        if d is not None and d != addr:
            fwd, stack = set(), [s for s in self.blocks[d].succ if s in self.blocks]
            while stack:
                n = stack.pop()
                if n in fwd or n == addr:
                    continue
                fwd.add(n)
                stack.extend(s for s in self.blocks[n].succ if s in self.blocks)
            back &= fwd
        want = (frozenset(self._written(back)) - expr._SPECIAL, self._writes_stack(back),
                self._writes_heap(back))
        assert got == want, (addr, entry, got, want)
        seen["joins"] += 1
        seen["killed"] += bool(want[0])
        return got
    graphs = [_rows_289(seed) for seed in range(300)]
    graphs += [(rows, base, mono) for _n, rows, base, mono, tier3 in _graphs_282()
               if tier3]
    graphs += [_rows_333(n, form) for n in (3, 12, 40) for form in _FORMS_333]
    graphs += [_rows_333_random(seed) for seed in range(150)]
    expr.Lifter._exit_slots, expr.Lifter._join_kill = exit_slots, join_kill
    walk = getattr(expr, "_KILL_WALK", 0)        # absent on main, where every join walks
    try:
        # Folded from the first join, then walked first as a lift does (_KILL_WALK).
        for expr._KILL_WALK in (0, walk):
            for rows, base, mono in graphs:
                lift_function([(base + i * 4, mn, op, "")
                               for i, (mn, op) in enumerate(rows)], mono=mono)
    finally:
        expr.Lifter._exit_slots, expr.Lifter._join_kill = exits, kill
        expr._KILL_WALK = walk
    assert seen["probed"] > 100 and seen["joins"] > 300, seen
    assert seen["swept"] > 40000, seen
    assert seen["dropped"] > 500 and seen["recorded"] > 100 and seen["killed"] > 100, seen


def test_loop_exits_and_goto_joins_cost_the_same_per_instruction_at_any_length():
    """N loops in a row asked `_exit_slots` about every block before each one, and N
    loops each leaving by a goto into the next one's body asked `_join_kill` to walk
    back over them and on over every block after: at 2,000 loops 79% of the time was
    `_exit_slots` and the cost about N * N (#289). Counted, not timed: the lines of
    expr.py and cfg.py those two run, per instruction, at 30 loops and at 120. Walked
    per loop that was 181 and 631 for loops in a row, and 257 and 865 with the gotos;
    folded once over the graph, and walked between a join and its dominator, 62 and 62,
    and 137 and 139."""
    from jadart import cfg, expr
    from jadart.expr import lift_function
    here = {expr.__file__, cfg.__file__}
    exits, kill = expr.Lifter._exit_slots, expr.Lifter._join_kill
    ran, depth = [0], [0]

    def lines(frame, event, _arg):
        if event == "line":
            ran[0] += 1
        return lines

    def calls(frame, _event, _arg):
        return lines if frame.f_code.co_filename in here else None

    def counted(fn):
        def run(*args, **kw):
            depth[0] += 1
            if depth[0] == 1:
                sys.settrace(calls)
            try:
                return fn(*args, **kw)
            finally:
                depth[0] -= 1
                if not depth[0]:
                    sys.settrace(None)
        return run

    def per_instruction(n, goto):
        rows = []
        for _ in range(n):
            h = len(rows) * 4
            if goto:
                rows += [("add", "x2, x2, #1"), ("cbz", f"x3, #{h + 20:#x}"),
                         ("cmp", "x2, x1"), ("b.lt", f"#{h:#x}")]
            else:
                rows += [("add", "x2, x2, #1"), ("cmp", "x2, x1"), ("b.lt", f"#{h:#x}")]
        rows += [("add", "x2, x2, #1"), ("ret", "")]
        ran[0] = 0
        lift_function([(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])
        return ran[0] / len(rows)
    expr.Lifter._exit_slots = counted(exits)
    expr.Lifter._join_kill = counted(kill)
    try:
        for goto in (False, True):
            small, large = per_instruction(30, goto), per_instruction(120, goto)
            assert large < 1.5 * small, (goto, small, large)
    finally:
        expr.Lifter._exit_slots, expr.Lifter._join_kill = exits, kill


_FORMS_333 = ("plain", "loop", "mono")


def _rows_332(seed):
    """(rows, base, mono) of a random nest of loops for #332's guard: loops up to six
    deep, each with a latch at its end, between them frame and heap stores and loads,
    calls, traps and moves, and branches out of a loop, past several, back into one or
    into another's body, to anywhere; in a quarter a monomorphic entry."""
    import random
    rng = random.Random(seed)
    base, mono, rows = 0, None, []
    if rng.random() < 0.25:
        base, mono, rows = 0x1000, 0x1008, list(_MONO_ROWS[:6])
    jumps = []

    def line():
        r, q = f"x{rng.randrange(1, 8)}", f"x{rng.randrange(1, 8)}"
        return rng.choice([
            ("add", f"{r}, {r}, #1"), ("mov", f"{r}, {q}"), ("add", f"{r}, {q}, {r}"),
            ("stur", f"{r}, [x29, #-{rng.randrange(1, 5) * 8}]"),
            ("ldur", f"{r}, [x29, #-{rng.randrange(1, 5) * 8}]"),
            ("str", f"{r}, [x0, #{rng.randrange(4) * 8 + 8}]"),
            ("ldr", f"{r}, [x0, #{rng.randrange(4) * 8 + 8}]"),
            ("str", f"{r}, [sp, #8]"), ("bl", "#0x100"), ("blr", "x5"), ("brk", "#0")])

    def loop(depth):
        head = len(rows)
        rows.append(line())
        for _ in range(rng.randrange(1, 4)):
            if depth < 6 and rng.random() < 0.6:
                loop(depth + 1)
            else:
                rows.append(line())
            if rng.random() < 0.3:
                jumps.append(len(rows))
                rows.append(("cbz", f"x{rng.randrange(1, 8)}, T"))
        rows.append(("cmp", "x2, x1"))
        rows.append(("b.lt", f"#{base + head * 4:#x}"))

    for _ in range(rng.randrange(1, 3)):
        loop(0)
        rows.append(line())
    rows.append(("ret", ""))
    for i in jumps:
        mn, op = rows[i]
        rows[i] = (mn, op.replace("T", f"#{base + rng.randrange(len(rows)) * 4:#x}"))
    return rows, base, mono


def test_nested_loop_bodies_and_what_they_hold_answer_what_the_walks_did():
    """A guard test (#332). Each loop's natural body, the body a second trip runs and
    the part of it the header reaches, what the loop reads before it writes, and what
    a set of blocks writes, stores or calls, were each worked out per loop by walking
    every block of it; the bodies are now built inner loops first taking the inner
    ones in whole, the liveness folded up that nest, and the rest read once per block.
    This holds each to the walk main had, in the middle of real lifts of 300 random
    nests of loops, 300 of #289's random ranges and _graphs_282's, and holds the
    structurer's output with the bodies built whole to its output with them walked.
    A loop exit is asked again of a state holding a slot at each frame offset the
    ranges store to, as well as of the walk's."""
    from jadart import cfg, expr
    from jadart.expr import V, P_ATOM, State, lift_function
    L = expr.Lifter
    old = {n: getattr(L, n) for n in (
        "_back_loop", "_trip_nodes", "_trip_body", "_written", "_writes_heap",
        "_writes_stack", "_writes_outgoing", "_exit_slots", "_reloads", "_render_loop")}
    seen = dict.fromkeys(("bodies", "nested", "trips", "live", "slots", "reloads"), 0)
    special = expr._SPECIAL - {expr._lr()}

    def roles(name):
        return next((r for r, v in expr._T.roles.items() if v == name), None)

    def written(self, nodes):
        w = set()
        for b in nodes:
            w |= set().union(
                *(expr._def_use(mn, o)[0] for (_a, mn, o, _n) in self.blocks[b].insns),
                *(self._moved_regs(a) for (a, _m, _o, _n) in self.blocks[b].insns
                  if a in self.frame_moves))
        return w

    def stores(self, nodes):
        for b in nodes:
            for (a, mn, op, _n) in self.blocks[b].insns:
                if mn in expr._STORES or expr._raw_store(mn):
                    yield a, mn, op, expr._addr(expr._split_ops(op))

    def heap(self, nodes):
        for a, _mn, _op, got in stores(self, nodes):
            if got is None or got[1] is expr._BAD_POST:
                return True
            role = expr._T.roles.get(got[0][0])
            if role not in ("SP", "FP"):
                return True
            if role == "FP":
                if self._fp_lost_set is None:
                    self._fp_lost_set = expr._fp_lost_at(self.blocks, self.raw)
                if a in self._fp_lost_set:
                    return True
        return False

    def stack(self, nodes):
        for _a, _mn, _op, got in stores(self, nodes):
            if got is None or got[1] is expr._BAD_POST:
                return True
            if expr._T.roles.get(got[0][0]) in ("SP", "FP"):
                return True
        return self._frame_escaped()

    def outgoing(self, nodes):
        sp = roles("SP")
        for b in nodes:
            for (a, mn, op, _n) in self.blocks[b].insns:
                if mn in expr._CALLS or a in self.frame_meets or a in self.frame_moves:
                    return True
                if mn in expr._STORES or expr._raw_store(mn):
                    if self._through_frame(a, mn, op):
                        return True
                    got = expr._addr(expr._split_ops(op))
                    if got is None or got[0][0] == sp or (
                            expr._T.roles.get(got[0][0]) == "FP"
                            and got[0][2] is not None):
                        return True
                    if expr._raw_store(mn) and expr._T.roles.get(got[0][0]) in (
                            "SP", "FP"):
                        return True
        return False

    def back_walk(self, header):
        tree = self._root_of.get(header)
        nodes, stack = {header}, [p for p in self._preds.get(header, ())
                                  if p not in self._idom or self._root_of.get(p) != tree
                                  or self._dominates(header, p)]
        while stack:
            n = stack.pop()
            if n not in nodes and n in self.blocks:
                nodes.add(n)
                stack.extend(self._preds.get(n, ()))
        return nodes

    def trip_walk(self, header):
        idom, ended, num = self._ridom, self._ended, self._rnum

        def dominated(n):
            if num is not None:
                return n == header or (header in num[0] and n in num[0]
                                       and num[0][header] <= num[0][n] < num[1][header])
            while n != header:
                up = idom.get(n)
                if up is None or up == n:
                    return False
                n = up
            return True
        nodes, stack = {header}, [p for p in self._preds.get(header, ())
                                  if p not in ended and dominated(p)]
        if not stack:
            return set()
        while stack:
            n = stack.pop()
            if n not in nodes and n not in ended:
                nodes.add(n)
                stack.extend(self._preds.get(n, ()))
        return nodes

    def back_loop(self, header):
        got = old["_back_loop"](self, header)
        want = back_walk(self, header)
        assert got == want, (header, sorted(got), sorted(want))
        seen["bodies"] += 1
        seen["nested"] += any(h != header and h in got and back_walk(self, h) - {h}
                              for h in got)
        return got

    def trip_nodes(self, header):
        got = old["_trip_nodes"](self, header)
        assert got == trip_walk(self, header), header
        seen["trips"] += bool(got)
        return got

    def trip_body(self, header):
        got = old["_trip_body"](self, header)
        trip = trip_walk(self, header)
        reach, stack = set(), [header] if trip else []
        while stack:
            n = stack.pop()
            if n not in reach:
                reach.add(n)
                stack.extend(s for s in self.blocks[n].succ if s in trip)
        assert got == reach, header
        return got

    def checked(name, ref):
        def run(self, nodes):
            got = old[name](self, nodes)
            assert got == ref(self, nodes), (name, sorted(nodes))
            return got
        return run

    def exit_walk(self, st, header):
        loop = {b for b in self._back_loop(header) if not self._quiet(b)}
        fp, sp = roles("FP"), roles("SP")
        if fp is None or self._frame_escaped() or fp in written(self, loop):
            st.slot.clear()
            return
        if sp is not None:
            for k in [k for k in st.slot if k.startswith(sp)]:
                del st.slot[k]
        wide = self._wide_slots()
        for b in sorted(loop):
            insns = self.blocks[b].insns
            for (_a, mn, op, _n) in insns:
                if mn in expr._STORES:
                    got = expr._addr(expr._split_ops(op))
                    if got is None or got[1] is expr._BAD_POST:
                        st.slot.clear()
                        return
            for i, keys, delta, ops, backs in self._accesses(b):
                if delta:
                    st.slot.clear()
                    return
                if backs is not None:
                    lo = int(keys[0][len(fp):])
                    expr._drop_stored(st.slot, fp, lo, lo + expr._access_width(
                        insns[i][1], ops[0]) * len(keys))
                    for off in range(lo - 15, lo - 7):
                        if f"{fp}{off:+d}" in wide:
                            st.slot.pop(f"{fp}{off:+d}", None)
        if heap(self, loop) or any(mn in ("bl", "blr") for b in loop
                                   for (_a, mn, _o, _n) in self.blocks[b].insns):
            for k in [k for k, v in st.slot.items() if self._reads_mem(v.text)]:
                del st.slot[k]
        w, unsafe = self._near_written(header)
        self._stale_slots(st, w, unsafe=unsafe)

    def exit_slots(self, st, header):
        probe = State()
        for off in range(-48, 8, 4):
            probe.slot[f"x29{off:+d}"] = V(rng_text[off % 3], P_ATOM)
        for state in (probe, st):
            want = state.copy()
            exit_walk(self, want, header)
            got = state.copy() if state is probe else state
            old["_exit_slots"](self, got, header)
            assert (got.slot, got.dropped) == (want.slot, want.dropped), header
            seen["slots"] += state is probe and len(want.slot) < len(probe.slot)

    def reloads(self, header, trip, st, regs):
        got = old["_reloads"](self, header, trip, st, regs)
        want = reload_walk(self, header, trip, st, regs)
        assert got == want, (header, got, want)
        seen["reloads"] += 1
        return got

    def reload_walk(self, header, trip, st, regs):
        fp = roles("FP")
        if fp is None or self._frame_escaped() or fp in written(self, trip):
            return set()
        held = {}
        narrow, files = self._narrow_slots(), self._slot_widths()[4]
        for k, v in st.slot.items():
            if (k.startswith(fp) and k[len(fp):][:1] in "+-" and k not in narrow
                    and len(files.get(k, ())) == 1
                    and not expr._ANY_REG.search(v.text)
                    and not self._reads_mem(v.text)):
                held[k] = v.text
        for b in trip:
            insns = self.blocks[b].insns
            for i, keys, delta, ops, backs in self._accesses(b):
                if delta:
                    return set()
                if backs is not None and held:
                    lo = int(keys[0][len(fp):])
                    expr._drop_stored(held, fp, lo, lo + expr._access_width(
                        insns[i][1], ops[0]) * len(keys))
        values = set(held.values())
        start = {r: st.get(r).text for r in regs if st.get(r).text in values}
        if not start:
            return set()
        return old["_reloads"](self, header, trip, st, regs)

    def render_loop(self, header, body, st, indent, depth):
        fresh = header not in self.carried
        out = old["_render_loop"](self, header, body, st, indent, depth)
        if fresh:
            nodes = back_walk(self, header)
            live = expr._live_in_header(self.blocks, nodes, header, self._preds,
                                        self._printed_liveness()[0])
            folded = getattr(self, "_loop_live_in", None)       # #332's, not on main
            if folded is not None:
                assert folded(header, self._back_loop(header)) == live, header
            want = ((live & written(self, nodes)) - special) | self.carry_more.get(
                header, frozenset())
            assert self.carried[header] == want, (header, self.carried[header], want)
            seen["live"] += bool(want)
        return out

    rng_text = ["x1 + 1", "x3", "x2.field_0x8"]
    graphs = [_rows_332(seed) for seed in range(300)]
    graphs += [_rows_289(seed) for seed in range(300)]
    graphs += [(rows, base, mono) for _n, rows, base, mono, _t in _graphs_282()]
    patched = dict(old, _back_loop=back_loop, _trip_nodes=trip_nodes,
                   _trip_body=trip_body, _written=checked("_written", written),
                   _writes_heap=checked("_writes_heap", heap),
                   _writes_stack=checked("_writes_stack", stack),
                   _writes_outgoing=checked("_writes_outgoing", outgoing),
                   _exit_slots=exit_slots, _reloads=reloads, _render_loop=render_loop)
    nest = getattr(cfg, "LoopNest", None)
    if nest is not None:
        closure = nest.closure

        def walked(self, header, latches):
            nodes, stack = {header}, list(latches)
            while stack:
                n = stack.pop()
                if n in nodes or not self.keep(header, n):
                    continue
                nodes.add(n)
                stack.extend(self.preds.get(n, ()))
            return frozenset(nodes)
    try:
        for name, fn in patched.items():
            setattr(L, name, fn)
        for rows, base, mono in graphs:
            ann = [(base + i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)]
            blocks, entry = cfg.build_cfg(ann)
            got = cfg.structure(blocks, entry, orphans=True)
            if nest is not None:
                nest.closure = walked
                try:
                    assert cfg.structure(blocks, entry, orphans=True) == got
                finally:
                    nest.closure = closure
            lift_function(ann, mono=mono)
    finally:
        for name, fn in old.items():
            setattr(L, name, fn)
    assert seen["bodies"] > 2000 and seen["nested"] > 500 and seen["trips"] > 1000, seen
    assert seen["live"] > 500 and seen["slots"] > 300 and seen["reloads"] > 300, seen


def test_nested_loops_cost_the_same_per_instruction_at_any_depth():
    """N loops nested in each other, their headers in a row and their latches after them
    innermost first, cost about N * N to lift: 14 s of CPU at 2,000 where 250 took 0.23,
    `_render_loop` 82% of it (#332). Each loop walked its whole body to find it, again
    for the body a second trip runs and the part of it the header reaches, ran the
    liveness dataflow over it, and asked each of its blocks what it writes, stores and
    calls; the structurer walked it and counted its exits. Counted, not timed: the lines
    of expr.py and cfg.py the whole lift runs, per instruction, at 30 loops and at 120,
    with one counter and with six. Walked per loop that was 2,973 and 8,160 lines with
    one, and 3,698 and 9,221 with six; built inner loops first and folded up the nest,
    1,721 and 1,734, and 2,375 and 2,455."""
    from jadart import cfg, expr
    from jadart.expr import lift_function
    here = {expr.__file__, cfg.__file__}
    ran = [0]

    def lines(frame, event, _arg):
        if event == "line":
            ran[0] += 1
        return lines

    def calls(frame, _event, _arg):
        return lines if frame.f_code.co_filename in here else None

    def per_instruction(n, regs):
        rows = [("add", f"x{2 + i % regs}, x{2 + i % regs}, #1") for i in range(n)]
        for i in range(n):
            rows += [("cmp", "x2, x1"), ("b.lt", f"#{(n - 1 - i) * 4:#x}")]
        rows.append(("ret", ""))
        ran[0] = 0
        sys.settrace(calls)
        try:
            lift_function([(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])
        finally:
            sys.settrace(None)
        return ran[0] / len(rows)
    for regs in (1, 6):
        small, large = per_instruction(30, regs), per_instruction(120, regs)
        assert 0 < small and large < 1.5 * small, (regs, small, large)


def _rows_333(n, form):
    """(rows, base, mono) of #333's shape: `n` conditionals that each jump over their own
    block and the next conditional, so every join's immediate dominator is the first
    one; `loop` wraps them in a loop, `mono` puts them behind a monomorphic entry."""
    base, mono, rows = (0x1000, 0x1008, list(_MONO_ROWS[:6])) if form == "mono" else (
        0, None, [])
    start = base + len(rows) * 4
    for i in range(n):
        h = base + len(rows) * 4
        rows += [("cbz", f"x{i % 8}, #{h + 12:#x}"), ("add", "x2, x2, #1")]
    rows.append(("add", "x2, x2, #1"))
    if form == "loop":
        rows += [("cmp", "x2, x1"), ("b.lt", f"#{start:#x}")]
    return rows + [("ret", "")], base, mono


def _rows_333_random(seed):
    """(rows, base, mono) of a random range for #333's guard: conditionals that jump a
    row or three on, loops back to anywhere before, gotos, frame and field stores and
    calls between, in half of them one loop around it all, and in a quarter a
    monomorphic entry some of the body jumps back into."""
    import random
    rng = random.Random(seed)
    base, mono, rows = 0, None, []
    if rng.random() < 0.25:
        base, mono, rows = 0x1000, 0x1008, list(_MONO_ROWS[:6])
    start = base + len(rows) * 4
    body = []
    for _ in range(rng.randrange(3, 40)):
        h, r, k = start + len(body) * 4, f"x{rng.randrange(8)}", rng.random()
        put = rng.choice([("add", "x2, x2, #1"), ("stur", f"{r}, [x29, #-8]"),
                          ("str", f"{r}, [x0, #8]"), ("bl", "#0x100"),
                          ("mov", f"x{rng.randrange(8)}, {r}")])
        if k < 0.5:
            body += [("cbz", f"{r}, #{h + 4 * rng.choice([3, 3, 4, 5]):#x}"), put]
        elif k < 0.65:
            back = start + 4 * rng.randrange(len(body) + 1)
            body += [put, ("cmp", "x2, x1"), ("b.lt", f"#{back:#x}")]
        elif k < 0.75:
            body += [("b", f"#{h + 4 * rng.choice([2, 3, 6]):#x}"), put]
        elif k < 0.8 and mono:
            into = rng.choice([0x1000, 0x1008, 0x1014, 0x1018, 0x101c])
            body += [("cbz", f"{r}, #{into:#x}"), put]
        else:
            body.append(put)
    rows += body + [("add", "x2, x2, #1"), ("add", "x3, x3, #1"), ("add", "x2, x2, #1")]
    if rng.random() < 0.5:
        rows += [("cmp", "x2, x1"), ("b.lt", f"#{start:#x}")]
    return rows + [("ret", "")], base, mono


def test_overlapping_conditionals_cost_the_same_per_instruction_at_any_length():
    """N conditionals that each jump over their own block and the next conditional hang
    every join off the first one, and `_join_kill` walked the blocks between each join
    and it, most of the function each time: 2.34 s of CPU at 2,000 and about N * N
    (#333). Counted, not timed: the lines of expr.py and cfg.py `_join_kill` runs, per
    instruction, at 30 conditionals and at 120, as they are, in a loop, and behind a
    monomorphic entry. Walked per join that was 477 and 1,805, 1,955 and 8,071, and 450
    and 1,909; walked until the walks cover eight times the blocks and then folded
    once over the dominator tree (_KILL_WALK), 362 and 355, 775 and 801, and 181 and
    177."""
    from jadart import cfg, expr
    from jadart.expr import lift_function
    here = {expr.__file__, cfg.__file__}
    kill, ran, depth = expr.Lifter._join_kill, [0], [0]

    def lines(frame, event, _arg):
        if event == "line":
            ran[0] += 1
        return lines

    def calls(frame, _event, _arg):
        return lines if frame.f_code.co_filename in here else None

    def counted(*args, **kw):
        depth[0] += 1
        if depth[0] == 1:
            sys.settrace(calls)
        try:
            return kill(*args, **kw)
        finally:
            depth[0] -= 1
            if not depth[0]:
                sys.settrace(None)

    def per_instruction(n, form):
        rows, base, mono = _rows_333(n, form)
        ran[0] = 0
        lift_function([(base + i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)],
                      mono=mono)
        return ran[0] / len(rows)
    expr.Lifter._join_kill = counted
    try:
        got = {form: (per_instruction(30, form), per_instruction(120, form))
               for form in _FORMS_333}
    finally:
        expr.Lifter._join_kill = kill
    for form, (small, large) in got.items():
        assert 0 < small and large < 1.5 * small, (form, small, large)


def _untag_text(rows, reg="x0"):
    """The value tier 3 gives `reg` after `rows`, by the store the body ends with."""
    from jadart.expr import lift_function
    body = lift_function([(i * 4, mn, op, "") for i, (mn, op) in enumerate(
        list(rows) + [("stur", f"{reg}, [x9, #7]"), ("ret", "")])])
    line = next(ln.strip() for ln in body if ln.strip().startswith("x9.field_0x8 = "))
    return line.split(" = ", 1)[1].rstrip(";")


def _dart_int(text, env):
    """`text` evaluated as Dart's 64-bit ints over `env`, the low 64 bits returned. A
    `.toSigned(n)` or `.toUnsigned(n)` becomes a call on the operand before it, a name or
    a bracketed group, left to right. `~/` truncates toward zero, as Dart's does, where
    Python's `//` floors; it has `//`'s precedence."""
    import ast
    def signed(v, n):
        v &= (1 << n) - 1
        return v - (1 << n) if v >> (n - 1) & 1 else v
    conv = re.compile(r"\.to(Signed|Unsigned)\((\d+)\)")
    while (m := conv.search(text)):
        i = m.start()
        if text[i - 1] == ")":
            depth, j = 0, i - 1
            while True:
                depth += {")": 1, "(": -1}.get(text[j], 0)
                if depth == 0:
                    break
                j -= 1
        else:
            j = re.search(r"\w+\Z", text[:i]).start()
        fn = "_s" if m.group(1) == "Signed" else "_u"
        text = f"{text[:j]}{fn}({text[j:i]}, {m.group(2)}){text[m.end():]}"

    class Trunc(ast.NodeTransformer):
        def visit_BinOp(self, node):
            self.generic_visit(node)
            if not isinstance(node.op, ast.FloorDiv):
                return node
            return ast.Call(ast.Name("_td", ast.Load()), [node.left, node.right], [])
    tree = ast.fix_missing_locations(Trunc().visit(ast.parse(text.replace("~/", "//"),
                                                            mode="eval")))
    return eval(compile(tree, "<dart>", "eval"),
                {"_s": signed, "_u": lambda v, n: v & ((1 << n) - 1),
                 "_td": lambda a, b: abs(a) // abs(b) * (1 if (a < 0) == (b < 0) else -1),
                 **{k: signed(v, 64) for k, v in env.items()}}) & ((1 << 64) - 1)


def test_a_smi_untag_reads_bit_31_as_the_sign_of_any_source():
    """`sbfx xD, xN, #1, #31` is SmiUntag under compressed pointers: bits 1 to 31 of xN,
    sign-extended from bit 31, `xN.toSigned(32) >> 1` for every 64-bit xN. Tier 3
    printed `xN >> 1`, right only where bits 31 to 63 of xN already agree. After a
    32-bit add they do not: the top half is zero, so a negative Smi read as a large
    positive one, `((x2 << 1) + 2).toUnsigned(32) >> 1` (#285). A field load, a value a
    join named and an entry register say nothing about the top half either, and the VM
    leaves it zero (LoadCompressedSmi) or the heap base (LoadCompressed) there. Each
    form is checked against the arm64 definition on random inputs."""
    import random
    after_add = [("add", "w1, w0, #2"), ("sbfx", "x0, x1, #1, #0x1f")]
    assert _untag_text(after_add) == "(x0 + 2).toSigned(32) >> 1"
    assert _untag_text([("sbfx", "x0, x1, #1, #0x1f")]) == "x1.toSigned(32) >> 1"
    # A bound of 32 is not a sign: `V.bits` is unsigned, and bit 31 may be set.
    masked = [("and", "x1, x2, #0xffffffff"), ("sbfx", "x0, x1, #1, #0x1f")]
    assert _untag_text(masked) == "(x2 & 0xffffffff).toSigned(32) >> 1"
    # A literal proves its sign only inside the int32 range. 0x80000000 has bit 31 set and
    # nothing above it, so the machine has -0x40000000 where `0x80000000 >> 1` says
    # 0x40000000; -0x80000001 has bit 31 clear under a negative top half.
    mask = (1 << 64) - 1
    for imm, want in (("0x80000000", "0x80000000.toSigned(32) >> 1"),
                      ("-0x80000001", "(-0x80000001).toSigned(32) >> 1")):
        got = _untag_text([("mov", f"x1, #{imm}"), ("sbfx", "x0, x1, #1, #0x1f")])
        assert got == want, (imm, got)
        field = (int(imm, 0) & mask) >> 1 & ((1 << 31) - 1)
        machine = (field - (1 << 31) if field >> 30 else field) & mask
        assert _dart_int(got, {}) == machine, (imm, got, hex(machine))
    # The untagged value may be negative, so a 32-bit write of it is truncated again.
    chain = after_add + [("add", "w3, w0, #1")]
    assert _untag_text(chain, "x3").endswith(".toUnsigned(32)"), _untag_text(chain, "x3")

    def arm(x0, x1, x2):
        def sext(v, n):
            v &= (1 << n) - 1
            return v - (1 << n) if v >> (n - 1) & 1 else v
        mask = (1 << 64) - 1
        w1 = (x0 + 2) & 0xffffffff
        r0 = sext(w1 >> 1, 31) & mask
        return {"after_add": r0, "alone": sext(x1 >> 1, 31) & mask,
                "masked": sext((x2 & 0xffffffff) >> 1, 31) & mask,
                "chain": (r0 + 1) & 0xffffffff}
    texts = {"after_add": _untag_text(after_add),
             "alone": _untag_text([("sbfx", "x0, x1, #1, #0x1f")]),
             "masked": _untag_text(masked), "chain": _untag_text(chain, "x3")}
    rng = random.Random(285)
    for _ in range(400):
        # Negative Smis and values with bit 31 set are the inputs main got wrong.
        env = {r: rng.choice((rng.getrandbits(64), rng.getrandbits(32),
                              (1 << 64) - rng.getrandbits(31)))
               for r in ("x0", "x1", "x2")}
        want = arm(env["x0"], env["x1"], env["x2"])
        for k, t in texts.items():
            assert _dart_int(t, env) == want[k], (k, t, {r: hex(v)
                                                         for r, v in env.items()})


def test_a_smi_untag_keeps_the_shift_where_the_value_proves_its_sign():
    """Guard, passes on main: `>> 1` is exact where the source's bits 31 to 63 agree,
    and the value says so, a bound under 2**31 or a literal in the int32 range (#285).
    The value decides, not the pattern before it: a w write that fits in 31 bits keeps
    the shift, one that does not gets the conversion."""
    assert _untag_text([("and", "x1, x2, #0xfffe"), ("sbfx", "x0, x1, #1, #0x1f")]) == (
        "(x2 & 0xfffe) >> 1")
    assert _untag_text([("and", "w1, w2, #0x7ffffffe"),
                        ("sbfx", "x0, x1, #1, #0x1f")]) == "(x2 & 0x7ffffffe) >> 1"
    assert _untag_text([("mov", "x1, #-4"), ("sbfx", "x0, x1, #1, #0x1f")]) == "-4 >> 1"
    # The bottom of the int32 range is still in it.
    assert _untag_text([("mov", "x1, #-0x80000000"), ("sbfx", "x0, x1, #1, #0x1f")]) == (
        "-0x80000000 >> 1")


def test_a_smi_untag_reads_the_value_a_w_write_left_through_its_low_half():
    """A 32-bit write leaves the value it truncated in `V.wide` (#235), and the untag
    reads only the low 32 bits, which are the same in both, so it reads that one: one
    conversion, not a truncation and a sign extension of the same bits (#285). A
    literal whose w write zero-extended it is still the literal to `toSigned(32)`."""
    assert _untag_text([("add", "w1, w5, #2"), ("sbfx", "x0, x1, #1, #0x1f")]) == (
        "(x5 + 2).toSigned(32) >> 1")
    assert _untag_text([("mov", "w1, #-2"), ("sbfx", "x0, x1, #1, #0x1f")]) == "-2 >> 1"


def test_a_smi_untag_on_arm32_rows_reads_bit_31_as_the_sign():
    """arm32 is not in LIFTABLE_ARCHS, so no command lifts its rows, and its SmiUntag is
    `asr` (kSmiBits 30 on a 32-bit word). The branch runs if a caller binds the target
    directly, as the arm32 tests do, and prints the exact form there too (#285)."""
    from jadart import expr as E
    rows = [("sbfx", "r0, r1, #1, #0x1f"), ("str", "r0, [r2, #7]"), ("bx", "lr")]
    with E.use_target(E.ARM32):
        body = [ln.strip() for ln in E._lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)],
            None, None, None, "  ", 1, None)]
    assert any(ln.endswith(" = r1.toSigned(32) >> 1;") for ln in body), body
    assert E._T is E.ARM64


def test_copywith_on_the_clean_fixture_untags_its_named_argument_index_signed():
    """#285 as reported: the named-argument walk at 0x5d10 on the clean fixture adds one
    Smi to the index with `add w2, w5, #2` and untags it with `sbfx x5, x2, #1, #0x1f`,
    and `lift` printed `((x2 << 1) + 2).toUnsigned(32) >> 1`. Through the library API and
    `lift`, each of the six reads the low half signed."""
    _needs_capstone()
    import contextlib
    import io
    from jadart import cli
    body = [ln.strip() for ln in jadart.decompile(CLEAN, "0x5d10")[0]["body"]]
    assert "t0 = ((x2 << 1) + 2).toSigned(32) >> 1;" in body, body
    assert sum(".toSigned(32) >> 1;" in ln for ln in body) == 6, body
    assert not [ln for ln in body if ".toUnsigned(32) >> 1" in ln], body
    out = io.StringIO()
    with contextlib.redirect_stdout(out):
        assert cli.main(["lift", CLEAN, "0x5d10"]) == 0
    assert "t5 = ((t4 << 1) + 2).toSigned(32) >> 1;" in out.getvalue(), out.getvalue()


def test_a_width_conversion_is_neither_a_call_nor_a_read_of_memory():
    """`.toSigned(n)` and `.toUnsigned(n)` are arithmetic on the value before them, and
    two rules that read the printed text took them for something else. `_CALL_IN_LINE`
    took one for a call, so `_drop_dead_phis` kept a phi nothing reads because an arm
    binding an untag or a 32-bit result looked like a side effect. `_READS_MEMORY` took
    `this.toSigned(` for a named field of the receiver, so an untag of `this` was
    assigned in each arm of an `if` rather than declared before it. Both were latent on
    main, which prints `.toUnsigned(32)` on a 32-bit result, and the untag's
    `.toSigned(32) >> 1` made them fire across the nine binaries #285 measured. A call
    that carries a conversion is still a call, and a field of `this` still reads
    memory."""
    from jadart.expr import _CALL_IN_LINE, _READS_MEMORY, _drop_dead_phis, lift_function

    def arms(v):
        return ["  var t4;", "  if (x0 != 0) {", f"    t4 = {v};",
                "    x3.field_0x8 = x4;", "  } else {", "    t4 = 0;",
                "    x3.field_0x8 = x5;", "  }", "  return x0;"]
    for v in ("x1.toSigned(32) >> 1", "(x1 + 2).toUnsigned(32)"):
        out = _drop_dead_phis(arms(v), {"t4"})
        assert not [ln for ln in out if "t4" in ln], (v, out)
    # Only the conversion the lifter prints, a literal width in the brackets: anything
    # else after those names is a call, and its phi stays.
    for v in ("f(x1).toSigned(32)", "Foo.toSigned(x1)"):
        called = _drop_dead_phis(arms(v), {"t4"})
        assert [ln for ln in called if "t4" in ln], (v, called)
    assert _CALL_IN_LINE.search("t4 = Foo.toSigned(x1);")
    assert not _CALL_IN_LINE.search("t4 = x1.toSigned(32) >> 1;")
    assert not _READS_MEMORY.search("this.toSigned(32) >> 1")
    assert not _READS_MEMORY.search("this.toUnsigned(32)")
    assert _READS_MEMORY.search("this.balance")
    assert _READS_MEMORY.search("this.toSigned(32).field_0x8")
    assert _READS_MEMORY.search("this.toSigned(x1)")
    # `get:isOdd` at 0x24238 on the clean fixture, the shape LoadInt64FromBoxOrSmi emits:
    # the untag, then the Mint's payload where the value is not a Smi.
    rows = [("sbfx", "x2, x1, #1, #0x1f"), ("tbz", "w1, #0, #0xc"),
            ("ldur", "x2, [x1, #7]"), ("stur", "x2, [x3, #7]"), ("ret", "")]
    body = [ln.strip() for ln in lift_function(
        [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)],
        receiver={"x1": "this"})]
    assert body[:2] == ["var t0 = this.toSigned(32) >> 1;", "if (this & 1 != 0) {"], body
    assert "} else {" not in body, body


def test_a_32_bit_sdiv_divides_the_signed_low_halves():
    """`sdiv w0, w1, w2` divides the low 32 bits of each register, read as signed, and
    keeps the low half of the quotient. Tier 3 printed `(x1 ~/ x2).toUnsigned(32)`, the
    whole registers divided: 0x92b1d3f3 for x1 = 0x92b1d3f2ca02135e and x2 = 0xffffffff,
    where the CPU has 0x35fdeca2 (#291). Each operand is sign-extended unless its value
    says it already is, as a Smi untag's does, and the text is checked against the arm64
    definition on random inputs, INT32_MIN ~/ -1 among them. A zero divisor is left out:
    the CPU gives 0 and Dart throws, and compiled code tests the divisor first."""
    import random
    plain = _untag_text([("sdiv", "w0, w1, w2")])
    assert plain == "(x1.toSigned(32) ~/ x2.toSigned(32)).toUnsigned(32)", plain
    assert _dart_int(plain, {"x1": 0x92b1d3f2ca02135e, "x2": 0xffffffff}) == 0x35fdeca2
    # The shape both fixtures have, Smi `~/` and `%`: two untags, then the divide. Each
    # untag is a 31-bit signed value already, so neither gets a second conversion.
    untags = [("sbfx", "x1, x3, #1, #0x1f"), ("sbfx", "x2, x4, #1, #0x1f"),
              ("sdiv", "w0, w1, w2")]
    smi = _untag_text(untags)
    assert smi == "((x3.toSigned(32) >> 1) ~/ (x4.toSigned(32) >> 1)).toUnsigned(32)", smi
    after_add = _untag_text([("add", "w1, w5, #3"), ("sdiv", "w0, w1, w2")])
    assert after_add == "((x5 + 3).toSigned(32) ~/ x2.toSigned(32)).toUnsigned(32)", (
        after_add)
    # The 64-bit form divides the whole registers, and says so.
    assert _untag_text([("sdiv", "x0, x1, x2")]) == "x1 ~/ x2"

    def sext(v, n):
        v &= (1 << n) - 1
        return v - (1 << n) if v >> (n - 1) & 1 else v

    def sdiv_w(n, d):
        n, d = sext(n, 32), sext(d, 32)
        q = abs(n) // abs(d) * (1 if (n < 0) == (d < 0) else -1)
        return q & 0xffffffff
    edge = (0x80000000, 0xffffffff, 0x7fffffff, 1, 0x100000000, (1 << 64) - 1, 1 << 63,
            0xffffffff80000000, 0x1234567880000000)
    assert _dart_int(plain, {"x1": 0x80000000, "x2": 0xffffffff}) == 0x80000000
    rng = random.Random(291)
    for _ in range(600):
        env = {r: rng.choice((rng.getrandbits(64), rng.getrandbits(32), rng.choice(edge),
                              (1 << 64) - rng.getrandbits(31)))
               for r in ("x1", "x2", "x3", "x4", "x5")}
        cases = ((plain, env["x1"], env["x2"]),
                 (smi, sext(env["x3"] >> 1, 31), sext(env["x4"] >> 1, 31)),
                 (after_add, env["x5"] + 3, env["x2"]))
        for text, n, d in cases:
            if d & 0xffffffff:
                assert _dart_int(text, env) == sdiv_w(n, d), (
                    text, {r: hex(v) for r, v in env.items()})


def _lift_value(rows, reg="x0"):
    """The value tier 3 gives `reg` after `rows`, by the store the body ends with, and the
    declarations before it as (name, text) pairs."""
    from jadart.expr import lift_function
    body = [ln.strip() for ln in lift_function([(i * 4, mn, op, "") for i, (mn, op) in
                                                enumerate(list(rows) + [
                                                    ("stur", f"{reg}, [x9, #7]"),
                                                    ("ret", "")])])]
    decl = re.compile(r"var (t\d+) = (.*);\Z")
    decls = [m.groups() for m in map(decl.match, body) if m]
    line = next(ln for ln in body if ln.startswith("x9.field_0x8 = "))
    return line.split(" = ", 1)[1].rstrip(";"), decls


def test_a_smi_tag_read_by_an_untag_gives_back_its_31_bits():
    """`sbfiz xD, xN, #1, #0x1f` is the Smi tag under compressed pointers, bits 0 to 30 of
    xN sign-extended and shifted up one, and tier 3 prints it as xN, the Dart value it
    tags. The untag `sbfx #1, #0x1f` printed machine arithmetic on that, so the pair
    divided twice: `x2.toSigned(32) >> 1` where the CPU has `x2.toSigned(31)` (#290). The
    tag records that the register holds the value tagged and the untag reads it back:
    for the w form, through a name a stale register gave it and through a frame slot.
    Past a box-or-tag check the Smi path proves x2 fits, so the box unboxes to x2 on
    both halves of an unbox, the untag and the Mint's value field. Each is checked
    against the arm64 definition, the box on the inputs that take the Smi path."""
    tag = [("sbfiz", "x1, x2, #1, #0x1f"), ("sbfx", "x0, x1, #1, #0x1f")]
    wtag = [("sbfiz", "w1, w2, #1, #0x1f"), ("sbfx", "x0, x1, #1, #0x1f")]
    box = [("sbfiz", "x1, x2, #1, #0x1f"), ("cmp", "x2, x1, asr #1"), ("b.eq", "#0x10"),
           ("nop", ""), ("sbfx", "x0, x1, #1, #0x1f")]
    unbox = box + [("tbz", "w1, #0, #0x1c"), ("ldur", "x0, [x1, #7]")]
    # x3 is written while x1 still holds its tag, so x1's value gets a name first.
    pinned = [("sbfiz", "w1, w3, #1, #0x1f"), ("asr", "w3, w5, #0x1a"),
              ("sbfx", "x0, x1, #1, #0x1f")]
    slot = [("add", "x3, x4, x5"), ("sbfiz", "x1, x3, #1, #0x1f"),
            ("stur", "x1, [x29, #-8]"), ("mov", "x1, #3"), ("ldur", "x6, [x29, #-8]"),
            ("sbfx", "x0, x6, #1, #0x1f")]
    want = {"tag": "x2.toSigned(31)", "wtag": "x2.toSigned(31)", "box": "x2",
            "unbox": "x2", "pinned": "t0.toSigned(31)", "slot": "(x4 + x5).toSigned(31)"}
    rows = {"tag": tag, "wtag": wtag, "box": box, "unbox": unbox, "pinned": pinned,
            "slot": slot}
    got = {k: _lift_value(r) for k, r in rows.items()}
    assert {k: g[0] for k, g in got.items()} == want, got
    # A value that provably fits in 31 signed bits is its own untag.
    fits = [("and", "x2, x5, #0xffff")] + tag
    assert _lift_value(fits)[0] == "x5 & 0xffff"

    def sext(v, n):
        v &= (1 << n) - 1
        return v - (1 << n) if v >> (n - 1) & 1 else v
    mask = (1 << 64) - 1

    def untag_of_tag(v):
        word = (sext(v, 31) << 1) & mask            # sbfiz #1, #0x1f
        return sext(word >> 1, 31) & mask           # sbfx #1, #0x1f, bits 1 to 31

    def machine(k, e):
        if k == "slot":
            return untag_of_tag(e["x4"] + e["x5"])
        return untag_of_tag(e["x3"] if k == "pinned" else e["x2"])
    import random
    rng = random.Random(290)
    for _ in range(400):
        env = {r: rng.choice((rng.getrandbits(64), rng.getrandbits(32), 0x40000000,
                              0x3fffffff, 0x7fffffff, 0x80000000, (1 << 64) - 1,
                              (1 << 64) - rng.getrandbits(31)))
               for r in ("x2", "x3", "x4", "x5")}
        for k, (text, decls) in got.items():
            if k in ("box", "unbox") and sext(env["x2"], 31) & mask != env["x2"]:
                continue                    # the Mint path, which the strip cuts
            scope = dict(env)
            for name, value in decls:
                scope[name] = _dart_int(value, scope)
            assert _dart_int(text, scope) == machine(k, env), (k, text, decls, {
                r: hex(v) for r, v in env.items()})


def test_a_smi_tag_still_prints_the_value_it_tags():
    """Guard, passes on main: a tag is read as the Dart value where nothing untags it,
    which is every one of the 1,211 tags on the clean fixture, each a box-or-tag check
    whose result is stored or passed on (#290)."""
    assert _lift_value([("sbfiz", "x1, x2, #1, #0x1f")], "x1")[0] == "x2"
    box = [("sbfiz", "x1, x2, #1, #0x1f"), ("cmp", "x2, x1, asr #1"), ("b.eq", "#0x10"),
           ("nop", "")]
    assert _lift_value(box, "x1")[0] == "x2"


def test_an_ldp_into_its_own_base_reads_both_words_off_the_base_before_it():
    """`ldp x8, x0, [x8, #8]` reads both words at the address x8 held before it ran: the
    ARM ARM computes the address before either register is written. Tier 3 wrote x8 and
    then read the second word off the value just loaded, `x8.field_0x9.field_0x11`, and
    the w and ldpsw forms did the same (#293). The two shapes the ARM ARM leaves
    CONSTRAINED UNPREDICTABLE print as they are: a writeback into a loaded register at a
    zero immediate read as a plain load, and an ldp into one register twice kept the
    second word. capstone decodes neither, so they reach the lifter only as rows."""
    from jadart.expr import lift_function

    def lift(rows):
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])]
    tail = [("add", "x0, x0, x8"), ("ret", "")]
    assert lift([("ldp", "x8, x0, [x8, #8]")] + tail) == [
        "return x8.field_0x11 + x8.field_0x9;"]
    # The same second word the rows print with another first register.
    assert lift([("ldp", "x1, x0, [x8, #8]"), ("add", "x0, x0, x1"), ("ret", "")]) == [
        "return x8.field_0x11 + x8.field_0x9;"]
    assert lift([("ldp", "w8, w0, [x8, #8]")] + tail) == [
        "return x8.field_0xd + x8.field_0x9;"]
    assert lift([("ldpsw", "x8, x0, [x8, #-8]")] + tail) == [
        "return ((x8 - 4).field_0x1 << 32 >> 32) + ((x8 - 8).field_0x1 << 32 >> 32);"]
    for mn, op in (("ldp", "x8, x0, [x8, #0]!"), ("ldp", "x0, x8, [x8], #0"),
                   ("ldr", "x8, [x8, #0]!"), ("ldp", "x0, x0, [x8, #8]"),
                   ("ldpsw", "x0, x0, [x8]")):
        assert lift([(mn, op)] + tail) == [f"{mn} {op}", "return x0 + x8;"], (mn, op)
    assert lift([("ldp", "d0, d0, [x1]"), ("ret", "")]) == ["ldp d0, d0, [x1]",
                                                           "return d0;"]


def test_strip_boilerplate_drops_the_fp_lr_pair_only_off_the_frame():
    """The frame chain is an `stp`/`ldp` of FP and LR off SP: the prologue's push and
    the epilogue's pop, `ldp x29, x30, [x15], #0x10`, the only base either fixture or
    FluffyChat uses for one. Off another base the pair loads FP and LR from an object
    or stores them to one, and `strip_boilerplate` made it a nop whatever the base was,
    which hid that write (#294)."""
    from jadart.expr import lift_function, strip_boilerplate

    def strip(mn, op):
        return strip_boilerplate([(0x1000, mn, op, ""), (0x1004, "ret", "", "")],
                                 set())[0][1]
    assert strip("ldp", "x29, x30, [x0, #0x10]") == "ldp"
    assert strip("stp", "x29, x30, [x0, #0x10]") == "stp"
    assert strip("ldp", "x29, x30, [x29]") == "ldp"
    for mn, op in (("ldp", "x29, x30, [x15], #0x10"), ("stp", "x29, x30, [x15, #-0x10]!"),
                   ("ldp", "x29, x30, [sp], #0x10"), ("stp", "x29, x30, [sp, #-0x10]!")):
        assert strip(mn, op) == "nop", (mn, op)

    def lift(rows):
        return [ln.strip() for ln in lift_function(
            [(0x1000 + i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])]
    assert lift([("ldp", "x29, x30, [x0, #0x10]"), ("mov", "x0, x30"), ("ret", "")]) == [
        "return x0.field_0x19;"]
    assert lift([("stp", "x29, x30, [x0, #0x10]"), ("ret", "")]) == [
        "x0.field_0x11 = FP;", "x0.field_0x19 = LR;", "return x0;"]


def test_a_read_through_x29_past_a_write_that_is_not_the_frame_reads_its_value():
    """Tier 3 read an access off x29 as a frame slot by the register's role, even past a
    row that put something else there, so `ldr x29, [x0, #8]; ldur x0, [x29, #-8]`
    printed `(FP - 8).field_0x1`, a stack slot the machine does not touch, and a store
    through it printed nothing (#307). Past such a write x29 reads as x9 does in the
    same rows; the frame chain, its push, its pop and an FFI frame's restore, keeps the
    frame as it printed."""
    import re
    from jadart.expr import lift_function

    def lift(rows):
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])]

    def through(reg, rows):
        return lift([(mn, op.replace("@", reg)) for mn, op in rows])
    for rows, want in (
            ([("ldr", "@, [x0, #8]"), ("ldur", "x0, [@, #-8]"), ("ret", "")],
             ["return (x0.field_0x9 - 8).field_0x1;"]),
            ([("mov", "@, x1"), ("ldr", "x0, [@, #0x10]"), ("ret", "")],
             ["return x1.field_0x11;"]),
            ([("ldr", "@, [x0, #8]"), ("stur", "x1, [@, #-8]"), ("ret", "")],
             ["(x0.field_0x9 - 8).field_0x1 = x1;", "return x0;"])):
        assert through("x29", rows) == want, rows
        assert [re.sub(r"\bx9\b", "x29", ln) for ln in through("x9", rows)] == want, rows
    # Moved by an immediate it is still the value the write put there, not the frame.
    for mn in ("add", "sub"):
        rows = [("ldr", "@, [x0, #8]"), (mn, "@, @, #8"), ("ldur", "x0, [@, #-8]"),
                ("ret", "")]
        sign = "+" if mn == "add" else "-"
        want = [f"return (x0.field_0x9 {sign} 8 - 8).field_0x1;"]
        assert through("x29", rows) == want, rows
        assert [re.sub(r"\bx9\b", "x29", ln) for ln in through("x9", rows)] == want, rows
    # The issue's pair, which strip_boilerplate no longer drops off x0 (#294).
    assert lift([("ldp", "x29, x30, [x0, #0x10]"), ("ldur", "x0, [x29, #-8]"),
                 ("ret", "")]) == ["return (x0.field_0x11 - 8).field_0x1;"]
    # Two write-backs through it are its own, not FP's moves for `_frame_plan`.
    assert lift([("mov", "x29, x9"), ("ldr", "x2, [x29, #8]!"), ("ldr", "x3, [x29, #8]!"),
                 ("add", "x0, x29, #8"), ("ret", "")])[-1] == "return x29 + 8;"
    # Where only one way in wrote it, x29 is the register, and no slot is claimed.
    assert lift([("cbz", "x2, #0xc"), ("ldr", "x29, [x0, #8]"), ("nop", ""),
                 ("ldur", "x0, [x29, #-8]"), ("ret", "")]) == [
        "return (x29 - 8).field_0x1;"]
    # The frame chain prints as it did: the push and the pop, and an FFI frame's, whose
    # pop off SP comes right after `mov x15, x29`. Without that move a pop off SP puts
    # what was pushed in x29, and is the value it reads as.
    assert lift([("stp", "x29, x30, [x15, #-0x10]!"), ("mov", "x29, x15"),
                 ("ldur", "x0, [x29, #0x10]"), ("mov", "x15, x29"),
                 ("ldp", "x29, x30, [x15], #0x10"), ("ret", "")]) == [
        "var t0 = FP.field_0x11;", "return t0;"]
    assert lift([("str", "x29, [x15, #-8]!"), ("mov", "x29, x15"), ("mov", "x15, x29"),
                 ("ldr", "x29, [x15], #8"), ("ldur", "x0, [x29, #-8]"), ("ret", "")]) == [
        "var t1 = (FP - 8).field_0x1;", "return t1;"]
    assert lift([("str", "x0, [x15, #-8]!"), ("ldr", "x29, [x15], #8"),
                 ("ldur", "x0, [x29, #-8]"), ("ret", "")]) == [
        "return (x0 - 8).field_0x1;"]


def test_x29_and_x30_read_as_their_role_again_where_the_frame_chain_gives_it_back():
    """`ldr x29, [x0, #8]; mov x29, x15; mov x0, x29` printed `return x0.field_0x9;`: the
    move is the frame chain, which strip_boilerplate blanks, so the role came back (#307)
    and no row wrote x29 in the lifted state, which kept the loaded value. The machine
    returns SP. A frame-chain row that gives the role back puts x29 back as FP: as a
    value, as a base, and at a join one way into which lost it; and x30 the same where
    the epilogue's pair pop puts the return address back (#331)."""
    from jadart.expr import lift_function

    def lift(rows):
        return [ln.strip() for ln in lift_function(
            [(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])]
    lose = ("ldr", "x29, [x0, #8]")
    for back in ([("mov", "x29, x15")], [("add", "x29, x15, #0")],
                 [("ldp", "x29, x30, [x15], #0x10")],
                 [("mov", "x15, x29"), ("ldr", "x29, [x15], #8")]):  # its load is its own
        want = lift([*back, ("mov", "x0, x29"), ("ret", "")])
        assert lift([lose, *back, ("mov", "x0, x29"), ("ret", "")]) == want, back
        want = lift([*back, ("ldur", "x0, [x29, #-8]"), ("ret", "")])
        assert lift([lose, *back, ("ldur", "x0, [x29, #-8]"), ("ret", "")]) == want, back
    assert lift([lose, ("mov", "x29, x15"), ("mov", "x0, x29"), ("ret", "")]) == [
        "return FP;"]
    # A move that is not the chain keeps the value, as #307 prints it.
    assert lift([lose, ("mov", "x29, x1"), ("mov", "x0, x29"), ("ret", "")]) == [
        "return x1;"]
    # At a join: the way that lost it and got it back, and the one that never lost it.
    assert lift([("cbz", "x2, #0x10"), lose, ("nop", ""), ("mov", "x29, x15"),
                 ("mov", "x0, x29"), ("ret", "")]) == ["return FP;"]
    # And the way that lost it and did not is still a register where they meet.
    assert lift([("cbz", "x2, #0xc"), lose, ("mov", "x0, x29"), ("ret", "")]) == [
        "return x0;"]
    # LR: the pair's pop puts the return address back.
    assert lift([("ldr", "x30, [x0, #8]"), ("ldp", "x29, x30, [x15], #0x10"),
                 ("mov", "x0, x30"), ("ret", "")]) == ["return LR;"]
    assert lift([("ldr", "x30, [x0, #8]"), ("mov", "x0, x30"), ("ret", "")]) == [
        "return x0.field_0x9;"]


def test_an_element_access_off_the_data_offset_prints_the_address_it_reads():
    """An element address, `add x2, x3, x4, lsl #3`, is read at the data offset less the
    tag, and only that access is element x4. Tier 3 dropped every displacement, so
    stores at #0x17 and #0x1f printed `x3[x4] = x5;` then `x3[x4] = x6;`, the second
    reading as overwriting the first, and a load at #8 or #-8 read `x3[x4]` too (#308).
    Where one access reaches a data offset of the target the others print k strides on
    from it or as the address they read; where none or two do, every one prints its
    address. 0x1f is Closure's in 3.13.0, so it is one of two there. A call ends the
    entry where the walk forgets the register, and only there. An untagged base has no
    header, and its offset is 0."""
    add = ("add", "x2, x3, x4, lsl #3")

    def lift(*rows, tail=(("ret", ""),)):
        return " ".join(_lift_rows([add, *rows, *tail], base=0x1000))
    assert lift(("str", "x5, [x2, #0x17]"), ("str", "x6, [x2, #0x27]")) == (
        "x3[x4] = x5; x3[x4 + 2] = x6; return x0;")
    assert lift(("str", "x5, [x2, #0x17]"), ("str", "x6, [x2, #0x1f]")) == (
        "(x3 + (x4 << 3)).field_0x18 = x5; (x3 + (x4 << 3)).field_0x20 = x6; return x0;")
    # An access past a call the walk forgets x2 at says nothing about one before it.
    assert lift(("str", "x5, [x2, #0x1f]"), ("bl", "#0x2000"),
                ("ldr", "x0, [x2, #0x17]")) == (
        "(x3 + (x4 << 3)).field_0x20 = x5; var t0; sub_0x2000(...); "
        "return t0.field_0x18;")
    assert " ".join(_lift_rows([
        ("add", "x2, x3, x4, lsl #2"), ("str", "x5, [x2, #0x13]"), ("bl", "#0x2000"),
        ("ldur", "w0, [x2, #0xf]"), ("ret", "")], base=0x1000)) == (
        "(x3 + (x4 << 2)).field_0x14 = x5; var t0; sub_0x2000(...); "
        "return t0.field_0x10;")
    ret0 = (("ret", ""),)
    for disp, want in (("#0", "x3[x4]"), ("#0xf", "x3[x4]"), ("#0x17", "x3[x4]"),
                       ("#8", "(x3 + (x4 << 3)).field_0x9"),
                       ("#0x1f", "(x3 + (x4 << 3)).field_0x20"),
                       ("#-8", "(x3 + (x4 << 3) - 8).field_0x1")):
        assert lift(("ldur", f"x0, [x2, {disp}]"), tail=ret0) == f"return {want};", disp
    # Two data offsets, 0xf and 0x17, off one address: neither is shown to be it, on
    # one path or on two.
    both = "return (x3 + (x4 << 3)).field_0x10 + (x3 + (x4 << 3)).field_0x18;"
    assert lift(("ldur", "x0, [x2, #0xf]"), ("ldur", "x1, [x2, #0x17]"),
                ("add", "x0, x0, x1")) == both
    assert lift(("cbz", "x9, #0x100c"), ("ldur", "x0, [x2, #0xf]"),
                ("ldur", "x1, [x2, #0x17]"), ("add", "x0, x1, x1")) == (
        "return (x3 + (x4 << 3)).field_0x18 + (x3 + (x4 << 3)).field_0x18;")
    # The megamorphic cache's probe reads a key at 0xf and its target one element on.
    assert " ".join(_lift_rows([
        ("add", "x2, x3, x4, lsl #2"), ("ldur", "w0, [x2, #0xf]"),
        ("ldur", "w1, [x2, #0x13]"), ("add", "x0, x0, x1"), ("ret", "")])) == (
        "return x3[x4] + x3[x4 + 1];")
    # A frame address: whole strides fold, anything else is the address.
    assert " ".join(_lift_rows([
        ("add", "x2, x29, x4, lsl #2"), ("ldr", "x0, [x2, #0x18]"),
        ("ldr", "x1, [x2, #6]"), ("add", "x0, x0, x1"), ("ret", "")])) == (
        "return FP[x4 + 6] + (FP + (x4 << 2)).field_0x7;")


def test_an_ldp_off_an_element_address_or_the_pool_loads_both_registers():
    """An `ldp` off an element address, PP or a far pool base took the element or pool
    path, set its first register and returned, so the second kept what it held:
    `ldp x0, x1, [x2]; add x0, x0, x1` printed `return x3[x4] + x1;`, x1 reading as its
    value on entry, and off PP `return pool_0x10 + x1;` (#306). The second word is one
    register's width on: an element where #308's rule shows it is one, else its
    address, and off the pool the entry 8 bytes on, or 4 for a w pair."""
    tail = [("add", "x0, x0, x1"), ("ret", "")]
    add = ("add", "x2, x3, x4, lsl #3")
    assert _lift_rows([add, ("ldp", "x0, x1, [x2]")] + tail) == [
        "return x3[x4] + x3[x4 + 1];"]
    assert _lift_rows([add, ("ldp", "w0, w1, [x2]")] + tail) == [
        "return x3[x4] + (x3 + (x4 << 3)).field_0x5;"]
    assert _lift_rows([("add", "x2, x3, x4, lsl #2"), ("ldpsw", "x0, x1, [x2]")]
                      + tail) == ["return x3[x4] + x3[x4 + 1];"]
    # Into the element address itself: both words off the address it held.
    assert _lift_rows([add, ("ldp", "x2, x1, [x2]"), ("add", "x0, x2, x1"),
                       ("ret", "")]) == ["return x3[x4] + x3[x4 + 1];"]
    assert _lift_rows([("ldp", "x0, x1, [x27, #0x10]")] + tail) == [
        "return pool_0x10 + pool_0x18;"]
    assert _lift_rows([("ldp", "w0, w1, [x27, #0x10]")] + tail) == [
        "return pool_0x10 + pool_0x14;"]
    assert _lift_rows([("add", "x16, x27, #8, lsl #12"), ("ldp", "x16, x1, [x16, #0x10]"),
                       ("add", "x0, x16, x1"), ("ret", "")]) == [
        "return pool_0x8010 + pool_0x8018;"]


def test_an_element_add_into_its_own_base_or_index_reads_the_operand_it_overwrote():
    """`add x3, x3, x4, lsl #3` makes the element address in the register its base was
    in, and the entry read the base after the write, so `ldr x0, [x3, #0x17]` printed
    `return (x3 + (x4 << 3))[x4];`, and with the index as destination `x3[x3 + (x4 <<
    3)]` (#314). Both operands are read before the add writes either."""
    tail = [("ret", "")]
    assert _lift_rows([("add", "x3, x3, x4, lsl #3"), ("ldr", "x0, [x3, #0x17]")]
                      + tail) == ["return x3[x4];"]
    assert _lift_rows([("add", "x4, x3, x4, lsl #3"), ("ldr", "x0, [x4, #0x17]")]
                      + tail) == ["return x3[x4];"]
    # The register itself is the address the add made.
    assert _lift_rows([("add", "x3, x3, x4, lsl #3"), ("ldr", "x0, [x3, #0x17]"),
                       ("add", "x0, x0, x3")] + tail) == [
        "return x3[x4] + (x3 + (x4 << 3));"]


def test_an_element_address_built_with_asr_prints_its_index_shifted():
    """`add x2, x3, x4, asr #1` adds x4 >> 1, and the element entry kept x4 itself, so
    `ldrb w0, [x2, #0x17]` printed `return x3[x4];`, what `lsl #0` prints (#315). The
    index is the shifted word, one byte a step; it reads as the Smi's value only where
    the walk saw the register tagged (#290)."""
    def lift(*rows):
        return _lift_rows([*rows, ("ret", "")])
    asr = ("add", "x2, x3, x4, asr #1")
    assert lift(asr, ("ldrb", "w0, [x2, #0x17]")) == ["return x3[x4 >> 1];"]
    assert lift(("add", "x2, x3, x4, lsl #0"), ("ldrb", "w0, [x2, #0x17]")) == [
        "return x3[x4];"]
    assert lift(asr, ("ldrb", "w0, [x2, #0x17]"), ("ldrb", "w1, [x2, #0x18]"),
                ("add", "x0, x0, x1")) == ["return x3[x4 >> 1] + x3[(x4 >> 1) + 1];"]
    assert lift(("sbfiz", "x4, x5, #1, #0x1f"), asr, ("ldrb", "w0, [x2, #0x17]")) == [
        "return x3[x5.toSigned(31)];"]


def test_an_stp_off_an_element_address_prints_both_stores():
    """An `stp` off an element address printed its first store and dropped the second:
    `add x2, x3, x4, lsl #3; stp x5, x6, [x2, #0x17]` printed `x3[x4] = x5;` and
    nothing for x6 (#316), the store side of #306. The second word is one register's
    width on, an element where #308's rule shows it is one and its address otherwise."""
    add = ("add", "x2, x3, x4, lsl #3")
    tail = [("ret", "")]
    assert _lift_rows([add, ("stp", "x5, x6, [x2]")] + tail) == [
        "x3[x4] = x5;", "x3[x4 + 1] = x6;", "return x0;"]
    assert _lift_rows([add, ("stp", "w5, w6, [x2]")] + tail) == [
        "x3[x4] = x5;", "(x3 + (x4 << 3)).field_0x5 = x6;", "return x0;"]
    # 0x17 and 0x1f are both data offsets on some release, so neither is shown to be.
    assert _lift_rows([add, ("stp", "x5, x6, [x2, #0x17]")] + tail) == [
        "(x3 + (x4 << 3)).field_0x18 = x5;", "(x3 + (x4 << 3)).field_0x20 = x6;",
        "return x0;"]


def test_a_load_from_null_plus_a_bool_offset_reads_the_word_there():
    """`add x0, x22, #0x20` is how arm64 code makes `true`: the object is at null +
    0x20. A load from that address reads a word inside the object, and printed `true`
    as well (#317). The table of offsets off NULL names objects only for the `add`."""
    def lift(*rows):
        return _lift_rows([*rows, ("ret", "")])
    assert lift(("ldr", "x0, [x22, #0x20]")) == ["return NULL.field_0x21;"]
    assert lift(("ldr", "x0, [x22, #0x30]")) == ["return NULL.field_0x31;"]
    assert lift(("add", "x0, x22, #0x20")) == ["return true;"]
    assert lift(("add", "x0, x22, #0x30")) == ["return false;"]


def test_an_offset_off_the_null_register_carries_the_tag_bias():
    """x22 holds null, loaded from `Thread::object_null_offset()` and so a tagged
    ObjectPtr like any other object, but the arm64 table listed it as untagged and an
    offset off it printed as written: `ldurb w0, [x22, #-1]`, null's header byte, read
    `(NULL - 1).field1_0x1`, where the same load off x1 reads `x1.field1_0x0` (#330).
    Every access off x22 is now spelled as the access off any other object, and as a copy
    of x22 already was, while the `add` that makes true and false is unchanged."""
    def lift(*rows):
        return _lift_rows([*rows, ("ret", "")])
    for rows in ([("ldurb", "w0, [{}, #-1]")], [("ldur", "x0, [{}, #-1]")],
                 [("ldr", "x0, [{}, #0x20]")], [("ldr", "w0, [{}, #7]")],
                 [("ldrb", "w0, [{}, #0xf]")], [("ldr", "x0, [{}, #-8]")],
                 [("ldp", "x0, x2, [{}, #0x10]"), ("add", "x0, x0, x2")],
                 [("str", "x2, [{}, #0xf]"), ("mov", "x0, x2")],
                 [("stp", "x2, x3, [{}, #0x10]"), ("mov", "x0, x2")],
                 [("add", "x3, {}, x2, lsl #3"), ("ldur", "x0, [x3, #0x17]")],
                 [("mov", "x3, {}"), ("ldr", "x0, [x3, #0x20]")]):
        off_x1 = lift(*[(m, o.format("x1")) for m, o in rows])
        assert lift(*[(m, o.format("x22")) for m, o in rows]) == [
            re.sub(r"\bx1\b", "NULL", ln) for ln in off_x1], rows
    assert lift(("ldurb", "w0, [x22, #-1]")) == ["return NULL.field1_0x0;"]
    assert lift(("ldur", "x0, [x22, #-1]")) == ["return NULL.tags;"]
    # The class id out of that tags word selects a dispatch-table row as any receiver's
    # does: the walk that follows it was keyed on the same set.
    call = [("ldur", "x0, [{}, #-1]"), ("ubfx", "x0, x0, #0xc, #0x14"),
            ("sub", "x30, x0, #0x30"), ("ldr", "x30, [x21, x30, lsl #3]"), ("blr", "x30")]
    assert lift(*[(m, o.format("x1")) for m, o in call]) == ["return x1.sel_m0x30(...);"]
    assert lift(*[(m, o.format("x22")) for m, o in call]) == [
        "return NULL.sel_m0x30(...);"]
    assert lift(("add", "x0, x22, #0x20")) == ["return true;"]
    assert lift(("add", "x0, x22, #0x30")) == ["return false;"]
    assert lift(("add", "x0, x22, #8")) == ["return NULL + 8;"]


def _lift_329(*rows):
    return _lift_rows([*rows, ("ret", "")])


def test_tags_is_printed_only_off_an_object_pointer():
    """`.tags` is the header word of the object a base points at, and offset 0 was
    spelled that way off any base: AllocateObjectParameterized's `add x5, x0, x5, lsl
    #2; stur w1, [x5, #-1]`, a type-argument store at an offset read from the class,
    printed `(t0 + 1 + (... << 2)).tags = x1;` (#329). A value now records that the
    lifter computed it (`V.calc`), the record follows it through a name, a slot, a
    32-bit view and a join, and off such a value offset 0 is the access at its address,
    exact off a tagged base and off an untagged one."""
    lift = _lift_329
    # The issue, and the constants of the address made one.
    assert lift(("add", "x0, x0, #1"), ("add", "x5, x0, x5, lsl #2"),
                ("stur", "w1, [x5, #-1]")) == [
        "(x0 + (x5 << 2)).field_0x1 = x1;", "return x0 + 1;"]
    assert lift(("sub", "x0, x2, #0xf"), ("stur", "x1, [x0, #-1]")) == [
        "(x2 - 16).field_0x1 = x1;", "return x2 - 15;"]
    assert lift(("stur", "x1, [x2, #-0x10]")) == ["(x2 - 16).field_0x1 = x1;",
                                                  "return x0;"]
    # An untagged base has no tag bias: these read THR + 0 and HEAP + 0, and the first
    # two printed `THR.field_0x1`, which is THR + 1, in the fix that was reverted.
    for rows, want in (
            ([("add", "x0, x26, #1"), ("ldur", "x0, [x0, #-1]")], "THR.field_0x0"),
            ([("add", "x0, x26, #8"), ("ldr", "x0, [x0, #-8]")],
             "(THR + 8 - 8).field_0x1"),
            ([("mov", "x5, x26"), ("add", "x0, x5, #1"), ("ldur", "x0, [x0, #-1]")],
             "THR.field_0x0"),
            ([("ldr", "x0, [x26]")], "THR.field_0x0"),
            ([("add", "x0, x28, #1"), ("ldur", "x0, [x0, #-1]")], "HEAP.field_0x0"),
            ([("ldr", "x0, [x28]")], "HEAP.field_0x0"),
            ([("mov", "x5, x28"), ("ldur", "x0, [x5, #-1]")], "(HEAP - 1).field_0x1"),
            ([("ldr", "x0, [x30]")], "LR.field_0x0")):
        assert lift(*rows) == [f"return {want};"], rows
    assert lift(("add", "x0, x26, #1"), ("stur", "x3, [x0, #-1]")) == [
        "THR.field_0x0 = x3;", "return THR + 1;"]
    # The constants of a longer sum are one offset.
    assert lift(("add", "x0, x2, #1"), ("add", "x0, x0, x3"), ("add", "x0, x0, #7"),
                ("ldur", "x0, [x0, #-1]")) == ["return (x2 + x3).field_0x8;"]
    # A tagged base carries the bias, a frame register its own convention, and the
    # null register is an object.
    for rows, want in (
            ([("add", "x0, x2, #1"), ("ldur", "x0, [x0, #-1]")], "x2.field_0x1"),
            ([("add", "x0, x2, #1"), ("ldurb", "w0, [x0, #-1]")], "x2.field1_0x1"),
            ([("add", "x0, x2, #2"), ("ldur", "x0, [x0, #-1]")], "x2.field_0x2"),
            ([("add", "x0, x22, #1"), ("ldur", "x0, [x0, #-1]")], "NULL.field_0x1"),
            ([("add", "x0, x29, #1"), ("ldur", "x0, [x0, #-1]")], "FP.field_0x1"),
            ([("ldur", "x0, [x22, #-1]")], "NULL.tags"),
            ([("ldur", "x0, [x1, #-1]")], "x1.tags")):
        assert lift(*rows) == [f"return {want};"], rows
    # Arithmetic of any kind, and a 32-bit view of it.
    for rows, want in (
            ([("and", "x0, x1, #0xfffffffffffffff0")],
             "((x1 & 0xfffffffffffffff0) - 1).field_0x1"),
            ([("lsl", "x0, x1, #3")], "((x1 << 3) - 1).field_0x1"),
            ([("mul", "x0, x1, x2")], "(x1 * x2 - 1).field_0x1"),
            ([("neg", "x0, x1")], "(-x1 - 1).field_0x1"),
            ([("mov", "x0, #0x10")], "15.field_0x1"),
            ([("add", "w0, w1, #1")], "((x1 + 1).toUnsigned(32) - 1).field_0x1"),
            ([("add", "x0, x1, x5")], "(x1 + x5 - 1).field_0x1")):
        assert lift(*rows, ("ldur", "x0, [x0, #-1]")) == [f"return {want};"], rows
    # A tagged Smi's word is arithmetic. One a Smi check left boxed is the object, and
    # so is the choice of two object pointers, but not of a pointer and a sum.
    assert lift(("sbfiz", "x0, x1, #1, #0x1f"), ("ldur", "x0, [x0, #-1]")) == [
        "return ((x1.toSigned(31) << 1) - 1).field_0x1;"]
    assert lift(("cmp", "x3, x4"), ("csel", "x0, x1, x2, eq"),
                ("ldur", "x0, [x0, #-1]")) == ["return (x3 == x4 ? x1 : x2).tags;"]
    assert lift(("add", "x2, x2, #8"), ("cmp", "x3, x4"), ("csel", "x0, x1, x2, eq"),
                ("ldur", "x0, [x0, #-1]")) == [
        "return ((x3 == x4 ? x1 : x2 + 8) - 1).field_0x1;"]
    assert lift(("cmp", "x3, x4"), ("csinc", "x0, x1, x2, eq"),
                ("ldur", "x0, [x0, #-1]")) == [
        "return ((x3 == x4 ? x1 : x2 + 1) - 1).field_0x1;"]


def test_a_computed_address_is_one_under_a_name_and_past_a_join():
    """The record is the value's and not the text's: the type-argument store survived
    wherever the address was given a name first. The clean fixture's 0x19d860 steps x1
    by 0x10 round a loop and stores `stur w22, [x1, #-1]`, which printed `t3.tags =
    NULL;` under `var t3 = t0 + 1 + 16;` (#329). A name carries what its value was, and
    where the walk has only a register's name, at a loop header, a join or a label,
    the rows on every way in say whether any of them left arithmetic there
    (`_addr_facts`)."""
    lift = _lift_329
    # The loop cursor: the name is made before the body is walked.
    assert lift(("add", "x1, x0, #0x10"), ("stur", "w22, [x1, #-1]"),
                ("add", "x1, x1, #0x10"), ("cmp", "x1, x3"), ("b.lo", "#0x4")) == [
        "var t0 = x0 + 16;", "while (true) {", "(t0 - 1).field_0x1 = NULL;",
        "if ((t0 + 16) u>= x3) {", "t0 += 16;", "break;", "}", "t0 += 16;", "}",
        "return x0;"]
    # Named because a store went by.
    assert lift(("add", "x0, x0, #1"), ("ldur", "w6, [x5, #0x4f]"),
                ("add", "x5, x0, x6, lsl #2"), ("stur", "x9, [x7, #0x4f]"),
                ("stur", "w1, [x5, #-1]"))[-2] == "(t0 - 1).field_0x1 = x1;"
    # Computed on one way in and an object pointer on the other.
    assert lift(("cbz", "x5, #0xc"), ("add", "x1, x1, #8"), ("b", "#0xc"),
                ("ldur", "x0, [x1, #-1]")) == [
        "var t0 = x1;", "if (x5 != 0) {", "t0 = x1 + 8;", "}",
        "return (t0 - 1).field_0x1;"]
    # Spilled and read back, past a call and past a join.
    spill = [("add", "x0, x1, #0x10"), ("stur", "x0, [x29, #-8]")]
    back = [("ldur", "x3, [x29, #-8]"), ("ldur", "x0, [x3, #-1]")]
    assert lift(*spill, ("bl", "#0x1000"), *back)[-1] == "return x1.field_0x10;"
    assert lift(*spill, ("cbz", "x5, #0x10"), ("bl", "#0x1000"), *back)[-1] == (
        "return x1.field_0x10;")
    # A Smi check is the compiler's word that the value is a Dart object: tagged on
    # one arm, a call's result on the other, the class id is still read off the header,
    # but only on the edge where the tag bit is set, and only of bit 0.
    arms = [("cbz", "x5, #0x10"), ("sbfiz", "x0, x1, #1, #0x1f"), ("b", "#0x14"),
            ("nop", ""), ("bl", "#0x1000")]
    read = [("ldur", "x2, [x0, #-1]"), ("mov", "x0, x2")]
    assert "t2 = t1.tags;" in lift(*arms, ("mov", "x2, x0"), ("tbz", "w0, #0, #0x24"),
                                   *read)
    assert "t2 = (t1 - 1).field_0x1;" in lift(*arms, ("mov", "x2, x0"),
                                              ("tbnz", "w0, #0, #0x24"), *read)
    assert "t2 = (t1 - 1).field_0x1;" in lift(*arms, ("mov", "x2, x0"),
                                              ("tbz", "w0, #1, #0x24"), *read)
    # `and w16, w0, w3; tbz w16, #0` is that check of two values at once, the Mint arm
    # of an integer equality: bit 0 of the AND is set only where it is set in both.
    both = ("and", "w16, w0, w3")
    assert "t4 = t2.tags;" in lift(*arms, both, ("tbz", "w16, #0, #0x24"), *read)
    assert "t4 = (t2 - 1).field_0x1;" in lift(*arms, both, ("tbnz", "w16, #0, #0x24"),
                                              *read)
    assert lift(("add", "x0, x1, #8"), ("tbz", "w0, #0, #0x10"), *read)[2] == (
        "t0 = x1.field_0x8;")


def test_a_store_through_a_computed_address_still_names_the_header_read_before_it():
    """A store at offset 0 off a computed address may write the header a live value
    read, as the `.tags` it used to be spelled as did, so the read is still named first.
    The fix that was reverted lost the name: `ldur x3, [x1, #-1]; add x0, x1, #8; sub
    x0, x0, #8; stur x4, [x0, #-1]; mov x0, x3` returned `x1.tags` read AFTER the store
    (#329). A sum that comes back to its base is the base, here and in the read."""
    lift = _lift_329
    assert lift(("ldur", "x3, [x1, #-1]"), ("add", "x0, x1, #8"), ("sub", "x0, x0, #8"),
                ("stur", "x4, [x0, #-1]"), ("mov", "x0, x3")) == [
        "var t0 = x1.tags;", "x1.tags = x4;", "return t0;"]
    assert lift(("add", "x0, x1, #8"), ("sub", "x0, x0, #8"), ("ldur", "x3, [x0, #-1]"),
                ("stur", "x4, [x1, #-1]"), ("mov", "x0, x3")) == [
        "var t0 = x1.tags;", "x1.tags = x4;", "return t0;"]
    assert lift(("ldur", "x3, [x1, #-1]"), ("add", "x0, x1, x5"),
                ("stur", "x4, [x0, #-1]"), ("mov", "x0, x3")) == [
        "var t0 = x1.tags;", "(x1 + x5 - 1).field_0x1 = x4;", "return t0;"]
    # The other way round: the read is the computed one and the store the header's,
    # through its own base or any other, at either width. x5 may be 0.
    assert lift(("add", "x0, x1, x5"), ("ldur", "x3, [x0, #-1]"),
                ("stur", "x4, [x1, #-1]"), ("mov", "x0, x3")) == [
        "var t0 = (x1 + x5 - 1).field_0x1;", "x1.tags = x4;", "return t0;"]
    assert lift(("add", "x0, x1, x5"), ("ldur", "x3, [x0, #-1]"),
                ("stur", "x4, [x7, #-1]"), ("mov", "x0, x3")) == [
        "var t0 = (x1 + x5 - 1).field_0x1;", "x7.tags = x4;", "return t0;"]
    assert lift(("add", "x0, x1, x5"), ("ldurb", "w3, [x0, #-1]"),
                ("sturb", "w4, [x1, #-1]"), ("mov", "x0, x3")) == [
        "var t0 = (x1 + x5 - 1).field1_0x1;", "x1.field1_0x0 = x4;", "return t0;"]
    # No header store, no name.
    assert lift(("add", "x0, x1, x5"), ("ldur", "x3, [x0, #-1]"), ("mov", "x0, x3")) == [
        "return (x1 + x5 - 1).field_0x1;"]
    # And the field at the address it is now spelled as.
    assert lift(("ldur", "x3, [x1, #0]"), ("add", "x0, x1, #1"),
                ("stur", "x4, [x0, #-1]"), ("mov", "x0, x3")) == [
        "var t0 = x1.field_0x1;", "x1.field_0x1 = x4;", "return t0;"]


def test_a_store_names_a_live_read_made_at_a_computed_address():
    """A read at a computed address is spelled by its address and not by a field, so a
    store matching fields by spelling did not name it: `add x0, x1, x5; ldur x3, [x0,
    #-1]; stur x4, [x1, #7]; mov x0, x3` returned `(x1 + x5 - 1).field_0x1` read AFTER
    the store, which writes it when x5 is 8 (#341). Each such read is recorded and every
    heap store names it, and the mirror: a store at a computed address may write any
    field of any object, so it names every live read of the heap. The frame stays out,
    as two fields of the object model do, and so does an element at a data offset
    against a field below it (#375 for one that reaches it)."""
    lift = _lift_329
    comp = ("add", "x0, x1, x5")
    for read, store, decl, line in (
            # the issue, at each width, and its stores: a pair, an unrelated base,
            # an element
            (("ldur", "x3, [x0, #-1]"), ("stur", "x4, [x1, #7]"),
             "(x1 + x5 - 1).field_0x1", "x1.field_0x8 = x4;"),
            (("ldur", "w3, [x0, #-1]"), ("stur", "w4, [x1, #7]"),
             "(x1 + x5 - 1).field_0x1", "x1.field_0x8 = x4;"),
            (("ldurb", "w3, [x0, #-1]"), ("sturb", "w4, [x1, #7]"),
             "(x1 + x5 - 1).field1_0x1", "x1.field1_0x8 = x4;"),
            (("ldur", "x3, [x0, #7]"), ("stur", "x4, [x1, #0xf]"),
             "(x1 + x5).field_0x8", "x1.field_0x10 = x4;"),
            (("ldur", "x3, [x0, #-1]"), ("stp", "x4, x6, [x1, #7]"),
             "(x1 + x5 - 1).field_0x1", "x1.field_0x8 = x4;"),
            (("ldur", "x3, [x0, #-1]"), ("stur", "x4, [x2, #7]"),
             "(x1 + x5 - 1).field_0x1", "x2.field_0x8 = x4;"),
            (("ldur", "x3, [x0, #-1]"), ("str", "x4, [x2, x6, lsl #3]"),
             "(x1 + x5 - 1).field_0x1", "x2[x6] = x4;"),
            # the mirror: the store is the computed one, at offset 0 and past it, a
            # pair, a displacement below the base, an element
            (("ldur", "x3, [x1, #7]"), ("stur", "x4, [x0, #-1]"),
             "x1.field_0x8", "(x1 + x5 - 1).field_0x1 = x4;"),
            (("ldur", "w3, [x1, #0xf]"), ("stur", "w4, [x0, #7]"),
             "x1.field_0x10", "(x1 + x5).field_0x8 = x4;"),
            (("ldurb", "w3, [x2, #7]"), ("sturb", "w4, [x0, #-1]"),
             "x2.field1_0x8", "(x1 + x5 - 1).field1_0x1 = x4;"),
            (("ldur", "x3, [x2, #0xf]"), ("stp", "x4, x6, [x0, #-1]"),
             "x2.field_0x10", "(x1 + x5 - 1).field_0x1 = x4;"),
            (("ldur", "x3, [x2, #7]"), ("stur", "x4, [x1, #-0x10]"),
             "x2.field_0x8", "(x1 - 16).field_0x1 = x4;"),
            (("ldr", "x3, [x2, x6, lsl #3]"), ("stur", "x4, [x0, #-1]"),
             "x2[x6]", "(x1 + x5 - 1).field_0x1 = x4;")):
        got = lift(comp, read, store, ("mov", "x0, x3"))
        assert got[0] == f"var t0 = {decl};" and line in got and got[-1] == (
            "return t0;"), (read, store, got)
    # A frame slot is not the heap, two plain fields at different offsets are two
    # addresses, and a field below the data offset is no element: nothing is named
    # for any of them.
    assert lift(comp, ("ldur", "x3, [x0, #-1]"), ("stur", "x4, [x29, #-8]"),
                ("mov", "x0, x3")) == ["return (x1 + x5 - 1).field_0x1;"]
    assert lift(("sub", "x0, x29, #0x10"), ("ldur", "x3, [x0, #0xf]"),
                ("stur", "x4, [x1, #7]"), ("mov", "x0, x3")) == [
        "x1.field_0x8 = x4;", "return (FP - 16).field_0x10;"]
    assert lift(("add", "x0, x29, #8"), ("ldur", "x3, [x1, #0xf]"),
                ("stur", "x4, [x0, #-1]"), ("mov", "x0, x3")) == [
        "FP.field_0x8 = x4;", "return x1.field_0x10;"]
    elem = ("add", "x5, x2, x6, lsl #3")
    assert lift(elem, ("ldur", "x3, [x5, #0x17]"), ("stur", "x4, [x1, #7]"),
                ("mov", "x0, x3")) == ["x1.field_0x8 = x4;", "return x2[x6];"]
    assert lift(("ldur", "x3, [x1, #0xf]"), elem, ("stur", "x4, [x5, #0x17]"),
                ("mov", "x0, x3")) == ["x2[x6] = x4;", "return x1.field_0x10;"]
    assert lift(("ldur", "x3, [x1, #7]"), ("stur", "x4, [x2, #0xf]"),
                ("mov", "x0, x3")) == ["x2.field_0x10 = x4;", "return x1.field_0x8;"]


def test_an_element_store_names_an_element_read_through_another_base():
    """A store names the live values that read what it writes. A field is matched by its
    selector under any base, since two registers may hold one object, but an element was
    matched by its base's text: `add x2, x3, x4, lsl #3; ldur x0, [x2, #0x17]; add x5,
    x6, x7, lsl #3; stur x9, [x5, #0x17]` printed `x6[x7] = x9;` and then
    `return x3[x4];`, the element after the store, where the machine returns it as it was
    before (#343). The two are one element when x6 is x3 and x7 is x4. Now an element
    store names every element read, whatever its base and index. A field below the
    data offset against an element is two things in the object model, as before."""
    lift = _lift_329
    ret = ("mov", "x0, x8")
    for read, store, line in (
            ((("add", "x2, x3, x4, lsl #3"), ("ldur", "x8, [x2, #0x17]")),
             (("add", "x5, x6, x7, lsl #3"), ("stur", "x9, [x5, #0x17]")),
             "x6[x7] = x9;"),
            ((("ldr", "x8, [x3, x4, lsl #3]"),),
             (("str", "x9, [x6, x7, lsl #3]"),), "x6[x7] = x9;"),
            ((("ldr", "x8, [x3, x4, lsl #3]"),),
             (("add", "x5, x6, x7, lsl #3"), ("stur", "x9, [x5, #0x17]")),
             "x6[x7] = x9;"),
            ((("add", "x2, x3, x4, lsl #3"), ("ldur", "x8, [x2, #0x17]")),
             (("str", "x9, [x3, x7, lsl #3]"),), "x3[x7] = x9;")):
        got = lift(*read, *store, ret)
        assert got[0].startswith("var t0 = x3[x4]") and line in got and got[-1] == (
            "return t0;"), (read, store, got)
    # The same element through the same base was named before, and still is.
    assert lift(("ldr", "x8, [x2, x4, lsl #3]"), ("str", "x9, [x2, x4, lsl #3]"),
                ret) == ["var t0 = x2[x4];", "x2[x4] = x9;", "return t0;"]
    # A field below the data offset is not an element, either way round.
    assert lift(("ldur", "x8, [x1, #7]"), ("add", "x5, x6, x7, lsl #3"),
                ("stur", "x9, [x5, #0x17]"), ret) == ["x6[x7] = x9;",
                                                      "return x1.field_0x8;"]
    assert lift(("add", "x5, x2, x4, lsl #3"), ("ldur", "x8, [x5, #0x17]"),
                ("stur", "x9, [x1, #7]"), ret) == ["x1.field_0x8 = x9;",
                                                   "return x2[x4];"]


def test_a_pair_store_reads_its_registers_and_address_before_either_store():
    """An `stp` reads both registers, and its address, before it writes either word, and
    it prints as two stores. The second was built before the first was printed, so a
    value that read the first word printed as the read under the line that had just
    changed it: `ldur x1, [x13, #8]; stp x2, x1, [x13, #8]` printed `x13.field_0x9 =
    x2;` and then `x13.field_0x11 = x13.field_0x9;`, which stores x2 twice where the
    machine stores the old word (#372). The first store now names what the second
    reads of the word it writes: the register stored, live after the `stp` or not, and
    the base the second word is addressed off."""
    lift = _lift_329
    # A field, with and without write back, a w pair, and the same register twice.
    for load, pair, want in (
            (("ldur", "x1, [x13, #8]"), ("stp", "x2, x1, [x13, #8]"),
             ["var t0 = x13.field_0x9;", "x13.field_0x9 = x2;", "x13.field_0x11 = t0;",
              "return x0;"]),
            (("ldur", "x1, [x13, #0x10]"), ("stp", "x2, x1, [x13, #0x10]!"),
             ["var t0 = x13.field_0x11;", "x13.field_0x11 = x2;",
              "x13.field_0x19 = t0;", "x13 += 16;", "return x0;"]),
            (("ldr", "x1, [x13]"), ("stp", "x2, x1, [x13], #0x10"),
             ["var t0 = x13.field_0x1;", "x13.field_0x1 = x2;", "x13.field_0x9 = t0;",
              "x13 += 16;", "return x0;"]),
            (("ldr", "w1, [x13, #8]"), ("stp", "w2, w1, [x13, #8]"),
             ["var t0 = x13.field_0x9;", "x13.field_0x9 = x2;", "x13.field_0xd = t0;",
              "return x0;"]),
            (("ldr", "x1, [x13, #8]"), ("stp", "xzr, x1, [x13, #8]"),
             ["var t0 = x13.field_0x9;", "x13.field_0x9 = 0;", "x13.field_0x11 = t0;",
              "return x0;"])):
        assert lift(load, pair) == want, (load, pair)
    # A value computed from the read, and one that is live after the pair.
    assert lift(("ldr", "x1, [x13, #8]"), ("add", "x1, x1, #5"),
                ("stp", "x2, x1, [x13, #8]")) == [
        "var t0 = x13.field_0x9 + 5;", "x13.field_0x9 = x2;", "x13.field_0x11 = t0;",
        "return x0;"]
    assert lift(("ldr", "x1, [x13, #8]"), ("stp", "x2, x1, [x13, #8]"),
                ("mov", "x0, x1")) == [
        "var t0 = x13.field_0x9;", "x13.field_0x9 = x2;", "x13.field_0x11 = t0;",
        "return t0;"]
    # The two words swapped: only the one the first store writes needs a name.
    assert lift(("ldp", "x1, x2, [x13, #8]"), ("stp", "x2, x1, [x13, #8]")) == [
        "var t0 = x13.field_0x9;", "x13.field_0x9 = x13.field_0x11;",
        "x13.field_0x11 = t0;", "return x0;"]
    # An element and an address the lifter computed.
    assert lift(("add", "x16, x13, x8, lsl #3"), ("ldr", "x1, [x16]"),
                ("stp", "x2, x1, [x16]")) == [
        "var t0 = x13[x8];", "x13[x8] = x2;", "x13[x8 + 1] = t0;", "return x0;"]
    assert lift(("add", "x16, x13, x8"), ("ldur", "x1, [x16, #8]"),
                ("stp", "x2, x1, [x16, #8]")) == [
        "var t0 = (x13 + x8).field_0x9;", "(x13 + x8).field_0x9 = x2;",
        "(x13 + x8).field_0x11 = t0;", "return x0;"]
    # The address the second word is stored at reads the first: a base loaded from
    # the field, and an index read from it.
    assert lift(("ldr", "x9, [x13, #8]"), ("stp", "x2, x1, [x9, #8]")) == [
        "var t0 = x13.field_0x9;", "x13.field_0x9.field_0x9 = x2;",
        "t0.field_0x11 = x1;", "return x0;"]
    assert lift(("ldr", "x8, [x13, #8]"), ("and", "x8, x8, #7"),
                ("add", "x16, x13, x8, lsl #3"), ("stp", "x2, x1, [x16, #8]")) == [
        "var t0 = x13 + ((x13.field_0x9 & 7) << 3);",
        "(x13 + ((x13.field_0x9 & 7) << 3)).field_0x9 = x2;", "t0.field_0x11 = x1;",
        "return x0;"]


def test_a_pair_store_that_reads_neither_word_prints_as_it_did():
    """Guards for #372: the second store of a pair takes a name only for what the
    first store may write. A value that reads the SECOND word, or another field,
    prints in place; a frame pair is two slots, as before; and an `ldp` into its own
    base still reads both words off the base as it was (#293)."""
    lift = _lift_329
    assert lift(("ldr", "x1, [x13, #0x10]"), ("add", "x1, x1, #1"),
                ("stp", "x2, x1, [x13, #8]")) == [
        "x13.field_0x9 = x2;", "x13.field_0x11 += 1;", "return x0;"]
    assert lift(("ldr", "x2, [x13, #0x10]"), ("stp", "x2, x1, [x13, #8]")) == [
        "x13.field_0x9 = x13.field_0x11;", "x13.field_0x11 = x1;", "return x0;"]
    assert lift(("ldr", "x1, [x12, #0x18]"), ("stp", "x2, x1, [x13, #8]")) == [
        "x13.field_0x9 = x2;", "x13.field_0x11 = x12.field_0x19;", "return x0;"]
    assert lift(("sub", "x15, x15, #0x20"), ("str", "x3, [x15, #8]"),
                ("ldr", "x1, [x15, #8]"), ("stp", "x2, x1, [x15, #8]"),
                ("ldr", "x0, [x15, #0x10]"), ("add", "x15, x15, #0x20")) == [
        "return x3;"]
    assert lift(("ldp", "x13, x0, [x13, #8]")) == ["return x13.field_0x11;"]
    assert lift(("ldp", "x0, x13, [x13, #8]"), ("mov", "x1, x13")) == [
        "return x13.field_0x9;"]


def test_a_field_read_and_an_element_that_may_be_one_word_are_named_before_the_store():
    """The elements of an object are the words from its data offset up, and a read at
    a fixed offset that reaches that far is one of them: `ldur x4, [x13, #0x17]; add
    x16, x13, x8, lsl #3; stur x1, [x16, #0x17]; mov x0, x4` printed `x13[x8] = x1;`
    and then `return x13.field_0x18;`, the word after the store, where the machine
    returns it as it was before whenever x8 is 0 (#375). An element store now names
    each live field read with a byte at the data offset or past it, a field store
    names each live element read whose data offset its bytes end past, and both
    through any base, since two registers may hold one object."""
    lift = _lift_329
    elem, ret = ("add", "x16, x13, x8, lsl #3"), ("mov", "x0, x4")
    # The issue and its mirror, at the data offset and above it, through another base.
    for base in ("x13", "x12"):
        for off, sel in ((0x17, "0x18"), (0x27, "0x28")):
            assert lift(("ldur", f"x4, [{base}, #{off:#x}]"), elem,
                        ("stur", "x1, [x16, #0x17]"), ret) == [
                f"var t0 = {base}.field_{sel};", "x13[x8] = x1;", "return t0;"]
            assert lift(elem, ("ldur", "x4, [x16, #0x17]"),
                        ("stur", f"x1, [{base}, #{off:#x}]"), ret) == [
                "var t0 = x13[x8];", f"{base}.field_{sel} = x1;", "return t0;"]
    # The width decides where a read ends: eight bytes at 0xc reach 0x10 and four do
    # not, a byte inside the data is in it, and sixteen bytes from 0x8 reach it.
    low = ("add", "x16, x13, x8, lsl #2")
    assert lift(("ldur", "x4, [x13, #0xb]"), low, ("stur", "w1, [x16, #0xf]"), ret) == [
        "var t0 = x13.field_0xc;", "x13[x8] = x1;", "return t0;"]
    assert lift(("ldur", "w4, [x13, #0xb]"), low, ("stur", "w1, [x16, #0xf]"), ret) == [
        "x13[x8] = x1;", "return x13.field_0xc;"]
    assert lift(("ldurb", "w4, [x13, #0x1a]"), elem, ("stur", "x1, [x16, #0x17]"),
                ret) == ["var t0 = x13.field1_0x1b;", "x13[x8] = x1;", "return t0;"]
    assert lift(("ldur", "q0, [x13, #7]"), low, ("stur", "w1, [x16, #0xf]"),
                ("stur", "q0, [x20, #7]"))[:2] == [
        "var t0 = x13.field16_0x8;", "x13[x8] = x1;"]
    assert lift(elem, ("ldur", "x4, [x16, #0x17]"), ("sturb", "w1, [x13, #0x1a]"),
                ret) == ["var t0 = x13[x8];", "x13.field1_0x1b = x1;", "return t0;"]
    # A field that ends below the data offset is the header, either way round.
    assert lift(("ldur", "x4, [x13, #0xf]"), elem, ("stur", "x1, [x16, #0x17]"),
                ret) == ["x13[x8] = x1;", "return x13.field_0x10;"]
    assert lift(elem, ("ldur", "x4, [x16, #0x17]"), ("stur", "x1, [x13, #0xf]"),
                ret) == ["x13.field_0x10 = x1;", "return x13[x8];"]
    assert lift(("ldur", "x4, [x13, #-1]"), elem, ("stur", "x1, [x16, #0x17]"),
                ret) == ["x13[x8] = x1;", "return x13.tags;"]
    # An element with no data offset shown is the access at its address: it may be
    # any field, the header too, and any field store may write it.
    for off, sel in ((7, "field_0x8"), (0x17, "field_0x18"), (-1, "tags")):
        assert lift(("ldur", f"x4, [x12, #{off:#x}]"), ("str", "x1, [x13, x8, lsl #3]"),
                    ret) == [f"var t0 = x12.{sel};", "x13[x8] = x1;", "return t0;"]
        assert lift(("ldr", "x4, [x13, x8, lsl #3]"), ("stur", f"x1, [x12, #{off:#x}]"),
                    ret) == ["var t0 = x13[x8];", f"x12.{sel} = x1;", "return t0;"]
    assert lift(("ldr", "x4, [x13, #0x10]"), elem, ("str", "x1, [x16]"), ret) == [
        "var t0 = x13.field_0x11;", "x13[x8] = x1;", "return t0;"]
    assert lift(elem, ("ldr", "x4, [x16]"), ("str", "x1, [x13, #0x10]"), ret) == [
        "var t0 = x13[x8];", "x13.field_0x11 = x1;", "return t0;"]
    # The frame is not the heap, and neither is the thread.
    frame = ("sub", "x0, x29, #0x10")
    assert lift(frame, ("ldur", "x4, [x0, #0x1f]"), elem, ("stur", "x1, [x16, #0x17]"),
                ret) == ["x13[x8] = x1;", "return (FP - 16).field_0x20;"]
    assert lift(frame, elem, ("ldur", "x4, [x16, #0x17]"), ("stur", "x1, [x0, #0x1f]"),
                ret) == ["(FP - 16).field_0x20 = x1;", "return x13[x8];"]
    assert lift(("ldr", "x4, [x26, #0x700]"), elem, ("stur", "x1, [x16, #0x17]"),
                ret) == ["x13[x8] = x1;", "return THR.field_0x700;"]
    assert lift(elem, ("ldur", "x4, [x16, #0x17]"), ("str", "x1, [x26, #0x700]"),
                ret) == ["THR.field_0x700 = x1;", "return x13[x8];"]


def test_a_store_through_a_pointer_read_out_of_the_thread_or_the_frame_names_elements():
    """A store INTO the thread or the frame writes no word of the heap, so it names
    no element read. A store through a pointer LOADED from one writes the object the
    pointer holds, which may be any: `add x16, x13, x8, lsl #3; ldur x5, [x16, #0x17];
    ldr x9, [x26, #0x40]; stur x1, [x9, #0x17]; mov x0, x5` printed
    `THR.field_0x40.field_0x18 = x1;` and then `return x13[x8];`, the word the store
    wrote wherever the thread's field holds x13 and x8 is 0. The base's spelling
    starting at THR or at a frame address said the first and was taken for the
    second (#375)."""
    lift = _lift_329
    read = (("add", "x16, x13, x8, lsl #3"), ("ldur", "x5, [x16, #0x17]"))
    ret = ("mov", "x0, x5")
    assert lift(*read, ("ldr", "x9, [x26, #0x40]"), ("stur", "x1, [x9, #0x17]"),
                ret) == ["var t0 = x13[x8];", "THR.field_0x40.field_0x18 = x1;",
                         "return t0;"]
    assert lift(*read, ("ldr", "x9, [x26, #0x40]"), ("ldur", "x9, [x9, #7]"),
                ("stur", "x1, [x9, #0x17]"), ret) == [
        "var t0 = x13[x8];", "THR.field_0x40.field_0x8.field_0x18 = x1;", "return t0;"]
    assert lift(*read, ("sub", "x10, x29, #0x20"), ("ldr", "x9, [x10]"),
                ("stur", "x1, [x9, #0x17]"), ret) == [
        "var t0 = x13[x8];", "(FP - 32).field_0x1.field_0x18 = x1;", "return t0;"]
    # Into the thread, the frame and the object pool, which are no object's words.
    assert lift(*read, ("str", "x1, [x26, #0x40]"), ret) == [
        "THR.field_0x40 = x1;", "return x13[x8];"]
    assert lift(*read, ("sub", "x10, x29, #0x20"), ("str", "x1, [x10, #0x18]"),
                ret) == ["(FP - 32).field_0x19 = x1;", "return x13[x8];"]
    assert lift(*read, ("str", "x1, [x27, #0x40]"), ret) == [
        "PP.field_0x40 = x1;", "return x13[x8];"]


#: An inline allocation as `_addr_facts` proves one: the top loaded from the thread,
#: bumped, stored back and tagged, and the header store.
_FRESH_375 = (("ldr", "x0, [x26, #0x50]"), ("add", "x1, x0, #0x30"),
              ("str", "x1, [x26, #0x50]"), ("add", "x0, x0, #1"),
              ("stur", "x2, [x0, #-1]"))
_FRESH_375_LINES = ["var t0 = THR.field_0x50;", "THR.field_0x50 += 48;",
                    "(t0 + 1).tags = x2;"]


def test_an_element_read_after_an_allocation_is_named_by_a_store_into_it():
    """A store into an object the rows before it allocated names the element reads
    made since the allocation, as any field store does (#375): one through the new
    pointer, and one through a field the pointer was stored to, are words of the new
    object. `(t0 + 1).field_0x18 = x3;` was followed by `return (t0 + 1)[x8];`."""
    lift = _lift_329
    store, tail = ("stur", "x3, [x0, #0x17]"), (("mov", "x6, x0"), ("mov", "x0, x5"))
    assert lift(*_FRESH_375, ("add", "x16, x0, x8, lsl #3"), ("ldur", "x5, [x16, #0x17]"),
                store, *tail) == _FRESH_375_LINES + [
        "var t1 = (t0 + 1)[x8];", "(t0 + 1).field_0x18 = x3;", "return t1;"]
    assert lift(*_FRESH_375, ("stur", "x0, [x13, #7]"), ("ldur", "x9, [x13, #7]"),
                ("add", "x16, x9, x8, lsl #3"), ("ldur", "x5, [x16, #0x17]"), store,
                *tail) == _FRESH_375_LINES + [
        "x13.field_0x8 = t0 + 1;", "var t1 = x13.field_0x8[x8];",
        "(t0 + 1).field_0x18 = x3;", "return t1;"]
    # Of two allocations, a read between them is after the first and before the
    # second, and a store through any other base is no store into a new object.
    read = (("add", "x16, x13, x8, lsl #3"), ("ldur", "x5, [x16, #0x17]"))
    assert lift(*_FRESH_375, ("mov", "x10, x0"), *read, *_FRESH_375, store,
                ("stur", "x3, [x10, #0x17]"), tail[1]) == _FRESH_375_LINES + [
        "var t1 = THR.field_0x50;", "THR.field_0x50 += 48;", "(t1 + 1).tags = x2;",
        "(t1 + 1).field_0x18 = x3;", "var t2 = x13[x8];", "(t0 + 1).field_0x18 = x3;",
        "return t2;"]
    assert lift(*read, *_FRESH_375, ("stur", "x3, [x12, #0x17]"), *tail) == (
        _FRESH_375_LINES + ["var t1 = x13[x8];", "x12.field_0x18 = x3;", "return t1;"])


def test_an_element_read_before_an_allocation_is_not_named_by_a_store_into_it():
    """An element read before an object was allocated is a word of some other
    object, and no store into the new one writes it, as no raw store into one
    reaches a field read (#341). The element stores of #375 named them: in 12 of 40
    ranges sampled from the nine binaries the new name was a typed data element in
    front of the header store of an allocation, `var t1 = x13[x8]; (t0 + 1).tags =
    x2;`. A guard against that: main, with no such rule, prints these as they are
    here."""
    lift = _lift_329
    tail = (("mov", "x6, x0"), ("mov", "x0, x5"))
    for read in ((("ldr", "x5, [x13, x8, lsl #3]"),),
                 (("add", "x16, x13, x8, lsl #3"), ("ldur", "x5, [x16, #0x17]"))):
        assert lift(*read, *_FRESH_375, *tail) == _FRESH_375_LINES + ["return x13[x8];"]
        assert lift(*read, *_FRESH_375, ("stur", "x3, [x0, #0x17]"), *tail) == (
            _FRESH_375_LINES + ["(t0 + 1).field_0x18 = x3;", "return x13[x8];"])


def test_a_body_walked_again_tells_the_reads_before_an_allocation_from_those_after():
    """A body is walked more than once (#204), and a walk tells what it read before
    an allocation from what it read after by how many names it had made by then. The
    counts are that walk's: kept with what the walks share, an earlier walk's were
    searched along with this one's, and the read before the allocation was named with
    the one after, `var t4 = x13[t2]; var t5 = x12[t2];`. The loop is the `pinned`
    one of `_GOTO_SHAPES`, which takes three walks; only the read after is named, and
    main, with no such rule, names neither."""
    from jadart import expr
    loop = [r[1:] for r in _GOTO_SHAPES["pinned"][0][:13]]
    walks, init = [], expr.Lifter.__init__
    try:
        def counted(self, *a, **k):
            walks.append(1)
            init(self, *a, **k)
        expr.Lifter.__init__ = counted
        got = _lift_329(
            *loop, ("ldr", "x5, [x13, x8, lsl #3]"), *_FRESH_375,
            ("ldr", "x7, [x12, x8, lsl #3]"), ("stur", "x4, [x0, #0x17]"),
            ("mov", "x6, x0"), ("add", "x0, x5, x7"))
    finally:
        expr.Lifter.__init__ = init
    assert len(walks) == 3, walks
    assert got[-6:] == [
        "t3 = THR.field_0x50;", "THR.field_0x50 += 48;", "(t3 + 1).tags = x2;",
        "var t4 = x12[t2];", "(t3 + 1).field_0x18 = t1;", "return x13[t2] + t4;"], got


def test_an_element_index_is_taken_to_be_zero_or_more():
    """What #375 names rests on an ASSUMPTION the lifter does not prove: an element's
    index is never negative, so `B[I]` off data offset D is at D or above and the
    header under it is no element. The compiler checks an index against the length
    before it uses one, and nothing in the rows says it did. Where it did not, `asr
    x8, x7, #63` making the index 0 or -1, the store below writes `x13.field_0x10`
    when x7 is negative and the value returned is printed as read after it. This
    keeps what is printed, wrong as it is there, so a change to the rule shows. A
    guard: main prints the same."""
    lift = _lift_329
    sign, elem = ("asr", "x8, x7, #63"), ("add", "x16, x13, x8, lsl #3")
    assert lift(sign, ("ldur", "x4, [x13, #0xf]"), elem, ("stur", "x1, [x16, #0x17]"),
                ("mov", "x0, x4")) == ["x13[x7 >> 63] = x1;", "return x13.field_0x10;"]
    assert lift(sign, elem, ("ldur", "x5, [x16, #0x17]"), ("stur", "x1, [x13, #0xf]"),
                ("mov", "x0, x5")) == ["x13.field_0x10 = x1;", "return x13[x7 >> 63];"]


def _slots_375(shape, n):
    """About `n` rows that keep many reads in frame slots under many stores: "fields",
    header reads and then element stores; "elems", element reads at two data offsets
    and then field stores that end between them; "chains", reads four fields deep
    and then element stores."""
    rows = [("sub", "x15, x15, #0x8000")]
    if shape == "fields":
        for j in range(n // 5):
            rows += [("ldur", f"x2, [x{9 + j % 4}, #{7 + 8 * (j % 2)}]"),
                     ("str", f"x2, [x15, #{8 * (j % 4000)}]")]
    elif shape == "elems":
        for j in range(64):
            rows += [("add", "x8, x8, #1"), ("add", "x17, x11, x8, lsl #3"),
                     ("ldur", "x3, [x17, #0xf]")]
        for j in range((n - 200) // 6):
            rows += [("add", "x8, x8, #1"), ("add", "x16, x13, x8, lsl #3"),
                     ("ldur", "x2, [x16, #0x17]"),
                     ("str", f"x2, [x15, #{8 * (j % 4000)}]")]
        return rows + [("stur", "x1, [x12, #0xf]")] * (n - len(rows)) + [("ret", "")]
    else:
        for j in range(n // 8):
            rows += [("ldur", f"x2, [x{9 + j % 4}, #7]"), ("ldur", "x2, [x2, #7]"),
                     ("ldur", "x2, [x2, #0xf]"), ("ldur", "x2, [x2, #7]"),
                     ("str", f"x2, [x15, #{8 * (j % 4000)}]")]
    while len(rows) < n:
        rows += [("add", "x16, x13, x8, lsl #3"), ("stur", "x1, [x16, #0x17]")]
    return rows + [("ret", "")]


def test_reads_kept_in_slots_under_many_stores_cost_the_same_per_row():
    """Every store asked every slot of the frame whether it reads what the store
    writes, and #375 gave it two more things to ask: element reads kept in slots
    under field stores took 7.7 s at 4,000 rows where they had taken 1.6 (0.11
    now), and field reads under element stores 0.62 s where 0.23 (0.11 now). A
    store past the first few (`_PIN_WALK`) now keeps the texts it does not write,
    under everything the answer is made of, and the next store that asks the same
    asks only about the texts it has not seen; an element is looked for among the
    reads made since the text was last asked (`_elem_below`). Counted, not timed:
    the Python calls to lift each shape, per row, at about 1,000 rows and at about
    2,000. On main the larger takes 1.47, 1.54 and 1.27 times the calls per row of
    the smaller, and here 1.00, 1.02 and 1.00."""
    from jadart import expr
    calls = [0]

    def count(frame, event, arg):
        if event == "call":
            calls[0] += 1

    def per_row(shape, n):
        rows = [(i * 4, mn, op, "") for i, (mn, op) in
                enumerate(_slots_375(shape, n))]
        expr.lift_function(rows)                # the memos, filled
        calls[0] = 0
        was = sys.getprofile()
        sys.setprofile(count)
        try:
            expr.lift_function(rows)
        finally:
            sys.setprofile(was)
        return calls[0] / len(rows)

    for shape in ("fields", "elems", "chains"):
        small, large = per_row(shape, 1000), per_row(shape, 2000)
        assert large <= small * 1.1, (shape, small, large)


#: `Assembler::TryAllocateObject` and `TryAllocateArray` (assembler_arm64.cc, 3.12.2),
#: and the register bump of the allocation stubs (stub_code_compiler_arm64.cc,
#: AllocateArray), each up to the header store.
_ALLOC_OBJECT = [("ldp", "x0, x1, [x26, #0x50]"), ("add", "x0, x0, #0x20"),
                 ("cmp", "x1, x0"), ("b.ls", "#0x24"), ("str", "x0, [x26, #0x50]"),
                 ("sub", "x0, x0, #0x1f"), ("mov", "x2, #0x3e19c"),
                 ("stur", "x2, [x0, #-1]"), ("ret", ""), ("bl", "#0x1000")]
_ALLOC_ARRAY = [("ldr", "x0, [x26, #0x50]"), ("adds", "x1, x0, #0x30"),
                ("b.hs", "#0x2c"), ("ldr", "x2, [x26, #0x58]"), ("cmp", "x1, x2"),
                ("b.hs", "#0x2c"), ("str", "x1, [x26, #0x50]"), ("add", "x0, x0, #1"),
                ("mov", "x2, #0x5e09c"), ("stur", "x2, [x0, #-1]"), ("ret", ""),
                ("bl", "#0x1000")]
_ALLOC_STUB = [("ldr", "x0, [x26, #0x50]"), ("adds", "x1, x0, x2"), ("b.hs", "#0x2c"),
               ("ldr", "x3, [x26, #0x58]"), ("cmp", "x1, x3"), ("b.hs", "#0x2c"),
               ("str", "x1, [x26, #0x50]"), ("add", "x0, x0, #1"),
               ("orr", "x2, x2, #0x5e09c"), ("stur", "x2, [x0, #-1]"), ("ret", ""),
               ("bl", "#0x1000")]


def test_an_inline_allocation_makes_an_object_pointer_and_nothing_else_does():
    """An inline allocation is arithmetic that makes an object pointer: top is loaded
    from a thread field, bumped, stored back to the same field and tagged, and the
    store after it is the new object's header. Spelling every offset 0 off a sum as an
    address store, as the fix that was reverted did, rewrote about 16,000 true header
    stores on the nine binaries, `(t1 + 1).tags = x2 | 0x5e09c;` among them (#329).
    The rows prove it (`_addr_facts`), on every way in and with no table of thread
    offsets, and each thing the proof needs is taken away in turn."""
    lift = _lift_329
    assert "(t0 - 31).tags = 0x3e19c;   // 127182 if Smi" in lift(*_ALLOC_OBJECT)
    assert "(t0 + 1).tags = 0x5e09c;   // 192590 if Smi" in lift(*_ALLOC_ARRAY)
    assert "(t0 + 1).tags = x2 | 0x5e09c;" in lift(*_ALLOC_STUB)
    load, bump, back, tag, store = (("ldr", "x0, [x26, #0x50]"),
                                    ("add", "x1, x0, #0x30"),
                                    ("str", "x1, [x26, #0x50]"), ("add", "x0, x0, #1"),
                                    ("stur", "x2, [x0, #-1]"))
    proven = ["var t0 = THR.field_0x50;", "THR.field_0x50 += 48;", "(t0 + 1).tags = x2;",
              "return t0 + 1;"]
    assert lift(load, bump, back, tag, store) == proven
    # The pointer is one in a copy and under a name; a field of it is a field.
    assert lift(load, bump, back, tag, ("mov", "x4, x0"), ("stur", "x2, [x4, #-1]"),
                ("mov", "x0, x4")) == proven
    assert lift(load, bump, back, tag, ("add", "x4, x0, #0x10"),
                ("stur", "x2, [x4, #-1]"))[2] == "t0.field_0x11 = x2;"
    for rows, want in (
            # stored back to another field of the thread, or not stored back
            ([load, bump, ("str", "x1, [x26, #0x60]"), tag, store],
             "THR.field_0x50.field_0x1 = x2;"),
            ([load, bump, tag, store], "THR.field_0x50.field_0x1 = x2;"),
            # stored back on one way in only
            ([load, bump, ("cbz", "x5, #0x10"), back, tag, store], "t1.field_0x1 = x2;"),
            # the bump is not one: nothing added, or the low half stored
            ([load, ("str", "x0, [x26, #0x50]"), tag, store], "t0.field_0x1 = x2;"),
            ([load, bump, ("str", "w1, [x26, #0x50]"), tag, store],
             "t0.field_0x1 = x2;"),
            # a call between the load and the store back may have moved top
            ([load, bump, ("bl", "#0x1000"), back, tag, store], "t2.field_0x1 = t1;"),
            # the start was written before the tag, or tagged with something else
            ([load, bump, back, ("mov", "x0, x7"), tag, store], "x7.field_0x1 = x2;"),
            ([load, bump, back, ("add", "x0, x0, #2"), store], "t0.field_0x2 = x2;"),
            # not the thread
            ([("ldr", "x0, [x5, #0x50]"), bump, ("str", "x1, [x5, #0x50]"), tag, store],
             "t0.field_0x1 = x2;"),
            # the end taken back by the wrong size
            ([("ldr", "x0, [x26, #0x50]"), ("add", "x0, x0, #0x20"),
              ("str", "x0, [x26, #0x50]"), ("sub", "x0, x0, #0x1e"), store],
             "(t0 - 31).field_0x1 = x2;")):
        got = lift(*rows)
        assert want in got and not any(".tags" in ln for ln in got), (rows, got)


def test_the_address_facts_cost_the_same_per_instruction_at_any_length():
    """`_addr_facts` is made once for a body, however many rows ask and however many
    times the body is walked, and each block is taken again only while a register's
    fact is raised, at most twice. Counted, not timed: the facts met and the constants
    added per instruction, over runs of add and store pairs, of joins and of loops, in
    a row and nested, at 40 and at 160 of each (#329). A guard: main has no such
    analysis, and the fix that was reverted folded text at every store instead, which
    took add and store pairs 1.65 times as long as main."""
    from jadart import expr
    from jadart.expr import lift_function
    made, work = [0], [0]
    facts, meet, add = expr._addr_facts, expr._af_meet, expr._af_add

    def counted_facts(*args, **kw):
        made[0] += 1
        return facts(*args, **kw)

    def counted_meet(a, b):
        work[0] += 1 + len(a) + len(b)
        return meet(a, b)

    def counted_add(f, k):
        work[0] += 1
        return add(f, k)

    def shape(name, n):
        # Each has a read the walk holds only a name for, off a register one way in
        # adds to, so the facts are asked for and no nearest write answers it (#346).
        rows = [("cbz", "x5, #0x8"), ("add", "x7, x7, #8"),
                ("ldur", "x2, [x7, #-1]")] if name == "pairs" else []
        for i in range(n):
            at = len(rows) * 4
            if name == "pairs":
                rows += [("add", "x0, x0, #8"), ("stur", "x3, [x0, #-1]")]
            elif name == "joins":
                rows += [("cbz", "x5, #%#x" % (at + 8)), ("add", "x1, x1, #8"),
                         ("ldur", "x2, [x1, #-1]")]
            elif name == "loops":
                rows += [("stur", "w22, [x1, #-1]"), ("add", "x1, x1, #0x10"),
                         ("cmp", "x1, x3"), ("b.lo", "#%#x" % at)]
            elif name == "nested":
                rows += [("stur", f"w22, [x{1 + i % 6}, #-1]"),
                         ("add", f"x{1 + i % 6}, x{1 + i % 6}, #0x10")]
        if name == "nested":
            for i in range(n):
                rows += [("cmp", "x1, x9"), ("b.lo", "#%#x" % ((n - 1 - i) * 8))]
        return rows + [("ret", "")]

    def per_instruction(name, n):
        rows = shape(name, n)
        made[0] = work[0] = 0
        lift_function([(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])
        assert made[0] == 1, (name, n, made[0])
        return work[0] / len(rows)

    expr._addr_facts, expr._af_meet = counted_facts, counted_meet
    expr._af_add = counted_add
    try:
        for name in ("pairs", "joins", "loops", "nested"):
            small, large = per_instruction(name, 40), per_instruction(name, 160)
            assert large <= small * 1.25 + 1, (name, small, large)
    finally:
        expr._addr_facts, expr._af_meet, expr._af_add = facts, meet, add


_PRO_346 = [("stp", "x29, x30, [x15, #-0x10]!"), ("mov", "x29, x15"),
            ("sub", "x15, x15, #0x20")]
_EPI_346 = [("mov", "x15, x29"), ("ldp", "x29, x30, [x15], #0x10"), ("ret", "")]


def _ordinary_346(i):
    """Body `i` of a corpus of ordinary code, as `lift_function` takes it: a frame, a
    field read off an argument, and by `i` a class id tested, calls with their results
    kept in the frame, a counted loop over an array, an object allocated and its fields
    stored, or Smi arithmetic and a test."""
    f, g, cid = 7 + 8 * (i % 4), 0xf + 8 * (i % 3), 0x40 + i
    rows = _PRO_346 + [("ldr", "x1, [x29, #0x10]"), ("ldur", f"x2, [x1, #{f:#x}]")]
    at, kind = len(rows) * 4, i % 5
    if kind == 0:
        rows += [("ldur", "x3, [x2, #-1]"), ("ubfx", "x3, x3, #0xc, #0x14"),
                 ("cmp", f"x3, #{cid:#x}"), ("b.ne", f"#{at + 24:#x}"),
                 ("ldur", f"x0, [x2, #{g:#x}]"), ("stur", "x0, [x1, #0x2f]"),
                 ("mov", "x0, x2")]
    elif kind == 1:
        rows += [("mov", "x0, x2"), ("bl", f"#{0x9000 + 0x40 * i:#x}"),
                 ("stur", "x0, [x29, #-8]"), ("ldr", "x1, [x29, #0x10]"),
                 ("ldur", f"x0, [x1, #{g:#x}]"), ("bl", f"#{0xa000 + 0x40 * i:#x}"),
                 ("ldur", "x1, [x29, #-8]"), ("stur", f"x0, [x1, #{f:#x}]")]
    elif kind == 2:
        rows += [("ldur", "x3, [x2, #0xf]"), ("mov", "x4, #0"), ("mov", "x0, #0"),
                 ("cmp", "x4, x3"), ("b.ge", f"#{at + 40:#x}"),
                 ("add", "x16, x2, x4, lsl #2"), ("ldur", "x5, [x16, #0x17]"),
                 ("add", "x0, x0, x5"), ("add", "x4, x4, #2"),
                 ("b", f"#{at + 12:#x}")]
    elif kind == 3:
        rows += [("stur", "x2, [x29, #-8]"), ("bl", f"#{0xb000 + 0x40 * i:#x}"),
                 ("ldur", "x2, [x29, #-8]"), ("stur", f"x2, [x0, #{f:#x}]"),
                 ("ldr", "x3, [x29, #0x18]"), ("stur", f"x3, [x0, #{g:#x}]"),
                 ("ldur", "x4, [x3, #-1]"), ("ubfx", "x4, x4, #0xc, #0x14"),
                 ("stur", "x4, [x0, #0x2f]")]
    else:
        rows += [("ldur", f"x3, [x1, #{g:#x}]"), ("asr", "x2, x2, #1"),
                 ("asr", "x3, x3, #1"), ("add", "x4, x2, x3"),
                 ("cmp", f"x4, #{cid:#x}"), ("b.le", f"#{at + 28:#x}"),
                 ("sub", "x4, x4, x2"), ("lsl", "x0, x4, #1")]
    return [(k * 4, mn, op, "") for k, (mn, op) in enumerate(rows + _EPI_346)]


def test_a_class_id_read_off_a_loaded_register_asks_for_no_address_facts():
    """Nearly every body reads a class id, `ldur x3, [x2, #-1]`, and each one asked
    `_addr_facts` for the whole body to learn that x2 was loaded a row or two up, which
    was 2.9% of the time tier 3 takes on the clean fixture. The rows before the read
    say so (`Lifter._row_plain`), and the analysis is made for none of the twenty
    ordinary bodies here, where it was made for eight of them, and no line they print
    differs from asking it at every row (#346)."""
    from jadart import expr
    made, facts = [0], expr._addr_facts

    def counted(*args, **kw):
        made[0] += 1
        return facts(*args, **kw)

    bodies = [_ordinary_346(i) for i in range(20)]
    expr._addr_facts = counted
    try:
        out = [expr.lift_function(b) for b in bodies]
        assert made[0] == 0, made[0]
        assert "  if (((t0.field_0x8.tags >> 12) & 0xfffff) == 0x40) {" in out[0]
        assert "  t2.field_0x30 = (t3.tags >> 12) & 0xfffff;" in out[3]
        plain = expr.Lifter._row_plain
        expr.Lifter._row_plain = lambda self, a: False
        try:
            assert [expr.lift_function(b) for b in bodies] == out
        finally:
            expr.Lifter._row_plain = plain
        assert made[0] == 8, made[0]
    finally:
        expr._addr_facts = facts


def _shapes_346(name, n):
    """Bodies for the rows read before the analysis, `n` of each: `far`, a class id
    read 60 rows after its base was loaded; `reads`, every class id off one base
    loaded once at the top; `ladder`, a read under a run of branches that all meet
    above it; `moved`, a read off a copy of an address a loop adds to; `calls`, a read
    off a register a call forgot, and one off a register it kept; `made`, a read off
    a shift's result; `thread`, off a field of the thread once more is stored back;
    `stepped`, off the base a load and a store moved as they went."""
    rows = [("ldur", "x1, [x0, #7]")] if name == "reads" else []
    for i in range(n):
        at = len(rows) * 4
        if name == "far":
            rows += [("ldur", "x1, [x0, #7]")] + [("add", "x9, x9, #1")] * 60
            rows += [("ldur", "x2, [x1, #-1]"), ("stur", "x2, [x0, #0xf]")]
        elif name == "reads":
            rows += [("ldur", "x2, [x1, #-1]"), ("ubfx", "x2, x2, #0xc, #0x14"),
                     ("stur", "x2, [x0, #0xf]")]
        elif name == "ladder":
            rows += [("ldur", "x1, [x0, #7]")]
            for k in range(6):
                rows += [("cbz", f"x{3 + k}, #{at + 12 + 8 * k:#x}"),
                         ("add", "x9, x9, #1")]
            rows += [("ldur", "x2, [x1, #-1]"), ("stur", "x2, [x0, #0xf]")]
        elif name == "moved":
            rows += [("mov", "x6, x1"), ("ldur", "x2, [x6, #-1]"),
                     ("stur", "x2, [x0, #0xf]"), ("add", "x1, x1, #0x10"),
                     ("cmp", "x1, x3"), ("b.lo", f"#{at:#x}")]
        elif name == "calls":
            rows += [("add", "x1, x1, #8"), ("add", "x20, x20, #8"),
                     ("bl", "#0x90000"), ("ldur", "x2, [x1, #-1]"),
                     ("ldur", "x3, [x20, #-1]"), ("stur", "x2, [x0, #0xf]"),
                     ("stur", "x3, [x0, #0x17]")]
        elif name == "made":
            rows += [("lsl", "x1, x3, #1"), ("ldur", "x2, [x1, #-1]"),
                     ("stur", "x2, [x0, #0xf]")]
        elif name == "thread":
            rows += [("ldr", "x1, [x26, #0x48]"), ("add", "x5, x1, #0x20"),
                     ("str", "x5, [x26, #0x48]"), ("ldur", "x2, [x1, #-1]"),
                     ("stur", "x2, [x0, #0xf]")]
        elif name == "stepped":
            rows += [("ldur", "x1, [x0, #7]"), ("ldr", "x3, [x1], #8"),
                     ("ldur", "x2, [x1, #-1]"), ("stur", "x2, [x0, #0xf]"),
                     ("ldur", "x4, [x0, #7]"), ("str", "x3, [x4, #8]!"),
                     ("ldur", "x2, [x4, #-1]"), ("stur", "x2, [x0, #0x17]")]
    return [(k * 4, mn, op, "") for k, (mn, op) in enumerate(rows + [("ret", "")])]


def test_the_rows_before_a_read_never_say_plain_where_the_address_facts_do_not():
    """`Lifter._row_plain` answers for `_addr_facts` without making it, so it may say
    a row reads a plain value only where the analysis has no computed address there.
    Asked of every row of every body here, ordinary ones and ones made to mislead it,
    against the analysis made in full: no row both. A guard: main has no such
    shortcut (#346)."""
    from jadart import expr
    real = expr.Lifter._lift_block
    plain, computed, both = [0], [0], []

    def checked(self, *args, **kw):
        box = self._elem_box
        if "checked_346" not in box:
            box["checked_346"] = True
            rows = [t[0] for blk in self.blocks.values() for t in blk.insns]
            said = {r for r in rows if self._row_plain(r)}
            held = expr._addr_facts(self.blocks, self._preds,
                                    (self.entry, *self.roots), self.raw)[0]
            plain[0] += len(said)
            computed[0] += len(held)
            both.extend(sorted(said & held))
        return real(self, *args, **kw)

    expr.Lifter._lift_block = checked
    try:
        for i in range(10):
            expr.lift_function(_ordinary_346(i))
        for name in ("far", "reads", "ladder", "moved", "calls", "made", "thread",
                     "stepped"):
            for n in (1, 2, 5, 12):
                expr.lift_function(_shapes_346(name, n))
    finally:
        expr.Lifter._lift_block = real
    assert not both, both
    assert plain[0] > 200 and computed[0] > 20, (plain[0], computed[0])


def test_the_rows_read_before_the_address_facts_are_made_stay_bounded():
    """What `Lifter._row_plain` reads for one row is capped, `_PLAIN_ROWS`, and past
    the cap the analysis is made once and asked from then on, so the shortcut adds at
    most a constant per row however the body is shaped: every read 60 rows from its
    base's load, every read off one base at the top of the body, which read back to
    the top each time would be quadratic, and reads under a run of joins. Counted, not
    timed, at 40 and at 160 of each. A guard: main has no such shortcut (#346)."""
    from jadart import expr
    plain, row, forgets = expr.Lifter._row_plain, expr._af_row, expr._call_forgets
    inside, asks, read = [False], [0], [0]

    def counted_plain(self, a):
        asks[0] += 1
        inside[0] = True
        try:
            return plain(self, a)
        finally:
            inside[0] = False

    def counted_row(*args):
        read[0] += inside[0]
        return row(*args)

    def counted_forgets(*args):
        read[0] += inside[0]
        return forgets(*args)

    def per_instruction(name, n):
        rows = _shapes_346(name, n)
        asks[0] = read[0] = 0
        expr.lift_function(rows)
        assert asks[0] and read[0] <= asks[0] * (expr.Lifter._PLAIN_ROWS + 1), (
            name, n, asks[0], read[0])
        return read[0] / len(rows)

    expr.Lifter._row_plain, expr._af_row = counted_plain, counted_row
    expr._call_forgets = counted_forgets
    try:
        for name in ("far", "reads", "ladder", "moved", "calls"):
            small, large = per_instruction(name, 40), per_instruction(name, 160)
            assert large <= small * 1.25 + 1, (name, small, large)
    finally:
        expr.Lifter._row_plain, expr._af_row = plain, row
        expr._call_forgets = forgets


def _fanin_346(ways, depth):
    """A join with `ways` one-row blocks leading into it, and under it a tree of blocks
    `depth` deep, each reading a field off a register that no row after the frame is
    set up writes."""
    rows = _PRO_346 + [("ldr", "x1, [x29, #0x10]")]
    join = (len(rows) + ways) * 4
    rows += [("cbz", f"x5, #{join:#x}")] * ways

    def under(d):
        at = len(rows) * 4
        if not d:
            rows.extend([("ldur", "x2, [x1, #0xf]"), ("ret", "")])
            return
        rows.extend([("ldur", "x2, [x1, #0xf]"),
                     ("cbz", f"x5, #{at + 8 + (2 ** d - 1) * 8:#x}")])
        under(d - 1)
        under(d - 1)

    under(depth)
    return [(k * 4, mn, op, "") for k, (mn, op) in enumerate(rows)]


def test_a_join_with_many_ways_in_is_not_read_again_for_every_row_under_it():
    """`Lifter._row_plain` follows the ways into a block as it reads its rows, and a
    join has as many as the body has branches to it. With only the rows capped, every
    way in was followed again for every read under the join: 400 ways into one block
    and 1,023 reads under it, 2,450 rows and about as many ways in as lift at Python's
    own recursion limit, took 0.132 s where the body took 0.054 s before the shortcut.
    The ways in are capped as the rows are, and it takes 0.062 s. Counted, not timed:
    what `_row_plain` itself calls, per row of the body, at 75 ways in and at 300. A
    guard: main has no such shortcut (#346)."""
    from jadart import expr
    steps = [0]

    def count(frame, event, arg):
        if event == "c_call" and frame.f_code.co_name == "_row_plain":
            steps[0] += 1

    def per_row(ways, depth):
        rows = _fanin_346(ways, depth)
        steps[0] = 0
        was = sys.getprofile()
        sys.setprofile(count)
        try:
            expr.lift_function(rows)
        finally:
            sys.setprofile(was)
        assert steps[0], (ways, depth)
        return steps[0] / len(rows)

    small, large = per_row(75, 5), per_row(300, 7)
    assert large <= small * 1.5 + 1, (small, large)


def test_a_body_that_keeps_reading_computed_addresses_costs_the_same_per_row():
    """A read at a computed address is kept by its text, for a store to find it live
    (#341), and the pattern of them was compiled again each time one was added. A body
    that makes such a read every few rows compiled a pattern of all it had made so far
    for each one: near the 4,000 rows the CLI takes, the `moved`, `calls` and `thread`
    shapes lifted in 1.76, 1.32 and 2.38 s. They are looked for as text (`_spelled`),
    and take 0.14, 0.13 and 0.08 s. Counted, not timed: the Python calls made to lift
    each shape, per row, at about 1,000 rows and at about 4,000. On main the larger
    takes 36, 22 and 57 times the calls per row of the smaller (#346)."""
    from jadart import expr
    calls = [0]

    def count(frame, event, arg):
        if event == "call":
            calls[0] += 1

    def per_row(name, n):
        rows = _shapes_346(name, n)
        expr.lift_function(rows)                # the memos, filled
        calls[0] = 0
        was = sys.getprofile()
        sys.setprofile(count)
        try:
            expr.lift_function(rows)
        finally:
            sys.setprofile(was)
        return calls[0] / len(rows)

    for name, small, large in (("moved", 160, 660), ("calls", 140, 570),
                               ("thread", 200, 799)):
        few, many = per_row(name, small), per_row(name, large)
        assert many <= few * 1.25 + 1, (name, few, many)


def test_a_value_built_with_its_defaults_is_the_value_it_was():
    """`V` is built about two million times lifting the clean fixture, nearly always
    with nothing but a text and a precedence, and its `__init__` stores only the fields
    that are not at their defaults (#346). A guard that nothing else about it moved:
    what it compares and hashes as, what it prints, every field read, `replace`, a
    copy and a pickle, and that it is still frozen."""
    import copy
    import dataclasses
    import pickle
    from jadart.expr import V, P_ATOM, _SMI_TAG
    bare, full = V("x0"), V("x0", P_ATOM, None, 64, 64, 0, False, None)
    names = [f.name for f in dataclasses.fields(V)]
    assert names == ["text", "prec", "wide", "bits", "sext", "smi", "calc", "at"]
    assert [getattr(bare, n) for n in names] == ["x0", P_ATOM, None, 64, 64, 0, False,
                                                 None]
    assert bare == full and hash(bare) == hash(full) and repr(bare) == repr(full)
    assert repr(bare) == ("V(text='x0', prec=%d, wide=None, bits=64, sext=64, smi=0, "
                          "calc=False, at=None)" % P_ATOM)
    assert dataclasses.replace(bare, text="x1") == V("x1")
    assert dataclasses.asdict(bare) == dict(zip(names, ["x0", P_ATOM, None, 64, 64, 0,
                                                        False, None]))
    assert copy.copy(bare) == bare and pickle.loads(pickle.dumps(bare)) == bare
    other = V("x0", 3, V("x9"), 32, 31, _SMI_TAG, True, (1, 2, 3, 4))
    assert [getattr(other, n) for n in names] == ["x0", 3, V("x9"), 32, 31, _SMI_TAG,
                                                  True, (1, 2, 3, 4)]
    assert dataclasses.replace(other, text="x1").wide == V("x9")
    assert pickle.loads(pickle.dumps(other)) == other
    for field, value in (("prec", 3), ("wide", V("x9")), ("bits", 32), ("sext", 32),
                         ("smi", _SMI_TAG)):
        assert V("x0", **{field: value}) != bare, field
        assert getattr(dataclasses.replace(bare, **{field: value}), field) == value
    # `calc` and `at` say where a value came from and are no part of what it is.
    assert V("x0", calc=True, at=(1, 2, 3, 4)) == bare
    assert hash(V("x0", calc=True, at=(1, 2, 3, 4))) == hash(bare)
    with pytest.raises(dataclasses.FrozenInstanceError):
        bare.text = "x1"
    with pytest.raises(dataclasses.FrozenInstanceError):
        bare.bits = 32


def test_a_store_finds_the_spellings_it_covers_as_its_pattern_did():
    """`_pin_mem` compiled `(?:a|b)(?![0-9a-fA-F])` of the spellings a store covers at
    every store, to ask each live value whether it reads one, and compiling them was
    4% of the time tier 3 takes on the clean fixture. `_spelled` looks for the same
    texts as text, and for the reads a body made at computed addresses and its
    element reads, whose pattern asked for a whole name. A guard that it finds
    exactly what each pattern does: every text of up to four pieces against every one
    and two spellings, the pieces chosen so one spelling sits inside another, ends at
    a hex digit, follows what a name is made of or is empty (#346)."""
    import itertools
    from jadart.expr import _spelled
    pieces = ("x1", ".field_0x8", ".field_0x80", "0", "g", "[", "_", "$", "@",
              "\u00e9", "\u00b2", "")
    texts = sorted({"".join(t) for k in range(5)
                    for t in itertools.product(pieces[:11], repeat=k)})
    spellings = [(a,) for a in pieces] + list(itertools.permutations(
        ("x1.field_0x8", ".field_0x8", "x1", "x1[", "0", ""), 2))
    for whole in (False, True):
        found = 0
        for spelling in spellings:
            pat = re.compile((r"(?<![\w$@])" if whole else "") + "(?:"
                             + "|".join(map(re.escape, spelling))
                             + r")(?![0-9a-fA-F])")
            for text in texts:
                want = pat.search(text) is not None
                assert _spelled(spelling, text, whole) is want, (spelling, text, whole)
                found += want
        assert 0 < found < len(spellings) * len(texts)
    assert _spelled(("t3[x4]",), "t3[x4] + 1", True)
    assert not _spelled(("t3[x4]",), "at3[x4] + 1", True)
    assert _spelled(("x1.field_0x8",), "x1.field_0x8 + x1.field_0x80")
    assert not _spelled(("x1.field_0x8",), "x1.field_0x80 + x1.field_0x8a")


#: Python calls made in jadart's own code to lift `_ordinary_346`'s forty bodies, as
#: recorded when #346 took the lift back to what it cost: 60,408 before it. Moved only
#: by a change that means to make ordinary code cost more, and says so.
_CALLS_346 = 58032


def test_ordinary_code_lifts_in_the_python_calls_it_was_recorded_at():
    """Tier 3 came to lift ordinary code 7% slower over eight fixes, none of which
    showed up in a test: each added a little to every row. This counts the work, not
    the time, so it is the same number on every machine: the Python calls made in
    jadart's own modules to lift forty ordinary bodies, with the memos filled by a
    first pass so the order tests run in does not move it, and without the frames of
    generators and comprehensions, which Python versions count differently (the same
    count on 3.9, 3.11, 3.12, 3.13, 3.14 and 3.15). More than 1% over `_CALLS_346`
    fails. It sees what Python runs, which is where the 7% was, not time inside a
    regular expression or a set, and only the shapes `_ordinary_346` has (#346)."""
    from jadart import expr
    frames = ("<genexpr>", "<listcomp>", "<dictcomp>", "<setcomp>")
    calls = [0]

    def count(frame, event, arg):
        if event == "call" and frame.f_code.co_name not in frames and (
                frame.f_globals.get("__name__", "").startswith("jadart")):
            calls[0] += 1

    bodies = [_ordinary_346(i) for i in range(40)]
    for b in bodies:
        expr.lift_function(b)
    was = sys.getprofile()
    sys.setprofile(count)
    try:
        for b in bodies:
            expr.lift_function(b)
    finally:
        sys.setprofile(was)
    assert calls[0] <= _CALLS_346 * 1.01, (calls[0], _CALLS_346)


_PRO_340 = [("stp", "x29, x30, [x15, #-0x10]!"), ("mov", "x29, x15"),
            ("sub", "x15, x15, #0x40")]
_EPI_340 = [("mov", "x15, x29"), ("ldp", "x29, x30, [x15], #0x10")]
_FFI_IN_340 = [("str", "x29, [x15, #-8]!"), ("mov", "x29, x15")]
_FFI_OUT_340 = [("mov", "x15, x29"), ("ldr", "x29, [x15], #8")]


def _lift_340(rows):
    return _lift_rows(rows + [("ret", "")])


def test_an_address_off_sp_follows_sp_past_a_move():
    # `add x0, x15, #0x238; sub x15, x15, #0x20; ret` printed `return SP + 0x238;` and
    # the machine returns SP as it is at that line plus 0x258. `SP` is SP at the line it
    # is printed on, so a value that is SP plus a constant by its own record takes the
    # move into the constant, at every row that moves SP by an amount it states (#340).
    hold = ("add", "x0, x15, #0x238")
    for move, want in ((("sub", "x15, x15, #0x20"), "SP + 0x258"),
                       (("add", "x15, x15, #0x20"), "SP + 0x218"),
                       (("str", "x2, [x15, #-8]!"), "SP + 0x240"),
                       (("str", "w2, [x15, #-8]!"), "SP + 0x240"),
                       (("str", "x2, [x15], #-8"), "SP + 0x240"),
                       (("ldr", "x2, [x15], #8"), "SP + 0x230"),
                       (("ldr", "x2, [x15, #8]!"), "SP + 0x230"),
                       (("ldrb", "w2, [x15], #1"), "SP + 0x237"),
                       (("stp", "x2, x3, [x15, #-0x10]!"), "SP + 0x248"),
                       (("stp", "w2, w3, [x15, #-0x10]!"), "SP + 0x248"),
                       (("ldp", "x2, x3, [x15], #0x10"), "SP + 0x228"),
                       (("ldp", "w2, w3, [x15], #0x10"), "SP + 0x228"),
                       (("ldpsw", "x2, x3, [x15], #8"), "SP + 0x230")):
        assert _lift_340([hold, move]) == [f"return {want};"], move
    assert _lift_340([hold, ("push", "x1, x2")]) == ["push x1, x2", "return SP + 0x248;"]
    # Moves that cancel leave the text it had, and the constant goes through zero.
    assert _lift_340([hold, ("sub", "x15, x15, #0x20"), ("str", "x2, [x15, #-8]!"),
                      ("ldr", "x3, [x15], #8"),
                      ("add", "x15, x15, #0x20")]) == ["return SP + 0x238;"]
    assert _lift_340([("add", "x0, x15, #0x20"),
                      ("add", "x15, x15, #0x20")]) == ["return SP;"]
    assert _lift_340([("add", "x0, x15, #8"),
                      ("add", "x15, x15, #0x20")]) == ["return SP - 24;"]
    assert _lift_340([("sub", "x0, x15, #0x18"),
                      ("sub", "x15, x15, #0x20")]) == ["return SP + 8;"]
    # SP itself is the sum with no constant, and a sum built on after the move is one.
    assert _lift_340([("mov", "x0, x15"),
                      ("sub", "x15, x15, #0x20")]) == ["return SP + 32;"]
    assert _lift_340([("add", "x1, x15, #0x238"), ("sub", "x15, x15, #0x20"),
                      ("add", "x0, x1, #8")]) == ["return SP + 0x260;"]
    assert _lift_340([("add", "x1, x15, #0x238"), ("mov", "x0, x1"),
                      ("sub", "x15, x15, #0x20"),
                      ("sub", "x0, x0, x1")]) == ["return SP + 0x258 - (SP + 0x258);"]
    # Every reader: a load and a store through it, a compare, a call's argument.
    move = ("sub", "x15, x15, #0x20")
    assert _lift_340([("add", "x1, x15, #0x238"), move,
                      ("ldr", "x0, [x1]")]) == ["return (SP + 0x258).field_0x1;"]
    assert _lift_340([("add", "x17, x15, #0x238"), ("str", "x2, [x15, #-8]!"),
                      ("str", "x1, [x17]")]) == ["(SP + 0x240).field_0x1 = x1;",
                                                 "return x0;"]
    assert _lift_340([("add", "x1, x15, #0x238"), move, ("cmp", "x1, x3"),
                      ("b.lt", "#0x18"), ("mov", "x0, #1"), ("ret", ""),
                      ("mov", "x0, #2")])[0] == "if ((SP + 0x258) >= x3) {"
    # Without a move nothing changes: the guard, which passes before the fix too.
    assert _lift_340([hold]) == ["return SP + 0x238;"]
    assert _lift_340([("add", "x1, x15, #0x238"),
                      ("ldr", "x0, [x1]")]) == ["return (SP + 0x238).field_0x1;"]


def test_a_value_naming_sp_is_named_before_a_move_it_cannot_follow():
    # Where the value is not SP plus a constant, or the row does not say how far SP
    # moves, no rewrite of the text is right after the move. It is given a name while
    # the text still is, on the line before, and read by that name after (#340).
    move = ("sub", "x15, x15, #0x20")

    def named(text):
        return [f"var t0 = {text};", "return t0;"]
    # Not a constant off SP: an index, a 32-bit sum, a conditional, a read through it.
    assert _lift_340([("add", "x1, x15, x2, lsl #3"), move,
                      ("mov", "x0, x1")]) == named("SP + (x2 << 3)")
    assert _lift_340([("add", "w0, w15, #0x238"),
                      move]) == named("(SP + 0x238).toUnsigned(32)")
    assert _lift_340([("add", "x1, x15, #0x238"), ("cmp", "x2, #0"),
                      ("csel", "x0, x1, x3, eq"),
                      move]) == named("x2 == 0 ? SP + 0x238 : x3")
    assert _lift_340([("add", "x1, x15, x2, lsl #3"), move, ("ldr", "x0, [x1]")]) == [
        "var t0 = SP + (x2 << 3);", "return t0.field_0x1;"]
    assert _lift_340([("mov", "x2, x29"), ("sub", "x2, x2, x15"),
                      ("str", "x3, [x15, #-8]!"), ("mov", "x0, x2")]) == named("FP - SP")
    # SP moved by an amount the row does not state.
    hold = ("add", "x0, x15, #0x238")
    for lost in (("and", "x15, x15, #0xfffffffffffffff0"), ("sub", "x15, x15, x3"),
                 ("mov", "x15, x3"), ("mov", "x15, x29")):
        assert _lift_340([hold, lost]) == named("SP + 0x238"), lost
    # The row that moves SP reads the value itself: a push of an address off SP, whose
    # own line is neither before the move nor after it.
    assert _lift_340([("add", "x1, x15, #0x10"), ("str", "x1, [x15, #-8]!"),
                      ("ldr", "x0, [x15], #8")]) == named("SP + 16")
    assert _lift_340([("add", "x1, x15, #0x10"), ("add", "x2, x15, #0x20"),
                      ("stp", "x1, x2, [x15, #-0x10]!"), ("sub", "x0, x2, x1")]) == [
        "var t0 = SP + 16;", "var t1 = SP + 32;", "return t1 - t0;"]
    assert _lift_340([("add", "x1, x15, #0x238"), ("str", "x1, [x15, #-8]!"),
                      ("bl", "#0x1000"), ("add", "x15, x15, #8")]) == [
        "var t0 = SP + 0x238;", "return sub_0x1000(t0);"]
    # A slot holds a name and never the text, so a reload past the move is the name.
    assert _lift_340([("add", "x1, x15, #0x238"), ("stur", "x1, [x29, #-0x10]"), move,
                      ("ldur", "x0, [x29, #-0x10]")]) == named("SP + 0x238")
    # A read through the address is the bytes there when it was read.
    assert _lift_340([("add", "x17, x15, #0x238"), ("ldr", "x5, [x17]"),
                      ("str", "x2, [x15, #-8]!"), ("str", "x1, [x15, #0x240]"),
                      ("mov", "x0, x5")]) == named("(SP + 0x238).field_0x1")
    # The rows strip_boilerplate blanks move SP as much as the ones it leaves.
    assert _lift_340(_PRO_340 + [("add", "x0, x15, #8"), move]
                     + _EPI_340) == named("SP + 40")
    assert _lift_340([("add", "x0, x15, #8")] + _PRO_340 + _EPI_340) == named("SP + 88")
    # A row printed raw that writes x15 leaves the bare register, the lifter knowing
    # nothing of what it holds. A value spelled with that is named before the next move
    # the same way, in a register or in a slot.
    lost = ("mrs", "x15, nzcv")
    for rows in ([("add", "x0, x15, #8"), move],
                 [("add", "x0, x15, #8"), ("str", "x2, [x15, #-8]!")],
                 [("add", "x0, x15, #8"), ("and", "x15, x15, #0xfffffffffffffff0")],
                 [("add", "x1, x15, #8"), ("stur", "x1, [x29, #-8]"), move,
                  ("ldur", "x0, [x29, #-8]")]):
        assert _lift_340([lost] + rows) == ["mrs x15, nzcv"] + named("x15 + 8"), rows
    # ...and x15 stays the bare register after the row, as it was before #340.
    assert _lift_340([lost, ("add", "x0, x15, #8")]) == ["mrs x15, nzcv",
                                                         "return x15 + 8;"]
    # A value nothing reads again is not named: the guard.
    assert _lift_340([("add", "x1, x15, #8"), ("and", "x15, x15, #0xfffffffffffffff0"),
                      ("mov", "x0, x3")]) == ["return x3;"]
    assert _lift_340([("mov", "x2, x29"), ("sub", "x2, x2, x15"),
                      ("mov", "x0, x2")]) == ["return FP - SP;"]


def test_a_value_naming_sp_is_right_past_a_loop_and_a_join():
    # A loop that moves SP is entered again with SP somewhere else, so a text naming SP
    # from before it is named before it; and where one way into a join moved SP and
    # another did not, each way writes the name its own text (#340).
    hold = ("add", "x0, x15, #0x238")
    assert _lift_340([hold, ("sub", "x15, x15, #0x20"), ("sub", "x2, x2, #1"),
                      ("cbnz", "x2, #0x4")]) == [
        "var t0 = SP + 0x238;", "var t1 = x2;", "while (true) {",
        "if ((t1 - 1) == 0) {", "t1 -= 1;", "break;", "}", "t1 -= 1;", "}",
        "return t0;"]
    assert _lift_340([hold, ("cbz", "x2, #0xc"), ("sub", "x15, x15, #0x20")]) == [
        "var t0 = SP + 0x238;", "if (x2 != 0) {", "t0 = SP + 0x258;", "}", "return t0;"]
    assert _lift_340([hold, ("cbz", "x2, #0x10"), ("sub", "x15, x15, #0x20"),
                      ("b", "#0x14"), ("sub", "x15, x15, #0x40"),
                      ("add", "x0, x0, #0")]) == [
        "var t0;", "if (x2 != 0) {", "t0 = SP + 0x258;", "} else {",
        "t0 = SP + 0x278;", "}", "return t0;"]
    # Two ways out of nested arms to one join, which the walk reaches by a goto.
    assert _lift_340([hold, ("cbz", "x2, #0x14"), ("sub", "x15, x15, #0x20"),
                      ("cbz", "x3, #0x14"), ("sub", "x15, x15, #0x20"),
                      ("add", "x0, x0, #8")]) == [
        "var t1 = SP + 0x238;", "if (x2 != 0) {", "var t0 = SP + 0x258;",
        "if (x3 != 0) {", "t0 = SP + 0x278;", "}", "t1 = t0;", "}", "return t1 + 8;"]
    # x15 itself is SP on every line, and is not carried through a join as a variable:
    # this printed `var t0 = x15;` and `t0 = SP & 0xfffffffffffffff0;` in the arm.
    assert _lift_340([("cbz", "x2, #0xc"), ("mov", "x19, x15"),
                      ("and", "x15, x15, #0xfffffffffffffff0"),
                      ("ldr", "x0, [x15, #8]")]) == ["var t0 = SP.field_0x9;",
                                                     "return t0;"]


def test_a_value_naming_fp_is_right_past_a_move_of_fp():
    # `FP` is the frame pointer of the frame in force at the line: where x29 was when
    # that frame began. Inside a frame a move of x29 by an amount the frame analysis
    # follows, an FFI call's own frame, goes into the offset, as it does for an access.
    # A move it does not follow begins another frame, and a value naming FP is named
    # before it (#340).
    def named(text):
        return [f"var t0 = {text};", "return t0;"]
    hold = ("add", "x0, x29, #8")
    for move in (("mov", "x29, x15"), ("sub", "x29, x29, #0x20"),
                 ("ldr", "x29, [x15], #8")):
        assert _lift_340([hold, move]) == named("FP + 8"), move
    assert _lift_340([("mov", "x0, x29"), ("mov", "x29, x15")]) == named("FP")
    assert _lift_340([hold] + _PRO_340 + _EPI_340) == named("FP + 8")
    assert _lift_340([("add", "x1, x29, #8"), ("mov", "x29, x15"), ("add", "x2, x29, #8"),
                      ("sub", "x0, x2, x1")]) == ["var t0 = FP + 8;",
                                                  "return FP + 8 - t0;"]
    # Inside the frame the prologue began, an FFI call's frame is 72 bytes down: the
    # push of x29 under the 0x40 of locals. `add x0, x29, #8` there is FP - 64, and a
    # load through x29 there has printed `(FP - 64).field_0x1` since #165.
    inner = _PRO_340 + _FFI_IN_340
    assert _lift_340(inner + [("add", "x0, x29, #8")] + _FFI_OUT_340) == [
        "return FP - 64;"]
    assert _lift_340(inner + [("mov", "x0, x29")] + _FFI_OUT_340) == ["return FP - 72;"]
    assert _lift_340(inner + [("ldr", "x0, [x29, #8]")] + _FFI_OUT_340) == [
        "var t0 = (FP - 64).field_0x1;", "return t0;"]
    assert _lift_340(_PRO_340 + [("add", "x0, x29, #8")] + _FFI_IN_340
                     + _FFI_OUT_340) == ["return FP + 8;"]
    assert _lift_340(_PRO_340 + [("add", "x1, x29, #8"), ("sub", "x29, x29, #0x20"),
                                 ("add", "x0, x29, #8"), ("sub", "x0, x0, x1"),
                                 ("add", "x29, x29, #0x20")]) == [
        "return FP - 24 - (FP + 8);"]
    # Two frames one after the other: FP in the second is not FP in the first.
    assert _lift_340(_FFI_IN_340 + [("add", "x16, x29, x4, lsl #3")] + _FFI_OUT_340
                     + [("mov", "x29, x15"), ("add", "x11, x29, x4, lsl #3"),
                        ("sub", "x0, x11, x16")]) == [
        "var t0 = FP + (x4 << 3);", "return FP + (x4 << 3) - t0;"]
    # Spelled with the bare register, past a row printed raw that wrote x29.
    for move in (("mov", "x29, x15"), ("sub", "x29, x29, #0x20"),
                 ("ldr", "x29, [x15], #8")):
        assert _lift_340([("mrs", "x29, nzcv"), hold, move]) == [
            "mrs x29, nzcv"] + named("x29 + 8"), move
    # No move: the guard.
    assert _lift_340([hold]) == ["return FP + 8;"]


def test_a_store_through_a_held_frame_address_agrees_with_the_reads_beside_it():
    # The store's text and the read's are of one SP, the one at their own line, so a
    # reader can tell whether they are the same bytes: `(SP + 0x238).field_0x1 = x1;`
    # under a push, beside `var t0 = SP.field_0x241;`, said they were not (#340). And a
    # read taken before the store, which the store may write, is still named before it,
    # through the held address or through the slot, whichever of the two each one is.
    push = ("str", "x2, [x15, #-8]!")
    held = ("add", "x17, x15, #0x238")
    assert _lift_340([held, push, ("str", "x3, [x15, #0x240]"), ("str", "x1, [x17]"),
                      ("ldr", "x0, [x15, #0x240]")]) == [
        "(SP + 0x240).field_0x1 = x1;", "var t0 = SP.field_0x241;", "return t0;"]
    assert _lift_340([("ldr", "x5, [x15, #0x240]"), held, push, ("str", "x1, [x17]"),
                      ("mov", "x0, x5")]) == [
        "var t0 = SP.field_0x241;", "(SP + 0x240).field_0x1 = x1;", "return t0;"]
    assert _lift_340([("add", "x16, x15, #0x238"), held, ("ldr", "x5, [x16]"), push,
                      ("str", "x1, [x17]"), ("mov", "x0, x5")]) == [
        "var t0 = (SP + 0x238).field_0x1;", "(SP + 0x240).field_0x1 = x1;",
        "return t0;"]
    assert _lift_340([held, push, ("str", "x1, [x15, #0x240]"),
                      ("ldr", "x0, [x17]")]) == ["return (SP + 0x240).field_0x1;"]
    # With no move between them both spellings were right already: the guard.
    assert _lift_340([("ldr", "x5, [x15, #0x238]"), held, ("str", "x1, [x17]"),
                      ("mov", "x0, x5")]) == [
        "var t0 = SP.field_0x239;", "(SP + 0x238).field_0x1 = x1;", "return t0;"]
    assert _lift_340([("ldur", "x5, [x29, #-0x10]"), ("sub", "x17, x29, #0x10"), push,
                      ("str", "x1, [x17]"), ("mov", "x0, x5")]) == [
        "var t0 = (FP - 16).field_0x1;", "(FP - 16).field_0x1 = x1;", "return t0;"]


def test_an_address_off_a_frame_register_is_what_the_cpu_returns():
    # Generated rows that build an address off SP or FP, move SP, add to the address or
    # not, and return it, run on a CPU: the text's constant off the register as the
    # return finds it is what x0 holds. 184 of these 300 printed another address (#340).
    _needs_capstone()
    if not _unicorn_available():
        _skip("  SKIP test_an_address_off_a_frame_register_is_what_the_cpu_returns"
              " (no unicorn)")
    import random
    from capstone import Cs, CS_ARCH_ARM64, CS_MODE_LITTLE_ENDIAN
    from unicorn import Uc, UC_ARCH_ARM64, UC_MODE_ARM, arm64_const as a64
    from jadart.expr import lift_function
    md = Cs(CS_ARCH_ARM64, CS_MODE_LITTLE_ENDIAN)

    def imm(op, d, n, k):                       # add or sub xD, xN, #k
        return op | k << 10 | n << 5 | d
    add, sub = 0x91000000, 0xD1000000
    moves = (lambda r: imm(sub, 15, 15, 8 * r.randrange(1, 40)),
             lambda r: imm(add, 15, 15, 8 * r.randrange(1, 40)),
             lambda r: 0xF81F8DE2,              # str x2, [x15, #-8]!
             lambda r: 0xF84085E2,              # ldr x2, [x15], #8
             lambda r: 0xA9BF0DE2,              # stp x2, x3, [x15, #-0x10]!
             lambda r: 0xA8C10DE2)              # ldp x2, x3, [x15], #0x10
    rng, wrong = random.Random(340), []
    for case in range(300):
        base = rng.choice((15, 15, 29))
        words = [imm(add, 0, base, 8 * rng.randrange(0, 100))]
        for _ in range(rng.randrange(1, 6)):
            words.append(rng.choice(moves)(rng))
            if rng.random() < 0.3:
                words.append(imm(rng.choice((add, sub)), 0, 0, 8 * rng.randrange(1, 9)))
        words.append(0xD65F03C0)                # ret
        code = b"".join(struct.pack("<I", w) for w in words)
        rows = [(i.address, i.mnemonic, i.op_str, "") for i in md.disasm(code, 0)]
        assert len(rows) == len(words), case
        mu = Uc(UC_ARCH_ARM64, UC_MODE_ARM)
        mu.mem_map(0x10000, 0x1000)
        mu.mem_map(0x40000, 0x10000)
        mu.mem_write(0x10000, code)
        mu.reg_write(a64.UC_ARM64_REG_X15, 0x48000)
        mu.reg_write(a64.UC_ARM64_REG_X29, 0x4c000)
        mu.emu_start(0x10000, 0x10000 + len(code) - 4)
        cpu = {"SP": mu.reg_read(a64.UC_ARM64_REG_X15),
               "FP": mu.reg_read(a64.UC_ARM64_REG_X29)}
        got = [ln.strip() for ln in lift_function(rows)]
        m = re.fullmatch(r"return (SP|FP)((?: [+-] (?:0x[0-9a-f]+|\d+))*);", got[-1])
        assert m and len(got) == 1, (case, got)
        k = sum(int(sign + num, 0) for sign, num in
                re.findall(r" ([+-]) (0x[0-9a-f]+|\d+)", m.group(2)))
        if cpu[m.group(1)] + k != mu.reg_read(a64.UC_ARM64_REG_X0):
            wrong.append((case, got))
    assert not wrong, (len(wrong), wrong[:3])


def test_naming_at_a_frame_move_costs_the_same_per_row_at_any_length():
    # A guard on the cost, counted and not timed: each row that moves a frame register
    # looks at the registers, a fixed number, so four times the rows is four times the
    # looks, with every register holding a text that names SP and half the moves ones
    # the constant cannot follow. It has nothing to count before #340, where it fails
    # for want of the function and not for the cost.
    import jadart.expr as expr
    real, calls = expr._names_role, [0]

    def counted(v, role):
        calls[0] += 1
        return real(v, role)

    def per_row(n):
        rows = []
        for i in range(n):
            rows.append(("add", f"x{1 + i % 8}, x15, #{8 * (i % 100)}"))
            rows.append(("sub", "x15, x15, #0x10") if i % 2 else
                        ("and", "x15, x15, #0xfffffffffffffff0"))
            rows.append(("eor", f"x0, x0, x{1 + (i + 3) % 8}"))
        calls[0] = 0
        _lift_rows(rows + [("ret", "")])
        return calls[0] / len(rows)
    expr._names_role = counted
    try:
        small, large = per_row(200), per_row(800)
        assert 0 < large <= small * 1.25 + 1, (small, large)
    finally:
        expr._names_role = real


# -- jadart serve: the setup is done once, and the answer is the fresh one (#352) --

def _fresh(argv, tty=False):
    """(exit code, stdout, stderr) of one command line answered by a process of its
    own, which is what `cli.main` is with no server named. `tty` is whether its stdout
    says it is a terminal."""
    import contextlib
    import io
    from jadart import cli

    class Out(io.StringIO):
        def isatty(self):
            return tty

    out, err = Out(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        rc = cli.main(list(argv))
    return rc, out.getvalue(), err.getvalue()


class _Served:
    """What `jadart serve` does with each request, without the socket: one session on
    one binary, and serve._reply for every command line."""

    def __init__(self, path):
        from jadart import cli, keep, serve
        from jadart.source import open_source
        self.src = open_source(path)
        self.sha = serve.digest(self.src.data)
        self.parser = cli.build_parser()
        self.session = keep.open_session(self.src.data)

    def reply(self, line, **over):
        import json
        from jadart import cli, serve
        req = {"build": serve.build_id(), "sha256": self.sha, "argv": line,
               "origin": self.src.origin, "path": self.src.path,
               "member": self.src.member, "color": [False, False],
               "tty": [False, False], "room": serve.headroom()}
        req.update(over)
        return serve._reply(self.src, self.sha, json.dumps(req).encode("ascii"),
                            lambda a, s, c, r: cli._answer(self.parser, a, s, c, r))

    def ask(self, argv, **over):
        r = self.reply(argv, **over)
        assert r["ok"] is True, (argv, r)
        return (r["exit"], "".join(t for fd, t in r["out"] if fd == 1),
                "".join(t for fd, t in r["out"] if fd == 2))

    def close(self):
        from jadart import keep
        keep.close_session()


def _serve_lines(lib, fn, klass, needle):
    """One line or more for every command a server answers, hits and misses."""
    return [
        ["info", lib], ["-j", "info", lib], ["libraries", lib, "-a"],
        ["classes", lib, "-l", "package:"], ["classes", lib, "-f", klass],
        ["-j", "classes", lib, "-f", klass], ["functions", lib, "-f", fn],
        ["-j", "functions", lib, "-n", "3", "-s", "size"],
        ["functions", lib, "--named", "-s", "callers", "-n", "5"],
        ["-j", "functions", lib, "-f", fn], ["xrefs", lib, "function", fn],
        ["symbols", lib, "--format", "r2", "-n", "5"], ["hook", lib, fn],
        ["lift", lib, fn], ["-j", "lift", lib, fn], ["lift", lib, "no_such_function"],
        ["disasm", lib, fn], ["-j", "disasm", lib, fn],
        ["decompile", lib, klass], ["decompile", lib, klass, "-t", "2"],
        ["decompile", lib, klass, "-t", "1"], ["-j", "decompile", lib, "NoSuchClass"],
        ["selectors", lib], ["constants", lib], ["strings", lib, "-g", needle],
        ["xrefs", lib, "string", needle], ["-j", "xrefs", lib, "function", fn],
        ["xrefs", lib, "string", "no such string at all"], ["xrefs", lib, needle],
        ["ffi", lib], ["verify", lib], ["--color", "always", "lift", lib, fn],
    ]


def _check_served_is_fresh(lines, monkeypatch):
    served = _Served(lines[0][1])
    try:
        # `-j` is indented for a terminal and compact for anything else (#378), and the
        # server writes to neither: it is told which the client's stdout is.
        monkeypatch.setenv("NO_COLOR", "1")
        documents = [argv for argv in lines if argv[0] == "-j"]
        assert len(documents) > 5
        for argv in documents:
            wide = _fresh(argv, tty=True)
            assert served.ask(argv, tty=[True, False]) == wide, argv
            assert wide[1].startswith("{\n  ") and wide != _fresh(argv), argv
        monkeypatch.delenv("NO_COLOR")
        fresh = [_fresh(argv) for argv in lines]
        # Twice, the second time backwards: a kept table one command changed would show
        # in a later command's answer, and a later command is a different one each way.
        for order in (range(len(lines)), reversed(range(len(lines)))):
            for i in order:
                colour = lines[i][0] == "--color"
                assert served.ask(lines[i], color=[colour, colour]) == fresh[i], lines[i]
        assert {rc for rc, _o, _e in fresh} == {0, 1}      # hits and misses, both ways
    finally:
        served.close()


def test_a_served_answer_is_the_fresh_one_on_clean(monkeypatch):
    """Every command `jadart serve` answers, on the clean fixture: exit code, stdout and
    stderr are what a process of its own gives, byte for byte (#352)."""
    _needs_capstone()
    monkeypatch.delenv("JADART_SERVER", raising=False)
    _check_served_is_fresh(
        _serve_lines(CLEAN, "benchWithdraw", "BenchAccount", "bench"), monkeypatch)


def test_a_served_answer_is_the_fresh_one_on_obf(monkeypatch):
    """The same on the obfuscated fixture, where a function is asked for by address."""
    _needs_capstone()
    monkeypatch.delenv("JADART_SERVER", raising=False)
    _check_served_is_fresh(_serve_lines(OBF, "0xf4190", "AE", "flutter"), monkeypatch)


def test_a_session_does_the_setup_once(monkeypatch):
    """`lift` of a 200 byte function on a 26 MB app was 1.35 s, 0.004 s of it the lift:
    the snapshot walk, the selector, cast and pool tables and the call graph were built
    again by every command, and every `xrefs` scanned the code again (#352). In a
    session they are built by the first command that needs them. Counted as calls, not
    timed."""
    _needs_capstone()
    import importlib
    from jadart import callgraph, disasm, dispatch, fields, fillwalk
    program = importlib.import_module("jadart.program")    # jadart.program is a function
    monkeypatch.delenv("JADART_SERVER", raising=False)
    calls = {}

    def counted(module, name):
        real = getattr(module, name)

        def wrapper(*a, **k):
            calls[name] = calls.get(name, 0) + 1
            return real(*a, **k)
        monkeypatch.setattr(module, name, wrapper)

    counted(fillwalk, "walk_fill")                 # the snapshot walk
    counted(program, "walk_fill")                  # and where `classes` reaches it
    counted(dispatch, "build_selector_map")        # selector recovery
    counted(fields, "recover_casts")               # cast recovery
    counted(disasm, "_pool_label")                 # the pool map, per entry
    counted(callgraph, "_read_words")              # the call graph, per code range
    counted(disasm, "_pool_loads")                 # the scan for what loads a pool entry
    lines = [["lift", CLEAN, "benchWithdraw"], ["lift", CLEAN, "build"],
             ["disasm", CLEAN, "benchWithdraw"], ["decompile", CLEAN, "BenchAccount"],
             ["xrefs", CLEAN, "function", "benchWithdraw"],
             ["xrefs", CLEAN, "string", "bench"], ["xrefs", CLEAN, "string", "flutter"],
             ["functions", CLEAN, "-f", "bench"], ["classes", CLEAN, "-f", "Bench"],
             ["libraries", CLEAN, "-a"], ["strings", CLEAN, "-g", "bench"]]
    served = _Served(CLEAN)
    try:
        for argv in lines:
            served.ask(argv)
        first = dict(calls)
        kept = len(served.session.memo)
        for argv in lines + lines:
            served.ask(argv)
        assert calls == first, (first, calls)       # nothing was built a second time
        assert len(served.session.memo) == kept     # and nothing more is held for it
    finally:
        served.close()
    # Three walks: the one the code is read from, the one `classes` and `libraries`
    # read, and the one `strings` reads. Two cast tables: with accessor names, without.
    assert first["walk_fill"] == 3 and first["recover_casts"] == 2, first
    assert first["_pool_loads"] == 1, first
    assert first["_read_words"] > 8000 and first["_pool_label"] > 1000, first
    # No session, no keeping: a process of its own builds what it always built.
    calls.clear()
    for argv in lines[:2]:
        assert _fresh(argv)[0] == 0
    assert calls["walk_fill"] == 2, calls


def test_a_session_keeps_the_whole_call_graph_and_never_a_part(monkeypatch):
    """`functions -f NAME` and `xrefs function NAME` build the graph for that name alone
    (#353), and a session keeps what it builds. A part kept and then read by `functions`
    would print counts nobody computed, so a session builds the whole graph for either
    question and keeps only that. The whole one is not the part where a range will not
    decode: the whole graph names it in a note and drops its calls, and a part that had
    no reason to decode it does neither, so there the part is built for each question,
    as it is by a process of its own. Counted in ranges decoded, not timed."""
    _needs_capstone()
    from jadart import callgraph
    from jadart.disasm import load_instructions
    monkeypatch.delenv("JADART_SERVER", raising=False)
    real = callgraph.disassemble_range
    tried, broken = [], set()

    def decode(image, cr, *limit):
        tried.append(cr.pc_offset)
        if cr.pc_offset in broken:
            raise ValueError("will not decode")
        return real(image, cr, *limit)

    monkeypatch.setattr(callgraph, "disassemble_range", decode)
    image, fr, _hdr = load_instructions(CLEAN)
    target = next(pc for pc, nm in sorted(callgraph.range_names(image, fr).items())
                  if nm[0] == "benchWithdraw")
    callgraph.build_index(image, fr)
    whole = set(tried)
    del tried[:]
    callgraph.build_index(image, fr, only={target})
    part = set(tried)
    assert part < whole and len(whole) > 1000, (len(part), len(whole))

    narrow = [["functions", CLEAN, "-f", "benchWithdraw"],
              ["-j", "functions", CLEAN, "-f", "benchWithdraw"],
              ["xrefs", CLEAN, "function", "benchWithdraw"]]
    wide = [["functions", CLEAN, "-n", "0"], ["-j", "functions", CLEAN, "-s", "callers"]]
    fresh = {tuple(argv): _fresh(argv) for argv in narrow + wide}
    for first, then in ((narrow, wide), (wide, narrow)):
        del tried[:]
        served = _Served(CLEAN)
        try:
            for i, argv in enumerate(first + then + first):
                assert served.ask(argv) == fresh[tuple(argv)], argv
                # the first question, wide or narrow, builds the whole graph and the
                # rest are read off it
                assert set(tried) == whole and len(tried) == len(whole), (i, argv)
        finally:
            served.close()

    # One range the whole graph decodes and the part for this name does not.
    broken.add(min(whole - part))
    fresh = {tuple(argv): _fresh(argv) for argv in narrow + wide}
    assert "would not decode" in fresh[tuple(wide[0])][1]
    assert "would not decode" not in fresh[tuple(narrow[0])][1]
    for first, then in ((narrow, wide), (wide, narrow)):
        served = _Served(CLEAN)
        try:
            for argv in first + then + first:
                assert served.ask(argv) == fresh[tuple(argv)], argv
        finally:
            served.close()


def test_a_session_keeps_only_what_is_about_its_binary():
    """What a session hands back twice is a result about the bytes it was opened on.
    The same bytes under another name are those bytes; another binary, or a path the
    session has not read, is answered as if there were no session, and is not held."""
    from jadart import keep
    from jadart.disasm import build_pool_map, load_instructions
    from jadart.source import Source, open_source
    src, other = open_source(CLEAN), open_source(OBF)
    assert load_instructions(src) is not load_instructions(src)     # no session
    session = keep.open_session(src.data)
    try:
        image, fr, hdr = loaded = load_instructions(src)
        assert load_instructions(src) is loaded
        renamed = Source(data=src.data, origin="elsewhere/libapp.so", path="x.so")
        assert load_instructions(renamed) is loaded
        pool = build_pool_map(fr, image.arch)
        assert build_pool_map(fr, image.arch) is pool
        held = len(session.memo)
        # a path: the file behind it can change between two calls
        assert load_instructions(CLEAN) is not loaded
        assert load_instructions(CLEAN) is not load_instructions(CLEAN)
        # another binary, and what is built from it
        theirs = load_instructions(other)
        assert theirs is not loaded and load_instructions(other) is not theirs
        assert theirs[2].version_hash == hdr.version_hash          # same release, even
        assert build_pool_map(theirs[1], theirs[0].arch) is not \
            build_pool_map(theirs[1], theirs[0].arch)
        # equal bytes in another object are not the session's bytes
        copy = Source(data=bytes(bytearray(src.data)), origin=CLEAN, path=CLEAN)
        assert load_instructions(copy) is not loaded
        assert len(session.memo) == held
    finally:
        keep.close_session()
    assert load_instructions(src) is not loaded                     # closed: no session


def test_a_server_answers_only_for_its_own_bytes_and_build(monkeypatch):
    """A request is answered when it is about the bytes the server holds, from the same
    build of jadart, and is a command a server takes. Anything else gets a reason and no
    output, and the client then answers for itself."""
    monkeypatch.delenv("JADART_SERVER", raising=False)
    from jadart import serve
    from jadart.source import open_source
    line = ["classes", CLEAN, "-f", "Bench"]
    fresh = _fresh(line)
    served = _Served(CLEAN)
    try:
        assert served.ask(line) == fresh
        refused = [
            ({"sha256": serve.digest(open_source(OBF).data)}, "different binary"),
            ({"sha256": served.sha[:-1]}, "different binary"),
            ({"sha256": None}, "different binary"),
            ({"build": "0" * 64}, "different build"),
            ({"argv": ["export", CLEAN, "-o", "out"]}, "does not answer"),
            ({"argv": ["serve", CLEAN, "--socket", "s"]}, "does not answer"),
            ({"argv": ["lift", CLEAN, "f", "--sigs", "lib.json"]}, "does not answer"),
            ({"argv": ["--version"]}, "does not answer"),
            ({"argv": ["classes"]}, "does not answer"),
            ({"argv": ["no-such-command", CLEAN]}, "does not answer"),
            ({"argv": "classes"}, "could not read"),
            ({"argv": ["classes", 7]}, "could not read"),
            ({"origin": None}, "could not read"),
            ({"path": 3}, "could not read"),
            ({"color": [1, 0]}, "could not read"),
            ({"color": [True]}, "could not read"),
            ({"tty": [1, 0]}, "could not read"), ({"tty": None}, "could not read"),
            ({"room": None}, "could not read"), ({"room": 0}, "could not read"),
            ({"room": True}, "could not read"), ({"room": 1 << 21}, "could not read"),
        ]
        for over, why in refused:
            r = served.reply(line, **over)
            assert r["ok"] is False and why in r["why"], (over, r)
            assert set(r) == {"ok", "why"}, (over, r)
        # 200 KB of brackets is nested deeper than the parser follows: that was a
        # RecursionError out of the server, which stopped it
        for raw in (b"", b"[]", b"{", b"\xff\xfe", b'"classes"', b"null",
                    b"[" * 200_000, b'{"a":' * 100_000):
            r = serve._reply(served.src, served.sha, raw, lambda *a: 1 / 0)
            assert r == {"ok": False, "why": "the server could not read the request"}
        assert served.ask(line) == fresh               # and it still answers
        # the client's name for the file is the one the output carries
        assert served.ask(["verify", CLEAN], origin="app/renamed.so",
                          path="app/renamed.so")[1].startswith("renamed.so ")
    finally:
        served.close()
    # The same source under an interpreter with no disassembler is another build: it
    # answers `verify` with fewer gates, and `lift` not at all.
    import importlib.machinery
    import types
    ids = []
    for origin in ("/somewhere/capstone/__init__.py", None):
        fake = None
        if origin:
            fake = types.ModuleType("capstone")
            fake.__spec__ = importlib.machinery.ModuleSpec("capstone", None,
                                                           origin=origin)
        monkeypatch.setitem(sys.modules, "capstone", fake)
        monkeypatch.setattr(serve, "_BUILD", None)
        ids.append(serve.build_id())
    assert len(set(ids)) == 2 and all(len(i) == 64 for i in ids), ids
    # ... and so is the same source with another capstone installed at the same path:
    # the digest held where capstone was, which an upgrade in place does not move
    import shutil
    import tempfile
    site = tempfile.mkdtemp()
    try:
        os.makedirs(os.path.join(site, "capstone"))
        origin = os.path.join(site, "capstone", "__init__.py")

        def installed(version, record, source="CS_VERSION = 5\n"):
            for name in os.listdir(site):
                if name.endswith(".dist-info"):
                    shutil.rmtree(os.path.join(site, name))
            os.makedirs(os.path.join(site, f"capstone-{version}.dist-info"))
            with open(os.path.join(site, f"capstone-{version}.dist-info", "RECORD"),
                      "w") as fh:
                fh.write(record)
            with open(origin, "w") as fh:
                fh.write(source)
            fake = types.ModuleType("capstone")
            fake.__spec__ = importlib.machinery.ModuleSpec("capstone", None,
                                                           origin=origin)
            monkeypatch.setitem(sys.modules, "capstone", fake)
            monkeypatch.setattr(serve, "_BUILD", None)
            return serve.build_id()

        ids = [installed("5.0.1", "a"), installed("5.0.9", "a"),
               installed("5.0.9", "b"), installed("5.0.9", "b", "CS_VERSION = 6\n")]
        assert len(set(ids)) == 4 and installed("5.0.1", "a") == ids[0], ids
    finally:
        shutil.rmtree(site)
    monkeypatch.setattr(serve, "_BUILD", None)


def _socket_dir():
    """A short directory for a unix socket (its path is limited to about 100 bytes, and
    pytest's tmp_path is longer than that on macOS), or a skip where there are none."""
    import socket
    import tempfile
    if not hasattr(socket, "AF_UNIX"):
        _skip(f"  SKIP {sys._getframe(1).f_code.co_name} (no unix sockets)")
    return tempfile.mkdtemp(prefix="jd", dir="/tmp" if os.path.isdir("/tmp") else None)


def test_a_client_answers_for_itself_when_the_server_is_no_use(monkeypatch):
    """Nothing listening, a file that is no socket, a link to a socket, a directory
    others can write, another user's socket, a reply cut short, too long, nested past
    parsing or of the wrong shape, a refusal, no reply in the time allowed: each is one
    line on stderr and then the answer a process of its own gives. No part of a bad
    reply is printed."""
    import json
    import shutil
    import socket
    import threading
    from jadart import serve
    monkeypatch.delenv("JADART_SERVER", raising=False)
    line = ["classes", CLEAN, "-f", "Bench"]
    fresh = _fresh(line)
    assert fresh[0] == 0 and "BenchAccount" in fresh[1]
    d = _socket_dir()

    def fallen_back(path, why, wait=None):
        extra = ["--server-wait", wait] if wait else []
        rc, out, err = _fresh(["--server", path] + extra + line)
        assert (rc, out) == fresh[:2], why
        note = f"jadart: server at {path} not used, "
        assert err.startswith(note) and why in err.splitlines()[0], err
        assert err.split("\n", 1)[1] == fresh[2], err
        # the environment names a server, and how long to wait, as the options do
        monkeypatch.setenv("JADART_SERVER", path)
        if wait:
            monkeypatch.setenv("JADART_SERVER_WAIT", wait)
        assert _fresh(line) == (rc, out, err)
        monkeypatch.delenv("JADART_SERVER")
        monkeypatch.delenv("JADART_SERVER_WAIT", raising=False)

    try:
        fallen_back(os.path.join(d, "none"), "nothing is there")
        plain = os.path.join(d, "file")
        with open(plain, "w") as fh:
            fh.write("not a socket")
        fallen_back(plain, "not a socket")

        stale = os.path.join(d, "stale")
        with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as s:
            s.bind(stale)
        fallen_back(stale, "nothing is listening")

        good = json.dumps({"ok": True, "exit": 0, "out": [[1, "FORGED\n"]]}).encode()
        monkeypatch.setattr(serve, "MAX_REPLY", 300_000)
        replies = [
            (b"", "cut short"), (good[:-3], "cut short"), (b"\xff", "cut short"),
            # brackets nested past parsing were a traceback and exit 1, not a fallback
            (b"[" * 200_000, "cut short"), (b" " * 300_000 + good, "too long"),
            (b'{"ok": false, "why": "' + b"x" * 500 + b'"}', "not one"),
            (b'{"ok": false, "why": "a\\u001b[2Jb"}', "not one"),
            (b"[1, 2]", "not one"), (b'{"ok": 1, "exit": 0, "out": []}', "not one"),
            (b'{"ok": true, "exit": "0", "out": []}', "not one"),
            (b'{"ok": true, "exit": true, "out": []}', "not one"),
            (b'{"ok": true, "exit": 0, "out": [[3, "x"]]}', "not one"),
            (b'{"ok": true, "exit": 0, "out": [[1, 5]]}', "not one"),
            (b'{"ok": true, "exit": 0, "out": "FORGED"}', "not one"),
            (b'{"ok": false, "why": "it holds a different binary"}', "different binary"),
            (b'{"ok": false, "why": 9}', "not one"),
        ]
        path = os.path.join(d, "fake")
        listener = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        listener.bind(path)
        listener.listen(8)
        seen, reply, hold = [], [None], threading.Event()

        def fake():
            while True:
                conn, _ = listener.accept()
                with conn:
                    raw = b""
                    while chunk := conn.recv(65536):
                        raw += chunk
                    if raw == b"stop":
                        return
                    seen.append(json.loads(raw))
                    try:
                        if reply[0] is None:
                            hold.wait(60)           # a server that does not answer
                        else:
                            conn.sendall(reply[0])
                    except OSError:
                        pass                        # the client stopped waiting

        t = threading.Thread(target=fake, daemon=True)
        t.start()
        try:
            for reply[0], why in replies:
                fallen_back(path, why)
            # a link to the socket is not the socket: the client does not follow it
            link = os.path.join(d, "link")
            os.symlink(path, link)
            fallen_back(link, "not a socket")
            # a well formed reply from the user's own socket is printed: that much is
            # the trust the option asks for, and the rest of this test is its edge
            reply[0] = good
            seen.clear()
            assert _fresh(["--server", path] + line) == (0, "FORGED\n", "")
            req = seen[0]
            # ... but not from a directory someone else could have put it in
            os.chmod(d, 0o777)
            fallen_back(path, "other users can write to its directory")
            os.chmod(d, 0o700)
            # ... and not from a socket some other user owns
            mine = os.getuid()
            monkeypatch.setattr(serve.os, "getuid", lambda: mine + 1)
            fallen_back(path, "another user")
            monkeypatch.setattr(serve.os, "getuid", lambda: mine)
            # a server that takes the request and says nothing is waited for as long
            # as the client was told to, and no longer
            reply[0] = None
            fallen_back(path, "no answer in 0.2 s", "0.2")
            monkeypatch.setenv("JADART_SERVER_WAIT", "soon")
            rc, out, err = _fresh(["--server", path] + line)
            monkeypatch.delenv("JADART_SERVER_WAIT")
            assert (rc, out) == fresh[:2] and "JADART_SERVER_WAIT is 'soon'" in err
        finally:
            hold.set()
            with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as s:
                s.connect(path)
                s.sendall(b"stop")
            t.join(10)
            listener.close()
        # what the client sends: its own build, the digest of the bytes it read, the
        # command line as typed after the option, the name it was given, its colours,
        # whether its streams are terminals, how deep it could still have gone
        assert req["build"] == serve.build_id() and len(req["build"]) == 64
        assert req["sha256"] == serve.digest(open(CLEAN, "rb").read())
        assert req["argv"] == ["--server", path] + line and req["origin"] == CLEAN
        assert type(req["room"]) is int and req["room"] > 100
        assert req["color"] == req["tty"] == [False, False] and set(req) == {
            "build", "sha256", "argv", "origin", "path", "member", "color", "tty", "room"}
        # a command a server does not take is not sent, and nothing is said about it
        seen.clear()
        rc, _out, err = _fresh(["--server", os.path.join(d, "none"), "lift", CLEAN,
                                "benchWithdraw", "--sigs", os.path.join(d, "none")])
        assert "server at" not in err and not seen
    finally:
        shutil.rmtree(d)


class _Servers:
    """The `jadart serve` processes a test starts. `close` stops every one that is
    still running, so a test that fails leaves none behind."""

    def __init__(self, env, cwd=None):
        self.env, self.cwd, self.started = env, cwd, []

    def start(self, lib, path, *extra):
        import socket
        import subprocess
        import time
        p = subprocess.Popen([sys.executable, "-m", "jadart", "serve", lib, "--socket",
                              path, *extra], env=self.env, cwd=self.cwd,
                             stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        self.started.append(p)
        for _ in range(800):                   # until it answers, or has given up
            if p.poll() is not None:
                break
            try:
                with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as probe:
                    probe.connect(path)
                break
            except OSError:
                time.sleep(0.025)
        return p

    def stop(self, p, sig=None):
        import signal
        p.send_signal(sig or signal.SIGTERM)
        out, err = p.communicate(timeout=30)
        return p.returncode, out, err

    def close(self):
        for p in self.started:
            if p.poll() is None:
                p.kill()
            p.communicate()


def test_serve_over_its_socket(monkeypatch):
    """The real thing: a `jadart serve` process, and commands sent to it. The socket is
    the only thing it writes, mode 0600, and it is gone when the server stops. A second
    server does not take a live socket, and takes a dead one. A file at the path that
    is not a socket, a symbolic link, a directory others can write and an idle time
    that is no time are refused, with nothing made and nothing left."""
    import shutil
    import signal
    import stat
    # The server is a process of its own with its own capstone, and one that has it is
    # another build to a suite run without (conftest.py), so it would not be asked.
    _needs_capstone()
    monkeypatch.delenv("JADART_SERVER", raising=False)
    d = _socket_dir()
    env = dict(os.environ, PYTHONPATH=os.path.join(os.path.dirname(__file__), ".."))
    env.pop("JADART_SERVER", None)
    servers = _Servers(env)
    start, stop = servers.start, servers.stop

    sock = os.path.join(d, "s")
    try:
        server = start(CLEAN, sock)
        assert os.listdir(d) == ["s"]
        mode = os.lstat(sock).st_mode
        assert stat.S_ISSOCK(mode) and stat.S_IMODE(mode) == 0o600
        for line in (["classes", CLEAN, "-f", "Bench"], ["-j", "info", CLEAN],
                     ["verify", CLEAN], ["strings", CLEAN, "-g", "bench"],
                     ["classes", CLEAN, "-f", "NoSuchClassAtAll"]):
            assert _fresh(["--server", sock] + line) == _fresh(line), line
        # the old flag form is rewritten before it is sent, as it is before it is run
        assert _fresh(["--server", sock, "classes", CLEAN, "-f", "Bench"])[1] == \
            _fresh([CLEAN, "--tier0", "--filter", "Bench"])[1]
        # the same bytes under another name: answered, and under the name asked with
        other = os.path.join(d, "renamed.so")
        shutil.copyfile(CLEAN, other)
        assert _fresh(["--server", sock, "verify", other]) == _fresh(["verify", other])
        assert _fresh(["verify", other])[1].startswith("renamed.so ")
        # another binary: not the server's to answer, whatever it is called
        shutil.copyfile(OBF, other)
        rc, out, err = _fresh(["--server", sock, "verify", other])
        assert (rc, out) == _fresh(["verify", other])[:2]
        assert "holds a different binary" in err.splitlines()[0]
        os.unlink(other)
        # a second server does not take the path while the first has it
        second = start(CLEAN, sock)
        assert second.wait(30) == 2
        assert "already listening" in second.stderr.read()
        plain = _fresh(["-j", "info", CLEAN])
        assert _fresh(["--server", sock, "-j", "info", CLEAN]) == plain
        rc, out, err = stop(server)
        assert rc == 0 and out == "" and err.startswith("jadart: serving ")
        assert os.listdir(d) == []
        # killed outright, a server leaves its socket; the next one takes it over
        server = start(CLEAN, sock, "--idle", "0")
        stop(server, signal.SIGKILL)
        assert os.listdir(d) == ["s"]
        server = start(CLEAN, sock)
        plain = _fresh(["-j", "info", CLEAN])
        assert _fresh(["--server", sock, "-j", "info", CLEAN]) == plain
        assert stop(server, signal.SIGINT)[0] == 0 and os.listdir(d) == []
        # a file that is not a socket is not jadart's to replace
        with open(sock, "w") as fh:
            fh.write("mine")
        refused = start(CLEAN, sock)
        assert refused.wait(30) == 2 and "not a socket" in refused.stderr.read()
        assert open(sock).read() == "mine"
        os.unlink(sock)
        # a link is not followed: binding through one made the socket at its target
        os.symlink(os.path.join(d, "elsewhere"), sock)
        refused = start(CLEAN, sock)
        assert refused.wait(30) == 2 and "symbolic link" in refused.stderr.read()
        assert os.listdir(d) == ["s"] and os.path.islink(sock)
        os.unlink(sock)
        # a directory another user can write is where they could have left one
        os.chmod(d, 0o777)
        refused = start(CLEAN, sock)
        assert refused.wait(30) == 2
        assert "other users can write to its directory" in refused.stderr.read()
        os.chmod(d, 0o700)
        # an idle time that is not one is a usage error: `inf` was an OverflowError
        # after the socket was made, and the socket stayed
        for idle in ("inf", "nan", "-1", "soon"):
            refused = start(CLEAN, sock, "--idle", idle)
            assert refused.wait(30) == 2, idle
            assert "argument --idle" in refused.stderr.read(), idle
        assert os.listdir(d) == []
    finally:
        servers.close()
        shutil.rmtree(d)


def test_a_served_command_has_the_depth_a_fresh_one_has(monkeypatch):
    """Tier 3 lifts a body by recursion and prints it flat when the interpreter's limit
    stops it, so how deep a command may go is part of its answer: 494 nested
    conditionals come out structured and 495 flat. A served command starts under the
    server's own frames, ten deep where a fresh one is four, and those six were enough
    to move that line. It is given the limit that leaves it what its client had.
    Counted in calls, on a command that goes down until it is stopped, with the server
    standing 0, 1, 7 and 40 frames deeper than it does."""
    import json
    from jadart import cli, serve
    monkeypatch.delenv("JADART_SERVER", raising=False)

    def probe(args):
        def down(n):
            try:
                return down(n + 1)
            except RecursionError:
                return n
        print(down(0))
        return 0

    monkeypatch.setattr(cli, "cmd_info", probe)
    served = _Served(CLEAN)
    extra = [0]

    def exchange(path, request, wait):
        def answer(a, s, c, r):
            return cli._answer(served.parser, a, s, c, r)

        def deeper(n):
            if n:
                return deeper(n - 1)
            return serve._reply(served.src, served.sha, request, answer)
        return json.dumps(deeper(extra[0])).encode("ascii"), None

    monkeypatch.setattr(serve, "_exchange", exchange)
    limit = sys.getrecursionlimit()
    try:
        fresh = _fresh(["info", CLEAN])
        assert fresh[0] == 0 and int(fresh[1]) > 100, fresh
        for extra[0] in (0, 1, 7, 40):
            assert _fresh(["--server", "any", "info", CLEAN]) == fresh, extra
            assert sys.getrecursionlimit() == limit
        # what the client measured is what the command gets, to the call
        assert served.ask(["info", CLEAN], room=5) == (0, "5\n", "")
        assert served.ask(["info", CLEAN], room=2000) == (0, "2000\n", "")
        assert sys.getrecursionlimit() == limit
    finally:
        served.close()


def test_a_server_is_the_build_it_started_as(monkeypatch):
    """The digest a server answers to is taken when it starts, with every module
    loaded. It was taken at the first request: a server started from one copy of
    jadart, whose cli.py was then edited, matched the first client of the edited copy
    and answered it with the code it had loaded before the edit, exit 1 where the
    client's own answer was exit 7, and no warning."""
    import shutil
    import subprocess
    here = os.path.dirname(os.path.abspath(__file__))
    d = _socket_dir()
    copy = os.path.join(d, "fw")
    shutil.copytree(os.path.join(here, "..", "jadart"), os.path.join(copy, "jadart"),
                    ignore=shutil.ignore_patterns("__pycache__"))
    env = dict(os.environ, PYTHONPATH=copy)
    env.pop("JADART_SERVER", None)
    servers = _Servers(env, cwd=d)     # not here: `-m` looks beside where it is run
    sock = os.path.join(d, "s")
    lib = os.path.abspath(CLEAN)

    def client():
        out = subprocess.run([sys.executable, "-m", "jadart", "--server", sock,
                              "classes", lib, "-f", "Bench"], env=env, cwd=d,
                             capture_output=True, text=True, timeout=120)
        return out.returncode, out.stdout, out.stderr

    cli_py = os.path.join(copy, "jadart", "cli.py")
    lazy_py = os.path.join(copy, "jadart", "interop.py")   # not loaded by `classes`
    try:
        servers.start(lib, sock)
        for edited in (cli_py, lazy_py):
            was = open(edited).read()
            with open(edited, "a") as fh:
                fh.write("\n# edited after the server started\n")
            rc, out, err = client()                 # the first request it gets
            assert rc == 0 and "BenchAccount" in out
            assert "it is a different build of jadart" in err.splitlines()[0], err
            with open(edited, "w") as fh:
                fh.write(was)
            assert client() == (rc, out, "")        # the copy it started as: answered
    finally:
        servers.close()
        shutil.rmtree(d)


def test_a_request_is_whole_and_soon_or_it_is_not_one(monkeypatch):
    """What a connection can do to a server is cost itself the answer. A request nested
    past parsing was a RecursionError that stopped the server, one past the size limit
    gets a refusal, and a client that sends a byte now and then, which held the server
    for as long as it kept sending, is dropped when the time for a request is up.
    Counted in bytes the server waited for, not timed."""
    import json
    import socket
    import threading
    import time
    from jadart import serve
    from jadart.source import open_source
    if not hasattr(socket, "socketpair"):
        _skip("  SKIP test_a_request_is_whole_and_soon_or_it_is_not_one (no socketpair)")
    src = open_source(CLEAN)
    sha = serve.digest(src.data)
    ran = []

    def one(send):
        """What the server sends back to a client that does `send(sock)`."""
        ours, theirs = socket.socketpair()

        def server():
            with theirs:
                serve._serve_one(theirs, src, sha, lambda *a: ran.append(a) or 0)

        t = threading.Thread(target=server, daemon=True)
        t.start()
        try:
            send(ours, t)
            try:
                ours.shutdown(socket.SHUT_WR)
            except OSError:
                pass                             # the server has already hung up
            raw = b""
            while chunk := ours.recv(65536):
                raw += chunk
        finally:
            ours.close()
            t.join(30)
        assert not t.is_alive()
        return raw

    unread = {"ok": False, "why": "the server could not read the request"}
    for junk in (b"[" * 200_000, b'{"a":' * 150_000, b"\xff" * 10):
        assert json.loads(one(lambda s, t: s.sendall(junk))) == unread
    good = json.dumps({
        "build": serve.build_id(), "sha256": sha, "argv": ["info", CLEAN],
        "origin": src.origin, "path": src.path, "member": src.member,
        "color": [False, False], "tty": [False, False],
        "room": serve.headroom()}).encode("ascii")
    assert json.loads(one(lambda s, t: s.sendall(good)))["ok"] is True
    assert len(ran) == 1 and ran.pop()[0] == ["info", CLEAN]
    monkeypatch.setattr(serve, "MAX_REQUEST", 4096)
    assert len(good) < 4096                      # the same request, made too long
    assert json.loads(one(lambda s, t: s.sendall(good + b" " * 5000))) == unread

    monkeypatch.setattr(serve, "REQUEST_SECONDS", 0.3)
    sent = []

    def trickle(s, t):
        for _ in range(400):                     # 40 s of it, if the server lets it
            if not t.is_alive():
                return
            s.sendall(b" ")
            sent.append(1)
            time.sleep(0.1)

    assert one(trickle) == b"" and 0 < len(sent) < 400, len(sent)
    assert ran == []                             # and none of it ran a command


def test_a_session_keeps_a_layout_for_each_way_it_is_finished():
    """`lift` folds accessor names into the field layout and `decompile` does not. In a
    session each has its own, so the one `decompile` reads is the one a fresh process
    builds whether or not a `lift` came first. The fixtures print the same either way,
    so this looks at the tables: one layout handed to both would hold the names."""
    _needs_capstone()
    from jadart import keep
    from jadart.disasm import load_instructions
    from jadart.fields import lift_tables, recover_fields
    from jadart.source import open_source

    def size(layout):
        return sum(len(m) for m in layout.by_class.values())

    src = open_source(CLEAN)
    keep.open_session(src.data)
    try:
        image, fr, hdr = load_instructions(src)
        named = lift_tables(image, fr, True)[0]        # what `lift` builds, first
        plain = lift_tables(image, fr, False)[0]       # what `decompile` then reads
        fresh = recover_fields(fr, getattr(image, "arch", None))
        assert plain is not named
        assert size(plain) == size(fresh) < size(named), (size(plain), size(named))
        assert lift_tables(image, fr, False)[0] is plain
        assert lift_tables(image, fr, True)[0] is named
    finally:
        keep.close_session()


def test_a_served_failure_is_json_only_when_this_command_asked(monkeypatch):
    """`-j` turns a failure into a JSON document, and the flag is the command's own:
    a server answers a `-j` line and then a plain one, and the plain one's failure is
    text. Left set by the line before, it was a document nobody asked for."""
    from jadart import cli
    from jadart.errors import InputError
    monkeypatch.delenv("JADART_SERVER", raising=False)

    def cannot(args):
        raise InputError("this snapshot cannot be read")

    monkeypatch.setattr(cli, "cmd_selectors", cannot)
    lines = [["-j", "selectors", CLEAN], ["selectors", CLEAN],
             ["-j", "selectors", CLEAN], ["selectors", CLEAN]]
    fresh = [_fresh(line) for line in lines]
    assert fresh[0][1].startswith("{") and fresh[1][1] == "" and fresh[1][2], fresh
    served = _Served(CLEAN)
    try:
        for order in (range(4), reversed(range(4))):
            for i in order:
                assert served.ask(lines[i]) == fresh[i], lines[i]
    finally:
        served.close()


def _dispatch_rows(*mid, recv="x2"):
    """A dispatch-table call on the object in `recv`: the class id read, `mid`, which
    makes the row out of it in x30, and the call through the table."""
    return [("ldur", f"x0, [{recv}, #-1]"), ("ubfx", "x0, x0, #0xc, #0x14"), *mid,
            ("ldr", "x30, [x21, x30, lsl #3]"), ("blr", "x30"), ("ret", "")]


def test_a_selector_offset_keeps_the_shift_of_its_immediate():
    """`sub x30, x0, #1, lsl #12` selects the row 0x1000 below the class id. The pass
    that follows the class id to the call read the immediate and dropped its shift, so
    the call printed as `sel_m0x1`, the name of another selector: 312 calls on the
    clean build, `_syncAll`'s among them (#376). An offset in a register is added whole
    or taken away whole, and a 32-bit move into it clears its top half."""
    from jadart.expr import detect_dispatch

    def call(*mid):
        return _lift_rows(_dispatch_rows(*mid))

    def offset(*mid):
        rows = _dispatch_rows(*mid)
        got = detect_dispatch([(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])
        assert len(got) == 1, got
        return next(iter(got.values()))[1]
    assert call(("sub", "x30, x0, #1, lsl #12")) == ["return x2.sel_m0x1000(...);"]
    assert call(("add", "x30, x0, #1, lsl #12")) == ["return x2.sel_0x1000(...);"]
    assert offset(("sub", "x30, x0, #0xfff, lsl #12")) == -0xfff000
    assert offset(("add", "x30, x0, #0xabc, lsl #12")) == 0xabc000
    assert offset(("mov", "x17, #0x48e9"), ("sub", "x30, x0, x17")) == -0x48e9
    assert offset(("mov", "w17, #-0x1234"), ("add", "x30, x0, x17")) == 0xffffedcc


def test_a_selector_offset_the_pass_cannot_add_up_names_no_selector():
    """Where the row is not the class id plus a number the pass has read whole, the call
    has no selector, and it had one: a register shifted or extended as it is added was
    taken as the register, and a 32-bit add, which wraps where the 64-bit one does not,
    as the 64-bit one (#376)."""
    declined = ["var t0 = dispatch(...);   // virtual dispatch", "return t0;"]
    for mid in ([("mov", "x17, #0x48e9"), ("add", "x30, x0, x17, lsl #2")],
                [("mov", "x17, #0x48e9"), ("add", "x30, x0, w17, uxtw")],
                [("mov", "x17, #0x48e9"), ("add", "x30, x0, w17, sxtw #2")],
                [("mov", "x17, #0x48e9"), ("sub", "x30, x0, x17, lsl #12")],
                [("sub", "w30, w0, #1")], [("sub", "w30, w0, #1, lsl #12")],
                [("add", "w30, w0, #5")]):
        assert _lift_rows(_dispatch_rows(*mid)) == declined, mid


def test_a_register_a_row_writes_keeps_no_dispatch_fact():
    """What the pass knows of a register ends where a row writes it. It ended only at
    the first register a row names, so the second register of an `ldp`, a base a load
    moves and whatever a call may write kept theirs: `mov x17, #5; ldp x3, x17, [x9];
    add x30, x0, x17` printed `sel_0x5`, and a call through the pool after a table
    call printed the table call's selector a second time (#376)."""
    declined = ["var t0 = dispatch(...);   // virtual dispatch", "return t0;"]
    for mid in ([("mov", "x17, #5"), ("ldp", "x3, x17, [x9]"), ("add", "x30, x0, x17")],
                [("mov", "x17, #5"), ("ldp", "x3, x17, [x9]"), ("sub", "x30, x0, x17")],
                [("mov", "x17, #5"), ("ldpsw", "x3, x17, [x9]"), ("add", "x30, x0, x17")],
                [("ldp", "x3, x0, [x9]"), ("add", "x30, x0, #5")],
                [("ldp", "x3, x0, [x9]"), ("mov", "x30, x0")]):
        assert _lift_rows(_dispatch_rows(*mid)) == declined, mid
    # A base that moves prints as the store or the load that moved it, then the call.
    for moved in (("ldr", "x3, [x17], #8"), ("ldr", "x3, [x17, #8]!"),
                  ("str", "x3, [x17, #8]!"), ("stp", "x3, x4, [x17], #0x10")):
        for add in (("add", "x30, x0, x17"), ("sub", "x30, x0, x17")):
            got = _lift_rows(_dispatch_rows(("mov", "x17, #5"), moved, add))
            assert "= dispatch(...);" in got[-2], (moved, add, got)
            assert not any("sel_" in ln for ln in got), (moved, add, got)
    # A call writes the registers a class id and a number are kept in.
    for mid in ([("bl", "#0x4000"), ("sub", "x30, x0, #5")],
                [("mov", "x17, #5"), ("bl", "#0x4000"), ("add", "x30, x0, x17")],
                [("mov", "x17, #5"), ("blr", "x9"), ("add", "x30, x0, x17")]):
        got = _lift_rows(_dispatch_rows(*mid))
        assert "= dispatch(...);" in got[-2], (mid, got)
        assert not any("sel_" in ln for ln in got), (mid, got)
    # The target a table call loaded is not the target of the next call.
    again = _dispatch_rows(("sub", "x30, x0, #5"))[:-1] + [
        ("add", "x16, x27, #0xf, lsl #12"), ("ldp", "x5, x30, [x16, #0x8d8]"),
        ("blr", "x30"), ("ret", "")]
    assert _lift_rows(again) == ["x2.sel_m0x5(...);", "return pool_0xf8e0(...);"]
    twice = _dispatch_rows(("sub", "x30, x0, #5"))[:-1] + [("blr", "x30"), ("ret", "")]
    got = _lift_rows(twice)
    assert [ln for ln in got if "sel_" in ln] == ["x2.sel_m0x5(...);"], got


def test_a_selector_offset_in_one_step_or_two_guard():
    """A guard: these already printed the offset the machine uses, or none. An immediate
    as written, a constant moved into a register and added, a copy of the class id,
    which is offset zero; and an offset made by two subtractions, or by a constant
    built with `movk`, has no selector."""
    def call(*mid):
        return _lift_rows(_dispatch_rows(*mid))
    declined = ["var t0 = dispatch(...);   // virtual dispatch", "return t0;"]
    assert call(("sub", "x30, x0, #1")) == ["return x2.sel_m0x1(...);"]
    assert call(("sub", "x30, x0, #0xfd8")) == ["return x2.sel_m0xfd8(...);"]
    assert call(("add", "x30, x0, #0x123")) == ["return x2.sel_0x123(...);"]
    assert call(("mov", "x17, #0x48e9"), ("add", "x30, x0, x17")) == [
        "return x2.sel_0x48e9(...);"]
    assert call(("mov", "x17, #-0x1234"), ("add", "x30, x0, x17")) == [
        "return x2.sel_m0x1234(...);"]
    assert call(("mov", "x30, x0")) == ["return x2.sel_0x0(...);"]
    assert call(("sub", "x30, x0, #1, lsl #12"), ("sub", "x30, x30, #0x234")) == declined
    assert call(("mov", "x17, #0x48e9"), ("movk", "x17, #1, lsl #16"),
                ("add", "x30, x0, x17")) == declined


def test_every_dispatch_offset_on_the_clean_build_is_the_one_in_the_word():
    """Each dispatch site whose row is made by an add or a subtract of an immediate, read
    again off the instruction word: twelve bits, the shift bit, the sign. 312 of the
    clean build's are shifted and each printed the unshifted number (#376); the body of
    `_syncAll` holds one."""
    _needs_capstone()
    import struct
    import jadart
    from jadart.disasm import disassemble_range, load_instructions
    from jadart.expr import detect_dispatch
    image, _fr, _ = load_instructions(CLEAN)
    seen = shifted = 0
    wrong = []
    for cr in image.all_ranges:
        dis = disassemble_range(image, cr)
        for addr, (_recv, off) in detect_dispatch(dis).items():
            (w,) = struct.unpack_from("<I", image.text, addr - 8)
            if off is None or w & 0xBF80001F != 0x9100001E:
                continue                 # not `add x30, xN, #imm` or `sub x30, xN, #imm`
            seen += 1
            shifted += w >> 22 & 1
            imm = (w >> 10 & 0xfff) << (12 if w >> 22 & 1 else 0)
            if off != (-imm if w >> 30 & 1 else imm):
                wrong.append((hex(addr), off))
    assert not wrong, (len(wrong), wrong[:5])
    assert (seen, shifted) == (1685, 312), (seen, shifted)
    body = [ln for f in jadart.decompile(CLEAN, "_syncAll") for ln in f["body"]]
    assert any(".sel_m0x1000(" in ln for ln in body), body
    assert not any(".sel_m0x1(" in ln for ln in body), body



#: The rows that end a dispatch call once the row is in x30.
_TABLE_CALL = [("ldr", "x30, [x21, x30, lsl #3]"), ("blr", "x30"), ("ret", "")]


def test_a_dispatch_receiver_is_the_object_the_class_id_was_read_from():
    """The class id is read before the arguments are moved into place. In
    `_deactivateRecursively` it is read off x2, x2 goes to x1 and x2 is then loaded from
    the pool, and the call printed `pool_0x2a00.sel_m0xfd8(...)`: the receiver was
    whatever the register of the read held at the call (#377). It is the object as it
    was at the read, which x1 holds here, and where no register is proven to hold it and
    it was not pushed either, the call has no receiver."""
    from jadart.expr import detect_dispatch

    def site(rows):
        got = detect_dispatch([(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])
        assert len(got) == 1, got
        return next(iter(got.values()))
    read = [("ldur", "x2, [x1, #0xf]"), ("ldur", "x0, [x2, #-1]"),
            ("ubfx", "x0, x0, #0xc, #0x14")]
    call = [("sub", "x30, x0, #0xfd8"), *_TABLE_CALL]
    pool = ("ldr", "x2, [x27, #0x2a00]")
    moved = [*read, ("mov", "x1, x2"), pool, *call]
    assert site(moved) == ("x1", -0xfd8)
    assert _lift_rows(moved) == ["return x1.field_0x10.sel_m0xfd8(...);"]
    # the register of the read, where nothing wrote it
    assert _lift_rows([*read, *call]) == ["return x1.field_0x10.sel_m0xfd8(...);"]
    none = ["var t0 = sel_m0xfd8(...);   // virtual dispatch", "return t0;"]
    for lost in ([pool],                                # written, and copied nowhere
                 [("mov", "w1, w2"), pool],             # half of it is not the object
                 [("mov", "x1, x2"), ("ldp", "x3, x1, [x5, #0x10]"), pool],
                 [("mov", "x1, x2"), ("mov", "x1, x3"), pool]):
        rows = [*read, *lost, *call]
        assert site(rows) == (None, -0xfd8), lost
        assert _lift_rows(rows) == none, lost
    # A call between the read and the dispatch takes every register it may write. The
    # class id is kept in x20 here, which a call leaves, and the object is not kept.
    kept = [("ldur", "x20, [x2, #-1]"), ("ubfx", "x20, x20, #0xc, #0x14"),
            ("mov", "x1, x2"), ("bl", "#0x4000"), ("sub", "x30, x20, #0xfd8"),
            *_TABLE_CALL]
    assert site(kept) == (None, -0xfd8)


def test_a_dispatch_receiver_is_what_every_way_to_the_call_leaves():
    """The receiver was followed down the rows between the class id read and the call
    as if they ran top to bottom. `cbz x5, L; mov x1, x2; L:` printed x1, which holds
    the object on one of the two ways to the call, and so did a copy that a block
    after the `ret` or a loop back edge writes over (#377). A row a branch names keeps
    what every way into it carries. The Smi check, a `tbz` on the row before the read
    that lands after the `ubfx`, carries the register of the read."""
    from jadart.expr import detect_dispatch

    def site(rows):
        got = detect_dispatch([(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])
        assert len(got) == 1, got
        return next(iter(got.values()))
    read = [("ldur", "x0, [x2, #-1]"), ("ubfx", "x0, x0, #0xc, #0x14")]
    call = [("sub", "x30, x0, #8"), *_TABLE_CALL]
    pool = ("ldr", "x2, [x27, #0x10]")
    # The Smi check: the object is in x2 whether or not its class id was read off it.
    smi = [("mov", "x3, #0x3b"), ("tbz", "w2, #0, #0x10"), ("ldur", "x3, [x2, #-1]"),
           ("ubfx", "x3, x3, #0xc, #0x14")]
    by_reg = [*smi, ("mov", "x1, x2"), pool, ("sub", "x30, x3, #8"), *_TABLE_CALL]
    assert site(by_reg) == ("x1", -8)
    assert _lift_rows(by_reg)[-1] == "return x2.sel_m0x8(...);"
    by_slot = [*smi, ("ldur", "x16, [x1, #0x17]"), ("stp", "x16, x2, [x15]"),
               ("mov", "x2, x3"), ("mov", "x30, x2"), *_TABLE_CALL]
    assert site(by_slot) == (8, 0)
    assert _lift_rows(by_slot)[-1] == "return x2.sel_0x0(x1.field_0x18);"
    # A push the check jumps over is a push on one way only.
    early = [("mov", "x3, #0x3b"), ("tbz", "w2, #0, #0x14"), ("ldur", "x3, [x2, #-1]"),
             ("ubfx", "x3, x3, #0xc, #0x14"), ("str", "x2, [x15]"), ("mov", "x2, x3"),
             ("mov", "x30, x2"), *_TABLE_CALL]
    assert site(early) == (None, 0)
    # Only that check may skip the read: another test, register or bit proves nothing
    # about what x2 holds on the way that did not read it.
    for skip in (("cbz", "x5, #0x10"), ("tbz", "w4, #0, #0x10"),
                 ("tbz", "w2, #1, #0x10"), ("tbnz", "w2, #0, #0x10")):
        rows = [smi[0], skip, *smi[2:], ("mov", "x1, x2"), ("sub", "x30, x3, #8"),
                *_TABLE_CALL]
        assert site(rows) == (None, -8), skip
        assert not any(".sel_" in line for line in _lift_rows(rows)), skip
    # A copy on one way only: x1 is not the object when x5 is zero, x2 is on both.
    one = [*read, ("cbz", "x5, #0x10"), ("mov", "x1, x2"), *call]
    assert site(one) == ("x2", -8)
    assert _lift_rows(one) == ["return x2.sel_m0x8(...);"]
    # ... and where x2 is then written, no register holds it on both.
    lost = [*read, ("cbz", "x5, #0x10"), ("mov", "x1, x2"), pool, *call]
    assert site(lost) == (None, -8)
    # A block after the `ret` writes x1 and jumps back in.
    far = [*read, ("mov", "x1, x2"), ("cbz", "x5, #0x20"), *call,
           ("mov", "x1, x7"), ("b", "#0x10")]
    assert site(far) == (None, -8)
    assert _lift_rows(far)[:2] == ["var t0 = sel_m0x8(...);   // virtual dispatch",
                                   "return t0;"]
    # A loop back edge into the stretch, after x1 is written.
    loop = [*read, ("mov", "x1, x2"), ("sub", "x30, x0, #8"), ("mov", "x1, x0"),
            ("cbnz", "x0, #0xc"), *_TABLE_CALL]
    assert site(loop) == (None, -8)
    # A branch from above the row before the read carries nothing that was followed.
    above = [("cbz", "x5, #0x14"), ("nop", ""), *read, ("mov", "x1, x2"), *call]
    assert site(above) == (None, -8)
    # A jump through a register may land on any row of the body.
    assert site([*read, ("mov", "x1, x2"), *call[:-1], ("br", "x9")]) == (None, -8)
    # Both ways agree: the copy is made before the branch and x2 is lost on one.
    both = [*read, ("mov", "x1, x2"), ("cbz", "x5, #0x18"), pool, ("nop", ""), *call]
    assert site(both) == ("x1", -8)
    # A row after `b` that no branch names is not on any way to the call.
    over = [*read, ("mov", "x1, x2"), ("b", "#0x18"), ("mov", "x1, x7"), ("nop", ""),
            *call]
    assert site(over) == ("x1", -8)
    # A branch to the call itself, past a write of x1.
    late = [*read, ("mov", "x1, x2"), ("sub", "x30, x0, #8"),
            ("ldr", "x30, [x21, x30, lsl #3]"), ("cbz", "x5, #0x1c"), ("mov", "x1, x7"),
            ("blr", "x30"), ("ret", "")]
    assert site(late) == ("x2", -8)


def test_a_dispatch_receiver_that_went_to_the_stack_is_read_from_its_slot():
    """A call that takes its arguments on the stack pushes the receiver and then copies
    the class id over it: `stp x16, x0, [x15]; mov x0, x8`. The call printed
    `x0.sel_0x0(...)`, the register the class id is in, 426 times on the clean build
    (#377). The receiver is the value pushed, where that slot is argument zero at the
    call. `markNeedsBuild` pushes it below another value, and prints no receiver."""
    from jadart.expr import detect_dispatch

    def site(rows):
        got = detect_dispatch([(i * 4, mn, op, "") for i, (mn, op) in enumerate(rows)])
        assert len(got) == 1, got
        return next(iter(got.values()))
    read = [("ldur", "x0, [x2, #0x27]"), ("ldur", "x8, [x0, #-1]"),
            ("ubfx", "x8, x8, #0xc, #0x14")]
    call = [("mov", "x0, x8"), ("mov", "x30, x0"), *_TABLE_CALL]
    swap = [*read, ("ldur", "x16, [x1, #0x17]"), ("stp", "x16, x0, [x15]"), *call]
    assert site(swap) == (8, 0)
    assert _lift_rows(swap) == ["return x2.field_0x28.sel_0x0(x1.field_0x18);"]
    one = [*read, ("str", "x0, [x15]"), *call]
    assert site(one) == (0, 0)
    assert _lift_rows(one) == ["return x2.field_0x28.sel_0x0();"]
    # The slot is written again, or part of it is or may be, or SP moves under it.
    for after in ([("str", "x3, [x15]")], [("str", "w3, [x15, #4]")],
                  [("sturb", "w3, [x15, #7]")], [("sub", "x15, x15, #0x10")],
                  [("stp", "x3, x5, [x15, #-8]")], [("str", "x3, [x15], #8")],
                  [("str", "q0, [x15, #-8]")], [("stlr", "x3, [x15]")],
                  [("mov", "x15, x3")], [("dc", "zva, x15")]):
        rows = [*read, ("str", "x0, [x15]"), *after, *call]
        assert site(rows) == (None, 0), after
        assert not _lift_rows(rows)[0].startswith("return x"), after
    # Dart 2.19 pushes: each store moves SP down first, and the slot is that much up.
    tail = [("mov", "x17, #0x9a0e"), ("add", "x30, x0, x17"), *_TABLE_CALL]
    load = [("ldur", "x2, [x1, #0xf]"), ("ldur", "x0, [x2, #-1]"),
            ("ubfx", "x0, x0, #0xc, #0x14")]
    push = [*load, ("ldur", "x16, [x1, #0x17]"), ("stp", "x16, x2, [x15, #-0x10]!"),
            ("ldur", "x2, [x1, #0x1f]"), ("str", "x2, [x15, #-8]!"), *tail]
    assert site(push) == (16, 0x9a0e)
    assert _lift_rows(push) == [
        "return x1.field_0x10.sel_0x9a0e(x1.field_0x18, x1.field_0x20);"]
    for after in ([("add", "x15, x15, #8")], [("str", "x4, [x15, #8]!")],
                  [("str", "w4, [x15, #-8]!")], [("str", "x4, [x15], #-8")]):
        rows = [*load, ("str", "x2, [x15, #-8]!"), ("mov", "x2, x3"), *after, *tail]
        assert site(rows) == (None, 0x9a0e), after
        assert not _lift_rows(rows)[0].startswith("return x"), after
    # markNeedsBuild: pushed below a value from the pool, then its register reloaded.
    below = [("ldur", "x4, [x2, #0x27]"), ("ldur", "x0, [x4, #-1]"),
             ("ubfx", "x0, x0, #0xc, #0x14"), ("ldr", "x16, [x27, #0x2ab8]"),
             ("stp", "x4, x16, [x15]"), ("ldr", "x4, [x27, #0x818]"),
             ("mov", "x17, #0x498d"), ("add", "x30, x0, x17"), *_TABLE_CALL]
    assert site(below) == (0, 0x498d)
    assert _lift_rows(below) == [
        "var t0 = sel_0x498d(pool_0x2ab8, x2.field_0x28);   // virtual dispatch",
        "return t0;"]


def test_every_dispatch_receiver_on_the_clean_build_is_where_the_pass_says():
    """Each dispatch site of the clean build with its offset, by where its receiver is at
    the call: the first argument register, the register the class id was read off,
    the stack. 440 of the calls printed another value: the register the class id is in
    for those on the stack, and what was loaded over the receiver for 13 of those in a
    register (#377). The six with none are in bodies that jump through a register. The
    named bodies are the issue's."""
    _needs_capstone()
    import jadart
    from jadart.disasm import disassemble_range, load_instructions
    from jadart.expr import detect_dispatch
    image, _fr, _ = load_instructions(CLEAN)
    where = {"x1": 0, "other": 0, "stack": 0, "none": 0}
    for cr in image.all_ranges:
        dis = disassemble_range(image, cr)
        at = {row[0]: i for i, row in enumerate(dis)}
        for addr, (recv, off) in detect_dispatch(dis).items():
            if off is None:
                assert recv is None, hex(addr)
                continue
            if isinstance(recv, str):
                # No row from the read to the call writes it but a copy of the object.
                i = at[addr]
                wrote = [j for j in range(i - 1, max(i - 24, -1), -1)
                         if dis[j][2].split(",")[0] in (recv, "w" + recv[1:])
                         and dis[j][1] not in ("str", "stur", "stp", "cmp", "tbz", "tbnz",
                                               "cbz", "cbnz", "tst")]
                tags = [j for j in range(i - 1, max(i - 24, -1), -1)
                        if dis[j][1] == "ldur" and dis[j][2].endswith(", #-1]")]
                assert tags and (not wrote or wrote[0] < tags[0]
                                 or dis[wrote[0]][1] == "mov"), hex(addr)
            where["x1" if recv == "x1" else "other" if isinstance(recv, str)
                  else "none" if recv is None else "stack"] += 1
    assert where == {"x1": 1761, "other": 368, "stack": 445, "none": 6}, where
    for name, want, wrong in (
            ("_deactivateRecursively", "a0.sel_m0xfd8(", "pool_0x2a00."),
            ("markNeedsBuild", "sel_0x498d(pool_0x2ab8, ", "pool_0x818.")):
        body = [ln for f in jadart.decompile(CLEAN, name) for ln in f["body"]]
        assert any(want in ln for ln in body), body
        assert not any(wrong in ln for ln in body), body


def test_following_a_dispatch_receiver_costs_the_same_per_row_guard():
    """A guard: the receiver is followed from the class id read to the call only over
    `_RECV_WINDOW` rows, so many calls off one read, the shape that would make the walk
    quadratic, cost the same per row at four times the length. Counted in rows whose
    writes are asked for, not in time."""
    from jadart import expr

    def per_row(blocks):
        rows = []
        for _ in range(blocks):
            rows.append(("ldur", "x0, [x2, #-1]"))
            for _ in range(15):
                rows += [("ubfx", "x3, x0, #0xc, #0x14"), ("sub", "x30, x3, #5"),
                         ("ldr", "x30, [x21, x30, lsl #3]"), ("blr", "x30")]
        for _ in range(blocks * 61):                # and the same again with no read
            rows += [("ubfx", "x3, x0, #0xc, #0x14"), ("sub", "x30, x3, #5"),
                     ("ldr", "x30, [x21, x30, lsl #3]"), ("blr", "x30")]
        calls = [0]
        real = expr._def_use

        def counted(mn, op):
            calls[0] += 1
            return real(mn, op)
        expr._def_use = counted
        try:
            got = expr.detect_dispatch(
                [(i * 4, m, o, "") for i, (m, o) in enumerate(rows)])
        finally:
            expr._def_use = real
        assert len(got) == blocks * 15 + blocks * 61
        return calls[0] / len(rows)
    small, large = per_row(8), per_row(32)
    assert large <= small * 1.25 + 1, (small, large)
    assert large <= getattr(expr, "_RECV_WINDOW", 64), large


def _flags_371(setter, a, b):
    """N, Z, C and V as an arm64 CPU leaves them after `cmp a, b` (or `subs`) and
    after `cmn a, b` (or `adds`), for two 64-bit values."""
    m = (1 << 64) - 1
    y, carry = ((~b) & m, 1) if setter in ("cmp", "subs") else (b, 0)
    total = a + y + carry
    r = total & m
    return (r >> 63, int(r == 0), total >> 64,
            int((a >> 63) == (y >> 63) and (r >> 63) != (a >> 63)))


_HOLDS_371 = {
    "hs": lambda n, z, c, v: c == 1, "lo": lambda n, z, c, v: c == 0,
    "hi": lambda n, z, c, v: c == 1 and z == 0,
    "ls": lambda n, z, c, v: c == 0 or z == 1}


def _reads_371(cond, env):
    """What a printed condition says for the register values `env`: Dart's 64-bit
    wrapping arithmetic either side of one comparison, signed unless the operator
    carries the unsigned mark."""
    m = (1 << 64) - 1
    lhs, rel, rhs = re.fullmatch(r"(.+) (u?(?:[<>]=?)|[=!]=) (.+)", cond).groups()
    a, b = (eval(side, {}, env) & m for side in (lhs, rhs))
    if not rel.startswith("u"):
        a, b = (v - (1 << 64) if v >> 63 else v for v in (a, b))
    return {"==": a == b, "!=": a != b, "<": a < b, "<=": a <= b, ">": a > b,
            ">=": a >= b}[rel.lstrip("u")]


def test_a_condition_reads_what_the_flags_hold():
    """Each unsigned condition `_cond_text` spells after an integer compare, a subtract
    or an add holds exactly when the CPU's flags make the branch go, over the values
    where the readings part: zero, the two ends of the signed range and of the unsigned.

    hs, lo, hi and ls read the carry, and printed `x5 < x6` for lo they were the signed
    comparison: `cmp x5, x6; cset x0, lo` disagreed with a CPU on 24 of 40 random
    entry states, and a bounds check, one unsigned compare of the index against the
    length, read as passing a negative index (#371). After an add the carry is the
    carry out, which printed as the sign of the sum. A condition with no exact
    spelling prints `?`, which nothing takes for a claim."""
    from jadart.cfg import _cond_text
    edge = [0, 1, 2, 7, (1 << 63) - 1, 1 << 63, (1 << 63) + 1, (1 << 64) - 2, (1 << 64) - 1]
    rows = {"cmp": "x5, x6", "subs": "x1, x5, x6", "cmn": "x5, x6", "adds": "x1, x5, x6"}
    spelled = 0
    for setter, op in rows.items():
        for cc, holds in _HOLDS_371.items():
            cond = _cond_text((0, setter, op, ""), "b." + cc, "#0")
            if "?" in cond:
                continue
            spelled += 1
            for a in edge:
                for b in edge:
                    assert (_reads_371(cond, {"x5": a, "x6": b})
                            == holds(*_flags_371(setter, a, b))), (
                        setter, cc, cond, hex(a), hex(b))
    # All four after each of the two subtracts; after an add hs and lo, the carry out,
    # and hi and ls declined.
    assert spelled == 12
    # ...and against a constant.
    for setter, op in (("cmp", "x5, #7"), ("subs", "x1, x5, #7"), ("cmn", "x5, #7"),
                       ("adds", "x1, x5, #7"), ("cmp", "x5, #0"), ("cmn", "x5, #0")):
        k = int(op.rsplit("#", 1)[1])
        for cc, holds in _HOLDS_371.items():
            cond = _cond_text((0, setter, op, ""), "b." + cc, "#0")
            if "?" in cond:
                assert setter in ("cmn", "adds") and cc in ("hi", "ls"), (setter, cc)
                continue
            for a in edge + [(1 << 64) - 7, (1 << 63) - 7, (1 << 63) + 7]:
                assert _reads_371(cond, {"x5": a}) == holds(*_flags_371(setter, a, k)), (
                    setter, cc, cond, hex(a))


def test_the_unsigned_conditions_are_not_spelled_as_the_signed_ones():
    """The spelling: the signed operator with a `u` in front, `x5 u< x6`, on a branch, a
    conditional select and a conditional set alike, and its negation is unsigned too.
    The issue's three programs (#371)."""
    from jadart.cfg import _cond_text, negate_cond
    for cc, rel in (("hs", "u>="), ("cs", "u>="), ("lo", "u<"), ("cc", "u<"),
                    ("hi", "u>"), ("ls", "u<=")):
        assert _cond_text((0, "cmp", "x5, x6", ""), "b." + cc, "#0") == f"x5 {rel} x6"
        assert _cond_text((0, "subs", "x1, x5, x6", ""), "b." + cc, "#0") == f"x5 {rel} x6"
    assert negate_cond("x5 u< x6") == "x5 u>= x6" and negate_cond("x5 u> 3") == "x5 u<= 3"
    assert negate_cond("(x5 + x6) u< x5") == "(x5 + x6) u>= x5"
    assert _lift_rows([("cmp", "x5, x6"), ("cset", "x0, lo"), ("ret", "")]) == [
        "return x5 u< x6 ? 1 : 0;"]
    assert _lift_rows([("cmp", "x5, x6"), ("b.hi", "#0x10"), ("mov", "x0, #1"),
                       ("ret", ""), ("mov", "x0, #2"), ("ret", "")]) == [
        "if (x5 u<= x6) {", "return 1;", "} else {", "return 2;", "}"]
    assert _lift_rows([("adds", "x1, x5, x6"), ("cset", "x0, hs"), ("ret", "")]) == [
        "return (x5 + x6) u< x5 ? 1 : 0;"]
    # The select family, and the operands as they read at the compare.
    assert _lift_rows([("cmp", "x5, x6"), ("csel", "x0, x2, x3, hs"), ("ret", "")]) == [
        "return x5 u>= x6 ? x2 : x3;"]
    assert _lift_rows([("add", "x5, x5, #1"), ("cmp", "x5, x6"), ("cinc", "x0, x2, ls"),
                       ("ret", "")]) == ["return (x5 + 1) u<= x6 ? x2 + 1 : x2;"]
    assert _lift_rows([("subs", "x5, x5, x6"), ("b.lo", "#0x10"), ("mov", "x0, #1"),
                       ("ret", ""), ("mov", "x0, #2"), ("ret", "")])[:2] == [
        "var t0 = x5;", "if (t0 u>= x6) {"]
    # hi and ls after an add read the carry and Z at once: declined, the select raw.
    assert _lift_rows([("cmn", "x5, x6"), ("cset", "x0, hi"), ("ret", "")]) == [
        "cset x0, hi", "return x0;"]
    assert "?" in _cond_text((0, "adds", "x1, x5, x6", ""), "b.ls", "#0")
    # The conditions that are not the carry read as they did, but for the sign of the
    # difference, which is not the order of the operands (#399).
    assert _cond_text((0, "cmp", "x5, x6", ""), "b.mi", "#0") == "(x5 - x6) < 0"
    # A signed condition after an add compares a with -b (#400).
    assert _cond_text((0, "cmn", "x5, #4", ""), "b.lt", "#0") == "x5 < -4"


def test_a_floating_point_compare_keeps_the_plain_operators():
    """The carry conditions after `fcmp` order two doubles, which have no unsigned
    reading: `fcmp d0, d1; b.lo` is `d0 < d1`. Those that also hold when a side is NaN
    are the negation of an ordering, never the reversed operator (#402)."""
    from jadart.cfg import _cond_text
    for cc, want in (("lo", "d0 < d1"), ("hs", "!(d0 < d1)"), ("hi", "!(d0 <= d1)"),
                     ("ls", "d0 <= d1"), ("mi", "d0 < d1"), ("pl", "!(d0 < d1)"),
                     ("lt", "!(d0 >= d1)"), ("ge", "d0 >= d1")):
        assert _cond_text((0, "fcmp", "d0, d1", ""), "b." + cc, "#0") == want
    assert _cond_text((0, "fcmp", "d0, d0", ""), "b.vs", "#0") == "isNaN(d0)"


#: Whether condition code `cc` holds for the flags NZCV, from the Arm ARM.
_HOLDS_402 = {
    "eq": lambda n, z, c, v: z == 1, "ne": lambda n, z, c, v: z == 0,
    "hs": lambda n, z, c, v: c == 1, "cs": lambda n, z, c, v: c == 1,
    "lo": lambda n, z, c, v: c == 0, "cc": lambda n, z, c, v: c == 0,
    "mi": lambda n, z, c, v: n == 1, "pl": lambda n, z, c, v: n == 0,
    "vs": lambda n, z, c, v: v == 1, "vc": lambda n, z, c, v: v == 0,
    "hi": lambda n, z, c, v: c == 1 and z == 0, "ls": lambda n, z, c, v: c == 0 or z == 1,
    "ge": lambda n, z, c, v: n == v, "lt": lambda n, z, c, v: n != v,
    "gt": lambda n, z, c, v: z == 0 and n == v, "le": lambda n, z, c, v: z == 1 or n != v}


def _fcmp_flags(a, b):
    """NZCV after `fcmp` of two Python floats: less, equal, greater or unordered."""
    if math.isnan(a) or math.isnan(b):
        return 0, 0, 1, 1
    return (1, 0, 0, 0) if a < b else (0, 1, 1, 0) if a == b else (0, 0, 1, 0)


def _reads_402(cond, env):
    """What a printed condition over doubles says for `env`, read as Dart reads it: an
    ordering with a NaN side is false, `!=` true."""
    py = cond.replace("isNaN(", "math.isnan(").replace("!(", "not (")
    py = py.replace(" || ", " or ").replace(" && ", " and ")
    return bool(eval(py, {"math": math}, env))


def test_a_condition_after_a_floating_point_compare_holds_on_nan():
    """`fcmp` sets NZCV to 0011 when either side is NaN, and every condition that holds
    there (ne, hs, pl, hi, lt, le, vs) is true for NaN where an ordering is false. `fcmp
    d0, d1; b.lt` printed `d0 < d1`, and the branch the CPU takes on NaN read as not
    taken; hs, pl and ge all printed `d0 >= d1`, three conditions as one (#402). The
    truth table: each condition over NaN, the infinities, both zeros and two finite
    values, printed after `fcmp` and `fcmpe`, against a register and against zero, and
    its negation; then the branch, `cset` and `csel` as tier 3 prints them, each
    either exact or left raw."""
    from jadart.cfg import _cond_text, negate_cond
    vals = [math.nan, -math.inf, -1.5, -0.0, 0.0, 1.5, math.inf]
    for setter, op in (("fcmp", "d0, d1"), ("fcmpe", "d0, d1"), ("fcmp", "d0, #0.0")):
        for cc, holds in _HOLDS_402.items():
            cond = _cond_text((0, setter, op, ""), "b." + cc, "#0")
            for a in vals:
                for b in (vals if "#" not in op else [0.0]):
                    want = holds(*_fcmp_flags(a, b))
                    env = {"d0": a, "d1": b}
                    assert _reads_402(cond, env) == want, (setter, op, cc, cond, a, b)
                    assert _reads_402(negate_cond(cond), env) != want, (op, cc, a, b)
    for cc, holds in _HOLDS_402.items():
        fall = _lift_rows([("fcmp", "d0, d1"), ("b." + cc, "#0x10"), ("mov", "x0, #1"),
                           ("ret", ""), ("mov", "x0, #2"), ("ret", "")])
        assert fall[1:] == ["return 1;", "} else {", "return 2;", "}"], (cc, fall)
        cond = fall[0][len("if ("):-len(") {")]
        sel = {}
        for mn, ops, arms in (("cset", f"x0, {cc}", " ? 1 : 0;"),
                              ("csel", f"x0, x2, x3, {cc}", " ? x2 : x3;")):
            out = _lift_rows([("fcmp", "d0, d1"), (mn, ops), ("ret", "")])
            if out[0].endswith(arms):
                sel[mn] = out[0][len("return "):-len(arms)]
            else:
                assert out == [f"{mn} {ops}", "return x0;"], (cc, out)
        for a in vals:
            for b in vals:
                env, want = {"d0": a, "d1": b}, holds(*_fcmp_flags(a, b))
                assert _reads_402(cond, env) != want, (cc, cond, a, b)
                for mn, text in sel.items():
                    assert _reads_402(text, env) == want, (mn, cc, text, a, b)
    # Negated once the operand is a field: `x1.field_0x9 < 0.0` names no double, and
    # flipping its operator was the bug again.
    assert _lift_rows([("ldr", "d0, [x1, #8]"), ("fcmp", "d0, #0.0"), ("b.lt", "#0x10"),
                       ("b", "#0x14"), ("bl", "#0x100"), ("ret", "")])[0] == (
        "if (!(x1.field_0x9 >= 0.0)) {")


_HOLDS_399 = {"mi": lambda n, z, c, v: n == 1, "pl": lambda n, z, c, v: n == 0}


def test_a_sign_condition_after_a_compare_reads_the_difference():
    """mi and pl after `cmp` or `subs` read N, the sign of the difference as it wrapped
    at 64 bits, which is the order of the two operands only where the subtraction does
    not overflow. Printed as `x5 >= x6`, `cmp x5, x6; b.mi` fell through for x5 =
    0x8000000000000000 and x6 = 1 where the CPU leaves N clear, and 3 of 40 random entry
    states disagreed with a CPU (#399). The truth table: each printed condition and its
    negation against the flags, over the values where the readings part."""
    from jadart.cfg import _cond_text, negate_cond
    m = (1 << 64) - 1
    edge = [0, 1, 2, 7, (1 << 63) - 1, 1 << 63, (1 << 63) + 1, (1 << 64) - 2, m]
    forms = [("cmp", "x5, x6", lambda b: b), ("subs", "x1, x5, x6", lambda b: b),
             ("cmp", "x5, x6, lsl #2", lambda b: b << 2 & m),
             ("cmp", "x5, #7", lambda b: 7), ("subs", "x1, x5, #7", lambda b: 7),
             ("cmp", "x5, #0", lambda b: 0), ("cmp", "x5, xzr", lambda b: 0)]
    for setter, op, rhs in forms:
        for cc, holds in _HOLDS_399.items():
            cond = _cond_text((0, setter, op, ""), "b." + cc, "#0")
            for a in edge:
                for b in edge:
                    env, want = {"x5": a, "x6": b}, holds(*_flags_371(setter, a, rhs(b)))
                    assert _reads_371(cond, env) == want, (setter, op, cc, cond, a, b)
                    assert _reads_371(negate_cond(cond), env) != want, (op, cc, cond)
    # Against zero the difference is the operand, and reads as it did.
    assert _cond_text((0, "cmp", "x5, #0", ""), "b.mi", "#0") == "x5 < 0"
    assert _cond_text((0, "cmp", "x5, x6", ""), "b.pl", "#0") == "(x5 - x6) >= 0"
    # The issue's program, a conditional set and a select.
    assert _lift_rows([("cmp", "x5, x6"), ("b.mi", "#0x10"), ("mov", "x0, #1"),
                       ("ret", ""), ("mov", "x0, #2"), ("ret", "")]) == [
        "if ((x5 - x6) >= 0) {", "return 1;", "} else {", "return 2;", "}"]
    assert _lift_rows([("subs", "x1, x5, #4"), ("cset", "x0, mi"), ("ret", "")]) == [
        "return (x5 - 4) < 0 ? 1 : 0;"]
    assert _lift_rows([("cmp", "x5, x6, lsl #2"), ("csel", "x0, x2, x3, pl"),
                       ("ret", "")]) == ["return (x5 - (x6 << 2)) >= 0 ? x2 : x3;"]
    # At 32 bits the sign is bit 31 of the difference, as it was (#370).
    assert _lift_rows([("cmp", "w5, w6"), ("cset", "x0, pl"), ("ret", "")]) == [
        "return (x5 - x6).toSigned(32) >= 0 ? 1 : 0;"]
    assert _lift_rows([("cmp", "w5, #4"), ("cset", "x0, mi"), ("ret", "")]) == [
        "return (x5 - 4).toSigned(32) < 0 ? 1 : 0;"]


_HOLDS_400 = {"lt": lambda n, z, c, v: n != v, "ge": lambda n, z, c, v: n == v,
              "gt": lambda n, z, c, v: z == 0 and n == v,
              "le": lambda n, z, c, v: z == 1 or n != v}


def test_a_signed_condition_after_an_add_compares_the_operands():
    """lt, ge, gt and le after `cmn a, b` or `adds` read N and V of the sum, which is
    the order of `a` against `-b`. Printed as the sign of the wrapped sum, `cmn x5, #4;
    b.lt` fell through to `return 2` where `x5 + 4` overflows and the CPU does not
    branch (1 of 40 random entry states, #400). Against a constant `-b` is exact. Against
    a register it overflows itself for b = 0x8000000000000000, and has no spelling here:
    the condition is declined. At 32 bits the halves are added sign-extended (#370), as
    before. The truth table: each printed condition and its negation against the flags."""
    from jadart.cfg import _cond_text, negate_cond
    m = (1 << 64) - 1
    edge = [0, 1, 2, 7, (1 << 63) - 1, 1 << 63, (1 << 63) + 1, (1 << 64) - 2, m,
            (1 << 63) - 4, (1 << 63) - 5, (1 << 64) - 4, (1 << 64) - 5, (1 << 63) - 0x10]
    for setter, op, k in (("cmn", "x5, #4", 4), ("adds", "x1, x5, #4", 4),
                          ("cmn", "x5, #0x10", 0x10), ("cmn", "x5, #0", 0)):
        for cc, holds in _HOLDS_400.items():
            cond = _cond_text((0, setter, op, ""), "b." + cc, "#0")
            for a in edge:
                want = holds(*_flags_371(setter, a, k))
                assert _reads_371(cond, {"x5": a}) == want, (setter, op, cc, cond, hex(a))
                assert _reads_371(negate_cond(cond), {"x5": a}) != want, (op, cc, cond)
    assert _cond_text((0, "cmn", "x5, #4", ""), "b.lt", "#0") == "x5 < -4"
    assert _cond_text((0, "cmn", "x5, #0", ""), "b.ge", "#0") == "x5 >= 0"
    for setter, op in (("cmn", "x5, x6"), ("adds", "x1, x5, x6"),
                       ("cmn", "x5, x6, lsl #2")):
        for cc in _HOLDS_400:
            assert "?" in _cond_text((0, setter, op, ""), "b." + cc, "#0"), (op, cc)
    # The issue's program, and a select declined to its raw line.
    assert _lift_rows([("cmn", "x5, #4"), ("b.lt", "#0x10"), ("mov", "x0, #1"),
                       ("ret", ""), ("mov", "x0, #2"), ("ret", "")]) == [
        "if (x5 >= -4) {", "return 1;", "} else {", "return 2;", "}"]
    assert _lift_rows([("adds", "x1, x5, #1"), ("cset", "x0, gt"), ("ret", "")]) == [
        "return x5 > -1 ? 1 : 0;"]
    assert _lift_rows([("cmn", "x5, x6"), ("csel", "x0, x2, x3, lt"), ("ret", "")]) == [
        "csel x0, x2, x3, lt", "return x0;"]
    # Neither a sign test nor a 32-bit sum changes.
    assert _cond_text((0, "cmn", "x5, #4", ""), "b.mi", "#0") == "(x5 + 4) < 0"
    assert _lift_rows([("cmn", "w5, w6"), ("cset", "x0, lt"), ("ret", "")]) == [
        "return (x5.toSigned(32) + x6.toSigned(32)) < 0 ? 1 : 0;"]


def _sx(v, n):
    """The low `n` bits of `v`, sign-extended."""
    v &= (1 << n) - 1
    return v - (1 << n) if v >> (n - 1) else v


#: Entry values that tell a 32-bit read from a 64-bit one: each half at its edges.
_W_EDGE = (0, 1, 0x7f, 0x80, 0xff, 0x7fff, 0x8000, 0xffff, 0x7fffffff, 0x80000000,
           0xffffffff, 0x100000000, 0x17fffffff, 0x180000000, 0xffffffff00000000,
           0xffffffff7fffffff, 0xffffffff80000000, (1 << 63) - 1, 1 << 63, (1 << 64) - 1)


def _w_env(rng, regs=("x5", "x6")):
    """Random 64-bit register values, weighted to `_W_EDGE` and to two registers that
    agree in their low half and differ above it."""
    env = {r: rng.choice((rng.getrandbits(64), rng.getrandbits(32), rng.choice(_W_EDGE)))
           for r in regs}
    if len(regs) > 1 and rng.random() < 0.2:
        env[regs[1]] = env[regs[0]] & 0xffffffff | rng.choice(_W_EDGE) >> 32 << 32
    return env


def test_an_extended_register_operand_reads_the_part_it_extends():
    """`add x0, x5, w6, sxtw` adds the low 32 bits of x6, sign-extended. Tier 3 printed
    `x5 + x6`, the register whole, and so for every extend, with a shift or without, on
    `add` and `sub` (#369). Each of the eight extends is checked against the arm64
    definition on random inputs, in the 64-bit form and the 32-bit one, where the result
    keeps its low half. An element address reads its index the same way, and a `cmn`
    with an extended operand, which `cmp` already declined, declines."""
    import random
    mask = (1 << 64) - 1
    one = lambda op: _untag_text([("add", f"x0, x5, {op}")])
    assert one("w6, sxtw") == "x5 + x6.toSigned(32)"
    assert one("w6, uxtw") == "x5 + x6.toUnsigned(32)"
    assert one("w6, uxtb") == "x5 + (x6 & 0xff)"
    assert one("w6, sxth #2") == "x5 + (x6.toSigned(16) << 2)"
    assert one("x6, sxtx #1") == "x5 + (x6 << 1)"
    assert _untag_text([("sub", "x0, x5, w6, uxtw #3")]) == (
        "x5 - (x6.toUnsigned(32) << 3)")
    # A value that already is the extension gets no second one, and a literal is folded.
    untag = [("sbfx", "x6, x6, #1, #0x1f"), ("add", "x0, x5, w6, sxtw")]
    assert _untag_text(untag) == "x5 + (x6.toSigned(32) >> 1)"
    assert _untag_text([("sxtw", "x6, w6"), ("add", "x0, x5, w6, sxtw")]) == (
        "x5 + (x6 << 32 >> 32)")
    assert _untag_text([("mov", "w6, #-5"), ("add", "x0, x5, w6, uxtw")]) == (
        "x5 + 0xfffffffb")
    # A 32-bit result truncated on the way is read before the truncation.
    assert _untag_text([("add", "w6, w6, w5"), ("add", "x0, x5, w6, sxtw")]) == (
        "x5 + (x6 + x5).toSigned(32)")
    rng = random.Random(369)
    extends = {"uxtb": 8, "uxth": 16, "uxtw": 32, "uxtx": 64,
               "sxtb": 8, "sxth": 16, "sxtw": 32, "sxtx": 64}
    for mn in ("add", "sub"):
        for kind, bits in extends.items():
            for sh in (0, 1, 3):
                tail = f"{kind} #{sh}" if sh else kind
                reg = "x6" if bits == 64 else "w6"
                wide = _untag_text([(mn, f"x0, x5, {reg}, {tail}")])
                low = _untag_text([(mn, f"w0, w5, w6, {tail}")])
                for _ in range(60):
                    env = _w_env(rng)
                    a, b = env["x5"], env["x6"]
                    part = _sx(b, bits) if kind[0] == "s" else b & ((1 << bits) - 1)
                    want = a + (part << sh) if mn == "add" else a - (part << sh)
                    assert _dart_int(wide, env) == want & mask, (wide, env)
                    part = _sx(b, min(bits, 32)) if kind[0] == "s" else (
                        b & ((1 << min(bits, 32)) - 1))
                    want = a + (part << sh) if mn == "add" else a - (part << sh)
                    assert _dart_int(low, env) == want & 0xffffffff, (low, env)
    # The index of an element address is the extended value, as the address is.
    elem = _lift_rows([("add", "x1, x13, w6, sxtw #2"), ("ldur", "w0, [x1, #0xf]"),
                       ("ret", "")])
    assert elem == ["return x13[x6.toSigned(32)];"], elem
    # A shifted `cmn` keeps its shift, and the carry out of the sum reads it as the
    # carry of `adds` does: it printed `?` while the sum was spelled without it.
    from jadart.cfg import _cond_text
    cmn = lambda cc: _cond_text((0, "cmn", "x5, x6, lsl #3", ""), "b." + cc, "#0")
    assert cmn("eq") == "(x5 + (x6 << 3)) == 0"
    assert cmn("hs") == "(x5 + (x6 << 3)) u< x5" and cmn("hi") == "? u> ?"
    assert _cond_text((0, "cmn", "w5, w6, lsl #3", ""), "b.hs", "#0") == (
        "(w5 + (w6 << 3)) u< w5")   # read at 32 bits where it is printed (#370)
    for cc in ("hs", "lo"):
        for _ in range(60):
            env = _w_env(rng)
            assert _reads_371(cmn(cc), env) == _HOLDS_371[cc](
                *_flags_371("cmn", env["x5"], env["x6"] << 3 & mask)), (cc, env)
    # `cmn x5, w6, sxtw` printed `(x5 + x6) < 0`. No spelling for it here: raw.
    for flags in ("cmn", "cmp"):
        body = _lift_rows([(flags, "x5, w6, sxtw"), ("cset", "x0, lt"), ("ret", "")])
        assert body == ["cset x0, lt", "return x0;"], body


def _flags32(kind, a, b):
    """N, Z, C, V as arm64 sets them for 32-bit `a - b` (`cmp`), `a + b` (`cmn`) or
    `a & b` (`tst`)."""
    m = 0xffffffff
    a, b = a & m, b & m
    if kind == "tst":
        r = a & b
        return r >> 31, r == 0, 0, 0
    if kind == "cmp":
        r = (a - b) & m
        return r >> 31, r == 0, a >= b, ((a ^ b) & (a ^ r)) >> 31
    r = (a + b) & m
    return r >> 31, r == 0, (a + b) >> 32, (~(a ^ b) & (a ^ r) & m) >> 31


_HOLDS = {"eq": lambda n, z, c, v: z, "ne": lambda n, z, c, v: not z,
          "hs": lambda n, z, c, v: c, "lo": lambda n, z, c, v: not c,
          "mi": lambda n, z, c, v: n, "pl": lambda n, z, c, v: not n,
          "hi": lambda n, z, c, v: c and not z, "ls": lambda n, z, c, v: not c or z,
          "ge": lambda n, z, c, v: n == v, "lt": lambda n, z, c, v: n != v,
          "gt": lambda n, z, c, v: not z and n == v,
          "le": lambda n, z, c, v: z or n != v}


def test_a_32_bit_comparison_reads_the_low_half_of_its_operands():
    """`cmp w1, #0; cset x0, lt` over a four-byte load printed `x13.field_0x8 < 0`, all
    64 bits of a value the CPU reads 32 of and never true, and `cbz w5` printed `x5 == 0`
    for an x5 of 0x100000000 (#370). A condition on w registers reads the low halves,
    sign-extended for a signed condition and zero-extended for an unsigned one. Every
    condition of `cmp`, `cmn` and `tst`, against a register, an immediate and a shifted
    register, is checked against the flags arm64 defines on random inputs."""
    import random
    cset = lambda rows, cc: _untag_text(list(rows) + [("cset", f"x0, {cc}")])
    load = [("ldur", "w1, [x13, #7]")]
    one = lambda rows, cc: cset(rows, cc)[:-len(" ? 1 : 0")]
    assert one(load + [("cmp", "w1, #0")], "lt") == "x13.field_0x8.toSigned(32) < 0"
    assert one([("cmp", "w5, w6")], "lt") == "x5.toSigned(32) < x6.toSigned(32)"
    assert one([("cmp", "w5, w6")], "lo") == "x5.toUnsigned(32) < x6.toUnsigned(32)"
    assert one([("cmp", "w5, #7")], "eq") == "x5.toUnsigned(32) == 7"
    assert one([("cmp", "w5, #0")], "mi") == "x5.toSigned(32) < 0"
    assert one([("cmp", "w5, w6")], "mi") == "(x5 - x6).toSigned(32) < 0"
    assert one([("cmn", "w5, w6")], "eq") == "(x5 + x6).toUnsigned(32) == 0"
    assert one([("tst", "w5, w6")], "ne") == "(x5 & x6).toUnsigned(32) != 0"
    # What a load of four bytes zero-extended is its own low half, and so is its name.
    assert one(load + [("cmp", "w1, #0")], "eq") == "x13.field_0x8 == 0"
    assert one(load + [("cmp", "w1, #4")], "hi") == "x13.field_0x8 > 4"
    assert one(load + [("cmp", "w1, w6")], "eq") == "x13.field_0x8 == x6.toUnsigned(32)"
    # An eight-byte read of the same field prints the same and is not known to fit.
    assert one([("ldur", "x1, [x13, #7]"), ("cmp", "w1, #0")], "eq") == (
        "x13.field_0x8.toUnsigned(32) == 0")
    # Two references are one object or two: the null register and a pool object are
    # read whole by `==`, and no other condition knows the pool object for one.
    assert one([("cmp", "w5, w22")], "eq") == "x5 == NULL"
    pool = [("ldr", "x16, [x27, #0x120]"), ("cmp", "w5, w16")]
    assert one(pool, "ne") == "x5 != pool_0x120"
    assert one(pool, "lo") == "x5.toUnsigned(32) < pool_0x120.toUnsigned(32)"
    # What a condition chose of `true` and `false` is one of the two objects, and the
    # `?` it is spelled with is not the `?` of a condition the lifter declines.
    chose = [("add", "x16, x22, #0x20"), ("add", "x17, x22, #0x30"), ("cmp", "x5, x6"),
             ("csel", "x1, x16, x17, gt"), ("cmp", "w1, w7")]
    assert one(chose, "eq") == "(x5 > x6 ? true : false) == x7"
    # An equality holds read either way, and reads the way that changes fewer operands.
    assert one([("mov", "x6, #-5"), ("cmp", "w5, w6")], "eq") == "x5.toSigned(32) == -5"
    # A Smi-tagged register is compared as the word it holds, and a class id, 20 bits
    # tagged, needs no truncation. An immediate keeps its spelling.
    assert one([("sbfiz", "x6, x5, #1, #31"), ("cmp", "w6, #0x800")], "lt") == (
        "(x5.toSigned(31) << 1) < 0x800")
    cid = [("ubfx", "x16, x16, #0xc, #0x14"), ("lsl", "x16, x16, #1")]
    assert one(cid + [("cmp", "w16, #0xbc")], "ne") == (
        "(((x16 >> 12) & 0xfffff) << 1) != 0xbc")
    # A branch reads its operand the same way, and one bit of it is that bit.
    arms = [("mov", "x0, #1"), ("ret", ""), ("mov", "x0, #2"), ("ret", "")]
    branch = lambda mn, op: _lift_rows([(mn, f"{op}, #0xc")] + arms)[0]
    assert branch("cbz", "w5") == "if (x5.toUnsigned(32) != 0) {"
    assert branch("cbnz", "w5") == "if (x5.toUnsigned(32) == 0) {"
    assert branch("tbz", "w5, #3") == "if ((x5 >> 3) & 1 != 0) {"
    less = _lift_rows([("cmp", "w5, w6"), ("b.ge", "#0x10")] + arms)[0]
    assert less == "if (x5.toSigned(32) < x6.toSigned(32)) {"

    rng = random.Random(370)
    shift = {"lsl": lambda v, n: v << n, "lsr": lambda v, n: (v & 0xffffffff) >> n,
             "asr": lambda v, n: _sx(v, 32) >> n}
    forms = [("cmp", "w5, w6", None), ("cmn", "w5, w6", None), ("tst", "w5, w6", None),
             ("cmp", "w5, #7", 7), ("cmp", "w5, #0", 0), ("cmn", "w5, #3", 3),
             ("tst", "w5, #0xff00", 0xff00)]
    forms += [("cmp", f"w5, w6, {sh} #{n}", (sh, n))
              for sh in shift for n in (1, 3, 31)]
    told = 0
    for kind, op, right in forms:
        for cc, holds in _HOLDS.items():
            text = cset([(kind, op)], cc)
            if text == "x0":
                # Declined, the `cset` left raw: only where the flags have no spelling,
                # which after an add is hi and ls, the carry and the zero flag at once.
                assert (kind == "tst" and cc not in ("eq", "ne", "mi", "pl")
                        or kind == "cmn" and cc in ("hi", "ls")), (op, cc)
                continue
            told += 1
            assert text.endswith(" ? 1 : 0"), text
            cond = text[:-len(" ? 1 : 0")].replace(">>>", ">>")
            for _ in range(60):
                env = _w_env(rng)
                b = (env["x6"] if right is None else right if isinstance(right, int)
                     else shift[right[0]](env["x6"], right[1]))
                want = bool(holds(*_flags32(kind, env["x5"], b)))
                assert bool(_dart_int(cond, env)) == want, (kind, op, cc, text, env)
    assert told == len(forms) * 12 - 2 * 8 - 2 * 2, told



def test_arithmetic_on_a_smi_tagged_register_reads_the_word_it_holds():
    """`sbfiz x1, x3, #1, #31` leaves x1 holding x3's low 31 bits shifted up one, and
    tier 3 names the register by the value it tags (#290). An instruction that computes
    with the register read that name: `add x0, x1, #2` printed `x3 + 2` where the CPU
    has `(x3.toSigned(31) << 1) + 2`, and so for every arithmetic, logical, shift and
    bitfield instruction, an operand with a shift or an extend, and a condition. A
    32-bit comparison of such a result compared a number the register never held
    (#370). Each reads the tagged word now, a shift right by one still gives the value
    back, and a store still prints the value. Every form is checked against arm64 on
    random inputs, the register past a box-or-tag check on those that take the Smi
    path."""
    import random
    tag = [("sbfiz", "x1, x3, #1, #0x1f")]
    box = tag + [("cmp", "x3, x1, asr #1"), ("b.eq", "#0x10"), ("nop", "")]
    one = lambda rows: _untag_text(tag + rows)
    assert one([("add", "x0, x1, #2")]) == "(x3.toSigned(31) << 1) + 2"
    assert one([("mul", "x0, x1, x4")]) == "(x3.toSigned(31) << 1) * x4"
    assert one([("add", "w0, w1, w4")]) == "((x3.toSigned(31) << 1) + x4).toUnsigned(32)"
    assert one([("asr", "x0, x1, #1")]) == "x3.toSigned(31)"
    assert one([("mov", "x0, x1")]) == "x3"
    assert _untag_text(box + [("add", "x0, x1, #2")]) == "(x3 << 1) + 2"
    assert _untag_text(box + [("asr", "x0, x1, #1")]) == "x3"
    assert one([("mov", "w1, w1"), ("asr", "w0, w1, #1")]) == (
        "x3.toSigned(31).toUnsigned(32)")
    assert one([("mov", "w1, w1"), ("asr", "x0, x1, #1")]) == (
        "(x3.toSigned(31) << 1).toUnsigned(32) >> 1")
    # The tagged word is its own low half sign-extended, so `sxtw` leaves it tagged.
    assert one([("sxtw", "x0, w1"), ("asr", "x0, x0, #1")]) == "x3.toSigned(31)"
    assert _untag_text(box + [("sxtw", "x1, w1"), ("add", "x0, x4, x1, asr #1")]) == (
        "x4 + x3")
    # Bit 0 of a boxed register says which path of the box-or-tag check filled it, the
    # Mint where the value does not fit in 31 bits; any other bit is a bit of the word.
    arms = [("mov", "x0, #1"), ("ret", ""), ("mov", "x0, #2"), ("ret", "")]
    assert _lift_rows(box + [("tbnz", "w1, #0, #0x1c")] + arms)[0] == (
        "if (x3 == x3.toSigned(31)) {")
    assert _lift_rows(box + [("tbz", "w1, #0, #0x1c")] + arms)[0] == (
        "if (x3 != x3.toSigned(31)) {")
    assert _lift_rows(box + [("tbz", "w1, #4, #0x1c")] + arms)[0] == (
        "if (((x3 << 1) >> 4) & 1 != 0) {")
    assert _lift_rows(tag + [("tbz", "w1, #4, #0x10")] + arms)[0] == (
        "if (((x3.toSigned(31) << 1) >> 4) & 1 != 0) {")
    # A 64-bit unsigned condition reads the word with the unsigned operators (#371).
    # The signed ones fail for the half of the words that are negative.
    over = [("mov", "w2, #0x800"), ("cmp", "x1, x2")]
    assert one(over + [("cset", "x0, hi")]) == "(x3.toSigned(31) << 1) u> 0x800 ? 1 : 0"
    assert _lift_rows(tag + over + [("b.ls", "#0x18")] + arms)[0] == (
        "if ((x3.toSigned(31) << 1) u> 0x800) {")
    assert one(over + [("cset", "x0, gt")]) == "(x3.toSigned(31) << 1) > 0x800 ? 1 : 0"
    assert one([("adds", "x7, x1, x6"), ("cset", "x0, hs")]) == (
        "((x3.toSigned(31) << 1) + x6) u< (x3.toSigned(31) << 1) ? 1 : 0")
    rng = random.Random(371)
    for setter, op in (("cmp", "x1, x6"), ("cmp", "x6, x1"), ("adds", "x7, x1, x6")):
        for cc, holds in _HOLDS_371.items():
            text = one([(setter, op), ("cset", "x0, " + cc)])
            if text == "x0":
                assert setter == "adds" and cc in ("hi", "ls"), (setter, cc)
                continue
            lhs, rel, rhs = re.fullmatch(r"(.+) (u[<>]=?) (.+) \? 1 : 0", text).groups()
            for _ in range(60):
                env = _w_env(rng, ("x3", "x6"))
                word = _sx(env["x3"], 31) << 1 & (1 << 64) - 1
                a, b = (env["x6"], word) if op == "x6, x1" else (word, env["x6"])
                got = {"u<": int.__lt__, "u<=": int.__le__, "u>": int.__gt__,
                       "u>=": int.__ge__}[rel](_dart_int(lhs, env), _dart_int(rhs, env))
                assert got == holds(*_flags_371(setter, a, b)), (text, env)
    # The three a 32-bit comparison made wrong where two errors had cancelled.
    twice = [("lsl", "w1, w1, #1"), ("mov", "x2, #-2")]
    assert one(twice + [("cmp", "w1, w2"), ("cset", "x0, eq")]) == (
        "(x3.toSigned(31) << 1 << 1).toSigned(32) == -2 ? 1 : 0")
    assert one(twice + [("cmn", "w1, #2"), ("cset", "x0, eq")]) == (
        "((x3.toSigned(31) << 1 << 1) + 2).toUnsigned(32) == 0 ? 1 : 0")

    mask, m32 = (1 << 64) - 1, 0xffffffff
    s32, s64 = (lambda v: _sx(v, 32)), (lambda v: _sx(v, 64))
    forms = {                                   # w is the tagged word, y is x4
        "add x0, x1, #2": lambda w, y: w + 2,
        "add x0, x4, x1": lambda w, y: y + w,
        "add x0, x4, x1, lsl #2": lambda w, y: y + (w << 2),
        "add x0, x4, w1, sxtw": lambda w, y: y + s32(w),
        "add x0, x4, w1, uxtw #2": lambda w, y: y + ((w & m32) << 2),
        "sub x0, x1, x4": lambda w, y: w - y,
        "sub x0, x4, x1": lambda w, y: y - w,
        "neg x0, x1": lambda w, y: -w,
        "mul x0, x4, x1": lambda w, y: y * w,
        "madd x0, x1, x4, x4": lambda w, y: y + w * y,
        "and x0, x1, #0xff": lambda w, y: w & 0xff,
        "orr x0, x1, x4": lambda w, y: w | y,
        "eor x0, x4, x1": lambda w, y: y ^ w,
        "bic x0, x4, x1": lambda w, y: y & ~w,
        "mvn x0, x1": lambda w, y: ~w,
        "lsl x0, x1, #2": lambda w, y: w << 2,
        "asr x0, x1, #2": lambda w, y: s64(w) >> 2,
        "asr x0, x1, #1": lambda w, y: s64(w) >> 1,
        "ubfx x0, x1, #2, #8": lambda w, y: (w >> 2) & 0xff,
        "sbfx x0, x1, #2, #8": lambda w, y: _sx(w >> 2, 8),
        "sbfiz x0, x1, #2, #20": lambda w, y: _sx(w, 20) << 2,
        "ubfiz x0, x1, #2, #20": lambda w, y: (w & 0xfffff) << 2,
        "uxtw x0, w1": lambda w, y: w & m32,
        "add w0, w1, #2": lambda w, y: (w + 2) & m32,
        "sub w0, w4, w1": lambda w, y: (y - w) & m32,
        "lsl w0, w1, #1": lambda w, y: (w << 1) & m32,
        "lsr w0, w1, #1": lambda w, y: (w & m32) >> 1,
        "asr w0, w1, #3": lambda w, y: (s32(w) >> 3) & m32,
        "and w0, w1, w4": lambda w, y: w & y & m32,
        "orr w0, w4, w1, lsr #3": lambda w, y: (y | (w & m32) >> 3) & m32,
        "mul w0, w1, w4": lambda w, y: w * y & m32,
        "cmp x1, #8; cset x0, lt": lambda w, y: s64(w) < 8,
        "cmp x1, x4; cset x0, eq": lambda w, y: w == y,
        "tst x1, #0x10; cset x0, ne": lambda w, y: w & 0x10 != 0,
        "cmp w1, #8; cset x0, lt": lambda w, y: s32(w) < 8,
        "cmp w1, w4; cset x0, eq": lambda w, y: (w ^ y) & m32 == 0,
        "cmp w1, w4; cset x0, hi": lambda w, y: w & m32 > y & m32,
        "cmn w1, #2; cset x0, eq": lambda w, y: (w + 2) & m32 == 0,
        "lsl w1, w1, #1; mov x2, #-2; cmp w1, w2; cset x0, eq":
            lambda w, y: (w << 1) & m32 == 0xfffffffe,
        "lsl w1, w1, #1; mov x2, #-2; cmp w1, w2; cset x0, ne":
            lambda w, y: (w << 1) & m32 != 0xfffffffe,
        "lsl w1, w1, #1; cmn w1, #2; cset x0, eq":
            lambda w, y: ((w << 1) + 2) & m32 == 0,
        "lsl w1, w1, #1; cmp w1, #4; cset x0, lt": lambda w, y: s32(w << 1) < 4,
    }
    rng = random.Random(3701)
    edge = (0x3fffffff, 0x40000000, 0x7fffffff, 0x80000000, (1 << 64) - 1, 1 << 63)
    for head, fits in ((tag, False), (box, True)):
        for form, machine in forms.items():
            rows = [tuple(p.strip().split(" ", 1)) for p in form.split(";")]
            text = _untag_text(head + rows).replace(">>>", ">>")
            cond = text.endswith(" ? 1 : 0")
            text = text[:-len(" ? 1 : 0")] if cond else text
            for _ in range(60):
                env = {r: rng.choice((rng.getrandbits(64), rng.getrandbits(32),
                                      rng.getrandbits(30), mask - rng.getrandbits(30),
                                      rng.choice(edge))) for r in ("x3", "x4")}
                if fits and _sx(env["x3"], 31) & mask != env["x3"]:
                    continue                    # the Mint path, which the strip cuts
                want = machine((_sx(env["x3"], 31) << 1) & mask, env["x4"])
                got = _dart_int(text, env)
                assert (bool(got) == want if cond else got == want & mask), (
                    form, text, {r: hex(v) for r, v in env.items()})


def test_a_32_bit_equality_reads_whole_only_what_every_path_proves_a_reference():
    """Three operands of a 32-bit comparison that printed whole and are read by half
    (#370). The null register was known by its name, and holds null only until the
    body writes it: `mov x22, x5; cmp w1, w22` printed `x1 == x5`. An equality with
    null was the identity test whatever the other side, and a number the body computed
    is no reference: `add x1, x22, x5, lsl #32; cmp w1, w22` is equal for every x5 and
    printed `(NULL + (x5 << 32)) == NULL`. And a four-byte load was known for its own
    low half past a join with an eight-byte load of the same field, which prints the
    same: `x13.field_0x8 < x2.toUnsigned(32)`."""
    import random
    one = lambda rows, cc: _untag_text(list(rows) + [("cset", f"x0, {cc}")])[:-len(
        " ? 1 : 0")]
    moved = one([("mov", "x22, x5"), ("cmp", "w1, w22")], "eq")
    assert moved == "x1.toUnsigned(32) == x5.toUnsigned(32)"
    summed = one([("add", "x1, x22, x5, lsl #32"), ("cmp", "w1, w22")], "eq")
    assert summed == "(NULL + (x5 << 32)).toUnsigned(32) == NULL.toUnsigned(32)"
    assert one([("add", "x1, x5, #1"), ("cmp", "w1, w22")], "ne") == (
        "(x5 + 1).toUnsigned(32) != NULL.toUnsigned(32)")
    pool = [("ldr", "x16, [x27, #0x120]"), ("add", "x1, x5, #1"), ("cmp", "w1, w16")]
    assert one(pool, "ne") == "(x5 + 1).toUnsigned(32) != pool_0x120.toUnsigned(32)"
    rng = random.Random(3702)
    for _ in range(200):
        env = _w_env(rng, ("x1", "x5"))
        env["NULL"] = rng.getrandbits(64)
        assert bool(_dart_int(moved, env)) == ((env["x1"] ^ env["x5"]) & 0xffffffff == 0)
        assert _dart_int(summed, env) == 1, env
    # What may be a reference is still compared whole with one: a register, a field
    # of four bytes or of eight, a frame slot.
    assert one([("cmp", "w1, w22")], "eq") == "x1 == NULL"
    for load in ("ldur w1, [x13, #7]", "ldur x1, [x13, #7]"):
        assert one([tuple(load.split(" ", 1)), ("cmp", "w1, w22")], "ne") == (
            "x13.field_0x8 != NULL")

    def joined(first, second):
        return _lift_rows([("cbz", "x3, #0xc"), ("ldur", first), ("b", "#0x10"),
                           ("ldur", second), ("cmp", "w1, w2"), ("cset", "x0, lo"),
                           ("ret", "")])[-1]
    assert joined("w1, [x13, #7]", "x1, [x13, #7]") == (
        "return x13.field_0x8.toUnsigned(32) < x2.toUnsigned(32) ? 1 : 0;")
    assert joined("x1, [x13, #7]", "w1, [x13, #7]") == (
        "return x13.field_0x8.toUnsigned(32) < x2.toUnsigned(32) ? 1 : 0;")
    assert joined("w1, [x13, #7]", "w1, [x13, #7]") == (
        "return x13.field_0x8 < x2.toUnsigned(32) ? 1 : 0;")


def test_a_shifted_operand_of_a_32_bit_instruction_is_shifted_at_32_bits():
    """`add w0, w5, w6, asr #3` shifts the low half of x6, sign-extended. Tier 3 printed
    `(x5 + (x6 >> 3)).toUnsigned(32)`, a shift of all 64 bits that brings three bits of
    the top half down into the result, and so for `lsr` (#373). A left shift only moves
    bits up and out, and stays as it was. Every shift on the 32-bit forms of `add`,
    `sub`, `and`, `orr`, `eor` and `bic` is checked against arm64 on random inputs.
    `tst` dropped the shift of its operand at either width, `(x5 & x6) == 0` for
    `tst x5, x6, lsl #3`."""
    import random
    one = lambda mn, op: _untag_text([(mn, op)])
    assert one("add", "w0, w5, w6, asr #3") == (
        "(x5 + (x6.toSigned(32) >> 3)).toUnsigned(32)")
    assert one("add", "w0, w5, w6, lsr #3") == (
        "(x5 + (x6.toUnsigned(32) >>> 3)).toUnsigned(32)")
    assert one("add", "w0, w5, w6, lsl #3") == "(x5 + (x6 << 3)).toUnsigned(32)"
    assert one("eor", "w0, w5, w5, asr #31") == (
        "(x5 ^ x5.toSigned(32) >> 31).toUnsigned(32)")
    # The 64-bit forms shift the register whole, as they did.
    assert one("add", "x0, x5, x6, asr #3") == "x5 + (x6 >> 3)"
    assert one("add", "x0, x5, x6, lsr #3") == "x5 + (x6 >>> 3)"
    # No spelling for a rotate: the instruction stays raw.
    raw = _lift_rows([("eor", "w0, w5, w6, ror #3"), ("ret", "")])
    assert raw[0] == "eor w0, w5, w6, ror #3", raw

    rng = random.Random(373)
    m32 = 0xffffffff
    shift = {"lsl": lambda v, n: v << n, "lsr": lambda v, n: (v & m32) >> n,
             "asr": lambda v, n: _sx(v, 32) >> n}
    insn = {"add": lambda a, b: a + b, "sub": lambda a, b: a - b,
            "and": lambda a, b: a & b, "orr": lambda a, b: a | b,
            "eor": lambda a, b: a ^ b, "bic": lambda a, b: a & ~b}
    for mn, fn in insn.items():
        for sh, shifted in shift.items():
            for n in (1, 3, 17, 31):
                text = one(mn, f"w0, w5, w6, {sh} #{n}").replace(">>>", ">>")
                for _ in range(40):
                    env = _w_env(rng)
                    want = fn(env["x5"], shifted(env["x6"], n)) & m32
                    assert _dart_int(text, env) == want, (mn, sh, n, text, env)

    cset = lambda rows, cc: _untag_text(list(rows) + [("cset", f"x0, {cc}")])
    assert cset([("tst", "x5, x6, lsl #3")], "eq") == "(x5 & (x6 << 3)) == 0 ? 1 : 0"
    assert cset([("tst", "w5, w6, lsr #3")], "ne") == (
        "(x5 & (x6.toUnsigned(32) >>> 3)) != 0 ? 1 : 0")
    for sh, shifted in shift.items():
        for cc, holds in _HOLDS.items():
            if cc not in ("eq", "ne", "mi", "pl"):
                continue
            text = cset([("tst", f"w5, w6, {sh} #3")], cc)
            assert text.endswith(" ? 1 : 0"), text
            cond = text[:-len(" ? 1 : 0")].replace(">>>", ">>")
            for _ in range(60):
                env = _w_env(rng)
                want = bool(holds(*_flags32("tst", env["x5"], shifted(env["x6"], 3))))
                assert bool(_dart_int(cond, env)) == want, (sh, cc, text, env)


def test_a_signed_load_into_a_w_register_is_extended_to_32_bits():
    """`ldursh w0, [x13, #7]` sign-extends two bytes to 32 bits and clears the top half
    of x0. Tier 3 printed `x13.field2_0x8 << 48 >> 48`, the extension to 64 bits, which
    is negative where the register holds a positive value (#374). The same load into an
    x register is extended to 64, as it was. A frame slot and an element read the same
    way, and a 32-bit consumer reads the value before the truncation."""
    ret = lambda rows: _lift_rows(list(rows) + [("ret", "")])[-1]
    assert ret([("ldursh", "w0, [x13, #7]")]) == (
        "return (x13.field2_0x8 << 48 >> 48).toUnsigned(32);")
    assert ret([("ldursb", "w0, [x13, #7]")]) == (
        "return (x13.field1_0x8 << 56 >> 56).toUnsigned(32);")
    assert ret([("ldrsb", "w0, [x13, #8]")]) == (
        "return (x13.field1_0x9 << 56 >> 56).toUnsigned(32);")
    assert ret([("ldursh", "x0, [x13, #7]")]) == "return x13.field2_0x8 << 48 >> 48;"
    assert ret([("ldursw", "x0, [x13, #7]")]) == "return x13.field_0x8 << 32 >> 32;"
    slot = [("sturh", "w5, [x29, #-8]"), ("ldursh", "w0, [x29, #-8]")]
    assert ret(slot) == "return (x5 << 48 >> 48).toUnsigned(32);"
    assert ret([("ldrsh", "w0, [x9, x7]")]) == (
        "return (x9[x7] << 48 >> 48).toUnsigned(32);")
    # What the w register holds, read by a 64-bit add, a 32-bit one and a compare.
    load = [("ldursh", "w1, [x13, #7]")]
    assert ret(load + [("add", "x0, x1, x5")]) == (
        "return (x13.field2_0x8 << 48 >> 48).toUnsigned(32) + x5;")
    assert ret(load + [("add", "w0, w1, w5")]) == (
        "return ((x13.field2_0x8 << 48 >> 48) + x5).toUnsigned(32);")
    assert ret(load + [("cmp", "w1, #0"), ("cset", "x0, lt")]) == (
        "return (x13.field2_0x8 << 48 >> 48) < 0 ? 1 : 0;")
    # The value printed is the one the register holds. `<< 48 >> 48` on Dart's 64-bit
    # ints is `.toSigned(16)`, which `_dart_int` has and a wrapping shift it has not.
    text = ret([("ldursh", "w0, [x13, #7]")])[len("return "):-1]
    text = text.replace("x13.field2_0x8 << 48 >> 48", "f.toSigned(16)")
    for half in (0, 1, 0x7fff, 0x8000, 0xffff, 0x1234, 0xfedc):
        assert _dart_int(text, {"f": half}) == _sx(half, 16) & 0xffffffff, (text, half)


def test_a_join_past_a_raw_write_names_what_each_way_in_left():
    # #368. `umulh` prints as the instruction, and the register it wrote reads bare after
    # it. An arm then wrote the register without printing a line, the join dropped it to
    # bare, the empty `if` went, and `return x3;` under the raw line said the product on
    # the way that had put 7 there: 38 of 40 entry states disagreed with the CPU.
    then = [("umulh", "x3, x5, x6"), ("cbz", "x1, #0xc"), ("mov", "x3, #7"),
            ("mov", "x0, x3"), ("ret", "")]
    assert _lift_rows(then) == [
        "umulh x3, x5, x6", "var t0 = x3;", "if (x1 != 0) {", "t0 = 7;", "}", "return t0;"]
    # Both arms write it, and neither value is the raw line's.
    both = [("umulh", "x3, x5, x6"), ("cbz", "x1, #0x10"), ("mov", "x3, #7"),
            ("b", "#0x14"), ("mov", "x3, #9"), ("mov", "x0, x3"), ("ret", "")]
    assert _lift_rows(both) == [
        "umulh x3, x5, x6", "var t0;", "if (x1 != 0) {", "t0 = 7;", "} else {",
        "t0 = 9;", "}", "return t0;"]
    # A raw line that reads the register after the join says what it holds there.
    raw_reader = [("udiv", "x3, x5, x6"), ("cbz", "x1, #0xc"), ("mov", "x3, x2"),
                  ("clz", "x0, x3"), ("ret", "")]
    assert _lift_rows(raw_reader) == [
        "udiv x3, x5, x6", "var t0 = x3;", "if (x1 != 0) {", "t0 = x2;", "}",
        "clz x0, x3   // x3 holds t0", "return x0;"]
    # Every instruction the census found printed raw on real code, and a few more, by
    # one road. The join of a register nothing printed a write to stays bare: that is
    # the value on entry, a gap and not a claim.
    for mn, ops in (("smulh", "x3, x5, x6"), ("fcvtms", "x3, d0"), ("fcvtps", "x3, d0"),
                    ("fcvtms", "w3, d0"), ("ldar", "x3, [x9]"), ("ldar", "w3, [x9]"),
                    ("adr", "x3, #0x40"), ("csel", "x3, x5, x6, vs"),
                    ("csinc", "x3, x5, x6, vs"), ("adc", "x3, x5, x6"),
                    ("adcs", "x3, x5, x6"), ("sbcs", "x3, x5, x6"), ("udiv", "w3, w5, w6"),
                    ("clz", "x3, x5"), ("smull", "x3, w5, w6"), ("rbit", "x3, x5"),
                    ("extr", "x3, x5, x6, #3")):
        got = _lift_rows([(mn, ops)] + then[1:])
        assert got[0] == f"{mn} {ops}" and got[1:] == [
            "var t0 = x3;", "if (x1 != 0) {", "t0 = 7;", "}", "return t0;"], (mn, got)
    assert _lift_rows([("cbz", "x1, #0x8"), ("mov", "x3, #7"), ("mov", "x0, x3"),
                       ("ret", "")]) == ["return x3;"]


def test_joins_past_raw_writes_cost_the_same_per_row_at_any_length():
    # A guard on the cost, counted and not timed: naming these joins adds no walk that
    # grows with them, so four times the rows is four times the blocks lifted. Each unit
    # is a raw write, an arm that writes over it, a join and a read; every fourth is a
    # join the structurer reaches by a goto.
    import jadart.expr as expr
    real, calls = expr.Lifter._lift_block, [0]

    def counted(self, addr, st):
        calls[0] += 1
        return real(self, addr, st)

    def per_row(n):
        rows = []
        for i in range(n):
            at = len(rows) * 4
            if i % 4 == 3:
                rows += [("clz", "x3, x5"), ("cbz", f"x1, #{at + 0x10:#x}"),
                         ("mov", "x3, x2"), ("cbz", f"x2, #{at + 0x14:#x}"),
                         ("add", "x4, x4, #1"), ("stur", "x3, [x11, #15]")]
            else:
                rows += [("umulh", "x3, x5, x6"), ("cbz", f"x1, #{at + 0xc:#x}"),
                         ("mov", "x3, #7"), ("stur", "x3, [x11, #15]")]
        calls[0] = 0
        _lift_rows(rows + [("ret", "")])
        return calls[0] / len(rows)
    expr.Lifter._lift_block = counted
    try:
        small, large = per_row(100), per_row(400)
        assert 0 < large <= small * 1.25 + 1, (small, large)
    finally:
        expr.Lifter._lift_block = real


def test_a_store_names_a_live_read_it_writes_part_of_from_another_offset():
    """`ldur x1, [x13, #7]; stur w2, [x13, #11]; mov x0, x1` printed `x13.field_0xc =
    x2;` and then `return x13.field_0x8;`: the read took eight bytes at offset 8, the
    store wrote four of them at 0xc, and only a read at the store's own offset was
    named before it (#385). A store now names each live field read that has a byte
    of what it writes, whatever the two offsets and widths, through any base, and a
    read with no byte of it stays inline."""
    lift = _lift_329
    assert lift(("ldur", "x1, [x13, #7]"), ("stur", "w2, [x13, #11]"),
                ("mov", "x0, x1")) == ["var t0 = x13.field_0x8;", "x13.field_0xc = x2;",
                                       "return t0;"]
    load = {1: ("ldurb", "w1"), 2: ("ldurh", "w1"), 4: ("ldur", "w1"), 8: ("ldur", "x1")}
    store = {1: ("sturb", "w2"), 2: ("sturh", "w2"), 4: ("stur", "w2"),
             8: ("stur", "x2")}
    seen = set()
    for rw, (ld, r) in load.items():
        for sw, (st, v) in store.items():
            for so in range(0x10 - 8, 0x10 + 9):
                for base in ("x13", "x12"):
                    got = lift((ld, f"{r}, [x13, #0xf]"),
                               (st, f"{v}, [{base}, #{so - 1}]"), ("mov", "x0, x1"))
                    shared = so < 0x10 + rw and 0x10 < so + sw
                    assert (got[0].startswith("var t0 = x13.field") and len(got) == 3
                            and got[2] == "return t0;") if shared else (
                        len(got) == 2 and got[1].startswith("return x13.field")), (
                        rw, sw, so, base, got)
                    seen.add(shared)
    assert seen == {True, False}
    # A chain, a value computed from the read, and the word under a pair's second.
    assert lift(("ldur", "x9, [x13, #7]"), ("ldur", "x1, [x9, #0xf]"),
                ("ldur", "x10, [x12, #7]"), ("sturb", "w2, [x10, #0x16]"),
                ("mov", "x0, x1")) == ["var t0 = x13.field_0x8.field_0x10;",
                                       "x12.field_0x8.field1_0x17 = x2;", "return t0;"]
    assert lift(("ldur", "x1, [x13, #0xf]"), ("add", "x3, x1, x5"),
                ("stur", "w2, [x13, #0x13]"), ("mov", "x0, x3"))[0] == (
        "var t0 = x13.field_0x10 + x5;")
    assert lift(("ldur", "x1, [x13, #0x1c]"), ("stp", "x2, x5, [x13, #0x10]"),
                ("mov", "x0, x1")) == ["x13.field_0x11 = x2;", "var t0 = x13.field_0x1d;",
                                       "x13.field_0x19 = x5;", "return t0;"]
    # Sixteen bytes written over a word in their top half, and read under a byte.
    assert lift(("ldur", "w1, [x13, #0x13]"), ("stur", "q0, [x13, #7]"),
                ("mov", "x0, x1"))[0] == "var t0 = x13.field_0x14;"
    assert lift(("ldur", "q1, [x13, #7]"), ("sturb", "w2, [x13, #0x16]"),
                ("stur", "q1, [x12, #7]"))[0] == "var t0 = x13.field16_0x8;"
    # The thread is no object: its own fields by their offsets, and no object's.
    assert lift(("ldr", "x1, [x26, #0x40]"), ("str", "w2, [x26, #0x44]"),
                ("mov", "x0, x1")) == ["var t0 = THR.field_0x40;",
                                       "THR.field_0x44 = x2;", "return t0;"]
    assert lift(("ldur", "x1, [x13, #0x3f]"), ("str", "w2, [x26, #0x44]"),
                ("mov", "x0, x1")) == ["THR.field_0x44 = x2;", "return x13.field_0x40;"]
    # Nor is the pool, the frame, or an untagged role's own address, DISPATCH or HEAP,
    # in a register of its own or copied: a store into one names what was read off
    # it and no object's field.
    read = ("ldur", "x1, [x13, #0xf]")
    for into in ([("stur", "w2, [x21, #0x13]")], [("stur", "w2, [x28, #0x13]")],
                 [("stur", "w2, [x27, #0x13]")],
                 [("mov", "x9, x21"), ("stur", "w2, [x9, #0x13]")],
                 [("mov", "x9, x29"), ("stur", "w2, [x9, #0x13]")],
                 [("sub", "x9, x29, #0x40"), ("stur", "w2, [x9, #0x13]")]):
        got = lift(read, *into, ("mov", "x0, x1"))
        assert len(got) == 2 and got[1] == "return x13.field_0x10;", (into, got)
    assert lift(("ldur", "x1, [x21, #0x10]"), ("stur", "w2, [x21, #0x14]"),
                ("mov", "x0, x1")) == ["var t0 = DISPATCH.field_0x10;",
                                       "DISPATCH.field_0x14 = x2;", "return t0;"]
    # A pointer READ OUT of one of them is to whatever object that is, and a store
    # through it names the read, as does one through an address made from a role.
    for ptr, tgt in ((("ldr", "x9, [x21, #0x20]"), "DISPATCH.field_0x20"),
                     (("ldr", "x9, [x28, #0x20]"), "HEAP.field_0x20"),
                     (("ldr", "x9, [x26, #0x20]"), "THR.field_0x20"),
                     (("ldr", "x9, [x27, #0x20]"), "pool_0x20"),
                     (("add", "x9, x21, #8"), "(DISPATCH + 8)")):
        assert lift(ptr, read, ("stur", "w2, [x9, #0x13]"), ("mov", "x0, x1")) == [
            "var t0 = x13.field_0x10;", tgt + ".field_0x14 = x2;", "return t0;"], ptr
    assert lift(("ldr", "x9, [x29, #0x20]"), read, ("stur", "w2, [x9, #0x13]"),
                ("mov", "x0, x1")) == ["var t0 = FP.field_0x21;",
                                       "var t1 = x13.field_0x10;",
                                       "t0.field_0x14 = x2;", "return t1;"]
    # A recovered name is the word at its offset: eight bytes where the body read
    # eight there, and four where it read four.
    from jadart.expr import lift_function

    def named(*rows):
        ann = [(i * 4, mn, op, "") for i, (mn, op) in enumerate([*rows, ("ret", "")])]
        return [ln.strip() for ln in lift_function(ann, receiver={"x1": "this"},
                                                   fields={8: "balance"})]
    assert named(("ldur", "x3, [x1, #7]"), ("stur", "w2, [x4, #11]"),
                 ("mov", "x0, x3")) == ["var t0 = this.balance;", "x4.field_0xc = x2;",
                                        "return t0;"]
    assert named(("ldur", "w3, [x1, #7]"), ("stur", "w2, [x4, #11]"),
                 ("mov", "x0, x3")) == ["x4.field_0xc = x2;", "return this.balance;"]


def test_a_comparison_still_to_be_read_is_named_before_a_store_that_may_write_it():
    """`ldur x4, [x13, #0x17]; add x16, x13, x8, lsl #3; cmp x4, x2; stur x1, [x16,
    #0x17]; cset x0, eq` printed `x13[x8] = x1;` and then `return x13.field_0x18 == x2
    ? 1 : 0;`: x4 is dead after the `cmp`, so the store named nothing, and the
    comparison was printed under it from the text of its operand, which reads the word
    the store wrote where x8 is 0 (#386). The operands of a comparison something still
    reads are asked what a live register is asked, by every store."""
    lift = _lift_329
    ld, el = ("ldur", "x4, [x13, #0x17]"), ("add", "x16, x13, x8, lsl #3")
    assert lift(ld, el, ("cmp", "x4, x2"), ("stur", "x1, [x16, #0x17]"),
                ("cset", "x0, eq")) == ["var t0 = x13.field_0x18;", "x13[x8] = x1;",
                                        "return t0 == x2 ? 1 : 0;"]
    # Each instruction that leaves a comparison, each kind of store, each reader.
    sets = {"cmp x4, x2": "t0 {} x2", "cmp x2, x4": "x2 {} t0",
            "cmn x4, x2": "(t0 + x2) {} 0", "tst x4, #0xff": "(t0 & 0xff) {} 0",
            "subs x3, x4, x2": "t0 {} x2", "adds x3, x4, x2": "(t0 + x2) {} 0",
            "ands x3, x4, x2": "(t0 & x2) {} 0"}
    stores = {"stur x1, [x13, #0x17]": "x13.field_0x18 = x1;",
              "stur x1, [x12, #0x17]": "x12.field_0x18 = x1;",
              "sturb w1, [x12, #0x1a]": "x12.field1_0x1b = x1;",
              "stur w1, [x12, #0x1b]": "x12.field_0x1c = x1;",
              "stlr x1, [x20]": "stlr x1, [x20]"}
    reads = {"cset x0, eq": "return {} ? 1 : 0;",
             "csel x0, x7, x5, eq": "return {} ? x7 : x5;",
             "csinc x0, x7, x5, eq": "return {} ? x7 : x5 + 1;"}
    for flags, cond in sets.items():
        for store, line in stores.items():
            for read, ret in reads.items():
                got = lift(ld, *(tuple(x.split(" ", 1)) for x in (flags, store, read)))
                assert got == ["var t0 = x13.field_0x18;", line,
                               ret.format(cond.format("=="))], (flags, store, got)
    # Two operands that read memory are two names, in the order of the registers.
    assert lift(ld, ("ldur", "x6, [x13, #0x1f]"), ("cmp", "x6, x4"), el,
                ("stur", "x1, [x16, #0x17]"), ("cset", "x0, lt")) == [
        "var t0 = x13.field_0x18;", "var t1 = x13.field_0x20;", "x13[x8] = x1;",
        "return t1 < t0 ? 1 : 0;"]
    # A register that is live as well has the one name, and a 32-bit view keeps it.
    assert lift(ld, ("cmp", "x4, x2"), ("stur", "x1, [x12, #0x17]"), ("cset", "x3, eq"),
                ("add", "x0, x3, x4")) == [
        "var t0 = x13.field_0x18;", "x12.field_0x18 = x1;",
        "return (t0 == x2 ? 1 : 0) + t0;"]
    # Read in the block the comparison is handed to, with the store on either side
    # of the edge.
    assert _lift_rows([ld, ("cmp", "x4, x2"), ("stur", "x1, [x12, #0x17]"),
                       ("b", "#0x10"), ("cset", "x0, eq"), ("ret", "")]) == [
        "var t0 = x13.field_0x18;", "x12.field_0x18 = x1;", "return t0 == x2 ? 1 : 0;"]
    assert _lift_rows([ld, ("cmp", "x4, x2"), ("b.lt", "#0x14"), ("mov", "x0, #9"),
                       ("ret", ""), ("stur", "x1, [x12, #0x17]"), ("cset", "x0, eq"),
                       ("ret", "")]) == [
        "if (x13.field_0x18 >= x2) {", "return 9;", "} else {",
        "var t0 = x13.field_0x18;", "x12.field_0x18 = x1;", "return t0 == x2 ? 1 : 0;",
        "}"]
    # Nothing is named where nothing reads the comparison after the store, where the
    # flags are set again before they are read, or where the store has no byte of
    # what was compared.
    assert lift(ld, ("cmp", "x4, x2"), ("stur", "x1, [x12, #0x17]"),
                ("mov", "x0, x5")) == ["x12.field_0x18 = x1;", "return x5;"]
    assert lift(ld, ("cmp", "x4, x2"), ("stur", "x1, [x12, #0x17]"), ("cmp", "x5, x6"),
                ("cset", "x0, eq")) == ["x12.field_0x18 = x1;",
                                        "return x5 == x6 ? 1 : 0;"]
    assert lift(ld, ("cmp", "x4, x2"), ("stur", "x1, [x12, #0x27]"),
                ("cset", "x0, eq")) == ["x12.field_0x28 = x1;",
                                        "return x13.field_0x18 == x2 ? 1 : 0;"]
    assert lift(ld, ("cmp", "x4, x2"), ("stur", "w1, [x12, #0x1f]"),
                ("cset", "x0, eq")) == ["x12.field_0x20 = x1;",
                                        "return x13.field_0x18 == x2 ? 1 : 0;"]


def test_an_element_off_a_computed_base_is_the_access_at_a_computed_address():
    """`ldur x4, [x13, #7]; sub x9, x13, #0x20; add x16, x9, x8, lsl #3; stur x1, [x16,
    #0x17]; mov x0, x4` printed `(x13 - 32)[x8] = x1;` and then `return
    x13.field_0x8;`: the store is to `x13.field_0x8` where x8 is 2, and it was taken
    for an element of an object at `x13 - 32`, whose elements start at its data
    offset and so reach no field below it (#387). An element off a base the rows
    computed keeps its spelling and is the access at a computed address (#341): a
    store names every live read of the heap, and a read is named before any store to
    the heap. A base that is an object pointer is as it was."""
    lift = _lift_329
    ld, el = ("ldur", "x4, [x13, #7]"), ("add", "x16, x9, x8, lsl #3")
    st, ret = ("stur", "x1, [x16, #0x17]"), ("mov", "x0, x4")
    assert lift(ld, ("sub", "x9, x13, #0x20"), el, st, ret) == [
        "var t0 = x13.field_0x8;", "(x13 - 32)[x8] = x1;", "return t0;"]
    # A constant added, two taken off, a copy, an unshifted index, and the header of
    # an object read through another register.
    for made, text in (((("add", "x9, x13, #8"),), "(x13 + 8)[x8]"),
                       ((("sub", "x9, x13, #0x10"), ("sub", "x9, x9, #0x10")),
                        "(x13 - 16 - 16)[x8]"),
                       ((("sub", "x10, x13, #0x20"), ("mov", "x9, x10")),
                        "(x13 - 32)[x8]")):
        assert lift(ld, *made, el, st, ret) == [
            "var t0 = x13.field_0x8;", text + " = x1;", "return t0;"], made
    assert lift(ld, ("sub", "x9, x13, #0x20"), ("add", "x16, x9, x8"), st, ret) == [
        "var t0 = x13.field_0x8;", "(x13 - 32)[x8] = x1;", "return t0;"]
    assert lift(("ldur", "x4, [x12, #-1]"), ("sub", "x9, x13, #0x20"), el, st, ret) == [
        "var t0 = x12.tags;", "(x13 - 32)[x8] = x1;", "return t0;"]
    # Computed on one way in only: the walk has lost the value, and the rows say.
    assert lift(ld, ("mov", "x9, x13"), ("cbz", "x5, #0x10"), ("sub", "x9, x9, #0x20"),
                el, st, ret) == [
        "var t0 = x13;", "if (x5 != 0) {", "t0 = x13 - 32;", "}",
        "var t1 = x13.field_0x8;", "t0[x8] = x1;", "return t1;"]
    # Read through such a base, the element is named before a store to any field,
    # and not before a store into the thread.
    rd = (("sub", "x9, x13, #0x20"), el, ("ldur", "x4, [x16, #0x17]"))
    assert lift(*rd, ("stur", "x1, [x13, #7]"), ret) == [
        "var t0 = (x13 - 32)[x8];", "x13.field_0x8 = x1;", "return t0;"]
    assert lift(*rd, ("stur", "x1, [x26, #0x40]"), ret) == [
        "THR.field_0x40 = x1;", "return (x13 - 32)[x8];"]
    # An object pointer: the register itself, a copy, and a constant added and taken
    # off again. The element is at the data offset or past it, and the field below
    # stays inline, both ways round.
    for made in ((("mov", "x9, x13"),), (("add", "x9, x13, #8"), ("sub", "x9, x9, #8"))):
        assert lift(ld, *made, el, st, ret) == [
            "x13[x8] = x1;", "return x13.field_0x8;"], made
        assert lift(*made, el, ("ldur", "x4, [x16, #0x17]"), ("stur", "x1, [x13, #7]"),
                    ret) == ["x13.field_0x8 = x1;", "return x13[x8];"], made
    # ...and a base loaded from a field is one without the rows being asked.
    from jadart import expr
    made, facts = [0], expr._addr_facts

    def counted(*args, **kw):
        made[0] += 1
        return facts(*args, **kw)

    expr._addr_facts = counted
    try:
        assert lift(ld, ("ldur", "x9, [x13, #0xf]"), el, st, ret) == [
            "x13.field_0x10[x8] = x1;", "return x13.field_0x8;"]
        assert made[0] == 0, made[0]
    finally:
        expr._addr_facts = facts


if __name__ == "__main__":
    # At EOF, and it has to stay there. `globals()` is read when this block RUNS, so
    # sitting mid-file it collected only the tests defined above it: CI ran 180 of 188
    # and reported success, and the eight it dropped were the whole field-layout suite.
    # test_the_runner_block_is_the_last_thing_in_this_file keeps it here.
    passed = skipped = 0
    for name, fn in sorted(globals().items()):
        if name.startswith("test_") and callable(fn):
            try:
                fn()
            except unittest.SkipTest as exc:
                # Counted apart from the passes, and named. A skip reported as a pass is
                # how this suite came to claim 192 while running 131.
                print(f"  SKIP {name}: {exc}")
                skipped += 1
                continue
            print(f"  PASS {name}")
            passed += 1
    print(f"{passed} passed, {skipped} skipped")


# ── field layout: the offset -> name map the snapshot still carries ───────────────
